);

SET default_table_access_method = heap;

--
-- Name: spot_price_monthly_summaries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.spot_price_monthly_summaries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source text DEFAULT 'elprisetjustnu'::text NOT NULL,
    price_area text NOT NULL,
    billing_month text NOT NULL,
    average_sek_per_kwh numeric NOT NULL,
    min_sek_per_kwh numeric NOT NULL,
    max_sek_per_kwh numeric NOT NULL,
    interval_count integer DEFAULT 0 NOT NULL,
    expected_interval_count integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'incomplete'::text NOT NULL,
    locked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    period_start timestamp with time zone,
    period_end timestamp with time zone,
    covered_duration_minutes bigint,
    expected_duration_minutes bigint,
    quality_issues jsonb DEFAULT '[]'::jsonb NOT NULL,
    provider_fetched_at timestamp with time zone,
    verified_at timestamp with time zone,
    locked_by uuid,
    lock_reason text,
    source_checksum text,
    CONSTRAINT spot_price_monthly_summaries_billing_month_check CHECK ((billing_month ~ '^\d{4}-\d{2}$'::text)),
    CONSTRAINT spot_price_monthly_summaries_price_area_check CHECK ((price_area = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text]))),
    CONSTRAINT spot_price_monthly_summaries_status_check CHECK ((status = ANY (ARRAY['incomplete'::text, 'complete'::text, 'verified'::text, 'locked'::text]))),
    CONSTRAINT spot_price_monthly_verified_coverage_check CHECK (((status <> ALL (ARRAY['verified'::text, 'locked'::text])) OR ((period_start IS NOT NULL) AND (period_end IS NOT NULL) AND (period_end > period_start) AND (average_sek_per_kwh IS NOT NULL) AND (min_sek_per_kwh IS NOT NULL) AND (max_sek_per_kwh IS NOT NULL) AND (covered_duration_minutes = expected_duration_minutes) AND (
CASE
    WHEN (jsonb_typeof(quality_issues) = 'array'::text) THEN jsonb_array_length(quality_issues)
    ELSE 1
END = 0) AND (verified_at IS NOT NULL) AND (NULLIF(btrim(source_checksum), ''::text) IS NOT NULL) AND ((status <> 'locked'::text) OR ((locked_at IS NOT NULL) AND (locked_at >= verified_at))))))
);

--
-- Name: activate_customer_supply_v1(uuid, uuid, uuid, date, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_customer_supply_v1(p_company_id uuid, p_supplier_switch_request_id uuid, p_source_message_id uuid, p_actual_start_date date DEFAULT NULL::date, p_actor_user_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text) RETURNS TABLE(supplier_switch_request_id uuid, supply_period_id uuid, contract_id uuid, customer_application_id uuid, workflow_id uuid, domain_event_id uuid, notification_job_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_switch public.supplier_switch_requests%rowtype;
  v_period_id uuid;
  v_contract_id uuid;
  v_application_id uuid;
  v_workflow public.customer_application_workflows%rowtype;
  v_event_id uuid;
  v_job_id uuid;
  v_start_date date;
  v_key text;
  v_now timestamptz := now();
  v_tenant_reference text;
begin
  if p_company_id is null then
    raise exception 'supply_activation_company_required' using errcode = '22023';
  end if;
  if p_supplier_switch_request_id is null then
    raise exception 'supply_activation_switch_required' using errcode = '22023';
  end if;
  if p_source_message_id is null then
    raise exception 'supply_activation_source_message_required' using errcode = '22023';
  end if;

  select * into v_switch
  from public.supplier_switch_requests
  where id = p_supplier_switch_request_id
    and company_id = p_company_id
  for update;

  if not found then
    raise exception 'supply_activation_switch_not_found' using errcode = 'P0002';
  end if;
  if v_switch.customer_id is null then
    raise exception 'supply_activation_customer_required' using errcode = '23502';
  end if;
  if v_switch.metering_point_id is null then
    raise exception 'supply_activation_metering_point_required' using errcode = '23502';
  end if;

  v_contract_id := coalesce(v_switch.contract_id, v_switch.customer_contract_id);
  if v_contract_id is null then
    raise exception 'supply_activation_contract_required' using errcode = '23502';
  end if;
  if v_switch.status not in (
    'confirmed',
    'accepted',
    'completed'
  ) then
    raise exception 'supply_activation_switch_not_confirmed' using errcode = '23514';
  end if;

  if not exists(
    select 1
    from public.customer_contracts cc
    join public.metering_points mp
      on mp.id=v_switch.metering_point_id
     and mp.company_id=cc.company_id
     and mp.customer_id=cc.customer_id
    left join public.customer_sites cs
      on cs.id=coalesce(v_switch.customer_site_id,v_switch.site_id)
     and cs.company_id=cc.company_id
     and cs.customer_id=cc.customer_id
    where cc.id=v_contract_id
      and cc.company_id=p_company_id
      and cc.customer_id=v_switch.customer_id
      and (
        coalesce(v_switch.customer_site_id,v_switch.site_id) is null
        or cs.id is not null
      )
  ) then
    raise exception using
      errcode='23514',
      message='supply_activation_customer_contract_site_meter_mismatch';
  end if;

  v_start_date := coalesce(
    p_actual_start_date,
    v_switch.confirmed_start_date,
    v_switch.requested_start_date
  );
  if v_start_date is null then
    raise exception 'supply_activation_start_date_required' using errcode = '23502';
  end if;
  v_key := coalesce(
    nullif(btrim(p_idempotency_key), ''),
    format('activate_customer_supply_v1:%s:%s', p_company_id, p_supplier_switch_request_id)
  );

  insert into public.customer_supply_periods(
    company_id,
    customer_id,
    metering_point_id,
    contract_id,
    start_date,
    actual_start_date,
    source,
    source_process,
    source_message_id,
    source_switch_request_id,
    status,
    metadata,
    updated_at
  ) values (
    p_company_id,
    v_switch.customer_id,
    v_switch.metering_point_id,
    v_contract_id,
    v_start_date,
    v_start_date,
    'activate_customer_supply_v1',
    'supplier_switch_confirmation',
    p_source_message_id,
    v_switch.id,
    'active',
    jsonb_build_object(
      'activation_idempotency_key', v_key,
      'activated_at', v_now
    ),
    v_now
  )
  on conflict (company_id, metering_point_id, start_date)
    where status in ('active', 'confirmed_by_grid_owner')
  do update set
    customer_id = excluded.customer_id,
    contract_id = excluded.contract_id,
    actual_start_date = coalesce(public.customer_supply_periods.actual_start_date, excluded.actual_start_date),
    source_message_id = excluded.source_message_id,
    source_switch_request_id = excluded.source_switch_request_id,
    status = 'active',
    metadata = coalesce(public.customer_supply_periods.metadata, '{}'::jsonb)
      || excluded.metadata,
    updated_at = excluded.updated_at
  returning id into v_period_id;

  update public.supplier_switch_requests
  set status = 'completed',
      confirmed_start_date = coalesce(confirmed_start_date, v_start_date),
      completed_at = coalesce(completed_at, v_now),
      external_reference = coalesce(external_reference, v_key),
      inbound_z04_message_id = coalesce(inbound_z04_message_id, p_source_message_id),
      lifecycle_blocked = false,
      lifecycle_block_source = null,
      updated_at = v_now
  where id = v_switch.id
    and company_id = p_company_id;

  update public.customer_contracts
  set status = 'active',
      lifecycle_stage = 'active',
      actual_start_date = coalesce(actual_start_date, v_start_date),
      confirmed_start_date = coalesce(confirmed_start_date, v_start_date),
      billing_eligible_at = coalesce(billing_eligible_at, v_now),
      billing_eligibility_source = coalesce(
        billing_eligibility_source,
        'activate_customer_supply_v1'
      ),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'supply_period_id', v_period_id,
        'supplier_switch_request_id', v_switch.id,
        'activation_source_message_id', p_source_message_id
      ),
      updated_at = v_now
  where id = v_contract_id
    and company_id = p_company_id
    and customer_id = v_switch.customer_id
    and status in ('signed', 'active');

  if not found then
    raise exception 'supply_activation_contract_not_activatable' using errcode = '23514';
  end if;

  select workflow.* into v_workflow
  from public.customer_application_workflows workflow
  where workflow.company_id = p_company_id
    and workflow.customer_id = v_switch.customer_id
    and workflow.contract_id = v_contract_id
  order by created_at desc
  limit 1
  for update;

  if found then
    v_application_id := v_workflow.customer_application_id;

    insert into public.customer_application_workflow_events(
      company_id,
      workflow_id,
      customer_application_id,
      operation_id,
      from_state,
      to_state,
      event_code,
      actor_user_id,
      metadata,
      idempotency_key
    ) values (
      p_company_id,
      v_workflow.id,
      v_workflow.customer_application_id,
      v_workflow.operation_id,
      v_workflow.state,
      'completed',
      'workflow.supply_activated',
      p_actor_user_id,
      jsonb_build_object(
        'supply_period_id', v_period_id,
        'supplier_switch_request_id', v_switch.id,
        'actual_start_date', v_start_date
      ),
      v_key || ':workflow'
    )
    on conflict (company_id, idempotency_key) do nothing;

    update public.customer_application_workflows
    set state = 'completed',
        next_action = 'none',
        completed_at = coalesce(completed_at, v_now),
        last_transition_at = v_now,
        workflow_version = case
          when state = 'completed' then workflow_version
          else workflow_version + 1
        end,
        snapshot = coalesce(snapshot, '{}'::jsonb) || jsonb_build_object(
          'supply_period_id', v_period_id,
          'supplier_switch_request_id', v_switch.id,
          'actual_start_date', v_start_date,
          'billing_eligible_at', v_now,
          'next_action', 'none'
        ),
        updated_at = v_now
    where id = v_workflow.id;

    update public.website_customer_applications
    set status = 'active',
        actual_start_date = coalesce(actual_start_date, v_start_date),
        next_step = 'none',
        updated_at = v_now
    where id = v_application_id
      and company_id = p_company_id;
  end if;

  insert into public.domain_events(
    company_id,
    event_type,
    aggregate_type,
    aggregate_id,
    subject_customer_id,
    actor_user_id,
    source,
    idempotency_key,
    payload,
    occurred_at
  ) values (
    p_company_id,
    'supply.started',
    'customer_supply_period',
    v_period_id::text,
    v_switch.customer_id,
    p_actor_user_id,
    'activate_customer_supply_v1',
    v_key || ':domain_event',
    jsonb_build_object(
      'customer_id', v_switch.customer_id,
      'contract_id', v_contract_id,
      'customer_site_id', coalesce(v_switch.customer_site_id, v_switch.site_id),
      'metering_point_id', v_switch.metering_point_id,
      'supplier_switch_request_id', v_switch.id,
      'supply_period_id', v_period_id,
      'actual_start_date', v_start_date,
      'billing_eligible_at', v_now
    ),
    v_now
  )
  on conflict (idempotency_key) where idempotency_key is not null
  do nothing
  returning id into v_event_id;

  if v_event_id is null then
    select id into v_event_id
    from public.domain_events
    where idempotency_key = v_key || ':domain_event';
  end if;

  insert into public.customer_operation_jobs(
    company_id,
    customer_id,
    customer_site_id,
    metering_point_id,
    job_type,
    status,
    priority,
    idempotency_key,
    payload,
    request_snapshot,
    run_after,
    created_by,
    updated_at
  ) values (
    p_company_id,
    v_switch.customer_id,
    coalesce(v_switch.customer_site_id, v_switch.site_id),
    v_switch.metering_point_id,
    'dispatch_lifecycle_notification',
    'queued',
    40,
    'lifecycle_notification:' || v_key || ':customer.welcome_active',
    jsonb_build_object(
      'event_type', 'supply_period.activated',
      'source_event_id', v_event_id,
      'contract_id', v_contract_id,
      'payload', jsonb_build_object(
        'start_date', v_start_date,
        'supply_period_id', v_period_id
      )
    ),
    jsonb_build_object(
      'domain_event_id', v_event_id,
      'supplier_switch_request_id', v_switch.id
    ),
    v_now,
    p_actor_user_id,
    v_now
  )
  on conflict do nothing
  returning id into v_job_id;

  if v_job_id is null then
    select id into v_job_id
    from public.customer_operation_jobs
    where company_id = p_company_id
      and job_type = 'dispatch_lifecycle_notification'
      and idempotency_key = 'lifecycle_notification:' || v_key || ':customer.welcome_active'
    order by created_at desc
    limit 1;
  end if;

  select external_tenant_reference into v_tenant_reference
  from public.companies
  where id = p_company_id;

  insert into public.webhook_deliveries(
    company_id,
    webhook_subscription_id,
    domain_event_id,
    event_type,
    max_attempts,
    target_url,
    idempotency_key,
    payload
  )
  select
    p_company_id,
    subscription.id,
    v_event_id,
    'supply.started',
    subscription.max_attempts,
    subscription.endpoint_url,
    format('webhook:%s:%s', subscription.id, v_event_id),
    jsonb_build_object(
      'id', v_event_id,
      'type', 'supply.started',
      'event_id', v_event_id,
      'event_type', 'supply.started',
      'created_at', v_now,
      'tenant_reference', v_tenant_reference,
      'customer_id', v_switch.customer_id,
      'aggregate', jsonb_build_object(
        'type', 'customer_supply_period',
        'id', v_period_id
      ),
      'data', jsonb_build_object(
        'contract_id', v_contract_id,
        'supplier_switch_request_id', v_switch.id,
        'supply_period_id', v_period_id,
        'actual_start_date', v_start_date
      )
    )
  from public.webhook_subscriptions subscription
  where subscription.company_id = p_company_id
    and subscription.status = 'active'
    and (
      '*' = any(coalesce(subscription.event_types, '{}'::text[]))
      or 'supply.started' = any(coalesce(subscription.event_types, '{}'::text[]))
    )
  on conflict (idempotency_key) do nothing;

  return query select
    v_switch.id,
    v_period_id,
    v_contract_id,
    v_application_id,
    v_workflow.id,
    v_event_id,
    v_job_id;
end;
$$;

--
-- Name: FUNCTION activate_customer_supply_v1(p_company_id uuid, p_supplier_switch_request_id uuid, p_source_message_id uuid, p_actual_start_date date, p_actor_user_id uuid, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.activate_customer_supply_v1(p_company_id uuid, p_supplier_switch_request_id uuid, p_source_message_id uuid, p_actual_start_date date, p_actor_user_id uuid, p_idempotency_key text) IS 'Idempotently and atomically activates confirmed customer supply, contract billing eligibility, workflow/projection, one supply.started domain event and durable notification/webhook outboxes.';

--
-- Name: agent_top_accounts_for_company(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agent_top_accounts_for_company(p_company_id uuid, p_limit integer DEFAULT 20) RETURNS TABLE(account_number text, abs_amount numeric)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $_$
declare
  v_entries regclass := to_regclass('public.journal_entries');
  v_lines regclass := to_regclass('public.journal_entry_lines');
begin
  if v_entries is null
     or v_lines is null
     or not exists (
       select 1
       from pg_attribute
       where attrelid = v_entries
         and attname = 'company_id'
         and not attisdropped
     ) then
    return;
  end if;

  return query execute $sql$
    select
      line.account_number::text,
      sum(abs(
        coalesce(line.debit_amount, 0)
        - coalesce(line.credit_amount, 0)
      ))::numeric
    from public.journal_entry_lines line
    join public.journal_entries entry on entry.id = line.journal_entry_id
    where entry.company_id = $1
      and entry.status = 'posted'
    group by line.account_number
    order by 2 desc, line.account_number
    limit least(greatest(coalesce($2, 20), 1), 100)
  $sql$ using p_company_id, p_limit;
end
$_$;

--
-- Name: anonymize_user_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.anonymize_user_account(target_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
    AS $_$
begin
  if auth.uid() is distinct from target_user_id then
    raise exception using
      errcode = '42501',
      message = 'Can only anonymize your own account';
  end if;

  if exists (
    select 1
    from public.company_memberships membership
    join public.companies company on company.id = membership.company_id
    where membership.user_id = target_user_id
      and coalesce(membership.status, 'active') = 'active'
      and coalesce(
        nullif(lower(membership.membership_role), ''),
        nullif(lower(membership.role), ''),
        nullif(lower(membership.role_key), '')
      ) = 'owner'
      and company.archived_at is null
  ) then
    raise exception using
      errcode = 'P0001',
      message = 'Active companies must be transferred or archived first';
  end if;

  if to_regclass('public.user_preferences') is not null then
    execute 'delete from public.user_preferences where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.user_permission_overrides') is not null then
    execute 'delete from public.user_permission_overrides where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.user_roles') is not null then
    execute 'delete from public.user_roles where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.company_memberships') is not null then
    execute 'delete from public.company_memberships where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.agency_members') is not null then
    execute 'delete from public.agency_members where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.team_members') is not null then
    execute 'delete from public.team_members where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.bankid_enrichment') is not null then
    execute 'delete from public.bankid_enrichment where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('public.extension_data') is not null then
    execute
      'delete from public.extension_data where user_id = $1 and key = ''bankid_enrichment'''
      using target_user_id;
  end if;

  if to_regclass('public.company_invitations') is not null
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'public'
         and table_name = 'company_invitations'
         and column_name = 'invited_user_id'
     ) then
    if exists (
      select 1 from information_schema.columns
      where table_schema = 'public'
        and table_name = 'company_invitations'
        and column_name = 'invited_user_id'
        and is_nullable = 'YES'
    ) then
      execute 'update public.company_invitations set invited_user_id = null where invited_user_id = $1'
        using target_user_id;
    else
      execute 'delete from public.company_invitations where invited_user_id = $1'
        using target_user_id;
    end if;
  end if;

  -- Revoke existing authenticated sessions without deleting the auth identity.
  -- The identity itself remains so the product can retain its established
  -- account-closure semantics while authorization state is removed atomically.
  if to_regclass('auth.sessions') is not null then
    execute 'delete from auth.sessions where user_id = $1'
      using target_user_id;
  end if;
  if to_regclass('auth.refresh_tokens') is not null
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'auth'
         and table_name = 'refresh_tokens'
         and column_name = 'user_id'
     ) then
    execute 'delete from auth.refresh_tokens where user_id::text = $1::text'
      using target_user_id;
  end if;

  update public.user_profiles
  set email = null,
      full_name = null,
      phone = null,
      user_status = 'disabled',
      active_company_id = null,
      updated_at = now()
  where id = target_user_id;
end
$_$;

--
-- Name: authenticate_integration_request_v1(text, text, text, text[], text[], text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authenticate_integration_request_v1(p_key_prefix text, p_secret_hash text, p_route text, p_required_all text[] DEFAULT ARRAY[]::text[], p_required_any text[] DEFAULT ARRAY[]::text[], p_client_ip text DEFAULT NULL::text, p_origin text DEFAULT NULL::text, p_rate_limit_cost integer DEFAULT 1, p_window_seconds integer DEFAULT 60) RETURNS TABLE(auth_outcome text, error_code text, tenant_status text, client_id uuid, company_id uuid, client_name text, client_status text, key_prefix text, scopes text[], allowed_ips text[], allowed_origins text[], metadata jsonb, rate_limit_per_minute integer, expires_at timestamp with time zone, request_count integer, route_limit integer, reset_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with auth as (
    select *
    from public.authenticate_integration_request_v1_credential_core(
      p_key_prefix,p_secret_hash,p_route,p_required_all,p_required_any,
      p_client_ip,p_origin,p_rate_limit_cost,p_window_seconds
    )
  ), readiness as (
    select
      auth.*,
      exists (
        select 1
        from public.integration_api_clients client
        where client.id=auth.client_id
          and client.company_id=auth.company_id
          and client.launch_ready is true
          and jsonb_typeof(coalesce(client.launch_blockers,'[]'::jsonb))='array'
          and jsonb_array_length(coalesce(client.launch_blockers,'[]'::jsonb))=0
      ) as client_ready,
      exists (
        select 1
        from public.tenant_website_installation_receipts receipt
        where receipt.api_client_id=auth.client_id
          and receipt.company_id=auth.company_id
          and receipt.profile_key='tenant_website'
          and receipt.state='completed'
          and receipt.completed_at is not null
          and nullif(receipt.receipt_sha256,'') is not null
          and (
            receipt.id::text = nullif(auth.metadata->>'provisioning_receipt_id','')
            or (
              nullif(auth.metadata->>'provisioning_receipt_id','') is null
            )
          )
      ) as receipt_ready,
      exists (
        select 1
        from public.company_capabilities capability
        where capability.company_id=auth.company_id
          and capability.capability_code='api_sales'
          and capability.enabled is true
          and capability.readiness_status='ready'
      ) as capability_ready,
      exists (
        select 1
        from public.tenant_website_installation_receipts receipt
        where p_route like 'provisioning-smoke:%'
          and receipt.id::text = nullif(auth.metadata->>'provisioning_receipt_id','')
          and receipt.api_client_id=auth.client_id
          and receipt.company_id=auth.company_id
          and receipt.profile_key='tenant_website'
          and receipt.state in (
            'client_ready','credential_created','preflight_passed','feed_verified','failed'
          )
      ) as provisioning_smoke_ready
    from auth
  )
  select
    case
      when readiness.auth_outcome<>'allowed' then readiness.auth_outcome
      when p_route like 'provisioning-smoke:%' and readiness.provisioning_smoke_ready then 'allowed'
      when p_route like 'provisioning-smoke:%' then 'denied'
      when readiness.client_ready and readiness.receipt_ready and readiness.capability_ready then 'allowed'
      else 'denied'
    end,
    case
      when readiness.auth_outcome<>'allowed' then readiness.error_code
      when p_route like 'provisioning-smoke:%' and not readiness.provisioning_smoke_ready then 'provisioning_smoke_receipt_invalid'
      when p_route like 'provisioning-smoke:%' then null
      when not readiness.client_ready then 'api_client_not_launch_ready'
      when not readiness.receipt_ready then 'integration_receipt_not_verified'
      when not readiness.capability_ready then 'integration_capability_not_ready'
      else null
    end,
    readiness.tenant_status,
    readiness.client_id,
    readiness.company_id,
    readiness.client_name,
    readiness.client_status,
    readiness.key_prefix,
    readiness.scopes,
    readiness.allowed_ips,
    readiness.allowed_origins,
    readiness.metadata,
    readiness.rate_limit_per_minute,
    readiness.expires_at,
    readiness.request_count,
    readiness.route_limit,
    readiness.reset_at
  from readiness
$$;

--
-- Name: FUNCTION authenticate_integration_request_v1(p_key_prefix text, p_secret_hash text, p_route text, p_required_all text[], p_required_any text[], p_client_ip text, p_origin text, p_rate_limit_cost integer, p_window_seconds integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.authenticate_integration_request_v1(p_key_prefix text, p_secret_hash text, p_route text, p_required_all text[], p_required_any text[], p_client_ip text, p_origin text, p_rate_limit_cost integer, p_window_seconds integer) IS 'Atomic integration auth. Normal traffic requires launch readiness, the metadata-linked completed receipt when present (else a legacy completed receipt) and api_sales; bounded provisioning-smoke routes require the exact in-progress receipt.';

--
-- Name: authenticate_integration_request_v1_credential_core(text, text, text, text[], text[], text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authenticate_integration_request_v1_credential_core(p_key_prefix text, p_secret_hash text, p_route text, p_required_all text[] DEFAULT ARRAY[]::text[], p_required_any text[] DEFAULT ARRAY[]::text[], p_client_ip text DEFAULT NULL::text, p_origin text DEFAULT NULL::text, p_rate_limit_cost integer DEFAULT 1, p_window_seconds integer DEFAULT 60) RETURNS TABLE(auth_outcome text, error_code text, tenant_status text, client_id uuid, company_id uuid, client_name text, client_status text, key_prefix text, scopes text[], allowed_ips text[], allowed_origins text[], metadata jsonb, rate_limit_per_minute integer, expires_at timestamp with time zone, request_count integer, route_limit integer, reset_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  select
    auth.auth_outcome,
    auth.error_code,
    auth.tenant_status,
    auth.client_id,
    auth.company_id,
    auth.client_name,
    auth.client_status,
    auth.key_prefix,
    auth.scopes,
    auth.allowed_ips,
    auth.allowed_origins,
    auth.metadata,
    auth.rate_limit_per_minute,
    auth.expires_at,
    auth.request_count,
    auth.route_limit,
    auth.reset_at
  from private.authenticate_integration_request_v1_secret_internal(
    p_key_prefix,p_secret_hash,p_route,p_required_all,p_required_any,
    p_client_ip,p_origin,p_rate_limit_cost,p_window_seconds
  ) auth
$$;

--
-- Name: authenticate_provisioning_smoke_request_v1(text, text, uuid, text, text[], text[], text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authenticate_provisioning_smoke_request_v1(p_key_prefix text, p_secret_hash text, p_receipt_id uuid, p_route text, p_required_all text[] DEFAULT ARRAY[]::text[], p_required_any text[] DEFAULT ARRAY[]::text[], p_client_ip text DEFAULT NULL::text, p_origin text DEFAULT NULL::text, p_rate_limit_cost integer DEFAULT 1, p_window_seconds integer DEFAULT 60) RETURNS TABLE(auth_outcome text, error_code text, tenant_status text, client_id uuid, company_id uuid, client_name text, client_status text, key_prefix text, scopes text[], allowed_ips text[], allowed_origins text[], metadata jsonb, rate_limit_per_minute integer, expires_at timestamp with time zone, request_count integer, route_limit integer, reset_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with auth as (
    select *
    from public.authenticate_integration_request_v1_credential_core(
      p_key_prefix,p_secret_hash,p_route,p_required_all,p_required_any,
      p_client_ip,p_origin,p_rate_limit_cost,p_window_seconds
    )
  ), checked as (
    select
      auth.*,
      p_route like 'provisioning-smoke:%'
      and exists (
        select 1 from public.tenant_website_installation_receipts receipt
        where receipt.id=p_receipt_id
          and receipt.api_client_id=auth.client_id
          and receipt.company_id=auth.company_id
          and receipt.state in (
            'client_ready','credential_created','preflight_passed',
            'feed_verified','failed'
          )
      ) as smoke_allowed
    from auth
  )
  select
    case
      when checked.auth_outcome<>'allowed' then checked.auth_outcome
      when checked.smoke_allowed then 'allowed'
      else 'denied'
    end,
    case
      when checked.auth_outcome<>'allowed' then checked.error_code
      when not checked.smoke_allowed then 'provisioning_smoke_receipt_invalid'
      else null
    end,
    checked.tenant_status,
    checked.client_id,
    checked.company_id,
    checked.client_name,
    checked.client_status,
    checked.key_prefix,
    checked.scopes,
    checked.allowed_ips,
    checked.allowed_origins,
    checked.metadata,
    checked.rate_limit_per_minute,
    checked.expires_at,
    checked.request_count,
    checked.route_limit,
    checked.reset_at
  from checked
$$;

--
-- Name: backfill_companies(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backfill_companies() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_run_id uuid;
  v_before integer := 0;
  v_after integer := 0;
  v_company_id uuid;
  v_inserted integer := 0;
begin
  v_run_id := public.gridex_db1_start_backfill_run('db1_backfill_companies', 'companies');
  select count(*) into v_before from public.companies;
  v_company_id := public.gridex_db1_default_company_id();
  select count(*) into v_after from public.companies;
  v_inserted := greatest(v_after - v_before, 0);

  return public.gridex_db1_finish_backfill_run(
    v_run_id,
    'completed',
    jsonb_build_object('default_company_id', v_company_id, 'safe_default_only', true),
    v_after,
    v_inserted,
    0,
    0,
    0
  );
end;
$$;

--
-- Name: backfill_poa_scopes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backfill_poa_scopes() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_run_id uuid;
  v_company_id uuid;
  r record;
  v_seen integer := 0;
  v_inserted integer := 0;
  v_updated integer := 0;
  v_skipped integer := 0;
  v_failed integer := 0;
  v_row_count integer := 0;
begin
  v_run_id := public.gridex_db1_start_backfill_run('db1_backfill_poa_scopes', 'powers_of_attorney');
  v_company_id := public.gridex_db1_default_company_id();

  if v_company_id is null then
    return public.gridex_db1_finish_backfill_run(v_run_id, 'skipped', jsonb_build_object('reason', 'ambiguous_company'), 0, 0, 0, 1, 0);
  end if;

  if to_regclass('public.powers_of_attorney') is null or to_regclass('public.power_of_attorney_scopes') is null then
    return public.gridex_db1_finish_backfill_run(v_run_id, 'skipped', jsonb_build_object('reason', 'poa_tables_missing'), 0, 0, 0, 1, 0);
  end if;

  update public.powers_of_attorney
  set company_id = v_company_id,
      updated_at = now()
  where company_id is null;
  get diagnostics v_row_count = row_count;
  v_updated := v_updated + v_row_count;

  for r in select * from public.powers_of_attorney loop
    v_seen := v_seen + 1;
    begin
      if exists(select 1 from public.power_of_attorney_scopes s where s.power_of_attorney_id = r.id) then
        v_skipped := v_skipped + 1;
        continue;
      end if;

      insert into public.power_of_attorney_scopes (
        company_id, power_of_attorney_id, customer_id, site_id, metering_point_id,
        scope_type, status, is_active, valid_from, valid_to, metadata, created_at, updated_at
      ) values (
        coalesce(r.company_id, v_company_id), r.id, r.customer_id, r.site_id, r.metering_point_id,
        coalesce(r.scope, 'supplier_switch'), 'active', true, r.valid_from, r.valid_to,
        jsonb_build_object('source_table', 'powers_of_attorney', 'source_id', r.id, 'backfill', 'db1_backfill_poa_scopes'),
        now(), now()
      );
      v_inserted := v_inserted + 1;
    exception when others then
      v_failed := v_failed + 1;
      insert into public.backfill_run_items(backfill_run_id, source_table, source_id, target_table, status, message, details)
      values (v_run_id, 'powers_of_attorney', coalesce(r.id::text, '<null>'), 'power_of_attorney_scopes', 'failed', SQLERRM, jsonb_build_object('sqlstate', SQLSTATE));
    end;
  end loop;

  return public.gridex_db1_finish_backfill_run(v_run_id, 'completed', jsonb_build_object('source_table', 'powers_of_attorney'), v_seen, v_inserted, v_updated, v_skipped, v_failed);
end;
$$;

--
-- Name: canonical_accept_tenant_invitation(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_accept_tenant_invitation(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_actor_user_id uuid := nullif(p_command->>'actor_user_id','')::uuid;
  v_user_id uuid := nullif(p_command->>'user_id','')::uuid;
  v_invitation_id uuid := nullif(p_command->>'invitation_id','')::uuid;
  v_idempotency_key text := nullif(btrim(p_command->>'idempotency_key'),'');
  v_invitation public.company_invitations%rowtype;
  v_company_status text;
  v_auth_email text;
  v_profile_active boolean;
  v_role_key text;
  v_membership_role text;
  v_role_id uuid;
  v_existing_user_role_id uuid;
  v_request jsonb := p_command - 'actor_user_id';
  v_hash text;
  v_existing public.canonical_command_results%rowtype;
  v_result jsonb;
  v_event_id uuid;
begin
  if v_actor_user_id is null or v_user_id is null or v_actor_user_id<>v_user_id
     or v_invitation_id is null or v_idempotency_key is null then
    raise exception using errcode='22023', message='verified_user_invitation_and_idempotency_required';
  end if;

  select * into v_invitation
  from public.company_invitations
  where id=v_invitation_id
  for update;
  if not found then
    raise exception using errcode='P0002', message='tenant_invitation_not_found';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('tenant-invitation:'||v_invitation.company_id::text||':'||v_invitation_id::text,0));
  v_hash := public.canonical_json_sha256(v_request);

  select * into v_existing
  from public.canonical_command_results
  where company_id=v_invitation.company_id
    and command_type='tenant.invitation.accept'
    and idempotency_key=v_idempotency_key;
  if found then
    if v_existing.request_hash is distinct from v_hash then
      raise exception using errcode='23505', message='IDEMPOTENCY_KEY_REUSE_MISMATCH';
    end if;
    return v_existing.result_payload;
  end if;

  if coalesce(v_invitation.status,'')='accepted'
     and v_invitation.invited_user_id=v_user_id then
    v_result:=jsonb_build_object(
      'changed',false,'already_accepted',true,'company_id',v_invitation.company_id,
      'user_id',v_user_id,'invitation_id',v_invitation_id
    );
    insert into public.canonical_command_results(
      company_id,command_type,idempotency_key,request_hash,request_payload,result_payload,actor_user_id
    ) values(
      v_invitation.company_id,'tenant.invitation.accept',v_idempotency_key,v_hash,v_request,v_result,v_actor_user_id
    );
    return v_result;
  end if;

  if coalesce(v_invitation.status,'')<>'pending' then
    raise exception using errcode='23514', message='tenant_invitation_not_pending';
  end if;
  if v_invitation.expires_at is not null and v_invitation.expires_at<=now() then
    raise exception using errcode='23514', message='tenant_invitation_expired';
  end if;
  if v_invitation.invited_user_id is not null and v_invitation.invited_user_id<>v_user_id then
    raise exception using errcode='42501', message='tenant_invitation_user_mismatch';
  end if;

  select lower(u.email),
         exists(select 1 from public.user_profiles up where up.id=u.id and up.user_status='active')
    into v_auth_email,v_profile_active
  from auth.users u
  where u.id=v_user_id and u.deleted_at is null
    and (u.banned_until is null or u.banned_until<=now());
  if v_auth_email is null or not coalesce(v_profile_active,false) then
    raise exception using errcode='42501', message='target_auth_user_missing_or_inactive';
  end if;
  if v_auth_email<>lower(coalesce(v_invitation.email,v_invitation.invited_email,'')) then
    raise exception using errcode='42501', message='tenant_invitation_email_mismatch';
  end if;

  select status into v_company_status
  from public.companies where id=v_invitation.company_id for update;
  if v_company_status not in ('onboarding','active') then
    raise exception using errcode='23514', message='tenant_state_blocks_invitation_acceptance';
  end if;

  v_role_key:=lower(coalesce(nullif(v_invitation.role_key,''),'customer_service_agent'));
  select m.membership_role into v_membership_role
  from public.canonical_tenant_access_role_mapping m
  where m.role_key=v_role_key and m.is_assignable;
  if v_membership_role is null then
    raise exception using errcode='22023', message='canonical_tenant_role_not_assignable';
  end if;
  if nullif(lower(v_invitation.membership_role),'') is not null
     and lower(v_invitation.membership_role)<>v_membership_role then
    raise exception using errcode='23514', message='invitation_membership_role_role_key_mismatch';
  end if;

  select r.id into v_role_id
  from public.roles r
  where lower(coalesce(r.key,r.name))=v_role_key
  order by r.created_at asc,r.id asc
  limit 1;
  if v_role_id is null then
    raise exception using errcode='22023', message='canonical_tenant_role_definition_missing';
  end if;

  insert into public.company_memberships(
    company_id,user_id,membership_role,role_key,status,is_active,invited_email,
    invited_by,invited_at,accepted_at,disabled_at,removed_at,status_reason,metadata
  ) values(
    v_invitation.company_id,v_user_id,v_membership_role,v_role_key,'active',true,v_auth_email,
    v_invitation.invited_by,coalesce(v_invitation.created_at,now()),now(),null,null,null,
    jsonb_build_object('canonical_invitation_id',v_invitation_id,'canonical_access_command',v_idempotency_key)
  ) on conflict(company_id,user_id) do update set
    membership_role=excluded.membership_role,role_key=excluded.role_key,status='active',is_active=true,
    invited_email=excluded.invited_email,accepted_at=coalesce(public.company_memberships.accepted_at,now()),
    disabled_at=null,removed_at=null,status_reason=null,
    metadata=coalesce(public.company_memberships.metadata,'{}'::jsonb)||excluded.metadata,
    updated_at=now();

  update public.user_roles
  set status='disabled',is_active=false,updated_at=now()
  where company_id=v_invitation.company_id and user_id=v_user_id and coalesce(is_active,true);

  select ur.id into v_existing_user_role_id
  from public.user_roles ur
  where ur.company_id=v_invitation.company_id and ur.user_id=v_user_id and ur.role_id=v_role_id
  order by ur.created_at asc,ur.id asc
  limit 1
  for update;
  if v_existing_user_role_id is null then
    insert into public.user_roles(user_id,company_id,role,role_id,status,is_active,created_at,updated_at)
    values(v_user_id,v_invitation.company_id,v_role_key,v_role_id,'active',true,now(),now());
  else
    update public.user_roles
    set role=v_role_key,role_id=v_role_id,status='active',is_active=true,updated_at=now()
    where id=v_existing_user_role_id;
  end if;

  update public.company_invitations
  set status='accepted',accepted_at=now(),invited_user_id=v_user_id,
      membership_role=v_membership_role,role_key=v_role_key,
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
        'access_source','canonical_verified_auth_invitation','accepted_by_verified_user',true
      ),updated_at=now()
  where id=v_invitation_id;

  insert into public.canonical_audit_events(
    company_id,event_type,aggregate_type,aggregate_id,actor_user_id,reason,idempotency_key,before_state,after_state
  ) values(
    v_invitation.company_id,'TENANT_INVITATION_ACCEPTED','tenant_user',v_user_id,v_actor_user_id,
    'Verified tenant invitation accepted',v_idempotency_key,
    jsonb_build_object('invitation_id',v_invitation_id,'status',v_invitation.status),
    jsonb_build_object('membership_role',v_membership_role,'role_key',v_role_key,'status','active')
  );
  insert into public.canonical_domain_events(
    company_id,event_type,aggregate_type,aggregate_id,idempotency_key,payload,created_by
  ) values(
    v_invitation.company_id,'TENANT_INVITATION_ACCEPTED','tenant_user',v_user_id,v_idempotency_key,
    jsonb_build_object('invitation_id',v_invitation_id,'membership_role',v_membership_role,'role_key',v_role_key),v_actor_user_id
  ) returning id into v_event_id;
  insert into public.canonical_event_outbox(company_id,domain_event_id,topic,idempotency_key,payload)
  values(
    v_invitation.company_id,v_event_id,'tenant.invitation.accepted',v_idempotency_key,
    jsonb_build_object('company_id',v_invitation.company_id,'user_id',v_user_id,'invitation_id',v_invitation_id)
  );

  v_result:=jsonb_build_object(
    'changed',true,'already_accepted',false,'company_id',v_invitation.company_id,
    'user_id',v_user_id,'invitation_id',v_invitation_id,
    'membership_role',v_membership_role,'role_key',v_role_key
  );
  insert into public.canonical_command_results(
    company_id,command_type,idempotency_key,request_hash,request_payload,result_payload,actor_user_id
  ) values(
    v_invitation.company_id,'tenant.invitation.accept',v_idempotency_key,v_hash,v_request,v_result,v_actor_user_id
  );
  return v_result;
end
$$;

--
-- Name: canonical_actor_is_authorized(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_actor_is_authorized(p_company_id uuid, p_actor_user_id uuid, p_permission_key text, p_platform_only boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  select public.canonical_actor_is_platform_admin(p_actor_user_id)
    or (
      not p_platform_only
      and p_company_id is not null
      and exists (
        select 1
        from auth.users u
        join public.user_profiles up on up.id = u.id
        join public.company_memberships cm
          on cm.user_id = u.id
         and cm.company_id = p_company_id
         and cm.status = 'active'
         and coalesce(cm.is_active, true)
        join public.user_roles ur
          on ur.user_id = u.id
         and ur.company_id = p_company_id
         and coalesce(ur.status, 'active') = 'active'
         and coalesce(ur.is_active, true)
        join public.roles r on r.id = ur.role_id and coalesce(r.is_active, true)
        join public.role_permissions rp on rp.role_id = r.id
        join public.permissions p on p.id = rp.permission_id
        where u.id = p_actor_user_id
          and u.deleted_at is null
          and (u.banned_until is null or u.banned_until <= now())
          and u.email_confirmed_at is not null
          and up.user_status = 'active'
          and p.key = p_permission_key
      )
    )
$$;

--
-- Name: canonical_actor_is_platform_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_actor_is_platform_admin(p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  select p_user_id is not null
    and exists (
      select 1
      from auth.users u
      join public.user_profiles up on up.id=u.id
      where u.id=p_user_id
        and u.deleted_at is null
        and (u.banned_until is null or u.banned_until <= now())
        and up.user_status='active'
    )
    and (
      exists (
        select 1
        from public.admin_users au
        where au.user_id=p_user_id
          and coalesce(au.is_active,true)
          and public.gridex_normalize_platform_role(au.role)
            in ('super_admin','platform_admin')
      )
      or exists (
        select 1
        from public.user_roles ur
        left join public.roles r on r.id=ur.role_id
        where ur.user_id=p_user_id
          and ur.company_id is null
          and coalesce(ur.is_active,true)
          and coalesce(ur.status,'active')='active'
          and public.gridex_normalize_platform_role(coalesce(ur.role,r.key,r.name))
            in ('super_admin','platform_admin')
      )
    )
$$;

--
-- Name: canonical_approve_actor_test_attestation(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_approve_actor_test_attestation(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid:=(p_command->>'company_id')::uuid;
  v_attestation_id uuid:=(p_command->>'attestation_id')::uuid;
  v_actor_user_id uuid:=nullif(p_command->>'actor_user_id','')::uuid;
  v_decision_reason text:=nullif(btrim(p_command->>'decision_reason'),'');
  v_idempotency_key text:=p_command->>'idempotency_key';
  v_attestation public.actor_test_manual_attestations%rowtype;
  v_run public.ediel_test_runs%rowtype;
  v_snapshot public.ediel_configuration_snapshots%rowtype;
  v_attempt_id uuid;
  v_event_id uuid;
  v_digest text;
  v_existing jsonb;
  v_result jsonb;
  v_actor_role text;
begin
  if v_company_id is null or v_attestation_id is null or v_actor_user_id is null
     or v_decision_reason is null or nullif(btrim(v_idempotency_key),'') is null then
    raise exception 'manual_attestation_approval_fields_required';
  end if;

  if not public.gridex_actor_has_company_permission(
    v_actor_user_id,v_company_id,'ediel_testing.attest'
  ) then
    raise exception using errcode='42501',message='ediel_testing_attest_permission_denied';
  end if;

  select result_payload into v_existing from public.canonical_command_results
  where company_id=v_company_id and command_type='ediel.test.attestation.approve' and idempotency_key=v_idempotency_key;
  if found then return v_existing; end if;

  select * into v_attestation from public.actor_test_manual_attestations
  where id=v_attestation_id and company_id=v_company_id for update;
  if not found then raise exception 'tenant_scoped_attestation_not_found'; end if;
  if v_attestation.status<>'requested' then raise exception 'attestation_is_not_pending'; end if;
  if v_attestation.requested_by=v_actor_user_id then raise exception 'attestation_requires_separate_approver'; end if;

  select * into v_run from public.ediel_test_runs
  where id=v_attestation.test_run_id and company_id=v_company_id for update;
  if not found then raise exception 'tenant_scoped_test_run_not_found'; end if;
  if v_run.environment_type='production'::public.ediel_environment_type
     or lower(coalesce(v_run.environment,''))<>'test' then
    raise exception 'manual_attestation_requires_consistent_test_environment';
  end if;
  if v_run.configuration_snapshot_id is null or coalesce(v_run.is_stale,false) then
    raise exception 'stale_test_run_cannot_be_manually_attested';
  end if;
  select * into v_snapshot from public.ediel_configuration_snapshots
  where id=v_run.configuration_snapshot_id and company_id=v_company_id;
  if not found then raise exception 'test_run_snapshot_not_found_for_tenant'; end if;

  v_actor_role:=case lower(coalesce(nullif(v_run.actor_role,''),v_run.role_code))
    when 'supplier' then 'supplier'
    when 'esco' then 'energy_service_company'
    when 'energy_service_company' then 'energy_service_company'
    else null
  end;
  if v_actor_role is null
     or nullif(btrim(v_run.test_suite),'') is null
     or nullif(btrim(v_run.setup_package),'') is null
     or nullif(btrim(v_run.message_family),'') is null
     or nullif(btrim(v_run.rulebook_version),'') is null then
    raise exception 'manual_attestation_canonical_identity_incomplete';
  end if;

  v_digest:=encode(extensions.digest(convert_to(v_attestation.reason||'|'||v_attestation.evidence_reference||'|'||v_decision_reason,'utf8'),'sha256'::text),'hex');
  insert into public.actor_test_attempts(
    company_id,test_run_id,test_case_code,environment_type,actor_role,role_code,
    test_suite,setup_package,message_family,message_variant,status,machine_verified,
    configuration_snapshot_id,configuration_hash,rulebook_version,engine_version,
    started_at,completed_at,evidence_digest,failure_details,created_by
  ) values (
    v_company_id,v_run.id,v_attestation.test_case_code,v_run.environment_type,v_actor_role,v_run.role_code,
    v_run.test_suite,v_run.setup_package,upper(v_run.message_family),v_run.message_variant,'manual_verified',false,
    v_snapshot.id,v_snapshot.configuration_hash,coalesce(v_run.rulebook_version,'unknown'),v_run.engine_version,
    coalesce(v_run.started_at,v_run.created_at),now(),v_digest,
    jsonb_build_object('reason',v_attestation.reason,'evidence_reference',v_attestation.evidence_reference,'decision_reason',v_decision_reason),
    v_actor_user_id
  ) returning id into v_attempt_id;

  update public.actor_test_manual_attestations
  set attempt_id=v_attempt_id,approved_by=v_actor_user_id,approved_at=now(),status='approved',decision_reason=v_decision_reason
  where id=v_attestation_id and company_id=v_company_id;

  insert into public.actor_test_results(
    company_id,test_key,status,latest_run_at,passed_at,failure_reason,ediel_test_run_id,evidence,
    configuration_snapshot_id,configuration_hash,is_stale,stale_reason,created_by,updated_by,created_at,updated_at
  ) values (
    v_company_id,v_attestation.test_case_code,'manual_verified',now(),null,null,v_run.id,
    jsonb_build_object('manual_attestation_id',v_attestation_id,'attempt_id',v_attempt_id,'reason',v_attestation.reason,
      'evidence_reference',v_attestation.evidence_reference,'approved_by',v_actor_user_id,'decision_reason',v_decision_reason),
    v_snapshot.id,v_snapshot.configuration_hash,false,null,v_actor_user_id,v_actor_user_id,now(),now()
  ) on conflict(company_id,test_key) do update set
    status='manual_verified',latest_run_at=excluded.latest_run_at,passed_at=null,failure_reason=null,
    ediel_test_run_id=excluded.ediel_test_run_id,evidence=excluded.evidence,
    configuration_snapshot_id=excluded.configuration_snapshot_id,configuration_hash=excluded.configuration_hash,
    is_stale=false,stale_reason=null,updated_by=excluded.updated_by,updated_at=excluded.updated_at;

  insert into public.canonical_audit_events(
    company_id,event_type,aggregate_type,aggregate_id,actor_user_id,reason,idempotency_key,after_state
  ) values (
    v_company_id,'EDIEL_TEST_MANUALLY_ATTESTED','actor_test_attempt',v_attempt_id,
    v_actor_user_id,v_decision_reason,v_idempotency_key,
    jsonb_build_object('status','manual_verified','test_run_id',v_run.id,'attestation_id',v_attestation_id,
      'configuration_snapshot_id',v_snapshot.id)
  );
  insert into public.canonical_domain_events(
    company_id,event_type,aggregate_type,aggregate_id,idempotency_key,payload,created_by
  ) values (
    v_company_id,'EDIEL_TEST_MANUALLY_ATTESTED','actor_test_attempt',v_attempt_id,v_idempotency_key,
    jsonb_build_object('test_run_id',v_run.id,'test_case_code',v_attestation.test_case_code,
      'attestation_id',v_attestation_id,'configuration_snapshot_id',v_snapshot.id),v_actor_user_id
  ) returning id into v_event_id;
  insert into public.canonical_event_outbox(company_id,domain_event_id,topic,idempotency_key,payload)
  values(v_company_id,v_event_id,'ediel.test.manually_attested',v_idempotency_key,
    jsonb_build_object('attempt_id',v_attempt_id,'attestation_id',v_attestation_id,'test_run_id',v_run.id));

  v_result:=jsonb_build_object('attempt_id',v_attempt_id,'attestation_id',v_attestation_id,
    'status','manual_verified','configuration_snapshot_id',v_snapshot.id);
  insert into public.canonical_command_results(company_id,command_type,idempotency_key,request_payload,result_payload,actor_user_id)
  values(v_company_id,'ediel.test.attestation.approve',v_idempotency_key,p_command,v_result,v_actor_user_id);
  return v_result;
end;
$$;

--
-- Name: canonical_approve_first_live_send(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_approve_first_live_send(p_company_id uuid, p_readiness_check_id uuid, p_actor_user_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_request jsonb := jsonb_build_object('readiness_check_id', p_readiness_check_id);
  v_hash text;
  v_existing public.canonical_command_results%rowtype;
  v_result jsonb;
begin
  if not public.canonical_actor_is_authorized(p_company_id, p_actor_user_id, 'ediel.send', false) then
    raise exception 'actor_not_authorized_for_first_live_send';
  end if;
  if nullif(btrim(p_idempotency_key), '') is null then raise exception 'idempotency_key_required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text || ':ediel.production.first_live_send.approve', 0));
  v_hash := public.canonical_json_sha256(v_request);
  select * into v_existing from public.canonical_command_results
  where company_id = p_company_id and command_type = 'ediel.production.first_live_send.approve'
    and idempotency_key = p_idempotency_key;
  if found then
    if v_existing.actor_user_id is distinct from p_actor_user_id then raise exception 'idempotency_actor_mismatch'; end if;
    if v_existing.request_hash <> v_hash then raise exception 'idempotency_key_payload_mismatch'; end if;
    return v_existing.result_payload;
  end if;
  if exists (
    select 1 from public.ediel_production_state
    where company_id = p_company_id and first_live_send_approved_at is not null
  ) then raise exception 'first_live_send_already_approved'; end if;
  v_result := public.canonical_approve_first_live_send_v1_unchecked(
    p_company_id, p_readiness_check_id, p_actor_user_id, p_idempotency_key
  );
  update public.canonical_command_results set request_payload = v_request
  where company_id = p_company_id and command_type = 'ediel.production.first_live_send.approve'
    and idempotency_key = p_idempotency_key;
  return v_result;
end;
$$;

--
-- Name: canonical_approve_first_live_send_v1_unchecked(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_approve_first_live_send_v1_unchecked(p_company_id uuid, p_readiness_check_id uuid, p_actor_user_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company public.companies%rowtype;
  v_state public.ediel_production_state%rowtype;
  v_readiness public.ediel_production_readiness_checks%rowtype;
  v_existing jsonb;
  v_event_id uuid;
  v_result jsonb;
begin
  select result_payload into v_existing from public.canonical_command_results
  where company_id=p_company_id and command_type='ediel.production.first_live_send.approve' and idempotency_key=p_idempotency_key;
  if found then return v_existing; end if;

  select * into v_company from public.companies where id=p_company_id for update;
  select * into v_state from public.ediel_production_state where company_id=p_company_id for update;
  if v_company.status<>'active' then raise exception 'tenant_must_be_active'; end if;
  if v_state.state<>'live' then raise exception 'ediel_production_must_be_live'; end if;
  select * into v_readiness from public.ediel_production_readiness_checks
  where id=p_readiness_check_id and company_id=p_company_id;
  if not found or v_readiness.status not in ('ready','warning','live')
     or jsonb_array_length(coalesce(v_readiness.blocking_issues,'[]'::jsonb))>0
     or coalesce(v_readiness.is_stale,false)
     or v_readiness.configuration_snapshot_id is distinct from v_state.configuration_snapshot_id then
    raise exception 'valid_current_readiness_check_required';
  end if;

  update public.ediel_production_state
  set first_live_send_approved_by=p_actor_user_id,
      first_live_send_approved_at=coalesce(first_live_send_approved_at,now()),
      updated_at=now()
  where company_id=p_company_id;
  update public.companies
  set ediel_first_live_send_approved_by=p_actor_user_id,
      ediel_first_live_send_approved_at=coalesce(ediel_first_live_send_approved_at,now()),
      updated_at=now()
  where id=p_company_id;

  insert into public.canonical_domain_events(company_id,event_type,aggregate_type,aggregate_id,aggregate_version,idempotency_key,payload,created_by)
  values(p_company_id,'EDIEL_FIRST_LIVE_SEND_APPROVED','ediel_production',p_company_id,v_state.state_version,
    p_idempotency_key,jsonb_build_object('readiness_check_id',p_readiness_check_id),p_actor_user_id)
  returning id into v_event_id;
  insert into public.canonical_event_outbox(company_id,domain_event_id,topic,idempotency_key,payload)
  values(p_company_id,v_event_id,'ediel.production.first_live_send.approved',p_idempotency_key,
    jsonb_build_object('company_id',p_company_id,'readiness_check_id',p_readiness_check_id));
  insert into public.canonical_audit_events(company_id,event_type,aggregate_type,aggregate_id,state_version,actor_user_id,reason,idempotency_key,after_state)
  values(p_company_id,'EDIEL_FIRST_LIVE_SEND_APPROVED','ediel_production',p_company_id,v_state.state_version,
    p_actor_user_id,'Första live-sändning godkänd.',p_idempotency_key,
    jsonb_build_object('approved',true,'readiness_check_id',p_readiness_check_id));

  v_result:=jsonb_build_object('changed',true,'company_id',p_company_id,'approved',true,'domain_event_id',v_event_id);
  insert into public.canonical_command_results(company_id,command_type,idempotency_key,request_payload,result_payload,actor_user_id)
  values(p_company_id,'ediel.production.first_live_send.approve',p_idempotency_key,
    jsonb_build_object('readiness_check_id',p_readiness_check_id),v_result,p_actor_user_id);
  return v_result;
end;
$$;

--
-- Name: canonical_authenticated_tenant_context(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_authenticated_tenant_context(p_selected_company_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
begin
  -- The scoped implementation filters roles and permissions by
  -- user_role.company_id = selected company. Permissions never span companies.
  return public.canonical_authenticated_tenant_context_v1_scoped(p_selected_company_id);
end
$$;

--
-- Name: FUNCTION canonical_authenticated_tenant_context(p_selected_company_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.canonical_authenticated_tenant_context(p_selected_company_id uuid) IS 'F-1: delegates to the company-scoped resolver. Permissions are never unioned across companies.';

--
-- Name: canonical_authenticated_tenant_context_v1_scoped(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_authenticated_tenant_context_v1_scoped(p_selected_company_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_user_email text;
  v_platform boolean := false;
  v_profile_active boolean := false;
  v_selected_company_id uuid;
  v_memberships jsonb := '[]'::jsonb;
  v_roles jsonb := '[]'::jsonb;
  v_permissions jsonb := '[]'::jsonb;
  v_company jsonb;
  v_policy jsonb := '{}'::jsonb;
begin
  if v_user_id is null then
    return jsonb_build_object('authorized',false,'reason_code','authentication_required');
  end if;

  select exists(
    select 1 from auth.users u
    join public.user_profiles profile on profile.id=u.id
    where u.id=v_user_id and u.deleted_at is null
      and (u.banned_until is null or u.banned_until <= now())
      and u.email_confirmed_at is not null
      and profile.user_status='active'
  ) into v_profile_active;
  if not v_profile_active then
    return jsonb_build_object('authorized',false,'reason_code','identity_not_active');
  end if;

  v_platform := public.canonical_actor_is_platform_admin(v_user_id);
  select u.email into v_user_email from auth.users u where u.id=v_user_id;

  if v_platform then
    select coalesce(jsonb_agg(jsonb_build_object(
      'membership_id',null,
      'company_id',company.id,
      'company_name',company.name,
      'company_slug',company.slug,
      'org_number',company.org_number,
      'membership_role','platform_admin',
      'role_key','platform_admin',
      'status',company.status
    ) order by company.name),'[]'::jsonb)
    into v_memberships
    from public.companies company
    where company.status <> 'deleted_test_only';

    if p_selected_company_id is not null and exists(
      select 1 from public.companies where id=p_selected_company_id and status <> 'deleted_test_only'
    ) then
      v_selected_company_id := p_selected_company_id;
    end if;
  else
    select coalesce(jsonb_agg(jsonb_build_object(
      'membership_id',membership.id,
      'company_id',company.id,
      'company_name',company.name,
      'company_slug',company.slug,
      'org_number',company.org_number,
      'membership_role',membership.membership_role,
      'role_key',role.key,
      'status',company.status
    ) order by (membership.membership_role='owner') desc, company.name),'[]'::jsonb)
    into v_memberships
    from public.company_memberships membership
    join public.companies company on company.id=membership.company_id
    join public.user_roles user_role
      on user_role.user_id=membership.user_id
     and user_role.company_id=membership.company_id
     and coalesce(user_role.status,'active')='active'
     and coalesce(user_role.is_active,true)
    join public.roles role on role.id=user_role.role_id and coalesce(role.is_active,true)
    where membership.user_id=v_user_id
      and membership.status='active'
      and coalesce(membership.is_active,true);

    select company_id into v_selected_company_id
    from public.company_memberships membership
    where membership.user_id=v_user_id
      and membership.status='active'
      and coalesce(membership.is_active,true)
      and (p_selected_company_id is null or membership.company_id=p_selected_company_id)
      and exists(
        select 1 from public.user_roles user_role
        where user_role.user_id=membership.user_id
          and user_role.company_id=membership.company_id
          and coalesce(user_role.status,'active')='active'
          and coalesce(user_role.is_active,true)
      )
    order by (membership.company_id=p_selected_company_id) desc,
             (membership.membership_role='owner') desc,
             membership.created_at
    limit 1;
  end if;

  select coalesce(jsonb_agg(distinct role.key),'[]'::jsonb)
  into v_roles
  from public.user_roles user_role
  join public.roles role on role.id=user_role.role_id and coalesce(role.is_active,true)
  where user_role.user_id=v_user_id
    and coalesce(user_role.status,'active')='active'
    and coalesce(user_role.is_active,true)
    and (user_role.company_id is null or user_role.company_id=v_selected_company_id);

  select coalesce(jsonb_agg(distinct permission.key),'[]'::jsonb)
  into v_permissions
  from public.user_roles user_role
  join public.roles role on role.id=user_role.role_id and coalesce(role.is_active,true)
  join public.role_permissions role_permission on role_permission.role_id=role.id
  join public.permissions permission on permission.id=role_permission.permission_id
  where user_role.user_id=v_user_id
    and coalesce(user_role.status,'active')='active'
    and coalesce(user_role.is_active,true)
    and (user_role.company_id is null or user_role.company_id=v_selected_company_id)
    and coalesce(role_permission.effect,'allow')='allow';

  if v_selected_company_id is not null then
    select jsonb_build_object(
      'id',company.id,
      'name',company.name,
      'slug',company.slug,
      'org_number',company.org_number,
      'status',company.status,
      'lifecycle_status',company.lifecycle_status,
      'lifecycle_state_version',company.lifecycle_state_version
    ) into v_company
    from public.companies company where company.id=v_selected_company_id;

    select coalesce(jsonb_object_agg(operation.operation, to_jsonb(decision)),'{}'::jsonb)
    into v_policy
    from unnest(array[
      'tenant.provisioning.execute','email.send','webhook.deliver',
      'customer_automation.execute','facility_lookup.execute',
      'contract_channel.sell','api_client.execute'
    ]::text[]) operation(operation)
    cross join lateral public.canonical_tenant_operation_decision(
      v_selected_company_id, operation.operation
    ) decision;
  end if;

  return jsonb_build_object(
    'authorized',true,
    'user_id',v_user_id,
    'user_email',v_user_email,
    'is_platform_admin',v_platform,
    'selected_company_id',v_selected_company_id,
    'memberships',v_memberships,
    'roles',v_roles,
    'permissions',v_permissions,
    'company',v_company,
    'operation_policy',v_policy,
    'access_invariant_ok',v_platform or v_selected_company_id is not null
  );
end
$$;

--
-- Name: canonical_bind_test_run_active_configuration(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_bind_test_run_active_configuration() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor_role text;
  v_environment_type public.ediel_environment_type;
  v_message_family text;
  v_definition_count integer;
  v_definition public.ediel_test_cases%rowtype;
  v_config_count integer;
  v_config public.ediel_active_test_configurations%rowtype;
  v_snapshot public.ediel_configuration_snapshots%rowtype;
  v_actor public.ediel_actor_settings%rowtype;
  v_route public.ediel_route_profiles%rowtype;
begin
  if lower(coalesce(new.environment,'test')) <> 'test' then return new; end if;
  if new.company_id is null then return new; end if;

  v_actor_role := case lower(coalesce(nullif(new.actor_role,''),new.role_code))
    when 'supplier' then 'supplier'
    when 'electricity_supplier' then 'supplier'
    when 'esco' then 'energy_service_company'
    when 'energy_service_company' then 'energy_service_company'
    else null
  end;
  if v_actor_role is null then return new; end if;

  v_message_family := upper(coalesce(nullif(new.message_family,''),new.test_suite));
  v_environment_type := new.environment_type;

  select count(*) into v_definition_count
  from public.ediel_test_cases tc
  where tc.is_active
    and upper(tc.test_case_code)=upper(new.test_case_code)
    and lower(tc.actor_role)=v_actor_role
    and upper(tc.message_family)=v_message_family;

  if v_definition_count=1 then
    select * into strict v_definition
    from public.ediel_test_cases tc
    where tc.is_active
      and upper(tc.test_case_code)=upper(new.test_case_code)
      and lower(tc.actor_role)=v_actor_role
      and upper(tc.message_family)=v_message_family;

    v_environment_type := case
      when upper(v_definition.suite_key) like 'AGT\_%' escape '\' then 'agt_test'::public.ediel_environment_type
      when upper(v_definition.suite_key) like 'TGT\_%' escape '\' then 'tgt_test'::public.ediel_environment_type
      else coalesce(v_environment_type,'bilateral_test'::public.ediel_environment_type)
    end;
    v_message_family := upper(v_definition.message_family);
  elsif v_definition_count>1 then
    raise exception 'canonical_test_definition_ambiguous_for_run';
  end if;

  select count(*) into v_config_count
  from public.ediel_active_test_configurations c
  where c.company_id=new.company_id
    and c.environment='test'
    and c.status='active'
    and c.environment_type=v_environment_type
    and upper(c.test_suite)=upper(new.test_suite)
    and lower(c.actor_role)=v_actor_role
    and upper(c.message_family)=v_message_family
    and (
      nullif(btrim(new.setup_package),'') is null
      or upper(new.setup_package)=upper(new.test_suite)
      or c.setup_package=new.setup_package
    );

  if v_config_count=0 then
    if coalesce(new.engine_version,'')='actor-testing-evidence-v2'
       or lower(coalesce(new.status,'')) in ('running','passed') then
      raise exception 'active_role_scoped_test_configuration_required';
    end if;
    return new;
  end if;
  if v_config_count>1 then
    raise exception 'active_role_scoped_test_configuration_ambiguous';
  end if;

  select * into strict v_config
  from public.ediel_active_test_configurations c
  where c.company_id=new.company_id
    and c.environment='test'
    and c.status='active'
    and c.environment_type=v_environment_type
    and upper(c.test_suite)=upper(new.test_suite)
    and lower(c.actor_role)=v_actor_role
    and upper(c.message_family)=v_message_family
    and (
      nullif(btrim(new.setup_package),'') is null
      or upper(new.setup_package)=upper(new.test_suite)
      or c.setup_package=new.setup_package
    );

  if v_config.actor_profile_id is null or v_config.route_profile_id is null then
    raise exception 'active_test_configuration_actor_and_route_binding_required';
  end if;

  select * into v_snapshot
  from public.ediel_configuration_snapshots
  where id=v_config.configuration_snapshot_id and company_id=new.company_id;
  if not found then raise exception 'active_test_configuration_snapshot_not_found'; end if;

  select * into v_actor
  from public.ediel_actor_settings
  where id=v_config.actor_profile_id and company_id=new.company_id;
  if not found or lower(coalesce(v_actor.environment,''))<>'test' or coalesce(v_actor.is_active,false)<>true then
    raise exception 'active_test_configuration_actor_invalid';
  end if;

  select * into v_route
  from public.ediel_route_profiles
  where id=v_config.route_profile_id and company_id=new.company_id;
  if not found or lower(coalesce(v_route.environment,''))<>'test'
     or coalesce(v_route.is_active,true)<>true or coalesce(v_route.is_enabled,true)<>true then
    raise exception 'active_test_configuration_route_invalid';
  end if;

  if upper(coalesce(v_route.sender_ediel_id,v_route.own_ediel_id,''))
     <> upper(coalesce(v_actor.actor_ediel_id,v_actor.ediel_id,'')) then
    raise exception 'active_test_configuration_route_sender_actor_mismatch';
  end if;

  new.actor_role := v_actor_role;
  new.message_family := v_message_family;
  new.environment_type := v_environment_type;
  new.setup_package := v_config.setup_package;
  new.actor_profile_id := v_config.actor_profile_id;
  new.route_profile_id := v_config.route_profile_id;
  new.configuration_snapshot_id := v_config.configuration_snapshot_id;
  new.configuration_hash := v_snapshot.configuration_hash;
  return new;
end;
$$;

--
-- Name: canonical_block_claimed_ediel_outbox_item(uuid, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_block_claimed_ediel_outbox_item(p_outbox_item_id uuid, p_worker_id text, p_reason text, p_company_status text DEFAULT NULL::text, p_operation_decision jsonb DEFAULT '{}'::jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_changed integer;
begin
  if p_outbox_item_id is null or nullif(btrim(p_worker_id),'') is null
     or nullif(btrim(p_reason),'') is null then
    raise exception using errcode='22023', message='outbox_item_worker_and_reason_required';
  end if;

  update public.ediel_outbox
  set status='blocked_tenant_state',
      blocked_reason=p_reason,
      blocked_at=now(),
      company_status_snapshot=p_company_status,
      operation_decision_snapshot=coalesce(p_operation_decision,'{}'::jsonb),
      locked_at=null,
      locked_by=null,
      updated_at=now()
  where id=p_outbox_item_id
    and locked_by=p_worker_id
    and status='sending';
  get diagnostics v_changed = row_count;
  if v_changed <> 1 then
    raise exception using errcode='P0001', message='ediel_outbox_claim_block_lock_lost';
  end if;
  return 'blocked_tenant_state';
end
$$;

--
-- Name: ediel_configuration_snapshots; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ediel_configuration_snapshots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    snapshot_version bigint NOT NULL,
    actor_role text,
    test_ediel_id text,
    production_ediel_id text,
    test_brp_ediel_id text,
    production_brp_ediel_id text,
    test_application_reference text,
    production_application_reference text,
    primary_test_route_id uuid,
    primary_production_route_id uuid,
    payload jsonb NOT NULL,
    configuration_hash text NOT NULL,
    reason text NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: canonical_capture_ediel_configuration_snapshot(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_capture_ediel_configuration_snapshot(p_company_id uuid, p_actor_user_id uuid, p_reason text) RETURNS public.ediel_configuration_snapshots
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_actor_user_id is null then
    return public.canonical_capture_ediel_configuration_snapshot_v1_unchecked(
      p_company_id,
      null,
      p_reason
    );
  end if;

  if not public.canonical_actor_is_authorized(
    p_company_id,
    p_actor_user_id,
    'ediel.profile.write',
    false
  ) then
    raise exception 'actor_not_authorized_for_configuration_snapshot';
  end if;

  return public.canonical_capture_ediel_configuration_snapshot_v1_unchecked(
    p_company_id,
    p_actor_user_id,
    p_reason
  );
end;
$$;

--
-- Name: canonical_capture_ediel_configuration_snapshot_v1_unchecked(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_capture_ediel_configuration_snapshot_v1_unchecked(p_company_id uuid, p_actor_user_id uuid, p_reason text) RETURNS public.ediel_configuration_snapshots
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_company public.companies%rowtype;
  v_payload jsonb;
  v_hash text;
  v_next_version bigint;
  v_snapshot public.ediel_configuration_snapshots%rowtype;
  v_existing public.ediel_configuration_snapshots%rowtype;
begin
  if p_company_id is null then raise exception 'company_id_required'; end if;
  select * into v_company from public.companies where id = p_company_id for update;
  if not found then raise exception 'tenant_not_found'; end if;

  v_payload := jsonb_build_object(
    'company', jsonb_build_object(
      'id', v_company.id,
      'actor_role', coalesce(v_company.actor_role, nullif(to_jsonb(v_company)->>'market_role', '')),
      'test_ediel_id', v_company.test_ediel_id,
      'production_ediel_id', v_company.production_ediel_id,
      'brp_ediel_id', v_company.brp_ediel_id,
      'test_application_reference', v_company.test_application_reference,
      'production_application_reference', v_company.production_application_reference,
      'test_sender_sub_address', v_company.test_sender_sub_address,
      'production_sender_sub_address', v_company.production_sender_sub_address,
      'test_mailbox', v_company.test_mailbox,
      'production_mailbox', v_company.production_mailbox,
      'primary_test_route_id', v_company.ediel_primary_test_route_profile_id,
      'primary_production_route_id', v_company.ediel_primary_production_route_profile_id
    ),
    'actor_profiles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', a.id,
        'environment', a.environment,
        'actor_role', coalesce(a.actor_role, a.role),
        'ediel_id', coalesce(a.actor_ediel_id, a.ediel_id),
        'sender_subaddress', coalesce(a.sender_sub_address, a.sender_subaddress),
        'receiver_subaddress', coalesce(a.receiver_sub_address, a.receiver_subaddress),
        'application_reference', coalesce(a.application_reference, a.default_application_reference),
        'mailbox', a.mailbox,
        'brp_ediel_id', a.brp_ediel_id,
        'is_active', a.is_active
      ) order by a.environment, a.id)
      from public.ediel_actor_settings a
      where a.company_id = p_company_id
    ), '[]'::jsonb),
    'routes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id,
        'environment', r.environment,
        'route_type', r.route_type,
        'sender_ediel_id', r.sender_ediel_id,
        'sender_subaddress', coalesce(r.sender_sub_address, r.sender_subaddress),
        'receiver_ediel_id', r.receiver_ediel_id,
        'receiver_subaddress', coalesce(r.receiver_sub_address, r.receiver_subaddress),
        'mailbox_id', r.mailbox_id,
        'transport_profile_id', r.transport_profile_id,
        'certificate_id', r.certificate_id,
        'receiver_certificate_id', r.receiver_certificate_id,
        'is_active', r.is_active,
        'is_enabled', r.is_enabled
      ) order by r.environment, r.id)
      from public.ediel_route_profiles r
      where r.company_id = p_company_id
    ), '[]'::jsonb),
    'mailboxes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', m.id,
        'environment', m.environment,
        'mailbox_name', m.mailbox_name,
        'email_address', m.email_address,
        'imap_host', m.imap_host,
        'imap_port', m.imap_port,
        'provider', m.provider,
        'mailbox_type', m.mailbox_type,
        'is_active', m.is_active,
        'is_shared_platform_mailbox', m.is_shared_platform_mailbox,
        'secret_reference_present', m.secret_reference is not null
      ) order by m.environment, m.id)
      from public.ediel_mailboxes m
      where m.company_id = p_company_id
    ), '[]'::jsonb),
    'certificates', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', c.id,
        'fingerprint', c.certificate_fingerprint,
        'valid_from', c.certificate_valid_from,
        'valid_to', c.certificate_valid_to,
        'encryption_status', c.encryption_status,
        'status', c.status
      ) order by c.id)
      from public.ediel_certificates c
      where c.company_id = p_company_id
    ), '[]'::jsonb),
    'active_test_configurations', coalesce((
      select jsonb_agg(jsonb_build_object(
        'environment', tc.environment,
        'test_suite', tc.test_suite,
        'actor_role', tc.actor_role,
        'message_family', tc.message_family,
        'setup_package', tc.setup_package,
        'status', tc.status
      ) order by tc.environment, tc.test_suite, tc.actor_role, tc.message_family, tc.setup_package)
      from public.ediel_active_test_configurations tc
      where tc.company_id = p_company_id and tc.status = 'active'
    ), '[]'::jsonb),
    'active_rule_versions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', rv.id,
        'rule_key', rv.rule_key,
        'version_code', rv.version_code,
        'schema_version', rv.schema_version,
        'environment', rv.environment,
        'message_family', rv.message_family,
        'message_code', rv.message_code,
        'business_process', rv.business_process,
        'source_version', rv.source_version,
        'status', rv.status,
        'is_active', rv.is_active
      ) order by rv.rule_key, rv.version_code, rv.id)
      from public.ediel_rule_versions rv
      where coalesce(rv.is_active, false) = true
        and coalesce(rv.status, 'active') = 'active'
    ), '[]'::jsonb),
    'active_rule_packs', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', rp.id,
        'market', rp.market,
        'family', rp.family,
        'guide_version', rp.guide_version,
        'guide_revision', rp.guide_revision,
        'unh_association_code', rp.unh_association_code,
        'valid_from', rp.valid_from,
        'valid_to', rp.valid_to,
        'status', rp.status,
        'source_hash', rp.source_hash,
        'field_matrix_version', rp.field_matrix_version,
        'code_list_versions', rp.code_list_versions
      ) order by rp.market, rp.family, rp.guide_version, rp.guide_revision, rp.id)
      from public.ediel_rule_packs rp
      where rp.status = 'active'
    ), '[]'::jsonb),
    'enabled_message_profiles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', mp.id,
        'rule_pack_id', mp.rule_pack_id,
        'message_code', mp.message_code,
        'transaction_subtype', mp.transaction_subtype,
        'direction', mp.direction,
        'business_process', mp.business_process,
        'phase', mp.phase,
        'profile_key', mp.profile_key,
        'profile', mp.profile,
        'is_enabled', mp.is_enabled
      ) order by mp.rule_pack_id, mp.message_code, mp.transaction_subtype, mp.direction, mp.profile_key, mp.id)
      from public.ediel_message_profiles mp
      where mp.is_enabled = true
    ), '[]'::jsonb),
    'active_tenant_rule_profile_versions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', rpv.id,
        'rule_profile_id', rpv.rule_profile_id,
        'profile_key', rpv.profile_key,
        'version', rpv.version,
        'status', rpv.status,
        'checksum', rpv.checksum,
        'source_revision', rpv.source_revision,
        'rules', rpv.rules
      ) order by rpv.profile_key, rpv.version, rpv.id)
      from public.ediel_rule_profile_versions rpv
      where rpv.company_id = p_company_id and rpv.status = 'active'
    ), '[]'::jsonb),
    'engine_version', 'canonical-evidence-v3'
  );

  v_hash := encode(digest(convert_to(v_payload::text, 'utf8'), 'sha256'), 'hex');
  select * into v_existing
  from public.ediel_configuration_snapshots
  where company_id = p_company_id and configuration_hash = v_hash;
  if found then return v_existing; end if;

  select coalesce(max(snapshot_version), 0) + 1 into v_next_version
  from public.ediel_configuration_snapshots
  where company_id = p_company_id;

  insert into public.ediel_configuration_snapshots(
    company_id, snapshot_version, actor_role, test_ediel_id, production_ediel_id,
    test_brp_ediel_id, production_brp_ediel_id,
    test_application_reference, production_application_reference,
    primary_test_route_id, primary_production_route_id, payload, configuration_hash,
    reason, created_by
  ) values (
    p_company_id,
    v_next_version,
    coalesce(v_company.actor_role, nullif(to_jsonb(v_company)->>'market_role', '')),
    v_company.test_ediel_id,
    v_company.production_ediel_id,
    v_company.brp_ediel_id,
    v_company.brp_ediel_id,
    v_company.test_application_reference,
    v_company.production_application_reference,
    v_company.ediel_primary_test_route_profile_id,
    v_company.ediel_primary_production_route_profile_id,
    v_payload,
    v_hash,
    coalesce(nullif(btrim(p_reason), ''), 'configuration_changed'),
    p_actor_user_id
  ) returning * into v_snapshot;

  -- Exactly one durable readiness revalidation job per immutable snapshot.
  insert into public.company_provisioning_jobs(
    company_id,
    job_key,
    status,
    idempotency_key,
    available_at,
    last_error_details
  ) values (
    p_company_id,
    'ediel_readiness_revalidate',
    'pending',
    v_snapshot.id::text,
    now(),
    '{}'::jsonb
  )
  on conflict (company_id, job_key, idempotency_key) do nothing;

  update public.ediel_test_runs
  set is_stale = true,
      stale_reason = 'configuration_changed',
      stale_at = now()
  where company_id = p_company_id
    and completed_at is not null
    and configuration_snapshot_id is distinct from v_snapshot.id;

  update public.actor_test_results
  set is_stale = true,
      stale_reason = 'configuration_changed',
      updated_at = now()
  where company_id = p_company_id
    and configuration_snapshot_id is distinct from v_snapshot.id;

  update public.ediel_production_readiness_checks
  set is_stale = true,
      stale_reason = 'configuration_changed'
  where company_id = p_company_id
    and configuration_snapshot_id is distinct from v_snapshot.id;

  update public.ediel_go_live_events
  set is_stale = true,
      stale_reason = 'configuration_changed'
  where company_id = p_company_id
    and event_type = 'production_dry_run'
    and configuration_snapshot_id is distinct from v_snapshot.id;

  update public.ediel_production_state
  set configuration_snapshot_id = v_snapshot.id,
      state = case when state in ('prepared', 'live') then 'blocked' else state end,
      blocked_reason = case when state in ('prepared', 'live') then 'configuration_changed' else blocked_reason end,
      state_version = state_version + 1,
      updated_at = now()
  where company_id = p_company_id;

  if exists(
    select 1 from public.ediel_production_state
    where company_id = p_company_id and state = 'blocked'
  ) then
    update public.companies
    set production_status = 'blocked',
        ediel_production_status = 'blocked',
        live_ediel_enabled = false,
        ediel_production_enabled = false,
        live_blocked_reason = 'configuration_changed',
        updated_at = now()
    where id = p_company_id;

    insert into public.ediel_send_locks(
      company_id, environment, locked, locked_reason, locked_at, updated_at
    ) values (
      p_company_id, 'production', true, 'configuration_changed', now(), now()
    )
    on conflict (company_id, environment) do update
    set locked = true,
        locked_reason = 'configuration_changed',
        locked_at = now(),
        updated_at = now();
  end if;

  return v_snapshot;
end;
$$;

--
-- Name: canonical_capture_ediel_test_configuration_snapshot(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_capture_ediel_test_configuration_snapshot(p_company_id uuid, p_actor_user_id uuid, p_actor_profile_id uuid, p_route_profile_id uuid, p_reason text) RETURNS public.ediel_configuration_snapshots
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_company public.companies%rowtype;
  v_actor public.ediel_actor_settings%rowtype;
  v_route public.ediel_route_profiles%rowtype;
  v_payload jsonb;
  v_hash text;
  v_next_version bigint;
  v_snapshot public.ediel_configuration_snapshots%rowtype;
  v_existing public.ediel_configuration_snapshots%rowtype;
  v_actor_role text;
  v_actor_ediel_id text;
  v_route_sender text;
  v_route_receiver text;
begin
  if p_company_id is null or p_actor_profile_id is null or p_route_profile_id is null then
    raise exception 'company_actor_profile_and_route_required';
  end if;
  if not public.canonical_actor_is_authorized(p_company_id, p_actor_user_id, 'ediel.profile.write', false) then
    raise exception 'actor_not_authorized_for_test_configuration_snapshot';
  end if;

  select * into v_company
  from public.companies
  where id=p_company_id
  for update;
  if not found then raise exception 'tenant_not_found'; end if;

  select * into v_actor
  from public.ediel_actor_settings
  where id=p_actor_profile_id and company_id=p_company_id
  for share;
  if not found then raise exception 'tenant_scoped_test_actor_profile_not_found'; end if;
  if lower(coalesce(v_actor.environment,'')) <> 'test' or coalesce(v_actor.is_active,false) <> true then
    raise exception 'test_actor_profile_must_be_active_test_profile';
  end if;

  v_actor_role := case lower(coalesce(nullif(v_actor.actor_role,''),v_actor.role))
    when 'supplier' then 'supplier'
    when 'electricity_supplier' then 'supplier'
    when 'esco' then 'energy_service_company'
    when 'energy_service_company' then 'energy_service_company'
    else lower(coalesce(nullif(v_actor.actor_role,''),v_actor.role))
  end;
  v_actor_ediel_id := nullif(btrim(coalesce(v_actor.actor_ediel_id,v_actor.ediel_id)), '');
  if v_actor_role is null or v_actor_ediel_id is null then
    raise exception 'test_actor_profile_identity_incomplete';
  end if;

  select * into v_route
  from public.ediel_route_profiles
  where id=p_route_profile_id and company_id=p_company_id
  for share;
  if not found then raise exception 'tenant_scoped_test_route_profile_not_found'; end if;
  if lower(coalesce(v_route.environment,'')) <> 'test'
     or coalesce(v_route.is_active,true) <> true
     or coalesce(v_route.is_enabled,true) <> true then
    raise exception 'test_route_profile_must_be_active_test_route';
  end if;

  v_route_sender := nullif(btrim(coalesce(v_route.sender_ediel_id,v_route.own_ediel_id)), '');
  v_route_receiver := nullif(btrim(coalesce(v_route.receiver_ediel_id,v_route.counterparty_ediel_id)), '');
  if v_route_sender is null or upper(v_route_sender) <> upper(v_actor_ediel_id) then
    raise exception 'test_route_sender_must_match_actor_profile';
  end if;
  if v_route_receiver is null then
    raise exception 'test_route_receiver_required';
  end if;
  if v_route.actor_setting_id is not null and v_route.actor_setting_id <> v_actor.id then
    raise exception 'test_route_actor_binding_mismatch';
  end if;

  v_payload := jsonb_build_object(
    'test_context', jsonb_build_object(
      'actor_profile_id', v_actor.id,
      'route_profile_id', v_route.id,
      'actor_role', v_actor_role,
      'test_ediel_id', v_actor_ediel_id,
      'counterparty_ediel_id', v_route_receiver,
      'message_family', upper(coalesce(v_route.message_family,'')),
      'application_reference', v_route.application_reference,
      'environment_type', v_route.environment_type
    ),
    'company', jsonb_build_object(
      'id', v_company.id,
      'actor_role', v_actor_role,
      'test_ediel_id', v_actor_ediel_id,
      'production_ediel_id', v_company.production_ediel_id,
      'brp_ediel_id', coalesce(v_actor.brp_ediel_id,v_company.brp_ediel_id),
      'test_application_reference', v_route.application_reference,
      'production_application_reference', v_company.production_application_reference,
      'primary_test_route_id', v_route.id,
      'primary_production_route_id', v_company.ediel_primary_production_route_profile_id
    ),
    'actor_profiles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',a.id,'environment',a.environment,'actor_role',coalesce(a.actor_role,a.role),
        'ediel_id',coalesce(a.actor_ediel_id,a.ediel_id),
        'sender_subaddress',coalesce(a.sender_sub_address,a.sender_subaddress),
        'receiver_subaddress',coalesce(a.receiver_sub_address,a.receiver_subaddress),
        'application_reference',coalesce(a.application_reference,a.default_application_reference),
        'mailbox',a.mailbox,'brp_ediel_id',a.brp_ediel_id,'is_active',a.is_active
      ) order by a.environment,a.id)
      from public.ediel_actor_settings a
      where a.company_id=p_company_id
    ),'[]'::jsonb),
    'routes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',r.id,'environment',r.environment,'route_type',r.route_type,
        'actor_setting_id',r.actor_setting_id,
        'sender_ediel_id',r.sender_ediel_id,
        'sender_subaddress',coalesce(r.sender_sub_address,r.sender_subaddress),
        'receiver_ediel_id',r.receiver_ediel_id,
        'receiver_subaddress',coalesce(r.receiver_sub_address,r.receiver_subaddress),
        'application_reference',r.application_reference,
        'message_family',r.message_family,
        'environment_type',r.environment_type,
        'mailbox_id',r.mailbox_id,'transport_profile_id',r.transport_profile_id,
        'certificate_id',r.certificate_id,'receiver_certificate_id',r.receiver_certificate_id,
        'transport_security_mode',r.transport_security_mode,
        'is_active',r.is_active,'is_enabled',r.is_enabled
      ) order by r.environment,r.id)
      from public.ediel_route_profiles r
      where r.company_id=p_company_id
    ),'[]'::jsonb),
    'mailboxes', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',m.id,'environment',m.environment,'mailbox_name',m.mailbox_name,
        'email_address',m.email_address,'provider',m.provider,'mailbox_type',m.mailbox_type,
        'transport_mode',m.transport_mode,'tls_required',m.tls_required,
        'signing_mode',m.signing_mode,'encryption_mode',m.encryption_mode,
        'is_active',m.is_active,'is_shared_platform_mailbox',m.is_shared_platform_mailbox
      ) order by m.environment,m.id)
      from public.ediel_mailboxes m
      where m.company_id=p_company_id or m.id=v_route.mailbox_id
    ),'[]'::jsonb),
    'certificates', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',c.id,'fingerprint',coalesce(c.fingerprint_sha256,c.certificate_fingerprint),
        'owner_ediel_id',c.owner_ediel_id,'owner_subaddress',c.owner_subaddress,
        'message_family',c.message_family,'purpose',c.purpose,'usage',c.usage,
        'valid_from',coalesce(c.valid_from,c.certificate_valid_from),
        'valid_to',coalesce(c.valid_to,c.certificate_valid_to),
        'encryption_status',c.encryption_status,'status',c.status
      ) order by c.id)
      from public.ediel_certificates c
      where c.id in (v_route.certificate_id,v_route.receiver_certificate_id)
    ),'[]'::jsonb),
    'active_rule_versions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'rule_key',rv.rule_key,'version_code',rv.version_code,'schema_version',rv.schema_version,
        'environment',rv.environment,'status',rv.status,'is_active',rv.is_active
      ) order by rv.rule_key,rv.version_code)
      from public.ediel_rule_versions rv
      where coalesce(rv.is_active,false)=true and coalesce(rv.status,'active')='active'
    ),'[]'::jsonb),
    'engine_version','canonical-evidence-v3-role-scoped'
  );

  v_hash := encode(digest(convert_to(v_payload::text,'utf8'),'sha256'),'hex');
  select * into v_existing
  from public.ediel_configuration_snapshots
  where company_id=p_company_id and configuration_hash=v_hash;
  if found then return v_existing; end if;

  select coalesce(max(snapshot_version),0)+1 into v_next_version
  from public.ediel_configuration_snapshots
  where company_id=p_company_id;

  insert into public.ediel_configuration_snapshots(
    company_id,snapshot_version,actor_role,test_ediel_id,production_ediel_id,
    test_brp_ediel_id,production_brp_ediel_id,
    test_application_reference,production_application_reference,
    primary_test_route_id,primary_production_route_id,payload,configuration_hash,
    reason,created_by
  ) values (
    p_company_id,v_next_version,v_actor_role,v_actor_ediel_id,v_company.production_ediel_id,
    coalesce(v_actor.brp_ediel_id,v_company.brp_ediel_id),v_company.brp_ediel_id,
    v_route.application_reference,v_company.production_application_reference,
    v_route.id,v_company.ediel_primary_production_route_profile_id,
    v_payload,v_hash,coalesce(nullif(btrim(p_reason),''),'test_configuration_changed'),p_actor_user_id
  ) returning * into v_snapshot;

  update public.ediel_test_runs r
  set is_stale=true,stale_reason='role_scoped_test_configuration_changed',stale_at=now()
  where r.company_id=p_company_id
    and r.completed_at is not null
    and r.configuration_snapshot_id is distinct from v_snapshot.id
    and case lower(coalesce(nullif(r.actor_role,''),r.role_code))
      when 'supplier' then 'supplier'
      when 'electricity_supplier' then 'supplier'
      when 'esco' then 'energy_service_company'
      when 'energy_service_company' then 'energy_service_company'
      else lower(coalesce(nullif(r.actor_role,''),r.role_code))
    end = v_actor_role
    and upper(coalesce(r.message_family,r.test_suite,'')) = upper(coalesce(v_route.message_family,r.test_suite,''));

  update public.actor_test_results ar
  set is_stale=true,stale_reason='role_scoped_test_configuration_changed',updated_at=now()
  from public.ediel_test_runs r
  where ar.company_id=p_company_id
    and ar.ediel_test_run_id=r.id
    and r.company_id=p_company_id
    and r.configuration_snapshot_id is distinct from v_snapshot.id
    and case lower(coalesce(nullif(r.actor_role,''),r.role_code))
      when 'supplier' then 'supplier'
      when 'electricity_supplier' then 'supplier'
      when 'esco' then 'energy_service_company'
      when 'energy_service_company' then 'energy_service_company'
      else lower(coalesce(nullif(r.actor_role,''),r.role_code))
    end = v_actor_role
    and upper(coalesce(r.message_family,r.test_suite,'')) = upper(coalesce(v_route.message_family,r.test_suite,''));

  return v_snapshot;
end;
$$;

--
-- Name: canonical_change_tenant_user_access(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_change_tenant_user_access(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_action text := lower(coalesce(p_command->>'action',''));
  v_company_id uuid := nullif(p_command->>'company_id','')::uuid;
  v_user_id uuid := nullif(p_command->>'user_id','')::uuid;
  v_role_key text := lower(nullif(btrim(p_command->>'role_key'),''));
  v_requested_membership text := lower(nullif(btrim(p_command->>'membership_role'),''));
  v_membership_role text;
  v_normalized jsonb := p_command;
begin
  if v_action = 'upsert' then
    if v_role_key is null then
      raise exception using errcode='22023', message='canonical_role_key_required';
    end if;

    select m.membership_role
      into v_membership_role
    from public.canonical_tenant_access_role_mapping m
    where m.role_key=v_role_key and m.is_assignable;

    if v_membership_role is null then
      raise exception using errcode='22023', message='canonical_tenant_role_not_assignable';
    end if;

    if v_requested_membership is not null
       and v_requested_membership is distinct from v_membership_role then
      raise exception using errcode='23514', message='membership_role_role_key_mismatch';
    end if;

    v_normalized := v_normalized || jsonb_build_object(
      'role_key',v_role_key,
      'membership_role',v_membership_role
    );
  end if;

  v_normalized := v_normalized || jsonb_build_object('actor_user_id',nullif(p_command->>'actor_user_id',''));

  declare
    v_result jsonb;
    v_role_id uuid;
    v_active_user_role_id uuid;
    v_existing_mapped_role_id uuid;
  begin
    v_result := public.canonical_change_tenant_user_access_v2_unmapped(v_normalized);

    if v_action = 'upsert' and v_company_id is not null and v_user_id is not null then
      select r.id into v_role_id
      from public.roles r
      where lower(coalesce(r.key,r.name))=v_role_key
      order by r.created_at asc,r.id asc
      limit 1;
      if v_role_id is null then
        raise exception using errcode='22023', message='canonical_tenant_role_definition_missing';
      end if;
      select ur.id into v_active_user_role_id
      from public.user_roles ur
      where ur.company_id=v_company_id and ur.user_id=v_user_id
        and coalesce(ur.is_active,true) and coalesce(ur.status,'active')='active'
      order by ur.created_at desc,ur.id desc
      limit 1
      for update;
      if v_active_user_role_id is null then
        raise exception using errcode='P0001', message='canonical_active_tenant_role_missing_after_access_change';
      end if;

      select ur.id into v_existing_mapped_role_id
      from public.user_roles ur
      where ur.company_id=v_company_id and ur.user_id=v_user_id
        and ur.role_id=v_role_id and ur.id<>v_active_user_role_id
      order by ur.created_at asc,ur.id asc
      limit 1
      for update;

      if v_existing_mapped_role_id is null then
        update public.user_roles
        set role=v_role_key,role_id=v_role_id,status='active',is_active=true,updated_at=now()
        where id=v_active_user_role_id;
      else
        update public.user_roles
        set status='disabled',is_active=false,updated_at=now()
        where id=v_active_user_role_id;
        update public.user_roles
        set role=v_role_key,role_id=v_role_id,status='active',is_active=true,updated_at=now()
        where id=v_existing_mapped_role_id;
      end if;
    end if;

    return v_result;
  end;
end
$$;

--
-- Name: canonical_change_tenant_user_access_v1_unchecked(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_change_tenant_user_access_v1_unchecked(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_company_id uuid:=(p_command->>'company_id')::uuid;
  v_user_id uuid:=(p_command->>'user_id')::uuid;
  v_actor_user_id uuid:=nullif(p_command->>'actor_user_id','')::uuid;
  v_action text:=lower(p_command->>'action');
  v_membership_role text:=lower(coalesce(nullif(p_command->>'membership_role',''),'member'));
  v_role_key text:=lower(coalesce(nullif(p_command->>'role_key',''),v_membership_role));
  v_idempotency_key text:=p_command->>'idempotency_key';
  v_company_status text;
  v_current_role text;
  v_current_status text;
  v_actor_membership_role text;
  v_actor_is_platform_admin boolean:=false;
  v_owner_count integer;
  v_admin_count integer;
  v_target_auth_active boolean:=false;
  v_target_profile_active boolean:=false;
  v_existing jsonb;
  v_result jsonb;
  v_event_id uuid;
begin
  if v_company_id is null or v_user_id is null or v_actor_user_id is null
     or nullif(btrim(v_idempotency_key),'') is null then
    raise exception 'company_user_actor_and_idempotency_required';
  end if;
  if v_action not in ('upsert','remove','disable') then raise exception 'invalid_access_action'; end if;
  if v_membership_role not in ('owner','admin','company_admin','member','viewer') then raise exception 'invalid_membership_role'; end if;

  select result_payload into v_existing from public.canonical_command_results
  where company_id=v_company_id and command_type='tenant.user_access.change' and idempotency_key=v_idempotency_key;
  if found then return v_existing; end if;

  select status into v_company_status from public.companies where id=v_company_id for update;
  if not found then raise exception 'tenant_not_found'; end if;
  if v_company_status not in ('onboarding','active','paused') then
    raise exception 'tenant_state_blocks_user_management:%',coalesce(v_company_status,'unknown');
  end if;

  v_actor_is_platform_admin:=public.canonical_actor_is_platform_admin(v_actor_user_id);
  if not v_actor_is_platform_admin then
    select membership_role into v_actor_membership_role
    from public.company_memberships
    where company_id=v_company_id and user_id=v_actor_user_id
      and status='active' and coalesce(is_active,true)
    for update;
    if v_actor_membership_role not in ('owner','admin','company_admin') then
      raise exception 'actor_not_authorized_for_tenant_user_management';
    end if;
  end if;

  select membership_role,status into v_current_role,v_current_status
  from public.company_memberships
  where company_id=v_company_id and user_id=v_user_id
  for update;

  select count(*) into v_owner_count from public.company_memberships
  where company_id=v_company_id and status='active' and coalesce(is_active,true) and membership_role='owner';
  select count(*) into v_admin_count from public.company_memberships
  where company_id=v_company_id and status='active' and coalesce(is_active,true)
    and membership_role in ('owner','admin','company_admin');

  if v_current_status='active' and v_current_role='owner' and v_owner_count<=1
     and (v_action<>'upsert' or v_membership_role<>'owner') then
    raise exception 'last_active_owner_cannot_be_removed_or_downgraded';
  end if;
  if v_current_status='active' and v_current_role in ('owner','admin','company_admin') and v_admin_count<=1
     and (v_action<>'upsert' or v_membership_role not in ('owner','admin','company_admin')) then
    raise exception 'last_active_admin_cannot_be_removed_or_downgraded';
  end if;
  if not v_actor_is_platform_admin and v_membership_role='owner' and v_actor_membership_role<>'owner' then
    raise exception 'only_owner_or_platform_admin_can_assign_owner';
  end if;
  if not v_actor_is_platform_admin and v_current_role='owner' and v_actor_membership_role<>'owner' then
    raise exception 'only_owner_or_platform_admin_can_modify_owner';
  end if;

  if v_action='upsert' then
    select exists(select 1 from auth.users u where u.id=v_user_id and coalesce(u.banned_until,now()-interval '1 second')<=now())
      into v_target_auth_active;
    select exists(select 1 from public.user_profiles up where up.id=v_user_id and up.user_status='active')
      into v_target_profile_active;
    if not v_target_auth_active then raise exception 'target_auth_user_missing_or_inactive'; end if;
    if not v_target_profile_active then raise exception 'target_user_profile_missing_or_inactive'; end if;

    insert into public.company_memberships(
      company_id,user_id,membership_role,status,is_active,invited_by,accepted_at,
      suspended_at,disabled_at,removed_at,metadata
    ) values (
      v_company_id,v_user_id,v_membership_role,'active',true,v_actor_user_id,now(),
      null,null,null,jsonb_build_object('canonical_access_command',v_idempotency_key)
    )
    on conflict(company_id,user_id) do update set
      membership_role=excluded.membership_role,status='active',is_active=true,
      accepted_at=coalesce(public.company_memberships.accepted_at,now()),
      suspended_at=null,disabled_at=null,removed_at=null,
      metadata=coalesce(public.company_memberships.metadata,'{}'::jsonb)||excluded.metadata,
      updated_at=now();

    update public.user_roles set status='disabled',is_active=false,updated_at=now()
    where company_id=v_company_id and user_id=v_user_id and is_active=true;
    insert into public.user_roles(user_id,company_id,role,status,is_active,created_at,updated_at)
    values(v_user_id,v_company_id,v_role_key,'active',true,now(),now());
  else
    update public.company_memberships
      set status=case when v_action='remove' then 'removed' else 'disabled' end,
          is_active=false,
          disabled_at=case when v_action='disable' then now() else disabled_at end,
          removed_at=case when v_action='remove' then now() else removed_at end,
          metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('canonical_access_command',v_idempotency_key),
          updated_at=now()
      where company_id=v_company_id and user_id=v_user_id;
    update public.user_roles set status='disabled',is_active=false,updated_at=now()
      where company_id=v_company_id and user_id=v_user_id and is_active=true;
  end if;

  insert into public.canonical_audit_events(
    company_id,event_type,aggregate_type,aggregate_id,actor_user_id,reason,idempotency_key,before_state,after_state
  ) values (
    v_company_id,'TENANT_USER_ROLE_CHANGED','tenant_user',v_user_id,v_actor_user_id,
    p_command->>'reason',v_idempotency_key,
    jsonb_build_object('membership_role',v_current_role,'status',v_current_status),
    jsonb_build_object('action',v_action,'membership_role',v_membership_role,'role_key',v_role_key)
  );
  insert into public.canonical_domain_events(
    company_id,event_type,aggregate_type,aggregate_id,idempotency_key,payload,created_by
  ) values (
    v_company_id,'TENANT_USER_ROLE_CHANGED','tenant_user',v_user_id,v_idempotency_key,
    jsonb_build_object('action',v_action,'membership_role',v_membership_role,'role_key',v_role_key),v_actor_user_id
  ) returning id into v_event_id;
  insert into public.canonical_event_outbox(company_id,domain_event_id,topic,idempotency_key,payload)
  values(v_company_id,v_event_id,'tenant.user.role.changed',v_idempotency_key,
    jsonb_build_object('company_id',v_company_id,'user_id',v_user_id,'action',v_action));

  v_result:=jsonb_build_object('changed',true,'company_id',v_company_id,'user_id',v_user_id,
    'action',v_action,'membership_role',v_membership_role,'role_key',v_role_key);
  insert into public.canonical_command_results(company_id,command_type,idempotency_key,request_payload,result_payload,actor_user_id)
  values(v_company_id,'tenant.user_access.change',v_idempotency_key,p_command,v_result,v_actor_user_id);
  return v_result;
end;
$$;

--
-- Name: canonical_change_tenant_user_access_v2_unmapped(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_change_tenant_user_access_v2_unmapped(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := nullif(p_command->>'company_id', '')::uuid;
  v_actor_user_id uuid := nullif(p_command->>'actor_user_id', '')::uuid;
  v_idempotency_key text := p_command->>'idempotency_key';
  v_request jsonb := p_command - 'actor_user_id';
  v_hash text;
  v_existing public.canonical_command_results%rowtype;
  v_result jsonb;
begin
  if not public.canonical_actor_is_authorized(v_company_id, v_actor_user_id, 'tenant.user.manage', false) then
    raise exception 'actor_not_authorized_for_tenant_user_management';
  end if;
  if nullif(btrim(v_idempotency_key), '') is null then raise exception 'idempotency_key_required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_company_id::text || ':tenant.user_access.change:' || v_idempotency_key, 0));
  v_hash := public.canonical_json_sha256(v_request);
  select * into v_existing from public.canonical_command_results
  where company_id = v_company_id and command_type = 'tenant.user_access.change'
    and idempotency_key = v_idempotency_key;
  if found then
    if v_existing.actor_user_id is distinct from v_actor_user_id then raise exception 'idempotency_actor_mismatch'; end if;
    if v_existing.request_hash <> v_hash then raise exception 'idempotency_key_payload_mismatch'; end if;
    return v_existing.result_payload;
  end if;
  v_result := public.canonical_change_tenant_user_access_v1_unchecked(p_command);
  update public.canonical_command_results set request_payload = v_request
  where company_id = v_company_id and command_type = 'tenant.user_access.change'
    and idempotency_key = v_idempotency_key;
  return v_result;
end;
$$;

--
-- Name: canonical_claim_company_provisioning_jobs(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_claim_company_provisioning_jobs(p_worker_id text, p_limit integer DEFAULT 20, p_lease_seconds integer DEFAULT 300) RETURNS TABLE(id uuid, company_id uuid, job_key text, idempotency_key text, attempt_count integer, max_attempts integer, lease_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if nullif(btrim(p_worker_id), '') is null then
    raise exception 'worker_id_required';
  end if;

  update public.company_provisioning_jobs job
  set status = case when job.attempt_count >= job.max_attempts then 'dead_letter' else 'retry' end,
      dead_letter_at = case when job.attempt_count >= job.max_attempts then coalesce(job.dead_letter_at, now()) else job.dead_letter_at end,
      available_at = case when job.attempt_count < job.max_attempts then now() else job.available_at end,
      last_error_code = 'stale_worker_lease',
      last_error_message = 'Provisioning worker lease expired before completion.',
      locked_at = null,
      locked_by = null,
      lease_token = null,
      updated_at = now()
  where job.status = 'processing'
    and job.locked_at < now() - make_interval(secs => greatest(30, least(p_lease_seconds, 3600)));

  return query
  with candidates as (
    select job.id
    from public.company_provisioning_jobs job
    join public.companies company on company.id = job.company_id
    where job.status in ('pending','retry')
      and job.available_at <= now()
      and job.attempt_count < job.max_attempts
      and company.status in ('onboarding','active')
      and (select decision.allowed
           from public.canonical_tenant_operation_decision(job.company_id, 'tenant.provisioning.execute') decision
           limit 1)
    order by job.available_at, job.created_at
    for update of job skip locked
    limit greatest(1, least(coalesce(p_limit, 20), 100))
  ), claimed as (
    update public.company_provisioning_jobs job
    set status = 'processing',
        attempt_count = job.attempt_count + 1,
        started_at = coalesce(job.started_at, now()),
        claimed_at = now(),
        locked_at = now(),
        locked_by = p_worker_id,
        lease_token = gen_random_uuid(),
        last_error_code = null,
        last_error_message = null,
        updated_at = now()
    from candidates
    where job.id = candidates.id
    returning job.*
  )
  select claimed.id, claimed.company_id, claimed.job_key,
         claimed.idempotency_key, claimed.attempt_count,
         claimed.max_attempts, claimed.lease_token
  from claimed;
end
$$;

--
-- Name: canonical_command_request_hash_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_command_request_hash_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_hash text := public.canonical_json_sha256(coalesce(new.request_payload, '{}'::jsonb));
begin
  if new.request_hash is not null and new.request_hash <> v_hash then
    raise exception 'canonical_request_hash_mismatch';
  end if;
  new.request_hash := v_hash;
  return new;
end;
$$;

