end
$$;

--
-- Name: canonical_guard_actor_test_result_authoritative_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_guard_actor_test_result_authoritative_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_authoritative_status_changed boolean;
begin
  if tg_op='INSERT' then
    v_authoritative_status_changed:=new.status in ('passed','manual_verified');
  else
    v_authoritative_status_changed:=new.status in ('passed','manual_verified')
      and old.status is distinct from new.status;
  end if;

  if v_authoritative_status_changed then
    if new.ediel_test_run_id is null or not exists(
      select 1
      from public.actor_test_attempts a
      where a.company_id=new.company_id
        and a.test_run_id=new.ediel_test_run_id
        and upper(a.test_case_code)=upper(new.test_key)
        and (
          (new.status='passed' and a.status='passed' and a.machine_verified)
          or (new.status='manual_verified' and a.status='manual_verified')
        )
        and a.configuration_snapshot_id=new.configuration_snapshot_id
        and a.configuration_hash=new.configuration_hash
    ) then
      raise exception using errcode='23514', message='authoritative_actor_test_result_requires_canonical_attempt';
    end if;
  end if;
  return new;
end
$$;

--
-- Name: canonical_guard_ediel_test_run_authoritative_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_guard_ediel_test_run_authoritative_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status='passed' and old.status is distinct from 'passed' then
    if not exists(
      select 1
      from public.actor_test_attempts a
      where a.company_id=new.company_id
        and a.test_run_id=new.id
        and a.status='passed'
        and a.machine_verified
        and a.configuration_snapshot_id=new.configuration_snapshot_id
        and a.configuration_hash=new.configuration_hash
        and upper(a.test_case_code)=upper(new.test_case_code)
    ) then
      raise exception using errcode='23514', message='direct_test_run_pass_forbidden_without_canonical_attempt';
    end if;
  end if;
  return new;
end
$$;

--
-- Name: canonical_guard_global_platform_role_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_guard_global_platform_role_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_role text;
begin
  select public.gridex_normalize_platform_role(
           coalesce(new.role, r.key, r.name)
         )
    into v_role
  from public.roles r
  where r.id = new.role_id;

  if v_role is null then
    v_role := public.gridex_normalize_platform_role(new.role);
  end if;

  if new.company_id is not null
     and v_role in ('super_admin', 'platform_admin') then
    raise exception using
      errcode = '23514',
      message = 'tenant_bound_global_platform_role_forbidden';
  end if;

  return new;
end
$$;

--
-- Name: FUNCTION canonical_guard_global_platform_role_scope(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.canonical_guard_global_platform_role_scope() IS 'Trigger-only invariant preventing tenant-bound super_admin/platform_admin rows.';

--
-- Name: canonical_json_sha256(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_json_sha256(p_payload jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select encode(extensions.digest(convert_to(p_payload::text, 'utf8'), 'sha256'::text), 'hex')
$$;

--
-- Name: canonical_manage_platform_user_access(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_manage_platform_user_access(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_actor_user_id uuid := nullif(p_command->>'actor_user_id','')::uuid;
  v_target_user_id uuid := nullif(p_command->>'target_user_id','')::uuid;
  v_action text := lower(coalesce(p_command->>'action',''));
  v_role_id uuid := nullif(p_command->>'role_id','')::uuid;
  v_user_role_id uuid := nullif(p_command->>'user_role_id','')::uuid;
  v_permission_key text := nullif(btrim(p_command->>'permission_key'),'');
  v_effect text := lower(coalesce(nullif(btrim(p_command->>'effect'),''),'allow'));
  v_reason text := nullif(btrim(p_command->>'reason'),'');
  v_preserve_overrides boolean := coalesce((p_command->>'preserve_overrides')::boolean,false);
  v_idempotency_key text := nullif(btrim(p_command->>'idempotency_key'),'');
  v_request jsonb := p_command - 'actor_user_id';
  v_hash text;
  v_existing public.canonical_platform_access_command_results%rowtype;
  v_before jsonb;
  v_after jsonb;
  v_result jsonb;
  v_missing_permissions text[];
  v_overlap text[];
  v_allow text[] := coalesce(array(select jsonb_array_elements_text(coalesce(p_command->'allow_permissions','[]'::jsonb))),array[]::text[]);
  v_deny text[] := coalesce(array(select jsonb_array_elements_text(coalesce(p_command->'deny_permissions','[]'::jsonb))),array[]::text[]);
  v_existing_role_id uuid;
begin
  if v_actor_user_id is null or v_target_user_id is null or v_idempotency_key is null then
    raise exception using errcode='22023', message='actor_target_and_idempotency_required';
  end if;
  if not public.canonical_actor_is_platform_admin(v_actor_user_id) then
    raise exception using errcode='42501', message='platform_admin_required';
  end if;
  if not exists(select 1 from auth.users where id=v_target_user_id and deleted_at is null) then
    raise exception using errcode='P0002', message='target_auth_user_not_found';
  end if;
  if v_action not in (
    'set_primary_role','add_role','remove_role','replace_overrides',
    'clear_overrides','upsert_override','remove_override','disable_platform_access'
  ) then
    raise exception using errcode='22023', message='invalid_platform_access_action';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('platform-access:'||v_target_user_id::text,0));
  v_hash := public.canonical_json_sha256(v_request);

  select * into v_existing
  from public.canonical_platform_access_command_results
  where target_user_id=v_target_user_id
    and command_type='platform.user_access.'||v_action
    and idempotency_key=v_idempotency_key;
  if found then
    if v_existing.request_hash is distinct from v_hash then
      raise exception using errcode='23505', message='IDEMPOTENCY_KEY_REUSE_MISMATCH';
    end if;
    return v_existing.result_payload;
  end if;

  select jsonb_build_object(
    'roles',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',ur.id,'role_id',ur.role_id,'role',ur.role,
        'status',ur.status,'is_active',ur.is_active
      ) order by ur.created_at,ur.id)
      from public.user_roles ur
      where ur.user_id=v_target_user_id and ur.company_id is null
    ),'[]'::jsonb),
    'overrides',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',upo.id,'permission_key',upo.permission_key,'effect',upo.effect,
        'reason',upo.reason,'is_active',upo.is_active
      ) order by upo.permission_key,upo.id)
      from public.user_permission_overrides upo
      where upo.user_id=v_target_user_id and upo.company_id is null
    ),'[]'::jsonb)
  ) into v_before;

  if v_action in ('set_primary_role','add_role') then
    if v_role_id is null or not exists(select 1 from public.roles where id=v_role_id) then
      raise exception using errcode='22023', message='platform_role_not_found';
    end if;
  end if;

  if v_action='set_primary_role' then
    update public.user_roles
    set status='disabled',is_active=false,updated_at=now()
    where user_id=v_target_user_id and company_id is null and coalesce(is_active,true);

    select id into v_existing_role_id
    from public.user_roles
    where user_id=v_target_user_id and company_id is null and role_id=v_role_id
    order by created_at asc,id asc
    limit 1
    for update;

    if v_existing_role_id is null then
      insert into public.user_roles(user_id,company_id,role_id,status,is_active,created_at,updated_at)
      values(v_target_user_id,null,v_role_id,'active',true,now(),now());
    else
      update public.user_roles
      set status='active',is_active=true,updated_at=now()
      where id=v_existing_role_id;
    end if;

    if not v_preserve_overrides then
      delete from public.user_permission_overrides
      where user_id=v_target_user_id and company_id is null;
    end if;

  elsif v_action='add_role' then
    select id into v_existing_role_id
    from public.user_roles
    where user_id=v_target_user_id and company_id is null and role_id=v_role_id
    order by created_at asc,id asc
    limit 1
    for update;
    if v_existing_role_id is null then
      insert into public.user_roles(user_id,company_id,role_id,status,is_active,created_at,updated_at)
      values(v_target_user_id,null,v_role_id,'active',true,now(),now());
    else
      update public.user_roles set status='active',is_active=true,updated_at=now()
      where id=v_existing_role_id;
    end if;

  elsif v_action='remove_role' then
    if v_user_role_id is not null then
      update public.user_roles set status='disabled',is_active=false,updated_at=now()
      where id=v_user_role_id and user_id=v_target_user_id and company_id is null;
    elsif v_role_id is not null then
      update public.user_roles set status='disabled',is_active=false,updated_at=now()
      where user_id=v_target_user_id and company_id is null and role_id=v_role_id;
    else
      raise exception using errcode='22023', message='role_identifier_required';
    end if;

  elsif v_action='replace_overrides' then
    select array_agg(value) into v_overlap
    from (
      select unnest(v_allow) value
      intersect
      select unnest(v_deny) value
    ) q;
    if coalesce(array_length(v_overlap,1),0)>0 then
      raise exception using errcode='23514', message='permission_allow_deny_overlap';
    end if;

    select array_agg(requested.permission_key order by requested.permission_key)
      into v_missing_permissions
    from (
      select distinct unnest(v_allow||v_deny) permission_key
    ) requested
    left join public.permissions p on p.key=requested.permission_key
    where p.id is null;
    if coalesce(array_length(v_missing_permissions,1),0)>0 then
      raise exception using errcode='22023', message='permission_not_found';
    end if;

    delete from public.user_permission_overrides
    where user_id=v_target_user_id and company_id is null;

    insert into public.user_permission_overrides(
      company_id,user_id,permission_key,effect,reason,is_active,created_by,updated_by,created_at,updated_at
    )
    select null,v_target_user_id,permission_key,'allow',v_reason,true,v_actor_user_id,v_actor_user_id,now(),now()
    from unnest(v_allow) permission_key
    union all
    select null,v_target_user_id,permission_key,'deny',v_reason,true,v_actor_user_id,v_actor_user_id,now(),now()
    from unnest(v_deny) permission_key;

  elsif v_action='clear_overrides' then
    delete from public.user_permission_overrides
    where user_id=v_target_user_id and company_id is null;

  elsif v_action='upsert_override' then
    if v_permission_key is null or v_effect not in ('allow','deny') then
      raise exception using errcode='22023', message='permission_key_and_valid_effect_required';
    end if;
    if not exists(select 1 from public.permissions where key=v_permission_key) then
      raise exception using errcode='22023', message='permission_not_found';
    end if;
    delete from public.user_permission_overrides
    where user_id=v_target_user_id and company_id is null and permission_key=v_permission_key;
    insert into public.user_permission_overrides(
      company_id,user_id,permission_key,effect,reason,is_active,created_by,updated_by,created_at,updated_at
    ) values(
      null,v_target_user_id,v_permission_key,v_effect,v_reason,true,v_actor_user_id,v_actor_user_id,now(),now()
    );

  elsif v_action='remove_override' then
    if v_permission_key is null then
      raise exception using errcode='22023', message='permission_key_required';
    end if;
    delete from public.user_permission_overrides
    where user_id=v_target_user_id and company_id is null and permission_key=v_permission_key;

  elsif v_action='disable_platform_access' then
    update public.user_roles
    set status='disabled',is_active=false,updated_at=now()
    where user_id=v_target_user_id and company_id is null and coalesce(is_active,true);
    delete from public.user_permission_overrides
    where user_id=v_target_user_id and company_id is null;
  end if;

  select jsonb_build_object(
    'roles',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',ur.id,'role_id',ur.role_id,'role',ur.role,
        'status',ur.status,'is_active',ur.is_active
      ) order by ur.created_at,ur.id)
      from public.user_roles ur
      where ur.user_id=v_target_user_id and ur.company_id is null
    ),'[]'::jsonb),
    'overrides',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',upo.id,'permission_key',upo.permission_key,'effect',upo.effect,
        'reason',upo.reason,'is_active',upo.is_active
      ) order by upo.permission_key,upo.id)
      from public.user_permission_overrides upo
      where upo.user_id=v_target_user_id and upo.company_id is null
    ),'[]'::jsonb)
  ) into v_after;

  v_result := jsonb_build_object(
    'changed',v_before is distinct from v_after,
    'target_user_id',v_target_user_id,
    'action',v_action,
    'state',v_after
  );

  insert into public.canonical_platform_access_audit_events(
    target_user_id,event_type,actor_user_id,idempotency_key,reason,before_state,after_state
  ) values(
    v_target_user_id,'PLATFORM_USER_ACCESS_CHANGED',v_actor_user_id,v_idempotency_key,v_reason,v_before,v_after
  );

  insert into public.canonical_platform_access_command_results(
    target_user_id,command_type,idempotency_key,request_hash,request_payload,result_payload,actor_user_id
  ) values(
    v_target_user_id,'platform.user_access.'||v_action,v_idempotency_key,v_hash,v_request,v_result,v_actor_user_id
  );

  return v_result;
end
$$;

--
-- Name: FUNCTION canonical_manage_platform_user_access(p_command jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.canonical_manage_platform_user_access(p_command jsonb) IS 'Atomic service-only platform-role and permission override command with actor validation, idempotency, and immutable audit.';

--
-- Name: canonical_onboard_customer_graph(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_onboard_customer_graph(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_command jsonb := coalesce(p_command, '{}'::jsonb);
  v_status text;
  v_has_signed_document boolean;
  v_has_catalog_offer boolean;
begin
  if v_command->>'channel' = 'admin' and jsonb_typeof(v_command->'contract') = 'object' then
    v_status := nullif(v_command#>>'{contract,status}', '');
    v_has_signed_document := coalesce((v_command#>>'{legal,acceptance_snapshot,signedAgreementUploaded}')::boolean, false);
    v_has_catalog_offer := nullif(v_command#>>'{contract,contract_offer_id}', '') is not null;

    -- A real signed document must be imported as evidence after the base graph
    -- exists. Direct signed/active INSERT is deliberately forbidden by the
    -- customer_contract state machine.
    if v_has_signed_document and v_status in ('signed', 'active') then
      v_command := jsonb_set(
        v_command,
        '{contract,status}',
        to_jsonb(case when v_has_catalog_offer then 'pending_signature' else 'draft' end),
        true
      );
      v_command := jsonb_set(v_command, '{contract,signed_at}', 'null'::jsonb, true);
    elsif not v_has_catalog_offer and v_status = 'pending_signature' then
      -- One-off/manual contracts need their exact canonical publication chain
      -- materialized before they can enter pending_signature.
      v_command := jsonb_set(v_command, '{contract,status}', '"draft"'::jsonb, true);
      v_command := jsonb_set(v_command, '{contract,signed_at}', 'null'::jsonb, true);
    end if;
  end if;

  return public.gridex_onboard_customer_graph(v_command);
end
$$;

--
-- Name: canonical_project_actor_test_result_state(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_project_actor_test_result_state(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_actor_user_id uuid := nullif(p_command->>'actor_user_id','')::uuid;
  v_company_id uuid := nullif(p_command->>'company_id','')::uuid;
  v_run_id uuid := nullif(p_command->>'test_run_id','')::uuid;
  v_test_case_code text := upper(nullif(btrim(p_command->>'test_case_code'),''));
  v_status text := lower(nullif(btrim(p_command->>'status'),''));
  v_idempotency_key text := nullif(btrim(p_command->>'idempotency_key'),'');
  v_request jsonb := p_command - 'actor_user_id';
  v_hash text;
  v_existing public.canonical_command_results%rowtype;
  v_authoritative public.actor_test_results%rowtype;
  v_result jsonb;
  v_event_id uuid;
begin
  if v_actor_user_id is null or v_company_id is null
     or v_test_case_code is null or v_idempotency_key is null then
    raise exception using errcode='22023', message='actor_company_case_and_idempotency_required';
  end if;
  if v_status not in ('running','failed','blocked') then
    raise exception using errcode='23514', message='authoritative_actor_test_status_requires_evidence_or_attestation';
  end if;
  if not public.gridex_actor_has_company_permission(
    v_actor_user_id,v_company_id,'ediel_testing.write'
  ) then
    raise exception using errcode='42501', message='ediel_testing_write_permission_denied';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('actor-test-projection:'||v_company_id::text||':'||v_test_case_code,0)
  );
  v_hash := public.canonical_json_sha256(v_request);

  select * into v_existing
  from public.canonical_command_results
  where company_id=v_company_id
    and command_type='ediel.test.projection.'||v_status
    and idempotency_key=v_idempotency_key;
  if found then
    if v_existing.request_hash is distinct from v_hash then
      raise exception using errcode='23505', message='IDEMPOTENCY_KEY_REUSE_MISMATCH';
    end if;
    return v_existing.result_payload;
  end if;

  if v_run_id is not null and not exists(
    select 1 from public.ediel_test_runs r
    where r.id=v_run_id and r.company_id=v_company_id
  ) then
    raise exception using errcode='23503', message='tenant_scoped_test_run_not_found';
  end if;

  select * into v_authoritative
  from public.actor_test_results
  where company_id=v_company_id and test_key=v_test_case_code
  for update;

  -- Preparing/syncing a fresh run is non-authoritative. Never downgrade a current
  -- machine/attested approval merely because the new attempt has entered running.
  -- Real failed/blocked outcomes still replace the approval and therefore remain fail-closed.
  if found
     and v_status='running'
     and v_authoritative.status in ('passed','manual_verified')
     and coalesce(v_authoritative.is_stale,false)=false then
    if v_run_id is not null then
      update public.ediel_test_runs
      set status='running', failure_reason=null, completed_at=null,
          updated_by=v_actor_user_id, updated_at=now()
      where id=v_run_id and company_id=v_company_id;
    end if;

    insert into public.canonical_audit_events(
      company_id,event_type,aggregate_type,aggregate_id,actor_user_id,reason,
      idempotency_key,after_state,metadata
    ) values(
      v_company_id,'EDIEL_TEST_PROJECTION_PRESERVED_AUTHORITATIVE','actor_test_result',
      coalesce(v_run_id,v_authoritative.id),v_actor_user_id,
      'Running projection preserved current authoritative actor-test approval.',
      v_idempotency_key,jsonb_build_object(
        'test_case_code',v_test_case_code,'status',v_authoritative.status,
        'attempted_status',v_status,'test_run_id',v_run_id,
        'authoritative_result_id',v_authoritative.id
      ),coalesce(p_command->'evidence','{}'::jsonb)
    );
    insert into public.canonical_domain_events(
      company_id,event_type,aggregate_type,aggregate_id,idempotency_key,payload,created_by
    ) values(
      v_company_id,'EDIEL_TEST_PROJECTION_PRESERVED_AUTHORITATIVE','actor_test_result',
      coalesce(v_run_id,v_authoritative.id),v_idempotency_key,
      jsonb_build_object(
        'test_case_code',v_test_case_code,'status',v_authoritative.status,
        'attempted_status',v_status,'test_run_id',v_run_id,
        'authoritative_result_id',v_authoritative.id
      ),v_actor_user_id
    ) returning id into v_event_id;
    insert into public.canonical_event_outbox(
      company_id,domain_event_id,topic,idempotency_key,payload
    ) values(
      v_company_id,v_event_id,'ediel.test.projection.preserved_authoritative',v_idempotency_key,
      jsonb_build_object(
        'test_case_code',v_test_case_code,'status',v_authoritative.status,
        'attempted_status',v_status,'test_run_id',v_run_id
      )
    );

    v_result:=jsonb_build_object(
      'changed',false,'preserved_authoritative',true,'company_id',v_company_id,
      'test_case_code',v_test_case_code,'status',v_authoritative.status,
      'attempted_status',v_status,'test_run_id',v_run_id,
      'authoritative_result_id',v_authoritative.id
    );
    insert into public.canonical_command_results(
      company_id,command_type,idempotency_key,request_hash,request_payload,result_payload,actor_user_id
    ) values(
      v_company_id,'ediel.test.projection.'||v_status,v_idempotency_key,v_hash,v_request,v_result,v_actor_user_id
    );
    return v_result;
  end if;

  insert into public.actor_test_results(
    company_id,test_key,test_name,test_id,package_key,message_family,message_code,direction,
    status,latest_run_at,passed_at,failure_reason,portal_status,raw_payload,
    ediel_test_run_id,evidence,is_stale,stale_reason,created_by,updated_by,created_at,updated_at
  ) values(
    v_company_id,v_test_case_code,nullif(p_command->>'test_name',''),nullif(p_command->>'test_id',''),
    nullif(p_command->>'package_key',''),nullif(p_command->>'message_family',''),
    nullif(p_command->>'message_code',''),nullif(p_command->>'direction',''),
    v_status,now(),null,nullif(p_command->>'failure_reason',''),nullif(p_command->>'portal_status',''),
    nullif(p_command->>'raw_payload',''),v_run_id,coalesce(p_command->'evidence','{}'::jsonb),
    false,null,v_actor_user_id,v_actor_user_id,now(),now()
  ) on conflict(company_id,test_key) do update set
    test_name=coalesce(excluded.test_name,public.actor_test_results.test_name),
    test_id=coalesce(excluded.test_id,public.actor_test_results.test_id),
    package_key=coalesce(excluded.package_key,public.actor_test_results.package_key),
    message_family=coalesce(excluded.message_family,public.actor_test_results.message_family),
    message_code=coalesce(excluded.message_code,public.actor_test_results.message_code),
    direction=coalesce(excluded.direction,public.actor_test_results.direction),
    status=excluded.status,latest_run_at=excluded.latest_run_at,passed_at=null,
    failure_reason=excluded.failure_reason,portal_status=excluded.portal_status,
    raw_payload=excluded.raw_payload,
    ediel_test_run_id=coalesce(excluded.ediel_test_run_id,public.actor_test_results.ediel_test_run_id),
    evidence=excluded.evidence,is_stale=false,stale_reason=null,
    updated_by=excluded.updated_by,updated_at=excluded.updated_at;

  if v_run_id is not null then
    update public.ediel_test_runs
    set status=case when v_status='running' then 'running' else 'failed' end,
        failure_reason=nullif(p_command->>'failure_reason',''),
        completed_at=case when v_status='running' then null else now() end,
        updated_by=v_actor_user_id,updated_at=now()
    where id=v_run_id and company_id=v_company_id;
  end if;

  insert into public.canonical_audit_events(
    company_id,event_type,aggregate_type,aggregate_id,actor_user_id,reason,
    idempotency_key,after_state,metadata
  ) values(
    v_company_id,'EDIEL_TEST_PROJECTION_UPDATED','actor_test_result',
    coalesce(v_run_id,v_company_id),v_actor_user_id,
    coalesce(nullif(p_command->>'failure_reason',''),'Non-authoritative actor-test projection updated'),
    v_idempotency_key,jsonb_build_object(
      'test_case_code',v_test_case_code,'status',v_status,'test_run_id',v_run_id
    ),coalesce(p_command->'evidence','{}'::jsonb)
  );
  insert into public.canonical_domain_events(
    company_id,event_type,aggregate_type,aggregate_id,idempotency_key,payload,created_by
  ) values(
    v_company_id,'EDIEL_TEST_PROJECTION_UPDATED','actor_test_result',
    coalesce(v_run_id,v_company_id),v_idempotency_key,
    jsonb_build_object('test_case_code',v_test_case_code,'status',v_status,'test_run_id',v_run_id),
    v_actor_user_id
  ) returning id into v_event_id;
  insert into public.canonical_event_outbox(
    company_id,domain_event_id,topic,idempotency_key,payload
  ) values(
    v_company_id,v_event_id,'ediel.test.projection.updated',v_idempotency_key,
    jsonb_build_object('test_case_code',v_test_case_code,'status',v_status,'test_run_id',v_run_id)
  );

  v_result:=jsonb_build_object(
    'changed',true,'company_id',v_company_id,'test_case_code',v_test_case_code,
    'status',v_status,'test_run_id',v_run_id
  );
  insert into public.canonical_command_results(
    company_id,command_type,idempotency_key,request_hash,request_payload,result_payload,actor_user_id
  ) values(
    v_company_id,'ediel.test.projection.'||v_status,v_idempotency_key,v_hash,v_request,v_result,v_actor_user_id
  );
  return v_result;
end
$$;

--
-- Name: canonical_provision_company(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_provision_company(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
declare
  v_result jsonb;
  v_company_id uuid;
  v_email text := lower(btrim(p_command->>'initial_admin_email'));
  v_token uuid;
  v_invitation_id uuid;
begin
  v_result := public.canonical_provision_company_v3_pre_invitation_intent(p_command);
  v_company_id := (v_result->>'company_id')::uuid;

  if nullif(v_email,'') is not null then
    v_token := gen_random_uuid();
    insert into public.company_invitations(
      company_id,email,full_name,membership_role,role_key,status,token,
      invited_by,expires_at,accept_token_hash,idempotency_key,metadata
    ) values (
      v_company_id,v_email,nullif(btrim(p_command->>'initial_admin_name'),''),
      'company_admin','company_admin','pending',v_token,
      nullif(p_command->>'actor_user_id','')::uuid,now()+interval '14 days',
      encode(digest(v_token::text,'sha256'),'hex'),
      (p_command->>'idempotency_key')||':initial-admin',
      jsonb_build_object(
        'invite_source','create_company_initial_admin',
        'access_source','verified_auth_invitation_link',
        'provider_delivery_status','pending'
      )
    )
    on conflict (company_id,idempotency_key) where idempotency_key is not null
    do update set updated_at=now()
    returning id into v_invitation_id;
  end if;

  return v_result || jsonb_build_object(
    'initial_admin_invitation_id',v_invitation_id,
    'external_delivery_queued',v_invitation_id is not null
  );
end
$$;

--
-- Name: canonical_provision_company_v1_unchecked(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_provision_company_v1_unchecked(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid:=nullif(p_command->>'company_id','')::uuid;
  v_actor_user_id uuid:=nullif(p_command->>'actor_user_id','')::uuid;
  v_idempotency_key text:=p_command->>'idempotency_key';
  v_existing jsonb;
  v_event_id uuid;
  v_result jsonb;
  v_job_key text;
begin
  if nullif(btrim(p_command->>'name'),'') is null
     or nullif(btrim(p_command->>'slug'),'') is null
     or nullif(btrim(v_idempotency_key),'') is null then
    raise exception 'name_slug_and_idempotency_key_required';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_idempotency_key,0));

  select result_payload into v_existing
  from public.canonical_provisioning_requests
  where idempotency_key=v_idempotency_key;
  if found and v_existing is not null then return v_existing; end if;
  if found then raise exception 'tenant_provisioning_request_in_progress'; end if;

  v_company_id:=coalesce(v_company_id,gen_random_uuid());

  insert into public.companies(
    id,name,slug,org_number,status,primary_contact_email,primary_contact_name,
    phone,website,industry,metadata,created_by,created_at,updated_at
  ) values (
    v_company_id,btrim(p_command->>'name'),lower(btrim(p_command->>'slug')),
    nullif(btrim(p_command->>'organization_number'),''),'onboarding',
    nullif(lower(btrim(p_command->>'primary_contact_email')),''),
    nullif(btrim(p_command->>'primary_contact_name'),''),
    nullif(btrim(p_command->>'phone'),''),nullif(btrim(p_command->>'website'),''),
    coalesce(nullif(btrim(p_command->>'industry'),''),'electricity_supplier'),
    coalesce(p_command->'metadata','{}'::jsonb)||jsonb_build_object('canonical_provisioning_idempotency_key',v_idempotency_key),
    v_actor_user_id,now(),now()
  );

  insert into public.canonical_provisioning_requests(idempotency_key,company_id,request_payload)
  values(v_idempotency_key,v_company_id,p_command);

  perform public.canonical_seed_company_capabilities(v_company_id);
  perform public.gridex_seed_company_onboarding_tasks(v_company_id);

  insert into public.company_onboarding_lifecycle(company_id,current_step,status)
  values(v_company_id,'created','in_progress')
  on conflict(company_id) do nothing;

  foreach v_job_key in array array[
    'legal_profile','email_configuration','capability_review','onboarding_tasks',
    'admin_access','auth_invite','ediel_configuration'
  ] loop
    insert into public.company_provisioning_jobs(company_id,job_key,idempotency_key)
    values(v_company_id,v_job_key,v_idempotency_key)
    on conflict do nothing;
  end loop;

  insert into public.canonical_audit_events(
    company_id,event_type,aggregate_type,aggregate_id,state_version,actor_user_id,
    reason,idempotency_key,after_state,metadata
  ) values (
    v_company_id,'TENANT_PROVISIONING_STARTED','company',v_company_id,0,v_actor_user_id,
    'Canonical tenant provisioning started.',v_idempotency_key,
    jsonb_build_object('status','onboarding'),p_command
  );
  insert into public.canonical_domain_events(
    company_id,event_type,aggregate_type,aggregate_id,aggregate_version,
    idempotency_key,payload,created_by
  ) values (
    v_company_id,'TENANT_PROVISIONING_STARTED','company',v_company_id,0,v_idempotency_key,
    jsonb_build_object('company_id',v_company_id,'status','onboarding'),v_actor_user_id
  ) returning id into v_event_id;
  insert into public.canonical_event_outbox(company_id,domain_event_id,topic,idempotency_key,payload)
  values(v_company_id,v_event_id,'tenant.provisioning.started',v_idempotency_key,
    jsonb_build_object('company_id',v_company_id));

  v_result:=jsonb_build_object('company_id',v_company_id,'status','onboarding','provisioning_started',true);
  insert into public.canonical_command_results(company_id,command_type,idempotency_key,request_payload,result_payload,actor_user_id)
  values(v_company_id,'tenant.provision',v_idempotency_key,p_command,v_result,v_actor_user_id);
  update public.canonical_provisioning_requests
  set result_payload=v_result,completed_at=now()
  where idempotency_key=v_idempotency_key;
  return v_result;
end;
$$;

--
-- Name: canonical_provision_company_v3_pre_invitation_intent(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_provision_company_v3_pre_invitation_intent(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actor_user_id uuid := nullif(p_command->>'actor_user_id', '')::uuid;
  v_idempotency_key text := p_command->>'idempotency_key';
  v_request jsonb := p_command - 'actor_user_id';
  v_hash text;
  v_existing public.canonical_provisioning_requests%rowtype;
  v_command jsonb := p_command;
  v_result jsonb;
  v_company_id uuid;
begin
  if not public.canonical_actor_is_platform_admin(v_actor_user_id) then
    raise exception 'actor_not_authorized_for_tenant_provisioning';
  end if;

  if nullif(btrim(v_idempotency_key), '') is null then
    raise exception 'idempotency_key_required';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('tenant.provision:' || v_idempotency_key, 0)
  );

  v_hash := public.canonical_json_sha256(v_request);

  select *
  into v_existing
  from public.canonical_provisioning_requests
  where idempotency_key = v_idempotency_key;

  if found then
    if v_existing.request_hash is distinct from v_hash then
      raise exception 'idempotency_key_payload_mismatch';
    end if;
    if v_existing.result_payload is null then
      raise exception 'tenant_provisioning_request_in_progress';
    end if;
    return v_existing.result_payload;
  end if;

  if nullif(v_command->>'company_id', '') is null then
    v_command := v_command || jsonb_build_object('company_id', gen_random_uuid());
  end if;

  v_result := public.canonical_provision_company_v1_unchecked(v_command);
  v_company_id := (v_result->>'company_id')::uuid;

  update public.companies
  set customer_number_prefix = nullif(upper(v_command->>'customer_number_prefix'), ''),
      updated_at = now()
  where id = v_company_id;

  update public.canonical_provisioning_requests
  set request_payload = v_request,
      request_hash = v_hash
  where idempotency_key = v_idempotency_key;

  update public.canonical_command_results
  set request_payload = v_request,
      request_hash = v_hash
  where company_id = v_company_id
    and command_type = 'tenant.provision'
    and idempotency_key = v_idempotency_key;

  return v_result;
end;
$$;

--
-- Name: FUNCTION canonical_provision_company_v3_pre_invitation_intent(p_command jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.canonical_provision_company_v3_pre_invitation_intent(p_command jsonb) IS 'Canonical tenant provisioning wrapper with platform authorization and request-bound idempotency; binds normalized request payload and hash atomically.';

--
-- Name: canonical_queue_customer_application_repair(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_queue_customer_application_repair(p_application_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  application public.website_customer_applications%rowtype;
  v_missing text[] := '{}'::text[];
  v_workflow_id uuid;
  v_job_id uuid;
begin
  select * into application
  from public.website_customer_applications
  where id=p_application_id
  for update;
  if not found then raise exception 'customer_application_not_found'; end if;
  if not public.canonical_actor_is_platform_admin(p_actor_user_id) then
    raise exception using errcode='42501',message='platform_admin_required';
  end if;

  if application.customer_id is null then v_missing:=array_append(v_missing,'customer_id'); end if;
  if application.api_client_id is null then v_missing:=array_append(v_missing,'api_client_id'); end if;
  if nullif(application.payload->>'auth_user_id','') is null then
    v_missing:=array_append(v_missing,'auth_user_id');
  end if;
  if nullif(application.payload->>'customer_portal_user_id','') is null then
    v_missing:=array_append(v_missing,'customer_portal_user_id');
  end if;

  if cardinality(v_missing)>0 then
    update public.website_customer_applications
    set repair_status='awaiting_input',
        repair_owner_user_id=p_actor_user_id,
        repair_reason_code='canonical_repair_input_missing',
        repair_attempts=repair_attempts+1,
        last_repair_at=now(),
        updated_at=now()
    where id=p_application_id;
    return jsonb_build_object(
      'queued',false,
      'status','awaiting_input',
      'missing_fields',to_jsonb(v_missing)
    );
  end if;

  insert into public.customer_application_workflows(
    company_id,customer_application_id,customer_id,customer_site_id,
    metering_point_id,state,snapshot,next_action
  ) values (
    application.company_id,application.id,application.customer_id,
    application.customer_site_id,application.metering_point_id,
    'received',coalesce(application.payload,'{}'::jsonb),'canonical_repair_retry'
  )
  on conflict(company_id,customer_application_id) do update
  set next_action='canonical_repair_retry',updated_at=now()
  returning id into v_workflow_id;

  insert into public.customer_operation_jobs(
    company_id,customer_id,customer_site_id,metering_point_id,
    job_type,status,idempotency_key,payload,created_by,workflow_id,request_snapshot
  ) values (
    application.company_id,application.customer_id,application.customer_site_id,
    application.metering_point_id,'customer_application_continuation','queued',
    'canonical-repair:'||application.id,
    jsonb_build_object('customer_application_id',application.id,'repair',true),
    p_actor_user_id,v_workflow_id,coalesce(application.payload,'{}'::jsonb)
  )
  on conflict do nothing
  returning id into v_job_id;

  if v_job_id is null then
    select id into v_job_id
    from public.customer_operation_jobs
    where company_id=application.company_id
      and workflow_id=v_workflow_id
      and job_type='customer_application_continuation'
    order by created_at desc
    limit 1;
  end if;
  if v_job_id is null then raise exception 'canonical_repair_job_not_created'; end if;

  update public.customer_application_workflows
  set last_job_id=v_job_id,updated_at=now()
  where id=v_workflow_id;

  update public.website_customer_applications
  set repair_status='ready_to_retry',
      repair_owner_user_id=p_actor_user_id,
      repair_reason_code=null,
      repair_attempts=repair_attempts+1,
      last_repair_at=now(),
      next_step='canonical_repair_retry',
      updated_at=now()
  where id=p_application_id;

  return jsonb_build_object(
    'queued',true,
    'status','ready_to_retry',
    'missing_fields','[]'::jsonb,
    'workflow_id',v_workflow_id,
    'job_id',v_job_id
  );
end
$$;

--
-- Name: canonical_record_actor_test_evidence(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_record_actor_test_evidence(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid:=(p_command->>'company_id')::uuid;
  v_run_id uuid:=(p_command->>'test_run_id')::uuid;
  v_actor_user_id uuid:=nullif(p_command->>'actor_user_id','')::uuid;
  v_test_case_code text:=upper(coalesce(p_command->>'test_case_code',p_command->>'test_case_key'));
  v_idempotency_key text:=p_command->>'idempotency_key';
  v_run public.ediel_test_runs%rowtype;
  v_snapshot public.ediel_configuration_snapshots%rowtype;
  v_test_case public.ediel_test_cases%rowtype;
  v_source public.ediel_messages%rowtype;
  v_contrl public.ediel_messages%rowtype;
  v_aperak public.ediel_messages%rowtype;
  v_utilts_err public.ediel_messages%rowtype;
  v_final_aperak public.ediel_messages%rowtype;
  v_actor_role text;
  v_expected_direction text;
  v_portal_ediel_id text;
  v_definition_count integer;
  v_source_count integer;
  v_match_count integer;
  v_step_count integer;
  v_attempt_id uuid;
  v_evidence jsonb;
  v_evidence_digest text;
  v_existing jsonb;
  v_result jsonb;
  v_event_id uuid;
begin
  if v_company_id is null or v_run_id is null or v_actor_user_id is null
     or nullif(v_test_case_code,'') is null
     or nullif(btrim(v_idempotency_key),'') is null then
    raise exception 'company_run_case_actor_and_idempotency_required';
  end if;

  if not public.gridex_actor_has_company_permission(
    v_actor_user_id,v_company_id,'ediel_testing.write'
  ) then
    raise exception using errcode='42501',message='ediel_testing_write_permission_denied';
  end if;

  select result_payload into v_existing from public.canonical_command_results
  where company_id=v_company_id and command_type='ediel.test.evidence.record' and idempotency_key=v_idempotency_key;
  if found then return v_existing; end if;

  select * into v_run from public.ediel_test_runs
  where id=v_run_id and company_id=v_company_id for update;
  if not found then raise exception 'tenant_scoped_test_run_not_found'; end if;
  if v_run.environment_type='production'::public.ediel_environment_type
     or lower(coalesce(v_run.environment,''))<>'test' then
    raise exception 'production_or_conflicting_run_cannot_be_test_evidence';
  end if;
  if upper(v_run.test_case_code)<>v_test_case_code then raise exception 'test_case_does_not_match_run'; end if;
  if nullif(btrim(v_run.test_suite),'') is null
     or nullif(btrim(v_run.setup_package),'') is null
     or nullif(btrim(v_run.message_family),'') is null
     or nullif(btrim(v_run.rulebook_version),'') is null then
    raise exception 'test_run_canonical_identity_incomplete';
  end if;

  v_actor_role:=case lower(coalesce(nullif(v_run.actor_role,''),v_run.role_code))
    when 'supplier' then 'supplier'
    when 'esco' then 'energy_service_company'
    when 'energy_service_company' then 'energy_service_company'
    else null
  end;
  if v_actor_role is null then raise exception 'unknown_actor_role_blocks_evidence'; end if;
  if lower(v_run.role_code) not in ('supplier','esco','energy_service_company') then
    raise exception 'unknown_role_code_blocks_evidence';
  end if;

  select count(*) into v_definition_count
  from public.ediel_test_cases tc
  where upper(tc.test_case_code)=v_test_case_code
    and tc.is_active
    and lower(tc.actor_role)=v_actor_role
    and upper(tc.message_family)=upper(v_run.message_family)
    and (
      (v_run.environment_type='agt_test'::public.ediel_environment_type and left(upper(tc.suite_key),4)='AGT_')
      or (v_run.environment_type='tgt_test'::public.ediel_environment_type and left(upper(tc.suite_key),4)='TGT_')
      or v_run.environment_type='bilateral_test'::public.ediel_environment_type
    );
  if v_definition_count<>1 then raise exception 'canonical_test_definition_missing_or_ambiguous'; end if;

  select * into strict v_test_case
  from public.ediel_test_cases tc
  where upper(tc.test_case_code)=v_test_case_code
    and tc.is_active
    and lower(tc.actor_role)=v_actor_role
    and upper(tc.message_family)=upper(v_run.message_family)
    and (
      (v_run.environment_type='agt_test'::public.ediel_environment_type and left(upper(tc.suite_key),4)='AGT_')
      or (v_run.environment_type='tgt_test'::public.ediel_environment_type and left(upper(tc.suite_key),4)='TGT_')
      or v_run.environment_type='bilateral_test'::public.ediel_environment_type
    );

  if v_test_case.rule_version is null
     or v_test_case.rule_version<>v_run.rulebook_version then
    raise exception 'test_definition_rulebook_does_not_match_run';
  end if;
  if v_test_case.subtype is not null
     and upper(coalesce(v_run.message_variant,''))<>upper(v_test_case.subtype) then
    raise exception 'message_variant_does_not_match_test_definition';
  end if;
  if v_run.configuration_snapshot_id is null then raise exception 'test_run_configuration_snapshot_required'; end if;
  select * into v_snapshot from public.ediel_configuration_snapshots
  where id=v_run.configuration_snapshot_id and company_id=v_company_id;
  if not found then raise exception 'test_run_snapshot_not_found_for_tenant'; end if;
  if v_run.configuration_hash is distinct from v_snapshot.configuration_hash then
    raise exception 'test_run_snapshot_hash_mismatch';
  end if;
  if coalesce(v_run.is_stale,false) then raise exception 'stale_test_run_cannot_pass'; end if;

  if not exists(
    select 1 from public.ediel_active_test_configurations c
    where c.company_id=v_company_id and c.environment='test' and c.status='active'
      and c.configuration_snapshot_id=v_snapshot.id
      and c.test_suite=v_run.test_suite
      and lower(c.actor_role)=v_actor_role
      and upper(c.message_family)=upper(v_run.message_family)
      and c.setup_package=v_run.setup_package
  ) then raise exception 'run_snapshot_is_not_current_active_test_configuration'; end if;

  select route->>'receiver_ediel_id' into v_portal_ediel_id
  from jsonb_array_elements(coalesce(v_snapshot.payload->'routes','[]'::jsonb)) route
  where route->>'id'=v_snapshot.primary_test_route_id::text
    and lower(coalesce(route->>'environment','test'))='test'
    and coalesce((route->>'is_active')::boolean,true)
    and coalesce((route->>'is_enabled')::boolean,true)
  limit 1;
  if nullif(btrim(v_snapshot.test_ediel_id),'') is null
     or nullif(btrim(v_portal_ediel_id),'') is null then
    raise exception 'snapshot_test_actor_or_portal_identity_missing';
  end if;

  v_expected_direction:=case lower(v_test_case.direction)
    when 'actor_to_portal' then 'outbound'
    when 'portal_to_actor' then 'inbound'
    when 'inbound' then 'inbound'
    when 'outbound' then 'outbound'
    else null
  end;
  if v_expected_direction is null then raise exception 'unknown_test_direction_blocks_evidence'; end if;
  if upper(v_test_case.message_family)='UTILTS' and v_expected_direction<>'inbound' then
    raise exception 'unsupported_outbound_utilts_definition_requires_canonical_steps';
  end if;

  select count(*) into v_source_count
  from public.ediel_test_run_messages trm
  join public.ediel_messages m
    on m.id=trm.ediel_message_id and m.company_id=trm.company_id
  where trm.company_id=v_company_id and trm.test_run_id=v_run_id
    and m.environment='test' and m.test_flag=1
    and m.created_at>=coalesce(v_run.started_at,v_run.created_at)
    and m.direction=v_expected_direction
    and upper(m.message_family)=upper(v_test_case.message_family)
    and upper(coalesce(m.message_code,''))=upper(v_test_case.message_code)
    and (v_test_case.subtype is null or upper(coalesce(m.message_subtype,''))=upper(v_test_case.subtype))
    and (
      (v_expected_direction='outbound' and m.sender_ediel_id=v_snapshot.test_ediel_id and m.receiver_ediel_id=v_portal_ediel_id)
      or (v_expected_direction='inbound' and m.sender_ediel_id=v_portal_ediel_id and m.receiver_ediel_id=v_snapshot.test_ediel_id)
    );
  if v_source_count<>1 then raise exception 'source_message_missing_or_ambiguous'; end if;

  select m.* into strict v_source
  from public.ediel_test_run_messages trm
  join public.ediel_messages m
    on m.id=trm.ediel_message_id and m.company_id=trm.company_id
  where trm.company_id=v_company_id and trm.test_run_id=v_run_id
    and m.environment='test' and m.test_flag=1
    and m.created_at>=coalesce(v_run.started_at,v_run.created_at)
    and m.direction=v_expected_direction
    and upper(m.message_family)=upper(v_test_case.message_family)
    and upper(coalesce(m.message_code,''))=upper(v_test_case.message_code)
    and (v_test_case.subtype is null or upper(coalesce(m.message_subtype,''))=upper(v_test_case.subtype))
    and (
      (v_expected_direction='outbound' and m.sender_ediel_id=v_snapshot.test_ediel_id and m.receiver_ediel_id=v_portal_ediel_id)
      or (v_expected_direction='inbound' and m.sender_ediel_id=v_portal_ediel_id and m.receiver_ediel_id=v_snapshot.test_ediel_id)
    );
  if v_source.direction='outbound'
     and v_source.status not in ('provider_accepted','sent','delivered','acknowledged') then
    raise exception 'source_message_has_no_strict_transport_acceptance';
  end if;
  if v_test_case_code='UL2' and upper(coalesce(v_source.measurement_resolution,''))<>'KVART' then
    raise exception 'ul2_requires_kvart_resolution';
  end if;
  if v_test_case_code='UL3' and upper(coalesce(v_source.measurement_resolution,''))<>'SCH' then
    raise exception 'ul3_requires_sch_resolution';
  end if;

  select count(*) into v_step_count from public.ediel_test_steps where test_case_id=v_test_case.id;

  select count(*) into v_match_count
  from public.ediel_test_run_messages trm join public.ediel_messages m
    on m.id=trm.ediel_message_id and m.company_id=trm.company_id
  where trm.company_id=v_company_id and trm.test_run_id=v_run_id
    and upper(m.message_family)='CONTRL' and m.related_message_id=v_source.id
    and m.environment='test' and m.test_flag=1
    and (lower(v_test_case.expected_contrl)='not_expected' or m.ack_outcome=lower(v_test_case.expected_contrl))
    and ((v_source.direction='outbound' and m.direction='inbound' and m.sender_ediel_id=v_portal_ediel_id)
      or (v_source.direction='inbound' and m.direction='outbound' and m.receiver_ediel_id=v_portal_ediel_id
        and m.status in ('provider_accepted','sent','delivered','acknowledged')));
  if lower(v_test_case.expected_contrl)='depends' then raise exception 'ambiguous_contrl_definition_blocks_pass'; end if;
  if lower(v_test_case.expected_contrl)='not_expected' then
    if v_match_count<>0 then raise exception 'unexpected_contrl_message'; end if;
  elsif v_match_count<>1 then raise exception 'expected_contrl_missing_or_ambiguous';
  else
    select m.* into strict v_contrl
    from public.ediel_test_run_messages trm join public.ediel_messages m
      on m.id=trm.ediel_message_id and m.company_id=trm.company_id
    where trm.company_id=v_company_id and trm.test_run_id=v_run_id
      and upper(m.message_family)='CONTRL' and m.related_message_id=v_source.id
      and m.environment='test' and m.test_flag=1 and m.ack_outcome=lower(v_test_case.expected_contrl)
      and ((v_source.direction='outbound' and m.direction='inbound' and m.sender_ediel_id=v_portal_ediel_id)
        or (v_source.direction='inbound' and m.direction='outbound' and m.receiver_ediel_id=v_portal_ediel_id
          and m.status in ('provider_accepted','sent','delivered','acknowledged')));
  end if;

  if lower(v_test_case.expected_aperak)='depends' then
    raise exception 'ambiguous_aperak_definition_blocks_pass';
  end if;
  select count(*) into v_match_count
  from public.ediel_test_run_messages trm join public.ediel_messages m
    on m.id=trm.ediel_message_id and m.company_id=trm.company_id
  where trm.company_id=v_company_id and trm.test_run_id=v_run_id
    and upper(m.message_family)='APERAK' and m.related_message_id=v_source.id
    and m.environment='test' and m.test_flag=1
    and (lower(v_test_case.expected_aperak)='not_expected' or m.ack_outcome=lower(v_test_case.expected_aperak))
    and ((v_source.direction='outbound' and m.direction='inbound' and m.sender_ediel_id=v_portal_ediel_id)
      or (v_source.direction='inbound' and m.direction='outbound' and m.receiver_ediel_id=v_portal_ediel_id
        and m.status in ('provider_accepted','sent','delivered','acknowledged')));
  if lower(v_test_case.expected_aperak)='not_expected' then
    if v_match_count<>0 then raise exception 'unexpected_aperak_message'; end if;
  elsif v_match_count<>1 then raise exception 'expected_aperak_missing_or_ambiguous';
  else
    select m.* into strict v_aperak
    from public.ediel_test_run_messages trm join public.ediel_messages m
      on m.id=trm.ediel_message_id and m.company_id=trm.company_id
    where trm.company_id=v_company_id and trm.test_run_id=v_run_id
      and upper(m.message_family)='APERAK' and m.related_message_id=v_source.id
      and m.environment='test' and m.test_flag=1 and m.ack_outcome=lower(v_test_case.expected_aperak)
      and ((v_source.direction='outbound' and m.direction='inbound' and m.sender_ediel_id=v_portal_ediel_id)
        or (v_source.direction='inbound' and m.direction='outbound' and m.receiver_ediel_id=v_portal_ediel_id
          and m.status in ('provider_accepted','sent','delivered','acknowledged')));
  end if;

  if upper(v_test_case.message_family)='UTILTS' then
    if lower(v_test_case.expected_utilts_err) not in ('expected','positive','negative') then
      raise exception 'utilts_full_chain_requires_explicit_utilts_err_definition';
    end if;
    select count(*) into v_match_count
    from public.ediel_test_run_messages trm join public.ediel_messages m
      on m.id=trm.ediel_message_id and m.company_id=trm.company_id
    where trm.company_id=v_company_id and trm.test_run_id=v_run_id
      and upper(m.message_family)='UTILTS_ERR' and m.related_message_id=v_source.id
      and m.direction='outbound' and m.environment='test' and m.test_flag=1
      and m.receiver_ediel_id=v_portal_ediel_id
      and m.status in ('provider_accepted','sent','delivered','acknowledged');
    if v_match_count<>1 then raise exception 'expected_utilts_err_missing_or_ambiguous'; end if;
    select m.* into strict v_utilts_err
    from public.ediel_test_run_messages trm join public.ediel_messages m
      on m.id=trm.ediel_message_id and m.company_id=trm.company_id
    where trm.company_id=v_company_id and trm.test_run_id=v_run_id
      and upper(m.message_family)='UTILTS_ERR' and m.related_message_id=v_source.id
      and m.direction='outbound' and m.environment='test' and m.test_flag=1
      and m.receiver_ediel_id=v_portal_ediel_id
      and m.status in ('provider_accepted','sent','delivered','acknowledged');

    select count(*) into v_match_count
    from public.ediel_test_run_messages trm join public.ediel_messages m
      on m.id=trm.ediel_message_id and m.company_id=trm.company_id
    where trm.company_id=v_company_id and trm.test_run_id=v_run_id
      and upper(m.message_family)='APERAK' and m.related_message_id=v_utilts_err.id
      and m.direction='inbound' and m.environment='test' and m.test_flag=1
      and m.sender_ediel_id=v_portal_ediel_id and m.receiver_ediel_id=v_snapshot.test_ediel_id;
    if v_match_count<>1 then raise exception 'final_portal_aperak_missing_or_ambiguous'; end if;
    select m.* into strict v_final_aperak
    from public.ediel_test_run_messages trm join public.ediel_messages m
      on m.id=trm.ediel_message_id and m.company_id=trm.company_id
    where trm.company_id=v_company_id and trm.test_run_id=v_run_id
      and upper(m.message_family)='APERAK' and m.related_message_id=v_utilts_err.id
      and m.direction='inbound' and m.environment='test' and m.test_flag=1
      and m.sender_ediel_id=v_portal_ediel_id and m.receiver_ediel_id=v_snapshot.test_ediel_id;
  elsif lower(v_test_case.expected_utilts_err)<>'not_expected' then
    raise exception 'non_utilts_case_has_invalid_utilts_err_expectation';
  end if;

  v_evidence:=jsonb_build_object(
    'verification','server_derived',
    'test_case_code',v_test_case_code,
    'test_definition_id',v_test_case.id,
    'expected_step_count',v_step_count,
    'source_message_id',v_source.id,
    'contrl_message_id',v_contrl.id,
    'aperak_message_id',v_aperak.id,
    'utilts_err_message_id',v_utilts_err.id,
    'final_aperak_message_id',v_final_aperak.id,
    'portal_ediel_id',v_portal_ediel_id,
    'configuration_snapshot_id',v_snapshot.id,
    'configuration_hash',v_snapshot.configuration_hash,
    'rulebook_version',v_run.rulebook_version
  );
  v_evidence_digest:=encode(extensions.digest(convert_to(v_evidence::text,'utf8'),'sha256'::text),'hex');

  insert into public.actor_test_attempts(
    company_id,test_run_id,test_case_code,environment_type,actor_role,role_code,
    test_suite,setup_package,message_family,message_variant,status,machine_verified,
    configuration_snapshot_id,configuration_hash,rulebook_version,engine_version,
    started_at,completed_at,evidence_digest,created_by
  ) values (
    v_company_id,v_run_id,v_test_case_code,v_run.environment_type,v_actor_role,v_run.role_code,
    v_run.test_suite,v_run.setup_package,upper(v_run.message_family),v_run.message_variant,'passed',true,
    v_snapshot.id,v_snapshot.configuration_hash,coalesce(v_run.rulebook_version,'unknown'),
    v_run.engine_version,coalesce(v_run.started_at,v_run.created_at),now(),v_evidence_digest,v_actor_user_id
  ) returning id into v_attempt_id;

  insert into public.actor_test_attempt_evidence(
    company_id,attempt_id,test_run_id,ediel_message_id,evidence_role,source_message_id,
    correlation_snapshot,transport_status_snapshot,message_hash,configuration_snapshot_id
  )
  select v_company_id,v_attempt_id,v_run_id,m.id,e.role,v_source.id,
    jsonb_build_object(
      'related_message_id',m.related_message_id,'original_message_id',m.original_message_id,
      'original_transaction_id',m.original_transaction_id,'interchange_reference',m.interchange_reference,
      'message_reference',m.message_reference,'transaction_reference',m.transaction_reference,
      'sender_ediel_id',m.sender_ediel_id,'receiver_ediel_id',m.receiver_ediel_id,'ack_outcome',m.ack_outcome
    ),coalesce(m.status,'unknown'),
    coalesce(m.raw_payload_hash,encode(extensions.digest(convert_to(coalesce(m.raw_payload,''),'utf8'),'sha256'::text),'hex')),
    v_snapshot.id
  from (values
    (v_source.id,'source_message'::text),(v_source.id,'portal_identity'::text),
    (v_source.id,'transport_acceptance'::text),
    (v_contrl.id,case when v_contrl.ack_outcome='negative' then 'negative_contrl' else 'positive_contrl' end),
    (v_aperak.id,case when v_aperak.ack_outcome='negative' then 'negative_aperak' else 'positive_aperak' end),
    (case when upper(v_test_case.message_family)='UTILTS' then v_source.id end,'utilts_inbound'::text),
    (v_utilts_err.id,'utilts_error_outbound'::text),(v_final_aperak.id,'final_portal_aperak'::text)
  ) e(message_id,role)
  join public.ediel_messages m on m.id=e.message_id and m.company_id=v_company_id
  where e.message_id is not null;

  insert into public.actor_test_results(
    company_id,test_key,test_name,test_id,package_key,message_family,message_code,direction,
    status,latest_run_at,passed_at,failure_reason,portal_status,raw_payload,
    ediel_test_run_id,contrl_message_id,aperak_message_id,utilts_err_message_id,
    evidence,configuration_snapshot_id,configuration_hash,is_stale,stale_reason,
    created_by,updated_by,created_at,updated_at
  ) values (
    v_company_id,v_test_case_code,coalesce(v_test_case.name,v_test_case.title),null,v_run.setup_package,
    v_test_case.message_family,v_test_case.message_code,v_test_case.direction,
    'passed',now(),now(),null,'Canonical serververifierad evidenskedja.',null,
    v_run_id,v_contrl.id,v_aperak.id,v_utilts_err.id,
    v_evidence,v_snapshot.id,v_snapshot.configuration_hash,false,null,
    v_actor_user_id,v_actor_user_id,now(),now()
  ) on conflict(company_id,test_key) do update set
    status='passed',latest_run_at=excluded.latest_run_at,passed_at=excluded.passed_at,
    failure_reason=null,portal_status=excluded.portal_status,raw_payload=excluded.raw_payload,
    ediel_test_run_id=excluded.ediel_test_run_id,contrl_message_id=excluded.contrl_message_id,
    aperak_message_id=excluded.aperak_message_id,utilts_err_message_id=excluded.utilts_err_message_id,
    evidence=excluded.evidence,configuration_snapshot_id=excluded.configuration_snapshot_id,
    configuration_hash=excluded.configuration_hash,is_stale=false,stale_reason=null,
    updated_by=excluded.updated_by,updated_at=excluded.updated_at;

  update public.ediel_test_runs set status='passed',completed_at=now(),failure_reason=null,updated_by=v_actor_user_id,updated_at=now()
  where id=v_run_id and company_id=v_company_id;

  insert into public.canonical_audit_events(
    company_id,event_type,aggregate_type,aggregate_id,actor_user_id,reason,idempotency_key,after_state,metadata
  ) values (
    v_company_id,'EDIEL_TEST_ATTEMPT_COMPLETED','actor_test_attempt',v_attempt_id,v_actor_user_id,
    'Maskinverifierad komplett evidenskedja.',v_idempotency_key,
    jsonb_build_object('status','passed','machine_verified',true,'configuration_snapshot_id',v_snapshot.id),v_evidence
  );
  insert into public.canonical_domain_events(
    company_id,event_type,aggregate_type,aggregate_id,idempotency_key,payload,created_by
  ) values (
    v_company_id,'EDIEL_TEST_ATTEMPT_COMPLETED','actor_test_attempt',v_attempt_id,v_idempotency_key,
    jsonb_build_object('test_run_id',v_run_id,'test_case_code',v_test_case_code,'status','passed',
      'configuration_snapshot_id',v_snapshot.id,'evidence_digest',v_evidence_digest),v_actor_user_id
  ) returning id into v_event_id;
  insert into public.canonical_event_outbox(company_id,domain_event_id,topic,idempotency_key,payload)
  values(v_company_id,v_event_id,'ediel.test.attempt.completed',v_idempotency_key,
    jsonb_build_object('attempt_id',v_attempt_id,'test_run_id',v_run_id,'status','passed'));

  v_result:=jsonb_build_object('attempt_id',v_attempt_id,'status','passed','machine_verified',true,
    'configuration_snapshot_id',v_snapshot.id,'evidence_digest',v_evidence_digest);
  insert into public.canonical_command_results(company_id,command_type,idempotency_key,request_payload,result_payload,actor_user_id)
  values(v_company_id,'ediel.test.evidence.record',v_idempotency_key,p_command,v_result,v_actor_user_id);
  return v_result;
end;
$$;

--
-- Name: canonical_record_platform_release_receipt(text, text, text, text, text, text, text, text, text, text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_record_platform_release_receipt(p_release_sha text, p_ci_run_id text, p_deployment_id text, p_environment text, p_schema_migration_version text, p_migration_manifest_hash text, p_database_schema_fingerprint text, p_generated_types_hash text, p_openapi_contract_version text, p_openapi_hash text, p_reconciliation_result jsonb, p_performance_evidence jsonb, p_evidence jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_id uuid;
begin
  if nullif(btrim(coalesce(p_release_sha, '')), '') is null
     or nullif(btrim(coalesce(p_ci_run_id, '')), '') is null
     or nullif(btrim(coalesce(p_deployment_id, '')), '') is null
     or nullif(btrim(coalesce(p_schema_migration_version, '')), '') is null
     or nullif(btrim(coalesce(p_migration_manifest_hash, '')), '') is null
     or nullif(btrim(coalesce(p_database_schema_fingerprint, '')), '') is null
     or nullif(btrim(coalesce(p_generated_types_hash, '')), '') is null
     or nullif(btrim(coalesce(p_openapi_contract_version, '')), '') is null
     or nullif(btrim(coalesce(p_openapi_hash, '')), '') is null then
    raise exception using
      errcode = '22023',
      message = 'release_identity_incomplete';
  end if;

  if p_environment not in ('development', 'preview', 'staging', 'production') then
    raise exception using
      errcode = '22023',
      message = 'release_environment_invalid';
  end if;

  if jsonb_typeof(coalesce(p_reconciliation_result, 'null'::jsonb)) <> 'object' then
    raise exception using
      errcode = '22023',
      message = 'release_reconciliation_result_required';
  end if;

  if jsonb_typeof(coalesce(p_performance_evidence, 'null'::jsonb)) <> 'object' then
    raise exception using
      errcode = '22023',
      message = 'release_performance_evidence_required';
  end if;

  if jsonb_typeof(coalesce(p_evidence, '{}'::jsonb)) <> 'object' then
    raise exception using
      errcode = '22023',
      message = 'release_evidence_must_be_object';
  end if;

  insert into public.platform_release_receipts(
    release_sha,
    ci_run_id,
    deployment_id,
    environment,
    schema_migration_version,
    status,
    evidence,
    recorded_by,
    recorded_at,
    verified_at,
    migration_manifest_hash,
    database_schema_fingerprint,
    generated_types_hash,
    openapi_contract_version,
    openapi_hash,
    reconciliation_result,
    performance_evidence
  )
  values (
    btrim(p_release_sha),
    btrim(p_ci_run_id),
    btrim(p_deployment_id),
    p_environment,
    btrim(p_schema_migration_version),
    'verified',
    coalesce(p_evidence, '{}'::jsonb),
    auth.uid(),
    now(),
    now(),
    btrim(p_migration_manifest_hash),
    btrim(p_database_schema_fingerprint),
    btrim(p_generated_types_hash),
    btrim(p_openapi_contract_version),
    btrim(p_openapi_hash),
    p_reconciliation_result,
    p_performance_evidence
  )
  on conflict(environment, release_sha, schema_migration_version) do update
  set ci_run_id = excluded.ci_run_id,
      deployment_id = excluded.deployment_id,
      status = 'verified',
      evidence = excluded.evidence,
      verified_at = now(),
      migration_manifest_hash = excluded.migration_manifest_hash,
      database_schema_fingerprint = excluded.database_schema_fingerprint,
      generated_types_hash = excluded.generated_types_hash,
      openapi_contract_version = excluded.openapi_contract_version,
      openapi_hash = excluded.openapi_hash,
      reconciliation_result = excluded.reconciliation_result,
      performance_evidence = excluded.performance_evidence
  where public.platform_release_receipts.status in ('candidate', 'verified')
  returning id into v_id;

  if v_id is null then
    raise exception using
      errcode = '22023',
      message = 'release_receipt_not_reverifiable';
  end if;

  return v_id;
end
$$;

--
-- Name: FUNCTION canonical_record_platform_release_receipt(p_release_sha text, p_ci_run_id text, p_deployment_id text, p_environment text, p_schema_migration_version text, p_migration_manifest_hash text, p_database_schema_fingerprint text, p_generated_types_hash text, p_openapi_contract_version text, p_openapi_hash text, p_reconciliation_result jsonb, p_performance_evidence jsonb, p_evidence jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.canonical_record_platform_release_receipt(p_release_sha text, p_ci_run_id text, p_deployment_id text, p_environment text, p_schema_migration_version text, p_migration_manifest_hash text, p_database_schema_fingerprint text, p_generated_types_hash text, p_openapi_contract_version text, p_openapi_hash text, p_reconciliation_result jsonb, p_performance_evidence jsonb, p_evidence jsonb) IS 'Service-role-only idempotent release evidence writer. Failed or superseded receipts cannot be overwritten as verified.';

--
-- Name: canonical_request_actor_test_attestation(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_request_actor_test_attestation(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid:=(p_command->>'company_id')::uuid;
  v_run_id uuid:=(p_command->>'test_run_id')::uuid;
  v_actor_user_id uuid:=nullif(p_command->>'actor_user_id','')::uuid;
  v_test_case_code text:=upper(coalesce(p_command->>'test_case_code',p_command->>'test_case_key'));
  v_reason text:=nullif(btrim(p_command->>'reason'),'');
  v_evidence_reference text:=nullif(btrim(p_command->>'evidence_reference'),'');
  v_idempotency_key text:=p_command->>'idempotency_key';
  v_run public.ediel_test_runs%rowtype;
  v_attestation_id uuid;
  v_event_id uuid;
  v_existing jsonb;
  v_result jsonb;
begin
  if v_company_id is null or v_run_id is null or v_actor_user_id is null
     or nullif(v_test_case_code,'') is null or v_reason is null or v_evidence_reference is null
     or nullif(btrim(v_idempotency_key),'') is null then
    raise exception 'manual_attestation_request_fields_required';
  end if;

  if not public.gridex_actor_has_company_permission(
    v_actor_user_id,v_company_id,'ediel_testing.write'
  ) then
    raise exception using errcode='42501',message='ediel_testing_write_permission_denied';
  end if;

  select result_payload into v_existing from public.canonical_command_results
  where company_id=v_company_id and command_type='ediel.test.attestation.request' and idempotency_key=v_idempotency_key;
  if found then return v_existing; end if;

  select * into v_run from public.ediel_test_runs
  where id=v_run_id and company_id=v_company_id for update;
  if not found then raise exception 'tenant_scoped_test_run_not_found'; end if;
  if upper(v_run.test_case_code)<>v_test_case_code then raise exception 'test_case_does_not_match_run'; end if;
  if v_run.environment_type='production'::public.ediel_environment_type
     or lower(coalesce(v_run.environment,''))<>'test' then
    raise exception 'manual_attestation_requires_consistent_test_environment';
  end if;
  if v_run.configuration_snapshot_id is null or coalesce(v_run.is_stale,false) then
    raise exception 'manual_attestation_requires_current_snapshot';
  end if;
  if not exists(
    select 1 from public.ediel_active_test_configurations c
    where c.company_id=v_company_id and c.environment='test' and c.status='active'
      and c.configuration_snapshot_id=v_run.configuration_snapshot_id
      and c.test_suite=v_run.test_suite and c.setup_package=v_run.setup_package
      and upper(c.message_family)=upper(v_run.message_family)
  ) then raise exception 'manual_attestation_requires_current_active_test_configuration'; end if;

  insert into public.actor_test_manual_attestations(
    company_id,test_run_id,test_case_code,reason,evidence_reference,requested_by,requested_at,status
  ) values (
    v_company_id,v_run_id,v_test_case_code,v_reason,v_evidence_reference,v_actor_user_id,now(),'requested'
  ) returning id into v_attestation_id;

  insert into public.canonical_audit_events(
    company_id,event_type,aggregate_type,aggregate_id,actor_user_id,reason,idempotency_key,after_state
  ) values (
    v_company_id,'EDIEL_TEST_MANUAL_ATTESTATION_REQUESTED','actor_test_attestation',v_attestation_id,
    v_actor_user_id,v_reason,v_idempotency_key,
    jsonb_build_object('status','requested','test_run_id',v_run_id,'test_case_code',v_test_case_code,'evidence_reference',v_evidence_reference)
  );
  insert into public.canonical_domain_events(
    company_id,event_type,aggregate_type,aggregate_id,idempotency_key,payload,created_by
  ) values (
    v_company_id,'EDIEL_TEST_MANUAL_ATTESTATION_REQUESTED','actor_test_attestation',v_attestation_id,
    v_idempotency_key,jsonb_build_object('test_run_id',v_run_id,'test_case_code',v_test_case_code),v_actor_user_id
  ) returning id into v_event_id;
  insert into public.canonical_event_outbox(company_id,domain_event_id,topic,idempotency_key,payload)
  values(v_company_id,v_event_id,'ediel.test.attestation.requested',v_idempotency_key,
    jsonb_build_object('attestation_id',v_attestation_id,'test_run_id',v_run_id));

  v_result:=jsonb_build_object('attestation_id',v_attestation_id,'status','requested','test_run_id',v_run_id);
  insert into public.canonical_command_results(company_id,command_type,idempotency_key,request_payload,result_payload,actor_user_id)
  values(v_company_id,'ediel.test.attestation.request',v_idempotency_key,p_command,v_result,v_actor_user_id);
  return v_result;
end;
$$;

--
-- Name: canonical_resolve_inbound_manual_review(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_resolve_inbound_manual_review(p_job_id uuid, p_inbound_email_message_id uuid, p_resolution text, p_next_status text, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_job public.inbound_processing_jobs%rowtype;
  v_resolved_at timestamptz := now();
  v_next_status text;
begin
  if p_actor_user_id is null
     or not public.canonical_actor_is_platform_admin(p_actor_user_id) then
    raise exception using
      errcode = '42501',
      message = 'platform_admin_required';
  end if;

  if p_inbound_email_message_id is null then
    raise exception using
      errcode = '22023',
      message = 'inbound_email_message_id_required';
  end if;

  if nullif(btrim(coalesce(p_resolution, '')), '') is null then
    raise exception using
      errcode = '22023',
      message = 'manual_review_resolution_required';
  end if;

  -- Canonical worker vocabulary uses done for successful terminal jobs.
  -- Accept completed for one release of UI/RPC compatibility, then normalize.
  v_next_status := case
    when lower(btrim(p_next_status)) = 'completed' then 'done'
    else lower(btrim(coalesce(p_next_status, '')))
  end;

  if v_next_status not in ('queued', 'done', 'failed') then
    raise exception using
      errcode = '22023',
      message = 'manual_review_next_status_invalid';
  end if;

  select *
  into v_job
  from public.inbound_processing_jobs
  where id = p_job_id
  for update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'inbound_processing_job_not_found';
  end if;

  if v_job.inbound_email_message_id is distinct from p_inbound_email_message_id then
    raise exception using
      errcode = '22023',
      message = 'inbound_processing_job_message_mismatch';
  end if;

  if v_job.status <> 'manual_review'
     or v_job.review_resolved_at is not null then
    raise exception using
      errcode = '22023',
      message = 'inbound_processing_job_not_open_for_manual_review';
  end if;

  update public.inbound_processing_jobs
  set status = v_next_status,
      review_resolution = btrim(p_resolution),
      review_resolved_at = v_resolved_at,
      locked_at = null,
      locked_by = null,
      error_message = case
        when v_next_status = 'failed' then coalesce(error_message, btrim(p_resolution))
        else null
      end,
      finished_at = case
        when v_next_status in ('done', 'failed') then coalesce(finished_at, v_resolved_at)
        else null
      end,
      updated_at = v_resolved_at
  where id = p_job_id;

  insert into public.audit_logs(
    company_id,
    actor_user_id,
    action,
    entity_type,
    entity_id,
    new_values
  )
  values (
    v_job.company_id,
    p_actor_user_id,
    'INBOUND_MANUAL_REVIEW_RESOLVED',
    'inbound_processing_jobs',
    p_job_id,
    jsonb_build_object(
      'previous_status', v_job.status,
      'next_status', v_next_status,
      'requested_next_status', p_next_status,
      'inbound_email_message_id', p_inbound_email_message_id,
      'resolution', btrim(p_resolution),
      'review_owner', v_job.review_owner,
      'review_priority', v_job.review_priority,
      'review_reason', v_job.review_reason,
      'resolved_at', v_resolved_at
    )
  );

  return jsonb_build_object(
    'ok', true,
    'job_id', p_job_id,
    'inbound_email_message_id', p_inbound_email_message_id,
    'status', v_next_status,
    'resolved_at', v_resolved_at
  );
end
$$;

--
-- Name: FUNCTION canonical_resolve_inbound_manual_review(p_job_id uuid, p_inbound_email_message_id uuid, p_resolution text, p_next_status text, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.canonical_resolve_inbound_manual_review(p_job_id uuid, p_inbound_email_message_id uuid, p_resolution text, p_next_status text, p_actor_user_id uuid) IS 'Platform-admin audited command for resolving an existing inbound_processing_jobs manual_review row. Requires job↔message binding and persists canonical statuses queued|done|failed.';

--
-- Name: canonical_restore_pre_engine_live_ediel_approval(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_restore_pre_engine_live_ediel_approval(p_company_id uuid, p_actor_user_id uuid, p_reason text DEFAULT 'Restore audited pre-engine Ediel production approval into the current evidence engine.'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_engine text := public.canonical_current_ediel_engine_schema_version();
  v_cutover timestamptz := timestamptz '2026-07-13 10:00:00+00';
  v_now timestamptz := clock_timestamp();
  v_company public.companies%rowtype;
  v_activation public.ediel_go_live_events%rowtype;
  v_historical_check public.ediel_production_readiness_checks%rowtype;
  v_historical_dry_run public.ediel_go_live_events%rowtype;
  v_current_replay public.ediel_go_live_events%rowtype;
  v_current_check public.ediel_production_readiness_checks%rowtype;
  v_historical_ediel_id text;
  v_historical_route_id uuid;
  v_historical_mailbox_id uuid;
  v_actor_setting_id uuid;
  v_actor_count integer := 0;
  v_readiness jsonb;
  v_missing_current_checks text[];
  v_from_state text;
  v_restore_event_id uuid;
begin
  if p_company_id is null then raise exception 'historical_live_restore_company_required'; end if;
  if p_actor_user_id is null then raise exception 'historical_live_restore_actor_required'; end if;
  if not public.canonical_actor_is_platform_admin(p_actor_user_id) then raise exception 'historical_live_restore_platform_admin_required'; end if;

  select * into v_company from public.companies where id = p_company_id for update;
  if not found then raise exception 'historical_live_restore_company_not_found'; end if;
  if coalesce(v_company.is_active, true) is false
     or lower(coalesce(v_company.lifecycle_status, v_company.status, 'active')) in ('paused','suspended','archived','pending_deletion','deleted_test_only') then
    raise exception 'historical_live_restore_company_not_active';
  end if;

  select e.* into v_activation from public.ediel_go_live_events e
  where e.company_id = p_company_id and e.event_type = 'production_activated' and e.to_status = 'live' and e.created_at < v_cutover
  order by e.created_at desc limit 1;
  if not found then raise exception 'historical_live_restore_prior_activation_missing'; end if;

  select r.* into v_historical_check from public.ediel_production_readiness_checks r
  where r.id = v_activation.readiness_check_id and r.company_id = p_company_id;
  if not found then raise exception 'historical_live_restore_activation_readiness_missing'; end if;
  if jsonb_array_length(coalesce(v_historical_check.blocking_issues, '[]'::jsonb)) <> 0 then raise exception 'historical_live_restore_activation_had_blockers'; end if;
  if not exists (
    select 1 from jsonb_array_elements(coalesce(v_historical_check.passed_checks, '[]'::jsonb)) as j(item)
    where j.item->>'code' = 'required_tests_approved' and j.item->>'severity' = 'passed'
  ) then raise exception 'historical_live_restore_required_tests_not_approved'; end if;

  v_historical_ediel_id := nullif(btrim(coalesce(
    v_activation.metadata #>> '{readinessSnapshot,summary,edielId}',
    v_historical_check.readiness_snapshot #>> '{summary,edielId}'
  )), '');
  if v_historical_ediel_id is null then raise exception 'historical_live_restore_historical_ediel_id_missing'; end if;

  begin
    v_historical_route_id := nullif(coalesce(
      v_activation.metadata->>'routeProfileId',
      v_activation.metadata #>> '{readinessSnapshot,summary,activeProductionProdatRouteProfileId}',
      v_historical_check.readiness_snapshot #>> '{summary,activeProductionProdatRouteProfileId}'
    ), '')::uuid;
  exception when invalid_text_representation then v_historical_route_id := null; end;
  begin
    v_historical_mailbox_id := nullif(coalesce(
      v_activation.metadata #>> '{readinessSnapshot,summary,productionMailboxId}',
      v_historical_check.readiness_snapshot #>> '{summary,productionMailboxId}'
    ), '')::uuid;
  exception when invalid_text_representation then v_historical_mailbox_id := null; end;
  if v_historical_route_id is null or v_historical_mailbox_id is null then raise exception 'historical_live_restore_transport_identity_missing'; end if;

  select e.* into v_historical_dry_run from public.ediel_go_live_events e
  where e.company_id = p_company_id and e.event_type = 'production_dry_run' and e.created_at <= v_activation.created_at
    and coalesce((e.metadata->>'success')::boolean, false) = true
    and jsonb_array_length(coalesce(e.metadata->'blockingIssues', '[]'::jsonb)) = 0
    and e.metadata #>> '{previewMetadata,edielId}' = v_historical_ediel_id
    and e.metadata #>> '{previewMetadata,productionProdatRouteProfileId}' = v_historical_route_id::text
    and e.metadata #>> '{previewMetadata,productionMailboxId}' = v_historical_mailbox_id::text
  order by e.created_at desc limit 1;
  if not found then raise exception 'historical_live_restore_successful_dry_run_missing'; end if;

  if not exists (
    select 1 from public.ediel_go_live_events e
    where e.company_id = p_company_id and e.event_type = 'first_live_send_approved'
      and e.created_at <= v_activation.created_at and e.metadata->>'edielId' = v_historical_ediel_id
      and e.metadata->>'routeProfileId' = v_historical_route_id::text and e.metadata->>'mailboxId' = v_historical_mailbox_id::text
  ) then raise exception 'historical_live_restore_first_send_approval_missing'; end if;

  select count(*), (array_agg(a.id order by a.id))[1]
    into v_actor_count, v_actor_setting_id
  from public.ediel_actor_settings a
  where a.company_id = p_company_id and a.environment = 'production' and a.is_active = true
    and lower(coalesce(a.actor_role, a.role, '')) in ('supplier','electricity_supplier')
    and coalesce(nullif(btrim(a.actor_ediel_id), ''), nullif(btrim(a.ediel_id), '')) = v_historical_ediel_id;
  if v_actor_count <> 1 or v_actor_setting_id is null then raise exception 'historical_live_restore_current_supplier_identity_not_exact'; end if;
  if nullif(btrim(coalesce(v_company.production_ediel_id, v_company.ediel_id)), '') is distinct from v_historical_ediel_id then raise exception 'historical_live_restore_company_ediel_identity_changed'; end if;

  if not exists (
    select 1 from public.ediel_route_profiles r
    where r.id = v_historical_route_id and r.company_id = p_company_id and r.environment = 'production'
      and upper(coalesce(r.message_family, r.application_reference, '')) = 'PRODAT'
      and coalesce(r.is_active, r.is_enabled, true) = true
      and coalesce(nullif(btrim(r.sender_ediel_id), ''), nullif(btrim(r.own_ediel_id), '')) = v_historical_ediel_id
      and r.mailbox_id = v_historical_mailbox_id and coalesce(r.tls_required, false) = true and lower(coalesce(r.encryption_mode, '')) = 'smime'
  ) then raise exception 'historical_live_restore_approved_prodat_path_changed'; end if;

  if exists (
    select 1 from public.ediel_messages m
    where m.company_id = p_company_id and m.environment = 'production' and m.direction = 'outbound' and m.status = 'sent'
  ) then raise exception 'historical_live_restore_real_production_send_requires_pilot_evidence'; end if;

  select e.* into v_current_replay from public.ediel_go_live_events e
  where e.company_id = p_company_id and e.event_type = 'production_dry_run' and e.created_at >= v_cutover
    and e.metadata #>> '{previewMetadata,edielId}' = v_historical_ediel_id
    and e.metadata #>> '{previewMetadata,productionProdatRouteProfileId}' = v_historical_route_id::text
    and e.metadata #>> '{previewMetadata,productionMailboxId}' = v_historical_mailbox_id::text
    and not exists (
      select 1 from jsonb_array_elements(coalesce(e.metadata->'blockingIssues', '[]'::jsonb)) as b(item)
      where b.item->>'code' <> 'external_certification_and_pilot_missing'
    )
  order by e.created_at desc limit 1;
  if not found then raise exception 'historical_live_restore_current_engine_replay_missing'; end if;

  select r.* into v_current_check from public.ediel_production_readiness_checks r
  where r.id = v_current_replay.readiness_check_id and r.company_id = p_company_id;
  if not found then raise exception 'historical_live_restore_current_readiness_missing'; end if;
  if exists (
    select 1 from jsonb_array_elements(coalesce(v_current_check.blocking_issues, '[]'::jsonb)) as b(item)
    where b.item->>'code' <> 'external_certification_and_pilot_missing'
  ) then raise exception 'historical_live_restore_current_readiness_has_non_evidence_blockers'; end if;

  select array_agg(required_code order by required_code) into v_missing_current_checks
  from (values
      ('company_active'),('production_ediel_id'),('production_actor_exists'),('production_tls_required'),
      ('production_smime_default'),('production_recipient_certificate_resolved_at_send'),('actor_role_configured'),
      ('brp_configured'),('brp_active'),('esett_ready'),('production_prodat_route_exists'),('production_utilts_route_exists'),
      ('production_route_sender_valid'),('production_transport_configured'),('production_mailbox_exists'),('required_tests_approved'),
      ('no_unresolved_items'),('no_failed_messages'),('no_negative_aperaks'),('first_live_send_ready')
  ) as required(required_code)
  where not exists (
    select 1 from jsonb_array_elements(coalesce(v_current_check.passed_checks, '[]'::jsonb)) as p(item)
    where p.item->>'code' = required.required_code and p.item->>'severity' = 'passed'
  );
  if coalesce(array_length(v_missing_current_checks, 1), 0) > 0 then
    raise exception 'historical_live_restore_current_checks_missing:%', array_to_string(v_missing_current_checks, ',');
  end if;

  insert into public.ediel_certification_evidence (
    company_id,environment,evidence_type,status,engine_schema_version,external_reference,evidence_document_reference,
    tested_at,valid_until,approved_by,approved_at,metadata,created_at,updated_at
  ) values
    (p_company_id,'production','TGT','passed',v_engine,'historical-live-activation:'||v_activation.id::text,'ediel_production_readiness_checks/'||v_historical_check.id::text,v_historical_check.checked_at,null,p_actor_user_id,v_now,jsonb_build_object('source','historical_approval_migration','source_event_id',v_activation.id,'source_readiness_check_id',v_historical_check.id,'historical_ediel_id',v_historical_ediel_id,'assertion','pre-engine readiness recorded all mandatory actor tests approved; no new portal test is claimed'),v_now,v_now),
    (p_company_id,'production','AGT','passed',v_engine,'historical-live-activation:'||v_activation.id::text,'ediel_production_readiness_checks/'||v_historical_check.id::text,v_historical_check.checked_at,null,p_actor_user_id,v_now,jsonb_build_object('source','historical_approval_migration','source_event_id',v_activation.id,'source_readiness_check_id',v_historical_check.id,'historical_ediel_id',v_historical_ediel_id,'assertion','pre-engine readiness recorded all mandatory actor tests approved; no new portal test is claimed'),v_now,v_now),
    (p_company_id,'production','SHADOW_PRODUCTION','passed',v_engine,'historical-production-dry-run:'||v_historical_dry_run.id::text,'ediel_go_live_events/'||v_historical_dry_run.id::text,v_historical_dry_run.created_at,null,p_actor_user_id,v_now,jsonb_build_object('source','historical_approval_migration','source_event_id',v_historical_dry_run.id,'approved_prodat_route_id',v_historical_route_id,'approved_mailbox_id',v_historical_mailbox_id,'historical_ediel_id',v_historical_ediel_id),v_now,v_now),
    (p_company_id,'production','LIVE_TENANT_INTEGRITY','passed',v_engine,'current-readiness:'||v_current_check.id::text,'ediel_production_readiness_checks/'||v_current_check.id::text,v_current_check.checked_at,null,p_actor_user_id,v_now,jsonb_build_object('source','historical_approval_migration','source_readiness_check_id',v_current_check.id,'current_actor_setting_id',v_actor_setting_id,'approved_prodat_route_id',v_historical_route_id,'approved_mailbox_id',v_historical_mailbox_id,'assertion','current readiness passed tenant identity, supplier, route, transport, mailbox, BRP/eSett and operational integrity checks; only current-evidence circular gate remained'),v_now,v_now),
    (p_company_id,'production','RESTORE_REPLAY','passed',v_engine,'current-engine-dry-run:'||v_current_replay.id::text,'ediel_go_live_events/'||v_current_replay.id::text,v_current_replay.created_at,null,p_actor_user_id,v_now,jsonb_build_object('source','historical_approval_migration','source_event_id',v_current_replay.id,'current_engine',v_engine,'approved_prodat_route_id',v_historical_route_id,'approved_mailbox_id',v_historical_mailbox_id,'assertion','current engine rebuilt the production envelope and was blocked only by the circular current-evidence gate'),v_now,v_now)
  on conflict (company_id,environment,evidence_type,engine_schema_version) do update set
    status=excluded.status,external_reference=excluded.external_reference,evidence_document_reference=excluded.evidence_document_reference,
    tested_at=excluded.tested_at,valid_until=excluded.valid_until,approved_by=excluded.approved_by,approved_at=excluded.approved_at,
    metadata=excluded.metadata,updated_at=excluded.updated_at;

  v_readiness := public.canonical_ediel_production_evidence_readiness(p_company_id);
  if coalesce((v_readiness->>'ready')::boolean, false) is false then
    raise exception 'historical_live_restore_current_evidence_not_ready:%', v_readiness::text;
  end if;

  select state into v_from_state from public.ediel_production_state where company_id=p_company_id for update;
  v_from_state := coalesce(v_from_state,'blocked');
  update public.ediel_production_state
  set state='live',readiness_check_id=v_current_check.id,dry_run_id=v_current_replay.id,state_version=coalesce(state_version,0)+1,
      approved_by=coalesce(approved_by,v_activation.actor_user_id,p_actor_user_id),approved_at=coalesce(approved_at,v_activation.created_at,v_now),
      blocked_reason=null,paused_by=null,paused_at=null,pause_reason=null,last_idempotency_key='historical-live-restore:'||v_engine,updated_at=v_now
  where company_id=p_company_id;
  if not found then
    insert into public.ediel_production_state (
      company_id,state,readiness_check_id,dry_run_id,state_version,approved_by,approved_at,
      first_live_send_approved_by,first_live_send_approved_at,blocked_reason,last_idempotency_key,created_at,updated_at
    ) values (
      p_company_id,'live',v_current_check.id,v_current_replay.id,1,coalesce(v_activation.actor_user_id,p_actor_user_id),v_activation.created_at,
      p_actor_user_id,v_activation.created_at,null,'historical-live-restore:'||v_engine,v_now,v_now
    );
  end if;

  update public.companies
  set ediel_production_status='live',ediel_production_enabled=true,ediel_production_enabled_at=coalesce(ediel_production_enabled_at,v_now),
      live_ediel_enabled=true,live_approved_at=coalesce(live_approved_at,v_activation.created_at),live_blocked_reason=null,updated_at=v_now
  where id=p_company_id;

  update public.ediel_send_locks
  set locked=false,locked_reason=null,unlocked_by=p_actor_user_id,unlocked_at=v_now,updated_at=v_now
  where company_id=p_company_id and environment='production' and locked=true;

  insert into public.ediel_go_live_events (
    company_id,event_type,from_status,to_status,reason,actor_user_id,readiness_check_id,metadata,created_at,is_stale,stale_reason
  ) values (
    p_company_id,'historical_live_approval_restored',v_from_state,'live',
    coalesce(nullif(btrim(p_reason),''),'Restore audited pre-engine Ediel production approval into the current evidence engine.'),
    p_actor_user_id,v_current_check.id,
    jsonb_build_object('source','historical_approval_migration','engine_schema_version',v_engine,'historical_activation_event_id',v_activation.id,
      'historical_dry_run_event_id',v_historical_dry_run.id,'current_replay_event_id',v_current_replay.id,'historical_ediel_id',v_historical_ediel_id,
      'approved_prodat_route_id',v_historical_route_id,'approved_mailbox_id',v_historical_mailbox_id,'limited_pilot_required',false),
    v_now,false,null
  ) returning id into v_restore_event_id;

  return jsonb_build_object('restored',true,'company_id',p_company_id,'state','live','engine_schema_version',v_engine,'ediel_id',v_historical_ediel_id,
    'historical_activation_event_id',v_activation.id,'historical_dry_run_event_id',v_historical_dry_run.id,'current_replay_event_id',v_current_replay.id,
    'current_readiness_check_id',v_current_check.id,'restore_event_id',v_restore_event_id,'evidence_readiness',v_readiness);
end;
$$;

--
-- Name: FUNCTION canonical_restore_pre_engine_live_ediel_approval(p_company_id uuid, p_actor_user_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.canonical_restore_pre_engine_live_ediel_approval(p_company_id uuid, p_actor_user_id uuid, p_reason text) IS 'Fail-closed compatibility restore for tenants auditably live before the current Ediel certification-evidence engine.';

--
-- Name: canonical_run_architecture_reconciliation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_run_architecture_reconciliation(p_company_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $_$
declare
  v_count bigint;
  v_results jsonb := '{}'::jsonb;
  v_sql text;
begin
  if p_company_id is null then
    raise exception using errcode = '22023', message = 'reconciliation_company_scope_required';
  end if;
  if not exists(select 1 from public.companies where id = p_company_id) then
    raise exception 'reconciliation_company_not_found';
  end if;

  -- Access: active membership without a canonical role.
  begin
    select count(*) into v_count
    from public.company_memberships membership
    where membership.company_id = p_company_id
      and membership.status = 'active' and coalesce(membership.is_active, true)
      and not exists (
        select 1 from public.user_roles role
        where role.company_id = membership.company_id
          and role.user_id = membership.user_id
          and coalesce(role.status, 'active') = 'active'
          and coalesce(role.is_active, true)
      );
    perform public.canonical_set_architecture_finding(
      p_company_id, 'active-membership-missing-role', 'access', 'critical',
      'Active memberships without canonical roles', v_count, 'platform_security',
      'Repair membership and role atomically through canonical_change_tenant_user_access', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:active-membership-missing-role', 'reconciliation', 'critical',
      'Membership reconciliation check failed', 0, 'platform_operations',
      'Repair the check before treating access as healthy', null);
    v_results := v_results || jsonb_build_object('membership_without_role', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:active-membership-missing-role', 'reconciliation', 'critical',
      'Membership reconciliation check failed', 1, 'platform_operations',
      'Repair the check before treating access as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('membership_without_role_error', sqlstate);
  end;

  -- Access: active role without an auth identity.
  begin
    select count(*) into v_count
    from public.user_roles role
    where role.company_id = p_company_id
      and coalesce(role.status, 'active') = 'active'
      and coalesce(role.is_active, true)
      and not exists (select 1 from auth.users identity where identity.id = role.user_id);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'role-without-auth-identity', 'access', 'critical',
      'Active roles without an auth identity', v_count, 'platform_security',
      'Remove stale authorization state or restore the authoritative identity', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:role-without-auth-identity', 'reconciliation', 'critical',
      'Role identity reconciliation check failed', 0, 'platform_operations',
      'Repair the check before treating access as healthy', null);
    v_results := v_results || jsonb_build_object('role_without_auth_identity', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:role-without-auth-identity', 'reconciliation', 'critical',
      'Role identity reconciliation check failed', 1, 'platform_operations',
      'Repair the check before treating access as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('role_without_auth_identity_error', sqlstate);
  end;

  -- Access: duplicate active memberships.
  begin
    select count(*) into v_count
    from (
      select membership.company_id, membership.user_id
      from public.company_memberships membership
      where membership.company_id = p_company_id
        and coalesce(membership.status, 'active') = 'active'
        and coalesce(membership.is_active, true)
      group by membership.company_id, membership.user_id
      having count(*) > 1
    ) duplicates;
    perform public.canonical_set_architecture_finding(
      p_company_id, 'duplicate-active-membership', 'access', 'critical',
      'Duplicate active tenant memberships', v_count, 'platform_security',
      'Converge duplicate memberships into the canonical access mutation', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:duplicate-active-membership', 'reconciliation', 'critical',
      'Membership duplicate check failed', 0, 'platform_operations',
      'Repair the check before treating access as healthy', null);
    v_results := v_results || jsonb_build_object('duplicate_membership', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:duplicate-active-membership', 'reconciliation', 'critical',
      'Membership duplicate check failed', 1, 'platform_operations',
      'Repair the check before treating access as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('duplicate_membership_error', sqlstate);
  end;

  -- Access: duplicate active canonical roles per role identity.
  begin
    select count(*) into v_count
    from (
      select role.company_id, role.user_id,
             coalesce(to_jsonb(role) ->> 'role_key', to_jsonb(role) ->> 'role', to_jsonb(role) ->> 'permission_key', '') as role_identity
      from public.user_roles role
      where role.company_id = p_company_id
        and coalesce(role.status, 'active') = 'active'
        and coalesce(role.is_active, true)
      group by role.company_id, role.user_id,
               coalesce(to_jsonb(role) ->> 'role_key', to_jsonb(role) ->> 'role', to_jsonb(role) ->> 'permission_key', '')
      having count(*) > 1
    ) duplicates;
    perform public.canonical_set_architecture_finding(
      p_company_id, 'duplicate-active-role', 'access', 'critical',
      'Duplicate active canonical roles', v_count, 'platform_security',
      'Converge duplicate role rows through canonical_change_tenant_user_access', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:duplicate-active-role', 'reconciliation', 'critical',
      'Role duplicate check failed', 0, 'platform_operations',
      'Repair the check before treating access as healthy', null);
    v_results := v_results || jsonb_build_object('duplicate_role', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:duplicate-active-role', 'reconciliation', 'critical',
      'Role duplicate check failed', 1, 'platform_operations',
      'Repair the check before treating access as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('duplicate_role_error', sqlstate);
  end;

  -- Invitations accepted without active access.
  begin
    if to_regclass('public.company_invitations') is not null then
      execute $q$
        select count(*)
        from public.company_invitations invitation
        where invitation.company_id = $1
          and lower(coalesce(to_jsonb(invitation) ->> 'status', '')) in ('accepted', 'completed')
          and (to_jsonb(invitation) ->> 'invited_user_id') is not null
          and not exists (
            select 1 from public.company_memberships membership
            where membership.company_id = invitation.company_id
              and membership.user_id::text = to_jsonb(invitation) ->> 'invited_user_id'
              and coalesce(membership.status, 'active') = 'active'
              and coalesce(membership.is_active, true)
          )
      $q$ into v_count using p_company_id;
    else
      v_count := 0;
    end if;
    perform public.canonical_set_architecture_finding(
      p_company_id, 'accepted-invite-without-access', 'access', 'critical',
      'Accepted invitations without active tenant access', v_count, 'tenant_operations',
      'Replay canonical invitation acceptance or revoke the invalid invitation state', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:accepted-invite-without-access', 'reconciliation', 'critical',
      'Invitation/access reconciliation check failed', 0, 'platform_operations',
      'Repair the check before treating invitations as healthy', null);
    v_results := v_results || jsonb_build_object('accepted_invite_without_access', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:accepted-invite-without-access', 'reconciliation', 'critical',
      'Invitation/access reconciliation check failed', 1, 'platform_operations',
      'Repair the check before treating invitations as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('accepted_invite_without_access_error', sqlstate);
  end;

  -- Integration readiness.
  begin
    select count(*) into v_count
    from public.integration_api_clients client
    where client.company_id = p_company_id
      and client.status = 'active'
      and coalesce(client.launch_ready, false) = false;
    perform public.canonical_set_architecture_finding(
      p_company_id, 'active-api-client-not-launch-ready', 'integration', 'critical',
      'Active API clients without verified launch readiness', v_count, 'integration_operations',
      'Run canonical readiness smoke and pause clients that cannot pass', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:active-api-client-not-launch-ready', 'reconciliation', 'critical',
      'API client readiness check failed', 0, 'platform_operations',
      'Repair the check before treating integrations as healthy', null);
    v_results := v_results || jsonb_build_object('active_client_not_ready', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:active-api-client-not-launch-ready', 'reconciliation', 'critical',
      'API client readiness check failed', 1, 'platform_operations',
      'Repair the check before treating integrations as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('active_client_not_ready_error', sqlstate);
  end;

  -- Canonical event ingress must not accumulate. Delivery remains the established
  -- domain_events/event_outbox path until all deprecated producers are removed.
  begin
    if to_regclass('public.canonical_event_outbox') is not null then
      select count(*) into v_count
      from public.canonical_event_outbox outbox
      where outbox.company_id = p_company_id
        and outbox.status in ('pending', 'retry', 'failed')
        and outbox.available_at <= now()
        and outbox.created_at < now() - interval '5 minutes';
    else
      v_count := 0;
    end if;
    perform public.canonical_set_architecture_finding(
      p_company_id, 'deprecated-canonical-event-bus-backlog', 'events', 'critical',
      'Deprecated canonical event ingress has a backlog', v_count, 'platform_operations',
      'Drain through the established event_outbox bridge and remove the remaining deprecated producer', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:deprecated-canonical-event-bus-backlog', 'reconciliation', 'critical',
      'Deprecated event ingress check failed', 0, 'platform_operations',
      'Repair the check before treating event delivery as healthy', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'due-stranded-canonical-outbox', 'events', 'critical',
      'Due canonical outbox rows are stranded', 0, 'platform_operations',
      'Claim and process the canonical event outbox; inspect dead letters', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:due-stranded-canonical-outbox', 'reconciliation', 'critical',
      'Canonical outbox check failed', 0, 'platform_operations',
      'Repair the check before treating event delivery as healthy', null);
    v_results := v_results || jsonb_build_object('deprecated_event_bus_backlog', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:deprecated-canonical-event-bus-backlog', 'reconciliation', 'critical',
      'Deprecated event ingress check failed', 1, 'platform_operations',
      'Repair the check before treating event delivery as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('deprecated_event_bus_backlog_error', sqlstate);
  end;

  -- Active event outbox must not have due stranded work.
  begin
    if to_regclass('public.event_outbox') is not null then
      execute $q$
        select count(*)
        from public.event_outbox outbox
        where outbox.company_id = $1
          and lower(coalesce(to_jsonb(outbox) ->> 'status', '')) in ('queued', 'pending', 'retry', 'failed', 'failed_retryable')
          and coalesce((to_jsonb(outbox) ->> 'available_at')::timestamptz, now()) <= now()
          and coalesce((to_jsonb(outbox) ->> 'created_at')::timestamptz, now()) < now() - interval '5 minutes'
      $q$ into v_count using p_company_id;
    else
      v_count := 0;
    end if;
    perform public.canonical_set_architecture_finding(
      p_company_id, 'due-stranded-event-outbox', 'events', 'critical',
      'Due active event outbox rows are stranded', v_count, 'platform_operations',
      'Run the existing outbox worker and inspect retry/dead-letter causes', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:due-stranded-event-outbox', 'reconciliation', 'critical',
      'Active event outbox check failed', 0, 'platform_operations',
      'Repair the check before treating event delivery as healthy', null);
    v_results := v_results || jsonb_build_object('due_stranded_outbox', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:due-stranded-event-outbox', 'reconciliation', 'critical',
      'Active event outbox check failed', 1, 'platform_operations',
      'Repair the check before treating event delivery as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('due_stranded_outbox_error', sqlstate);
  end;

  -- Provisioning: dead letters and jobs stuck in an in-flight state.
  begin
    select count(*) into v_count
    from public.company_provisioning_jobs job
    where job.company_id = p_company_id and job.status = 'dead_letter';
    perform public.canonical_set_architecture_finding(
      p_company_id, 'provisioning-dead-letter', 'provisioning', 'critical',
      'Tenant provisioning jobs are dead-lettered', v_count, 'tenant_operations',
      'Correct the provider/configuration fault and explicitly requeue', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:provisioning-dead-letter', 'reconciliation', 'critical',
      'Provisioning dead-letter check failed', 0, 'platform_operations',
      'Repair the check before treating provisioning as healthy', null);
    v_results := v_results || jsonb_build_object('provisioning_dead_letter', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:provisioning-dead-letter', 'reconciliation', 'critical',
      'Provisioning dead-letter check failed', 1, 'platform_operations',
      'Repair the check before treating provisioning as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('provisioning_dead_letter_error', sqlstate);
  end;

  begin
    if to_regclass('public.company_provisioning_jobs') is not null then
      execute $q$
        select count(*)
        from public.company_provisioning_jobs job
        where job.company_id = $1
          and lower(coalesce(to_jsonb(job) ->> 'status', '')) in ('queued', 'pending', 'running', 'processing', 'retry')
          and coalesce(
                nullif(to_jsonb(job) ->> 'updated_at', '')::timestamptz,
                nullif(to_jsonb(job) ->> 'created_at', '')::timestamptz,
                now()
              ) < now() - interval '30 minutes'
      $q$ into v_count using p_company_id;
    else
      v_count := 0;
    end if;
    perform public.canonical_set_architecture_finding(
      p_company_id, 'stuck-provisioning', 'provisioning', 'critical',
      'Tenant provisioning jobs are stuck', v_count, 'tenant_operations',
      'Recover the existing provisioning lease/retry path; do not create a second provisioner', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:stuck-provisioning', 'reconciliation', 'critical',
      'Stuck provisioning check failed', 0, 'platform_operations',
      'Repair the check before treating provisioning as healthy', null);
    v_results := v_results || jsonb_build_object('stuck_provisioning', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:stuck-provisioning', 'reconciliation', 'critical',
      'Stuck provisioning check failed', 1, 'platform_operations',
      'Repair the check before treating provisioning as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('stuck_provisioning_error', sqlstate);
  end;

  -- Manual review: both the existing customer-operation path and inbound mail
  -- must have explicit ownership and SLA semantics.
  begin
    if to_regclass('public.customer_operation_jobs') is not null then
      select count(*) into v_count
      from public.customer_operation_jobs job
      where job.company_id = p_company_id
        and job.status = 'needs_review'
        and job.review_resolved_at is null
        and job.review_sla_due_at < now();
    else
      v_count := 0;
    end if;
    perform public.canonical_set_architecture_finding(
      p_company_id, 'manual-review-over-sla', 'customer_operations', 'warning',
      'Manual-review jobs exceeded their SLA', v_count, 'tenant_operations',
      'Resolve the blocker and record the resolution on the existing job', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:manual-review-over-sla', 'reconciliation', 'critical',
      'Manual-review SLA check failed', 0, 'platform_operations',
      'Repair the check before treating manual review as healthy', null);
    v_results := v_results || jsonb_build_object('manual_review_over_sla', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:manual-review-over-sla', 'reconciliation', 'critical',
      'Manual-review SLA check failed', 1, 'platform_operations',
      'Repair the check before treating manual review as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('manual_review_over_sla_error', sqlstate);
  end;

  begin
    if to_regclass('public.inbound_processing_jobs') is not null then
      select count(*) into v_count
      from public.inbound_processing_jobs job
      where job.company_id = p_company_id
        and job.status = 'manual_review'
        and job.review_resolved_at is null
        and (nullif(job.review_owner, '') is null
          or nullif(job.review_reason, '') is null
          or job.review_sla_due_at is null);
    else
      v_count := 0;
    end if;
    perform public.canonical_set_architecture_finding(
      p_company_id, 'manual-review-without-owner-or-sla', 'customer_operations', 'critical',
      'Manual-review work lacks owner, reason or SLA', v_count, 'tenant_operations',
      'Complete ownership, reason and SLA fields on the existing inbound processing job', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:manual-review-without-owner-or-sla', 'reconciliation', 'critical',
      'Inbound manual-review check failed', 0, 'platform_operations',
      'Repair the check before treating manual review as healthy', null);
    v_results := v_results || jsonb_build_object('manual_review_without_owner', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:manual-review-without-owner-or-sla', 'reconciliation', 'critical',
      'Inbound manual-review check failed', 1, 'platform_operations',
      'Repair the check before treating manual review as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('manual_review_without_owner_error', sqlstate);
  end;

  -- Customer intake repair workflow.
  begin
    select count(*) into v_count
    from public.website_customer_applications application
    where application.company_id = p_company_id
      and application.status in ('failed', 'pending_review', 'manual_review')
      and application.customer_id is null
      and application.repair_status is null;
    perform public.canonical_set_architecture_finding(
      p_company_id, 'customer-application-without-repair-workflow', 'customer_intake', 'critical',
      'Incomplete customer applications lack a repair workflow', v_count, 'platform_operations',
      'Classify the payload and attach the canonical repair workflow', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:customer-application-without-repair-workflow', 'reconciliation', 'critical',
      'Customer-application repair check failed', 0, 'platform_operations',
      'Repair the check before treating customer intake as healthy', null);
    v_results := v_results || jsonb_build_object('application_without_repair', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:customer-application-without-repair-workflow', 'reconciliation', 'critical',
      'Customer-application repair check failed', 1, 'platform_operations',
      'Repair the check before treating customer intake as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('application_without_repair_error', sqlstate);
  end;

  -- Contracts must have their customer, site and metering-point prerequisites.
  begin
    if to_regclass('public.customer_contracts') is not null then
      execute $q$
        select count(*)
        from public.customer_contracts contract
        where contract.company_id = $1
          and lower(coalesce(to_jsonb(contract) ->> 'status', '')) in ('active', 'signed')
          and (
            nullif(to_jsonb(contract) ->> 'customer_id', '') is null
            or coalesce(
                 nullif(to_jsonb(contract) ->> 'customer_site_id', ''),
                 nullif(to_jsonb(contract) ->> 'site_id', '')
               ) is null
          )
      $q$ into v_count using p_company_id;
    else
      v_count := 0;
    end if;
    perform public.canonical_set_architecture_finding(
      p_company_id, 'contract-missing-customer-or-site', 'customer_operations', 'critical',
      'Active contracts are missing customer or site links', v_count, 'tenant_operations',
      'Repair the canonical contract relationship before billing or supplier switch', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:contract-missing-customer-or-site', 'reconciliation', 'critical',
      'Contract relationship check failed', 0, 'platform_operations',
      'Repair the check before treating contracts as healthy', null);
    v_results := v_results || jsonb_build_object('contract_missing_customer_or_site', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:contract-missing-customer-or-site', 'reconciliation', 'critical',
      'Contract relationship check failed', 1, 'platform_operations',
      'Repair the check before treating contracts as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('contract_missing_customer_or_site_error', sqlstate);
  end;

  begin
    if to_regclass('public.customer_contracts') is not null
       and to_regclass('public.metering_points') is not null then
      execute $q$
        select count(*)
        from public.customer_contracts contract
        where contract.company_id = $1
          and lower(coalesce(to_jsonb(contract) ->> 'status', '')) in ('active', 'signed')
          and coalesce(
                nullif(to_jsonb(contract) ->> 'customer_site_id', ''),
                nullif(to_jsonb(contract) ->> 'site_id', '')
              ) is not null
          and not exists (
            select 1 from public.metering_points point
            where coalesce(
                    nullif(to_jsonb(point) ->> 'site_id', ''),
                    nullif(to_jsonb(point) ->> 'customer_site_id', '')
                  ) = coalesce(
                        nullif(to_jsonb(contract) ->> 'customer_site_id', ''),
                        nullif(to_jsonb(contract) ->> 'site_id', '')
                      )
          )
      $q$ into v_count using p_company_id;
    else
      v_count := 0;
    end if;
    perform public.canonical_set_architecture_finding(
      p_company_id, 'contract-without-metering-point', 'customer_operations', 'critical',
      'Active contracts have no metering point on their site', v_count, 'tenant_operations',
      'Attach the authoritative metering point before supplier switch or settlement', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:contract-without-metering-point', 'reconciliation', 'critical',
      'Contract metering-point check failed', 0, 'platform_operations',
      'Repair the check before treating contracts as healthy', null);
    v_results := v_results || jsonb_build_object('contract_without_metering_point', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:contract-without-metering-point', 'reconciliation', 'critical',
      'Contract metering-point check failed', 1, 'platform_operations',
      'Repair the check before treating contracts as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('contract_without_metering_point_error', sqlstate);
  end;

  -- Supplier switches must retain a contract relationship when the schema exposes
  -- one. The JSON projection keeps this check compatible with older columns.
  begin
    if to_regclass('public.supplier_switch_requests') is not null then
      execute $q$
        select count(*)
        from public.supplier_switch_requests switch
        where switch.company_id = $1
          and lower(coalesce(to_jsonb(switch) ->> 'status', '')) in
              ('ready', 'queued', 'sending', 'sent', 'pending', 'in_progress', 'awaiting_response')
          and (to_jsonb(switch) ? 'contract_id')
          and nullif(to_jsonb(switch) ->> 'contract_id', '') is null
      $q$ into v_count using p_company_id;
    else
      v_count := 0;
    end if;
    perform public.canonical_set_architecture_finding(
      p_company_id, 'switch-without-contract', 'customer_operations', 'critical',
      'Open supplier switches lack a contract relationship', v_count, 'tenant_operations',
      'Repair the existing switch request before dispatch', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:switch-without-contract', 'reconciliation', 'critical',
      'Supplier-switch contract check failed', 0, 'platform_operations',
      'Repair the check before treating supplier switches as healthy', null);
    v_results := v_results || jsonb_build_object('switch_without_contract', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:switch-without-contract', 'reconciliation', 'critical',
      'Supplier-switch contract check failed', 1, 'platform_operations',
      'Repair the check before treating supplier switches as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('switch_without_contract_error', sqlstate);
  end;

  -- EDIEL live state must never coexist with a non-active tenant.
  begin
    if to_regclass('public.ediel_production_state') is not null then
      execute $q$
        select count(*)
        from public.ediel_production_state state
        join public.companies company on company.id::text = to_jsonb(state) ->> 'company_id'
        where company.id = $1
          and lower(coalesce(to_jsonb(state) ->> 'status', to_jsonb(state) ->> 'state', '')) in ('live', 'production', 'active')
          and (company.status <> 'active' or company.lifecycle_status <> 'active' or not coalesce(company.is_active, true))
      $q$ into v_count using p_company_id;
    else
      v_count := 0;
    end if;
    perform public.canonical_set_architecture_finding(
      p_company_id, 'ediel-live-without-valid-tenant', 'ediel', 'critical',
      'EDIEL production state is live for a non-active tenant', v_count, 'platform_operations',
      'Pause EDIEL through the canonical lifecycle/EDIEL transition before tenant suspension', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:ediel-live-without-valid-tenant', 'reconciliation', 'critical',
      'EDIEL lifecycle check failed', 0, 'platform_operations',
      'Repair the check before treating EDIEL state as healthy', null);
    v_results := v_results || jsonb_build_object('ediel_live_without_valid_tenant', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:ediel-live-without-valid-tenant', 'reconciliation', 'critical',
      'EDIEL lifecycle check failed', 1, 'platform_operations',
      'Repair the check before treating EDIEL state as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('ediel_live_without_valid_tenant_error', sqlstate);
  end;

  -- Tenant lifecycle projection must agree with the existing status model.
  begin
    select count(*) into v_count
    from public.companies company
    where company.id = p_company_id
      and company.lifecycle_status is distinct from case company.status
        when 'active' then 'active'
        when 'onboarding' then 'onboarding'
        when 'paused' then 'suspended'
        when 'suspended' then 'suspended'
        when 'archived' then 'closing'
        when 'pending_deletion' then 'closing'
        when 'closed' then 'closed'
        when 'deleted_test_only' then 'closed'
        else company.lifecycle_status
      end;
    perform public.canonical_set_architecture_finding(
      p_company_id, 'invalid-tenant-lifecycle-projection', 'tenant_lifecycle', 'critical',
      'Tenant status and lifecycle projection disagree', v_count, 'tenant_operations',
      'Use canonical_transition_tenant_lifecycle; do not patch lifecycle columns independently', null);
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:invalid-tenant-lifecycle-projection', 'reconciliation', 'critical',
      'Tenant lifecycle check failed', 0, 'platform_operations',
      'Repair the check before treating lifecycle state as healthy', null);
    v_results := v_results || jsonb_build_object('invalid_lifecycle', v_count);
  exception when others then
    perform public.canonical_set_architecture_finding(
      p_company_id, 'check-error:invalid-tenant-lifecycle-projection', 'reconciliation', 'critical',
      'Tenant lifecycle check failed', 1, 'platform_operations',
      'Repair the check before treating lifecycle state as healthy', sqlstate || ':' || sqlerrm);
    v_results := v_results || jsonb_build_object('invalid_lifecycle_error', sqlstate);
  end;

  return jsonb_build_object(
    'checked_at', now(),
    'companies', jsonb_build_object(p_company_id::text, v_results)
  );
end
$_$;

--
-- Name: canonical_run_hardening_preflight(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_run_hardening_preflight() RETURNS TABLE(check_key text, status text, affected_rows bigint, details jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  truncate public.canonical_hardening_preflight_results;

  insert into public.canonical_hardening_preflight_results(check_key,status,affected_rows,details)
  select 'companies_noncanonical_status',case when count(*)=0 then 'pass' else 'blocked' end,count(*),
    jsonb_build_object('action','review_each_tenant_status_without_active_fallback')
  from public.companies c
  where c.status is null or c.status not in (
    'onboarding','active','paused','suspended','archived','pending_deletion','closed','deleted_test_only'
  );

  insert into public.canonical_hardening_preflight_results(check_key,status,affected_rows,details)
  select 'ediel_test_runs_missing_company',case when count(*)=0 then 'pass' else 'blocked' end,count(*),
    jsonb_build_object('action','quarantine_and_resolve_without_guessing')
  from public.ediel_test_runs where company_id is null;

  insert into public.canonical_hardening_preflight_results(check_key,status,affected_rows,details)
  select 'ediel_test_run_messages_missing_company',case when count(*)=0 then 'pass' else 'blocked' end,count(*),
    jsonb_build_object('action','review_ediel_tenant_relation_quarantine')
  from public.ediel_test_run_messages where company_id is null;

  insert into public.canonical_hardening_preflight_results(check_key,status,affected_rows,details)
  select 'cross_tenant_run_message',case when count(*)=0 then 'pass' else 'blocked' end,count(*),
    jsonb_build_object('invariant','run_message_company_ids_must_match')
  from public.ediel_test_run_messages trm
  join public.ediel_test_runs r on r.id=trm.test_run_id
  join public.ediel_messages m on m.id=trm.ediel_message_id
  where trm.company_id is distinct from r.company_id or trm.company_id is distinct from m.company_id;

  insert into public.canonical_hardening_preflight_results(check_key,status,affected_rows,details)
  select 'application_reference_mismatch',case when count(*)=0 then 'pass' else 'blocked' end,count(*),
    jsonb_build_object('action','resolve_canonical_application_reference')
  from public.ediel_actor_settings
  where application_reference is distinct from default_application_reference;

  insert into public.canonical_hardening_preflight_results(check_key,status,affected_rows,details)
  select 'production_without_snapshot',case when count(*)=0 then 'pass' else 'blocked' end,count(*),
    jsonb_build_object('action','capture_snapshot_and_rerun_readiness_dry_run')
  from public.ediel_production_state
  where state in ('prepared','live') and configuration_snapshot_id is null;

  return query select r.check_key,r.status,r.affected_rows,r.details
  from public.canonical_hardening_preflight_results r order by r.check_key;
end;
$$;

--
-- Name: canonical_save_ediel_actor_profile(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_save_ediel_actor_profile(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := nullif(p_command->>'company_id', '')::uuid;
  v_actor_user_id uuid := nullif(p_command->>'actor_user_id', '')::uuid;
  v_idempotency_key text := p_command->>'idempotency_key';
  v_company public.companies%rowtype;
  v_actor_role text;
  v_environment text;
  v_profile public.ediel_actor_settings%rowtype;
  v_profile_count bigint;
  v_requested_profile_id uuid;
  v_defaults jsonb;
  v_command jsonb;
  v_hash text;
  v_existing public.canonical_command_results%rowtype;
  v_latest_snapshot public.ediel_configuration_snapshots%rowtype;
  v_result jsonb;
begin
  if not public.canonical_actor_is_authorized(v_company_id, v_actor_user_id, 'ediel.profile.write', false) then
    raise exception 'actor_not_authorized_for_ediel_profile';
  end if;
  if nullif(btrim(v_idempotency_key), '') is null then raise exception 'idempotency_key_required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_company_id::text || ':ediel.actor_profile.save:' || v_idempotency_key, 0));
  select * into v_company from public.companies where id = v_company_id for update;
  if not found then raise exception 'tenant_not_found'; end if;

  v_actor_role := lower(nullif(btrim(p_command->>'actor_role'), ''));
  if v_actor_role is null or v_actor_role not in (
    'supplier', 'electricity_supplier', 'grid_owner', 'energy_service_company',
    'balance_responsible_party', 'brp', 'system_supplier',
    'metering_point_operator', 'metering_data_responsible'
  ) then
    raise exception 'unsupported_actor_role:%', coalesce(v_actor_role, 'null');
  end if;

  v_defaults := jsonb_build_object(
    'company_id', v_company_id, 'company_name', v_company.name,
    'organization_number', v_company.org_number,
    'actor_role', v_actor_role,
    'ediel_id', v_company.ediel_id,
    'test_ediel_id', case when v_actor_role in ('supplier', 'electricity_supplier') then v_company.test_ediel_id end,
    'production_ediel_id', case when v_actor_role in ('supplier', 'electricity_supplier') then v_company.production_ediel_id end,
    'test_sender_sub_address', case when v_actor_role in ('supplier', 'electricity_supplier') then v_company.test_sender_sub_address end,
    'production_sender_sub_address', case when v_actor_role in ('supplier', 'electricity_supplier') then v_company.production_sender_sub_address end,
    'test_mailbox', case when v_actor_role in ('supplier', 'electricity_supplier') then v_company.test_mailbox end,
    'production_mailbox', case when v_actor_role in ('supplier', 'electricity_supplier') then v_company.production_mailbox end,
    'test_application_reference', case when v_actor_role in ('supplier', 'electricity_supplier') then v_company.test_application_reference end,
    'production_application_reference', case when v_actor_role in ('supplier', 'electricity_supplier') then v_company.production_application_reference end,
    'test_counterparty_ediel_id', case when v_actor_role in ('supplier', 'electricity_supplier') then v_company.test_counterparty_ediel_id end,
    'production_counterparty_ediel_id', case when v_actor_role in ('supplier', 'electricity_supplier') then v_company.production_counterparty_ediel_id end,
    'brp_name', v_company.brp_name, 'brp_ediel_id', v_company.brp_ediel_id,
    'brp_status', v_company.brp_status, 'esett_status', v_company.esett_status,
    'technical_contact_name', v_company.technical_contact_name,
    'technical_contact_email', v_company.technical_contact_email,
    'support_email', v_company.support_email,
    'billing_contact_email', v_company.billing_contact_email
  );

  foreach v_environment in array array['test', 'production'] loop
    select count(*) into v_profile_count from public.ediel_actor_settings
    where company_id = v_company_id and environment = v_environment and is_active = true
      and lower(coalesce(role, actor_role)) = v_actor_role;
    if v_profile_count > 1 then
      raise exception 'active_ediel_profile_identity_ambiguous:%', v_environment;
    end if;
    select a.* into v_profile
    from public.canonical_ediel_profile_identities i
    join public.ediel_actor_settings a on a.id = i.profile_id
    where i.company_id = v_company_id and i.environment = v_environment
      and i.actor_role = v_actor_role
      and a.company_id = i.company_id and a.environment = i.environment
      and lower(coalesce(a.role, a.actor_role)) = i.actor_role
      and a.is_active = true;
    if not found and v_profile_count = 1 then
      select * into v_profile from public.ediel_actor_settings
      where company_id = v_company_id and environment = v_environment and is_active = true
        and lower(coalesce(role, actor_role)) = v_actor_role;
      insert into public.canonical_ediel_profile_identities(company_id, environment, actor_role, profile_id, bound_by)
      values(v_company_id, v_environment, v_actor_role, v_profile.id, v_actor_user_id)
      on conflict (company_id, environment, actor_role) do update
      set profile_id = excluded.profile_id, bound_at = now(), bound_by = excluded.bound_by;
    end if;
    if p_command ? (v_environment || '_profile_id') then
      v_requested_profile_id := nullif(p_command->>(v_environment || '_profile_id'), '')::uuid;
      if v_profile.id is distinct from v_requested_profile_id then
        raise exception 'canonical_profile_identity_mismatch:%', v_environment;
      end if;
    end if;
    if v_profile.id is not null then
      v_defaults := v_defaults || jsonb_build_object(
        v_environment || '_profile_id', v_profile.id,
        v_environment || '_ediel_id', coalesce(v_profile.actor_ediel_id, v_profile.ediel_id),
        v_environment || '_sender_sub_address', coalesce(v_profile.sender_sub_address, v_profile.sender_subaddress),
        v_environment || '_application_reference', coalesce(v_profile.application_reference, v_profile.default_application_reference),
        v_environment || '_mailbox', v_profile.mailbox,
        'actor_role', coalesce(v_defaults->>'actor_role', v_profile.actor_role, v_profile.role),
        'brp_name', coalesce(v_defaults->>'brp_name', v_profile.brp_name),
        'brp_ediel_id', coalesce(v_defaults->>'brp_ediel_id', v_profile.brp_ediel_id),
        'brp_status', coalesce(v_defaults->>'brp_status', v_profile.brp_status),
        'esett_status', coalesce(v_defaults->>'esett_status', v_profile.esett_status),
        'smtp_from_email', v_profile.smtp_from_email
      );
    end if;
    v_profile := null;
    v_requested_profile_id := null;
  end loop;

  v_command := v_defaults || p_command;
  v_hash := public.canonical_json_sha256(v_command - 'actor_user_id');
  select * into v_existing from public.canonical_command_results
  where company_id = v_company_id and command_type = 'ediel.actor_profile.save'
    and idempotency_key = v_idempotency_key;
  if found then
    if v_existing.actor_user_id is distinct from v_actor_user_id then raise exception 'idempotency_actor_mismatch'; end if;
    if v_existing.request_hash <> v_hash then raise exception 'idempotency_key_payload_mismatch'; end if;
    return v_existing.result_payload;
  end if;

  v_result := public.canonical_save_ediel_actor_profile_v1_unchecked(v_command);
  update public.canonical_command_results
  set request_payload = v_command - 'actor_user_id', request_hash = v_hash
  where company_id = v_company_id and command_type = 'ediel.actor_profile.save'
    and idempotency_key = v_idempotency_key;

  foreach v_environment in array array['test', 'production'] loop
    update public.ediel_actor_settings a
    set actor_name = case when v_command ? (v_environment || '_actor_name')
          then nullif(v_command->>(v_environment || '_actor_name'), '') else a.actor_name end,
        legal_name = case when v_command ? (v_environment || '_actor_name')
          then nullif(v_command->>(v_environment || '_actor_name'), '') else a.legal_name end,
        sender_name = case when v_command ? (v_environment || '_sender_name')
          then nullif(v_command->>(v_environment || '_sender_name'), '') else a.sender_name end,
        organization_number = case when v_command ? (v_environment || '_organization_number')
          then nullif(v_command->>(v_environment || '_organization_number'), '') else a.organization_number end,
        sender_subaddress_prodat = case when v_command ? (v_environment || '_sender_subaddress_prodat')
          then nullif(v_command->>(v_environment || '_sender_subaddress_prodat'), '') else a.sender_subaddress_prodat end,
        sender_subaddress_utilts = case when v_command ? (v_environment || '_sender_subaddress_utilts')
          then nullif(v_command->>(v_environment || '_sender_subaddress_utilts'), '') else a.sender_subaddress_utilts end,
        receiver_subaddress = case when v_command ? (v_environment || '_receiver_subaddress')
          then nullif(v_command->>(v_environment || '_receiver_subaddress'), '') else a.receiver_subaddress end,
        smtp_reply_to_email = case when v_command ? (v_environment || '_smtp_reply_to_email')
          then nullif(v_command->>(v_environment || '_smtp_reply_to_email'), '') else a.smtp_reply_to_email end,
        default_transport_channel = case when v_command ? (v_environment || '_default_transport_channel')
          then nullif(v_command->>(v_environment || '_default_transport_channel'), '') else a.default_transport_channel end,
        default_timezone = case when v_command ? (v_environment || '_default_timezone')
          then (v_command->>(v_environment || '_default_timezone'))::integer else a.default_timezone end,
        default_charset = case when v_command ? (v_environment || '_default_charset')
          then nullif(upper(v_command->>(v_environment || '_default_charset')), '') else a.default_charset end,
        default_test_flag = case when v_command ? (v_environment || '_default_test_flag')
          then (v_command->>(v_environment || '_default_test_flag'))::integer else a.default_test_flag end,
        production_status = case when v_command ? (v_environment || '_production_status')
          then nullif(v_command->>(v_environment || '_production_status'), '') else a.production_status end,
        test_status = case when v_command ? (v_environment || '_test_status')
          then nullif(v_command->>(v_environment || '_test_status'), '') else a.test_status end,
        notes = case when v_command ? (v_environment || '_notes')
          then nullif(v_command->>(v_environment || '_notes'), '') else a.notes end,
        valid_from = case when v_command ? (v_environment || '_valid_from')
          then nullif(v_command->>(v_environment || '_valid_from'), '')::date else a.valid_from end,
        valid_to = case when v_command ? (v_environment || '_valid_to')
          then nullif(v_command->>(v_environment || '_valid_to'), '')::date else a.valid_to end,
        is_active = case when v_command ? (v_environment || '_is_active')
          then coalesce((v_command->>(v_environment || '_is_active'))::boolean, false) else a.is_active end,
        updated_by = v_actor_user_id,
        updated_at = now()
    from public.canonical_ediel_profile_identities i
    where i.company_id = v_company_id and i.environment = v_environment
      and i.actor_role = v_actor_role
      and i.profile_id = a.id and a.company_id = i.company_id and a.environment = i.environment;

    select count(*) into v_profile_count from public.ediel_actor_settings
    where company_id = v_company_id and environment = v_environment and is_active = true
      and lower(coalesce(role, actor_role)) = v_actor_role;
    if v_profile_count > 1 then raise exception 'active_ediel_profile_identity_ambiguous:%', v_environment; end if;
    if v_profile_count = 1 then
      select * into v_profile from public.ediel_actor_settings
      where company_id = v_company_id and environment = v_environment and is_active = true
        and lower(coalesce(role, actor_role)) = v_actor_role;
      insert into public.canonical_ediel_profile_identities(company_id, environment, actor_role, profile_id, bound_by)
      values(v_company_id, v_environment, v_actor_role, v_profile.id, v_actor_user_id)
      on conflict (company_id, environment, actor_role) do update
      set profile_id = excluded.profile_id, bound_at = now(), bound_by = excluded.bound_by;
    else
      delete from public.canonical_ediel_profile_identities
      where company_id = v_company_id and environment = v_environment
        and actor_role = v_actor_role;
    end if;
    v_profile := null;
  end loop;
  if v_command ? 'production_primary_route_id' or v_command ? 'test_primary_route_id' then
    update public.companies
    set ediel_primary_production_route_profile_id = case
          when v_command ? 'production_primary_route_id'
            then nullif(v_command->>'production_primary_route_id', '')::uuid
          else ediel_primary_production_route_profile_id end,
        ediel_primary_test_route_profile_id = case
          when v_command ? 'test_primary_route_id'
            then nullif(v_command->>'test_primary_route_id', '')::uuid
          else ediel_primary_test_route_profile_id end,
        updated_at = now()
    where id = v_company_id;
    perform public.canonical_capture_ediel_configuration_snapshot_v1_unchecked(
      v_company_id, v_actor_user_id, 'canonical_primary_route_changed'
    );
  end if;
  select * into v_latest_snapshot from public.ediel_configuration_snapshots
  where company_id = v_company_id order by snapshot_version desc limit 1;
  if found then
    v_result := v_result || jsonb_build_object(
      'configuration_snapshot_id', v_latest_snapshot.id,
      'configuration_hash', v_latest_snapshot.configuration_hash
    );
    update public.canonical_command_results set result_payload = v_result
    where company_id = v_company_id and command_type = 'ediel.actor_profile.save'
      and idempotency_key = v_idempotency_key;
  end if;
  return v_result;
end;
$$;

--
-- Name: canonical_save_ediel_actor_profile_v1_unchecked(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_save_ediel_actor_profile_v1_unchecked(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid := nullif(p_command->>'company_id', '')::uuid;
  v_actor_user_id uuid := nullif(p_command->>'actor_user_id', '')::uuid;
  v_idempotency_key text := p_command->>'idempotency_key';
  v_actor_role text := lower(nullif(btrim(p_command->>'actor_role'), ''));
  v_environment text;
  v_ediel_id text;
  v_profile_id uuid;
  v_snapshot public.ediel_configuration_snapshots%rowtype;
  v_existing jsonb;
  v_result jsonb;
begin
  if v_company_id is null or nullif(btrim(v_idempotency_key), '') is null then
    raise exception 'company_id_and_idempotency_key_required';
  end if;
  if v_actor_role is null or v_actor_role not in (
    'supplier', 'electricity_supplier', 'grid_owner', 'energy_service_company',
    'balance_responsible_party', 'brp', 'system_supplier',
    'metering_point_operator', 'metering_data_responsible'
  ) then
    raise exception 'unsupported_actor_role:%', coalesce(v_actor_role, 'null');
  end if;

  select result_payload into v_existing
  from public.canonical_command_results
  where company_id = v_company_id
    and command_type = 'ediel.actor_profile.save'
    and idempotency_key = v_idempotency_key;
  if found then return v_existing; end if;

  perform 1 from public.companies where id = v_company_id for update;
  if not found then raise exception 'tenant_not_found'; end if;

  perform set_config('gridex.skip_ediel_snapshot_trigger', 'on', true);

  -- Company-level Ediel fields describe the primary supplier identity. Other
  -- market roles are stored in actor profiles and must not overwrite it.
  if v_actor_role in ('supplier', 'electricity_supplier') then
    update public.companies set
      org_number = nullif(p_command->>'organization_number', ''),
      market_role = v_actor_role,
      actor_role = v_actor_role,
      ediel_id = nullif(upper(p_command->>'ediel_id'), ''),
      test_ediel_id = nullif(upper(p_command->>'test_ediel_id'), ''),
      production_ediel_id = nullif(upper(p_command->>'production_ediel_id'), ''),
      test_sender_sub_address = nullif(p_command->>'test_sender_sub_address', ''),
      production_sender_sub_address = nullif(p_command->>'production_sender_sub_address', ''),
      test_mailbox = nullif(p_command->>'test_mailbox', ''),
      production_mailbox = nullif(p_command->>'production_mailbox', ''),
      test_application_reference = nullif(upper(p_command->>'test_application_reference'), ''),
      production_application_reference = nullif(upper(p_command->>'production_application_reference'), ''),
      test_counterparty_ediel_id = nullif(upper(p_command->>'test_counterparty_ediel_id'), ''),
      production_counterparty_ediel_id = nullif(upper(p_command->>'production_counterparty_ediel_id'), ''),
      brp_name = nullif(p_command->>'brp_name', ''),
      brp_ediel_id = nullif(upper(p_command->>'brp_ediel_id'), ''),
      brp_status = coalesce(nullif(p_command->>'brp_status', ''), 'missing'),
      esett_status = coalesce(nullif(p_command->>'esett_status', ''), 'missing'),
      technical_contact_name = nullif(p_command->>'technical_contact_name', ''),
      technical_contact_email = nullif(p_command->>'technical_contact_email', ''),
      support_email = nullif(p_command->>'support_email', ''),
      billing_contact_email = nullif(p_command->>'billing_contact_email', ''),
      updated_at = now()
    where id = v_company_id;
  end if;

  foreach v_environment in array array['test', 'production'] loop
    v_ediel_id := nullif(upper(p_command->>(v_environment || '_ediel_id')), '');

    select a.id into v_profile_id
    from public.canonical_ediel_profile_identities i
    join public.ediel_actor_settings a on a.id = i.profile_id
    where i.company_id = v_company_id
      and i.environment = v_environment
      and i.actor_role = v_actor_role
      and a.company_id = i.company_id
      and a.environment = i.environment
      and lower(coalesce(a.role, a.actor_role)) = i.actor_role
      and a.is_active = true
    for update of a;

    if v_profile_id is null then
      select id into v_profile_id
      from public.ediel_actor_settings
      where company_id = v_company_id
        and environment = v_environment
        and lower(coalesce(role, actor_role)) = v_actor_role
        and is_active = true
      order by updated_at desc, id desc
      limit 1
      for update;
    end if;

    update public.ediel_actor_settings
    set is_active = false, updated_by = v_actor_user_id, updated_at = now()
    where company_id = v_company_id
      and environment = v_environment
      and lower(coalesce(role, actor_role)) = v_actor_role
      and is_active = true
      and id is distinct from v_profile_id;

    if v_ediel_id is null then
      update public.ediel_actor_settings
      set is_active = false, updated_by = v_actor_user_id, updated_at = now()
      where id = v_profile_id and company_id = v_company_id;
      delete from public.canonical_ediel_profile_identities
      where company_id = v_company_id and environment = v_environment
        and actor_role = v_actor_role;
      v_profile_id := null;
      continue;
    end if;

    if v_profile_id is null then
      insert into public.ediel_actor_settings(
        company_id, actor_name, sender_name, actor_role, role,
        actor_ediel_id, ediel_id, environment, is_active,
        sender_sub_address, sender_subaddress,
        default_application_reference, application_reference, mailbox,
        default_charset, default_timezone, default_test_flag,
        smtp_from_email, smtp_reply_to_email,
        brp_name, brp_ediel_id, brp_status, esett_status,
        created_by, updated_by, created_at, updated_at
      ) values (
        v_company_id, coalesce(nullif(p_command->>'company_name', ''), 'Aktör'),
        coalesce(nullif(p_command->>'company_name', ''), 'Aktör'),
        v_actor_role, v_actor_role, v_ediel_id, v_ediel_id,
        v_environment, true,
        nullif(p_command->>(v_environment || '_sender_sub_address'), ''),
        nullif(p_command->>(v_environment || '_sender_sub_address'), ''),
        nullif(upper(p_command->>(v_environment || '_application_reference')), ''),
        nullif(upper(p_command->>(v_environment || '_application_reference')), ''),
        nullif(p_command->>(v_environment || '_mailbox'), ''),
        'UNOC', 1, case when v_environment = 'production' then 0 else 1 end,
        nullif(p_command->>'smtp_from_email', ''),
        nullif(p_command->>'smtp_from_email', ''),
        nullif(p_command->>'brp_name', ''),
        nullif(upper(p_command->>'brp_ediel_id'), ''),
        coalesce(nullif(p_command->>'brp_status', ''), 'missing'),
        coalesce(nullif(p_command->>'esett_status', ''), 'missing'),
        v_actor_user_id, v_actor_user_id, now(), now()
      ) returning id into v_profile_id;
    else
      update public.ediel_actor_settings set
        actor_name = coalesce(nullif(p_command->>'company_name', ''), 'Aktör'),
        sender_name = coalesce(nullif(p_command->>'company_name', ''), 'Aktör'),
        actor_role = v_actor_role,
        role = v_actor_role,
        actor_ediel_id = v_ediel_id,
        ediel_id = v_ediel_id,
        is_active = true,
        sender_sub_address = nullif(p_command->>(v_environment || '_sender_sub_address'), ''),
        sender_subaddress = nullif(p_command->>(v_environment || '_sender_sub_address'), ''),
        default_application_reference = nullif(upper(p_command->>(v_environment || '_application_reference')), ''),
        application_reference = nullif(upper(p_command->>(v_environment || '_application_reference')), ''),
        mailbox = nullif(p_command->>(v_environment || '_mailbox'), ''),
        default_test_flag = case when v_environment = 'production' then 0 else 1 end,
        smtp_from_email = nullif(p_command->>'smtp_from_email', ''),
        smtp_reply_to_email = nullif(p_command->>'smtp_from_email', ''),
        brp_name = nullif(p_command->>'brp_name', ''),
        brp_ediel_id = nullif(upper(p_command->>'brp_ediel_id'), ''),
        brp_status = coalesce(nullif(p_command->>'brp_status', ''), 'missing'),
        esett_status = coalesce(nullif(p_command->>'esett_status', ''), 'missing'),
        updated_by = v_actor_user_id,
        updated_at = now()
      where id = v_profile_id and company_id = v_company_id;
    end if;

    insert into public.canonical_ediel_profile_identities(
      company_id, environment, actor_role, profile_id, bound_by
    ) values (
      v_company_id, v_environment, v_actor_role, v_profile_id, v_actor_user_id
    )
    on conflict (company_id, environment, actor_role) do update
    set profile_id = excluded.profile_id, bound_at = now(), bound_by = excluded.bound_by;
  end loop;

  perform set_config('gridex.skip_ediel_snapshot_trigger', 'off', true);
  v_snapshot := public.canonical_capture_ediel_configuration_snapshot_v1_unchecked(
    v_company_id, v_actor_user_id, 'actor_profile_updated'
  );

  insert into public.canonical_audit_events(
    company_id, event_type, aggregate_type, aggregate_id, actor_user_id,
    reason, idempotency_key, after_state, metadata
  ) values (
    v_company_id, 'EDIEL_ACTOR_PROFILE_UPDATED', 'company', v_company_id,
    v_actor_user_id, 'Aktörsprofil uppdaterad atomiskt.', v_idempotency_key,
    jsonb_build_object(
      'actor_role', v_actor_role,
      'configuration_snapshot_id', v_snapshot.id,
      'configuration_hash', v_snapshot.configuration_hash
    ), p_command
  );

  v_result := jsonb_build_object(
    'changed', true,
    'company_id', v_company_id,
    'actor_role', v_actor_role,
    'configuration_snapshot_id', v_snapshot.id,
    'configuration_hash', v_snapshot.configuration_hash
  );
  insert into public.canonical_command_results(
    company_id, command_type, idempotency_key,
    request_payload, result_payload, actor_user_id
  ) values (
    v_company_id, 'ediel.actor_profile.save', v_idempotency_key,
    p_command, v_result, v_actor_user_id
  );
  return v_result;
end;
$$;

--
-- Name: canonical_seed_company_capabilities(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_seed_company_capabilities(p_company_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  insert into public.company_capabilities(company_id,capability_code,enabled,readiness_status)
  select p_company_id, capability_code, false, 'not_configured'
  from unnest(array[
    'customer_intake','website_sales','api_sales','ediel_test','ediel_production',
    'webhooks','email_outbound','customer_automation','billing','facility_lookup'
  ]::text[]) capability_code
  on conflict(company_id,capability_code) do nothing;
$$;

--
-- Name: canonical_set_architecture_finding(uuid, text, text, text, text, bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_set_architecture_finding(p_company_id uuid, p_finding_key text, p_category text, p_severity text, p_title text, p_count bigint, p_owner text, p_repair_action text, p_check_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_count > 0 or p_check_error is not null then
    insert into public.platform_reconciliation_findings(
      company_id,finding_key,category,severity,entity_type,status,title,details,
      owner,repair_action,sla_due_at,check_error,first_detected_at,last_detected_at,
      created_at,updated_at
    ) values (
      p_company_id,p_finding_key,p_category,
      case when p_check_error is not null then 'critical' else p_severity end,
      'company','open',p_title,
      jsonb_build_object('count',p_count,'checked_at',now()),
      p_owner,p_repair_action,now()+interval '24 hours',p_check_error,
      now(),now(),now(),now()
    )
    on conflict(company_id,finding_key) do update
    set category=excluded.category,severity=excluded.severity,status='open',
        title=excluded.title,details=excluded.details,owner=excluded.owner,
        repair_action=excluded.repair_action,
        sla_due_at=coalesce(platform_reconciliation_findings.sla_due_at,excluded.sla_due_at),
        check_error=excluded.check_error,resolved_at=null,last_detected_at=now(),updated_at=now();
  else
    update public.platform_reconciliation_findings
    set status='resolved',resolved_at=coalesce(resolved_at,now()),check_error=null,updated_at=now()
    where company_id=p_company_id and finding_key=p_finding_key and status='open';
  end if;
end
$$;

--
-- Name: canonical_sync_company_ediel_projection_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_sync_company_ediel_projection_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_projection_status text;
begin
  v_projection_status := case new.state
    when 'live' then 'live'
    when 'paused' then 'paused'
    when 'blocked' then 'blocked'
    when 'prepared' then 'production_prepared'
    when 'retired' then 'blocked'
    when 'configuring' then 'not_ready'
    when 'disabled' then 'not_ready'
    else 'not_ready'
  end;

  update public.companies
     set production_status = v_projection_status,
         ediel_production_status = v_projection_status,
         live_ediel_enabled = new.state = 'live',
         ediel_production_enabled = new.state = 'live',
         operating_environment = case when new.state = 'live' then 'production' else operating_environment end,
         live_approved_by = coalesce(new.approved_by, live_approved_by),
         live_approved_at = coalesce(new.approved_at, live_approved_at),
         ediel_production_enabled_by = case
           when new.state = 'live' then coalesce(new.approved_by, ediel_production_enabled_by)
           else ediel_production_enabled_by
         end,
         ediel_production_enabled_at = case
           when new.state = 'live' then coalesce(new.approved_at, ediel_production_enabled_at)
           else ediel_production_enabled_at
         end,
         ediel_production_paused_by = case
           when new.state = 'paused' then new.paused_by
           when new.state = 'live' then null
           else ediel_production_paused_by
         end,
         ediel_production_paused_at = case
           when new.state = 'paused' then new.paused_at
           when new.state = 'live' then null
           else ediel_production_paused_at
         end,
         ediel_production_pause_reason = case
           when new.state = 'paused' then new.pause_reason
           when new.state = 'live' then null
           else ediel_production_pause_reason
         end,
         live_blocked_reason = case
           when new.state = 'blocked' then new.blocked_reason
           when new.state = 'paused' then coalesce(new.pause_reason, new.blocked_reason)
           when new.state = 'retired' then coalesce(new.blocked_reason, 'ediel_production_retired')
           when new.state in ('prepared', 'live') then null
           else live_blocked_reason
         end,
         ediel_first_live_send_approved_by = coalesce(new.first_live_send_approved_by, ediel_first_live_send_approved_by),
         ediel_first_live_send_approved_at = coalesce(new.first_live_send_approved_at, ediel_first_live_send_approved_at),
         updated_at = now()
   where id = new.company_id;

  return new;
end;
$$;

--
-- Name: FUNCTION canonical_sync_company_ediel_projection_v1(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.canonical_sync_company_ediel_projection_v1() IS 'Projects canonical ediel_production_state into legacy company compatibility fields after every canonical state change.';

--
-- Name: canonical_sync_provisioning_jobs_for_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_sync_provisioning_jobs_for_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status in ('paused','suspended','archived','pending_deletion','closed') then
    update public.company_provisioning_jobs job
    set status = 'blocked_tenant_state',
        lifecycle_blocked_by_tenant = true,
        lifecycle_previous_status = job.status,
        locked_at = null,
        locked_by = null,
        lease_token = null,
        last_error_code = 'tenant_lifecycle_blocked',
        last_error_message = 'Tenant lifecycle blocks provisioning work.',
        updated_at = now()
    where job.company_id = new.id
      and job.status in ('pending','retry');
  elsif new.status = 'active' then
    update public.company_provisioning_jobs job
    set status = case when job.lifecycle_previous_status in ('pending','retry') then job.lifecycle_previous_status else 'pending' end,
        lifecycle_blocked_by_tenant = false,
        lifecycle_previous_status = null,
        available_at = now(),
        last_error_code = null,
        last_error_message = null,
        updated_at = now()
    where job.company_id = new.id
      and job.status = 'blocked_tenant_state'
      and job.lifecycle_blocked_by_tenant;
  end if;
  return new;
end
$$;

--
-- Name: canonical_tenant_operation_decision(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_tenant_operation_decision(p_company_id uuid, p_operation text) RETURNS TABLE(allowed boolean, reason_code text, company_status text, capability_status text, production_status text, state_version bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_company public.companies%rowtype;
  v_capability text;
  v_capability_row public.company_capabilities%rowtype;
  v_production_status text;
  v_base_allowed boolean := false;
  v_evidence jsonb;
  v_api_bundle_active boolean := false;
  v_capability_ready boolean := false;
  v_effective_capability_status text;
begin
  select * into v_company
  from public.companies
  where id = p_company_id;

  if not found then
    return query select false, 'tenant_not_found', null::text, 'missing'::text, null::text, 0::bigint;
    return;
  end if;

  if to_regclass('public.ediel_production_state') is not null then
    execute 'select state from public.ediel_production_state where company_id = $1'
      into v_production_status using p_company_id;
  end if;

  v_production_status := coalesce(
    v_production_status,
    v_company.ediel_production_status,
    v_company.production_status,
    'disabled'
  );

  v_capability := case p_operation
    when 'email.send' then 'email_outbound'
    when 'webhook.deliver' then 'webhooks'
    when 'ediel.production.send' then 'ediel_production'
    when 'ediel.test.process' then 'ediel_test'
    when 'customer_automation.execute' then 'customer_automation'
    when 'facility_lookup.execute' then 'facility_lookup'
    when 'contract_channel.sell' then 'website_sales'
    when 'api_client.execute' then 'api_sales'
    else null
  end;

  if v_capability is not null then
    select * into v_capability_row
    from public.company_capabilities
    where company_id = p_company_id
      and capability_code = v_capability;

    v_capability_ready :=
      coalesce(v_capability_row.enabled, false)
      and coalesce(v_capability_row.readiness_status, 'missing') = 'ready';
  end if;

  if p_operation in (
    'api_client.execute',
    'contract_channel.sell',
    'customer_automation.execute',
    'facility_lookup.execute',
    'email.send',
    'webhook.deliver'
  ) then
    select exists (
      select 1
      from public.integration_api_clients c
      where c.company_id = p_company_id
        and c.status = 'active'
        and c.profile_key = 'tenant_website'
    ) into v_api_bundle_active;
  end if;

  v_effective_capability_status := case
    when v_capability is null then 'not_required'
    when v_capability_ready then coalesce(v_capability_row.readiness_status, 'ready')
    when v_api_bundle_active then 'api_bundle'
    else coalesce(v_capability_row.readiness_status, 'missing')
  end;

  v_base_allowed := case coalesce(v_company.status, '__unknown__')
    when 'onboarding' then p_operation in (
      'tenant.provisioning.execute',
      'ediel.test.process',
      'invitation.accept',
      'company_user.manage',
      'production.prepare',
      'production.pause'
    )
    when 'active' then p_operation in (
      'tenant.provisioning.execute',
      'email.send',
      'webhook.deliver',
      'ediel.production.send',
      'ediel.test.process',
      'customer_automation.execute',
      'facility_lookup.execute',
      'invitation.accept',
      'company_user.manage',
      'production.prepare',
      'production.activate',
      'production.pause',
      'production.resume',
      'contract_channel.sell',
      'api_client.execute'
    )
    else false
  end;

  if not v_base_allowed then
    return query select false,
      case coalesce(v_company.status, '__unknown__')
        when 'paused' then 'tenant_paused'
        when 'suspended' then 'tenant_suspended'
        when 'archived' then 'tenant_archived'
        when 'pending_deletion' then 'tenant_pending_deletion'
        when 'closed' then 'tenant_closed'
        when 'deleted_test_only' then 'tenant_deleted_test_only'
        when 'onboarding' then 'operation_not_allowed_during_onboarding'
        else 'tenant_status_unknown'
      end,
      v_company.status,
      v_effective_capability_status,
      v_production_status,
      v_company.lifecycle_state_version;
    return;
  end if;

  if v_capability is not null
     and not v_capability_ready
     and not v_api_bundle_active then
    return query select false,
      'capability_not_ready',
      v_company.status,
      v_effective_capability_status,
      v_production_status,
      v_company.lifecycle_state_version;
    return;
  end if;

  -- Customer/contract intake is deliberately decoupled from the Ediel send
  -- lock. A tenant may accept a valid contract while a production transport
  -- change is being revalidated. The downstream Ediel send remains fail-closed
  -- and will not leave the platform until its own gate is live again.
  if p_operation = 'ediel.production.send'
     and v_production_status <> 'live' then
    return query select false,
      'ediel_production_not_live',
      v_company.status,
      v_effective_capability_status,
      v_production_status,
      v_company.lifecycle_state_version;
    return;
  end if;

  if p_operation = 'ediel.production.send' then
    v_evidence := public.canonical_ediel_production_evidence_readiness(p_company_id);
    if coalesce((v_evidence->>'ready')::boolean, false) is not true then
      return query select false,
        'ediel_production_evidence_not_ready',
        v_company.status,
        v_effective_capability_status,
        v_production_status,
        v_company.lifecycle_state_version;
      return;
    end if;
  end if;

  return query select true,
    case when v_api_bundle_active and not v_capability_ready then 'allowed_by_tenant_api_bundle' else 'allowed' end,
    v_company.status,
    v_effective_capability_status,
    v_production_status,
    v_company.lifecycle_state_version;
end;
$_$;

--
-- Name: FUNCTION canonical_tenant_operation_decision(p_company_id uuid, p_operation text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.canonical_tenant_operation_decision(p_company_id uuid, p_operation text) IS 'Canonical tenant operation gate. Contract/customer intake is independent of temporary Ediel production send locks; actual Ediel production sends remain fail-closed on live state and certification evidence.';

--
-- Name: canonical_transition_ediel_production(uuid, text, bigint, uuid, uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_transition_ediel_production(p_company_id uuid, p_target_state text, p_expected_state_version bigint, p_configuration_snapshot_id uuid, p_readiness_check_id uuid, p_dry_run_id uuid, p_reason text, p_actor_user_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_permission text := case when p_target_state = 'paused' then 'ediel.production.pause' else 'ediel.production.activate' end;
  v_request jsonb := jsonb_build_object(
    'target_state', p_target_state, 'expected_state_version', p_expected_state_version,
    'configuration_snapshot_id', p_configuration_snapshot_id,
    'readiness_check_id', p_readiness_check_id, 'dry_run_id', p_dry_run_id,
    'reason', p_reason
  );
  v_hash text;
  v_existing public.canonical_command_results%rowtype;
  v_readiness jsonb;
  v_result jsonb;
begin
  if not public.canonical_actor_is_authorized(p_company_id, p_actor_user_id, v_permission, false) then
    raise exception 'actor_not_authorized_for_ediel_production_transition';
  end if;
  if nullif(btrim(p_idempotency_key), '') is null then raise exception 'idempotency_key_required'; end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_company_id::text || ':ediel.production.transition:' || p_idempotency_key, 0)
  );
  v_hash := public.canonical_json_sha256(v_request);

  select * into v_existing
  from public.canonical_command_results
  where company_id = p_company_id
    and command_type = 'ediel.production.transition'
    and idempotency_key = p_idempotency_key;

  if found then
    if v_existing.actor_user_id is distinct from p_actor_user_id then raise exception 'idempotency_actor_mismatch'; end if;
    if v_existing.request_hash <> v_hash then raise exception 'idempotency_key_payload_mismatch'; end if;
    return v_existing.result_payload;
  end if;

  if p_target_state in ('prepared', 'live') then
    v_readiness := public.canonical_company_readiness(
      p_company_id,
      p_configuration_snapshot_id,
      p_readiness_check_id,
      p_dry_run_id,
      p_target_state
    );
    if coalesce((v_readiness->>'ready')::boolean, false) is not true then
      raise exception 'canonical_readiness_blocked:%', v_readiness->'blockers';
    end if;
  end if;

  v_result := public.canonical_transition_ediel_production_v1_unchecked(
    p_company_id,
    p_target_state,
    p_expected_state_version,
    p_configuration_snapshot_id,
    p_readiness_check_id,
    p_dry_run_id,
    p_reason,
    p_actor_user_id,
    p_idempotency_key
  );

  update public.canonical_command_results
  set request_payload = v_request,
      request_hash = v_hash
  where company_id = p_company_id
    and command_type = 'ediel.production.transition'
    and idempotency_key = p_idempotency_key;

  return v_result;
end;
$$;

--
-- Name: canonical_transition_ediel_production_v1_unchecked(uuid, text, bigint, uuid, uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_transition_ediel_production_v1_unchecked(p_company_id uuid, p_target_state text, p_expected_state_version bigint, p_configuration_snapshot_id uuid, p_readiness_check_id uuid, p_dry_run_id uuid, p_reason text, p_actor_user_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company public.companies%rowtype;
  v_state public.ediel_production_state%rowtype;
  v_readiness public.ediel_production_readiness_checks%rowtype;
  v_dry_run public.ediel_go_live_events%rowtype;
  v_existing jsonb;
  v_changed boolean;
  v_next_version bigint;
  v_event_type text;
  v_domain_event_id uuid;
  v_result jsonb;
  v_lock boolean;
  v_configuration_snapshot_id uuid;
begin
  if p_company_id is null or nullif(btrim(p_idempotency_key),'') is null then
    raise exception 'company_id_and_idempotency_key_required';
  end if;
  if p_target_state not in ('disabled','configuring','prepared','live','paused','blocked','retired') then
    raise exception 'invalid_ediel_production_target_state:%', p_target_state;
  end if;

  select result_payload into v_existing
  from public.canonical_command_results
  where company_id=p_company_id
    and command_type='ediel.production.transition'
    and idempotency_key=p_idempotency_key;
  if found then return v_existing; end if;

  select * into v_company from public.companies where id=p_company_id for update;
  if not found then raise exception 'tenant_not_found'; end if;

  insert into public.ediel_production_state(company_id,state)
  values (p_company_id,'disabled') on conflict do nothing;
  select * into v_state from public.ediel_production_state where company_id=p_company_id for update;

  if p_expected_state_version is not null and v_state.state_version<>p_expected_state_version then
    raise exception 'ediel_production_state_version_conflict:expected=%,actual=%',
      p_expected_state_version,v_state.state_version;
  end if;

  if v_company.status is null or v_company.status not in (
    'onboarding','active','paused','suspended','archived',
    'pending_deletion','closed','deleted_test_only'
  ) then
    raise exception 'tenant_status_unknown_or_invalid';
  end if;
  if v_company.status in ('closed','archived','suspended','pending_deletion','deleted_test_only') then
    raise exception 'tenant_lifecycle_blocks_ediel_production:%',v_company.status;
  end if;
  if p_target_state in ('prepared','live') and v_company.status<>'active' then
    raise exception 'tenant_must_be_active_for_ediel_production:%',v_company.status;
  end if;
  if v_state.state='retired' and p_target_state<>'retired' then
    raise exception 'retired_ediel_production_is_terminal';
  end if;

  v_configuration_snapshot_id:=coalesce(p_configuration_snapshot_id,v_state.configuration_snapshot_id);

  if p_target_state in ('prepared','live') then
    if p_readiness_check_id is null then raise exception 'readiness_check_required'; end if;
    select * into v_readiness
    from public.ediel_production_readiness_checks
    where id=p_readiness_check_id and company_id=p_company_id;
    if not found then raise exception 'readiness_check_not_found_for_tenant'; end if;
    if v_readiness.status not in ('ready','warning','live')
       or jsonb_array_length(coalesce(v_readiness.blocking_issues,'[]'::jsonb))>0 then
      raise exception 'readiness_check_has_blockers';
    end if;
    if v_configuration_snapshot_id is null then raise exception 'configuration_snapshot_required'; end if;
    if v_readiness.configuration_snapshot_id is distinct from v_configuration_snapshot_id
       or coalesce(v_readiness.is_stale,false) then
      raise exception 'readiness_snapshot_is_stale_or_mismatched';
    end if;
  end if;

  if p_target_state='live' then
    if p_dry_run_id is null then raise exception 'current_dry_run_required'; end if;
    select * into v_dry_run
    from public.ediel_go_live_events
    where id=p_dry_run_id and company_id=p_company_id and event_type='production_dry_run';
    if not found then raise exception 'production_dry_run_not_found_for_tenant'; end if;
    if v_dry_run.to_status not in ('allowed','warning') then
      raise exception 'production_dry_run_not_approved';
    end if;
    if coalesce(v_dry_run.is_stale,false)
       or v_dry_run.configuration_snapshot_id is distinct from v_configuration_snapshot_id then
      raise exception 'production_dry_run_snapshot_is_stale_or_mismatched';
    end if;
    if coalesce(v_dry_run.expires_at,v_dry_run.created_at+interval '24 hours') <= now() then
      raise exception 'production_dry_run_expired';
    end if;
    if v_state.state not in ('prepared','paused','blocked','live') then
      raise exception 'production_must_be_prepared_before_live:%',v_state.state;
    end if;
  end if;

  v_changed := v_state.state is distinct from p_target_state
    or v_state.configuration_snapshot_id is distinct from v_configuration_snapshot_id
    or v_state.readiness_check_id is distinct from p_readiness_check_id
    or v_state.dry_run_id is distinct from p_dry_run_id;

  if not v_changed then
    v_result:=jsonb_build_object('changed',false,'company_id',p_company_id,'state',v_state.state,'state_version',v_state.state_version);
    insert into public.canonical_command_results(company_id,command_type,idempotency_key,request_payload,result_payload,actor_user_id)
    values(p_company_id,'ediel.production.transition',p_idempotency_key,
      jsonb_build_object('target_state',p_target_state,'reason',p_reason),v_result,p_actor_user_id)
    on conflict do nothing;
    return v_result;
  end if;

  v_next_version:=v_state.state_version+1;
  update public.ediel_production_state
  set state=p_target_state,
      configuration_snapshot_id=v_configuration_snapshot_id,
      readiness_check_id=coalesce(p_readiness_check_id,readiness_check_id),
      dry_run_id=coalesce(p_dry_run_id,dry_run_id),
      state_version=v_next_version,
      approved_by=case when p_target_state='live' then p_actor_user_id else approved_by end,
      approved_at=case when p_target_state='live' then now() else approved_at end,
      paused_by=case when p_target_state='paused' then p_actor_user_id when p_target_state='live' then null else paused_by end,
      paused_at=case when p_target_state='paused' then now() when p_target_state='live' then null else paused_at end,
      pause_reason=case when p_target_state='paused' then p_reason when p_target_state='live' then null else pause_reason end,
      blocked_reason=case when p_target_state='blocked' then p_reason when p_target_state in ('prepared','live') then null else blocked_reason end,
      last_idempotency_key=p_idempotency_key,
      updated_at=now()
  where company_id=p_company_id;

  v_lock:=p_target_state<>'live';
  insert into public.ediel_send_locks(
    company_id,environment,locked,locked_reason,locked_by,locked_at,
    unlocked_by,unlocked_at,updated_at
  ) values (
    p_company_id,'production',v_lock,
    case when v_lock then coalesce(p_reason,'Canonical production state is not live.') else null end,
    case when v_lock then p_actor_user_id else null end,
    case when v_lock then now() else null end,
    case when not v_lock then p_actor_user_id else null end,
    case when not v_lock then now() else null end,
    now()
  ) on conflict (company_id,environment) do update
  set locked=excluded.locked,locked_reason=excluded.locked_reason,
      locked_by=excluded.locked_by,locked_at=excluded.locked_at,
      unlocked_by=excluded.unlocked_by,unlocked_at=excluded.unlocked_at,
      updated_at=excluded.updated_at;

  -- Compatibility projections. Runtime decisions must use ediel_production_state.
  update public.companies
  set operating_environment=case when p_target_state='live' then 'production' else operating_environment end,
      production_status=case p_target_state when 'prepared' then 'production_prepared' else p_target_state end,
      ediel_production_status=case p_target_state when 'prepared' then 'production_prepared' else p_target_state end,
      live_ediel_enabled=p_target_state='live',
      ediel_production_enabled=p_target_state='live',
      live_approved_by=case when p_target_state='live' then p_actor_user_id else live_approved_by end,
      live_approved_at=case when p_target_state='live' then now() else live_approved_at end,
      ediel_production_enabled_by=case when p_target_state='live' then p_actor_user_id else ediel_production_enabled_by end,
      ediel_production_enabled_at=case when p_target_state='live' then now() else ediel_production_enabled_at end,
      ediel_production_paused_by=case when p_target_state='paused' then p_actor_user_id when p_target_state='live' then null else ediel_production_paused_by end,
      ediel_production_paused_at=case when p_target_state='paused' then now() when p_target_state='live' then null else ediel_production_paused_at end,
      ediel_production_pause_reason=case when p_target_state='paused' then p_reason when p_target_state='live' then null else ediel_production_pause_reason end,
      live_blocked_reason=case when p_target_state in ('blocked','paused') then p_reason when p_target_state in ('prepared','live') then null else live_blocked_reason end,
      updated_at=now()
  where id=p_company_id;

  v_event_type:=case p_target_state
    when 'prepared' then 'EDIEL_PRODUCTION_PREPARED'
    when 'live' then case when v_state.state='paused' then 'EDIEL_PRODUCTION_RESUMED' else 'EDIEL_PRODUCTION_ACTIVATED' end
    when 'paused' then 'EDIEL_PRODUCTION_PAUSED'
    else 'EDIEL_PRODUCTION_STATE_CHANGED'
  end;

  insert into public.canonical_audit_events(
    company_id,event_type,aggregate_type,aggregate_id,state_version,
    actor_user_id,reason,idempotency_key,before_state,after_state,metadata
  ) values (
    p_company_id,v_event_type,'ediel_production',p_company_id,v_next_version,
    p_actor_user_id,p_reason,p_idempotency_key,
    jsonb_build_object('state',v_state.state,'state_version',v_state.state_version),
    jsonb_build_object('state',p_target_state,'state_version',v_next_version),
    jsonb_build_object('readiness_check_id',p_readiness_check_id,'dry_run_id',p_dry_run_id,'configuration_snapshot_id',v_configuration_snapshot_id)
  );

  insert into public.canonical_domain_events(
    company_id,event_type,aggregate_type,aggregate_id,aggregate_version,
    idempotency_key,payload,created_by
  ) values (
    p_company_id,v_event_type,'ediel_production',p_company_id,v_next_version,
    p_idempotency_key,
    jsonb_build_object('from_state',v_state.state,'to_state',p_target_state,'reason',p_reason,
      'readiness_check_id',p_readiness_check_id,'dry_run_id',p_dry_run_id,
      'configuration_snapshot_id',v_configuration_snapshot_id),
    p_actor_user_id
  ) returning id into v_domain_event_id;

  insert into public.canonical_event_outbox(company_id,domain_event_id,topic,idempotency_key,payload)
  values(p_company_id,v_domain_event_id,'ediel.production.state.changed',p_idempotency_key,
    jsonb_build_object('company_id',p_company_id,'state',p_target_state,'state_version',v_next_version));

  insert into public.ediel_go_live_events(
    company_id,event_type,from_status,to_status,reason,actor_user_id,readiness_check_id,metadata
  ) values (
    p_company_id,lower(v_event_type),v_state.state,p_target_state,p_reason,p_actor_user_id,p_readiness_check_id,
    jsonb_build_object('canonical',true,'state_version',v_next_version,'dry_run_id',p_dry_run_id,'configuration_snapshot_id',v_configuration_snapshot_id)
  );

  v_result:=jsonb_build_object('changed',true,'company_id',p_company_id,'previous_state',v_state.state,
    'state',p_target_state,'state_version',v_next_version,'domain_event_id',v_domain_event_id);
  insert into public.canonical_command_results(company_id,command_type,idempotency_key,request_payload,result_payload,actor_user_id)
  values(p_company_id,'ediel.production.transition',p_idempotency_key,
    jsonb_build_object('target_state',p_target_state,'reason',p_reason),v_result,p_actor_user_id);
  return v_result;
end;
$$;

--
-- Name: canonical_transition_tenant_lifecycle(uuid, text, bigint, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_transition_tenant_lifecycle(p_company_id uuid, p_target_status text, p_expected_state_version bigint, p_reason text, p_actor_user_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_cached jsonb;
  v_current_status text;
  v_current_version bigint;
  v_result jsonb;
  v_session_count bigint := 0;
  v_client_count bigint := 0;
  v_portal_count bigint := 0;
begin
  if nullif(btrim(coalesce(p_idempotency_key,'')),'') is null then
    raise exception using errcode='22023',message='tenant_lifecycle_idempotency_key_required';
  end if;

  select result_payload into v_cached
  from public.canonical_command_results
  where company_id=p_company_id
    and command_type='tenant.lifecycle.transition'
    and idempotency_key=p_idempotency_key;
  if found then
    return v_cached || jsonb_build_object(
      'offboarding_policy','canonical_lifecycle_offboarding_v1',
      'idempotent_replay',true
    );
  end if;

  select lifecycle_status,lifecycle_state_version
  into v_current_status,v_current_version
  from public.companies
  where id=p_company_id
  for update;
  if not found then raise exception 'tenant_not_found'; end if;

  if v_current_status=p_target_status then
    return jsonb_build_object(
      'ok',true,
      'changed',false,
      'code','tenant_lifecycle_unchanged',
      'company_id',p_company_id,
      'status',p_target_status,
      'state_version',v_current_version,
      'offboarding_policy','canonical_lifecycle_offboarding_v1'
    );
  end if;

  select count(*) into v_client_count
  from public.integration_api_clients
  where company_id=p_company_id and deleted_at is null
    and status in ('active','paused');

  select count(*) into v_portal_count
  from public.customer_portal_identities
  where company_id=p_company_id and status in ('active','disabled');

  if p_target_status='closed' then
    select count(*) into v_session_count
    from auth.sessions session
    where session.user_id in (
      select membership.user_id
      from public.company_memberships membership
      where membership.company_id=p_company_id
        and membership.status='active'
        and coalesce(membership.is_active,true)
    );
  end if;

  v_result := public.canonical_transition_tenant_lifecycle_v4_pre_replay_guard(
    p_company_id,p_target_status,p_expected_state_version,p_reason,
    p_actor_user_id,p_idempotency_key
  );

  if coalesce((v_result->>'changed')::boolean,false) then
    insert into public.canonical_audit_events(
      company_id,event_type,aggregate_type,aggregate_id,actor_user_id,reason,
      idempotency_key,after_state
    ) values (
      p_company_id,'TENANT_LIFECYCLE_SIDE_EFFECTS_APPLIED','company',p_company_id,
      p_actor_user_id,p_reason,p_idempotency_key||':side-effects',
      jsonb_build_object(
        'target_status',p_target_status,
        'sessions_revoked',v_session_count,
        'api_clients_evaluated',v_client_count,
        'portal_identities_evaluated',v_portal_count
      )
    );
  end if;

  return v_result || jsonb_build_object(
    'offboarding_policy','canonical_lifecycle_offboarding_v1'
  );
end
$$;

--
-- Name: canonical_transition_tenant_lifecycle_v1_unchecked(uuid, text, bigint, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_transition_tenant_lifecycle_v1_unchecked(p_company_id uuid, p_target_status text, p_expected_state_version bigint, p_reason text, p_actor_user_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_company public.companies%rowtype;
  v_existing jsonb;
  v_changed boolean;
  v_next_version bigint;
  v_event_id uuid;
  v_result jsonb;
  v_allowed boolean := false;
begin
  if p_company_id is null or nullif(btrim(p_idempotency_key), '') is null then
    raise exception 'company_id_and_idempotency_key_required';
  end if;
  if p_target_status not in (
    'onboarding','active','paused','suspended','archived',
    'pending_deletion','closed','deleted_test_only'
  ) then
    raise exception 'invalid_tenant_target_status:%', p_target_status;
  end if;

  select result_payload into v_existing
  from public.canonical_command_results
  where company_id = p_company_id
    and command_type = 'tenant.lifecycle.transition'
    and idempotency_key = p_idempotency_key;
  if found then return v_existing; end if;

  select * into v_company from public.companies where id = p_company_id for update;
  if not found then raise exception 'tenant_not_found'; end if;
  if p_expected_state_version is not null
     and v_company.lifecycle_state_version <> p_expected_state_version then
    raise exception 'tenant_state_version_conflict:expected=%,actual=%',
      p_expected_state_version, v_company.lifecycle_state_version;
  end if;

  v_changed := v_company.status is distinct from p_target_status;
  if not v_changed then
    v_result := jsonb_build_object(
      'changed', false, 'company_id', p_company_id, 'status', v_company.status,
      'state_version', v_company.lifecycle_state_version
    );
    insert into public.canonical_command_results(
      company_id, command_type, idempotency_key, request_payload,
      result_payload, actor_user_id
    ) values (
      p_company_id, 'tenant.lifecycle.transition', p_idempotency_key,
      jsonb_build_object('target_status', p_target_status, 'reason', p_reason),
      v_result, p_actor_user_id
    ) on conflict do nothing;
    return v_result;
  end if;

  v_allowed := case v_company.status
    when 'onboarding' then p_target_status in ('active','paused','suspended','archived','pending_deletion','closed','deleted_test_only')
    when 'active' then p_target_status in ('paused','suspended','archived','pending_deletion','closed')
    when 'paused' then p_target_status in ('active','suspended','archived','pending_deletion','closed')
    when 'suspended' then p_target_status in ('active','paused','archived','pending_deletion','closed')
    when 'archived' then p_target_status in ('pending_deletion','closed')
    when 'pending_deletion' then p_target_status in ('closed','deleted_test_only')
    when 'closed' then false
    when 'deleted_test_only' then false
    else false
  end;
  if not v_allowed then
    raise exception 'invalid_tenant_lifecycle_transition:%->%', v_company.status, p_target_status;
  end if;

  v_next_version := v_company.lifecycle_state_version + 1;
  update public.companies
  set status = p_target_status,
      lifecycle_state_version = v_next_version,
      lifecycle_last_transition_at = now(),
      lifecycle_last_transition_by = p_actor_user_id,
      lifecycle_last_idempotency_key = p_idempotency_key,
      status_reason = p_reason,
      updated_at = now(),
      closed_at = case when p_target_status = 'closed' then coalesce(closed_at, now()) else closed_at end,
      closed_by = case when p_target_status = 'closed' then coalesce(closed_by, p_actor_user_id) else closed_by end,
      closure_reason = case when p_target_status = 'closed' then coalesce(closure_reason, p_reason) else closure_reason end
  where id = p_company_id;

  if exists (select 1 from information_schema.columns where table_schema='public' and table_name='companies' and column_name='is_active') then
    execute 'update public.companies set is_active = $2 where id = $1'
      using p_company_id, p_target_status = 'active';
  end if;
  if exists (select 1 from information_schema.columns where table_schema='public' and table_name='companies' and column_name='is_paused') then
    execute 'update public.companies set is_paused = $2 where id = $1'
      using p_company_id, p_target_status = 'paused';
  end if;

  if p_target_status in ('paused','suspended','archived','pending_deletion','closed')
     and to_regclass('public.company_invitations') is not null then
    update public.company_invitations
    set status = 'invitation_revoked', updated_at = now()
    where company_id = p_company_id and status in ('pending','invited');
  end if;

  insert into public.canonical_audit_events(
    company_id,event_type,aggregate_type,aggregate_id,state_version,
    actor_user_id,reason,idempotency_key,before_state,after_state
  ) values (
    p_company_id,'TENANT_LIFECYCLE_CHANGED','company',p_company_id,v_next_version,
    p_actor_user_id,p_reason,p_idempotency_key,
    jsonb_build_object('status',v_company.status,'state_version',v_company.lifecycle_state_version),
    jsonb_build_object('status',p_target_status,'state_version',v_next_version)
  );

  insert into public.canonical_domain_events(
    company_id,event_type,aggregate_type,aggregate_id,aggregate_version,
    idempotency_key,payload,created_by
  ) values (
    p_company_id,'TENANT_LIFECYCLE_CHANGED','company',p_company_id,v_next_version,
    p_idempotency_key,
    jsonb_build_object('from_status',v_company.status,'to_status',p_target_status,'reason',p_reason),
    p_actor_user_id
  ) returning id into v_event_id;

  insert into public.canonical_event_outbox(
    company_id,domain_event_id,topic,idempotency_key,payload
  ) values (
    p_company_id,v_event_id,'tenant.lifecycle.changed',p_idempotency_key,
    jsonb_build_object('company_id',p_company_id,'status',p_target_status,'state_version',v_next_version)
  );

  v_result := jsonb_build_object(
    'changed', true, 'company_id', p_company_id,
    'previous_status', v_company.status, 'status', p_target_status,
    'state_version', v_next_version, 'domain_event_id', v_event_id
  );
  insert into public.canonical_command_results(
    company_id,command_type,idempotency_key,request_payload,result_payload,actor_user_id
  ) values (
    p_company_id,'tenant.lifecycle.transition',p_idempotency_key,
    jsonb_build_object('target_status',p_target_status,'reason',p_reason),
    v_result,p_actor_user_id
  );
  return v_result;
end;
$_$;

--
-- Name: canonical_transition_tenant_lifecycle_v3_pre_offboarding(uuid, text, bigint, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_transition_tenant_lifecycle_v3_pre_offboarding(p_company_id uuid, p_target_status text, p_expected_state_version bigint, p_reason text, p_actor_user_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_request jsonb := jsonb_build_object(
    'target_status', p_target_status,
    'expected_state_version', p_expected_state_version,
    'reason', p_reason
  );
  v_hash text;
  v_existing public.canonical_command_results%rowtype;
  v_result jsonb;
begin
  if not public.canonical_actor_is_authorized(
    p_company_id,
    p_actor_user_id,
    'tenant.lifecycle.transition',
    true
  ) then
    raise exception 'actor_not_authorized_for_tenant_lifecycle';
  end if;

  if nullif(btrim(p_idempotency_key), '') is null then
    raise exception 'idempotency_key_required';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(
      p_company_id::text || ':tenant.lifecycle.transition:' || p_idempotency_key,
      0
    )
  );

  v_hash := public.canonical_json_sha256(v_request);

  select *
  into v_existing
  from public.canonical_command_results
  where company_id = p_company_id
    and command_type = 'tenant.lifecycle.transition'
    and idempotency_key = p_idempotency_key;

  if found then
    if v_existing.actor_user_id is distinct from p_actor_user_id then
      raise exception 'idempotency_actor_mismatch';
    end if;
    if v_existing.request_hash <> v_hash then
      raise exception 'idempotency_key_payload_mismatch';
    end if;
    return v_existing.result_payload;
  end if;

  v_result := public.canonical_transition_tenant_lifecycle_v1_unchecked(
    p_company_id,
    p_target_status,
    p_expected_state_version,
    p_reason,
    p_actor_user_id,
    p_idempotency_key
  );

  -- request_payload and request_hash must move together. The canonical hash
  -- trigger validates this pair and will continue to reject tampering.
  update public.canonical_command_results
  set request_payload = v_request,
      request_hash = v_hash
  where company_id = p_company_id
    and command_type = 'tenant.lifecycle.transition'
    and idempotency_key = p_idempotency_key;

  return v_result;
end;
$$;

--
-- Name: FUNCTION canonical_transition_tenant_lifecycle_v3_pre_offboarding(p_company_id uuid, p_target_status text, p_expected_state_version bigint, p_reason text, p_actor_user_id uuid, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.canonical_transition_tenant_lifecycle_v3_pre_offboarding(p_company_id uuid, p_target_status text, p_expected_state_version bigint, p_reason text, p_actor_user_id uuid, p_idempotency_key text) IS 'Canonical tenant lifecycle wrapper with actor authorization and request-bound idempotency; binds enriched request payload and hash atomically.';

--
-- Name: canonical_transition_tenant_lifecycle_v4_pre_replay_guard(uuid, text, bigint, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_transition_tenant_lifecycle_v4_pre_replay_guard(p_company_id uuid, p_target_status text, p_expected_state_version bigint, p_reason text, p_actor_user_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_readiness jsonb;
  v_blockers jsonb := '[]'::jsonb;
  v_result jsonb;
begin
  if not public.canonical_actor_is_authorized(
    p_company_id,
    p_actor_user_id,
    'tenant.lifecycle.transition',
    true
  ) then
    raise exception using errcode = '42501', message = 'actor_not_authorized_for_tenant_lifecycle';
  end if;

  if p_target_status = 'active'
     and to_regprocedure('public.gridex_tenant_activation_readiness(uuid)') is not null then
    v_readiness := public.gridex_tenant_activation_readiness(p_company_id);
    if not coalesce((v_readiness->>'ready')::boolean, false) then
      return jsonb_build_object(
        'changed', false,
        'code', 'tenant_not_operationally_ready',
        'blocking_reasons', coalesce(v_readiness->'blocking_reasons', '[]'::jsonb),
        'readiness', v_readiness
      );
    end if;
  end if;

  if p_target_status = 'closed' then
    if exists (
      select 1 from public.customer_contracts contract
      where contract.company_id = p_company_id
        and contract.status in ('active','signed','current')
    ) then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'tenant_has_active_customer_contracts',
        'message', 'Aktiva kundavtal måste överföras eller avslutas.'
      ));
    end if;
    if exists (
      select 1 from public.supplier_switch_requests request
      where request.company_id = p_company_id
        and request.status not in ('completed','failed','cancelled','rejected')
    ) then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'tenant_has_open_supplier_switches',
        'message', 'Pågående leverantörsbyten måste slutföras.'
      ));
    end if;
    if exists (
      select 1 from public.billing_underlays underlay
      where underlay.company_id = p_company_id
        and underlay.status not in ('completed','exported','cancelled','rejected')
    ) then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'tenant_has_unsettled_billing',
        'message', 'Ofärdig fakturering måste regleras.'
      ));
    end if;
    if jsonb_array_length(v_blockers) > 0 then
      return jsonb_build_object(
        'changed', false,
        'code', 'tenant_closure_blocked',
        'blocking_reasons', v_blockers
      );
    end if;
  end if;

  v_result := public.canonical_transition_tenant_lifecycle_v3_pre_offboarding(
    p_company_id,
    p_target_status,
    p_expected_state_version,
    p_reason,
    p_actor_user_id,
    p_idempotency_key
  );

  if p_target_status in ('paused','suspended','archived','pending_deletion','closed') then
    update public.integration_api_clients client
    set status = case when p_target_status = 'closed' then 'revoked' else 'paused' end,
        revoked_at = case when p_target_status = 'closed' then coalesce(client.revoked_at, now()) else client.revoked_at end,
        revoked_by = case when p_target_status = 'closed' then p_actor_user_id else client.revoked_by end,
        revoke_reason = case when p_target_status = 'closed' then p_reason else client.revoke_reason end,
        metadata = coalesce(client.metadata, '{}'::jsonb) || jsonb_build_object(
          'lifecycle_paused_by_tenant', true,
          'lifecycle_previous_status', coalesce(
            client.metadata->>'lifecycle_previous_status',
            client.status
          ),
          'lifecycle_status', p_target_status,
          'lifecycle_transition_at', now()
        ),
        updated_at = now()
    where client.company_id = p_company_id
      and client.deleted_at is null
      and (
        client.status = 'active'
        or (
          p_target_status = 'closed'
          and client.status = 'paused'
          and coalesce((client.metadata->>'lifecycle_paused_by_tenant')::boolean, false)
        )
      );

    update public.webhook_subscriptions subscription
    set lifecycle_paused_by_tenant = true,
        lifecycle_previous_status = subscription.status,
        status = case when p_target_status = 'closed' then 'disabled' else 'paused' end,
        updated_at = now()
    where subscription.company_id = p_company_id
      and subscription.status = 'active';

    update public.tenant_contract_channels channel
    set lifecycle_paused_by_tenant = true,
        lifecycle_previous_status = channel.status,
        status = case when p_target_status = 'closed' then 'ended' else 'paused' end,
        valid_to = case when p_target_status = 'closed' then coalesce(channel.valid_to, now()) else channel.valid_to end,
        updated_by = p_actor_user_id,
        updated_at = now()
    from public.tenant_contract_assignments assignment
    where channel.assignment_id = assignment.id
      and assignment.company_id = p_company_id
      and channel.status = 'active';

    update public.company_provisioning_jobs job
    set status = 'blocked_tenant_state',
        lifecycle_blocked_by_tenant = true,
        lifecycle_previous_status = job.status,
        claimed_at = null,
        last_error_code = 'tenant_lifecycle_blocked',
        last_error_details = coalesce(job.last_error_details, '{}'::jsonb)
          || jsonb_build_object('tenant_status', p_target_status),
        updated_at = now()
    where job.company_id = p_company_id
      and job.status = 'pending';

    update public.customer_operation_jobs job
    set status = case when p_target_status = 'closed' then 'cancelled' else 'blocked' end,
        lifecycle_blocked_by_tenant = true,
        lifecycle_previous_status = job.status,
        locked_at = null,
        locked_by = null,
        last_error_code = 'tenant_lifecycle_blocked',
        last_error_message = 'Tenant lifecycle blocks scheduled business work.',
        updated_at = now()
    where job.company_id = p_company_id
      and job.status = 'queued';

    update public.customer_portal_identities identity
    set status = 'disabled',
        metadata = coalesce(identity.metadata, '{}'::jsonb) || jsonb_build_object(
          'lifecycle_paused_by_tenant', true,
          'lifecycle_previous_status', identity.status,
          'lifecycle_status', p_target_status
        ),
        updated_at = now()
    where identity.company_id = p_company_id
      and identity.status = 'active';

    if p_target_status = 'closed' then
      delete from auth.sessions session
      where session.user_id in (
        select membership.user_id
        from public.company_memberships membership
        where membership.company_id = p_company_id
          and membership.status = 'active'
          and coalesce(membership.is_active, true)
      );
    end if;
  elsif p_target_status = 'active' then
    update public.integration_api_clients client
    set status = 'active',
        metadata = coalesce(client.metadata, '{}'::jsonb)
          - 'lifecycle_paused_by_tenant'
          - 'lifecycle_previous_status'
          - 'lifecycle_status'
          - 'lifecycle_transition_at',
        updated_at = now()
    where client.company_id = p_company_id
      and client.status = 'paused'
      and client.launch_ready is true
      and coalesce((client.metadata->>'lifecycle_paused_by_tenant')::boolean, false);

    update public.webhook_subscriptions subscription
    set status = 'active',
        lifecycle_paused_by_tenant = false,
        lifecycle_previous_status = null,
        updated_at = now()
    where subscription.company_id = p_company_id
      and subscription.status = 'paused'
      and subscription.lifecycle_paused_by_tenant
      and subscription.lifecycle_previous_status = 'active';

    update public.tenant_contract_channels channel
    set status = 'active',
        lifecycle_paused_by_tenant = false,
        lifecycle_previous_status = null,
        updated_by = p_actor_user_id,
        updated_at = now()
    from public.tenant_contract_assignments assignment
    where channel.assignment_id = assignment.id
      and assignment.company_id = p_company_id
      and channel.status = 'paused'
      and channel.lifecycle_paused_by_tenant
      and channel.lifecycle_previous_status = 'active';

    update public.company_provisioning_jobs job
    set status = job.lifecycle_previous_status,
        lifecycle_blocked_by_tenant = false,
        lifecycle_previous_status = null,
        available_at = now(),
        last_error_code = null,
        last_error_details = '{}'::jsonb,
        updated_at = now()
    where job.company_id = p_company_id
      and job.status = 'blocked_tenant_state'
      and job.lifecycle_blocked_by_tenant
      and job.lifecycle_previous_status = 'pending';

    update public.customer_operation_jobs job
    set status = job.lifecycle_previous_status,
        lifecycle_blocked_by_tenant = false,
        lifecycle_previous_status = null,
        run_after = now(),
        last_error = null,
        last_error_code = null,
        last_error_message = null,
        updated_at = now()
    where job.company_id = p_company_id
      and job.status = 'blocked'
      and job.lifecycle_blocked_by_tenant
      and job.lifecycle_previous_status = 'queued';

    update public.customer_portal_identities identity
    set status = 'active',
        metadata = coalesce(identity.metadata, '{}'::jsonb)
          - 'lifecycle_paused_by_tenant'
          - 'lifecycle_previous_status'
          - 'lifecycle_status',
        updated_at = now()
    where identity.company_id = p_company_id
      and identity.status = 'disabled'
      and coalesce((identity.metadata->>'lifecycle_paused_by_tenant')::boolean, false)
      and identity.metadata->>'lifecycle_previous_status' = 'active';
  end if;

  return v_result || jsonb_build_object(
    'offboarding_policy', 'canonical_lifecycle_offboarding_v1'
  );
end
$$;

--
-- Name: ediel_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.ediel_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid,
    ediel_message_id uuid NOT NULL,
    source_message_id uuid,
    status text DEFAULT 'prepared'::text NOT NULL,
    priority integer DEFAULT 100 NOT NULL,
    lock_key text NOT NULL,
    message_family text,
    message_code text,
    ack_outcome text,
    environment text DEFAULT 'test'::text NOT NULL,
    route_profile_id uuid,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    queued_at timestamp with time zone,
    sent_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    updated_by uuid,
    locked_at timestamp with time zone,
    locked_by text,
    send_attempt_count integer DEFAULT 0 NOT NULL,
    current_send_attempt_id uuid,
    route_contract_fingerprint text,
    route_contract_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    receiver_ediel_id text,
    receiver_subaddress text,
    certificate_fingerprint text,
    intent_id uuid,
    rule_profile_key text,
    rule_profile_version_id uuid,
    rule_profile_version text,
    rule_pack_checksum text,
    rule_pack_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    immutable_payload_hash text,
    generation integer DEFAULT 1 NOT NULL,
    blocked_reason text,
    blocked_at timestamp with time zone,
    company_status_snapshot text,
    operation_decision_snapshot jsonb,
    CONSTRAINT ediel_outbox_generation_check CHECK ((generation > 0)),
    CONSTRAINT ediel_outbox_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'prepared'::text, 'queued'::text, 'sending'::text, 'sent'::text, 'failed'::text, 'superseded'::text, 'blocked'::text, 'blocked_tenant_state'::text, 'delivery_uncertain'::text])))
);

--
-- Name: COLUMN ediel_outbox.intent_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ediel_outbox.intent_id IS 'EdielMessageIntent that produced this outbox item (null for legacy rows).';

--
-- Name: claim_ediel_outbox_item(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_ediel_outbox_item(p_outbox_item_id uuid, p_worker_id text, p_actor_user_id uuid) RETURNS SETOF public.ediel_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_outbox_item_id is null or nullif(trim(p_worker_id),'') is null or p_actor_user_id is null then
    raise exception 'ediel_outbox_claim_arguments_required' using errcode='22023';
  end if;
  return query
  with claimed as (
    update public.ediel_outbox o
       set status='sending',locked_at=now(),locked_by=p_worker_id,
           attempts=coalesce(o.attempts,0)+1,
           send_attempt_count=coalesce(o.send_attempt_count,0)+1,
           current_send_attempt_id=gen_random_uuid(),updated_by=p_actor_user_id,updated_at=now()
     where o.id=p_outbox_item_id
       and o.company_id is not null
       and o.status in ('prepared','queued')
       and exists(
         select 1 from public.ediel_messages m
         where m.id=o.ediel_message_id and m.company_id=o.company_id and m.direction='outbound'
           and m.rule_profile_version_id is not null and nullif(m.rule_pack_checksum,'') is not null
       )
     returning o.*
  ) select * from claimed;
end; $$;

--
-- Name: claim_ediel_outbox_items(text, uuid, integer, text, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_ediel_outbox_items(p_environment text DEFAULT NULL::text, p_company_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 25, p_worker_id text DEFAULT 'ediel-outbox-engine'::text, p_stale_after interval DEFAULT '00:10:00'::interval) RETURNS SETOF public.ediel_outbox
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.ediel_outbox
     set status = 'delivery_uncertain',
         last_error = coalesce(last_error, 'stale_sending_lock_requires_transport_reconciliation'),
         locked_at = null,
         locked_by = null,
         updated_at = now()
   where status = 'sending'
     and locked_at < now() - p_stale_after
     and (p_environment is null or environment = p_environment)
     and (p_company_id is null or company_id = p_company_id);

  return query
  with candidates as (
    select id
    from public.ediel_outbox
    where status in ('prepared', 'queued')
      and (locked_at is null or locked_at < now() - p_stale_after)
      and (p_environment is null or environment = p_environment)
      and (p_company_id is null or company_id = p_company_id)
    order by priority asc, created_at asc
    limit greatest(1, least(coalesce(p_limit, 25), 100))
    for update skip locked
  ), updated as (
    update public.ediel_outbox o
       set status = 'sending',
           locked_at = now(),
           locked_by = p_worker_id,
           attempts = coalesce(o.attempts, 0) + 1,
           send_attempt_count = coalesce(o.send_attempt_count, 0) + 1,
           current_send_attempt_id = gen_random_uuid(),
           updated_at = now()
     where o.id in (select id from candidates)
     returning o.*
  )
  select * from updated;
end;
$$;

--
-- Name: inbound_processing_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.inbound_processing_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid,
    mailbox_id uuid,
    inbound_email_message_id uuid,
    status text DEFAULT 'queued'::text NOT NULL,
    step text,
    attempts_count integer DEFAULT 0 NOT NULL,
    locked_at timestamp with time zone,
    locked_by text,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    error_message text,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    review_owner text,
    review_priority text,
    review_reason text,
    review_sla_due_at timestamp with time zone,
    review_resolution text,
    review_resolved_at timestamp with time zone,
    CONSTRAINT inbound_processing_jobs_review_priority_check CHECK (((review_priority IS NULL) OR (review_priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'critical'::text]))))
);

--
-- Name: COLUMN inbound_processing_jobs.review_owner; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inbound_processing_jobs.review_owner IS 'Operational owner for manual-review work. This is an operational responsibility, not a fabricated user identity.';

--
-- Name: COLUMN inbound_processing_jobs.review_sla_due_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.inbound_processing_jobs.review_sla_due_at IS 'Explicit SLA deadline for unresolved manual-review work.';

--
-- Name: claim_inbound_processing_jobs(text, integer, text, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_inbound_processing_jobs(p_environment text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_worker_id text DEFAULT 'inbound-mail-engine'::text, p_stale_after interval DEFAULT '00:10:00'::interval) RETURNS SETOF public.inbound_processing_jobs
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  return query
  with candidates as (
    select j.id
    from public.inbound_processing_jobs j
    left join public.inbound_email_messages m on m.id = j.inbound_email_message_id
    where (
      j.status in ('queued', 'retry', 'received')
      or (j.status = 'processing' and j.locked_at < now() - p_stale_after)
    )
      and (j.locked_at is null or j.locked_at < now() - p_stale_after)
      and (p_environment is null or coalesce(m.environment, 'test') = p_environment)
    order by j.created_at asc
    limit greatest(1, least(coalesce(p_limit, 50), 200))
    -- FOR UPDATE OF j: never lock the nullable side of the LEFT JOIN.
    for update of j skip locked
  ), updated as (
    update public.inbound_processing_jobs j
       set status = 'processing',
           step = 'processor_claimed',
           locked_at = now(),
           locked_by = p_worker_id,
           started_at = now(),
           finished_at = null,
           attempts_count = coalesce(j.attempts_count, 0) + 1,
           error_message = case when j.status = 'processing' then coalesce(j.error_message, 'stale_inbound_lock_reclaimed') else null end,
           updated_at = now()
     where j.id in (select id from candidates)
     returning j.*
  )
  select * from updated;
end;
$$;

--
-- Name: cleanup_energy_geodata_staging_v1(integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_energy_geodata_staging_v1(p_retention_days integer DEFAULT NULL::integer, p_dry_run boolean DEFAULT true) RETURNS TABLE(candidate_versions bigint, candidate_features bigint, candidate_bytes bigint, deleted_features bigint, dry_run boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_retention_days integer;
  v_candidate_versions bigint := 0;
  v_candidate_features bigint := 0;
  v_candidate_bytes bigint := 0;
  v_deleted_features bigint := 0;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'energy_geodata_cleanup_service_role_required' using errcode = '42501';
  end if;

  select coalesce(
    p_retention_days,
    (
      select retention_days
      from public.gridex_data_retention_policies
      where data_category = 'energy_geodata_staging'
        and is_enabled
    )
  ) into v_retention_days;

  if v_retention_days is null or v_retention_days < 1 or v_retention_days > 3650 then
    raise exception 'energy_geodata_cleanup_retention_days_invalid' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('energy-geodata-staging-cleanup', 0));

  with candidates as (
    select s.*
    from public.energy_geodata_features_staging s
    join public.energy_geodata_versions v on v.id = s.geodata_version_id
    where v.status in ('failed', 'superseded')
      and coalesce(v.completed_at, v.updated_at, v.created_at)
        < now() - (v_retention_days * interval '1 day')
  )
  select
    count(distinct geodata_version_id),
    count(*),
    coalesce(sum(pg_column_size(candidates.*)), 0)
  into
    v_candidate_versions,
    v_candidate_features,
    v_candidate_bytes
  from candidates;

  if not p_dry_run then
    delete from public.energy_geodata_features_staging s
    using public.energy_geodata_versions v
    where v.id = s.geodata_version_id
      and v.status in ('failed', 'superseded')
      and coalesce(v.completed_at, v.updated_at, v.created_at)
        < now() - (v_retention_days * interval '1 day');
    get diagnostics v_deleted_features = row_count;
  end if;

  candidate_versions := v_candidate_versions;
  candidate_features := v_candidate_features;
  candidate_bytes := v_candidate_bytes;
  deleted_features := v_deleted_features;
  dry_run := p_dry_run;
  return next;
end;
$$;

--
-- Name: FUNCTION cleanup_energy_geodata_staging_v1(p_retention_days integer, p_dry_run boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cleanup_energy_geodata_staging_v1(p_retention_days integer, p_dry_run boolean) IS 'Dry-run-first cleanup of expired failed/superseded geodata staging payloads. Never targets importing or verified versions; service role only.';

--
-- Name: ediel_configuration_change_snapshot_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_configuration_change_snapshot_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
begin
  if current_setting('gridex.skip_ediel_snapshot_trigger', true) = 'on' then
    if tg_level = 'STATEMENT' then return null; end if;
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;

  if tg_level = 'STATEMENT' then
    if tg_table_name not in ('ediel_rule_versions', 'ediel_rule_packs', 'ediel_message_profiles') then
      return null;
    end if;

    for v_company_id in
      select c.id
      from public.companies c
      where c.status = 'active'
        and (
          exists(select 1 from public.ediel_production_state ps where ps.company_id = c.id)
          or exists(select 1 from public.ediel_actor_settings eas where eas.company_id = c.id)
        )
      order by c.id
    loop
      perform public.canonical_capture_ediel_configuration_snapshot_v1_unchecked(
        v_company_id,
        auth.uid(),
        tg_table_name || '_changed'
      );
    end loop;
    return null;
  end if;

  if tg_op = 'DELETE' then
    v_company_id := old.company_id;
  else
    v_company_id := new.company_id;
  end if;

  if v_company_id is not null then
    perform public.canonical_capture_ediel_configuration_snapshot_v1_unchecked(
      v_company_id,
      auth.uid(),
      tg_table_name || '_changed'
    );
  end if;

  if tg_op = 'DELETE' then return old; else return new; end if;
end;
$$;

--
-- Name: ensure_customer_invoice_reference_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_customer_invoice_reference_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
begin
  if tg_op = 'UPDATE'
     and new.company_id is not distinct from old.company_id
     and new.id is not distinct from old.id then
    new.invoice_reference := old.invoice_reference;
    return new;
  end if;
  new.invoice_reference := 'invoice_' || substr(
    translate(
      rtrim(encode(extensions.digest(convert_to(
        'gridex-public-reference:v1:' || new.company_id::text || ':invoice:' || new.id::text,
        'UTF8'
      ), 'sha256'::text), 'base64'), '='),
      '+/', '-_'
    ),
    1,
    32
  );
  return new;
end;
$$;

--
-- Name: gridex_acquire_automation_lock(text, uuid, uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_acquire_automation_lock(p_lock_key text, p_lock_token uuid, p_company_id uuid DEFAULT NULL::uuid, p_ttl_seconds integer DEFAULT 3600, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_expires timestamptz;
begin
  if nullif(btrim(p_lock_key), '') is null or p_lock_token is null then
    raise exception 'lock_key_and_token_required' using errcode = '22023';
  end if;
  if p_ttl_seconds < 30 or p_ttl_seconds > 86400 then
    raise exception 'lock_ttl_out_of_range' using errcode = '22023';
  end if;
  v_expires := v_now + make_interval(secs => p_ttl_seconds);

  delete from public.automation_locks where expires_at <= v_now;
  insert into public.automation_locks(lock_key, company_id, lock_token, locked_at, expires_at, metadata)
  values (btrim(p_lock_key), p_company_id, p_lock_token, v_now, v_expires, coalesce(p_metadata, '{}'::jsonb))
  on conflict (lock_key) do nothing;
  return found;
end;
$$;

--
-- Name: gridex_actor_has_company_permission(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_actor_has_company_permission(p_actor_user_id uuid, p_company_id uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select p_actor_user_id is not null and p_company_id is not null
  and exists(
    select 1 from auth.users u
    where u.id = p_actor_user_id and u.deleted_at is null
      and (u.banned_until is null or u.banned_until <= now())
  )
  and (
    exists(
      select 1 from public.admin_users au
      where au.user_id = p_actor_user_id
        and coalesce(au.is_active, true)
        and lower(coalesce(au.role, '')) in ('super_admin', 'superadmin', 'platform_superadmin')
    )
    or exists(
      select 1
      from public.user_roles ur left join public.roles r on r.id = ur.role_id
      where ur.user_id = p_actor_user_id and ur.company_id is null
        and coalesce(ur.status, 'active') = 'active' and coalesce(ur.is_active, true)
        and lower(coalesce(ur.role, r.key, r.name, '')) in ('super_admin', 'superadmin', 'platform_superadmin')
    )
    or (
      exists(
        select 1 from public.company_memberships cm
        join public.companies c on c.id = cm.company_id
        where cm.user_id = p_actor_user_id and cm.company_id = p_company_id
          and coalesce(cm.status, 'active') = 'active' and coalesce(cm.is_active, true)
          and coalesce(c.is_active, true)
          and coalesce(c.status, 'active') not in ('archived', 'suspended', 'pending_deletion', 'deleted')
      )
      and p_permission = any(
        public.gridex_get_user_permissions_in_company(p_actor_user_id, p_company_id)
      )
    )
  )
$$;

--
-- Name: FUNCTION gridex_actor_has_company_permission(p_actor_user_id uuid, p_company_id uuid, p_permission text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_actor_has_company_permission(p_actor_user_id uuid, p_company_id uuid, p_permission text) IS 'F-17: resolves the permission in the company being asked about. Backs the storage policies on customer documents.';

--
-- Name: gridex_actor_readiness_backfill(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_actor_readiness_backfill(p_run_type text DEFAULT 'nightly_backfill'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run_id uuid;
  v_actors int := 0;
  v_routes int := 0;
  v_certs jsonb;
begin
  insert into public.platform_actor_readiness_runs(run_type, status, metadata)
  values (coalesce(p_run_type, 'nightly_backfill'), 'running', jsonb_build_object('source', 'gridex_actor_readiness_backfill'))
  returning id into v_run_id;

  update public.platform_actor_identifiers i
  set is_verified = true,
      metadata = coalesce(i.metadata, '{}'::jsonb) || jsonb_build_object('auto_verified_from_registry_at', now(), 'auto_readiness_run_id', v_run_id),
      updated_at = now()
  where i.identifier_type in ('EdielId','EIC','SvKId','OrgNo')
    and coalesce(i.source, '') in ('companies_xml','xml_actor_registry','xml_import','svk_esett_actor_registry_match')
    and coalesce(i.is_verified, false) = false;

  update public.platform_market_actors a
  set status = 'active',
      match_status = case when exists (
        select 1 from public.platform_actor_identifiers i
        where i.actor_id = a.id and i.identifier_type in ('EdielId','EIC','SvKId') and i.is_verified = true
      ) then 'verified' else a.match_status end,
      visible_to_tenants = case when exists (
        select 1 from public.platform_actor_roles r
        where r.actor_id = a.id and r.actor_role in ('grid_owner','electricity_supplier') and r.is_active = true
      ) then true else a.visible_to_tenants end,
      verified_at = case when a.verified_at is null and exists (
        select 1 from public.platform_actor_identifiers i
        where i.actor_id = a.id and i.identifier_type in ('EdielId','EIC','SvKId') and i.is_verified = true
      ) then now() else a.verified_at end,
      metadata = coalesce(a.metadata, '{}'::jsonb) || jsonb_build_object('auto_readiness_backfilled_at', now(), 'auto_readiness_run_id', v_run_id),
      updated_at = now()
  where a.status in ('active','needs_review')
    and exists (select 1 from public.platform_actor_roles r where r.actor_id = a.id and r.is_active = true);

  get diagnostics v_actors = row_count;

  update public.platform_actor_routes r
  set status = 'active',
      is_verified = true,
      auto_send_allowed = false,
      metadata = coalesce(r.metadata, '{}'::jsonb) || jsonb_build_object(
        'verification_status', 'auto_verified_from_actor_registry',
        'auto_readiness_checked_at', now(),
        'auto_readiness_run_id', v_run_id,
        'auto_send_policy', 'requires_send_readiness_before_enable'
      ),
      updated_at = now()
  from public.platform_actor_identifiers i
  where i.actor_id = r.actor_id
    and i.identifier_type = 'EdielId'
    and i.is_verified = true
    and r.status in ('needs_review','active')
    and coalesce(r.is_verified, false) = false
    and upper(r.message_family) in ('PRODAT','UTILTS')
    and r.environment in ('test','production')
    and upper(coalesce(r.communication_type, 'SMTP')) = 'SMTP'
    and nullif(trim(coalesce(r.communication_address, '')), '') is not null
    and r.party_id = i.identifier_value
    and r.interchange_party_id = i.identifier_value
    and (r.valid_to is null or r.valid_to >= current_date);

  get diagnostics v_routes = row_count;

  v_certs := public.gridex_refresh_actor_certificate_statuses('certificate_refresh');
  perform public.gridex_apply_actor_auto_send_readiness(v_run_id);

  update public.platform_actor_readiness_runs
  set status = 'completed', finished_at = now(), checked_actor_count = v_actors, checked_route_count = v_routes,
      metadata = metadata || jsonb_build_object('cert_refresh', v_certs)
  where id = v_run_id;

  return jsonb_build_object('ok', true, 'run_id', v_run_id, 'actors_backfilled', v_actors, 'routes_verified', v_routes, 'cert_refresh', v_certs);
exception when others then
  if v_run_id is not null then
    update public.platform_actor_readiness_runs
    set status = 'failed', finished_at = now(), failed_count = 1, metadata = metadata || jsonb_build_object('error', sqlerrm)
    where id = v_run_id;
  end if;
  raise;
end;
$$;

--
-- Name: gridex_address_complete(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_address_complete(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_country text := coalesce(p_value->>'country_code', '');
  v_postal text := coalesce(p_value->>'postal_code', '');
begin
  if length(btrim(coalesce(p_value->>'address_line_1', ''))) < 3
     or length(btrim(coalesce(p_value->>'city', ''))) < 2
     or v_country !~ '^[A-Z]{2}$' then
    return false;
  end if;
  if v_country = 'SE' then
    return v_postal ~ '^[0-9]{3} [0-9]{2}$';
  end if;
  return length(btrim(v_postal)) between 2 and 16;
end
$_$;

--
-- Name: gridex_address_is_complete(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_address_is_complete(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select public.gridex_address_complete(coalesce(p_value, '{}'::jsonb))
$$;

