--
-- Name: gridex_company_launch_blocker_reasons_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_company_launch_blocker_reasons_v WITH (security_invoker='true') AS
 SELECT c.id AS company_id,
    'missing_facility_id'::text AS reason_key,
    'Saknar anläggnings-ID'::text AS reason_label,
    ( SELECT count(*) AS count
           FROM public.customer_sites s
          WHERE ((s.company_id = c.id) AND (NULLIF(TRIM(BOTH FROM COALESCE(s.facility_id, ''::text)), ''::text) IS NULL))) AS issue_count
   FROM public.companies c
UNION ALL
 SELECT c.id AS company_id,
    'missing_grid_owner'::text AS reason_key,
    'Saknar verifierad nätägare'::text AS reason_label,
    ( SELECT count(*) AS count
           FROM public.customer_sites s
          WHERE ((s.company_id = c.id) AND (s.grid_owner_id IS NULL))) AS issue_count
   FROM public.companies c
UNION ALL
 SELECT c.id AS company_id,
    'missing_grid_area'::text AS reason_key,
    'Saknar nätområdeskod'::text AS reason_label,
    ( SELECT count(*) AS count
           FROM public.customer_sites s
          WHERE ((s.company_id = c.id) AND (NULLIF(TRIM(BOTH FROM COALESCE(s.grid_area_code, ''::text)), ''::text) IS NULL))) AS issue_count
   FROM public.companies c
UNION ALL
 SELECT c.id AS company_id,
    'missing_price_area_code'::text AS reason_key,
    'Saknar SE-område'::text AS reason_label,
    ( SELECT count(*) AS count
           FROM public.customer_sites s
          WHERE ((s.company_id = c.id) AND (NULLIF(TRIM(BOTH FROM COALESCE(s.price_area_code, ''::text)), ''::text) IS NULL))) AS issue_count
   FROM public.companies c
UNION ALL
 SELECT c.id AS company_id,
    'missing_metering_identifier'::text AS reason_key,
    'Mätpunkt saknar identifierare'::text AS reason_label,
    ( SELECT count(*) AS count
           FROM public.metering_points m
          WHERE ((m.company_id = c.id) AND (NULLIF(TRIM(BOTH FROM COALESCE(m.metering_point_id, m.meter_point_id, ''::text)), ''::text) IS NULL))) AS issue_count
   FROM public.companies c
UNION ALL
 SELECT c.id AS company_id,
    'missing_power_of_attorney'::text AS reason_key,
    'Saknar aktiv fullmakt'::text AS reason_label,
    ( SELECT count(*) AS count
           FROM public.supplier_switch_requests s
          WHERE ((s.company_id = c.id) AND (s.power_of_attorney_id IS NULL) AND (COALESCE(s.status, ''::text) <> ALL (ARRAY['completed'::text, 'cancelled'::text])))) AS issue_count
   FROM public.companies c
UNION ALL
 SELECT c.id AS company_id,
    'negative_aperak_or_z02'::text AS reason_key,
    'Negativ APERAK/Z02 olöst'::text AS reason_label,
    ( SELECT count(*) AS count
           FROM public.ediel_business_errors e
          WHERE ((e.company_id = c.id) AND (e.status <> ALL (ARRAY['resolved'::text, 'ignored'::text])) AND (e.business_error = ANY (ARRAY['negative_aperak'::text, 'z02_rejected'::text, 'object_not_identified'::text, 'facility_rejected'::text])))) AS issue_count
   FROM public.companies c
UNION ALL
 SELECT c.id AS company_id,
    'billing_blocked'::text AS reason_key,
    'Fakturering blockerad'::text AS reason_label,
    ( SELECT count(*) AS count
           FROM public.billing_underlays b
          WHERE ((b.company_id = c.id) AND (COALESCE(b.readiness_status, b.status) = ANY (ARRAY['blocked'::text, 'failed'::text, 'needs_review'::text])))) AS issue_count
   FROM public.companies c;

