--
-- Name: company_dashboard_summary_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.company_dashboard_summary_v WITH (security_invoker='true') AS
 SELECT id AS company_id,
    name AS company_name,
    ( SELECT count(*) AS count
           FROM public.customers x
          WHERE ((x.company_id = c.id) AND (COALESCE(x.source, ''::text) <> 'ediel_portal_test'::text) AND (COALESCE(x.status, ''::text) <> ALL (ARRAY['archived'::text, 'deleted'::text, 'deleted_test_only'::text, 'pending_deletion'::text])))) AS customers_total,
    ( SELECT count(*) AS count
           FROM public.customer_contracts x
          WHERE (x.company_id = c.id)) AS contracts_total,
    ( SELECT count(*) AS count
           FROM public.customer_sites x
          WHERE (x.company_id = c.id)) AS sites_total,
    ( SELECT count(*) AS count
           FROM public.metering_points x
          WHERE (x.company_id = c.id)) AS metering_points_total,
    ( SELECT count(*) AS count
           FROM public.customer_operation_tasks x
          WHERE ((x.company_id = c.id) AND (x.status = 'open'::text))) AS open_tasks,
    ( SELECT count(*) AS count
           FROM public.grid_owner_data_requests x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['sent'::text, 'waiting_response'::text, 'queued'::text, 'pending'::text])))) AS open_grid_owner_requests,
    ( SELECT count(*) AS count
           FROM public.supplier_switch_requests x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['open'::text, 'draft'::text, 'queued'::text, 'submitted'::text, 'accepted'::text, 'cancellation_requested'::text, 'cancellation_sent'::text, 'manual_followup_required'::text])))) AS open_switches,
    ( SELECT count(*) AS count
           FROM public.outbound_requests x
          WHERE (x.company_id = c.id)) AS outbound_requests_total,
    ( SELECT count(*) AS count
           FROM public.metering_values x
          WHERE (x.company_id = c.id)) AS metering_values_total,
    ( SELECT count(*) AS count
           FROM public.billing_underlays x
          WHERE (x.company_id = c.id)) AS billing_underlays_total,
    ( SELECT count(*) AS count
           FROM public.supplier_switch_requests x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['draft'::text, 'queued'::text, 'submitted'::text, 'accepted'::text, 'cancellation_requested'::text, 'cancellation_sent'::text, 'manual_followup_required'::text])))) AS ongoing_supplier_switches,
    ( SELECT count(*) AS count
           FROM public.grid_owner_data_requests x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['sent'::text, 'waiting_response'::text, 'queued'::text])))) AS waiting_for_grid_owner,
    ( SELECT count(*) AS count
           FROM public.ediel_messages x
          WHERE ((x.company_id = c.id) AND (x.ack_outcome = 'negative'::text))) AS negative_acknowledgements,
    ( SELECT count(*) AS count
           FROM public.data_quality_issues x
          WHERE ((x.company_id = c.id) AND (x.status = 'open'::text) AND (x.issue_type = 'missing_metering_values'::text))) AS missing_metering_values,
    ( SELECT count(*) AS count
           FROM public.customer_operation_tasks x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['open'::text, 'in_progress'::text, 'blocked'::text])))) AS customers_action_required,
    ( SELECT count(*) AS count
           FROM public.metering_values x
          WHERE ((x.company_id = c.id) AND (x.created_at >= (now() - '7 days'::interval)))) AS latest_metering_values,
    ( SELECT count(*) AS count
           FROM public.customer_contracts x
          WHERE ((x.company_id = c.id) AND (x.ends_at >= CURRENT_DATE) AND (x.ends_at <= (CURRENT_DATE + '30 days'::interval)))) AS upcoming_terminations,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['needs_review'::text, 'partially_created'::text, 'failed'::text])))) AS pending_customer_applications,
    ( SELECT count(*) AS count
           FROM public.billing_underlays x
          WHERE ((x.company_id = c.id) AND (COALESCE(x.readiness_status, x.status) = ANY (ARRAY['blocked'::text, 'failed'::text, 'needs_review'::text])))) AS billing_blocked_or_failed,
    ( SELECT count(*) AS count
           FROM public.integration_api_requests x
          WHERE ((x.company_id = c.id) AND (COALESCE(x.status_code, 200) >= 400))) AS api_errors,
    ( SELECT count(*) AS count
           FROM public.webhook_deliveries x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['failed'::text, 'dead'::text, 'dead_letter'::text, 'retrying'::text])))) AS webhook_failures,
    ( SELECT COALESCE(sum(r.issue_count), (0)::numeric) AS "coalesce"
           FROM public.gridex_company_launch_blocker_reasons_v r
          WHERE ((r.company_id = c.id) AND (r.issue_count > 0))) AS customers_blocked_or_data_issues,
    ( SELECT count(*) AS count
           FROM public.gridex_route_readiness_v x
          WHERE (x.readiness_status = ANY (ARRAY['critical_missing_route'::text, 'recommended_missing_route'::text, 'not_sendable'::text, 'needs_review'::text]))) AS route_missing_or_not_ready
   FROM public.companies c;

--
-- Name: gridex_admin_dashboard_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_admin_dashboard_summary(p_company_id uuid) RETURNS SETOF public.company_dashboard_summary_v
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select *
  from public.company_dashboard_summary_v
  where company_id = p_company_id
$$;

--
-- Name: gridex_apply_actor_auto_send_readiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_apply_actor_auto_send_readiness(p_existing_run_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run_id uuid;
  v_enabled int := 0;
  v_disabled int := 0;
begin
  if p_existing_run_id is null then
    insert into public.platform_actor_readiness_runs(run_type, status, metadata)
    values ('auto_send_apply', 'running', jsonb_build_object('source', 'gridex_apply_actor_auto_send_readiness', 'scope', 'electricity_prodat_utilts_no_gas'))
    returning id into v_run_id;
  else
    v_run_id := p_existing_run_id;
  end if;

  update public.platform_actor_routes r
  set auto_send_allowed = true,
      metadata = coalesce(r.metadata, '{}'::jsonb) || jsonb_build_object(
        'auto_send_enabled_at', now(),
        'auto_send_enabled_by', 'system',
        'auto_send_enabled_reason', 'all_readiness_checks_passed',
        'readiness_run_id', v_run_id,
        'certificate_fingerprint', v.certificate_fingerprint_sha256,
        'auto_send_scope', 'electricity_prodat_utilts_no_gas'
      ),
      updated_at = now()
  from public.platform_actor_send_readiness_v v
  where v.route_id = r.id
    and v.readiness_status = 'ready_for_auto_send'
    and upper(coalesce(v.message_family, '')) in ('PRODAT','UTILTS')
    and upper(coalesce(v.subaddress, '')) <> 'GAS'
    and coalesce(r.auto_send_allowed, false) = false;

  get diagnostics v_enabled = row_count;

  update public.platform_actor_routes r
  set auto_send_allowed = false,
      metadata = coalesce(r.metadata, '{}'::jsonb) || jsonb_build_object(
        'auto_send_disabled_at', now(),
        'auto_send_disabled_by', 'system',
        'auto_send_disabled_reason', case
          when upper(coalesce(v.message_family, '')) not in ('PRODAT','UTILTS') then 'message_family_out_of_electricity_auto_send_scope'
          when upper(coalesce(v.subaddress, '')) = 'GAS' then 'gas_route_out_of_electricity_auto_send_scope'
          else 'readiness_not_green'
        end,
        'readiness_run_id', v_run_id,
        'blocking_reasons', v.blocking_reasons,
        'warnings', v.warnings
      ),
      updated_at = now()
  from public.platform_actor_send_readiness_v v
  where v.route_id = r.id
    and coalesce(r.auto_send_allowed, false) = true
    and (
      v.readiness_status <> 'ready_for_auto_send'
      or upper(coalesce(v.message_family, '')) not in ('PRODAT','UTILTS')
      or upper(coalesce(v.subaddress, '')) = 'GAS'
    );

  get diagnostics v_disabled = row_count;

  insert into public.platform_actor_readiness_checks(run_id, actor_id, route_id, certificate_id, check_type, status, blocking_reasons, warnings, metadata, checked_at, next_check_at)
  select v_run_id, v.actor_id, v.route_id, v.certificate_id, 'auto_send',
         case when v.readiness_status = 'ready_for_auto_send'
                and upper(coalesce(v.message_family, '')) in ('PRODAT','UTILTS')
                and upper(coalesce(v.subaddress, '')) <> 'GAS' then 'passed'
              when cardinality(v.blocking_reasons) > 0 then 'blocking'
              when cardinality(v.warnings) > 0 then 'warning'
              else 'unknown' end,
         case
           when upper(coalesce(v.message_family, '')) not in ('PRODAT','UTILTS') then array_append(v.blocking_reasons, 'message_family_out_of_electricity_auto_send_scope')
           when upper(coalesce(v.subaddress, '')) = 'GAS' then array_append(v.blocking_reasons, 'gas_route_out_of_electricity_auto_send_scope')
           else v.blocking_reasons
         end,
         v.warnings,
         jsonb_build_object('readiness_status', v.readiness_status, 'message_family', v.message_family, 'environment', v.environment, 'subaddress', v.subaddress, 'auto_send_scope', 'electricity_prodat_utilts_no_gas'),
         now(), v.next_check_at
  from public.platform_actor_send_readiness_v v;

  if p_existing_run_id is null then
    update public.platform_actor_readiness_runs
    set status = 'completed', finished_at = now(), auto_enabled_count = v_enabled, auto_disabled_count = v_disabled,
        metadata = metadata || jsonb_build_object('auto_enabled_count', v_enabled, 'auto_disabled_count', v_disabled, 'auto_send_scope', 'electricity_prodat_utilts_no_gas')
    where id = v_run_id;
  else
    update public.platform_actor_readiness_runs
    set auto_enabled_count = auto_enabled_count + v_enabled,
        auto_disabled_count = auto_disabled_count + v_disabled,
        metadata = metadata || jsonb_build_object('auto_enabled_count', v_enabled, 'auto_disabled_count', v_disabled, 'auto_send_scope', 'electricity_prodat_utilts_no_gas')
    where id = v_run_id;
  end if;

  return jsonb_build_object('ok', true, 'run_id', v_run_id, 'auto_enabled_count', v_enabled, 'auto_disabled_count', v_disabled, 'auto_send_scope', 'electricity_prodat_utilts_no_gas');
exception when others then
  if v_run_id is not null then
    update public.platform_actor_readiness_runs
    set status = 'failed', finished_at = now(), failed_count = 1, metadata = metadata || jsonb_build_object('error', sqlerrm)
    where id = v_run_id;
  end if;
  raise;
end;
$$;

--
-- Name: gridex_apply_billing_export_partner_result(uuid, uuid, uuid[], jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_apply_billing_export_partner_result(p_company_id uuid, p_export_run_id uuid, p_accepted_ids uuid[] DEFAULT '{}'::uuid[], p_rejected jsonb DEFAULT '[]'::jsonb, p_response jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_target_count integer; v_accounted_count integer; v_unknown_count integer; v_rejected_count integer;
begin
  if jsonb_typeof(coalesce(p_rejected,'[]'::jsonb))<>'array' then raise exception using errcode='22023',message='rejected_rows_must_be_array'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_export_run_id::text||':partner-result',0));
  perform 1 from public.billing_export_runs where id=p_export_run_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='billing_export_run_not_found'; end if;
  select count(*) into v_target_count from public.billing_export_run_items
   where company_id=p_company_id and billing_export_run_id=p_export_run_id and status in ('ready','ready_for_retry') and export_status='queued';
  select count(distinct id) into v_accounted_count from (
    select unnest(coalesce(p_accepted_ids,'{}'::uuid[])) id
    union all
    select nullif(x->>'id','')::uuid from jsonb_array_elements(coalesce(p_rejected,'[]'::jsonb)) x
  ) q;
  select count(*) into v_unknown_count from (
    select unnest(coalesce(p_accepted_ids,'{}'::uuid[])) id
    union all select nullif(x->>'id','')::uuid from jsonb_array_elements(coalesce(p_rejected,'[]'::jsonb)) x
  ) q where q.id is null or not exists(select 1 from public.billing_export_run_items i where i.id=q.id and i.company_id=p_company_id and i.billing_export_run_id=p_export_run_id and i.status in ('ready','ready_for_retry') and i.export_status='queued');
  if v_unknown_count>0 or v_accounted_count<>v_target_count then raise exception using errcode='23514',message='partner_row_acknowledgement_incomplete_or_unknown'; end if;
  if exists(select 1 from unnest(coalesce(p_accepted_ids,'{}'::uuid[])) a join jsonb_array_elements(coalesce(p_rejected,'[]'::jsonb)) x on nullif(x->>'id','')::uuid=a) then
    raise exception using errcode='23514',message='partner_row_both_accepted_and_rejected';
  end if;
  update public.billing_export_run_items set export_status='sent',partner_result_type='accepted',sent_at=now(),failed_at=null,last_error=null,sent_by=p_actor_user_id,
    partner_response_log=coalesce(partner_response_log,'[]'::jsonb)||jsonb_build_array(p_response),last_partner_response_at=now(),updated_at=now()
  where company_id=p_company_id and billing_export_run_id=p_export_run_id and export_status='queued' and id=any(coalesce(p_accepted_ids,'{}'::uuid[]));
  update public.partner_exports p set status='sent',sent_at=now(),failure_reason=null,response_payload=p_response,
    partner_response_log=coalesce(p.partner_response_log,'[]'::jsonb)||jsonb_build_array(p_response),last_partner_response_at=now(),updated_at=now(),updated_by=p_actor_user_id
  from public.billing_export_run_items i where i.partner_export_id=p.id and i.company_id=p_company_id and i.billing_export_run_id=p_export_run_id and i.id=any(coalesce(p_accepted_ids,'{}'::uuid[]));
  with rejected as (select nullif(x->>'id','')::uuid id,coalesce(nullif(x->>'error',''),'Fakturapartnern avvisade raden.') error from jsonb_array_elements(coalesce(p_rejected,'[]'::jsonb)) x)
  update public.billing_export_run_items i set export_status='failed',status='ready_for_retry',
    partner_result_type=case when nullif(p_response->>'error','') is null then 'rejected' else 'transport_failed' end,
    failed_at=now(),last_error=r.error,
    partner_response_log=coalesce(i.partner_response_log,'[]'::jsonb)||jsonb_build_array(p_response),last_partner_response_at=now(),updated_at=now()
  from rejected r where i.id=r.id and i.company_id=p_company_id and i.billing_export_run_id=p_export_run_id and i.export_status='queued';
  with rejected as (select nullif(x->>'id','')::uuid id,coalesce(nullif(x->>'error',''),'Fakturapartnern avvisade raden.') error from jsonb_array_elements(coalesce(p_rejected,'[]'::jsonb)) x)
  update public.partner_exports p set status='failed',failed_at=now(),failure_reason=r.error,response_payload=p_response,
    partner_response_log=coalesce(p.partner_response_log,'[]'::jsonb)||jsonb_build_array(p_response),last_partner_response_at=now(),retry_count=p.retry_count+1,updated_at=now(),updated_by=p_actor_user_id
  from rejected r, public.billing_export_run_items i
  where i.id=r.id and i.partner_export_id=p.id
    and i.company_id=p_company_id and i.billing_export_run_id=p_export_run_id;
  select jsonb_array_length(coalesce(p_rejected,'[]'::jsonb)) into v_rejected_count;
  update public.billing_export_runs set partner_response_log=coalesce(partner_response_log,'[]'::jsonb)||jsonb_build_array(p_response),last_partner_response_at=now(),updated_at=now() where id=p_export_run_id and company_id=p_company_id;
  perform public.gridex_refresh_billing_export_run(p_company_id,p_export_run_id);
  return jsonb_build_object('accepted',coalesce(cardinality(p_accepted_ids),0),'rejected',v_rejected_count);
end $$;

--
-- Name: gridex_apply_contract_offer_standard_fees(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_apply_contract_offer_standard_fees() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_offer public.contract_offers%rowtype;
begin
  if new.contract_offer_id is null or new.company_id is null then
    return new;
  end if;

  -- Customer-specific/manual pricing is intentional and must not be replaced
  -- by catalog values merely because the original offer reference is retained.
  if coalesce(new.source_type, '') in ('manual', 'manual_override') then
    return new;
  end if;

  select offer.*
    into v_offer
  from public.contract_offers offer
  where offer.id = new.contract_offer_id
    and offer.company_id = new.company_id;

  if not found then
    return new;
  end if;

  new.monthly_fee_sek := v_offer.monthly_fee_sek;
  new.invoice_fee_sek := v_offer.invoice_fee_sek;
  new.green_fee_mode := v_offer.green_fee_mode;
  new.green_fee_value := v_offer.green_fee_value;
  new.discount_value := v_offer.discount_value;
  new.discount_unit := v_offer.discount_unit;
  new.start_fee_sek := v_offer.start_fee_sek;
  new.admin_fee_sek := v_offer.admin_fee_sek;
  new.break_fee_sek := v_offer.break_fee_sek;
  new.vat_rate := v_offer.vat_rate;

  return new;
end;
$$;

--
-- Name: FUNCTION gridex_apply_contract_offer_standard_fees(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_apply_contract_offer_standard_fees() IS 'Projects catalog-wide standard fees into a newly bound customer contract without mutating manual overrides or tracking later offer edits.';

--
-- Name: gridex_apply_exact_z02_core(uuid, uuid, uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_apply_exact_z02_core(p_company_id uuid, p_customer_id uuid, p_site_id uuid, p_request_id uuid, p_message_id uuid, p_operation_id uuid DEFAULT NULL::uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request public.customer_info_requests%rowtype;
  v_message public.ediel_messages%rowtype;
  v_site public.customer_sites%rowtype;
  v_meter public.metering_points%rowtype;
  v_conflict public.metering_points%rowtype;
  v_meter_external text;
  v_facility_id text;
  v_grid_area text;
  v_price_area text;
  v_annual numeric;
  v_inbound_price_area text;
  v_price_area_count integer := 0;
  v_now timestamptz := now();
begin
  select * into v_request
  from public.customer_info_requests
  where id = p_request_id
    and company_id = p_company_id
    and customer_id = p_customer_id
    and site_id = p_site_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'z02_request_site_customer_mismatch');
  end if;

  select * into v_message
  from public.ediel_messages
  where id = p_message_id
    and company_id = p_company_id
    and direction = 'inbound'
    and message_family = 'PRODAT'
    and upper(coalesce(message_code, '')) = 'Z02'
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'z02_inbound_message_not_found');
  end if;

  select * into v_site
  from public.customer_sites
  where id = p_site_id
    and company_id = p_company_id
    and customer_id = p_customer_id
  for update;

  if not found then
    return jsonb_build_object('ok', false, 'code', 'z02_site_not_found');
  end if;

  if v_message.customer_id is not null and v_message.customer_id <> p_customer_id then
    return jsonb_build_object('ok', false, 'code', 'z02_customer_mismatch');
  end if;
  if v_message.site_id is not null and v_message.site_id <> p_site_id then
    return jsonb_build_object('ok', false, 'code', 'response_site_mismatch');
  end if;
  if v_request.grid_owner_id is not null
     and v_message.grid_owner_id is not null
     and v_request.grid_owner_id <> v_message.grid_owner_id then
    return jsonb_build_object('ok', false, 'code', 'grid_owner_conflict');
  end if;

  v_meter_external := coalesce(
    nullif(btrim(v_message.parsed_payload ->> 'meteringPointId'), ''),
    nullif(btrim(v_message.parsed_payload ->> 'meterPointId'), ''),
    public.gridex_edifact_first_lin_item_id(v_message.raw_payload)
  );
  v_facility_id := coalesce(nullif(btrim(v_site.facility_id), ''), v_meter_external);
  v_grid_area := coalesce(
    nullif(btrim(v_message.parsed_payload ->> 'gridAreaId'), ''),
    nullif(btrim(v_message.parsed_payload ->> 'grid_area_code'), ''),
    public.gridex_edifact_rff_value(v_message.raw_payload, 'Z05')
  );
  v_inbound_price_area := upper(coalesce(
    nullif(btrim(v_message.parsed_payload ->> 'priceAreaCode'), ''),
    nullif(btrim(v_message.parsed_payload ->> 'price_area_code'), '')
  ));

  select count(distinct upper(pga.price_area))::integer,
         min(upper(pga.price_area))
    into v_price_area_count, v_price_area
  from public.platform_grid_areas pga
  where pga.is_active = true
    and upper(pga.grid_area_code) = upper(v_grid_area)
    and upper(coalesce(pga.price_area, '')) in ('SE1','SE2','SE3','SE4')
    and (pga.valid_from is null or pga.valid_from <= current_date)
    and (pga.valid_to is null or pga.valid_to >= current_date);

  begin
    v_annual := nullif(coalesce(
      v_message.parsed_payload ->> 'annualConsumptionKwh',
      v_message.parsed_payload ->> 'annual_consumption_kwh'
    ), '')::numeric;
  exception when others then
    v_annual := null;
  end;

  if v_meter_external is null then
    return jsonb_build_object('ok', false, 'code', 'z02_metering_point_missing');
  end if;
  if v_price_area_count <> 1 or v_price_area not in ('SE1','SE2','SE3','SE4') then
    return jsonb_build_object('ok', false, 'code', 'z02_grid_area_price_area_unresolved', 'gridAreaCode', v_grid_area);
  end if;
  if v_inbound_price_area is not null and v_inbound_price_area not in ('SE1','SE2','SE3','SE4') then
    return jsonb_build_object('ok', false, 'code', 'invalid_price_area');
  end if;
  if v_inbound_price_area is not null and v_inbound_price_area <> v_price_area then
    return jsonb_build_object('ok', false, 'code', 'z02_price_area_conflict', 'inboundPriceArea', v_inbound_price_area, 'canonicalPriceArea', v_price_area);
  end if;
  if nullif(btrim(v_site.price_area_code), '') is not null and upper(v_site.price_area_code) <> v_price_area then
    return jsonb_build_object('ok', false, 'code', 'z02_existing_price_area_conflict', 'existingPriceArea', upper(v_site.price_area_code), 'canonicalPriceArea', v_price_area);
  end if;
  if v_annual is not null and v_annual < 0 then
    return jsonb_build_object('ok', false, 'code', 'z02_annual_consumption_invalid');
  end if;

  if v_site.facility_id is not null and btrim(v_site.facility_id) <> v_facility_id then
    return jsonb_build_object('ok', false, 'code', 'facility_identifier_conflict');
  end if;

  if v_facility_id is not null and exists (
    select 1
    from public.customer_sites s
    where s.company_id = p_company_id
      and s.id <> p_site_id
      and s.is_active = true
      and (
        s.normalized_facility_id = v_facility_id
        or s.facility_id = v_facility_id
      )
  ) then
    return jsonb_build_object('ok', false, 'code', 'cross_site_identifier_conflict');
  end if;

  select * into v_conflict
  from public.metering_points m
  where m.company_id = p_company_id
    and coalesce(m.customer_site_id, m.site_id) <> p_site_id
    and m.status in ('draft','pending_validation','active')
    and (
      m.metering_point_id = v_meter_external
      or m.meter_point_id = v_meter_external
      or m.ediel_reference = v_meter_external
      or m.ediel_metering_point_id = v_meter_external
    )
  limit 1;

  if found then
    return jsonb_build_object(
      'ok', false,
      'code', 'duplicate_metering_point',
      'conflictingSiteId', coalesce(v_conflict.customer_site_id, v_conflict.site_id),
      'conflictingMeteringPointId', v_conflict.id
    );
  end if;

  update public.customer_sites
  set facility_id = coalesce(v_facility_id, facility_id),
      normalized_facility_id = coalesce(v_facility_id, normalized_facility_id),
      grid_area_code = coalesce(v_grid_area, grid_area_code),
      price_area_code = coalesce(v_price_area, price_area_code),
      bidding_zone_code = coalesce(v_price_area, bidding_zone_code),
      annual_consumption_kwh = coalesce(v_annual, annual_consumption_kwh),
      facility_data_status = 'verified',
      facility_data_verified_at = v_now,
      resolution_status = 'facility_verified',
      data_quality_status = 'verified',
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'facility_provenance', jsonb_build_object(
          'sourceType', 'ediel_inbound',
          'sourceMessageId', p_message_id,
          'sourcePartyId', coalesce(v_message.grid_owner_id, v_request.grid_owner_id),
          'receivedAt', v_now,
          'verificationLevel', 'market_verified',
          'verifiedAt', v_now,
          'customerInfoRequestId', p_request_id,
          'operationId', p_operation_id
        )
      ),
      updated_at = v_now,
      updated_by = p_actor_user_id
  where id = p_site_id
    and company_id = p_company_id
    and customer_id = p_customer_id;

  if v_request.metering_point_id is not null then
    select * into v_meter
    from public.metering_points m
    where m.id = v_request.metering_point_id
      and m.company_id = p_company_id
      and m.customer_id = p_customer_id
      and coalesce(m.customer_site_id, m.site_id) = p_site_id
    for update;
  end if;

  if not found then
    select * into v_meter
    from public.metering_points m
    where m.company_id = p_company_id
      and m.customer_id = p_customer_id
      and coalesce(m.customer_site_id, m.site_id) = p_site_id
      and (
        m.metering_point_id = v_meter_external
        or m.meter_point_id = v_meter_external
        or m.ediel_reference = v_meter_external
        or m.ediel_metering_point_id = v_meter_external
      )
    order by m.updated_at desc nulls last, m.created_at desc
    limit 1
    for update;
  end if;

  if found then
    update public.metering_points
    set site_id = p_site_id,
        customer_site_id = p_site_id,
        customer_id = p_customer_id,
        metering_point_id = v_meter_external,
        meter_point_id = v_meter_external,
        ediel_metering_point_id = coalesce(ediel_metering_point_id, v_meter_external),
        ediel_reference = coalesce(ediel_reference, v_meter_external),
        site_facility_id = coalesce(v_facility_id, site_facility_id),
        grid_owner_id = coalesce(v_request.grid_owner_id, v_message.grid_owner_id, grid_owner_id),
        grid_area_code = coalesce(v_grid_area, grid_area_code),
        price_area_code = coalesce(v_price_area, price_area_code),
        bidding_zone_code = coalesce(v_price_area, bidding_zone_code),
        estimated_annual_consumption_kwh = coalesce(v_annual, estimated_annual_consumption_kwh),
        status = 'active',
        data_quality_status = 'verified',
        verification_status = 'verified',
        facility_data_status = 'verified',
        facility_data_verified_at = v_now,
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'z02_market_verified', true,
          'z02_message_id', p_message_id,
          'customer_info_request_id', p_request_id,
          'operation_id', p_operation_id,
          'verified_at', v_now
        ),
        updated_at = v_now,
        updated_by = p_actor_user_id
    where id = v_meter.id
    returning * into v_meter;
  else
    insert into public.metering_points (
      company_id,
      customer_id,
      site_id,
      customer_site_id,
      metering_point_id,
      meter_point_id,
      ediel_metering_point_id,
      ediel_reference,
      site_facility_id,
      grid_owner_id,
      grid_area_code,
      price_area_code,
      bidding_zone_code,
      status,
      measurement_type,
      reading_frequency,
      is_settlement_relevant,
      data_quality_status,
      verification_status,
      facility_data_status,
      facility_data_verified_at,
      estimated_annual_consumption_kwh,
      metadata,
      created_by,
      updated_by
    ) values (
      p_company_id,
      p_customer_id,
      p_site_id,
      p_site_id,
      v_meter_external,
      v_meter_external,
      v_meter_external,
      v_meter_external,
      v_facility_id,
      coalesce(v_request.grid_owner_id, v_message.grid_owner_id),
      v_grid_area,
      v_price_area,
      v_price_area,
      'active',
      'consumption',
      'hourly',
      true,
      'verified',
      'verified',
      'verified',
      v_now,
      v_annual,
      jsonb_build_object(
        'z02_market_verified', true,
        'z02_message_id', p_message_id,
        'customer_info_request_id', p_request_id,
        'operation_id', p_operation_id,
        'verified_at', v_now
      ),
      p_actor_user_id,
      p_actor_user_id
    )
    returning * into v_meter;
  end if;

  update public.customer_info_requests
  set status = 'ready_for_switch',
      metering_point_id = v_meter.id,
      response_ediel_message_id = p_message_id,
      received_at = coalesce(received_at, v_now),
      blocker_code = null,
      blocker_reason = null,
      blocker_details = '{}'::jsonb,
      route_resolution_status = 'z02_market_verified',
      next_required_action = 'Kör canonical supplier-switch readiness och nästa steg.',
      verified_payload = coalesce(verified_payload, '{}'::jsonb) || jsonb_build_object(
        'z02', jsonb_build_object(
          'message_id', p_message_id,
          'metering_point_id', v_meter_external,
          'facility_id', v_facility_id,
          'grid_area_code', v_grid_area,
          'price_area_code', v_price_area,
          'annual_consumption_kwh', v_annual,
          'verification_level', 'market_verified',
          'verified_at', v_now,
          'atomic_core_apply', true
        )
      ),
      updated_at = v_now,
      updated_by = p_actor_user_id
  where id = p_request_id
    and company_id = p_company_id
    and customer_id = p_customer_id
    and site_id = p_site_id;

  if v_request.grid_owner_data_request_id is not null then
    update public.grid_owner_data_requests
    set status = 'received',
        response_payload = coalesce(response_payload, '{}'::jsonb) || jsonb_build_object(
          'z02_message_id', p_message_id,
          'metering_point_id', v_meter_external,
          'facility_id', v_facility_id,
          'grid_area_code', v_grid_area,
          'price_area_code', v_price_area,
          'atomic_core_apply', true,
          'received_at', v_now
        ),
        updated_at = v_now,
        updated_by = p_actor_user_id
    where id = v_request.grid_owner_data_request_id
      and company_id = p_company_id;
  end if;

  update public.ediel_messages
  set customer_id = p_customer_id,
      site_id = p_site_id,
      metering_point_id = v_meter.id,
      grid_owner_id = coalesce(grid_owner_id, v_request.grid_owner_id),
      operation_id = coalesce(operation_id, p_operation_id),
      parsed_payload = coalesce(parsed_payload, '{}'::jsonb) || jsonb_build_object(
        'canonicalCorrelation', jsonb_build_object(
          'status', 'exact',
          'customer_info_request_id', p_request_id,
          'customer_id', p_customer_id,
          'site_id', p_site_id,
          'metering_point_record_id', v_meter.id,
          'operation_id', p_operation_id,
          'atomic_core_apply', true,
          'applied_at', v_now
        )
      ),
      updated_at = v_now
  where id = p_message_id
    and company_id = p_company_id;

  return jsonb_build_object(
    'ok', true,
    'requestId', p_request_id,
    'messageId', p_message_id,
    'customerId', p_customer_id,
    'customerSiteId', p_site_id,
    'meteringPointRecordId', v_meter.id,
    'meteringPointExternalId', v_meter_external,
    'facilityId', v_facility_id,
    'gridAreaCode', v_grid_area,
    'priceAreaCode', v_price_area,
    'annualConsumptionKwh', v_annual,
    'atomicCoreApply', true
  );
end;
$$;

--
-- Name: FUNCTION gridex_apply_exact_z02_core(p_company_id uuid, p_customer_id uuid, p_site_id uuid, p_request_id uuid, p_message_id uuid, p_operation_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_apply_exact_z02_core(p_company_id uuid, p_customer_id uuid, p_site_id uuid, p_request_id uuid, p_message_id uuid, p_operation_id uuid, p_actor_user_id uuid) IS 'Atomic market-verified Z02 core apply: exact site, metering point, request, grid-owner-data request and inbound message linkage commit together.';

--
-- Name: gridex_apply_public_contract_backfill_v1(uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_apply_public_contract_backfill_v1(p_company_id uuid DEFAULT NULL::uuid, p_offer_id uuid DEFAULT NULL::uuid, p_publication_version_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS TABLE(company_id uuid, offer_id uuid, publication_version_id uuid, channel text, action text, applied boolean, details jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  candidate record;
  result jsonb;
begin
  if p_actor_user_id is null then
    raise exception using errcode='22023',
      message='PUBLICATION_BACKFILL_ACTOR_REQUIRED';
  end if;
  for candidate in
    select * from public.gridex_preview_public_contract_backfill_v1(
      p_company_id,p_offer_id,p_publication_version_id,p_channel
    )
  loop
    if not candidate.safe_to_apply then
      with review as (
        select candidate.company_id company_id,
          coalesce(
            (select pv.price_plan_version_id
              from public.contract_publication_versions pv
              where pv.id=candidate.publication_version_id),
            (select offer.price_plan_version_id
              from public.contract_offers offer
              where offer.id=candidate.offer_id)
          ) price_plan_version_id,
          case when candidate.publication_version_id is null
            then 'contract_offers' else 'contract_publication_versions' end
            source_table,
          coalesce(candidate.publication_version_id,candidate.offer_id)
            source_id,
          coalesce(candidate.manual_review_reason,
            'PUBLICATION_BACKFILL_UNSAFE') reason_code,
          jsonb_build_object('channel',candidate.channel,
            'detected_problem',candidate.detected_problem) details
      )
      insert into public.contract_pricing_migration_reviews(
        company_id,price_plan_version_id,source_table,source_id,
        reason_code,details
      )
      select review.company_id,review.price_plan_version_id,
        review.source_table,review.source_id,review.reason_code,review.details
      from review
      where not exists(
        select 1 from public.contract_pricing_migration_reviews existing
        where existing.company_id=review.company_id
          and existing.price_plan_version_id is not distinct from
            review.price_plan_version_id
          and existing.source_table=review.source_table
          and existing.source_id is not distinct from review.source_id
          and existing.reason_code=review.reason_code
      );
      company_id:=candidate.company_id;offer_id:=candidate.offer_id;
      publication_version_id:=candidate.publication_version_id;
      channel:=candidate.channel;action:='MANUAL_REVIEW';applied:=false;
      details:=jsonb_build_object('reason',candidate.manual_review_reason);
      return next;
      continue;
    end if;

    begin
      -- Restore a reusable template copy only when the published snapshot is
      -- the deterministic source. Commercial values are copied unchanged.
      with version_row as (
        select * from public.contract_publication_versions
        where id=candidate.publication_version_id
      ), inserted as (
        insert into public.contract_price_options(
          company_id,contract_product_version_id,price_plan_version_id,
          contract_publication_version_id,option_reference,option_code,
          customer_name,internal_description,contract_type,binding_months,
          notice_months,auto_renew_enabled,renewal_term_months,valid_from,
          valid_to,earliest_start_date,latest_start_date,status,sort_order,
          version_number,metadata,created_by,customer_type,is_default,
          selection_required
        )
        select source.company_id,source.contract_product_version_id,
          source.price_plan_version_id,null,source.option_reference,
          source.option_code,source.customer_name,source.internal_description,
          source.contract_type,source.binding_months,source.notice_months,
          source.auto_renew_enabled,source.renewal_term_months,
          source.valid_from,source.valid_to,source.earliest_start_date,
          source.latest_start_date,source.status,source.sort_order,
          source.version_number,coalesce(source.metadata,'{}'::jsonb)
            ||jsonb_build_object(
              'restored_from_publication_price_option_id',source.id),
          coalesce(p_actor_user_id,source.created_by),source.customer_type,
          source.is_default,source.selection_required
        from public.contract_price_options source
        join version_row v on v.id=source.contract_publication_version_id
        where not exists(select 1 from public.contract_price_options template
          where template.company_id=source.company_id
            and template.contract_product_version_id=
              source.contract_product_version_id
            and template.price_plan_version_id=source.price_plan_version_id
            and template.contract_publication_version_id is null
            and template.option_reference=source.option_reference
            and template.option_code=source.option_code)
        on conflict do nothing
        returning id,metadata
      )
      insert into public.contract_price_option_area_prices(
        company_id,contract_price_option_id,price_plan_version_id,
        price_row_reference,price_area,amount,unit,vat_treatment,
        valid_from,valid_to,metadata,created_by,status
      )
      select template.company_id,template.id,template.price_plan_version_id,
        area.price_row_reference,area.price_area,area.amount,area.unit,
        area.vat_treatment,area.valid_from,area.valid_to,
        coalesce(area.metadata,'{}'::jsonb)||jsonb_build_object(
          'restored_from_area_price_id',area.id),
        coalesce(p_actor_user_id,area.created_by),area.status
      from inserted template
      join public.contract_price_option_area_prices area
        on area.contract_price_option_id=
          (template.metadata->>'restored_from_publication_price_option_id')::uuid
      on conflict(contract_price_option_id,price_area) do nothing;

      result:=public.gridex_finalize_contract_publication_v1(
        candidate.publication_version_id,p_actor_user_id,true
      );
      company_id:=candidate.company_id;offer_id:=candidate.offer_id;
      publication_version_id:=candidate.publication_version_id;
      channel:=candidate.channel;action:=candidate.proposed_action;
      applied:=true;details:=result;
    exception
      when sqlstate '23503' or sqlstate '23505' or sqlstate '23514'
        or sqlstate '55000' or sqlstate 'P0001' or sqlstate 'P0002' then
        insert into public.contract_pricing_migration_reviews(
          company_id,price_plan_version_id,source_table,source_id,
          reason_code,details
        )
        select candidate.company_id,pv.price_plan_version_id,
          'contract_publication_versions',candidate.publication_version_id,
          'PUBLICATION_BACKFILL_APPLY_BLOCKED',
          jsonb_build_object('channel',candidate.channel,
            'sqlstate',sqlstate,'message',sqlerrm)
        from public.contract_publication_versions pv
        where pv.id=candidate.publication_version_id
        on conflict do nothing;
        company_id:=candidate.company_id;offer_id:=candidate.offer_id;
        publication_version_id:=candidate.publication_version_id;
        channel:=candidate.channel;action:='MANUAL_REVIEW';applied:=false;
        details:=jsonb_build_object('reason','APPLY_VALIDATION_FAILED',
          'sqlstate',sqlstate,'message',sqlerrm);
    end;
    return next;
  end loop;
end $$;

--
-- Name: gridex_apply_public_contract_legal_backfill_v1(uuid, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_apply_public_contract_legal_backfill_v1(p_company_id uuid DEFAULT NULL::uuid, p_dry_run boolean DEFAULT true, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  candidate record;
  scanned_count bigint:=0;
  already_valid_count bigint:=0;
  backfilled_count bigint:=0;
  ambiguous_count bigint:=0;
  missing_source_count bigint:=0;
  blocked_count bigint:=0;
  failed_count bigint:=0;
  v_snapshot jsonb;
  v_before_snapshot jsonb;
  v_before_hash text;
  v_after_hash text;
  failure_details jsonb:='[]'::jsonb;
begin
  for candidate in
    select * from public.gridex_preview_public_contract_legal_backfill_v1(
      p_company_id
    )
  loop
    scanned_count:=scanned_count+1;
    if candidate.category='already_valid' then
      already_valid_count:=already_valid_count+1;
    elsif candidate.category='missing_source' then
      missing_source_count:=missing_source_count+1;
    elsif candidate.category='blocked' then
      blocked_count:=blocked_count+1;
    elsif candidate.category='backfillable' then
      if p_dry_run then
        backfilled_count:=backfilled_count+1;
      else
        begin
          v_snapshot:=public.gridex_publication_legal_snapshot_json_v1(
            candidate.company_id,candidate.legal_bundle_version_id
          );
          if v_snapshot is null then
            missing_source_count:=missing_source_count+1;
          else
            select pv.publication_snapshot,pv.content_sha256
              into v_before_snapshot,v_before_hash
            from public.contract_publication_versions pv
            where pv.id=candidate.publication_version_id
            for update;
            v_after_hash:=encode(extensions.digest(
              jsonb_set(coalesce(v_before_snapshot,'{}'::jsonb),
                '{legal_snapshot}',v_snapshot,true)::text,'sha256'
            ),'hex');
            perform set_config('gridex.version_transition','on',true);
            perform set_config('gridex.publication_graph_repair','on',true);
            update public.contract_publication_versions pv
            set publication_snapshot=jsonb_set(
                  coalesce(v_before_snapshot,'{}'::jsonb),
                  '{legal_snapshot}',v_snapshot,true
                ),
                content_sha256=v_after_hash
            where pv.id=candidate.publication_version_id;
            perform set_config('gridex.publication_graph_repair','off',true);
            insert into public.audit_logs(
              company_id,actor_user_id,entity_type,entity_id,action,
              old_values,new_values,metadata
            ) values(
              candidate.company_id,p_actor_user_id,
              'contract_publication_version',
              candidate.publication_version_id::text,
              'public_contract_legal_snapshot_backfilled',
              jsonb_build_object(
                'content_sha256',v_before_hash,
                'legal_snapshot',v_before_snapshot->'legal_snapshot'
              ),
              jsonb_build_object(
                'content_sha256',v_after_hash,
                'legal_snapshot',v_snapshot
              ),
              jsonb_build_object(
                'derivation_method',candidate.derivation_method,
                'commercial_values_changed',false,
                'contract_schema_version','2026-08-01.1'
              )
            );
            backfilled_count:=backfilled_count+1;
          end if;
        exception when others then
          perform set_config('gridex.publication_graph_repair','off',true);
          failed_count:=failed_count+1;
          failure_details:=failure_details||jsonb_build_array(jsonb_build_object(
            'publication_version_id',candidate.publication_version_id,
            'sqlstate',sqlstate,
            'message',sqlerrm
          ));
        end;
      end if;
    else
      ambiguous_count:=ambiguous_count+1;
    end if;
  end loop;
  return jsonb_build_object(
    'dry_run',p_dry_run,
    'scanned',scanned_count,
    'already_valid',already_valid_count,
    'backfilled',backfilled_count,
    'ambiguous',ambiguous_count,
    'missing_source',missing_source_count,
    'blocked',blocked_count,
    'failed',failed_count,
    'failure_details',failure_details
  );
end $$;

--
-- Name: FUNCTION gridex_apply_public_contract_legal_backfill_v1(p_company_id uuid, p_dry_run boolean, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_apply_public_contract_legal_backfill_v1(p_company_id uuid, p_dry_run boolean, p_actor_user_id uuid) IS 'Idempotent exact-relation legal snapshot backfill. Never selects first/latest bundle version.';

--
-- Name: gridex_approve_first_production_send(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_approve_first_production_send(p_company_id uuid, p_actor_setting_id uuid DEFAULT NULL::uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.ediel_actor_settings
  set
    first_production_send_approved = true,
    production_send_lock_enabled = false,
    updated_at = now(),
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
      'production_send_approved_by', p_actor_user_id,
      'production_send_approved_at', now(),
      'production_send_approval_reason', coalesce(p_reason, 'Första produktionssändningen godkänd av platform admin.')
    )
  where company_id = p_company_id
    and environment = 'production'
    and is_active = true
    and (p_actor_setting_id is null or id = p_actor_setting_id);

  insert into public.ediel_production_send_approvals(
    company_id,
    actor_setting_id,
    environment,
    status,
    approved_by,
    reason,
    metadata
  ) values (
    p_company_id,
    p_actor_setting_id,
    'production',
    'approved',
    p_actor_user_id,
    p_reason,
    jsonb_build_object('source', 'gridex_approve_first_production_send')
  );
end;
$$;

--
-- Name: gridex_archive_contract_product(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_archive_contract_product(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  v_before jsonb;
  v_channels bigint:=0;
  v_publications bigint:=0;
  v_versions bigint:=0;
  v_assignments bigint:=0;
  v_public_offers bigint:=0;
  v_offers bigint:=0;
  v_readiness jsonb;
begin
  perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.archive');
  select * into o from public.contract_offers
  where id=p_offer_id and company_id=p_company_id for update;
  if not found then
    return jsonb_build_object(
      'ok',false,'changed',false,'mode','blocked','code','contract_not_found',
      'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'contract_offer_not_found','contract_offer_id',
        'Avtalsversionen hittades inte för valt bolag.',to_jsonb(p_offer_id),
        'contract_offer',p_offer_id
      ))
    );
  end if;
  if o.lifecycle_status='archived' then
    return jsonb_build_object(
      'ok',true,'changed',false,'mode','archived','code','contract_already_archived',
      'offer_id',o.id,'contract_product_id',o.contract_product_id
    );
  end if;

  v_readiness:=public.gridex_validate_contract_readiness_v2(
    p_company_id,o.id,'archive',null
  );
  if not coalesce((v_readiness->>'can_execute')::boolean,false) then
    return jsonb_build_object(
      'ok',false,'changed',false,'mode','blocked',
      'code','invalid_contract_transition',
      'current_status',o.lifecycle_status,'requested_status','archived',
      'blockers',coalesce(v_readiness->'blockers','[]'::jsonb),
      'readiness',v_readiness
    );
  end if;
  v_before:=to_jsonb(o);

  if o.contract_product_id is null then
    perform public.gridex_sync_internal_offer_to_canonical(o.id);
    select * into o from public.contract_offers where id=o.id for update;
  end if;

  update public.tenant_contract_channels ch
  set status='ended',valid_to=coalesce(ch.valid_to,now()),updated_by=p_actor_user_id,updated_at=now()
  from public.tenant_contract_assignments ta
  join public.contract_product_versions cpv on cpv.id=ta.contract_product_version_id
  where ch.assignment_id=ta.id and ta.company_id=p_company_id and cpv.contract_product_id=o.contract_product_id
    and ch.status<>'ended';
  get diagnostics v_channels=row_count;

  perform set_config('gridex.version_transition','on',true);
  update public.contract_publication_versions pv
  set status=case when pv.locked_at is null then 'archived' else 'ended' end,
      valid_to=coalesce(pv.valid_to,now())
  from public.contract_publications p
  join public.tenant_contract_assignments ta on ta.id=p.assignment_id
  join public.contract_product_versions cpv on cpv.id=ta.contract_product_version_id
  where pv.contract_publication_id=p.id and ta.company_id=p_company_id
    and cpv.contract_product_id=o.contract_product_id
    and pv.status not in ('ended','archived');
  get diagnostics v_versions=row_count;

  update public.contract_publications p set status='archived',updated_at=now()
  from public.tenant_contract_assignments ta
  join public.contract_product_versions cpv on cpv.id=ta.contract_product_version_id
  where p.assignment_id=ta.id and ta.company_id=p_company_id and cpv.contract_product_id=o.contract_product_id
    and p.status<>'archived';
  get diagnostics v_publications=row_count;

  update public.tenant_contract_assignments ta
  set status='ended',valid_to=coalesce(ta.valid_to,current_date),updated_at=now()
  from public.contract_product_versions cpv
  where cpv.id=ta.contract_product_version_id and ta.company_id=p_company_id
    and cpv.contract_product_id=o.contract_product_id and ta.status<>'ended';
  get diagnostics v_assignments=row_count;

  perform set_config('gridex.public_offer_write','on',true);
  update public.public_contract_offers
  set lifecycle_status='archived',publication_status='archived',is_public=false,is_archived=true,
      website_enabled=false,website_cta_enabled=false,archived_at=coalesce(archived_at,now()),
      updated_by=p_actor_user_id,updated_at=now()
  where company_id=p_company_id and (
      (o.contract_product_id is not null and contract_product_id=o.contract_product_id)
      or source_contract_offer_id in (
        select series_offer.id from public.contract_offers series_offer
        where series_offer.company_id=p_company_id and series_offer.version_series_id=o.version_series_id
      )
    ) and not is_archived;
  get diagnostics v_public_offers=row_count;

  update public.contract_offers series_offer
  set lifecycle_status='archived',status='inactive',is_active=false,
      archived_at=coalesce(series_offer.archived_at,now()),
      updated_by=p_actor_user_id,updated_at=now()
  where series_offer.company_id=p_company_id
    and (series_offer.version_series_id=o.version_series_id
         or (o.contract_product_id is not null and series_offer.contract_product_id=o.contract_product_id))
    and series_offer.lifecycle_status<>'archived';
  get diagnostics v_offers=row_count;

  select * into o from public.contract_offers where id=p_offer_id;
  update public.contract_products set status='archived',updated_at=now()
  where id=o.contract_product_id and company_id=p_company_id;

  insert into public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata)
  values(p_company_id,p_actor_user_id,'contract_product',o.contract_product_id::text,'contract.product.archived',
    v_before,to_jsonb(o),jsonb_build_object(
      'offer_id',o.id,'history_preserved',true,'affected_channels',v_channels,
      'affected_publication_versions',v_versions,'affected_public_offers',v_public_offers
    ));

  return jsonb_build_object(
    'ok',true,'changed',(v_channels+v_publications+v_versions+v_assignments+v_public_offers+v_offers)>0,
    'mode','archived','code','contract_archived','offer',to_jsonb(o),'contract_product_id',o.contract_product_id,
    'affected_channels',v_channels,'affected_publications',v_publications,
    'affected_publication_versions',v_versions,'affected_assignments',v_assignments,
    'affected_public_offers',v_public_offers,'affected_contract_offers',v_offers
  );
end $$;

--
-- Name: FUNCTION gridex_archive_contract_product(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_archive_contract_product(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) IS 'Atomic idempotent contract archive RPC. Preserves history and qualifies every valid_to reference.';

--
-- Name: gridex_archive_draft_legal_template_version(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_archive_draft_legal_template_version(p_version_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.legal_template_versions set status='archived'
  where id=p_version_id and status in('draft','review') and locked_at is null;
  if not found then raise exception using errcode='55000',message='published_legal_template_is_immutable'; end if;
  return p_version_id;
end $$;

--
-- Name: gridex_archive_draft_tenant_legal_override(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_archive_draft_tenant_legal_override(p_company_id uuid, p_override_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.tenant_legal_overrides set status='archived'
  where id=p_override_id and company_id=p_company_id and status in('draft','submitted','approved','rejected') and locked_at is null;
  if not found then raise exception using errcode='55000',message='published_tenant_legal_override_is_immutable'; end if;
  return p_override_id;
end $$;

--
-- Name: gridex_archive_public_contract_offer(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_archive_public_contract_offer(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare o public.public_contract_offers%rowtype;
begin
  select * into o from public.public_contract_offers where id=p_offer_id and company_id=p_company_id for update;
  if not found then raise exception 'Avtalet hittades inte.'; end if;
  perform set_config('gridex.public_offer_write','on',true); perform set_config('gridex.version_transition','on',true);
  update public.public_contract_offers set publication_status='archived',is_public=false,is_archived=true,website_enabled=false,website_cta_enabled=false,archived_at=coalesce(archived_at,now()),updated_by=p_actor_user_id,updated_at=now() where id=p_offer_id returning * into o;
  update public.contract_publication_versions set status='archived' where id=o.contract_publication_version_id;
  update public.contract_publications p set status='archived',updated_at=now() from public.contract_publication_versions v where v.id=o.contract_publication_version_id and p.id=v.contract_publication_id;
  update public.tenant_contract_channels ch set status='ended',updated_at=now() from public.contract_publications p,public.contract_publication_versions v where v.id=o.contract_publication_version_id and p.id=v.contract_publication_id and ch.assignment_id=p.assignment_id and ch.channel='website';
  return to_jsonb(o);
end $$;

--
-- Name: gridex_assert_area_price_snapshot_unique_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_assert_area_price_snapshot_unique_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
begin
  if exists(
    select 1 from public.contract_price_option_area_prices existing
    where existing.id is distinct from new.id
      and existing.contract_price_option_id=new.contract_price_option_id
      and existing.price_row_reference=new.price_row_reference
  ) then
    raise exception using errcode='23505',
      message='PUBLICATION_AREA_PRICE_REFERENCE_DUPLICATE';
  end if;
  return new;
end $$;

--
-- Name: gridex_assert_commercial_child_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_assert_commercial_child_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_plan_version_id uuid;
begin
  if tg_table_name='contract_price_option_area_prices' then
    select option_row.company_id,option_row.price_plan_version_id
      into v_company_id,v_plan_version_id
    from public.contract_price_options option_row
    where option_row.id=new.contract_price_option_id;
    if v_company_id is null
      or v_company_id<>new.company_id
      or v_plan_version_id<>new.price_plan_version_id then
      raise exception using
        errcode='23514',
        message='commercial_area_price_tenant_or_version_mismatch';
    end if;
  else
    select plan_version.company_id
      into v_company_id
    from public.price_plan_versions plan_version
    where plan_version.id=new.price_plan_version_id;
    if v_company_id is null or v_company_id<>new.company_id then
      raise exception using
        errcode='23514',
        message='commercial_option_tenant_or_version_mismatch';
    end if;
    if not exists(
      select 1
      from public.contract_product_versions product_version
      join public.contract_products product
        on product.id=product_version.contract_product_id
      where product_version.id=new.contract_product_version_id
        and product_version.price_plan_version_id=new.price_plan_version_id
        and product.company_id=new.company_id
    ) then
      raise exception using
        errcode='23514',
        message='commercial_option_product_version_mismatch';
    end if;
    if new.contract_publication_version_id is not null and not exists(
      select 1
      from public.contract_publication_versions publication
      join public.contract_publications publication_root
        on publication_root.id=publication.contract_publication_id
      join public.tenant_contract_assignments assignment
        on assignment.id=publication_root.assignment_id
      where publication.id=new.contract_publication_version_id
        and assignment.company_id=new.company_id
        and publication.contract_product_version_id=
          new.contract_product_version_id
        and publication.price_plan_version_id=new.price_plan_version_id
        and (
          new.customer_type='both'
          or publication.customer_type='both'
          or new.customer_type=publication.customer_type
        )
    ) then
      raise exception using
        errcode='23514',
        message='commercial_option_publication_chain_mismatch';
    end if;
  end if;
  return new;
end
$$;

--
-- Name: gridex_assert_contract_channel_permission(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_assert_contract_channel_permission(p_company_id uuid, p_contract_product_version_id uuid, p_channel text, p_actor_user_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_assignment public.tenant_contract_assignments%rowtype;
  v_channel text := lower(coalesce(p_channel,''));
begin
  if v_channel not in ('internal','website','api') then
    raise exception using
      errcode='22023',
      message='invalid_contract_channel';
  end if;
  perform public.gridex_assert_contract_permission(
    p_actor_user_id,
    'contracts.publish.'||v_channel
  );
  if not public.gridex_contract_actor_can_operate_company(
    p_actor_user_id,
    p_company_id
  ) then
    raise exception using
      errcode='42501',
      message='contract_company_scope_denied';
  end if;
  select *
  into v_assignment
  from public.tenant_contract_assignments assignment
  where assignment.company_id=p_company_id
    and assignment.contract_product_version_id=p_contract_product_version_id
  for update;
  if not found then
    raise exception using
      errcode='P0002',
      message='contract_assignment_not_found';
  end if;
  if not public.gridex_contract_channel_permission_allowed(
    v_assignment,
    v_channel
  ) then
    raise exception using
      errcode='42501',
      message='contract_channel_permission_missing',
      detail=v_channel;
  end if;
  return v_assignment.id;
end
$$;

--
-- Name: gridex_assert_contract_permission(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_assert_contract_permission(p_actor_user_id uuid, p_permission text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
begin
  if not public.gridex_contract_actor_has_permission(p_actor_user_id,p_permission) then
    raise exception using errcode='42501',message='contract_permission_denied:'||coalesce(p_permission,'unknown');
  end if;
end $$;

--
-- Name: gridex_assert_no_public_offer_fk_references(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_assert_no_public_offer_fk_references(p_public_offer_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_blockers jsonb;
  v_first jsonb;
begin
  v_blockers:=public.gridex_fk_reference_blockers(
    'public.public_contract_offers'::regclass,
    p_public_offer_ids
  );
  if coalesce((v_blockers->>'count')::integer,0)>0 then
    v_first:=v_blockers#>'{items,0}';
    raise exception using
      errcode='23503',
      message='contract_public_offer_still_referenced',
      detail=format(
        'Foreign key %s on %s.%s still references %s public offer row(s).',
        coalesce(v_first->>'constraint','unknown'),
        coalesce(v_first->>'relation','unknown'),
        coalesce(v_first->>'column','unknown'),
        coalesce(v_first->>'rows','0')
      ),
      hint='Run gridex_preview_delete_unused_contract and inspect foreign_key_blockers.';
  end if;
end $$;

--
-- Name: gridex_assert_portfolio_permission(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_assert_portfolio_permission(p_actor_user_id uuid, p_permission text, p_company_id uuid, p_portfolio_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if not public.gridex_portfolio_actor_has_permission(
    p_actor_user_id,p_permission,p_company_id,p_portfolio_id
  ) then
    raise exception using errcode='42501',message='portfolio_settlement_permission_denied',
      detail=p_permission;
  end if;
end $$;

--
-- Name: gridex_assert_price_option_snapshot_unique_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_assert_price_option_snapshot_unique_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
begin
  if new.contract_publication_version_id is null then
    if exists(
      select 1 from public.contract_price_options existing
      where existing.id is distinct from new.id
        and existing.contract_publication_version_id is null
        and existing.contract_product_version_id=new.contract_product_version_id
        and existing.price_plan_version_id=new.price_plan_version_id
        and (existing.option_reference=new.option_reference
          or existing.option_code=new.option_code)
    ) then
      raise exception using errcode='23505',
        message='PUBLICATION_PRICE_OPTION_TEMPLATE_DUPLICATE';
    end if;
  elsif exists(
    select 1 from public.contract_price_options existing
    where existing.id is distinct from new.id
      and existing.contract_publication_version_id=
        new.contract_publication_version_id
      and (existing.option_reference=new.option_reference
        or existing.option_code=new.option_code
        or (existing.status='active' and new.status='active'
          and existing.is_default is true and new.is_default is true))
  ) then
    raise exception using errcode='23505',
      message='PUBLICATION_PRICE_OPTION_DUPLICATE';
  end if;
  return new;
end $$;

--
-- Name: gridex_assert_role_scope_is_consistent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_assert_role_scope_is_consistent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_is_platform boolean;
begin
  select public.gridex_normalize_platform_role(coalesce(r.key, r.name))
           in ('super_admin', 'platform_admin')
    into v_is_platform
  from public.roles r
  where r.id = new.role_id;

  if v_is_platform is null then
    return new;
  end if;

  if v_is_platform and new.company_id is not null then
    raise exception 'platform_role_must_be_global'
      using errcode = '23514',
            detail = 'A super_admin or platform_admin role cannot be scoped to a company.';
  end if;

  if not v_is_platform and new.company_id is null then
    raise exception 'company_role_requires_company'
      using errcode = '23514',
            detail = 'A non-platform role must be bound to a company; a global company role grants everywhere.';
  end if;

  return new;
end
$$;

--
-- Name: gridex_assert_supplier_switch_ready(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_assert_supplier_switch_ready(p_company_id uuid, p_contract_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_readiness record;
begin
  select * into v_readiness
  from public.customer_contract_lifecycle_readiness_v
  where company_id=p_company_id and customer_contract_id=p_contract_id;
  if not found then
    raise exception using errcode='P0002',message='supplier_switch_contract_readiness_missing';
  end if;
  if not v_readiness.switch_ready then
    raise exception using errcode='23514',message='supplier_switch_not_ready',
      detail=array_to_string(v_readiness.blockers,',');
  end if;
  return jsonb_build_object(
    'ready',true,'contract_id',p_contract_id,
    'lifecycle_stage',v_readiness.lifecycle_stage,
    'checked_at',clock_timestamp()
  );
end $$;

--
-- Name: gridex_assert_tenant_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_assert_tenant_reference() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_related_company uuid; v_relation_id uuid;
begin
  if tg_table_name='tenant_counterparty_routes' then
    select company_id into v_related_company from public.tenant_counterparty_relations where id=new.counterparty_relation_id;
    if v_related_company is distinct from new.company_id then raise exception 'tenant_counterparty_relation_mismatch'; end if;
    select company_id into v_related_company from public.communication_routes where id=new.communication_route_id;
    if v_related_company is distinct from new.company_id then raise exception 'tenant_communication_route_mismatch'; end if;
    if new.certificate_profile_id is not null then
      select company_id into v_related_company from public.tenant_certificate_profiles where id=new.certificate_profile_id;
      if v_related_company is distinct from new.company_id then raise exception 'tenant_certificate_profile_mismatch'; end if;
    end if;
  end if;
  return new;
end $$;

--
-- Name: gridex_assert_utilts_transaction_coverage(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_assert_utilts_transaction_coverage(p_source_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare v_company uuid; v_environment text; v_expected integer; v_final integer;
begin
  select company_id,environment into v_company,v_environment
    from public.ediel_messages where id=p_source_message_id and message_family='UTILTS';
  if not found then raise exception 'utilts_source_message_missing'; end if;
  select count(*) into v_expected from public.ediel_ack_transaction_results
    where company_id=v_company and environment=v_environment and source_message_id=p_source_message_id;
  if v_expected=0 then raise exception 'utilts_transaction_coverage_missing'; end if;
  select count(*) into v_final from public.ediel_ack_transaction_results
    where company_id=v_company and environment=v_environment and source_message_id=p_source_message_id
      and final_response_type is not null and response_message_id is not null and finalized_at is not null;
  if v_final<>v_expected then raise exception 'utilts_transaction_coverage_incomplete:%/%',v_final,v_expected; end if;
end $$;

--
-- Name: gridex_assert_verified_site_owner_for_manual_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_assert_verified_site_owner_for_manual_outbox() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_request_type text;
  v_request_grid_owner_id uuid;
  v_site_grid_owner_id uuid;
  v_site_grid_area_code text;
  v_site_resolution_status text;
  v_owner_verified boolean;
  v_owner_technical_only boolean;
  v_owner_verification_status text;
  v_site_specific_verified boolean;
begin
  if coalesce(new.external_delivery, false) is not true
     or new.status not in ('queued','sending')
     or new.request_id is null then
    return new;
  end if;

  select r.request_type,
         r.grid_owner_id,
         s.grid_owner_id,
         s.grid_area_code,
         s.resolution_status,
         g.verified_for_customer_flow,
         g.technical_owner_only,
         g.verification_status,
         coalesce(
           csr.id is not null
           and csr.company_id = s.company_id
           and csr.customer_id = s.customer_id
           and csr.customer_site_id = s.id
           and csr.grid_owner_id = s.grid_owner_id
           and csr.resolution_status = 'grid_area_master_validated'
           and csr.automation_allowed is true
           and lower(coalesce(csr.source_claims->>'manual_grid_owner_confirmation','false')) in ('true','1','yes'),
           false
         )
    into v_request_type,
         v_request_grid_owner_id,
         v_site_grid_owner_id,
         v_site_grid_area_code,
         v_site_resolution_status,
         v_owner_verified,
         v_owner_technical_only,
         v_owner_verification_status,
         v_site_specific_verified
    from public.grid_owner_information_requests r
    join public.customer_sites s
      on s.id = r.customer_site_id
     and s.company_id = r.company_id
     and s.customer_id = r.customer_id
    left join public.grid_owners g on g.id = r.grid_owner_id
    left join public.customer_site_resolution csr on csr.id = s.resolution_id
   where r.id = new.request_id
     and r.company_id = new.company_id;

  if not found then
    return new;
  end if;

  if v_request_type in ('facility_lookup', 'facility_identifier_lookup') then
    if v_site_grid_owner_id is null
       or v_request_grid_owner_id is null
       or v_request_grid_owner_id is distinct from v_site_grid_owner_id
       or nullif(btrim(coalesce(v_site_grid_area_code, '')), '') is null
       or coalesce(v_site_resolution_status, '') not in (
         'grid_area_master_validated',
         'facility_data_requested',
         'facility_data_received',
         'facility_verified'
       ) then
      raise exception using
        errcode = '23514',
        message = 'manual_facility_outbox_requires_canonical_geographic_site_owner',
        detail = 'External facility-information mail requires customer_sites.grid_owner_id and grid_area_code from canonical site geography. selected_grid_owner_id and Ediel/PRODAT readiness are not geographical authority.';
    end if;
    return new;
  end if;

  if v_site_grid_owner_id is null
     or v_request_grid_owner_id is null
     or v_request_grid_owner_id is distinct from v_site_grid_owner_id
     or v_owner_verified is distinct from true
     or coalesce(v_owner_verification_status, '') <> 'verified'
     or (coalesce(v_owner_technical_only, false) is true and not coalesce(v_site_specific_verified, false)) then
    raise exception using
      errcode = '23514',
      message = 'manual_grid_owner_outbox_requires_verified_site_owner',
      detail = 'External non-facility grid-owner mail requires exact site ownership and customer-flow verified operational routing.';
  end if;

  return new;
end;
$$;

--
-- Name: gridex_assign_customer_contract_identity_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_assign_customer_contract_identity_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.customer_id is null or new.company_id is null then
    return new;
  end if;

  if nullif(btrim(new.customer_number),'') is null then
    select c.customer_number into new.customer_number
    from public.customers c
    where c.id=new.customer_id and c.company_id=new.company_id;
  end if;
  if nullif(btrim(new.customer_number),'') is null then
    raise exception using errcode='23502',message='customer_contract_customer_number_required';
  end if;

  if nullif(btrim(new.contract_number),'') is null then
    new.contract_number := public.gridex_next_contract_number(new.company_id,new.customer_number);
  end if;
  return new;
end
$$;

--
-- Name: gridex_assign_customer_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_assign_customer_number() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.customer_number is null or btrim(new.customer_number) = '' then
    new.customer_number := public.gridex_next_customer_number(new.company_id);
  end if;
  return new;
end;
$$;

--
-- Name: gridex_assign_public_offer_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_assign_public_offer_code() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  base_code text;
  candidate text;
  suffix integer := 1;
begin
  base_code := coalesce(
    public.gridex_normalize_public_offer_code(new.offer_code),
    public.gridex_normalize_public_offer_code(new.public_name),
    'AVTAL'
  );
  base_code := left(base_code, 70);
  candidate := base_code;

  while exists (
    select 1
    from public.public_contract_offers existing
    where existing.company_id = new.company_id
      and existing.offer_code = candidate
      and existing.id is distinct from new.id
  ) loop
    suffix := suffix + 1;
    candidate := left(base_code, greatest(1, 80 - length(suffix::text) - 1)) || '-' || suffix::text;

    if suffix > 999 then
      candidate := left(base_code, 62) || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12));
      exit;
    end if;
  end loop;

  new.offer_code := candidate;
  return new;
end;
$$;

--
-- Name: FUNCTION gridex_assign_public_offer_code(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_assign_public_offer_code() IS 'Normalizes and auto-suffixes public_contract_offers.offer_code so duplicate tenant offer codes do not break contract creation.';

--
-- Name: gridex_attach_portfolio_settlement_to_invoice(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_attach_portfolio_settlement_to_invoice(p_actor_user_id uuid, p_company_id uuid, p_customer_invoice_id uuid, p_billing_underlay_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_binding public.portfolio_settlement_invoice_bindings%rowtype;
  v_settlement public.portfolio_monthly_settlements%rowtype;
  v_underlay public.billing_underlays%rowtype;
  v_version_snapshot jsonb;
  v_method jsonb;
  v_consumption numeric;
  v_portfolio_share numeric;
  v_spot_share numeric;
  v_fixed_share numeric;
  v_portfolio_cost numeric;
  v_spot_cost numeric;
  v_fixed_price numeric;
  v_fixed_cost numeric;
  v_management_fee numeric;
  v_other_fees numeric;
  v_calculation_snapshot jsonb;
  v_calculation_sha256 text;
begin
  if p_actor_user_id is null
     or not exists(select 1 from auth.users where id = p_actor_user_id) then
    raise exception using errcode = '42501', message = 'real_billing_actor_required';
  end if;
  if nullif(btrim(p_idempotency_key), '') is null then
    raise exception using errcode = '22023', message = 'invoice_settlement_idempotency_key_required';
  end if;

  select *
    into v_binding
  from public.portfolio_settlement_invoice_bindings
  where company_id = p_company_id
    and invoice_idempotency_key = btrim(p_idempotency_key);

  if found then
    if v_binding.customer_invoice_id is distinct from p_customer_invoice_id
       or v_binding.billing_underlay_id is distinct from p_billing_underlay_id then
      raise exception using errcode = '23505', message = 'invoice_settlement_idempotency_scope_mismatch';
    end if;
    return (
      select to_jsonb(i)
      from public.customer_invoices i
      where i.id = p_customer_invoice_id
    );
  end if;

  select *
    into v_binding
  from public.portfolio_settlement_invoice_bindings
  where company_id = p_company_id
    and billing_underlay_id = p_billing_underlay_id;
  if not found then
    raise exception using errcode = '23514', message = 'portfolio_settlement_binding_required';
  end if;

  select *
    into v_settlement
  from public.portfolio_monthly_settlements
  where id = v_binding.portfolio_monthly_settlement_id
    and company_id = p_company_id
    and status = 'locked'
    and is_current;
  if not found then
    raise exception using errcode = '23514', message = 'locked_current_portfolio_settlement_required';
  end if;

  select *
    into v_underlay
  from public.billing_underlays
  where id = p_billing_underlay_id
    and company_id = p_company_id;
  if not found or v_underlay.contract_id is null then
    raise exception using errcode = '23514', message = 'exact_contract_billing_underlay_required';
  end if;

  select coalesce(v.snapshot_json, '{}'::jsonb)
    into v_version_snapshot
  from public.price_plan_versions v
  where v.id = v_settlement.price_plan_version_id
    and v.company_id = p_company_id;
  if not found then
    raise exception using errcode = '23514', message = 'portfolio_price_plan_version_required';
  end if;

  v_method := coalesce(v_version_snapshot -> 'portfolio_method', '{}'::jsonb);
  v_consumption := v_underlay.total_kwh;
  v_portfolio_share := coalesce(
    nullif(v_method #>> '{mix_shares,portfolio_weight_percent}', '')::numeric,
    100
  );
  v_spot_share := coalesce(
    nullif(v_method #>> '{mix_shares,spot_weight_percent}', '')::numeric,
    0
  );
  v_fixed_share := coalesce(
    nullif(v_method #>> '{mix_shares,fixed_weight_percent}', '')::numeric,
    0
  );

  if coalesce(v_consumption, 0) <= 0
     or v_portfolio_share < 0
     or v_spot_share < 0
     or v_fixed_share < 0
     or v_portfolio_share > 100
     or v_spot_share > 100
     or v_fixed_share > 100
     or abs(v_portfolio_share + v_spot_share + v_fixed_share - 100) > 0.000001 then
    raise exception using errcode = '23514', message = 'portfolio_invoice_mix_shares_must_total_100';
  end if;

  v_portfolio_cost :=
    v_consumption
    * (v_portfolio_share / 100)
    * (v_settlement.portfolio_price_ore_per_kwh / 100);

  if v_spot_share > 0 then
    v_spot_cost := nullif(
      v_underlay.pricing_snapshot #>> '{portfolio_billing,spot_energy_cost_sek}',
      ''
    )::numeric;
    if v_spot_cost is null or v_spot_cost < 0 then
      raise exception using errcode = '23514', message = 'final_spot_energy_cost_required_for_mixed_invoice';
    end if;
  else
    v_spot_cost := 0;
  end if;

  if v_fixed_share > 0 then
    select nullif(component ->> 'fixed_price_sek_per_kwh', '')::numeric
      into v_fixed_price
    from jsonb_array_elements(
      coalesce(v_version_snapshot -> 'base_components', '[]'::jsonb)
    ) component
    where component ->> 'source_type' = 'fixed'
      and coalesce(component ->> 'price_area', '') in ('', v_settlement.price_area_code)
    order by case
      when component ->> 'price_area' = v_settlement.price_area_code then 0
      else 1
    end
    limit 1;

    if v_fixed_price is null or v_fixed_price < 0 then
      raise exception using errcode = '23514', message = 'final_fixed_area_price_required_for_mixed_invoice';
    end if;
    v_fixed_cost := v_consumption * (v_fixed_share / 100) * v_fixed_price;
  else
    v_fixed_price := null;
    v_fixed_cost := 0;
  end if;

  v_management_fee :=
    v_consumption
    * (v_portfolio_share / 100)
    * (v_settlement.management_fee_ore_per_kwh / 100);
  v_other_fees := coalesce(
    nullif(v_underlay.pricing_snapshot #>> '{portfolio_billing,other_fees_sek}', '')::numeric,
    0
  );

  v_calculation_snapshot := jsonb_build_object(
    'customer_contract_id', v_underlay.contract_id,
    'price_plan_version_id', v_settlement.price_plan_version_id,
    'portfolio_monthly_settlement_id', v_settlement.id,
    'delivery_month', v_settlement.delivery_month,
    'price_area_code', v_settlement.price_area_code,
    'consumption_kwh', v_consumption,
    'portfolio_share_percent', v_portfolio_share,
    'spot_share_percent', v_spot_share,
    'fixed_share_percent', v_fixed_share,
    'portfolio_price_ore_per_kwh', v_settlement.portfolio_price_ore_per_kwh,
    'fixed_price_sek_per_kwh', v_fixed_price,
    'portfolio_energy_cost_sek', v_portfolio_cost,
    'spot_energy_cost_sek', v_spot_cost,
    'fixed_energy_cost_sek', v_fixed_cost,
    'management_fee_sek', v_management_fee,
    'other_fees_sek', v_other_fees,
    'energy_cost_sek_ex_vat', v_portfolio_cost + v_spot_cost + v_fixed_cost,
    'vat_rate', v_settlement.vat_rate,
    'settlement_snapshot_sha256', v_binding.settlement_sha256
  );
  v_calculation_sha256 := encode(
    extensions.digest(convert_to(v_calculation_snapshot::text, 'UTF8'), 'sha256'),
    'hex'
  );

  update public.customer_invoices
  set billing_underlay_id = p_billing_underlay_id,
      contract_id = v_underlay.contract_id,
      customer_contract_id = v_underlay.contract_id,
      portfolio_id = v_settlement.portfolio_id,
      portfolio_monthly_settlement_id = v_settlement.id,
      price_plan_version_id = v_settlement.price_plan_version_id,
      portfolio_price_area_code = v_settlement.price_area_code,
      portfolio_delivery_month = v_settlement.delivery_month,
      portfolio_settlement_revision = v_settlement.revision_no,
      portfolio_settlement_status = v_settlement.status,
      portfolio_price_ore_per_kwh = v_settlement.portfolio_price_ore_per_kwh,
      portfolio_management_fee_ore_per_kwh = v_settlement.management_fee_ore_per_kwh,
      portfolio_gross_energy_cost_sek = v_settlement.gross_energy_cost_sek,
      portfolio_energy_volume_kwh = v_settlement.energy_volume_kwh,
      portfolio_settlement_sha256 = v_binding.settlement_sha256,
      portfolio_settlement_source = v_settlement.source,
      portfolio_settlement_snapshot = v_binding.settlement_snapshot,
      delivery_month = v_settlement.delivery_month,
      price_area_code = v_settlement.price_area_code,
      consumption_kwh = v_consumption,
      portfolio_share_percent = v_portfolio_share,
      spot_share_percent = v_spot_share,
      fixed_share_percent = v_fixed_share,
      fixed_price_sek_per_kwh = v_fixed_price,
      portfolio_energy_cost_sek = v_portfolio_cost,
      spot_energy_cost_sek = v_spot_cost,
      fixed_energy_cost_sek = v_fixed_cost,
      management_fee_sek = v_management_fee,
      other_fees_sek = v_other_fees,
      vat_rate = v_settlement.vat_rate,
      calculation_snapshot = v_calculation_snapshot,
      calculation_snapshot_sha256 = v_calculation_sha256,
      updated_at = now()
  where id = p_customer_invoice_id
    and company_id = p_company_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'customer_invoice_not_found';
  end if;

  update public.portfolio_settlement_invoice_bindings
  set customer_invoice_id = p_customer_invoice_id,
      invoice_idempotency_key = btrim(p_idempotency_key)
  where id = v_binding.id
    and customer_invoice_id is null;
  if not found and (
    v_binding.customer_invoice_id is distinct from p_customer_invoice_id
    or v_binding.invoice_idempotency_key is distinct from btrim(p_idempotency_key)
  ) then
    raise exception using errcode = '23505', message = 'portfolio_settlement_binding_already_attached';
  end if;

  return (
    select to_jsonb(i)
    from public.customer_invoices i
    where i.id = p_customer_invoice_id
  );
end $$;

--
-- Name: gridex_audit_admin_users_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_audit_admin_users_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
begin
  insert into public.admin_users_audit_events(admin_user_id, action, actor_user_id, old_row, new_row)
  values (
    case
      when tg_op = 'INSERT' then coalesce(to_jsonb(new)->>'id', to_jsonb(new)->>'user_id')
      when tg_op = 'UPDATE' then coalesce(to_jsonb(new)->>'id', to_jsonb(old)->>'id', to_jsonb(new)->>'user_id', to_jsonb(old)->>'user_id')
      else coalesce(to_jsonb(old)->>'id', to_jsonb(old)->>'user_id')
    end,
    tg_op,
    auth.uid(),
    case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end,
    case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end
  );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

--
-- Name: gridex_audit_portfolio_settlement_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_audit_portfolio_settlement_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  insert into public.portfolio_settlement_audit_log(
    company_id,portfolio_id,settlement_id,actor_user_id,permission,action,
    old_values,new_values,reason,calculation_snapshot_sha256,approval
  ) values(
    case when tg_op='INSERT' then new.company_id else old.company_id end,
    case when tg_op='INSERT' then new.portfolio_id else old.portfolio_id end,
    case when tg_op='INSERT' then new.id else old.id end,
    case
      when tg_op='INSERT' then new.created_by
      when new.locked_by is distinct from old.locked_by then new.locked_by
      when new.approved_by is distinct from old.approved_by then new.approved_by
      when new.reviewed_by is distinct from old.reviewed_by then new.reviewed_by
      when new.calculated_by is distinct from old.calculated_by then new.calculated_by
      else coalesce(
        nullif(current_setting('gridex.portfolio_actor_user_id',true), '')::uuid,
        new.created_by
      )
    end,
    case
      when tg_op='INSERT' then case when new.source='import' then 'portfolio_settlement.import' else 'portfolio_settlement.create' end
      when new.is_current=false and old.is_current then 'portfolio_settlement.correct'
      when new.status='calculated' and old.status is distinct from new.status then 'portfolio_settlement.calculate'
      when new.status='reviewed' and old.status is distinct from new.status then 'portfolio_settlement.review'
      when new.status='final' and old.status is distinct from new.status then 'portfolio_settlement.approve'
      when new.status='locked' and old.status is distinct from new.status then 'portfolio_settlement.lock'
      else 'portfolio_settlement.correct'
    end,
    case
      when tg_op='INSERT' then 'settlement.created'
      when new.is_current=false and old.is_current then 'settlement.superseded'
      when new.status is distinct from old.status then 'settlement.'||new.status
      else 'settlement.updated'
    end,
    case when tg_op='INSERT' then null else to_jsonb(old) end,
    case when tg_op='DELETE' then null else to_jsonb(new) end,
    coalesce(
      nullif(current_setting('gridex.portfolio_audit_reason',true),''),
      case when tg_op='INSERT' then new.correction_reason else coalesce(new.correction_reason,old.correction_reason) end
    ),
    new.calculation_snapshot_sha256,
    case
      when new.approved_by is not null then jsonb_build_object('approved_by',new.approved_by,'approved_at',new.approved_at)
      else null
    end
  );
  return new;
end $$;

--
-- Name: gridex_backfill_contract_lifecycle(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_backfill_contract_lifecycle(p_company_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  po public.public_contract_offers%rowtype;
  v_match_id uuid;
  v_match_count integer;
  v_assignment_id uuid;
  v_channel_id uuid;
  v_publication_id uuid;
  v_publication_version_id uuid;
  v_version integer;
  v_offer_reference text;
  v_snapshot jsonb;
  v_hash text;
  v_active boolean;
  v_synced integer:=0;
  v_mapped integer:=0;
  v_publications integer:=0;
  v_issues integer:=0;
begin
  -- Clear only issues in this execution scope. Failed rows are reopened below.
  update public.contract_lifecycle_backfill_issues
  set status='resolved',resolved_at=now(),last_seen_at=now()
  where status='open' and (p_company_id is null or company_id=p_company_id);

  for o in
    select * from public.contract_offers
    where p_company_id is null or company_id=p_company_id
    order by company_id,created_at,id
  loop
    begin
      perform public.gridex_sync_internal_offer_to_canonical(o.id);
      v_synced:=v_synced+1;
    exception when others then
      perform public.gridex_record_contract_backfill_issue(
        o.company_id,o.id,null,'CANONICAL_SYNC_FAILED',
        jsonb_build_object('sqlstate',sqlstate,'message',sqlerrm)
      );
      v_issues:=v_issues+1;
    end;
  end loop;

  -- Deterministically attach legacy public offers that have exactly one source.
  for po in
    select * from public.public_contract_offers
    where source_contract_offer_id is null
      and (p_company_id is null or company_id=p_company_id)
    order by company_id,created_at,id
  loop
    v_match_id:=null;
    v_match_count:=0;
    select count(*),(array_agg(o2.id order by o2.id))[1] into v_match_count,v_match_id
    from public.contract_offers o2
    where o2.company_id=po.company_id
      and (
        (po.contract_product_version_id is not null and o2.contract_product_version_id=po.contract_product_version_id)
        or (po.version_series_id is not null and o2.version_series_id=po.version_series_id and o2.version_number=po.version_number)
        or (po.price_plan_version_id is not null and o2.price_plan_version_id=po.price_plan_version_id
            and lower(o2.name)=lower(po.public_name))
      );

    if v_match_count=1 then
      perform set_config('gridex.public_offer_write','on',true);
      update public.public_contract_offers
      set source_contract_offer_id=v_match_id,updated_at=now()
      where id=po.id;
      v_mapped:=v_mapped+1;
    else
      perform public.gridex_record_contract_backfill_issue(
        po.company_id,null,po.id,
        case when v_match_count=0 then 'PUBLIC_OFFER_SOURCE_NOT_FOUND' else 'PUBLIC_OFFER_SOURCE_AMBIGUOUS' end,
        jsonb_build_object('candidate_count',v_match_count)
      );
      v_issues:=v_issues+1;
    end if;
  end loop;

  -- Build/repair the website assignment, channel and immutable publication graph.
  for po in
    select p.* from public.public_contract_offers p
    where p.source_contract_offer_id is not null
      and (p_company_id is null or p.company_id=p_company_id)
    order by p.company_id,p.created_at,p.id
  loop
    begin
      select * into o from public.contract_offers
      where id=po.source_contract_offer_id and company_id=po.company_id;
      if not found then
        perform public.gridex_record_contract_backfill_issue(
          po.company_id,po.source_contract_offer_id,po.id,'PUBLIC_OFFER_SOURCE_MISSING','{}'::jsonb
        );
        v_issues:=v_issues+1;
        continue;
      end if;

      if o.contract_product_id is null or o.contract_product_version_id is null or o.legal_bundle_version_id is null then
        perform public.gridex_sync_internal_offer_to_canonical(o.id);
        select * into o from public.contract_offers where id=o.id;
      end if;
      if o.contract_product_id is null or o.contract_product_version_id is null or o.legal_bundle_version_id is null then
        perform public.gridex_record_contract_backfill_issue(
          o.company_id,o.id,po.id,'INCOMPLETE_CANONICAL_MAPPING',
          jsonb_build_object(
            'contract_product_id',o.contract_product_id,
            'contract_product_version_id',o.contract_product_version_id,
            'legal_bundle_version_id',o.legal_bundle_version_id
          )
        );
        v_issues:=v_issues+1;
        continue;
      end if;

      select id into v_assignment_id
      from public.tenant_contract_assignments
      where company_id=o.company_id and contract_product_version_id=o.contract_product_version_id
      order by created_at,id limit 1 for update;
      if v_assignment_id is null then
        insert into public.tenant_contract_assignments(
          company_id,contract_product_version_id,internal_sales_allowed,website_publication_allowed,
          status,legal_mode,valid_from,valid_to
        ) values(
          o.company_id,o.contract_product_version_id,true,true,
          case when o.lifecycle_status='archived' then 'ended' when po.is_public and not po.is_archived then 'active' else 'paused' end,
          'ops_standard',o.valid_from,o.valid_to
        ) returning id into v_assignment_id;
      else
        update public.tenant_contract_assignments
        set website_publication_allowed=true,
            status=case when o.lifecycle_status='archived' then 'ended'
                        when po.is_public and not po.is_archived then 'active'
                        when status='ended' then status else 'paused' end,
            valid_from=o.valid_from,valid_to=o.valid_to,updated_at=now()
        where id=v_assignment_id;
      end if;

      v_active:=coalesce(po.is_public,false)
        and not coalesce(po.is_archived,false)
        and coalesce(po.publication_status,'')='published'
        and coalesce(po.lifecycle_status,'')='published'
        and o.lifecycle_status<>'archived';

      insert into public.tenant_contract_channels(
        assignment_id,channel,status,valid_from,valid_to,marketing_content
      ) values(
        v_assignment_id,'website',case when v_active then 'active' else 'paused' end,
        o.valid_from::timestamptz,o.valid_to::timestamptz,
        jsonb_build_object('name',o.name,'source_contract_offer_id',o.id,'source_of_truth','contract_product_versions')
      ) on conflict(assignment_id,channel) do update set
        status=excluded.status,valid_from=excluded.valid_from,valid_to=excluded.valid_to,
        marketing_content=excluded.marketing_content,updated_at=now()
      returning id into v_channel_id;

      insert into public.contract_publications(assignment_id,channel,status)
      values(v_assignment_id,'website',case when v_active then 'published' else 'paused' end)
      on conflict(assignment_id,channel) do update set status=excluded.status,updated_at=now()
      returning id into v_publication_id;

      v_offer_reference:=public.gridex_new_offer_reference(concat_ws('|',o.company_id::text,o.version_series_id::text,o.version_number::text,'website'));
      v_snapshot:=jsonb_build_object(
        'schema','gridex_contract_publication_v5',
        'company_id',o.company_id,
        'contract_product_id',o.contract_product_id,
        'contract_product_version_id',o.contract_product_version_id,
        'source_contract_offer_id',o.id,
        'channel','website',
        'offer_reference',v_offer_reference,
        'commercial_snapshot',o.commercial_snapshot,
        'legal_bundle_version_id',o.legal_bundle_version_id,
        'valid_from',o.valid_from,
        'valid_to',o.valid_to
      );
      v_hash:=encode(digest(v_snapshot::text,'sha256'),'hex');

      select id into v_publication_version_id
      from public.contract_publication_versions
      where contract_publication_id=v_publication_id
        and (content_sha256=v_hash or legacy_public_contract_offer_id=po.id)
      order by version_number desc limit 1 for update;

      if v_active then
        if v_publication_version_id is null then
          select coalesce(max(version_number),0)+1 into v_version
          from public.contract_publication_versions where contract_publication_id=v_publication_id;
          insert into public.contract_publication_versions(
            contract_publication_id,version_number,contract_product_version_id,
            price_plan_id,price_plan_version_id,price_book_id,legal_bundle_version_id,
            legacy_public_contract_offer_id,customer_type,channel,valid_from,valid_to,
            publication_snapshot,offer_reference,content_sha256,status,published_at,locked_at
          ) values(
            v_publication_id,v_version,o.contract_product_version_id,
            o.price_plan_id,o.price_plan_version_id,o.price_book_id,o.legal_bundle_version_id,
            po.id,o.customer_type,'website',o.valid_from::timestamptz,o.valid_to::timestamptz,
            v_snapshot,v_offer_reference,v_hash,'published',coalesce(po.published_at,now()),now()
          ) returning id into v_publication_version_id;
          v_publications:=v_publications+1;
        else
          perform set_config('gridex.version_transition','on',true);
          update public.contract_publication_versions backfill_publication_version
          set status='published',valid_to=o.valid_to::timestamptz,
              published_at=coalesce(published_at,po.published_at,now()),locked_at=coalesce(locked_at,now()),
              legacy_public_contract_offer_id=coalesce(legacy_public_contract_offer_id,po.id)
          where id=v_publication_version_id;
        end if;
      else
        if v_publication_version_id is not null then
          perform set_config('gridex.version_transition','on',true);
          update public.contract_publication_versions backfill_publication_version
          set status=case when o.lifecycle_status='archived' then 'archived' else 'ended' end,
              valid_to=coalesce(backfill_publication_version.valid_to,po.archived_at,po.updated_at,now())
          where backfill_publication_version.id=v_publication_version_id and backfill_publication_version.status in ('draft','review','published','paused');
        end if;
      end if;

      perform set_config('gridex.public_offer_write','on',true);
      update public.public_contract_offers
      set contract_product_id=o.contract_product_id,
          contract_product_version_id=o.contract_product_version_id,
          legal_bundle_version_id=o.legal_bundle_version_id,
          contract_publication_version_id=case when v_active then v_publication_version_id else contract_publication_version_id end,
          version_series_id=o.version_series_id,version_number=o.version_number,
          lifecycle_status=case when o.lifecycle_status='archived' then 'archived' when v_active then 'published' else 'paused' end,
          updated_at=now()
      where id=po.id;

      update public.contract_lifecycle_backfill_issues
      set status='resolved',resolved_at=now(),last_seen_at=now()
      where (contract_offer_id=o.id or public_contract_offer_id=po.id) and status='open';
    exception when others then
      perform public.gridex_record_contract_backfill_issue(
        po.company_id,po.source_contract_offer_id,po.id,'PUBLICATION_BACKFILL_FAILED',
        jsonb_build_object('sqlstate',sqlstate,'message',sqlerrm)
      );
      v_issues:=v_issues+1;
    end;
  end loop;

  -- Re-derive offer lifecycle from exact current channels. Preserve archived and drafts.
  update public.contract_offers o2
  set lifecycle_status=case
        when o2.lifecycle_status='archived' then 'archived'
        when exists(
          select 1 from public.tenant_contract_assignments ta
          join public.tenant_contract_channels ch on ch.assignment_id=ta.id
          where ta.company_id=o2.company_id
            and ta.contract_product_version_id=o2.contract_product_version_id
            and ta.status='active' and ch.status='active'
        ) then 'published'
        when o2.lifecycle_status in ('published','paused','superseded') then 'paused'
        else o2.lifecycle_status
      end,
      status=case when exists(
          select 1 from public.tenant_contract_assignments ta
          join public.tenant_contract_channels ch on ch.assignment_id=ta.id
          where ta.company_id=o2.company_id
            and ta.contract_product_version_id=o2.contract_product_version_id
            and ta.status='active' and ch.status='active'
        ) then 'active' else 'inactive' end,
      is_active=exists(
          select 1 from public.tenant_contract_assignments ta
          join public.tenant_contract_channels ch on ch.assignment_id=ta.id
          where ta.company_id=o2.company_id
            and ta.contract_product_version_id=o2.contract_product_version_id
            and ta.status='active' and ch.status='active'
        ),
      updated_at=now()
  where (p_company_id is null or o2.company_id=p_company_id)
    and o2.contract_product_version_id is not null;

  return jsonb_build_object(
    'ok',true,'synced_contract_offers',v_synced,'mapped_public_offers',v_mapped,
    'created_publication_versions',v_publications,
    'open_issue_count',(select count(*) from public.contract_lifecycle_backfill_issues i
                        where i.status='open' and (p_company_id is null or i.company_id=p_company_id)),
    'issues_seen_this_run',v_issues
  );
end $$;

--
-- Name: FUNCTION gridex_backfill_contract_lifecycle(p_company_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_backfill_contract_lifecycle(p_company_id uuid) IS 'Idempotently repairs all legacy internal/public contract offers into the canonical product, assignment, channel and publication graph.';

--
-- Name: gridex_backfill_grid_owner_verification(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_backfill_grid_owner_verification(p_source text DEFAULT 'manual'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_inserted_grid_owners int := 0;
  v_inserted_platform_grid_owners int := 0;
  v_updated_grid_owners int := 0;
  v_review_items int := 0;
begin
  if to_regclass('public.platform_grid_owners') is not null then
    insert into public.platform_grid_owners(name, org_number, ediel_id, communication_email, source, metadata, market_actor_id, updated_at)
    select distinct
      a.name,
      a.org_number,
      ai.ediel_id,
      nullif(coalesce(r.communication_address, ''), ''),
      'actor_registry_backfill',
      jsonb_build_object('backfill_source', p_source, 'platform_actor_id', a.id),
      a.id,
      now()
    from public.platform_market_actors a
    join public.platform_actor_roles ar on ar.actor_id = a.id and coalesce(ar.is_active, true) = true
    left join lateral (
      select max(identifier_value) filter (where lower(identifier_type) in ('edielid','ediel_id')) as ediel_id
      from public.platform_actor_identifiers i where i.actor_id = a.id
    ) ai on true
    left join lateral (
      select communication_address
      from public.platform_actor_routes r
      where r.actor_id = a.id and nullif(btrim(coalesce(r.communication_address,'')), '') is not null
      order by case when r.environment = 'production' then 0 else 1 end, updated_at desc nulls last
      limit 1
    ) r on true
    where lower(ar.actor_role) in ('grid_owner','network_owner','netowner','dso','distribution_system_operator','nätägare','elnatsforetag','elnätsföretag')
      and not exists (
        select 1 from public.platform_grid_owners pgo
        where ai.ediel_id is not null and pgo.ediel_id = ai.ediel_id
      )
      and not exists (
        select 1 from public.platform_grid_owners pgo
        where lower(regexp_replace(coalesce(pgo.name,''), '\s+', ' ', 'g'))
            = lower(regexp_replace(coalesce(a.name,''), '\s+', ' ', 'g'))
      );
    get diagnostics v_inserted_platform_grid_owners = row_count;
  end if;

  insert into public.grid_owners(name, owner_code, ediel_id, org_number, communication_email, email, contact_name, country, environment, lifecycle_status, platform_market_actor_id, platform_grid_owner_id, is_active, notes, verification_metadata, created_at, updated_at)
  select distinct
    a.name,
    coalesce(ai.ediel_id, regexp_replace(lower(a.name), '[^a-z0-9]+', '_', 'g')),
    ai.ediel_id,
    coalesce(ai.registry_org_number, a.org_number),
    route.communication_address,
    route.communication_address,
    null,
    'SE',
    coalesce(route.environment, 'production'),
    'active',
    a.id,
    pgo.id,
    true,
    'Importerad/synkad från platform actor registry.',
    jsonb_build_object('backfill_source', p_source, 'platform_actor_id', a.id, 'platform_grid_owner_id', pgo.id),
    now(),
    now()
  from public.platform_market_actors a
  join public.platform_actor_roles ar on ar.actor_id = a.id and coalesce(ar.is_active, true) = true
  left join lateral (
    select
      max(identifier_value) filter (where lower(identifier_type) in ('edielid','ediel_id')) as ediel_id,
      max(identifier_value) filter (where lower(identifier_type) in ('orgno','org_number','orgnr')) as registry_org_number
    from public.platform_actor_identifiers i where i.actor_id = a.id
  ) ai on true
  left join lateral (
    select environment, communication_address
    from public.platform_actor_routes r
    where r.actor_id = a.id
    order by case when r.environment = 'production' then 0 else 1 end, updated_at desc nulls last
    limit 1
  ) route on true
  left join public.platform_grid_owners pgo
    on pgo.market_actor_id = a.id
    or (ai.ediel_id is not null and pgo.ediel_id = ai.ediel_id)
    or lower(regexp_replace(coalesce(pgo.name,''), '\s+', ' ', 'g')) = lower(regexp_replace(coalesce(a.name,''), '\s+', ' ', 'g'))
  where lower(ar.actor_role) in ('grid_owner','network_owner','netowner','dso','distribution_system_operator','nätägare','elnatsforetag','elnätsföretag')
    and not exists (select 1 from public.grid_owners g where ai.ediel_id is not null and g.ediel_id = ai.ediel_id)
    and not exists (select 1 from public.grid_owners g where a.org_number is not null and g.org_number = a.org_number)
    and not exists (
      select 1 from public.grid_owners g
      where lower(regexp_replace(coalesce(g.name,''), '\s+', ' ', 'g'))
          = lower(regexp_replace(coalesce(a.name,''), '\s+', ' ', 'g'))
    );
  get diagnostics v_inserted_grid_owners = row_count;

  with unique_verified as (
    select v.*
    from public.gridex_verified_grid_owners_v v
    join (
      select grid_owner_id
      from public.gridex_verified_grid_owners_v
      group by grid_owner_id
      having count(*) = 1
    ) u on u.grid_owner_id = v.grid_owner_id
  )
  update public.grid_owners g
  set platform_market_actor_id = coalesce(g.platform_market_actor_id, uv.platform_market_actor_id),
      platform_grid_owner_id = coalesce(g.platform_grid_owner_id, uv.platform_grid_owner_id),
      ediel_id = coalesce(nullif(g.ediel_id, ''), uv.ediel_id),
      org_number = coalesce(nullif(g.org_number, ''), uv.org_number),
      updated_at = now()
  from unique_verified uv
  where uv.grid_owner_id = g.id
    and (
      g.platform_market_actor_id is distinct from coalesce(g.platform_market_actor_id, uv.platform_market_actor_id)
      or g.platform_grid_owner_id is distinct from coalesce(g.platform_grid_owner_id, uv.platform_grid_owner_id)
      or g.ediel_id is distinct from coalesce(nullif(g.ediel_id, ''), uv.ediel_id)
      or g.org_number is distinct from coalesce(nullif(g.org_number, ''), uv.org_number)
    );

  if to_regclass('public.platform_grid_owners') is not null then
    with matched as materialized (
      select pgo.id as pgo_id, g.id as grid_owner_id
      from public.platform_grid_owners pgo
      join public.grid_owners g on pgo.id = g.platform_grid_owner_id
      union
      select pgo.id, g.id
      from public.platform_grid_owners pgo
      join public.grid_owners g on g.ediel_id is not null and pgo.ediel_id = g.ediel_id
      union
      select pgo.id, g.id
      from public.platform_grid_owners pgo
      join public.grid_owners g
        on lower(regexp_replace(coalesce(pgo.name,''), '\s+', ' ', 'g'))
         = lower(regexp_replace(coalesce(g.name,''), '\s+', ' ', 'g'))
    ),
    classified as (
      select
        m.pgo_id,
        count(distinct m.grid_owner_id)::integer as match_count,
        case when count(distinct m.grid_owner_id) = 1 then min(m.grid_owner_id::text)::uuid else null::uuid end as grid_owner_id
      from matched m
      group by m.pgo_id
    ),
    target_counts as (
      select c.grid_owner_id, count(*)::integer as target_count
      from classified c
      where c.match_count = 1 and c.grid_owner_id is not null
      group by c.grid_owner_id
    ),
    unique_matched as (
      select c.pgo_id, c.grid_owner_id
      from classified c
      join target_counts tc on tc.grid_owner_id = c.grid_owner_id
      where c.match_count = 1 and c.grid_owner_id is not null and tc.target_count = 1
    )
    update public.platform_grid_owners pgo
    set ops_grid_owner_id = g.id,
        updated_at = now(),
        metadata = coalesce(pgo.metadata, '{}'::jsonb) || jsonb_build_object('ops_grid_owner_linked_at', now())
    from unique_matched m
    join public.grid_owners g on g.id = m.grid_owner_id
    where pgo.id = m.pgo_id
      and (
        pgo.ops_grid_owner_id is distinct from g.id
        or not (coalesce(pgo.metadata, '{}'::jsonb) ? 'ops_grid_owner_linked_at')
      );
  end if;

  with unique_verified as (
    select v.*
    from public.gridex_verified_grid_owners_v v
    join (
      select grid_owner_id
      from public.gridex_verified_grid_owners_v
      group by grid_owner_id
      having count(*) = 1
    ) u on u.grid_owner_id = v.grid_owner_id
  )
  update public.grid_owners g
  set verification_status = uv.verification_status,
      verification_reasons = uv.verification_reasons,
      certificate_status = uv.certificate_status,
      certificate_environment = uv.certificate_environment,
      certificate_fingerprint_sha256 = uv.certificate_fingerprint_sha256,
      route_status = uv.route_status,
      route_count = uv.route_count,
      prodat_route_count = uv.prodat_route_count,
      utilts_route_count = uv.utilts_route_count,
      duplicate_group_key = uv.duplicate_key,
      duplicate_count = uv.duplicate_count,
      verified_for_customer_flow = uv.verified_for_customer_flow,
      actor_registry_status = uv.actor_registry_status,
      verified_at = case when uv.verified_for_customer_flow and g.verified_at is null then now() else g.verified_at end,
      verification_checked_at = now(),
      verification_metadata = coalesce(g.verification_metadata, '{}'::jsonb) || jsonb_build_object(
        'last_backfill_source', p_source,
        'last_backfill_at', now(),
        'next_action', uv.next_action,
        'platform_market_actor_id', uv.platform_market_actor_id,
        'actor_roles', uv.actor_roles
      ),
      updated_at = now()
  from unique_verified uv
  where uv.grid_owner_id = g.id;
  get diagnostics v_updated_grid_owners = row_count;

  with unique_verified as (
    select v.*
    from public.gridex_verified_grid_owners_v v
    join (
      select grid_owner_id
      from public.gridex_verified_grid_owners_v
      group by grid_owner_id
      having count(*) = 1
    ) u on u.grid_owner_id = v.grid_owner_id
  )
  insert into public.grid_owner_verification_reviews(grid_owner_id, platform_market_actor_id, issue_type, severity, status, message, metadata)
  select uv.grid_owner_id, uv.platform_market_actor_id, uv.verification_status,
         case when uv.verification_status in ('unresolved_duplicate','needs_ediel_id','needs_route','needs_subaddress','needs_certificate') then 'blocking' else 'warning' end,
         'open', uv.next_action,
         jsonb_build_object('verification_reasons', uv.verification_reasons, 'certificate_status', uv.certificate_status, 'route_count', uv.route_count, 'duplicate_count', uv.duplicate_count, 'backfill_source', p_source)
  from unique_verified uv
  where uv.verification_status <> 'verified'
    and not exists (
      select 1 from public.grid_owner_verification_reviews r
      where r.grid_owner_id = uv.grid_owner_id and r.issue_type = uv.verification_status and r.status = 'open'
    );
  get diagnostics v_review_items = row_count;

  return jsonb_build_object(
    'ok', true,
    'inserted_platform_grid_owners', v_inserted_platform_grid_owners,
    'inserted_grid_owners', v_inserted_grid_owners,
    'updated_grid_owners', v_updated_grid_owners,
    'created_review_items', v_review_items
  );
end;
$$;

--
-- Name: gridex_backfill_invoice_fees(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_backfill_invoice_fees() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_public public.public_contract_offers%rowtype;
  v_internal public.contract_offers%rowtype;
  v_ppv_snapshot jsonb;
  v_commercial_snapshot jsonb;
  v_materialized_snapshot jsonb;
  v_candidate jsonb;
  v_candidates numeric[];
  v_distinct numeric[];
  v_sources jsonb;
  v_amount numeric;
  v_visible boolean;
  v_ambiguous boolean;
  v_code text;
  v_actor uuid;
  v_pricing_model text;
  v_corrected jsonb;
  v_payload jsonb;
  v_result jsonb;
  v_processed integer:=0;
  v_resolved integer:=0;
  v_blocked integer:=0;
  v_failed integer:=0;
  v_error text;
  v_company_resolution jsonb;
  v_effective_company_id uuid;
  v_original_company_id uuid;
begin
  -- Public offers: exact locked price version, commercial snapshot,
  -- materialized components, then compatibility row. Different values conflict.
  for v_public in
    select o.* from public.public_contract_offers o
    left join public.price_plan_versions ppv on ppv.id=o.price_plan_version_id
    where o.publication_status in('draft','review','published')
      and coalesce(o.is_archived,false)=false
      and coalesce(public.gridex_invoice_fee_readiness(coalesce(ppv.snapshot_json,'{}'::jsonb),o.invoice_fee_sek)->>'status','blocked')<>'ready'
    order by o.created_at,o.id
  loop
    v_processed:=v_processed+1;
    v_candidates:='{}'::numeric[]; v_sources:='[]'::jsonb; v_ambiguous:=false; v_visible:=false;
    select ppv.snapshot_json,
           cpv.commercial_snapshot,
           coalesce(cpv.pricing_model,ppv.snapshot_json->>'pricing_model','spot')
      into v_ppv_snapshot,v_commercial_snapshot,v_pricing_model
    from public.public_contract_offers o
    left join public.price_plan_versions ppv on ppv.id=o.price_plan_version_id and ppv.company_id=o.company_id
    left join public.contract_publication_versions pubv on pubv.id=o.contract_publication_version_id
    left join public.contract_product_versions cpv on cpv.id=coalesce(o.contract_product_version_id,pubv.contract_product_version_id)
    where o.id=v_public.id and o.company_id=v_public.company_id;

    select jsonb_build_object('price_components',coalesce(jsonb_agg(jsonb_build_object(
      'component_type',pc.component_type,'component_code',coalesce(pc.metadata->>'component_code',pc.component_type),
      'amount',pc.amount,'unit',pc.unit,'calculation_type',pc.calculation_type,'status',pc.status,
      'website_card_visible',case when lower(coalesce(pc.metadata#>>'{visibility,website_card}','')) in('true','false') then (pc.metadata#>>'{visibility,website_card}')::boolean else false end,'metadata',pc.metadata
    ) order by pc.priority,pc.id),'[]'::jsonb))
    into v_materialized_snapshot
    from public.price_components pc
    where pc.company_id=v_public.company_id and pc.price_plan_version_id=v_public.price_plan_version_id
      and pc.status='active' and (pc.component_type='invoice_fee' or pc.metadata->>'component_code'='invoice_fee');

    foreach v_candidate in array array[
      public.gridex_invoice_fee_snapshot_candidate(v_ppv_snapshot),
      public.gridex_invoice_fee_snapshot_candidate(v_commercial_snapshot),
      public.gridex_invoice_fee_snapshot_candidate(v_materialized_snapshot)
    ] loop
      if v_candidate->>'status'='ready' then
        v_candidates:=array_append(v_candidates,(v_candidate->>'amount')::numeric);
        v_sources:=v_sources||jsonb_build_array(v_candidate);
        if jsonb_array_length(v_sources)=1 then v_visible:=coalesce((v_candidate->>'website_card_visible')::boolean,false); end if;
      elsif v_candidate->>'code'='invoice_fee_ambiguous' then
        v_ambiguous:=true;
      end if;
    end loop;
    if v_public.invoice_fee_sek is not null and v_public.invoice_fee_sek>=0 then
      v_candidates:=array_append(v_candidates,v_public.invoice_fee_sek);
      v_sources:=v_sources||jsonb_build_array(jsonb_build_object('status','ready','amount',v_public.invoice_fee_sek,'source','compatibility_row'));
    end if;
    select coalesce(array_agg(distinct value order by value),'{}'::numeric[]) into v_distinct from unnest(v_candidates) value;

    if v_ambiguous then v_code:='invoice_fee_ambiguous';
    elsif cardinality(v_distinct)=0 then v_code:='invoice_fee_missing';
    elsif cardinality(v_distinct)>1 then v_code:='invoice_fee_conflict';
    else v_code:=null; end if;

    if v_code is not null then
      perform public.gridex_record_invoice_fee_remediation(v_public.company_id,'public_contract_offers',v_public.id,'open',v_code,
        jsonb_build_object('candidate_values',to_jsonb(v_distinct),'sources',v_sources,'source_order',jsonb_build_array('price_plan_version','commercial_snapshot','materialized_price_components','compatibility_row')));
      v_blocked:=v_blocked+1; continue;
    end if;

    v_amount:=v_distinct[1]; v_actor:=coalesce(v_public.updated_by,v_public.created_by);
    if v_actor is null or nullif(v_public.offer_code,'') is null then
      perform public.gridex_record_invoice_fee_remediation(v_public.company_id,'public_contract_offers',v_public.id,'failed','invoice_fee_missing',
        jsonb_build_object('candidate_values',to_jsonb(v_distinct),'sources',v_sources),'Backfill saknar aktör eller avtalskod.');
      v_failed:=v_failed+1; continue;
    end if;

    v_corrected:=public.gridex_snapshot_with_invoice_fee(
      coalesce(v_ppv_snapshot,v_commercial_snapshot,v_public.metadata->'pricing_snapshot','{}'::jsonb),v_amount,v_visible
    );
    v_payload:=to_jsonb(v_public)||jsonb_build_object(
      'invoice_fee_sek',v_amount,'pricing_model',coalesce(v_pricing_model,'spot'),
      'metadata',coalesce(v_public.metadata,'{}'::jsonb)||jsonb_build_object('invoice_fee_backfill',true,'invoice_fee_backfill_sources',v_sources)
    );
    begin
      v_result:=public.gridex_publish_contract_version(
        v_public.company_id,v_public.id,v_public.offer_code,v_payload,v_corrected,v_actor
      );
      if coalesce((v_result->>'ok')::boolean,false)=false then
        raise exception '%',coalesce(v_result->>'message','invoice_fee_backfill_failed');
      end if;
      perform public.gridex_record_invoice_fee_remediation(v_public.company_id,'public_contract_offers',v_public.id,'resolved',null,
        jsonb_build_object('old_value',v_public.invoice_fee_sek,'new_value',v_amount,'sources',v_sources,'new_offer_id',v_result#>>'{offer,id}','new_publication_version_id',v_result->>'contract_publication_version_id'));
      insert into public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata)
      values(v_public.company_id,v_actor,'public_contract_offer',v_public.id::text,'contract.invoice_fee.backfilled',
        jsonb_build_object('invoice_fee_sek',v_public.invoice_fee_sek),jsonb_build_object('invoice_fee_sek',v_amount),
        jsonb_build_object('version_safe',true,'sources',v_sources,'result',v_result));
      v_resolved:=v_resolved+1;
    exception when others then
      v_error:=sqlerrm;
      perform public.gridex_record_invoice_fee_remediation(v_public.company_id,'public_contract_offers',v_public.id,'failed','invoice_fee_conflict',
        jsonb_build_object('candidate_values',to_jsonb(v_distinct),'sources',v_sources),v_error);
      v_failed:=v_failed+1;
    end;
  end loop;

  -- Internal offers use the same deterministic evidence order and canonical RPC.
  for v_internal in
    select o.* from public.contract_offers o
    left join public.price_plan_versions ppv on ppv.id=o.price_plan_version_id
    where o.status in('draft','active') and coalesce(o.archived_at is not null,false)=false
      and coalesce(public.gridex_invoice_fee_readiness(coalesce(ppv.snapshot_json,o.commercial_snapshot,'{}'::jsonb),o.invoice_fee_sek)->>'status','blocked')<>'ready'
    order by o.created_at,o.id
  loop
    v_processed:=v_processed+1;
    v_candidates:='{}'::numeric[]; v_sources:='[]'::jsonb; v_ambiguous:=false; v_visible:=false;

    -- Old internal offers were historically allowed to have company_id=null.
    -- Resolve ownership only from exact relational evidence; never select an arbitrary tenant.
    v_original_company_id:=v_internal.company_id;
    v_company_resolution:=public.gridex_contract_offer_company_resolution(v_internal.id);
    if coalesce(v_company_resolution->>'status','blocked')<>'ready' then
      v_code:=coalesce(v_company_resolution->>'code','tenant_context_missing');
      perform public.gridex_record_invoice_fee_remediation(
        null,'contract_offers',v_internal.id,'open',v_code,
        jsonb_build_object(
          'company_resolution',v_company_resolution,
          'source_order',jsonb_build_array(
            'contract_offers.company_id','price_plan_versions.company_id','price_plans.company_id',
            'contract_products.company_id','contract_product_versions.contract_product_id',
            'tenant_contract_assignments.company_id','customer_contracts.company_id','contract_offer_versions.company_id'
          )
        )
      );
      v_blocked:=v_blocked+1;
      continue;
    end if;

    v_effective_company_id:=(v_company_resolution->>'company_id')::uuid;
    if v_internal.company_id is null then
      update public.contract_offers
      set company_id=v_effective_company_id,updated_at=now()
      where id=v_internal.id and company_id is null;

      select * into v_internal
      from public.contract_offers
      where id=v_internal.id
      for update;

      if v_internal.company_id is distinct from v_effective_company_id then
        perform public.gridex_record_invoice_fee_remediation(
          null,'contract_offers',v_internal.id,'open','tenant_context_conflict',
          jsonb_build_object(
            'company_resolution',v_company_resolution,
            'current_company_id',v_internal.company_id,
            'expected_company_id',v_effective_company_id
          )
        );
        v_blocked:=v_blocked+1;
        continue;
      end if;

      insert into public.audit_logs(
        company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata
      ) values(
        v_effective_company_id,coalesce(v_internal.updated_by,v_internal.created_by),
        'contract_offer',v_internal.id::text,'contract.company_id.backfilled',
        jsonb_build_object('company_id',v_original_company_id),
        jsonb_build_object('company_id',v_effective_company_id),
        jsonb_build_object('deterministic',true,'company_resolution',v_company_resolution)
      );
    end if;

    select ppv.snapshot_json,cpv.commercial_snapshot,coalesce(cpv.pricing_model,ppv.snapshot_json->>'pricing_model',o.commercial_snapshot->>'pricing_model','spot')
      into v_ppv_snapshot,v_commercial_snapshot,v_pricing_model
    from public.contract_offers o
    left join public.price_plan_versions ppv on ppv.id=o.price_plan_version_id and ppv.company_id=o.company_id
    left join public.contract_product_versions cpv on cpv.id=o.contract_product_version_id
    where o.id=v_internal.id and o.company_id=v_internal.company_id;

    select jsonb_build_object('price_components',coalesce(jsonb_agg(jsonb_build_object(
      'component_type',pc.component_type,'component_code',coalesce(pc.metadata->>'component_code',pc.component_type),
      'amount',pc.amount,'unit',pc.unit,'calculation_type',pc.calculation_type,'status',pc.status,
      'website_card_visible',case when lower(coalesce(pc.metadata#>>'{visibility,website_card}','')) in('true','false') then (pc.metadata#>>'{visibility,website_card}')::boolean else false end,'metadata',pc.metadata
    ) order by pc.priority,pc.id),'[]'::jsonb))
    into v_materialized_snapshot
    from public.price_components pc
    where pc.company_id=v_internal.company_id and pc.price_plan_version_id=v_internal.price_plan_version_id
      and pc.status='active' and (pc.component_type='invoice_fee' or pc.metadata->>'component_code'='invoice_fee');

    foreach v_candidate in array array[
      public.gridex_invoice_fee_snapshot_candidate(v_ppv_snapshot),
      public.gridex_invoice_fee_snapshot_candidate(coalesce(v_commercial_snapshot,v_internal.commercial_snapshot)),
      public.gridex_invoice_fee_snapshot_candidate(v_materialized_snapshot)
    ] loop
      if v_candidate->>'status'='ready' then
        v_candidates:=array_append(v_candidates,(v_candidate->>'amount')::numeric);
        v_sources:=v_sources||jsonb_build_array(v_candidate);
        if jsonb_array_length(v_sources)=1 then v_visible:=coalesce((v_candidate->>'website_card_visible')::boolean,false); end if;
      elsif v_candidate->>'code'='invoice_fee_ambiguous' then v_ambiguous:=true; end if;
    end loop;
    if v_internal.invoice_fee_sek is not null and v_internal.invoice_fee_sek>=0 then
      v_candidates:=array_append(v_candidates,v_internal.invoice_fee_sek);
      v_sources:=v_sources||jsonb_build_array(jsonb_build_object('status','ready','amount',v_internal.invoice_fee_sek,'source','compatibility_row'));
    end if;
    select coalesce(array_agg(distinct value order by value),'{}'::numeric[]) into v_distinct from unnest(v_candidates) value;
    if v_ambiguous then v_code:='invoice_fee_ambiguous';
    elsif cardinality(v_distinct)=0 then v_code:='invoice_fee_missing';
    elsif cardinality(v_distinct)>1 then v_code:='invoice_fee_conflict';
    else v_code:=null; end if;

    if v_code is not null then
      perform public.gridex_record_invoice_fee_remediation(v_internal.company_id,'contract_offers',v_internal.id,'open',v_code,
        jsonb_build_object('candidate_values',to_jsonb(v_distinct),'sources',v_sources,'source_order',jsonb_build_array('price_plan_version','commercial_snapshot','materialized_price_components','compatibility_row')));
      v_blocked:=v_blocked+1; continue;
    end if;

    v_amount:=v_distinct[1]; v_actor:=coalesce(v_internal.updated_by,v_internal.created_by);
    if v_actor is null then
      perform public.gridex_record_invoice_fee_remediation(v_internal.company_id,'contract_offers',v_internal.id,'failed','invoice_fee_missing',
        jsonb_build_object('candidate_values',to_jsonb(v_distinct),'sources',v_sources),'Backfill saknar aktör.');
      v_failed:=v_failed+1; continue;
    end if;
    v_corrected:=public.gridex_snapshot_with_invoice_fee(
      coalesce(v_ppv_snapshot,v_commercial_snapshot,v_internal.commercial_snapshot,'{}'::jsonb),v_amount,v_visible
    );
    v_payload:=to_jsonb(v_internal)||jsonb_build_object('invoice_fee_sek',v_amount,'pricing_model',coalesce(v_pricing_model,'spot'));
    begin
      v_result:=public.gridex_upsert_internal_contract_offer(v_internal.company_id,v_internal.id,v_payload,v_corrected,v_actor);
      perform public.gridex_record_invoice_fee_remediation(v_internal.company_id,'contract_offers',v_internal.id,'resolved',null,
        jsonb_build_object('old_value',v_internal.invoice_fee_sek,'new_value',v_amount,'sources',v_sources,'new_offer_id',v_result#>>'{offer,id}'));
      insert into public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata)
      values(v_internal.company_id,v_actor,'contract_offer',v_internal.id::text,'contract.invoice_fee.backfilled',
        jsonb_build_object('invoice_fee_sek',v_internal.invoice_fee_sek),jsonb_build_object('invoice_fee_sek',v_amount),
        jsonb_build_object('version_safe',true,'sources',v_sources,'result',v_result));
      v_resolved:=v_resolved+1;
    exception when others then
      v_error:=sqlerrm;
      perform public.gridex_record_invoice_fee_remediation(v_internal.company_id,'contract_offers',v_internal.id,'failed','invoice_fee_conflict',
        jsonb_build_object('candidate_values',to_jsonb(v_distinct),'sources',v_sources),v_error);
      v_failed:=v_failed+1;
    end;
  end loop;

  return jsonb_build_object('processed',v_processed,'resolved',v_resolved,'blocked',v_blocked,'failed',v_failed);
end $$;

--
-- Name: gridex_billing_information_complete(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_billing_information_complete(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select public.gridex_legal_contact_complete(coalesce(p_value->'contact','{}'::jsonb))
      or public.gridex_jsonb_valid_email(coalesce(p_value,'{}'::jsonb))
      or public.gridex_jsonb_valid_phone(coalesce(p_value,'{}'::jsonb))
      or public.gridex_address_complete(public.gridex_contact_address(coalesce(p_value,'{}'::jsonb)))
$$;

--
-- Name: gridex_billing_underlay_item_gate_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_billing_underlay_item_gate_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  n public.normalized_metering_values%rowtype;
  u public.billing_underlays%rowtype;
  v_value_start_date date;
  v_value_end_date date;
begin
  if new.source_normalized_metering_value_id is null then raise exception 'billing_underlay_source_normalized_value_required' using errcode='23514'; end if;
  select * into n from public.normalized_metering_values where id=new.source_normalized_metering_value_id;
  select * into u from public.billing_underlays where id=new.billing_underlay_id;
  if not found or u.id is null then raise exception 'billing_underlay_missing' using errcode='23503'; end if;
  if n.id is null then raise exception 'billing_underlay_normalized_value_missing' using errcode='23503'; end if;
  if n.company_id<>new.company_id or u.company_id<>new.company_id then raise exception 'billing_underlay_lineage_tenant_mismatch' using errcode='23514'; end if;
  if n.revision_status<>'current' or n.billing_status<>'billable' or n.billing_gate_status<>'eligible' then raise exception 'billing_underlay_value_not_gate_eligible' using errcode='23514'; end if;
  if n.source_message_id is null or n.source_metering_value_id is null or n.supply_period_id is null then raise exception 'billing_underlay_lineage_incomplete' using errcode='23514'; end if;
  if u.supply_period_id is null or u.supply_period_id<>n.supply_period_id then raise exception 'billing_underlay_supply_period_mismatch' using errcode='23514'; end if;

  v_value_start_date := (n.period_start at time zone 'Europe/Stockholm')::date;
  v_value_end_date := (n.period_end at time zone 'Europe/Stockholm')::date;
  if v_value_start_date < u.billing_period_start or v_value_end_date > u.billing_period_end then
    raise exception 'billing_underlay_period_outside_segment'
      using errcode='23514', detail=jsonb_build_object(
        'normalized_metering_value_id',n.id,
        'value_start_date',v_value_start_date,
        'value_end_date',v_value_end_date,
        'billing_period_start',u.billing_period_start,
        'billing_period_end',u.billing_period_end,
        'timezone','Europe/Stockholm',
        'billing_period_end_exclusive',true
      )::text;
  end if;
  return new;
end;
$$;

--
-- Name: gridex_bind_contract_snapshot_to_quote_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_bind_contract_snapshot_to_quote_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_snapshot jsonb:=coalesce(new.snapshot_json,'{}'::jsonb);
  v_quote public.website_contract_quotes%rowtype;
  v_requires_quote boolean;
begin
  new.snapshot_schema_version:=coalesce(
    new.snapshot_schema_version,
    v_snapshot->>'snapshot_schema',
    v_snapshot->>'schema_version'
  );

  if new.snapshot_schema_version is distinct from 'gridex_contract_pricing_v6_selection' then
    return new;
  end if;

  new.quote_reference:=coalesce(
    new.quote_reference,v_snapshot->>'quote_reference'
  );
  new.quote_hash:=coalesce(new.quote_hash,v_snapshot->>'quote_hash');
  new.price_option_reference:=coalesce(
    new.price_option_reference,v_snapshot->>'price_option_reference'
  );
  new.area_price_reference:=coalesce(
    new.area_price_reference,v_snapshot->>'area_price_reference'
  );
  new.invoice_delivery_method:=coalesce(
    new.invoice_delivery_method,v_snapshot->>'invoice_delivery_method'
  );
  if new.selected_component_references='{}'::text[] then
    new.selected_component_references:=array(
      select value
      from jsonb_array_elements_text(
        coalesce(v_snapshot->'selected_component_references','[]'::jsonb)
      )
    );
  end if;
  v_requires_quote:=coalesce(new.source,'') in (
    'website_customer_applications',
    'external_website',
    'website_application'
  );
  if (v_requires_quote and new.quote_reference is null)
    or (v_requires_quote and new.quote_hash is null)
    or new.price_option_reference is null
    or new.invoice_delivery_method is null
    or (
      v_snapshot->>'contract_type'='fixed'
      and new.area_price_reference is null
    )
    or jsonb_typeof(new.base_price_components_snapshot)<>'array'
    or jsonb_typeof(new.price_components_snapshot)<>'array' then
    raise exception using
      errcode='23514',
      message='contract_commercial_snapshot_identity_incomplete';
  end if;

  if v_requires_quote then
    select quote.*
      into v_quote
    from public.website_contract_quotes quote
    where quote.company_id=new.company_id
      and quote.quote_reference=new.quote_reference;
    if not found
      or v_quote.quote_hash is distinct from new.quote_hash
      or v_quote.price_option_reference
        is distinct from new.price_option_reference
      or v_quote.area_price_reference is distinct from new.area_price_reference
      or v_quote.invoice_delivery_method
        is distinct from new.invoice_delivery_method
      or v_quote.selected_component_references
        is distinct from new.selected_component_references
      or v_quote.resolved_base_components
        is distinct from new.base_price_components_snapshot
      or v_quote.resolved_price_components
        is distinct from new.price_components_snapshot then
      raise exception using
        errcode='23514',
        message='contract_snapshot_quote_selection_mismatch';
    end if;
  end if;
  return new;
end
$$;

--
-- Name: gridex_bind_customer_contract_to_exact_publication(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_bind_customer_contract_to_exact_publication() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v public.contract_publication_versions;
  pv public.contract_product_versions;
begin
  if new.contract_publication_version_id is not null then
    select cpv.*
    into v
    from public.contract_publication_versions cpv
    join public.contract_publications publication
      on publication.id = cpv.contract_publication_id
    join public.tenant_contract_assignments assignment
      on assignment.id = publication.assignment_id
    where cpv.id = new.contract_publication_version_id
      and assignment.company_id = new.company_id
      and assignment.status = 'active'
      and cpv.status = 'published'
      and cpv.locked_at is not null
      and (new.offer_reference is null or new.offer_reference = cpv.offer_reference)
    limit 1;
  elsif new.public_contract_offer_id is not null or new.offer_reference is not null then
    select cpv.*
    into v
    from public.contract_publication_versions cpv
    where cpv.offer_reference = new.offer_reference
      and cpv.legacy_public_contract_offer_id = new.public_contract_offer_id
      and cpv.status = 'published'
      and cpv.locked_at is not null
      and exists (
        select 1
        from public.public_contract_offers offer
        where offer.id = cpv.legacy_public_contract_offer_id
          and offer.company_id = new.company_id
      )
    limit 1;
  else
    return new;
  end if;

  if not found then
    raise exception using errcode='23514', message='exact_published_contract_version_required';
  end if;

  select *
  into pv
  from public.contract_product_versions
  where id = v.contract_product_version_id
    and locked_at is not null
    and status = 'approved';
  if not found then
    raise exception using errcode='23514', message='exact_approved_contract_product_version_required';
  end if;

  new.offer_reference := v.offer_reference;
  new.contract_publication_version_id := v.id;
  new.contract_product_version_id := pv.id;
  new.contract_product_id := pv.contract_product_id;
  new.legal_bundle_version_id := v.legal_bundle_version_id;
  new.price_plan_id := v.price_plan_id;
  new.price_plan_version_id := v.price_plan_version_id;
  new.price_book_id := v.price_book_id;
  new.commercial_snapshot := coalesce(
    v.publication_snapshot->'commercial_snapshot',
    pv.commercial_snapshot,
    '{}'::jsonb
  );
  new.legal_snapshot := coalesce(
    v.publication_snapshot->'legal_snapshot',
    (select rendered_snapshot from public.legal_bundle_versions where id = v.legal_bundle_version_id),
    '{}'::jsonb
  );
  return new;
end
$$;

--
-- Name: gridex_bind_inbound_ediel_rule_pack_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_bind_inbound_ediel_rule_pack_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_rule_pack_id uuid;
  v_profile_id uuid;
  v_profile_key text;
  v_guide_version text;
  v_guide_revision text;
  v_source_hash text;
  v_effective_date date;
  v_match_count integer;
begin
  if new.direction <> 'inbound' or new.company_id is null or new.message_family not in ('PRODAT','UTILTS') then
    return new;
  end if;

  if new.canonical_rule_pack_id is not null
     and nullif(new.rule_profile_key,'') is not null
     and new.rule_profile_version_id is not null
     and nullif(new.rule_profile_version,'') is not null
     and nullif(new.rule_pack_checksum,'') is not null
     and coalesce(new.rule_pack_snapshot,'{}'::jsonb) <> '{}'::jsonb then
    return new;
  end if;

  v_effective_date := coalesce(new.message_received_at::date, new.created_at::date, current_date);

  select count(*)
  into v_match_count
  from public.ediel_message_profiles mp
  join public.ediel_rule_packs rp on rp.id = mp.rule_pack_id
  where mp.is_enabled = true
    and mp.profile->>'family' = new.message_family
    and mp.message_code = new.message_code
    and mp.direction in ('inbound','both')
    and rp.status in ('active','future')
    and rp.valid_from <= v_effective_date
    and (rp.valid_to is null or rp.valid_to >= v_effective_date);

  if v_match_count <> 1 then
    raise exception 'canonical_inbound_rule_profile_resolution_failed:%:%:%:%',
      new.message_family, coalesce(new.message_code,''), v_effective_date, v_match_count
      using errcode='23514';
  end if;

  select mp.rule_pack_id, mp.id, mp.profile_key, rp.guide_version, rp.guide_revision, rp.source_hash
  into v_rule_pack_id, v_profile_id, v_profile_key, v_guide_version, v_guide_revision, v_source_hash
  from public.ediel_message_profiles mp
  join public.ediel_rule_packs rp on rp.id = mp.rule_pack_id
  where mp.is_enabled = true
    and mp.profile->>'family' = new.message_family
    and mp.message_code = new.message_code
    and mp.direction in ('inbound','both')
    and rp.status in ('active','future')
    and rp.valid_from <= v_effective_date
    and (rp.valid_to is null or rp.valid_to >= v_effective_date)
  limit 1;

  new.canonical_rule_pack_id := v_rule_pack_id;
  new.rule_profile_key := v_profile_key;
  new.rule_profile_version_id := v_profile_id;
  new.rule_profile_version := v_guide_version || ':r' || v_guide_revision;
  new.rule_pack_checksum := v_source_hash;
  new.rule_pack_snapshot := jsonb_build_object(
    'family', new.message_family,
    'code', new.message_code,
    'direction', 'inbound',
    'environment', new.environment,
    'profileKey', v_profile_key,
    'profileVersionId', v_profile_id,
    'version', v_guide_version || ':r' || v_guide_revision,
    'checksum', v_source_hash,
    'authority', 'gridex_bind_inbound_ediel_rule_pack_evidence',
    'databaseRole', 'evidence_only',
    'effectiveDate', v_effective_date
  );

  return new;
end;
$$;

--
-- Name: gridex_bind_internal_customer_contract(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_bind_internal_customer_contract() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_publication_id uuid; v_publication public.contract_publication_versions%rowtype;
  v_product public.contract_product_versions%rowtype;
begin
  if new.contract_offer_id is null or new.contract_publication_version_id is not null then return new; end if;
  v_publication_id:=public.gridex_ensure_internal_contract_publication(new.company_id,new.contract_offer_id,coalesce(new.created_by,new.updated_by));
  select * into v_publication from public.contract_publication_versions where id=v_publication_id;
  select * into v_product from public.contract_product_versions where id=v_publication.contract_product_version_id;
  new.contract_publication_version_id:=v_publication.id;
  new.contract_product_version_id:=v_product.id;
  new.contract_product_id:=v_product.contract_product_id;
  new.legal_bundle_version_id:=v_publication.legal_bundle_version_id;
  new.price_plan_id:=v_publication.price_plan_id;
  new.price_plan_version_id:=v_publication.price_plan_version_id;
  new.price_book_id:=v_publication.price_book_id;
  new.offer_reference:=coalesce(new.offer_reference,v_publication.offer_reference);
  new.commercial_snapshot:=v_product.commercial_snapshot;
  new.legal_snapshot:=(select rendered_snapshot from public.legal_bundle_versions where id=v_publication.legal_bundle_version_id);
  return new;
end $$;

--
-- Name: gridex_bind_locked_portfolio_settlement_to_underlay(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_bind_locked_portfolio_settlement_to_underlay(p_actor_user_id uuid, p_company_id uuid, p_billing_underlay_id uuid, p_portfolio_monthly_settlement_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_underlay public.billing_underlays%rowtype; v_settlement public.portfolio_monthly_settlements%rowtype;
  v_snapshot jsonb; v_sha text; v_existing record;
begin
  if p_actor_user_id is null or not exists(select 1 from auth.users u where u.id=p_actor_user_id) then
    raise exception using errcode='42501',message='real_billing_actor_required';
  end if;
  if nullif(btrim(p_idempotency_key),'') is null then
    raise exception using errcode='22023',message='billing_settlement_idempotency_key_required';
  end if;
  select * into v_existing from public.portfolio_settlement_invoice_bindings
  where company_id=p_company_id and idempotency_key=p_idempotency_key;
  if found then return to_jsonb(v_existing); end if;
  select * into v_underlay from public.billing_underlays
  where id=p_billing_underlay_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='billing_underlay_not_found'; end if;
  select * into v_settlement from public.portfolio_monthly_settlements
  where id=p_portfolio_monthly_settlement_id and company_id=p_company_id
    and is_current and status in('final','locked') for update;
  if not found then raise exception using errcode='23514',message='final_or_locked_portfolio_settlement_required_for_billing'; end if;
  if v_settlement.price_area_code<>v_underlay.price_area
     or extract(year from v_settlement.delivery_month)::integer<>v_underlay.underlay_year
     or extract(month from v_settlement.delivery_month)::integer<>v_underlay.underlay_month
     or v_settlement.price_plan_version_id is distinct from v_underlay.price_plan_version_id then
    raise exception using errcode='23514',message='portfolio_settlement_underlay_scope_mismatch';
  end if;
  if not exists(
    select 1 from public.price_plan_versions v
    where v.id=v_settlement.price_plan_version_id and v.company_id=p_company_id
      and v.snapshot_json#>>'{portfolio_method,portfolio_id}'=v_settlement.portfolio_id::text
  ) then
    raise exception using errcode='23514',message='portfolio_settlement_contract_method_mismatch';
  end if;
  if v_underlay.contract_id is null or not exists(
    select 1 from public.customer_contracts c
    where c.id=v_underlay.contract_id and c.company_id=p_company_id
      and c.status in('signed','active')
      and c.price_plan_version_id=v_settlement.price_plan_version_id
  ) then
    raise exception using errcode='23514',message='portfolio_settlement_underlay_contract_mismatch';
  end if;
  if v_settlement.status='final' then
    perform set_config('gridex.portfolio_actor_user_id',p_actor_user_id::text,true);
    perform set_config('gridex.portfolio_audit_reason','locked by exact billing binding',true);
    update public.portfolio_monthly_settlements
    set status='locked',locked_by=p_actor_user_id,locked_at=now()
    where id=v_settlement.id;
    select * into v_settlement from public.portfolio_monthly_settlements
    where id=p_portfolio_monthly_settlement_id;
  end if;
  v_snapshot:=jsonb_build_object(
    'settlement_id',v_settlement.id,'company_id',v_settlement.company_id,
    'portfolio_id',v_settlement.portfolio_id,'price_plan_version_id',v_settlement.price_plan_version_id,
    'price_area_code',v_settlement.price_area_code,'delivery_month',v_settlement.delivery_month,
    'revision_no',v_settlement.revision_no,'status',v_settlement.status,
    'portfolio_price_ore_per_kwh',v_settlement.portfolio_price_ore_per_kwh,
    'management_fee_ore_per_kwh',v_settlement.management_fee_ore_per_kwh,
    'gross_energy_cost_sek',v_settlement.gross_energy_cost_sek,
    'hedging_result_sek',v_settlement.hedging_result_sek,
    'balancing_cost_sek',v_settlement.balancing_cost_sek,
    'other_allowed_cost_sek',v_settlement.other_allowed_cost_sek,
    'energy_volume_kwh',v_settlement.energy_volume_kwh,
    'calculation_snapshot_sha256',v_settlement.calculation_snapshot_sha256,'vat_rate',v_settlement.vat_rate,
    'vat_included',v_settlement.vat_included,
    'source',v_settlement.source,'locked_at',v_settlement.locked_at
  );
  v_sha:=encode(extensions.digest(convert_to(v_snapshot::text,'UTF8'),'sha256'),'hex');
  update public.billing_underlays set
    portfolio_id=v_settlement.portfolio_id,
    portfolio_monthly_settlement_id=v_settlement.id,
    portfolio_settlement_revision=v_settlement.revision_no,
    portfolio_settlement_sha256=v_sha,
    pricing_snapshot=coalesce(pricing_snapshot,'{}'::jsonb)||jsonb_build_object('portfolio_settlement',v_snapshot),
    updated_at=now()
  where id=v_underlay.id;
  insert into public.portfolio_settlement_invoice_bindings(
    company_id,billing_underlay_id,portfolio_monthly_settlement_id,
    settlement_snapshot,settlement_sha256,idempotency_key,bound_by
  ) values(
    p_company_id,v_underlay.id,v_settlement.id,v_snapshot,v_sha,btrim(p_idempotency_key),p_actor_user_id
  ) returning * into v_existing;
  return to_jsonb(v_existing);
end $$;

--
-- Name: gridex_bind_poa_authorization_document(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_bind_poa_authorization_document() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
begin
  if new.power_of_attorney_id is null
     or new.document_type <> 'power_of_attorney'
     or new.status not in ('active','signed','uploaded') then
    return new;
  end if;

  update public.powers_of_attorney p
     set document_id = new.id,
         metadata = coalesce(p.metadata, '{}'::jsonb) || jsonb_build_object(
           'authorization_document_id', new.id,
           'authorization_document_bound_at', now()
         ),
         updated_at = now()
   where p.id = new.power_of_attorney_id
     and p.company_id = new.company_id
     and p.customer_id = new.customer_id
     and p.document_id is null
     and coalesce(p.customer_site_id, p.site_id) is not distinct from new.site_id;

  return new;
end;
$$;

--
-- Name: gridex_block_contract_price_snapshot_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_block_contract_price_snapshot_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Escape hatch for explicit DBA maintenance (GDPR erasure, data repair):
  --   set local app.gridex_pricing_maintenance = 'on';
  if coalesce(current_setting('app.gridex_pricing_maintenance', true), '') = 'on' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  raise exception 'contract_price_snapshots are immutable (%). Create a new snapshot instead of mutating an existing one.', tg_op
    using errcode = 'P0001';
end;
$$;

--
-- Name: gridex_bridge_deprecated_canonical_event_bus(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_bridge_deprecated_canonical_event_bus() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_event public.canonical_domain_events%rowtype;
  v_event_type text;
begin
  select * into v_event
  from public.canonical_domain_events
  where id = new.domain_event_id;
  if not found then
    raise exception using errcode = '23503', message = 'canonical_domain_event_missing';
  end if;

  v_event_type := lower(regexp_replace(v_event.event_type, '_', '.', 'g'));
  if v_event_type !~ '^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$' then
    v_event_type := 'canonical.' || lower(regexp_replace(v_event.event_type, '[^a-zA-Z0-9]+', '_', 'g'));
  end if;

  insert into public.domain_events(
    id, company_id, event_type, aggregate_type, aggregate_id, actor_user_id,
    source, event_version, idempotency_key, payload, occurred_at, created_at
  ) values (
    v_event.id, v_event.company_id, v_event_type, v_event.aggregate_type,
    v_event.aggregate_id::text, v_event.created_by,
    'canonical_event_bus_deprecation',
    greatest(1, least(coalesce(v_event.aggregate_version, 1), 2147483647)::integer),
    'canonical:' || v_event.id::text,
    v_event.payload,
    v_event.occurred_at,
    v_event.occurred_at
  ) on conflict (id) do nothing;

  insert into public.event_outbox(
    id, company_id, domain_event_id, destination_type, destination_key,
    status, attempts, max_attempts, available_at, payload, created_at, updated_at
  ) values (
    new.id, new.company_id, v_event.id, 'webhook', 'webhook_fanout_v1',
    'queued', 0, 12, new.available_at,
    coalesce(new.payload, '{}'::jsonb)
      || jsonb_build_object('canonical_topic', new.topic),
    new.created_at, now()
  ) on conflict (id) do nothing;

  update public.canonical_event_outbox
  set status = 'processed',
      processed_at = coalesce(processed_at, now()),
      last_error = 'canonical_event_bus_deprecation:mirrored_to_domain_events',
      claimed_at = coalesce(claimed_at, now())
  where id = new.id;

  return new;
end
$_$;

--
-- Name: gridex_build_canonical_address(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_build_canonical_address(p_address_line_1 text, p_address_line_2 text, p_postal_code text, p_city text, p_country_code text DEFAULT 'SE'::text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_line1 text := nullif(btrim(coalesce(p_address_line_1, '')), '');
  v_line2 text := nullif(btrim(coalesce(p_address_line_2, '')), '');
  v_city text := nullif(btrim(coalesce(p_city, '')), '');
  v_country text := upper(coalesce(nullif(btrim(coalesce(p_country_code, '')), ''), 'SE'));
  v_postal text;
  v_formatted text;
begin
  if v_country !~ '^[A-Z]{2}$' then v_country := null; end if;
  begin
    v_postal := public.gridex_normalize_postal_code(p_postal_code, coalesce(v_country, 'SE'));
  exception when check_violation then
    v_postal := null;
  end;
  if v_line1 is null and v_line2 is null and v_postal is null and v_city is null then
    return '{}'::jsonb;
  end if;
  v_formatted := concat_ws(', ', v_line1, v_line2, nullif(concat_ws(' ', v_postal, v_city), ''), v_country);
  return jsonb_strip_nulls(jsonb_build_object(
    'address_line_1', v_line1,
    'address_line_2', v_line2,
    'postal_code', v_postal,
    'city', v_city,
    'country_code', v_country,
    'formatted', nullif(v_formatted, '')
  ));
end
$_$;

--
-- Name: gridex_bump_contract_publication_revision(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_bump_contract_publication_revision(p_company_id uuid, p_channel text, p_reason text, p_entity_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r public.contract_publication_revisions%rowtype;
  v_event_id uuid;
  v_tenant_reference text;
  v_event_data jsonb;
  v_occurred_at timestamptz:=now();
begin
  if p_company_id is null or p_channel not in ('website','api','internal','phone','partner') then
    raise exception using errcode='22023',message='publication_revision_scope_invalid';
  end if;

  select external_tenant_reference into v_tenant_reference
  from public.companies where id=p_company_id;
  if v_tenant_reference is null then
    raise exception using errcode='23502',message='external_tenant_reference_missing';
  end if;

  insert into public.contract_publication_revisions(company_id,channel,revision,revision_token,updated_at)
  values(p_company_id,p_channel,1,gen_random_uuid(),v_occurred_at)
  on conflict(company_id,channel) do update set
    revision=public.contract_publication_revisions.revision+1,
    revision_token=gen_random_uuid(),
    updated_at=v_occurred_at
  returning * into r;

  v_event_data:=jsonb_build_object(
    'tenant_reference',v_tenant_reference,
    'channel',p_channel,
    'publication_revision',r.revision,
    'revision_token',r.revision_token,
    'reason',p_reason,
    'timestamp',r.updated_at
  );

  insert into public.domain_events(
    company_id,event_type,aggregate_type,aggregate_id,source,idempotency_key,payload,occurred_at
  ) values(
    p_company_id,'contracts.publication.changed','contract_publication',
    coalesce(p_entity_id,'publication:'||p_channel),'database',
    format('contracts.publication.changed:%s:%s:%s',p_company_id,p_channel,r.revision),
    v_event_data,v_occurred_at
  ) on conflict(idempotency_key) where idempotency_key is not null do nothing
  returning id into v_event_id;

  if v_event_id is not null then
    insert into public.webhook_deliveries(
      company_id,webhook_subscription_id,domain_event_id,event_type,
      max_attempts,target_url,idempotency_key,payload
    )
    select
      p_company_id,ws.id,v_event_id,'contracts.publication.changed',
      ws.max_attempts,ws.endpoint_url,
      format('webhook:%s:%s',ws.id,v_event_id),
      jsonb_build_object(
        'id',v_event_id,
        'type','contracts.publication.changed',
        'event_id',v_event_id,
        'event_type','contracts.publication.changed',
        'created_at',v_occurred_at,
        'tenant_reference',v_tenant_reference,
        'environment',null,
        'customer_id',null,
        'customer_number',null,
        'external_customer_id',null,
        'aggregate',jsonb_build_object(
          'type','contract_publication',
          'id',coalesce(p_entity_id,'publication:'||p_channel)
        ),
        'data',v_event_data
      )
    from public.webhook_subscriptions ws
    where ws.company_id=p_company_id
      and ws.status='active'
      and ('*'=any(coalesce(ws.event_types,'{}'::text[]))
           or 'contracts.publication.changed'=any(coalesce(ws.event_types,'{}'::text[])))
    on conflict(idempotency_key) do nothing;
  end if;

  return jsonb_build_object(
    'tenant_reference',v_tenant_reference,
    'channel',r.channel,
    'revision',r.revision,
    'revision_token',r.revision_token,
    'updated_at',r.updated_at,
    'event_id',v_event_id
  );
end $$;

--
-- Name: gridex_can(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_can(p_permission text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare
  result boolean := false;
begin
  if p_permission is null or auth.uid() is null then
    return false;
  end if;
  if public.gridex_user_is_platform_admin() then
    return true;
  end if;

  if to_regclass('public.user_permission_overrides') is not null then
    select exists(
      select 1 from public.user_permission_overrides upo
      where upo.user_id = auth.uid()
        and upo.permission_key = p_permission
        and coalesce(upo.is_active, true) = true
        and coalesce(upo.effect, 'allow') = 'allow'
        and (upo.valid_from is null or upo.valid_from <= now())
        and (upo.valid_to is null or upo.valid_to >= now())
    ) into result;
    if result then return true; end if;
  end if;

  if to_regclass('public.user_permissions') is not null then
    select exists(
      select 1 from public.user_permissions up
      left join public.permissions p on p.id = up.permission_id
      where up.user_id = auth.uid()
        and coalesce(up.status, 'active') = 'active'
        and coalesce(up.is_active, true) = true
        and coalesce(up.effect, 'allow') = 'allow'
        and lower(coalesce(up.permission_key, p.key, '')) = lower(p_permission)
    ) into result;
    if result then return true; end if;
  end if;

  if to_regclass('public.role_permissions') is not null and to_regclass('public.user_roles') is not null then
    select exists(
      select 1
      from public.user_roles ur
      left join public.roles r on r.id = ur.role_id or lower(coalesce(r.key, '')) = lower(coalesce(ur.role, ''))
      left join public.role_permissions rp on rp.role_id = r.id or lower(coalesce(rp.role_key, '')) = lower(coalesce(ur.role, r.key, ''))
      left join public.permissions p on p.id = rp.permission_id
      where ur.user_id = auth.uid()
        and coalesce(ur.status, 'active') = 'active'
        and coalesce(ur.is_active, true) = true
        and coalesce(rp.effect, 'allow') = 'allow'
        and lower(coalesce(rp.permission_key, p.key, '')) = lower(p_permission)
    ) into result;
  end if;

  return coalesce(result, false);
exception when others then
  return false;
end;
$$;

--
-- Name: gridex_can_read_company(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_can_read_company(p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  select public.gridex_is_current_session_allowed()
    and (
      public.gridex_user_is_platform_admin()
      or exists (
        select 1
        from public.company_memberships membership
        join public.companies company on company.id = membership.company_id
        where membership.company_id = p_company_id
          and membership.user_id = (select auth.uid())
          and coalesce(membership.status, 'active') = 'active'
          and coalesce(membership.is_active, true)
          and company.status in ('active', 'onboarding', 'paused')
      )
    )
$$;

--
-- Name: gridex_can_write_company(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_can_write_company(p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  select public.gridex_is_current_session_allowed()
    and exists (
      select 1
      from public.companies company
      where company.id = p_company_id
        and company.status in ('active', 'onboarding')
    )
    and (
      public.gridex_user_is_platform_admin()
      or exists (
        select 1
        from public.company_memberships membership
        where membership.company_id = p_company_id
          and membership.user_id = (select auth.uid())
          and coalesce(membership.status, 'active') = 'active'
          and coalesce(membership.is_active, true)
          and coalesce(membership.membership_role, 'member')
            in ('owner', 'admin', 'company_admin', 'operations')
      )
    )
$$;

--
-- Name: gridex_canonicalize_company_org_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_canonicalize_company_org_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'INSERT' then
    new.org_number := coalesce(nullif(btrim(new.org_number), ''), nullif(btrim(new.organization_number), ''));
  elsif new.org_number is distinct from old.org_number then
    new.org_number := nullif(btrim(new.org_number), '');
  elsif new.organization_number is distinct from old.organization_number then
    -- Legacy writers are accepted as an input alias, then immediately projected
    -- into the canonical org_number field.
    new.org_number := nullif(btrim(new.organization_number), '');
  end if;

  new.organization_number := new.org_number;
  return new;
end
$$;

--
-- Name: gridex_canonicalize_publication_invoice_fee_v1(jsonb, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_canonicalize_publication_invoice_fee_v1(p_publication_snapshot jsonb, p_invoice_fee_sek numeric) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_snapshot jsonb:=coalesce(p_publication_snapshot,'{}'::jsonb);
  v_commercial jsonb:=coalesce(v_snapshot->'commercial_snapshot','{}'::jsonb);
  v_source_components jsonb;
  v_retained_components jsonb;
  v_visible boolean:=true;
begin
  if p_invoice_fee_sek is null or p_invoice_fee_sek<0 then
    return v_snapshot;
  end if;

  v_source_components:=case
    when jsonb_typeof(v_commercial->'price_components')='array'
      then v_commercial->'price_components'
    when jsonb_typeof(v_commercial->'price_components_snapshot')='array'
      then v_commercial->'price_components_snapshot'
    else '[]'::jsonb
  end;

  select coalesce(
    (
      select case
        when lower(coalesce(component.value->>'website_card_visible','')) in ('true','1') then true
        when lower(coalesce(component.value->>'website_card_visible','')) in ('false','0') then false
        when lower(coalesce(component.value->'metadata'->'visibility'->>'website_card','')) in ('true','1') then true
        when lower(coalesce(component.value->'metadata'->'visibility'->>'website_card','')) in ('false','0') then false
        else null
      end
      from jsonb_array_elements(v_source_components) component(value)
      where coalesce(
        nullif(component.value->>'component_code',''),
        nullif(component.value->>'component_type',''),
        nullif(component.value->'metadata'->>'component_code','')
      )='invoice_fee'
      limit 1
    ),
    case
      when lower(coalesce(v_commercial->'website_visibility'->>'invoice_fee','')) in ('true','1') then true
      when lower(coalesce(v_commercial->'website_visibility'->>'invoice_fee','')) in ('false','0') then false
      else null
    end,
    true
  ) into v_visible;

  select coalesce(jsonb_agg(component.value order by component.ordinality),'[]'::jsonb)
  into v_retained_components
  from jsonb_array_elements(v_source_components) with ordinality
    component(value,ordinality)
  where coalesce(
    nullif(component.value->>'component_code',''),
    nullif(component.value->>'component_type',''),
    nullif(component.value->'metadata'->>'component_code','')
  ) is distinct from 'invoice_fee';

  v_retained_components:=coalesce(v_retained_components,'[]'::jsonb)
    ||jsonb_build_array(jsonb_build_object(
      'component_code','invoice_fee',
      'component_type','invoice_fee',
      'name','Fakturaavgift',
      'amount',p_invoice_fee_sek,
      'calculation_type','per_invoice',
      'unit','sek_invoice',
      'priority',110,
      'status','active',
      'website_card_visible',v_visible,
      'metadata',jsonb_build_object(
        'lifecycle','per_invoice',
        'visibility',jsonb_build_object(
          'website_card',v_visible,
          'quote_breakdown',true,
          'checkout',true,
          'contract_document',true,
          'invoice',true
        )
      )
    ));

  v_commercial:=jsonb_set(
    v_commercial,
    '{price_components}',
    v_retained_components,
    true
  )||jsonb_build_object('invoice_fee_sek',p_invoice_fee_sek);

  return jsonb_set(v_snapshot,'{commercial_snapshot}',v_commercial,true);
end
$$;

--
-- Name: FUNCTION gridex_canonicalize_publication_invoice_fee_v1(p_publication_snapshot jsonb, p_invoice_fee_sek numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_canonicalize_publication_invoice_fee_v1(p_publication_snapshot jsonb, p_invoice_fee_sek numeric) IS 'Upserts exactly one canonical per-invoice fee component, including explicit 0 SEK, into a publication commercial snapshot.';

--
-- Name: gridex_capture_ediel_route_profile_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_capture_ediel_route_profile_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_route_version integer;
  v_actor uuid;
begin
  if TG_OP = 'UPDATE' and to_jsonb(old) = to_jsonb(new) then
    return new;
  end if;

  v_route_version := coalesce(new.route_version, 1);
  v_actor := coalesce(new.updated_by, new.created_by);

  insert into public.ediel_route_history (
    route_profile_id,
    company_id,
    route_version,
    snapshot,
    change_reason,
    created_by
  )
  values (
    new.id,
    new.company_id,
    v_route_version,
    to_jsonb(new),
    case when TG_OP = 'INSERT' then 'created' else 'updated' end,
    v_actor
  )
  on conflict (route_profile_id, route_version) do nothing;

  return new;
end;
$$;

--
-- Name: gridex_capture_ediel_rule_pack_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_capture_ediel_rule_pack_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_profile_rule_pack_id uuid;
begin
  if new.direction='outbound' and new.message_family in ('PRODAT','UTILTS','CONTRL','APERAK','UTILTS_ERR') then
    if new.company_id is null then
      raise exception 'outbound_ediel_company_id_required' using errcode='23502';
    end if;

    if nullif(new.rule_profile_key,'') is null or new.rule_profile_version_id is null
       or nullif(new.rule_profile_version,'') is null or nullif(new.rule_pack_checksum,'') is null
       or coalesce(new.rule_pack_snapshot,'{}'::jsonb)='{}'::jsonb then
      raise exception 'outbound_ediel_rule_pack_snapshot_required' using errcode='23514';
    end if;

    select mp.rule_pack_id into v_profile_rule_pack_id
    from public.ediel_message_profiles mp
    where mp.id = new.rule_profile_version_id
      and mp.is_enabled = true;

    if v_profile_rule_pack_id is null then
      raise exception 'canonical_ediel_message_profile_required:%', new.rule_profile_version_id using errcode='23503';
    end if;

    if new.canonical_rule_pack_id is null or new.canonical_rule_pack_id <> v_profile_rule_pack_id then
      raise exception 'canonical_ediel_rule_pack_profile_mismatch:%:%', coalesce(new.canonical_rule_pack_id::text,'null'), v_profile_rule_pack_id::text using errcode='23514';
    end if;

    insert into public.ediel_rule_pack_snapshots(
      company_id,ediel_message_id,profile_key,rule_profile_version_id,profile_version,checksum,snapshot
    ) values (
      new.company_id,new.id,new.rule_profile_key,new.rule_profile_version_id,new.rule_profile_version,new.rule_pack_checksum,new.rule_pack_snapshot
    ) on conflict(ediel_message_id) do update set
      company_id=excluded.company_id,
      profile_key=excluded.profile_key,
      rule_profile_version_id=excluded.rule_profile_version_id,
      profile_version=excluded.profile_version,
      checksum=excluded.checksum,
      snapshot=excluded.snapshot;
  end if;
  return new;
end;
$$;

--
-- Name: gridex_capture_manual_email_template_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_capture_manual_email_template_audit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.request_id is null then
    return new;
  end if;

  update public.grid_owner_information_requests r
  set rendered_subject = new.subject,
      rendered_body_hash = encode(
        extensions.digest(coalesce(new.body_text, new.body_html, ''), 'sha256'),
        'hex'
      ),
      updated_at = greatest(r.updated_at, coalesce(new.updated_at, now()))
  where r.id = new.request_id
    and r.company_id = new.company_id;

  return new;
end;
$$;

--
-- Name: FUNCTION gridex_capture_manual_email_template_audit(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_capture_manual_email_template_audit() IS 'Captures exact rendered manual e-mail subject and SHA-256 body hash on the originating grid-owner information request.';

--
-- Name: gridex_capture_portfolio_monthly_price_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_capture_portfolio_monthly_price_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  row_id uuid;
  row_company_id uuid;
  row_version integer;
  row_changed_by uuid;
  row_old jsonb;
  row_new jsonb;
begin
  if tg_op = 'DELETE' then
    row_id := old.id;
    row_company_id := old.company_id;
    row_version := coalesce(old.version_number, 1);
    row_changed_by := coalesce(old.updated_by, old.created_by);
    row_old := to_jsonb(old);
    row_new := null;
  elsif tg_op = 'INSERT' then
    row_id := new.id;
    row_company_id := new.company_id;
    row_version := coalesce(new.version_number, 1);
    row_changed_by := coalesce(new.updated_by, new.created_by);
    row_old := null;
    row_new := to_jsonb(new);
  else
    row_id := new.id;
    row_company_id := new.company_id;
    row_version := coalesce(new.version_number, old.version_number, 1);
    row_changed_by := coalesce(new.updated_by, new.created_by, old.updated_by, old.created_by);
    row_old := to_jsonb(old);
    row_new := to_jsonb(new);
  end if;

  insert into public.portfolio_monthly_price_history(
    portfolio_price_id,
    company_id,
    version_number,
    action,
    old_values,
    new_values,
    changed_by
  ) values (
    row_id,
    row_company_id,
    row_version,
    lower(tg_op),
    row_old,
    row_new,
    row_changed_by
  );

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;

--
-- Name: gridex_capture_signed_contract_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_capture_signed_contract_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_acceptance jsonb; v_sha text; v_pub uuid; v_product_version uuid; v_product uuid; v_bundle uuid;
begin
  if new.status not in ('signed','active') or new.signed_at is null then return new; end if;
  if tg_op='UPDATE' and old.status in ('signed','active') and old.signed_at is not null then return new; end if;

  if new.contract_publication_version_id is null and new.public_contract_offer_id is not null then
    select cpv.id,cpv.contract_product_version_id,pv.contract_product_id,cpv.legal_bundle_version_id
      into v_pub,v_product_version,v_product,v_bundle
    from public.contract_publication_versions cpv
    join public.contract_product_versions pv on pv.id=cpv.contract_product_version_id
    where cpv.legacy_public_contract_offer_id=new.public_contract_offer_id
    order by cpv.version_number desc limit 1;
    new.contract_publication_version_id:=v_pub;
    new.contract_product_version_id:=coalesce(new.contract_product_version_id,v_product_version);
    new.contract_product_id:=coalesce(new.contract_product_id,v_product);
    new.legal_bundle_version_id:=coalesce(new.legal_bundle_version_id,v_bundle);
  end if;

  new.locked_at:=coalesce(new.locked_at,now());
  new.commercial_snapshot:=coalesce(nullif(new.commercial_snapshot,'{}'::jsonb),jsonb_build_object(
    'contract_name',new.contract_name,'contract_type',new.contract_type,'price_plan_id',new.price_plan_id,
    'price_plan_version_id',new.price_plan_version_id,'price_snapshot',new.price_snapshot,'campaign_snapshot',new.campaign_snapshot));
  new.legal_snapshot:=coalesce(nullif(new.legal_snapshot,'{}'::jsonb),jsonb_build_object(
    'legal_bundle_version_id',new.legal_bundle_version_id,'legal_versions_snapshot',new.legal_versions_snapshot,
    'terms_version',new.terms_version,'terms_signed_version',new.terms_signed_version));
  v_acceptance:=jsonb_build_object('customer_contract_id',new.id,'company_id',new.company_id,'accepted_at',new.signed_at,
    'offer_reference',new.offer_reference,'publication_version_id',new.contract_publication_version_id,
    'commercial_snapshot',new.commercial_snapshot,'legal_snapshot',new.legal_snapshot,'signature_snapshot_sha256',new.signature_snapshot_sha256);
  v_sha:=encode(digest(v_acceptance::text,'sha256'),'hex');
  insert into public.customer_contract_acceptances(company_id,customer_contract_id,contract_publication_version_id,accepted_at,channel,signing_method,customer_identity_snapshot,power_of_attorney_snapshot,acceptance_snapshot,acceptance_sha256)
  values(new.company_id,new.id,new.contract_publication_version_id,new.signed_at,coalesce(new.source_type,'website'),'server_verified',jsonb_build_object('customer_id',new.customer_id), '{}'::jsonb,v_acceptance,v_sha)
  on conflict do nothing;
  insert into public.customer_contract_evidence(company_id,customer_contract_id,evidence_type,evidence_snapshot,evidence_sha256,captured_at)
  values(new.company_id,new.id,'contract_acceptance',v_acceptance,v_sha,new.signed_at) on conflict do nothing;
  return new;
end $$;

--
-- Name: billing_automation_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.billing_automation_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    billing_month text NOT NULL,
    target_system text NOT NULL,
    export_format text NOT NULL,
    send_to_partner boolean DEFAULT false NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 5 NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    locked_by text,
    last_error text,
    result jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT billing_automation_jobs_attempts_check CHECK ((attempts >= 0)),
    CONSTRAINT billing_automation_jobs_billing_month_check CHECK ((billing_month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'::text)),
    CONSTRAINT billing_automation_jobs_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 20))),
    CONSTRAINT billing_automation_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'completed'::text, 'completed_with_blockers'::text, 'failed'::text, 'cancelled'::text])))
);

ALTER TABLE ONLY public.billing_automation_jobs FORCE ROW LEVEL SECURITY;

--
-- Name: gridex_claim_billing_automation_jobs(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_claim_billing_automation_jobs(p_worker_id text, p_limit integer DEFAULT 8) RETURNS SETOF public.billing_automation_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if nullif(btrim(p_worker_id),'') is null then raise exception 'worker_id_required'; end if;
  if p_limit < 1 or p_limit > 50 then raise exception 'invalid_claim_limit'; end if;
  return query
  with candidates as (
    select j.id
    from public.billing_automation_jobs j
    where j.status in ('queued','failed')
      and j.available_at <= now()
      and j.attempts < j.max_attempts
      and (j.locked_at is null or j.locked_at < now() - interval '30 minutes')
    order by j.available_at,j.created_at,j.company_id
    for update skip locked
    limit p_limit
  )
  update public.billing_automation_jobs j
     set status='running', locked_at=now(), locked_by=p_worker_id,
         attempts=j.attempts+1, updated_at=now(), last_error=null
    from candidates c
   where j.id=c.id
  returning j.*;
end $$;

--
-- Name: customer_operation_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_operation_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    customer_site_id uuid,
    metering_point_id uuid,
    job_type text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    priority smallint DEFAULT 100 NOT NULL,
    idempotency_key text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    result jsonb DEFAULT '{}'::jsonb NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 5 NOT NULL,
    run_after timestamp with time zone DEFAULT now() NOT NULL,
    locked_at timestamp with time zone,
    locked_by text,
    last_error text,
    created_by uuid,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    workflow_id uuid,
    payload_version integer DEFAULT 1 NOT NULL,
    last_error_code text,
    last_error_message text,
    operation_id uuid DEFAULT gen_random_uuid() NOT NULL,
    lock_token uuid,
    heartbeat_at timestamp with time zone,
    request_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    stale_reason text,
    trace_id uuid DEFAULT gen_random_uuid(),
    lifecycle_blocked_by_tenant boolean DEFAULT false NOT NULL,
    lifecycle_previous_status text,
    review_owner text,
    review_owner_user_id uuid,
    review_reason_code text,
    review_sla_due_at timestamp with time zone,
    review_environment text DEFAULT 'unknown'::text NOT NULL,
    review_resolved_at timestamp with time zone,
    CONSTRAINT customer_operation_jobs_attempts_check CHECK (((attempts >= 0) AND (max_attempts > 0))),
    CONSTRAINT customer_operation_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'waiting_response'::text, 'completed'::text, 'needs_review'::text, 'blocked'::text, 'delivery_uncertain'::text, 'failed'::text, 'skipped'::text, 'cancelled'::text])))
);

--
-- Name: COLUMN customer_operation_jobs.workflow_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.customer_operation_jobs.workflow_id IS 'Canonical workflow correlation. A customer_application_continuation job is created atomically with provisioning commit.';

--
-- Name: gridex_claim_customer_operation_jobs(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_claim_customer_operation_jobs(p_worker_id text, p_limit integer DEFAULT 20) RETURNS SETOF public.customer_operation_jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
begin
  -- Terminalize jobs that have exhausted retries instead of leaving stale running rows forever.
  update public.customer_operation_jobs jobs
  set status='failed',
      last_error=coalesce(jobs.last_error,'customer_operation_retry_exhausted'),
      last_error_code=coalesce(jobs.last_error_code,'retry_exhausted'),
      last_error_message=coalesce(jobs.last_error_message,'Customer operation retry limit exhausted'),
      stale_reason=case when jobs.status='running'
        then coalesce(jobs.stale_reason,'retry_exhausted_after_stale_lock')
        else jobs.stale_reason end,
      completed_at=coalesce(jobs.completed_at,now()),
      locked_at=null,
      locked_by=null,
      lock_token=null,
      heartbeat_at=null,
      updated_at=now()
  from public.companies company
  where company.id=jobs.company_id
    and company.status in ('active','onboarding')
    and coalesce(jobs.lifecycle_blocked_by_tenant,false)=false
    and jobs.attempts>=jobs.max_attempts
    and (
      (jobs.status='queued' and jobs.run_after<=now())
      or
      (jobs.status='running' and (
        jobs.locked_at is null
        or jobs.lock_token is null
        or jobs.locked_at<now()-interval '15 minutes'
      ))
    );

  return query
  with candidates as (
    select jobs.id
    from public.customer_operation_jobs jobs
    join public.companies company on company.id=jobs.company_id
    where company.status in ('active','onboarding')
      and coalesce(jobs.lifecycle_blocked_by_tenant,false)=false
      and jobs.attempts < jobs.max_attempts
      and (
        (
          jobs.status='queued'
          and jobs.run_after<=now()
          and (jobs.locked_at is null or jobs.lock_token is null or jobs.locked_at<now()-interval '15 minutes')
        )
        or
        (
          jobs.status='running'
          and (jobs.locked_at is null or jobs.lock_token is null or jobs.locked_at<now()-interval '15 minutes')
        )
      )
    order by jobs.priority asc,jobs.run_after asc,jobs.created_at asc
    for update of jobs skip locked
    limit greatest(1,least(coalesce(p_limit,20),100))
  )
  update public.customer_operation_jobs jobs
  set status='running',
      attempts=jobs.attempts+1,
      locked_at=now(),
      locked_by=nullif(trim(p_worker_id),''),
      lock_token=gen_random_uuid(),
      heartbeat_at=now(),
      last_error=case when jobs.status='running'
        then coalesce(jobs.last_error,'stale_customer_operation_lock_reclaimed')
        else jobs.last_error end,
      updated_at=now()
  from candidates
  where jobs.id=candidates.id
  returning jobs.*;
end
$$;

--
-- Name: invoice_provider_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.invoice_provider_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid,
    provider text NOT NULL,
    provider_event_id text,
    provider_invoice_guid text,
    event_type text NOT NULL,
    status text DEFAULT 'received'::text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    matched_invoice_export_item_id uuid,
    idempotency_hash text,
    received_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    environment text NOT NULL,
    processing_token uuid,
    processing_started_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    failure_reason text,
    CONSTRAINT invoice_provider_events_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT invoice_provider_events_environment_check CHECK (((environment IS NULL) OR (environment = ANY (ARRAY['test'::text, 'production'::text])))),
    CONSTRAINT invoice_provider_events_status_check CHECK ((status = ANY (ARRAY['received'::text, 'processing'::text, 'processed'::text, 'needs_review'::text, 'failed'::text, 'dead_letter'::text])))
);

--
-- Name: gridex_claim_invoice_provider_events(uuid, text[], integer, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_claim_invoice_provider_events(p_company_id uuid, p_statuses text[], p_limit integer, p_processing_token uuid, p_max_age_days integer DEFAULT 365) RETURNS SETOF public.invoice_provider_events
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if p_processing_token is null or p_statuses is null or coalesce(array_length(p_statuses,1),0)=0
     or p_limit is null or p_limit < 1 or p_limit > 500
     or p_max_age_days is null or p_max_age_days < 1 or p_max_age_days > 3650 then
    raise exception 'invalid_provider_event_claim_arguments' using errcode='22023';
  end if;
  if exists(select 1 from unnest(p_statuses) s where s not in ('received','needs_review','failed')) then
    raise exception 'invalid_provider_event_claim_status' using errcode='22023';
  end if;

  return query
  with candidates as (
    select e.id
      from public.invoice_provider_events e
     where e.company_id is not null
       and (p_company_id is null or e.company_id=p_company_id)
       and e.received_at >= clock_timestamp()-(p_max_age_days::text||' days')::interval
       and (
         e.status=any(p_statuses)
         or (e.status='processing' and e.processing_started_at < clock_timestamp()-interval '15 minutes')
       )
     order by e.received_at,e.id
     for update skip locked
     limit p_limit
  ), claimed as (
    update public.invoice_provider_events e
       set status='processing',
           processing_token=p_processing_token,
           processing_started_at=clock_timestamp(),
           attempt_count=coalesce(e.attempt_count,0)+1,
           failure_reason=null
      from candidates c
     where e.id=c.id
     returning e.*
  )
  select * from claimed;
end;
$$;

--
-- Name: gridex_claim_spot_price_import_job(text, text, date, uuid, interval, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_claim_spot_price_import_job(p_provider text, p_price_area text, p_calendar_date date, p_company_id uuid DEFAULT NULL::uuid, p_stale_after interval DEFAULT '00:15:00'::interval, p_force boolean DEFAULT false) RETURNS TABLE(id uuid, claimed boolean, status text, attempt_count integer, correlation_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_job public.spot_price_import_jobs%rowtype;
begin
  if upper(coalesce(p_price_area,'')) not in ('SE1','SE2','SE3','SE4') then
    raise exception 'invalid_price_area' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(lower(trim(p_provider)) || ':' || upper(trim(p_price_area)) || ':' || p_calendar_date::text,0));

  select * into v_job
  from public.spot_price_import_jobs j
  where j.provider=lower(trim(p_provider))
    and j.price_area=upper(trim(p_price_area))
    and j.calendar_date=p_calendar_date
  for update;

  if not found then
    insert into public.spot_price_import_jobs(
      company_id,provider,price_area,calendar_date,status,attempt_count,started_at,completed_at,
      last_error_code,last_error_message,next_attempt_at,updated_at
    ) values (
      p_company_id,lower(trim(p_provider)),upper(trim(p_price_area)),p_calendar_date,'running',1,now(),null,
      null,null,null,now()
    ) returning * into v_job;
    return query select v_job.id,true,v_job.status,v_job.attempt_count,v_job.correlation_id;
    return;
  end if;

  if v_job.status='completed' and not coalesce(p_force,false) then
    return query select v_job.id,false,v_job.status,v_job.attempt_count,v_job.correlation_id;
    return;
  end if;

  if v_job.status='running' and v_job.started_at > now()-p_stale_after then
    return query select v_job.id,false,v_job.status,v_job.attempt_count,v_job.correlation_id;
    return;
  end if;

  if v_job.status='retry_wait' and v_job.next_attempt_at is not null and v_job.next_attempt_at > now() then
    return query select v_job.id,false,v_job.status,v_job.attempt_count,v_job.correlation_id;
    return;
  end if;

  update public.spot_price_import_jobs j
  set company_id=coalesce(p_company_id,j.company_id),
      status='running',
      attempt_count=j.attempt_count+1,
      started_at=now(),
      completed_at=null,
      next_attempt_at=null,
      last_error_code=null,
      last_error_message=null,
      correlation_id=gen_random_uuid(),
      updated_at=now()
  where j.id=v_job.id
  returning * into v_job;

  return query select v_job.id,true,v_job.status,v_job.attempt_count,v_job.correlation_id;
end;
$$;

--
-- Name: gridex_cleanup_orphan_contract_pricing(uuid, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_cleanup_orphan_contract_pricing(p_company_id uuid, p_older_than interval DEFAULT '24:00:00'::interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_books integer:=0; v_versions integer:=0;
begin
  if p_company_id is null then raise exception using errcode='22023',message='company_required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':orphan-pricing-cleanup',0));
  perform set_config('gridex.pricing_version_write','on',true);
  delete from public.price_books b where b.company_id=p_company_id and b.locked_at is null and b.created_at<now()-p_older_than
    and not exists(select 1 from public.public_contract_offers o where o.price_book_id=b.id)
    and not exists(select 1 from public.contract_publication_versions v where v.price_book_id=b.id)
    and not exists(select 1 from public.contract_offers o where o.price_book_id=b.id)
    and not exists(select 1 from public.customer_contracts c where c.price_book_id=b.id)
    and not exists(select 1 from public.contract_price_snapshots s where s.price_book_id=b.id)
    and not exists(select 1 from public.billing_underlays u where u.price_book_id=b.id)
    and not exists(select 1 from public.billing_underlay_items i where i.price_book_id=b.id);
  get diagnostics v_books=row_count;
  delete from public.price_plan_versions v where v.company_id=p_company_id and v.locked_at is null and v.created_at<now()-p_older_than
    and not exists(select 1 from public.public_contract_offers o where o.price_plan_version_id=v.id)
    and not exists(select 1 from public.contract_publication_versions p where p.price_plan_version_id=v.id)
    and not exists(select 1 from public.contract_offers o where o.price_plan_version_id=v.id)
    and not exists(select 1 from public.customer_contracts c where c.price_plan_version_id=v.id)
    and not exists(select 1 from public.contract_price_snapshots s where s.price_plan_version_id=v.id)
    and not exists(select 1 from public.billing_underlays u where u.price_plan_version_id=v.id)
    and not exists(select 1 from public.billing_underlay_items i where i.price_plan_version_id=v.id);
  get diagnostics v_versions=row_count;
  return jsonb_build_object('company_id',p_company_id,'price_books_deleted',v_books,'price_versions_deleted',v_versions);
end $$;

--
-- Name: gridex_cleanup_unused_contract_drafts(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_cleanup_unused_contract_drafts(p_company_id uuid, p_actor_user_id uuid, p_apply boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record;
  v_preview jsonb;
  v_item jsonb;
  v_items jsonb:='[]'::jsonb;
  v_deleted integer:=0;
  v_deletable integer:=0;
  v_blocked integer:=0;
  v_errors integer:=0;
  v_sqlstate text;
  v_message text;
  v_detail text;
  v_hint text;
  v_reference text;
begin
  perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.delete_unused');

  for r in
    select co.id,co.name,co.lifecycle_status,co.updated_at
    from public.contract_offers co
    where co.company_id=p_company_id
      and co.lifecycle_status in ('draft','ready')
    order by co.updated_at,co.id
    limit 100
  loop
    begin
      v_preview:=public.gridex_preview_delete_unused_contract(p_company_id,r.id);
      if coalesce((v_preview->>'can_delete')::boolean,false) then
        v_deletable:=v_deletable+1;
        if p_apply then
          v_item:=public.gridex_remove_internal_contract_offer(
            p_company_id,r.id,'safe_delete',p_actor_user_id
          );
          if coalesce((v_item->>'ok')::boolean,false)
             and v_item->>'mode'='deleted' then
            v_deleted:=v_deleted+1;
          else
            v_blocked:=v_blocked+1;
          end if;
        else
          v_item:=jsonb_build_object(
            'ok',true,'offer_id',r.id,'name',r.name,
            'action','would_delete','preview',v_preview
          );
        end if;
      else
        v_blocked:=v_blocked+1;
        v_item:=jsonb_build_object(
          'ok',false,'offer_id',r.id,'name',r.name,
          'action','blocked',
          'reason_codes',coalesce(v_preview->'reason_codes','[]'::jsonb),
          'recommended_action',coalesce(v_preview->>'recommended_action','review'),
          'preview',v_preview
        );
      end if;
    exception when others then
      get stacked diagnostics
        v_sqlstate=returned_sqlstate,
        v_message=message_text,
        v_detail=pg_exception_detail,
        v_hint=pg_exception_hint;
      v_errors:=v_errors+1;
      v_reference:=upper(substr(replace(gen_random_uuid()::text,'-',''),1,12));
      insert into public.contract_lifecycle_operation_errors(
        reference,company_id,actor_user_id,action,offer_id,sqlstate,
        error_message,error_detail,error_hint,metadata
      ) values(
        v_reference,p_company_id,p_actor_user_id,
        'gridex_cleanup_unused_contract_drafts',r.id,v_sqlstate,
        coalesce(v_message,'unknown_error'),v_detail,v_hint,
        jsonb_build_object('apply',p_apply,'lifecycle_status',r.lifecycle_status)
      );
      v_item:=jsonb_build_object(
        'ok',false,'offer_id',r.id,'name',r.name,'action','error',
        'reference',v_reference,'sqlstate',v_sqlstate,
        'message','Avtalet kunde inte behandlas i batchen.'
      );
    end;
    v_items:=v_items||jsonb_build_array(v_item);
  end loop;

  return jsonb_build_object(
    'ok',true,'apply',p_apply,
    'scanned_count',jsonb_array_length(v_items),
    'deletable_count',v_deletable,
    'deleted_count',v_deleted,
    'blocked_count',v_blocked,
    'error_count',v_errors,
    'batch_limit',100,
    'items',v_items
  );
end $$;

--
-- Name: FUNCTION gridex_cleanup_unused_contract_drafts(p_company_id uuid, p_actor_user_id uuid, p_apply boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_cleanup_unused_contract_drafts(p_company_id uuid, p_actor_user_id uuid, p_apply boolean) IS 'Batch-safe dry-run/apply for at most 100 draft/ready offers. Per-offer exceptions are isolated and durably referenced.';

--
-- Name: gridex_close_contract_product(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_close_contract_product(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  v_before jsonb;
  v_offer_ids uuid[]:='{}'::uuid[];
  v_product_version_ids uuid[]:='{}'::uuid[];
  v_assignment_ids uuid[]:='{}'::uuid[];
  v_public_offer_ids uuid[]:='{}'::uuid[];
  v_publication_version_ids uuid[]:='{}'::uuid[];
  v_offer_references text[]:='{}'::text[];
  v_channels bigint:=0;
  v_publications bigint:=0;
  v_versions bigint:=0;
  v_public_offers bigint:=0;
  v_quotes bigint:=0;
  v_event_id uuid;
  v_aggregate_id text;
  v_readiness jsonb;
begin
  perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.close');
  if nullif(btrim(coalesce(p_reason,'')),'') is null then
    return jsonb_build_object('ok',false,'changed',false,'code','contract_close_reason_required');
  end if;

  select * into o
  from public.contract_offers co
  where co.id=p_offer_id and co.company_id=p_company_id
  for update;
  if not found then
    return jsonb_build_object('ok',false,'changed',false,'code','contract_not_found');
  end if;
  if o.lifecycle_status='closed' then
    return jsonb_build_object('ok',true,'changed',false,'mode','closed','code','contract_already_closed');
  end if;

  -- Repeat the same operation-specific readiness used by the admin preview
  -- after the target row has been locked. This prevents a stale UI preview
  -- from becoming the security or state-transition boundary.
  v_readiness:=public.gridex_validate_contract_readiness_v2(
    p_company_id,o.id,'close',null
  );
  if not coalesce((v_readiness->>'can_execute')::boolean,false) then
    return jsonb_build_object(
      'ok',false,'changed',false,'mode','blocked',
      'code','invalid_contract_transition',
      'current_status',o.lifecycle_status,'requested_status','closed',
      'blockers',coalesce(v_readiness->'blockers','[]'::jsonb),
      'readiness',v_readiness
    );
  end if;
  v_before:=to_jsonb(o);
  v_aggregate_id:=coalesce(o.contract_product_id,o.id)::text;

  -- Close only the selected version and currently sellable siblings. Historic
  -- superseded/expired/archived versions keep their original lifecycle status.
  v_offer_ids:=array(
    select co.id
    from public.contract_offers co
    where co.company_id=p_company_id
      and (
        co.id=o.id
        or (
          o.contract_product_id is not null
          and co.contract_product_id=o.contract_product_id
          and co.lifecycle_status in ('published','paused')
        )
      )
      and co.lifecycle_status not in ('superseded','expired','archived','closed')
    order by co.id
  );
  v_product_version_ids:=array(
    select distinct co.contract_product_version_id
    from public.contract_offers co
    where co.id=any(v_offer_ids) and co.contract_product_version_id is not null
    order by co.contract_product_version_id
  );
  v_assignment_ids:=array(
    select ta.id
    from public.tenant_contract_assignments ta
    where ta.company_id=p_company_id
      and ta.contract_product_version_id=any(v_product_version_ids)
    order by ta.id
  );
  v_public_offer_ids:=array(
    select pco.id
    from public.public_contract_offers pco
    where pco.company_id=p_company_id and (
      pco.source_contract_offer_id=any(v_offer_ids)
      or pco.contract_product_version_id=any(v_product_version_ids)
    )
    order by pco.id
  );
  v_publication_version_ids:=array(
    select cpv.id
    from public.contract_publication_versions cpv
    join public.contract_publications cp on cp.id=cpv.contract_publication_id
    where cp.assignment_id=any(v_assignment_ids)
      and cpv.contract_product_version_id=any(v_product_version_ids)
    order by cpv.id
  );
  v_offer_references:=public.gridex_contract_offer_references_v1(
    p_company_id,
    v_public_offer_ids,
    v_product_version_ids,
    v_publication_version_ids
  );

  perform set_config('gridex.version_transition','on',true);
  perform set_config('gridex.public_offer_write','on',true);

  update public.tenant_contract_channels ch
  set status='ended',valid_to=coalesce(ch.valid_to,now()),
      updated_by=p_actor_user_id,updated_at=now()
  where ch.assignment_id=any(v_assignment_ids) and ch.status<>'ended';
  get diagnostics v_channels=row_count;

  update public.contract_publications cp
  set status='ended',updated_at=now()
  where cp.assignment_id=any(v_assignment_ids)
    and cp.status not in ('ended','archived');
  get diagnostics v_publications=row_count;

  update public.contract_publication_versions cpv
  set status='ended',valid_to=coalesce(cpv.valid_to,now())
  where cpv.contract_publication_id in (
    select cp.id from public.contract_publications cp
    where cp.assignment_id=any(v_assignment_ids)
  ) and cpv.status not in ('ended','archived');
  get diagnostics v_versions=row_count;

  update public.public_contract_offers pco
  set lifecycle_status='closed',publication_status='unpublished',
      is_public=false,website_enabled=false,website_cta_enabled=false,
      closed_at=coalesce(pco.closed_at,now()),closed_by=p_actor_user_id,
      close_reason=btrim(p_reason),updated_by=p_actor_user_id,updated_at=now()
  where pco.id=any(v_public_offer_ids)
    and pco.lifecycle_status in ('draft','ready','published','paused');
  get diagnostics v_public_offers=row_count;

  update public.website_contract_quotes q
  set status='revoked',updated_at=now()
  where q.company_id=p_company_id and q.status='active' and (
    q.offer_reference=any(v_offer_references)
    or q.contract_product_version_id=any(v_product_version_ids)
  );
  get diagnostics v_quotes=row_count;

  update public.tenant_contract_assignments ta
  set status='ended',valid_to=coalesce(ta.valid_to,now()),updated_at=now()
  where ta.id=any(v_assignment_ids) and ta.status<>'ended';

  update public.contract_offers co
  set lifecycle_status='closed',status='inactive',is_active=false,
      closed_at=coalesce(co.closed_at,now()),closed_by=p_actor_user_id,
      close_reason=btrim(p_reason),updated_by=p_actor_user_id,updated_at=now()
  where co.id=any(v_offer_ids)
    and co.lifecycle_status in ('draft','ready','published','paused');

  if o.contract_product_id is not null then
    update public.contract_products cp
    set status='closed',updated_at=now()
    where cp.id=o.contract_product_id and cp.company_id=p_company_id;
  end if;

  insert into public.audit_logs(
    company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata
  ) values(
    p_company_id,p_actor_user_id,'contract_product',v_aggregate_id,
    'contract.closed',v_before,
    jsonb_build_object('lifecycle_status','closed','closed_at',now(),'close_reason',btrim(p_reason)),
    jsonb_build_object(
      'offer_id',o.id,'legacy_without_product_id',o.contract_product_id is null,
      'affected_channels',v_channels,'affected_publications',v_publications,
      'affected_publication_versions',v_versions,'affected_public_offers',v_public_offers,
      'revoked_unused_quotes',v_quotes
    )
  );

  insert into public.domain_events(
    company_id,event_type,aggregate_type,aggregate_id,actor_user_id,source,idempotency_key,payload
  ) values(
    p_company_id,'contract.closed','contract_product',v_aggregate_id,
    p_actor_user_id,'database',
    format('contract.closed:%s:%s',v_aggregate_id,extract(epoch from now())::bigint),
    jsonb_build_object(
      'contract_product_id',o.contract_product_id,
      'offer_id',o.id,'reason',btrim(p_reason)
    )
  ) returning id into v_event_id;

  insert into public.event_outbox(
    company_id,domain_event_id,destination_type,destination_key,payload
  ) values(
    p_company_id,v_event_id,'webhook','contract.closed',
    jsonb_build_object('domain_event_id',v_event_id,'event_type','contract.closed')
  ) on conflict do nothing;

  perform public.gridex_bump_contract_publication_revision(
    p_company_id,'website','contract_closed',v_aggregate_id
  );
  perform public.gridex_bump_contract_publication_revision(
    p_company_id,'api','contract_closed',v_aggregate_id
  );

  return jsonb_build_object(
    'ok',true,'changed',true,'mode','closed','code','contract_closed',
    'contract_product_id',o.contract_product_id,'offer_id',o.id,
    'legacy_without_product_id',o.contract_product_id is null,
    'affected_channels',v_channels,'affected_publications',v_publications,
    'affected_publication_versions',v_versions,'affected_public_offers',v_public_offers,
    'revoked_unused_quotes',v_quotes,'event_id',v_event_id
  );
end $$;

--
-- Name: FUNCTION gridex_close_contract_product(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_close_contract_product(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid, p_reason text) IS 'Terminal close for active/current versions only. Repeats close readiness under lock; historic superseded, expired and archived versions are preserved.';

--
-- Name: gridex_commit_customer_application_provisioning(uuid, uuid, uuid, uuid, uuid, uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_commit_customer_application_provisioning(p_company_id uuid, p_customer_application_id uuid, p_customer_id uuid, p_customer_site_id uuid, p_metering_point_id uuid, p_contract_id uuid, p_power_of_attorney_id uuid, p_operation_id uuid, p_state text, p_snapshot jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(operation_id uuid, state text, workflow_id uuid, continuation_job_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_application record;
  v_workflow_id uuid;
  v_existing_operation_id uuid;
  v_job_id uuid;
  v_final_state text := coalesce(nullif(btrim(p_state), ''), 'pending_review');
  v_snapshot jsonb := coalesce(p_snapshot, '{}'::jsonb);
begin
  if v_final_state not in ('pending_customer_data','ready_for_switch','pending_review') then
    raise exception 'invalid_workflow_state' using errcode = '22023';
  end if;

  select application.id,
         application.customer_id,
         application.customer_site_id,
         application.metering_point_id,
         application.contract_id
  into v_application
  from public.website_customer_applications application
  where application.id = p_customer_application_id
    and application.company_id = p_company_id
  for update;

  if not found then
    raise exception 'customer_application_not_found' using errcode='P0002';
  end if;

  if v_application.customer_id is not null and v_application.customer_id <> p_customer_id then
    raise exception 'customer_application_customer_mismatch' using errcode='23514';
  end if;

  if p_customer_site_id is not null and not exists (
    select 1
    from public.customer_sites site
    where site.id = p_customer_site_id
      and site.company_id = p_company_id
      and site.customer_id = p_customer_id
  ) then
    raise exception 'customer_site_scope_mismatch' using errcode='23514';
  end if;

  if p_metering_point_id is not null and not exists (
    select 1
    from public.metering_points meter
    where meter.id = p_metering_point_id
      and meter.company_id = p_company_id
      and meter.customer_id = p_customer_id
      and (
        p_customer_site_id is null
        or meter.site_id = p_customer_site_id
        or meter.customer_site_id = p_customer_site_id
      )
  ) then
    raise exception 'metering_point_scope_mismatch' using errcode='23514';
  end if;

  if p_contract_id is not null and not exists (
    select 1
    from public.customer_contracts contract_row
    where contract_row.id = p_contract_id
      and contract_row.company_id = p_company_id
      and contract_row.customer_id = p_customer_id
  ) then
    raise exception 'contract_scope_mismatch' using errcode='23514';
  end if;

  if p_power_of_attorney_id is not null and not exists (
    select 1
    from public.powers_of_attorney poa
    where poa.id = p_power_of_attorney_id
      and poa.company_id = p_company_id
      and poa.customer_id = p_customer_id
      and poa.revoked_at is null
      and (poa.valid_from is null or poa.valid_from <= current_date)
      and (poa.valid_to is null or poa.valid_to >= current_date)
      and poa.status in ('signed','accepted','active','completed')
  ) then
    raise exception 'power_of_attorney_not_active' using errcode='23514';
  end if;

  select workflow_row.id, workflow_row.operation_id
  into v_workflow_id, v_existing_operation_id
  from public.customer_application_workflows workflow_row
  where workflow_row.company_id = p_company_id
    and workflow_row.customer_application_id = p_customer_application_id
  for update;

  if v_workflow_id is null then
    insert into public.customer_application_workflows as workflow_target (
      company_id,customer_application_id,customer_id,customer_site_id,metering_point_id,
      contract_id,operation_id,state,next_action,snapshot,last_transition_at,updated_at
    ) values (
      p_company_id,p_customer_application_id,p_customer_id,p_customer_site_id,p_metering_point_id,
      p_contract_id,p_operation_id,v_final_state,'customer_application_continuation',
      v_snapshot || jsonb_build_object('commit_version','customer_application_continuation_v1'),now(),now()
    )
    returning workflow_target.id, workflow_target.operation_id
    into v_workflow_id, v_existing_operation_id;
  else
    update public.customer_application_workflows as workflow_target
    set customer_id = p_customer_id,
        customer_site_id = p_customer_site_id,
        metering_point_id = p_metering_point_id,
        contract_id = p_contract_id,
        state = v_final_state,
        next_action = 'customer_application_continuation',
        snapshot = coalesce(workflow_target.snapshot,'{}'::jsonb)
          || v_snapshot
          || jsonb_build_object('commit_version','customer_application_continuation_v1'),
        failure_code = null,
        failure_detail_internal = null,
        completed_at = null,
        last_transition_at = now(),
        updated_at = now()
    where workflow_target.id = v_workflow_id;
  end if;

  select job.id
  into v_job_id
  from public.customer_operation_jobs job
  where job.company_id = p_company_id
    and job.workflow_id = v_workflow_id
    and job.job_type = 'customer_application_continuation'
  limit 1
  for update;

  if v_job_id is null then
    insert into public.customer_operation_jobs as job_target (
      company_id,customer_id,customer_site_id,metering_point_id,workflow_id,
      job_type,status,priority,idempotency_key,payload,payload_version,
      operation_id,request_snapshot,run_after,created_by,updated_at
    ) values (
      p_company_id,p_customer_id,p_customer_site_id,p_metering_point_id,v_workflow_id,
      'customer_application_continuation','queued',10,
      format('customer_application_continuation:%s',p_customer_application_id),
      jsonb_build_object(
        'application_id',p_customer_application_id,
        'workflow_id',v_workflow_id,
        'contract_id',p_contract_id,
        'power_of_attorney_id',p_power_of_attorney_id,
        'initial_state',v_final_state,
        'snapshot',v_snapshot
      ),1,v_existing_operation_id,v_snapshot,now(),null,now()
    )
    returning job_target.id into v_job_id;
  else
    update public.customer_operation_jobs as job_target
    set status = case
          when job_target.status in ('failed','blocked','delivery_uncertain') then 'queued'
          else job_target.status
        end,
        run_after = case
          when job_target.status in ('failed','blocked','delivery_uncertain') then now()
          else job_target.run_after
        end,
        locked_at = null,
        locked_by = null,
        lock_token = null,
        last_error = case
          when job_target.status in ('failed','blocked','delivery_uncertain') then null
          else job_target.last_error
        end,
        last_error_code = case
          when job_target.status in ('failed','blocked','delivery_uncertain') then null
          else job_target.last_error_code
        end,
        last_error_message = case
          when job_target.status in ('failed','blocked','delivery_uncertain') then null
          else job_target.last_error_message
        end,
        payload = coalesce(job_target.payload,'{}'::jsonb) || jsonb_build_object(
          'application_id',p_customer_application_id,
          'workflow_id',v_workflow_id,
          'contract_id',p_contract_id,
          'power_of_attorney_id',p_power_of_attorney_id,
          'initial_state',v_final_state,
          'snapshot',v_snapshot
        ),
        updated_at = now()
    where job_target.id = v_job_id;
  end if;

  update public.customer_application_workflows as workflow_target
  set last_job_id = v_job_id,
      updated_at = now()
  where workflow_target.id = v_workflow_id;

  insert into public.customer_application_workflow_events(
    company_id,workflow_id,customer_application_id,operation_id,from_state,to_state,
    event_code,metadata,idempotency_key
  ) values (
    p_company_id,v_workflow_id,p_customer_application_id,v_existing_operation_id,null,v_final_state,
    'workflow.committed',
    jsonb_build_object(
      'continuation_job_id',v_job_id,
      'power_of_attorney_id',p_power_of_attorney_id
    ),
    format('workflow.committed:%s',p_customer_application_id)
  ) on conflict (company_id,idempotency_key) do nothing;

  perform public.gridex_record_application_provisioning_step(
    p_company_id,p_customer_application_id,v_existing_operation_id,
    'workflow_committed','completed',
    jsonb_build_object(
      'workflow_id',v_workflow_id,
      'customer_id',p_customer_id,
      'customer_site_id',p_customer_site_id,
      'metering_point_id',p_metering_point_id,
      'contract_id',p_contract_id,
      'power_of_attorney_id',p_power_of_attorney_id,
      'state',v_final_state,
      'continuation_job_id',v_job_id
    )
  );

  perform public.gridex_record_application_provisioning_step(
    p_company_id,p_customer_application_id,v_existing_operation_id,
    'external_automation_queued','completed',
    jsonb_build_object(
      'workflow_id',v_workflow_id,
      'continuation_job_id',v_job_id,
      'job_type','customer_application_continuation'
    )
  );

  return query
  select v_existing_operation_id, v_final_state, v_workflow_id, v_job_id;
end;
$$;

--
-- Name: gridex_commit_customer_site_address(uuid, uuid, uuid, text, text, text, text, text, text, text, text, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_commit_customer_site_address(p_company_id uuid, p_customer_id uuid, p_site_id uuid, p_street text, p_postal_code text, p_city text, p_country text, p_care_of text, p_apartment_number text, p_address_normalized text, p_address_hash text, p_source text, p_source_reference text, p_metadata jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_previous_hash text;
  v_address_id uuid;
  v_now timestamptz := now();
  v_address_changed boolean;
begin
  select address_hash into v_previous_hash
    from public.customer_sites
   where id = p_site_id and company_id = p_company_id and customer_id = p_customer_id
   for update;
  if not found then raise exception 'customer_site_not_found' using errcode = 'P0002'; end if;
  if nullif(btrim(p_address_hash), '') is null then raise exception 'address_hash_required' using errcode = '22023'; end if;

  -- NULL -> canonical hash is the first canonicalization of the address already
  -- present on the site. It is not a later customer address change and must not
  -- stale jobs, requests, grid context or metering context.
  v_address_changed := v_previous_hash is not null and v_previous_hash is distinct from p_address_hash;

  if v_address_changed then
    update public.customer_operation_jobs
       set status = 'needs_review', stale_reason = 'site_address_changed_after_operation_started',
           last_error = 'Anläggningsadressen ändrades. Nätägar- och routinguppgifter har ogiltigförklarats.',
           completed_at = v_now, locked_at = null, locked_by = null, lock_token = null, updated_at = v_now
     where company_id = p_company_id and customer_site_id = p_site_id
       and status in ('queued','running','waiting_response');

    update public.customer_info_requests
       set status = 'manual_review_required', blocker_reason = 'Anläggningsadressen ändrades. Skapa en ny nätägarresolution och begäran.', updated_at = v_now
     where company_id = p_company_id and customer_id = p_customer_id and site_id = p_site_id
       and status in ('draft','ready_to_send','z01_prepared','waiting_for_z02','waiting_for_aperak','waiting_for_contrl');

    update public.grid_owner_information_requests
       set status = 'needs_review',
           last_error_code = 'site_address_changed',
           last_error_message = 'Begäran gäller en tidigare adress och får inte återanvändas.',
           metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object('stale',true,'stale_at',v_now,'stale_reason','site_address_changed'),
           updated_at = v_now
     where company_id = p_company_id and customer_id = p_customer_id and customer_site_id = p_site_id
       and status in ('draft','ready_to_send','sent','waiting_response','blocked_missing_poa','blocked_missing_grid_owner_contact',
                      'blocked_missing_manual_mailbox','ready_to_send_manual_email','manual_email_queued','manual_email_sent','waiting_manual_response');

    update public.manual_email_outbox o
       set status = case when o.status in ('queued','sending') then 'failed' else o.status end,
           last_error = case when o.status in ('queued','sending') then 'Begäran ogiltigförklarades eftersom anläggningsadressen ändrades.' else o.last_error end,
           updated_at = v_now
      from public.grid_owner_information_requests r
     where o.request_id = r.id and r.company_id = p_company_id and r.customer_site_id = p_site_id
       and o.status in ('queued','sending');
  end if;

  update public.customer_sites
     set street = p_street, postal_code = p_postal_code, city = p_city, country = p_country,
         care_of = p_care_of, apartment_number = p_apartment_number,
         address_normalized = p_address_normalized, address_hash = p_address_hash,
         address_source = p_source, address_source_reference = p_source_reference,
         address_received_at = v_now,
         address_verified_at = case when p_source = 'grid_owner_response' then v_now else null end,
         address_verification_method = case when p_source = 'grid_owner_response' then 'grid_owner_response' else null end,
         address_confidence = case when p_source = 'grid_owner_response' then 1 else null end,
         address_status = case when p_source = 'grid_owner_response' then 'verified' else 'candidate' end,
         address_quality_status = 'complete', address_quality_warnings = '[]'::jsonb,
         -- Canonical grid context is always derived by the resolver or a verified
         -- grid-owner response. Claimed values remain evidence in metadata only.
         grid_owner_id = case when v_address_changed then null else grid_owner_id end,
         selected_grid_owner_id = case when v_address_changed then null else selected_grid_owner_id end,
         grid_area_code = case when v_address_changed then null else grid_area_code end,
         price_area_code = case when v_address_changed then null else price_area_code end,
         bidding_zone_code = case when v_address_changed then null else bidding_zone_code end,
         resolution_id = case when v_address_changed then null else resolution_id end,
         resolution_status = case when v_address_changed then 'pending_resolution' else resolution_status end,
         resolution_confidence = case when v_address_changed then null else resolution_confidence end,
         facility_data_status = case when p_source = 'grid_owner_response' then 'verified' when v_address_changed then 'unverified' else facility_data_status end,
         metadata = coalesce(metadata,'{}'::jsonb) || coalesce(p_metadata,'{}'::jsonb), updated_at = v_now
   where id = p_site_id and company_id = p_company_id and customer_id = p_customer_id;

  if v_address_changed then
    update public.metering_points
       set grid_owner_id = null, grid_area_code = null, price_area_code = null,
           verification_status = 'pending_verification', updated_at = v_now
     where company_id = p_company_id and (site_id = p_site_id or customer_site_id = p_site_id) and status <> 'closed';
  end if;

  select id into v_address_id from public.customer_addresses
   where company_id = p_company_id and customer_id = p_customer_id and type = 'facility'
     and metadata @> jsonb_build_object('customer_site_id', p_site_id)
   order by updated_at desc nulls last limit 1 for update;
  if v_address_id is null then
    insert into public.customer_addresses(company_id,customer_id,type,street_1,street_2,postal_code,city,country,is_active,metadata,created_at,updated_at)
    values(p_company_id,p_customer_id,'facility',p_street,p_care_of,p_postal_code,p_city,p_country,true,
      jsonb_build_object('customer_site_id',p_site_id,'address_hash',p_address_hash,'source',p_source),v_now,v_now);
  else
    update public.customer_addresses set street_1=p_street,street_2=p_care_of,postal_code=p_postal_code,city=p_city,country=p_country,
      is_active=true,metadata=jsonb_build_object('customer_site_id',p_site_id,'address_hash',p_address_hash,'source',p_source),updated_at=v_now
    where id=v_address_id;
  end if;

  insert into public.customer_site_address_history(company_id,customer_id,customer_site_id,address_hash,source,source_reference,actor_user_id,snapshot)
  values(p_company_id,p_customer_id,p_site_id,p_address_hash,p_source,p_source_reference,p_actor_user_id,
    jsonb_build_object('street',p_street,'postal_code',p_postal_code,'city',p_city,'country',p_country,'care_of',p_care_of,
      'apartment_number',p_apartment_number,'address_hash',p_address_hash,'source',p_source,'source_reference',p_source_reference,
      'claimed_grid_owner_id',p_metadata->>'claimed_grid_owner_id','claimed_grid_area_code',p_metadata->>'claimed_grid_area_code',
      'claimed_price_area_code',p_metadata->>'claimed_price_area_code','derived_context_invalidated',v_address_changed));
end;
$$;

--
-- Name: gridex_commit_website_portal_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_commit_website_portal_identity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $_$
declare
  v_auth_user_id_text text :=
    nullif(btrim(coalesce(new.payload->>'auth_user_id', '')), '');
  v_portal_user_id_text text :=
    nullif(btrim(coalesce(new.payload->>'customer_portal_user_id', '')), '');
  v_auth_user_id uuid;
  v_identity_id uuid;
  v_email text :=
    nullif(lower(btrim(coalesce(new.payload#>>'{customer,email}', ''))), '');
begin
  if new.customer_id is null then
    return new;
  end if;

  if (v_auth_user_id_text is null) <> (v_portal_user_id_text is null) then
    raise exception using
      errcode = '23514',
      message = 'website_portal_identity_pair_required';
  end if;
  if v_auth_user_id_text is null then
    return new;
  end if;
  if v_auth_user_id_text is distinct from v_portal_user_id_text
     or v_auth_user_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception using
      errcode = '23514',
      message = 'website_portal_identity_mismatch';
  end if;

  v_auth_user_id := v_auth_user_id_text::uuid;

  insert into public.customer_portal_identities(
    company_id,
    customer_id,
    api_client_id,
    provider,
    external_customer_id,
    external_account_id,
    customer_number,
    auth_user_id,
    customer_portal_user_id,
    email,
    status,
    match_strength,
    match_method,
    linked_at,
    last_resolved_at,
    metadata,
    updated_at
  ) values (
    new.company_id,
    new.customer_id,
    new.api_client_id,
    'gridex_website',
    new.external_customer_id,
    v_auth_user_id_text,
    new.customer_number,
    v_auth_user_id,
    v_auth_user_id,
    v_email,
    'active',
    'strong',
    'atomic_website_application_auth',
    now(),
    now(),
    jsonb_build_object(
      'source', 'website_customer_application',
      'application_id', new.id,
      'atomic_commit', true
    ),
    now()
  )
  on conflict (company_id, provider, external_customer_id)
  do update set
    customer_id = excluded.customer_id,
    api_client_id = excluded.api_client_id,
    external_account_id = excluded.external_account_id,
    customer_number = excluded.customer_number,
    auth_user_id = excluded.auth_user_id,
    customer_portal_user_id = excluded.customer_portal_user_id,
    email = excluded.email,
    status = 'active',
    match_strength = 'strong',
    match_method = 'atomic_website_application_auth',
    linked_at = coalesce(customer_portal_identities.linked_at, now()),
    last_resolved_at = now(),
    metadata = coalesce(customer_portal_identities.metadata, '{}'::jsonb) ||
      excluded.metadata,
    updated_at = now()
  where customer_portal_identities.customer_id is null
     or customer_portal_identities.customer_id = excluded.customer_id
  returning id into v_identity_id;

  if v_identity_id is null then
    raise exception using
      errcode = '23505',
      message = 'website_portal_identity_customer_conflict';
  end if;

  insert into public.customer_portal_accounts(
    company_id,
    customer_id,
    portal_user_id,
    external_account_id,
    customer_number,
    external_customer_id,
    role,
    email,
    user_email,
    status,
    is_active,
    activated_at,
    verified_at,
    match_method,
    verified_identity_snapshot,
    metadata
  ) values (
    new.company_id,
    new.customer_id,
    v_auth_user_id,
    v_auth_user_id_text,
    new.customer_number,
    new.external_customer_id,
    'owner',
    v_email,
    v_email,
    'active',
    true,
    now(),
    now(),
    'atomic_website_application_auth',
    jsonb_build_object(
      'auth_user_id', v_auth_user_id,
      'customer_portal_user_id', v_auth_user_id,
      'portal_identity_id', v_identity_id
    ),
    jsonb_build_object(
      'source', 'website_customer_application',
      'application_id', new.id,
      'atomic_commit', true
    )
  )
  on conflict do nothing;

  if not exists (
    select 1
    from public.customer_portal_accounts account
    where account.company_id = new.company_id
      and account.portal_user_id = v_auth_user_id
      and account.customer_id = new.customer_id
      and account.is_active = true
  ) then
    raise exception using
      errcode = '23505',
      message = 'website_portal_account_customer_conflict';
  end if;

  return new;
end
$_$;

--
-- Name: FUNCTION gridex_commit_website_portal_identity(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_commit_website_portal_identity() IS 'Fails the canonical website onboarding transaction unless the paired auth subject, portal identity and owner portal account commit for the same tenant/customer.';

--
-- Name: gridex_company_go_live_readiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_company_go_live_readiness(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare
  c public.companies%rowtype;
  blockers text[] := array[]::text[];
  prodat_total integer := 6;
  utilts_total integer := 5;
  prodat_passed integer := 0;
  utilts_passed integer := 0;
  v_prod_actor_count integer := 0;
  v_test_actor_count integer := 0;
  v_prod_actor_id uuid;
  v_test_actor_id uuid;
  v_has_prod_route boolean := false;
  v_has_test_route boolean := false;
  v_has_brp boolean := false;
  v_has_prod_mailbox boolean := false;
  v_prod_receiver_source text;
  v_prod_dynamic_strategy text;
  v_prod_receiver_ediel_id text;
  v_prod_mailbox_id uuid;
  v_prod_application_reference text;
  v_prod_certificate_required boolean;
  v_prod_certificate_id uuid;
  v_prod_receiver_certificate_id uuid;
  v_dynamic_receiver boolean := false;
  v_evidence jsonb := '{}'::jsonb;
  v_evidence_ready boolean := false;
begin
  select * into c
  from public.companies
  where id = p_company_id;

  if not found then
    return jsonb_build_object(
      'company_id', p_company_id,
      'status', 'missing_company',
      'blockers', jsonb_build_array('Bolaget hittades inte')
    );
  end if;

  select count(*)
  into v_prod_actor_count
  from public.ediel_actor_settings eas
  where eas.company_id = p_company_id
    and eas.environment = 'production'
    and coalesce(eas.is_active, false) = true
    and lower(coalesce(eas.actor_role, eas.role, '')) in ('supplier', 'electricity_supplier');

  if v_prod_actor_count = 1 then
    select eas.id
    into v_prod_actor_id
    from public.ediel_actor_settings eas
    where eas.company_id = p_company_id
      and eas.environment = 'production'
      and coalesce(eas.is_active, false) = true
      and lower(coalesce(eas.actor_role, eas.role, '')) in ('supplier', 'electricity_supplier')
    order by eas.updated_at desc, eas.id
    limit 1;
  elsif v_prod_actor_count = 0 then
    blockers := array_append(blockers, 'Aktiv supplier-produktionsaktörsprofil saknas');
  else
    blockers := array_append(blockers, 'Flera aktiva supplier-produktionsaktörsprofiler finns');
  end if;

  select count(*)
  into v_test_actor_count
  from public.ediel_actor_settings eas
  where eas.company_id = p_company_id
    and eas.environment = 'test'
    and coalesce(eas.is_active, false) = true
    and lower(coalesce(eas.actor_role, eas.role, '')) in ('supplier', 'electricity_supplier');

  if v_test_actor_count = 1 then
    select eas.id
    into v_test_actor_id
    from public.ediel_actor_settings eas
    where eas.company_id = p_company_id
      and eas.environment = 'test'
      and coalesce(eas.is_active, false) = true
      and lower(coalesce(eas.actor_role, eas.role, '')) in ('supplier', 'electricity_supplier')
    order by eas.updated_at desc, eas.id
    limit 1;
  elsif v_test_actor_count = 0 then
    blockers := array_append(blockers, 'Aktiv supplier-testaktörsprofil saknas');
  else
    blockers := array_append(blockers, 'Flera aktiva supplier-testaktörsprofiler finns');
  end if;

  if v_prod_actor_id is not null then
    select exists(
      select 1
      from public.ediel_route_profiles erp
      where erp.company_id = p_company_id
        and erp.environment = 'production'
        and erp.actor_setting_id = v_prod_actor_id
        and coalesce(erp.is_enabled, false) = true
        and coalesce(erp.is_active, true) = true
        and upper(coalesce(erp.message_family, '')) = 'PRODAT'
    ) into v_has_prod_route;

    select
      erp.receiver_source,
      erp.dynamic_receiver_strategy,
      erp.receiver_ediel_id,
      erp.mailbox_id,
      erp.application_reference,
      coalesce(erp.certificate_required, false),
      erp.certificate_id,
      erp.receiver_certificate_id
    into
      v_prod_receiver_source,
      v_prod_dynamic_strategy,
      v_prod_receiver_ediel_id,
      v_prod_mailbox_id,
      v_prod_application_reference,
      v_prod_certificate_required,
      v_prod_certificate_id,
      v_prod_receiver_certificate_id
    from public.ediel_route_profiles erp
    where erp.company_id = p_company_id
      and erp.environment = 'production'
      and erp.actor_setting_id = v_prod_actor_id
      and coalesce(erp.is_enabled, false) = true
      and coalesce(erp.is_active, true) = true
      and upper(coalesce(erp.message_family, '')) = 'PRODAT'
    order by coalesce(erp.is_production_route, false) desc, erp.updated_at desc, erp.id
    limit 1;
  end if;

  if v_test_actor_id is not null then
    select exists(
      select 1
      from public.ediel_route_profiles erp
      where erp.company_id = p_company_id
        and erp.environment = 'test'
        and erp.actor_setting_id = v_test_actor_id
        and coalesce(erp.is_enabled, false) = true
        and coalesce(erp.is_active, true) = true
    ) into v_has_test_route;
  end if;

  v_dynamic_receiver :=
    lower(coalesce(v_prod_receiver_source, '')) in (
      'selected_metering_point_grid_owner',
      'selected_customer_site_grid_owner',
      'selected_supplier_switch_grid_owner',
      'selected_data_request_grid_owner',
      'original_inbound_sender',
      'original_inbound_receiver'
    )
    or (
      nullif(btrim(coalesce(v_prod_dynamic_strategy, '')), '') is not null
      and lower(v_prod_dynamic_strategy) <> 'resolve_from_counterparty_id'
    );

  select exists(
    select 1
    from public.ediel_brp_settings b
    where b.company_id = p_company_id
      and b.environment = 'production'
      and coalesce(b.is_active, true) = true
      and nullif(btrim(coalesce(b.brp_ediel_id, '')), '') is not null
  ) into v_has_brp;

  if v_prod_mailbox_id is not null then
    select exists(
      select 1
      from public.ediel_mailboxes m
      where m.id = v_prod_mailbox_id
        and m.environment = 'production'
        and coalesce(m.is_active, false) = true
        and (m.company_id = p_company_id or m.company_id is null)
    ) into v_has_prod_mailbox;
  end if;
  v_has_prod_mailbox := v_has_prod_mailbox
    or nullif(btrim(coalesce(c.production_mailbox, '')), '') is not null;

  begin
    v_evidence := public.canonical_ediel_production_evidence_readiness(p_company_id);
    v_evidence_ready := coalesce((v_evidence ->> 'ready')::boolean, false);
  exception when others then
    v_evidence := jsonb_build_object('ready', false, 'error', sqlerrm);
    v_evidence_ready := false;
  end;

  if v_evidence_ready then
    prodat_passed := prodat_total;
    utilts_passed := utilts_total;
  elsif to_regclass('public.actor_test_results') is not null then
    select
      count(*) filter (
        where package_key = 'PRODAT_SUPPLIER'
          and status in ('passed', 'manual_verified')
          and coalesce(is_stale, false) = false
      ),
      count(*) filter (
        where package_key = 'UTILTS_METERING'
          and status in ('passed', 'manual_verified')
          and coalesce(is_stale, false) = false
      )
    into prodat_passed, utilts_passed
    from public.actor_test_results
    where company_id = p_company_id;
  end if;

  if nullif(btrim(coalesce(c.org_number, '')), '') is null then
    blockers := array_append(blockers, 'Orgnummer saknas');
  end if;
  if nullif(btrim(coalesce(c.production_ediel_id, c.ediel_id, '')), '') is null then
    blockers := array_append(blockers, 'Produktions Ediel-id saknas');
  end if;
  if not v_has_brp then
    blockers := array_append(blockers, 'Aktiv production-BRP saknas');
  end if;
  if lower(coalesce(c.esett_status, 'missing')) <> 'ready' then
    blockers := array_append(blockers, 'eSett-status är inte klar');
  end if;
  if not v_has_prod_route then
    blockers := array_append(blockers, 'Supplier-bunden PRODAT-produktionsroute saknas');
  end if;
  if not v_has_test_route then
    blockers := array_append(blockers, 'Supplier-bunden test-route saknas');
  end if;
  if not v_has_prod_mailbox then
    blockers := array_append(blockers, 'Produktionsmailbox/transport saknas');
  end if;
  if v_has_prod_route and nullif(btrim(coalesce(v_prod_application_reference, c.production_application_reference, '')), '') is null then
    blockers := array_append(blockers, 'Produktions Application Reference saknas');
  end if;
  if v_has_prod_route and not v_dynamic_receiver and nullif(btrim(coalesce(v_prod_receiver_ediel_id, '')), '') is null then
    blockers := array_append(blockers, 'Fast produktionsmotpart saknas och dynamisk receiver är inte konfigurerad');
  end if;
  if v_has_prod_route
     and coalesce(v_prod_certificate_required, false)
     and not v_dynamic_receiver
     and v_prod_certificate_id is null
     and v_prod_receiver_certificate_id is null then
    blockers := array_append(blockers, 'Mottagarcertifikat saknas för fast PRODAT-produktionsroute');
  end if;

  if not v_evidence_ready then
    blockers := array_append(
      blockers,
      format(
        'Canonical Ediel-evidens är inte komplett (PRODAT %s/%s, UTILTS %s/%s)',
        prodat_passed, prodat_total, utilts_passed, utilts_total
      )
    );
  end if;

  return jsonb_build_object(
    'company_id', p_company_id,
    'status', case when cardinality(blockers) = 0 then 'ready' else 'blocked' end,
    'blockers', to_jsonb(blockers),
    'prodat_passed', prodat_passed,
    'prodat_total', prodat_total,
    'utilts_passed', utilts_passed,
    'utilts_total', utilts_total,
    'has_production_actor', v_prod_actor_count = 1,
    'has_test_actor', v_test_actor_count = 1,
    'has_production_route', v_has_prod_route,
    'has_test_route', v_has_test_route,
    'has_production_mailbox', v_has_prod_mailbox,
    'dynamic_receiver_capable', v_dynamic_receiver,
    'evidence_ready', v_evidence_ready,
    'evidence', v_evidence,
    'source', 'canonical_runtime_v2'
  );
end;
$$;

--
-- Name: gridex_company_legal_contract_runtime_health(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_company_legal_contract_runtime_health() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_missing_crypto text[];
  v_trigger_count integer;
  v_rendered text;
begin
  select array_agg(p.oid::regprocedure::text order by p.oid::regprocedure::text)
  into v_missing_crypto
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and p.prokind = 'f'
    and pg_get_functiondef(p.oid) ~* '\m(digest|hmac|gen_random_bytes|crypt|gen_salt)\s*\('
    and coalesce(array_to_string(p.proconfig, ','), '') !~* 'search_path=.*extensions';

  select count(*) into v_trigger_count
  from pg_trigger t
  join pg_class c on c.oid = t.tgrelid
  join pg_namespace n on n.oid = c.relnamespace
  join pg_proc p on p.oid = t.tgfoid
  where n.nspname = 'public'
    and c.relname = 'companies'
    and not t.tgisinternal
    and (t.tgname ilike '%legal_profile%' or p.proname ilike '%legal_profile%sync%');

  v_rendered := public.gridex_render_legal_document(
    '{{billing_information}} {{dispute_resolution_information}}',
    jsonb_build_object(
      'billing_information', jsonb_build_object('email', 'health@example.se'),
      'dispute_resolution_information', jsonb_build_object('authority', 'ARN', 'url', 'https://www.arn.se/')
    ),
    '{}'::jsonb
  );

  return jsonb_build_object(
    'ok', coalesce(array_length(v_missing_crypto, 1), 0) = 0
      and v_trigger_count = 1
      and v_rendered !~ '\{"(email|authority|source)"'
      and v_rendered not like '%{{%',
    'pgcrypto_search_path_ready', coalesce(array_length(v_missing_crypto, 1), 0) = 0,
    'functions_missing_extensions', coalesce(to_jsonb(v_missing_crypto), '[]'::jsonb),
    'company_legal_profile_sync_trigger_count', v_trigger_count,
    'legal_renderer_readable', v_rendered !~ '\{"(email|authority|source)"' and v_rendered not like '%{{%'
  );
end
$$;

--
-- Name: FUNCTION gridex_company_legal_contract_runtime_health(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_company_legal_contract_runtime_health() IS 'Live preflight for canonical company/legal runtime, pgcrypto search_path, trigger count and readable rendering.';

--
-- Name: gridex_company_legal_profile_defaults(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_company_legal_profile_defaults(p_company jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  j jsonb := coalesce(p_company, '{}'::jsonb);
  v_postal jsonb;
  v_complaints_address jsonb;
  v_privacy_address jsonb;
  v_billing_address jsonb;
  v_legal_name text;
  v_legal_name_source text;
  v_service_email text;
  v_service_phone text;
  v_complaints_email text;
  v_complaints_phone text;
  v_privacy_email text;
  v_privacy_phone text;
  v_billing_email text;
  v_billing_phone text;
  v_dispute_default jsonb;
  v_dispute jsonb;
  v_snapshot jsonb;
  v_complaints_explicit boolean;
  v_privacy_explicit boolean;
  v_billing_explicit boolean;
begin
  v_legal_name := coalesce(nullif(btrim(j->>'legal_name'), ''), nullif(btrim(j->>'name'), ''));
  v_legal_name_source := case when nullif(btrim(j->>'legal_name'), '') is not null then 'tenant_explicit' else 'legacy_fallback' end;

  v_postal := public.gridex_build_canonical_address(
    coalesce(nullif(j->>'address_line_1', ''), nullif(j->>'address', '')),
    nullif(j->>'address_line_2', ''), j->>'postal_code', j->>'city', coalesce(j->>'country_code', 'SE')
  );
  v_complaints_address := public.gridex_build_canonical_address(
    j->>'complaints_address_line_1', j->>'complaints_address_line_2', j->>'complaints_postal_code', j->>'complaints_city', coalesce(j->>'complaints_country_code', j->>'country_code', 'SE')
  );
  if v_complaints_address = '{}'::jsonb then v_complaints_address := v_postal; end if;
  v_privacy_address := public.gridex_build_canonical_address(
    j->>'data_protection_address_line_1', j->>'data_protection_address_line_2', j->>'data_protection_postal_code', j->>'data_protection_city', coalesce(j->>'data_protection_country_code', j->>'country_code', 'SE')
  );
  if v_privacy_address = '{}'::jsonb then v_privacy_address := v_postal; end if;
  v_billing_address := public.gridex_build_canonical_address(
    j->>'billing_address_line_1', j->>'billing_address_line_2', j->>'billing_postal_code', j->>'billing_city', coalesce(j->>'billing_country_code', j->>'country_code', 'SE')
  );
  if v_billing_address = '{}'::jsonb then v_billing_address := v_postal; end if;

  v_service_email := lower(coalesce(nullif(j->>'support_email', ''), nullif(j->>'primary_contact_email', ''), nullif(j->>'email', '')));
  v_service_phone := coalesce(nullif(j->>'phone', ''), nullif(j->>'primary_contact_phone', ''));
  v_complaints_email := lower(coalesce(nullif(j->>'complaints_email', ''), v_service_email));
  v_complaints_phone := coalesce(nullif(j->>'complaints_phone', ''), v_service_phone);
  v_privacy_email := lower(coalesce(nullif(j->>'data_protection_email', ''), v_service_email));
  v_privacy_phone := coalesce(nullif(j->>'data_protection_phone', ''), v_service_phone);
  v_billing_email := lower(coalesce(nullif(j->>'billing_contact_email', ''), v_service_email));
  v_billing_phone := coalesce(nullif(j->>'billing_contact_phone', ''), v_service_phone);

  v_complaints_explicit := nullif(j->>'complaints_email', '') is not null or nullif(j->>'complaints_phone', '') is not null or nullif(j->>'complaints_address_line_1', '') is not null;
  v_privacy_explicit := nullif(j->>'data_protection_email', '') is not null or nullif(j->>'data_protection_phone', '') is not null or nullif(j->>'data_protection_address_line_1', '') is not null;
  v_billing_explicit := nullif(j->>'billing_contact_email', '') is not null or nullif(j->>'billing_contact_phone', '') is not null or nullif(j->>'billing_address_line_1', '') is not null;

  v_dispute_default := jsonb_build_object(
    'authority', 'Allmänna reklamationsnämnden för behöriga konsumenttvister',
    'address', 'Box 174, 101 23 Stockholm',
    'url', 'https://www.arn.se/',
    'description', 'Klagomål lämnas först till bolagets klagomålskontakt. Privatkund kan, när ARN:s regler är uppfyllda, vända sig till Allmänna reklamationsnämnden. Tvist avgörs i övrigt enligt svensk rätt och behörig svensk domstol om inget annat avtalats för företagskund.',
    'source', 'platform_default'
  );
  v_dispute := case
    when coalesce(j->'dispute_resolution_override', '{}'::jsonb) in ('{}'::jsonb, 'null'::jsonb) then v_dispute_default
    else v_dispute_default || (j->'dispute_resolution_override') || jsonb_build_object('source', 'tenant_explicit')
  end;

  v_snapshot := jsonb_strip_nulls(jsonb_build_object(
    'legal_name', v_legal_name,
    'legal_name_source', v_legal_name_source,
    'trade_name', j->>'name',
    'organization_number', j->>'org_number',
    'vat_number', j->>'vat_number',
    'website', j->>'website',
    'postal_address', v_postal,
    'customer_service', jsonb_build_object(
      'name', j->>'primary_contact_name', 'email', v_service_email, 'phone', v_service_phone,
      'hours', j->>'customer_service_hours', 'address', v_postal
    ),
    'complaints', jsonb_build_object(
      'name', j->>'complaints_contact_name', 'email', v_complaints_email, 'phone', v_complaints_phone,
      'address', v_complaints_address, 'description', j->>'complaints_description',
      'source', case when v_complaints_explicit then 'tenant_explicit' else 'company_fallback' end
    ),
    'data_protection', jsonb_build_object(
      'name', j->>'data_protection_contact_name', 'email', v_privacy_email, 'phone', v_privacy_phone,
      'address', v_privacy_address,
      'source', case when v_privacy_explicit then 'tenant_explicit' else 'company_fallback' end
    ),
    'billing', jsonb_build_object(
      'email', v_billing_email, 'phone', v_billing_phone, 'address', v_billing_address,
      'terms_summary', j->>'billing_terms_summary',
      'source', case when v_billing_explicit then 'tenant_explicit' else 'company_fallback' end
    ),
    'dispute_resolution', v_dispute
  ));

  return jsonb_build_object(
    'legal_name', v_legal_name,
    'legal_name_source', v_legal_name_source,
    'organization_number', nullif(j->>'org_number', ''),
    'postal_address', v_postal,
    'customer_service_address', v_postal,
    'customer_service_email', v_service_email,
    'phone', v_service_phone,
    'website', nullif(j->>'website', ''),
    'customer_service_contact', jsonb_strip_nulls(jsonb_build_object(
      'name', coalesce(nullif(j->>'primary_contact_name', ''), 'Kundservice'),
      'email', v_service_email, 'phone', v_service_phone, 'address', v_postal,
      'hours', nullif(j->>'customer_service_hours', ''), 'source', 'company_fallback'
    )),
    'complaints_contact', jsonb_strip_nulls(jsonb_build_object(
      'name', coalesce(nullif(j->>'complaints_contact_name', ''), 'Klagomålsansvarig'),
      'email', v_complaints_email, 'phone', v_complaints_phone, 'address', v_complaints_address,
      'description', nullif(j->>'complaints_description', ''),
      'source', case when v_complaints_explicit then 'tenant_explicit' else 'company_fallback' end
    )),
    'data_protection_contact', jsonb_strip_nulls(jsonb_build_object(
      'name', coalesce(nullif(j->>'data_protection_contact_name', ''), 'Dataskyddsansvarig'),
      'email', v_privacy_email, 'phone', v_privacy_phone, 'address', v_privacy_address,
      'description', 'Dataskyddsfrågor och rättighetsbegäran hanteras via angiven kontaktkanal.',
      'source', case when v_privacy_explicit then 'tenant_explicit' else 'company_fallback' end
    )),
    'billing_information', jsonb_strip_nulls(jsonb_build_object(
      'contact', jsonb_strip_nulls(jsonb_build_object(
        'name', 'Fakturering', 'email', v_billing_email, 'phone', v_billing_phone,
        'address', v_billing_address,
        'source', case when v_billing_explicit then 'tenant_explicit' else 'company_fallback' end
      )),
      'email', v_billing_email, 'phone', v_billing_phone, 'address', v_billing_address,
      'terms_summary', coalesce(nullif(j->>'billing_terms_summary', ''), 'Fakturering sker enligt avtalad period och den låsta prisversionen. Preliminära mätvärden får rättas när validerade värden erhålls.'),
      'source', case when v_billing_explicit then 'tenant_explicit' else 'company_fallback' end
    )),
    'dispute_resolution_information', v_dispute,
    'source_company_snapshot', v_snapshot,
    'source_company_snapshot_sha256', encode(extensions.digest(convert_to(v_snapshot::text, 'UTF8'), 'sha256'::text), 'hex')
  );
end
$$;

--
-- Name: FUNCTION gridex_company_legal_profile_defaults(p_company jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_company_legal_profile_defaults(p_company jsonb) IS 'Deterministic canonical projection from companies. Hash includes every legal field and excludes unrelated updated_at timestamps.';

--
-- Name: gridex_complete_facility_response(uuid, uuid, uuid, text, uuid, text, text, text, text, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_complete_facility_response(p_company_id uuid, p_request_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_source text DEFAULT 'system'::text, p_ediel_message_id uuid DEFAULT NULL::uuid, p_facility_id text DEFAULT NULL::text, p_metering_point_external_id text DEFAULT NULL::text, p_grid_area_code text DEFAULT NULL::text, p_price_area_code text DEFAULT NULL::text, p_source_party_grid_owner_id uuid DEFAULT NULL::uuid, p_raw_payload jsonb DEFAULT '{}'::jsonb, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_request public.grid_owner_information_requests%rowtype;
  v_site public.customer_sites%rowtype;
  v_meter public.metering_points%rowtype;
  v_conflict public.metering_points%rowtype;
  v_previous_resolution public.customer_site_resolution%rowtype;
  v_facility_id text;
  v_meter_external text;
  v_grid_area text;
  v_grid_area_name text;
  v_grid_owner_name text;
  v_master_ops_grid_owner_id uuid;
  v_master_price_area text;
  v_price_area text;
  v_resolution_id uuid;
  v_now timestamptz := now();
  v_received jsonb;
begin
  select * into v_request
  from public.grid_owner_information_requests
  where id = p_request_id and company_id = p_company_id
  for update;

  if not found then raise exception using errcode = 'P0002', message = 'facility_request_not_found'; end if;
  if v_request.customer_id is null or v_request.customer_site_id is null then raise exception using errcode = '23514', message = 'request_site_customer_missing'; end if;

  select * into v_site
  from public.customer_sites
  where id = v_request.customer_site_id and company_id = p_company_id and customer_id = v_request.customer_id
  for update;
  if not found then raise exception using errcode = '23514', message = 'request_site_customer_mismatch'; end if;

  if v_request.grid_owner_id is null or v_site.grid_owner_id is null or v_request.grid_owner_id is distinct from v_site.grid_owner_id then
    raise exception using errcode = '23514', message = 'facility_request_requires_bound_canonical_site_owner';
  end if;

  if p_source_party_grid_owner_id is not null and v_request.grid_owner_id is distinct from p_source_party_grid_owner_id then
    insert into public.facility_data_quality_issues(company_id,customer_id,customer_site_id,grid_owner_id,issue_type,severity,source,recommended_action,retry_allowed,metadata)
    values (p_company_id,v_request.customer_id,v_request.customer_site_id,v_request.grid_owner_id,'grid_owner_conflict','critical',p_source,'Verify the sender/grid owner before applying the response.',false,jsonb_build_object('request_id',p_request_id,'expected_grid_owner_id',v_request.grid_owner_id,'incoming_grid_owner_id',p_source_party_grid_owner_id));
    return jsonb_build_object('ok',false,'code','grid_owner_conflict','requestId',p_request_id,'customerId',v_request.customer_id,'customerSiteId',v_request.customer_site_id);
  end if;

  if v_request.status = 'completed' then
    select * into v_meter from public.metering_points where company_id=p_company_id and customer_id=v_request.customer_id and site_id=v_request.customer_site_id order by updated_at desc nulls last,created_at desc limit 1;
    return jsonb_build_object('ok',true,'alreadyCompleted',true,'requestId',p_request_id,'customerId',v_request.customer_id,'customerSiteId',v_request.customer_site_id,'meteringPointRecordId',v_meter.id,'operationId',v_request.operation_id);
  end if;

  if v_request.status not in ('draft','ready_to_send','sent','waiting_response','received','needs_review','manual_email_sent','waiting_manual_response','manual_response_received','manual_response_parsed') then
    raise exception using errcode = '23514', message = 'facility_request_not_open';
  end if;

  v_facility_id := nullif(trim(coalesce(p_facility_id,v_request.facility_id,'')),'');
  v_meter_external := nullif(trim(coalesce(p_metering_point_external_id,v_request.metering_point_id,'')),'');
  v_grid_area := upper(nullif(trim(coalesce(p_grid_area_code,v_request.grid_area_code,v_site.grid_area_code,'')),''));
  v_price_area := upper(nullif(trim(coalesce(p_price_area_code,v_request.price_area,v_site.price_area_code,'')),''));

  if v_facility_id is null and v_meter_external is null then raise exception using errcode = '23514', message = 'facility_or_metering_point_missing'; end if;
  if v_grid_area is null then raise exception using errcode = '23514', message = 'facility_response_grid_area_missing'; end if;
  if v_price_area is not null and v_price_area not in ('SE1','SE2','SE3','SE4') then raise exception using errcode = '23514', message = 'invalid_price_area'; end if;

  select ga.grid_area_name, coalesce(pgo.name,ga.grid_owner_name), pgo.ops_grid_owner_id, ga.price_area
    into v_grid_area_name, v_grid_owner_name, v_master_ops_grid_owner_id, v_master_price_area
  from public.platform_grid_areas ga
  left join public.platform_grid_owners pgo on pgo.id = ga.grid_owner_id
  where ga.grid_area_code = v_grid_area and ga.is_active = true;

  if v_master_ops_grid_owner_id is null or v_master_ops_grid_owner_id is distinct from v_request.grid_owner_id then
    insert into public.facility_data_quality_issues(company_id,customer_id,customer_site_id,grid_owner_id,issue_type,severity,source,recommended_action,retry_allowed,metadata)
    values (p_company_id,v_request.customer_id,v_request.customer_site_id,v_request.grid_owner_id,'grid_owner_conflict','critical',p_source,'Facility response grid area does not map to the canonical request owner.',false,jsonb_build_object('request_id',p_request_id,'grid_area_code',v_grid_area,'master_ops_grid_owner_id',v_master_ops_grid_owner_id));
    return jsonb_build_object('ok',false,'code','grid_owner_conflict','requestId',p_request_id,'customerId',v_request.customer_id,'customerSiteId',v_request.customer_site_id);
  end if;

  if v_price_area is not null and v_master_price_area is not null and v_price_area <> v_master_price_area then
    insert into public.facility_data_quality_issues(company_id,customer_id,customer_site_id,grid_owner_id,issue_type,severity,source,recommended_action,retry_allowed,metadata)
    values (p_company_id,v_request.customer_id,v_request.customer_site_id,v_request.grid_owner_id,'price_area_conflict','critical',p_source,'Facility response price area conflicts with canonical grid-area masterdata.',false,jsonb_build_object('request_id',p_request_id,'incoming_price_area',v_price_area,'master_price_area',v_master_price_area,'grid_area_code',v_grid_area));
    return jsonb_build_object('ok',false,'code','price_area_conflict','requestId',p_request_id,'customerId',v_request.customer_id,'customerSiteId',v_request.customer_site_id);
  end if;
  v_price_area := coalesce(v_master_price_area,v_price_area);

  if v_facility_id is not null and v_site.facility_id is not null and trim(v_site.facility_id) <> v_facility_id then
    insert into public.facility_data_quality_issues(company_id,customer_id,customer_site_id,grid_owner_id,issue_type,severity,facility_id,source,recommended_action,retry_allowed,metadata)
    values (p_company_id,v_request.customer_id,v_request.customer_site_id,v_request.grid_owner_id,'facility_identifier_conflict','critical',v_facility_id,p_source,'Review conflicting facility identifiers before continuing.',false,jsonb_build_object('request_id',p_request_id,'existing_facility_id',v_site.facility_id,'incoming_facility_id',v_facility_id));
    return jsonb_build_object('ok',false,'code','facility_identifier_conflict','requestId',p_request_id,'customerId',v_request.customer_id,'customerSiteId',v_request.customer_site_id);
  end if;

  if v_facility_id is not null and exists (select 1 from public.customer_sites s where s.company_id=p_company_id and s.id<>v_request.customer_site_id and s.is_active=true and s.normalized_facility_id=v_facility_id) then
    insert into public.facility_data_quality_issues(company_id,customer_id,customer_site_id,grid_owner_id,issue_type,severity,facility_id,source,recommended_action,retry_allowed,metadata)
    values (p_company_id,v_request.customer_id,v_request.customer_site_id,v_request.grid_owner_id,'cross_site_identifier_conflict','critical',v_facility_id,p_source,'Resolve the duplicate facility identifier across sites.',false,jsonb_build_object('request_id',p_request_id));
    return jsonb_build_object('ok',false,'code','cross_site_identifier_conflict','requestId',p_request_id,'customerId',v_request.customer_id,'customerSiteId',v_request.customer_site_id);
  end if;

  if v_meter_external is not null then
    select * into v_conflict from public.metering_points m where m.company_id=p_company_id and m.site_id<>v_request.customer_site_id and m.status in ('draft','pending_validation','active') and (m.metering_point_id=v_meter_external or m.meter_point_id=v_meter_external or m.ediel_reference=v_meter_external) limit 1;
    if found then
      insert into public.facility_data_quality_issues(company_id,customer_id,customer_site_id,metering_point_id,grid_owner_id,issue_type,severity,ediel_metering_point_id,source,recommended_action,retry_allowed,metadata)
      values (p_company_id,v_request.customer_id,v_request.customer_site_id,v_conflict.id,v_request.grid_owner_id,'duplicate_metering_point','critical',v_meter_external,p_source,'Resolve the metering-point identity conflict across sites.',false,jsonb_build_object('request_id',p_request_id,'conflicting_site_id',v_conflict.site_id));
      return jsonb_build_object('ok',false,'code','duplicate_metering_point','requestId',p_request_id,'customerId',v_request.customer_id,'customerSiteId',v_request.customer_site_id);
    end if;
  end if;

  if v_site.resolution_id is not null then
    select * into v_previous_resolution from public.customer_site_resolution
    where id=v_site.resolution_id and company_id=p_company_id and customer_site_id=v_request.customer_site_id;
  end if;

  insert into public.customer_site_resolution(
    company_id,customer_id,customer_site_id,customer_application_id,
    grid_owner_id,grid_area_code,grid_area_name,grid_owner_name,price_area,
    resolution_status,confidence,source_chain,input_snapshot,result_snapshot,
    automation_allowed,next_required_action,facility_data_verified_at,verified_by,
    resolved_at,resolver_version,geodata_version,source_claims,conflict_code,
    price_area_assurance_status,price_area_assurance_source,price_area_assurance_confidence,
    price_area_assurance_source_version,price_area_candidate_count,price_area_unique_count,
    price_area_evidence,updated_at
  ) values (
    p_company_id,v_request.customer_id,v_request.customer_site_id,v_request.customer_application_id,
    v_request.grid_owner_id,v_grid_area,v_grid_area_name,v_grid_owner_name,v_price_area,
    'facility_verified',1,
    jsonb_build_array('facility_response',p_source,'grid_owner_information_request','platform_grid_areas'),
    jsonb_build_object('request_id',p_request_id,'source',p_source,'ediel_message_id',p_ediel_message_id),
    jsonb_build_object(
      'gridAreaCode',v_grid_area,'gridAreaName',v_grid_area_name,
      'gridOwnerId',v_request.grid_owner_id,'gridOwnerName',v_grid_owner_name,
      'priceArea',v_price_area,
      'coordinates',jsonb_build_object('latitude',v_site.latitude,'longitude',v_site.longitude,'sweref99X',v_site.sweref99_x,'sweref99Y',v_site.sweref99_y),
      'facility',jsonb_build_object('facilityId',v_facility_id,'meteringPointId',v_meter_external,'verifiedAt',v_now,'source',p_source)
    ),
    false,'Facility data verified. Evaluate supplier-switch and Ediel/PRODAT readiness separately.',v_now,p_actor_user_id,
    v_now,'facility-response-v2',v_previous_resolution.geodata_version,'{}'::jsonb,null,
    'verified','facility_data',1,v_now::text,1,1,
    jsonb_build_object('request_id',p_request_id,'grid_area_code',v_grid_area,'grid_owner_id',v_request.grid_owner_id,'price_area',v_price_area,'source',p_source),v_now
  ) returning id into v_resolution_id;

  update public.customer_sites
  set facility_id=coalesce(v_facility_id,facility_id),
      normalized_facility_id=coalesce(v_facility_id,normalized_facility_id),
      resolution_id=v_resolution_id,
      resolution_status='facility_verified',
      resolution_confidence=1,
      bidding_zone_code=coalesce(v_price_area,bidding_zone_code),
      facility_data_status='verified',facility_data_verified_at=v_now,data_quality_status='verified',
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('facility_provenance',jsonb_build_object('sourceType',p_source,'sourceMessageId',p_ediel_message_id,'receivedAt',v_now,'verificationLevel',case when p_source='ediel_inbound' then 'market_verified' else 'externally_verified' end,'verifiedAt',v_now),'facility_resolution_id',v_resolution_id),
      updated_at=v_now,updated_by=p_actor_user_id
  where id=v_request.customer_site_id and company_id=p_company_id and customer_id=v_request.customer_id;

  if v_meter_external is not null then
    select * into v_meter from public.metering_points m where m.company_id=p_company_id and m.customer_id=v_request.customer_id and m.site_id=v_request.customer_site_id and (m.metering_point_id=v_meter_external or m.meter_point_id=v_meter_external or m.ediel_reference=v_meter_external) for update;
    if found then
      update public.metering_points set customer_site_id=v_request.customer_site_id,site_facility_id=coalesce(v_facility_id,site_facility_id),grid_owner_id=coalesce(v_request.grid_owner_id,grid_owner_id),grid_area_code=coalesce(v_grid_area,grid_area_code),price_area_code=coalesce(v_price_area,price_area_code),bidding_zone_code=coalesce(v_price_area,bidding_zone_code),status='active',data_quality_status='verified',verification_status='verified',facility_data_status='verified',facility_data_verified_at=v_now,metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('facility_response_source',p_source,'facility_response_request_id',p_request_id,'source_message_id',p_ediel_message_id,'resolution_id',v_resolution_id),updated_at=v_now,updated_by=p_actor_user_id where id=v_meter.id returning * into v_meter;
    else
      insert into public.metering_points(company_id,customer_id,site_id,customer_site_id,metering_point_id,meter_point_id,ediel_reference,site_facility_id,grid_owner_id,grid_area_code,price_area_code,bidding_zone_code,status,measurement_type,reading_frequency,data_quality_status,verification_status,facility_data_status,facility_data_verified_at,metadata,created_by,updated_by)
      values (p_company_id,v_request.customer_id,v_request.customer_site_id,v_request.customer_site_id,v_meter_external,v_meter_external,v_meter_external,v_facility_id,v_request.grid_owner_id,v_grid_area,v_price_area,v_price_area,'active','consumption','hourly','verified','verified','verified',v_now,jsonb_build_object('facility_response_source',p_source,'facility_response_request_id',p_request_id,'source_message_id',p_ediel_message_id,'raw_payload',coalesce(p_raw_payload,'{}'::jsonb),'resolution_id',v_resolution_id),p_actor_user_id,p_actor_user_id) returning * into v_meter;
    end if;
  end if;

  update public.customer_info_requests
  set blocker_code=null,blocker_reason=null,blocker_details='{}'::jsonb,route_resolution_status='facility_identifier_received',next_required_action='Starta leverantörsbyte när readiness är grön.',metering_point_id=coalesce(v_meter.id,metering_point_id),status='ready_for_switch',updated_at=v_now,updated_by=p_actor_user_id
  where company_id=p_company_id and customer_id=v_request.customer_id and site_id=v_request.customer_site_id and blocker_code='facility_or_metering_point_missing';

  v_received := coalesce(v_request.received_payload,'{}'::jsonb)||jsonb_build_object('source',p_source,'ediel_message_id',p_ediel_message_id,'facility_id',v_facility_id,'metering_point_id',v_meter_external,'grid_area_code',v_grid_area,'price_area',v_price_area,'resolution_id',v_resolution_id,'note',p_note,'raw_payload',coalesce(p_raw_payload,'{}'::jsonb),'completed_at',v_now);

  update public.grid_owner_information_requests
  set status='completed',dispatch_status='completed',received_at=v_now,completed_at=v_now,facility_id=v_facility_id,metering_point_id=v_meter_external,grid_area_code=v_grid_area,price_area=v_price_area,resolution_id=v_resolution_id,received_payload=v_received,metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('completed_by',p_source,'completed_at',v_now,'matched_ediel_message_id',p_ediel_message_id,'atomic_completion',true,'resolution_id',v_resolution_id),updated_at=v_now,updated_by=p_actor_user_id
  where id=p_request_id and company_id=p_company_id;

  return jsonb_build_object('ok',true,'alreadyCompleted',false,'requestId',p_request_id,'customerId',v_request.customer_id,'customerSiteId',v_request.customer_site_id,'meteringPointRecordId',v_meter.id,'operationId',v_request.operation_id,'facilityId',v_facility_id,'meteringPointExternalId',v_meter_external,'gridAreaCode',v_grid_area,'priceAreaCode',v_price_area,'resolutionId',v_resolution_id);
end;
$$;

--
-- Name: gridex_complete_grid_owner_readiness(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_complete_grid_owner_readiness(p_source text DEFAULT 'manual'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_prodat_route_filled int := 0;
  v_utilts_route_filled int := 0;
  v_status_updated int := 0;
  v_reviews_created int := 0;
  v_reviews_resolved int := 0;
  v_backfill jsonb;
begin
  -- Auto-fill PRODAT only when exactly one non-empty production PRODAT subaddress exists for the actor.
  with candidates as (
    select
      r.actor_id,
      min(nullif(btrim(coalesce(r.subaddress, '')), '')) as only_subaddress
    from public.platform_actor_routes r
    where upper(r.message_family) = 'PRODAT'
      and r.environment = 'production'
      and coalesce(r.status, '') = 'active'
      and nullif(btrim(coalesce(r.subaddress, '')), '') is not null
    group by r.actor_id
    having count(distinct nullif(btrim(coalesce(r.subaddress, '')), '')) = 1
  )
  update public.grid_owners g
  set default_prodat_subaddress = c.only_subaddress,
      prodat_subaddress_status = 'verified',
      prodat_subaddress_source = 'route',
      subaddress_verified_at = coalesce(g.subaddress_verified_at, now()),
      subaddress_verification_note = coalesce(g.subaddress_verification_note, 'Autoifylld från verifierad actor route.'),
      updated_at = now()
  from candidates c
  where g.platform_market_actor_id = c.actor_id
    and nullif(btrim(coalesce(g.default_prodat_subaddress, '')), '') is null
    and coalesce(g.prodat_subaddress_status, 'missing') <> 'not_required_confirmed';
  get diagnostics v_prodat_route_filled = row_count;

  -- Auto-fill UTILTS only when exactly one non-empty production UTILTS subaddress exists for the actor.
  with candidates as (
    select
      r.actor_id,
      min(nullif(btrim(coalesce(r.subaddress, '')), '')) as only_subaddress
    from public.platform_actor_routes r
    where upper(r.message_family) = 'UTILTS'
      and r.environment = 'production'
      and coalesce(r.status, '') = 'active'
      and nullif(btrim(coalesce(r.subaddress, '')), '') is not null
    group by r.actor_id
    having count(distinct nullif(btrim(coalesce(r.subaddress, '')), '')) = 1
  )
  update public.grid_owners g
  set default_utilts_subaddress = c.only_subaddress,
      utilts_subaddress_status = 'verified',
      utilts_subaddress_source = 'route',
      subaddress_verified_at = coalesce(g.subaddress_verified_at, now()),
      subaddress_verification_note = coalesce(g.subaddress_verification_note, 'Autoifylld från verifierad actor route.'),
      updated_at = now()
  from candidates c
  where g.platform_market_actor_id = c.actor_id
    and nullif(btrim(coalesce(g.default_utilts_subaddress, '')), '') is null
    and coalesce(g.utilts_subaddress_status, 'missing') <> 'not_required_confirmed';
  get diagnostics v_utilts_route_filled = row_count;

  -- Persist evaluated subaddress status and per-flow readiness from the canonical view.
  update public.grid_owners g
  set prodat_subaddress_status = case
        when v.prodat_route_count = 0 then g.prodat_subaddress_status
        when v.prodat_subaddress_status in ('verified','not_required_confirmed','ambiguous','missing') then v.prodat_subaddress_status
        else g.prodat_subaddress_status
      end,
      utilts_subaddress_status = case
        when v.utilts_route_count = 0 then g.utilts_subaddress_status
        when v.utilts_subaddress_status in ('verified','not_required_confirmed','ambiguous','missing') then v.utilts_subaddress_status
        else g.utilts_subaddress_status
      end,
      prodat_subaddress_source = case
        when v.prodat_route_count = 0 then g.prodat_subaddress_source
        when v.prodat_subaddress_source in ('route','manual_verified','not_required_confirmed','ambiguous','missing') then v.prodat_subaddress_source
        else g.prodat_subaddress_source
      end,
      utilts_subaddress_source = case
        when v.utilts_route_count = 0 then g.utilts_subaddress_source
        when v.utilts_subaddress_source in ('route','manual_verified','not_required_confirmed','ambiguous','missing') then v.utilts_subaddress_source
        else g.utilts_subaddress_source
      end,
      prodat_ready_for_customer_flow = coalesce(v.can_use_for_prodat, false),
      utilts_ready_for_metering_flow = coalesce(v.can_use_for_utilts, false),
      supplier_switch_ready = coalesce(v.can_start_supplier_switch, false),
      certificate_last_import_at = case when v.certificate_status = 'finns' then now() else g.certificate_last_import_at end,
      certificate_import_source = case when v.certificate_status = 'finns' then coalesce(v.certificate_source, g.certificate_import_source) else g.certificate_import_source end,
      updated_at = now()
  from public.gridex_verified_grid_owners_v v
  where v.grid_owner_id = g.id;
  get diagnostics v_status_updated = row_count;

  -- Add explicit ambiguous-subaddress review rows when registry has multiple candidates.
  insert into public.grid_owner_verification_reviews(grid_owner_id, platform_market_actor_id, issue_type, severity, status, message, metadata)
  select v.grid_owner_id, v.platform_market_actor_id, 'ambiguous_subaddress', 'blocking', 'open',
         'Flera möjliga subadresser finns. Välj rätt PRODAT/UTILTS-subadress innan nätägaren används.',
         jsonb_build_object(
           'possible_prodat_subaddresses', v.possible_prodat_subaddresses,
           'possible_utilts_subaddresses', v.possible_utilts_subaddresses,
           'backfill_source', p_source
         )
  from public.gridex_verified_grid_owners_v v
  where v.verification_status = 'ambiguous_subaddress'
    and not exists (
      select 1 from public.grid_owner_verification_reviews r
      where r.grid_owner_id = v.grid_owner_id and r.issue_type = 'ambiguous_subaddress' and r.status = 'open'
    );
  get diagnostics v_reviews_created = row_count;

  -- Let the Batch O function persist overall verification state and ordinary review issues.
  v_backfill := public.gridex_backfill_grid_owner_verification(coalesce(p_source, 'manual') || '_o2');

  -- Close stale open review items once the current canonical view no longer carries that issue.
  update public.grid_owner_verification_reviews r
  set status = 'resolved',
      resolved_at = now(),
      metadata = coalesce(r.metadata, '{}'::jsonb) || jsonb_build_object('resolved_by_batch_o2', now(), 'source', p_source)
  from public.gridex_verified_grid_owners_v v
  where r.grid_owner_id = v.grid_owner_id
    and r.status = 'open'
    and r.issue_type in ('needs_subaddress','ambiguous_subaddress','needs_certificate','needs_route','needs_contact','needs_ediel_id','unresolved_duplicate')
    and r.issue_type <> v.verification_status
    and not (r.issue_type = any(v.verification_reasons));
  get diagnostics v_reviews_resolved = row_count;

  return jsonb_build_object(
    'ok', true,
    'prodat_subaddresses_filled_from_route', v_prodat_route_filled,
    'utilts_subaddresses_filled_from_route', v_utilts_route_filled,
    'grid_owners_status_updated', v_status_updated,
    'ambiguous_review_items_created', v_reviews_created,
    'stale_review_items_resolved', v_reviews_resolved,
    'batch_o_backfill', v_backfill
  );
end;
$$;

--
-- Name: gridex_complete_unreferenced_internal_invoice_fee_tasks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_complete_unreferenced_internal_invoice_fee_tasks() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  r record;
  v_snapshot jsonb;
  v_readiness jsonb;
  v_processed integer:=0;
  v_resolved integer:=0;
  v_blocked integer:=0;
  v_failed integer:=0;
  v_error text;
begin
  for r in
    select o.*,t.evidence as remediation_evidence
    from public.contract_offers o
    join public.contract_invoice_fee_remediation_tasks t
      on t.source_table='contract_offers' and t.offer_id=o.id
    where t.status in('open','failed')
      and t.blocker_code in('invoice_fee_missing','invoice_fee_conflict','invoice_fee_ambiguous')
      and o.company_id is not null
      and o.invoice_fee_sek is not null
      and o.invoice_fee_sek>=0
      and o.contract_type in('variable_monthly','variable_hourly','variable_quarterly','spot','fixed')
      and o.published_at is null
      and not exists(
        select 1 from public.customer_contracts cc
        where cc.company_id=o.company_id and cc.contract_offer_id=o.id
      )
      and not exists(
        select 1 from public.contract_offer_versions cov
        where (to_jsonb(cov)->>'contract_offer_id'=o.id::text or to_jsonb(cov)->>'offer_id'=o.id::text)
      )
    order by o.created_at,o.id
    for update of o
  loop
    v_processed:=v_processed+1;
    begin
      v_snapshot:=public.gridex_legacy_internal_offer_pricing_snapshot(r.id);
      v_readiness:=public.gridex_invoice_fee_readiness(v_snapshot,r.invoice_fee_sek);

      if coalesce(v_readiness->>'status','blocked')<>'ready' then
        perform public.gridex_record_invoice_fee_remediation(
          r.company_id,'contract_offers',r.id,'open',
          coalesce(v_readiness->>'code','invoice_fee_missing'),
          jsonb_build_object(
            'readiness',v_readiness,
            'snapshot',v_snapshot,
            'strategy','unpublished_unreferenced_in_place'
          )
        );
        v_blocked:=v_blocked+1;
        continue;
      end if;

      update public.contract_offers
      set commercial_snapshot=v_snapshot,
          version_snapshot=coalesce(version_snapshot,'{}'::jsonb)
            || jsonb_build_object(
              'pricing_snapshot',v_snapshot,
              'pricing',coalesce(version_snapshot->'pricing','{}'::jsonb)
                || jsonb_build_object(
                  'monthlyFeeSek',monthly_fee_sek,
                  'invoiceFeeSek',invoice_fee_sek,
                  'spotMarkupOrePerKwh',spot_markup_ore_per_kwh,
                  'variableFeeOrePerKwh',variable_fee_ore_per_kwh,
                  'fixedPriceOrePerKwh',fixed_price_ore_per_kwh,
                  'greenFeeMode',green_fee_mode,
                  'greenFeeValue',green_fee_value
                )
            ),
          updated_at=now()
      where id=r.id and company_id=r.company_id;

      perform public.gridex_record_invoice_fee_remediation(
        r.company_id,'contract_offers',r.id,'resolved',null,
        jsonb_build_object(
          'old_evidence',r.remediation_evidence,
          'new_value',r.invoice_fee_sek,
          'readiness',v_readiness,
          'strategy','unpublished_unreferenced_in_place',
          'history_mutated',false,
          'requires_price_area_before_publication',jsonb_array_length(coalesce(v_snapshot->'price_areas','[]'::jsonb))=0
        )
      );

      insert into public.audit_logs(
        company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata
      ) values(
        r.company_id,coalesce(r.updated_by,r.created_by),'contract_offer',r.id::text,
        'contract.invoice_fee.legacy_snapshot_completed',
        jsonb_build_object('commercial_snapshot',r.commercial_snapshot,'version_snapshot',r.version_snapshot),
        jsonb_build_object('invoice_fee_sek',r.invoice_fee_sek,'commercial_snapshot',v_snapshot),
        jsonb_build_object(
          'version_safe',true,
          'unpublished',true,
          'customer_references',0,
          'offer_version_references',0,
          'price_area_required_before_publication',jsonb_array_length(coalesce(v_snapshot->'price_areas','[]'::jsonb))=0
        )
      );

      v_resolved:=v_resolved+1;
    exception when others then
      v_error:=sqlerrm;
      perform public.gridex_record_invoice_fee_remediation(
        r.company_id,'contract_offers',r.id,'failed','legacy_snapshot_completion_failed',
        jsonb_build_object(
          'strategy','unpublished_unreferenced_in_place',
          'invoice_fee_sek',r.invoice_fee_sek
        ),v_error
      );
      v_failed:=v_failed+1;
    end;
  end loop;

  return jsonb_build_object(
    'processed',v_processed,'resolved',v_resolved,'blocked',v_blocked,'failed',v_failed
  );
end $$;

--
-- Name: gridex_confirm_grid_owner_empty_subaddress(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_confirm_grid_owner_empty_subaddress(p_grid_owner_id uuid, p_message_family text, p_actor_user_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_family text := upper(coalesce(p_message_family, ''));
  v_owner public.grid_owners%rowtype;
  v_backfill jsonb;
begin
  if p_grid_owner_id is null then
    raise exception 'grid_owner_id is required';
  end if;
  if v_family not in ('PRODAT','UTILTS') then
    raise exception 'message_family must be PRODAT or UTILTS';
  end if;

  select * into v_owner from public.grid_owners where id = p_grid_owner_id for update;
  if not found then
    raise exception 'grid owner not found';
  end if;

  if v_family = 'PRODAT' then
    update public.grid_owners
    set default_prodat_subaddress = null,
        prodat_subaddress_status = 'not_required_confirmed',
        prodat_subaddress_source = 'not_required_confirmed',
        subaddress_verified_at = now(),
        subaddress_verified_by = p_actor_user_id,
        subaddress_verification_note = coalesce(nullif(btrim(p_note), ''), 'Tom PRODAT-subadress bekräftad som korrekt av platform admin.'),
        verification_metadata = coalesce(verification_metadata, '{}'::jsonb) || jsonb_build_object('prodat_empty_subaddress_confirmed_at', now(), 'prodat_empty_subaddress_confirmed_by', p_actor_user_id),
        updated_at = now()
    where id = p_grid_owner_id;
  else
    update public.grid_owners
    set default_utilts_subaddress = null,
        utilts_subaddress_status = 'not_required_confirmed',
        utilts_subaddress_source = 'not_required_confirmed',
        subaddress_verified_at = now(),
        subaddress_verified_by = p_actor_user_id,
        subaddress_verification_note = coalesce(nullif(btrim(p_note), ''), 'Tom UTILTS-subadress bekräftad som korrekt av platform admin.'),
        verification_metadata = coalesce(verification_metadata, '{}'::jsonb) || jsonb_build_object('utilts_empty_subaddress_confirmed_at', now(), 'utilts_empty_subaddress_confirmed_by', p_actor_user_id),
        updated_at = now()
    where id = p_grid_owner_id;
  end if;

  update public.grid_owner_verification_reviews
  set status = 'resolved',
      resolved_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('resolved_by', p_actor_user_id, 'resolution', 'empty_subaddress_confirmed', 'message_family', v_family)
  where grid_owner_id = p_grid_owner_id
    and issue_type in ('needs_subaddress','ambiguous_subaddress')
    and status = 'open';

  v_backfill := public.gridex_complete_grid_owner_readiness('confirm_empty_subaddress_' || lower(v_family));
  return jsonb_build_object('ok', true, 'grid_owner_id', p_grid_owner_id, 'message_family', v_family, 'backfill', v_backfill);
end;
$$;

--
-- Name: gridex_confirm_registry_empty_subaddresses(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_confirm_registry_empty_subaddresses(p_source text DEFAULT 'manual'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_prodat_confirmed int := 0;
  v_utilts_confirmed int := 0;
  v_reviews_resolved int := 0;
  v_recheck jsonb := '{}'::jsonb;
begin
  -- PRODAT: mark empty route-subaddress as verified empty only when the registry route is unique and safe.
  with route_candidates as (
    select
      r.actor_id,
      count(*) filter (where upper(r.message_family) = 'PRODAT' and r.environment = 'production' and coalesce(r.status, '') = 'active') as active_route_count,
      count(*) filter (where upper(r.message_family) = 'PRODAT' and r.environment = 'production' and coalesce(r.status, '') = 'active' and nullif(btrim(coalesce(r.subaddress, '')), '') is not null) as non_empty_subaddress_count,
      count(distinct nullif(btrim(coalesce(r.subaddress, '')), '')) filter (where upper(r.message_family) = 'PRODAT' and r.environment = 'production' and coalesce(r.status, '') = 'active' and nullif(btrim(coalesce(r.subaddress, '')), '') is not null) as distinct_subaddress_count,
      bool_or(upper(r.message_family) = 'PRODAT' and r.environment = 'production' and coalesce(r.status, '') = 'active' and nullif(btrim(coalesce(r.communication_address, '')), '') is not null) as has_communication_address,
      bool_and(coalesce(r.is_verified, true)) filter (where upper(r.message_family) = 'PRODAT' and r.environment = 'production' and coalesce(r.status, '') = 'active') as active_routes_verified
    from public.platform_actor_routes r
    group by r.actor_id
  )
  update public.grid_owners g
  set prodat_subaddress_status = 'not_required_confirmed',
      prodat_subaddress_source = 'registry_empty_route',
      default_prodat_subaddress = null,
      subaddress_verified_at = coalesce(g.subaddress_verified_at, now()),
      subaddress_verification_note = coalesce(
        nullif(btrim(g.subaddress_verification_note), ''),
        'Tom PRODAT-subadress verifierad från aktiv platform actor route utan registrerad subadress.'
      ),
      verification_metadata = coalesce(g.verification_metadata, '{}'::jsonb)
        || jsonb_build_object(
          'prodat_empty_subaddress_confirmed_at', now(),
          'prodat_empty_subaddress_confirmed_source', p_source,
          'prodat_empty_subaddress_confirmation_rule', 'unique_active_production_route_with_empty_registry_subaddress'
        ),
      updated_at = now()
  from route_candidates c
  where g.platform_market_actor_id = c.actor_id
    and c.active_route_count = 1
    and c.non_empty_subaddress_count = 0
    and c.distinct_subaddress_count = 0
    and c.has_communication_address = true
    and coalesce(c.active_routes_verified, true) = true
    and coalesce(g.prodat_subaddress_status, 'missing') in ('missing','ambiguous')
    and nullif(btrim(coalesce(g.default_prodat_subaddress, '')), '') is null;
  get diagnostics v_prodat_confirmed = row_count;

  -- UTILTS: same safe rule for metering route readiness.
  with route_candidates as (
    select
      r.actor_id,
      count(*) filter (where upper(r.message_family) = 'UTILTS' and r.environment = 'production' and coalesce(r.status, '') = 'active') as active_route_count,
      count(*) filter (where upper(r.message_family) = 'UTILTS' and r.environment = 'production' and coalesce(r.status, '') = 'active' and nullif(btrim(coalesce(r.subaddress, '')), '') is not null) as non_empty_subaddress_count,
      count(distinct nullif(btrim(coalesce(r.subaddress, '')), '')) filter (where upper(r.message_family) = 'UTILTS' and r.environment = 'production' and coalesce(r.status, '') = 'active' and nullif(btrim(coalesce(r.subaddress, '')), '') is not null) as distinct_subaddress_count,
      bool_or(upper(r.message_family) = 'UTILTS' and r.environment = 'production' and coalesce(r.status, '') = 'active' and nullif(btrim(coalesce(r.communication_address, '')), '') is not null) as has_communication_address,
      bool_and(coalesce(r.is_verified, true)) filter (where upper(r.message_family) = 'UTILTS' and r.environment = 'production' and coalesce(r.status, '') = 'active') as active_routes_verified
    from public.platform_actor_routes r
    group by r.actor_id
  )
  update public.grid_owners g
  set utilts_subaddress_status = 'not_required_confirmed',
      utilts_subaddress_source = 'registry_empty_route',
      default_utilts_subaddress = null,
      subaddress_verified_at = coalesce(g.subaddress_verified_at, now()),
      subaddress_verification_note = coalesce(
        nullif(btrim(g.subaddress_verification_note), ''),
        'Tom UTILTS-subadress verifierad från aktiv platform actor route utan registrerad subadress.'
      ),
      verification_metadata = coalesce(g.verification_metadata, '{}'::jsonb)
        || jsonb_build_object(
          'utilts_empty_subaddress_confirmed_at', now(),
          'utilts_empty_subaddress_confirmed_source', p_source,
          'utilts_empty_subaddress_confirmation_rule', 'unique_active_production_route_with_empty_registry_subaddress'
        ),
      updated_at = now()
  from route_candidates c
  where g.platform_market_actor_id = c.actor_id
    and c.active_route_count = 1
    and c.non_empty_subaddress_count = 0
    and c.distinct_subaddress_count = 0
    and c.has_communication_address = true
    and coalesce(c.active_routes_verified, true) = true
    and coalesce(g.utilts_subaddress_status, 'missing') in ('missing','ambiguous')
    and nullif(btrim(coalesce(g.default_utilts_subaddress, '')), '') is null;
  get diagnostics v_utilts_confirmed = row_count;

  -- Re-run O2 completion if it exists, then Batch O verification if available through that function.
  if exists (
    select 1 from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.proname = 'gridex_complete_grid_owner_readiness'
  ) then
    v_recheck := public.gridex_complete_grid_owner_readiness(coalesce(p_source, 'manual') || '_registry_empty_subaddress');
  end if;

  -- Close needs_subaddress review items when no current canonical view reason remains.
  update public.grid_owner_verification_reviews r
  set status = 'resolved',
      resolved_at = now(),
      metadata = coalesce(r.metadata, '{}'::jsonb)
        || jsonb_build_object('resolved_by_batch_o2_1', now(), 'source', p_source)
  from public.gridex_verified_grid_owners_v v
  where r.grid_owner_id = v.grid_owner_id
    and r.status = 'open'
    and r.issue_type = 'needs_subaddress'
    and not ('needs_subaddress' = any(v.verification_reasons));
  get diagnostics v_reviews_resolved = row_count;

  return jsonb_build_object(
    'ok', true,
    'prodat_empty_subaddresses_confirmed_from_registry', v_prodat_confirmed,
    'utilts_empty_subaddresses_confirmed_from_registry', v_utilts_confirmed,
    'needs_subaddress_review_items_resolved', v_reviews_resolved,
    'readiness_recheck', v_recheck
  );
end;
$$;

--
-- Name: FUNCTION gridex_confirm_registry_empty_subaddresses(p_source text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_confirm_registry_empty_subaddresses(p_source text) IS 'Batch O2.1: marks null route subaddress as verified-empty only for unique active verified production routes with communication address. Does not invent a subaddress value.';

--
-- Name: gridex_confirm_safe_blank_route_subaddresses(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_confirm_safe_blank_route_subaddresses(p_source text DEFAULT 'manual'::text, p_actor_id uuid DEFAULT NULL::uuid, p_apply_auto_send boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_routes_confirmed int := 0;
  v_prodat_routes_confirmed int := 0;
  v_utilts_routes_confirmed int := 0;
  v_grid_prodat_updated int := 0;
  v_grid_utilts_updated int := 0;
  v_readiness jsonb := '{}'::jsonb;
  v_auto_send jsonb := '{}'::jsonb;
begin
  -- Confirm only safe blank routes. Keep subaddress NULL; write provenance to metadata.
  with candidates as (
    select *
    from public.gridex_o6_3_safe_blank_subaddress_candidates_v
    where can_auto_confirm = true
      and (p_actor_id is null or actor_id = p_actor_id)
  ), updated as (
    update public.platform_actor_routes r
    set metadata = coalesce(r.metadata, '{}'::jsonb)
          || jsonb_build_object(
            'subaddress_status', 'not_required_confirmed',
            'subaddress_confirmation_source', 'unique_active_verified_production_route_without_subaddress',
            'subaddress_confirmation_policy', 'blank_allowed_only_for_unique_active_route',
            'subaddress_confirmed_by', 'system',
            'subaddress_confirmed_at', now(),
            'subaddress_confirmation_batch', 'O6.3',
            'subaddress_confirmation_trigger', coalesce(p_source, 'manual'),
            'blank_subaddress_requires_review', false
          ),
        updated_at = now()
    from candidates c
    where r.id = c.route_id
      and coalesce(r.metadata->>'subaddress_status', '') <> 'not_required_confirmed'
    returning r.id, r.actor_id, upper(r.message_family) as message_family
  )
  select
    count(*)::integer,
    count(*) filter (where message_family = 'PRODAT')::integer,
    count(*) filter (where message_family = 'UTILTS')::integer
  into v_routes_confirmed, v_prodat_routes_confirmed, v_utilts_routes_confirmed
  from updated;

  -- Keep legacy/grid-owner readiness fields in sync for grid owners mapped to confirmed actor routes.
  with confirmed as (
    select distinct actor_id, message_family
    from public.gridex_o6_3_safe_blank_subaddress_candidates_v
    where can_auto_confirm = true
      and message_family = 'PRODAT'
      and (p_actor_id is null or actor_id = p_actor_id)
  )
  update public.grid_owners g
  set prodat_subaddress_status = 'not_required_confirmed',
      prodat_subaddress_source = 'registry_empty_route',
      default_prodat_subaddress = null,
      subaddress_verified_at = coalesce(g.subaddress_verified_at, now()),
      subaddress_verification_note = coalesce(nullif(btrim(g.subaddress_verification_note), ''), 'Tom PRODAT-subadress bekräftad från unik aktiv verifierad registerroute utan subadress.'),
      verification_metadata = coalesce(g.verification_metadata, '{}'::jsonb)
        || jsonb_build_object(
          'o6_3_prodat_blank_subaddress_confirmed_at', now(),
          'o6_3_prodat_blank_subaddress_source', coalesce(p_source, 'manual'),
          'o6_3_prodat_blank_subaddress_policy', 'unique_active_verified_production_route_without_subaddress'
        ),
      updated_at = now()
  from confirmed c
  where g.platform_market_actor_id = c.actor_id
    and coalesce(g.prodat_subaddress_status, 'missing') in ('missing', 'ambiguous')
    and nullif(btrim(coalesce(g.default_prodat_subaddress, '')), '') is null;
  get diagnostics v_grid_prodat_updated = row_count;

  with confirmed as (
    select distinct actor_id, message_family
    from public.gridex_o6_3_safe_blank_subaddress_candidates_v
    where can_auto_confirm = true
      and message_family = 'UTILTS'
      and (p_actor_id is null or actor_id = p_actor_id)
  )
  update public.grid_owners g
  set utilts_subaddress_status = 'not_required_confirmed',
      utilts_subaddress_source = 'registry_empty_route',
      default_utilts_subaddress = null,
      subaddress_verified_at = coalesce(g.subaddress_verified_at, now()),
      subaddress_verification_note = coalesce(nullif(btrim(g.subaddress_verification_note), ''), 'Tom UTILTS-subadress bekräftad från unik aktiv verifierad registerroute utan subadress.'),
      verification_metadata = coalesce(g.verification_metadata, '{}'::jsonb)
        || jsonb_build_object(
          'o6_3_utilts_blank_subaddress_confirmed_at', now(),
          'o6_3_utilts_blank_subaddress_source', coalesce(p_source, 'manual'),
          'o6_3_utilts_blank_subaddress_policy', 'unique_active_verified_production_route_without_subaddress'
        ),
      updated_at = now()
  from confirmed c
  where g.platform_market_actor_id = c.actor_id
    and coalesce(g.utilts_subaddress_status, 'missing') in ('missing', 'ambiguous')
    and nullif(btrim(coalesce(g.default_utilts_subaddress, '')), '') is null;
  get diagnostics v_grid_utilts_updated = row_count;

  if exists (
    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'gridex_recalculate_actor_readiness'
  ) then
    v_readiness := public.gridex_recalculate_actor_readiness(p_actor_id);
  end if;

  if coalesce(p_apply_auto_send, true) and exists (
    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.proname = 'gridex_apply_actor_auto_send_readiness'
  ) then
    v_auto_send := public.gridex_apply_actor_auto_send_readiness(null::uuid);
  end if;

  return jsonb_build_object(
    'ok', true,
    'source', coalesce(p_source, 'manual'),
    'actor_id', p_actor_id,
    'routes_confirmed', v_routes_confirmed,
    'prodat_routes_confirmed', v_prodat_routes_confirmed,
    'utilts_routes_confirmed', v_utilts_routes_confirmed,
    'grid_owner_prodat_rows_updated', v_grid_prodat_updated,
    'grid_owner_utilts_rows_updated', v_grid_utilts_updated,
    'readiness_recalculation', v_readiness,
    'auto_send', v_auto_send
  );
end;
$$;

--
-- Name: FUNCTION gridex_confirm_safe_blank_route_subaddresses(p_source text, p_actor_id uuid, p_apply_auto_send boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_confirm_safe_blank_route_subaddresses(p_source text, p_actor_id uuid, p_apply_auto_send boolean) IS 'Backfills and enforces safe blank subaddress handling. Blank subaddress is accepted only for unique active verified production PRODAT/UTILTS routes with matching party IDs and a communication address. Does not invent a subaddress.';

--
-- Name: gridex_consume_api_rate_limit(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_consume_api_rate_limit(p_api_client_id uuid, p_company_id uuid, p_limit integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_actual_company_id uuid;
  v_result record;
begin
  select company_id
  into v_actual_company_id
  from public.integration_api_clients
  where id = p_api_client_id
    and status = 'active';

  if v_actual_company_id is null or v_actual_company_id is distinct from p_company_id then
    raise exception 'api_client_tenant_mismatch' using errcode = '42501';
  end if;

  select *
  into v_result
  from public.integration_api_rate_limit_check(
    p_api_client_id,
    '*legacy*',
    p_limit,
    60
  );

  return jsonb_build_object(
    'allowed', v_result.allowed,
    'request_count', v_result.request_count,
    'limit', v_result.limit_value,
    'reset_at', v_result.reset_at
  );
end;
$$;

--
-- Name: gridex_contact_address(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_contact_address(p_value jsonb) RETURNS jsonb
