--
-- Name: company_customer_list_summary_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.company_customer_list_summary_v WITH (security_invoker='true') AS
 SELECT c.id AS customer_id,
    c.company_id,
    c.customer_number,
    COALESCE(NULLIF(c.full_name, ''::text), NULLIF(c.company_name, ''::text), NULLIF(TRIM(BOTH FROM concat_ws(' '::text, c.first_name, c.last_name)), ''::text), 'Namnlös kund'::text) AS customer_name,
    c.email,
    c.phone,
    c.status,
    c.customer_type,
    ( SELECT count(*) AS count
           FROM public.customer_sites s
          WHERE ((s.company_id = c.company_id) AND (s.customer_id = c.id))) AS sites_count,
    ( SELECT count(*) AS count
           FROM public.metering_points mp
          WHERE ((mp.company_id = c.company_id) AND (mp.customer_id = c.id))) AS metering_points_count,
    latest_contract.status AS active_contract_status,
    GREATEST(c.updated_at, COALESCE(latest_contract.updated_at, c.updated_at), COALESCE(( SELECT max(t.updated_at) AS max
           FROM public.customer_operation_tasks t
          WHERE ((t.company_id = c.company_id) AND (t.customer_id = c.id))), c.updated_at)) AS latest_activity_at,
    ( SELECT count(*) AS count
           FROM public.customer_operation_tasks t
          WHERE ((t.company_id = c.company_id) AND (t.customer_id = c.id) AND (t.status = ANY (ARRAY['open'::text, 'in_progress'::text, 'blocked'::text])))) AS blocking_reason_count
   FROM (public.customers c
     LEFT JOIN LATERAL ( SELECT cc.status,
            cc.updated_at
           FROM public.customer_contracts cc
          WHERE ((cc.company_id = c.company_id) AND (cc.customer_id = c.id))
          ORDER BY cc.updated_at DESC NULLS LAST, cc.created_at DESC
         LIMIT 1) latest_contract ON (true))
  WHERE ((c.company_id IS NOT NULL) AND (COALESCE(c.source, ''::text) <> 'ediel_portal_test'::text) AND (COALESCE(c.status, ''::text) <> ALL (ARRAY['archived'::text, 'deleted'::text, 'deleted_test_only'::text, 'pending_deletion'::text])));

--
-- Name: gridex_customer_list_summary(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_list_summary(p_company_id uuid, p_limit integer DEFAULT 100) RETURNS SETOF public.company_customer_list_summary_v
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select *
  from public.company_customer_list_summary_v
  where company_id = p_company_id
  order by latest_activity_at desc nulls last
  limit greatest(1, least(coalesce(p_limit, 100), 500))
$$;

--
-- Name: gridex_customer_operation_jobs_run_after_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_operation_jobs_run_after_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.run_after is null then
    new.run_after := now();
  end if;

  return new;
end;
$$;

--
-- Name: gridex_customer_operation_outcome_class(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_operation_outcome_class(p_status text, p_attempts integer, p_max_attempts integer) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog'
    AS $$
  select case
    when p_status = 'needs_review' then 'REVIEW'
    when p_status in ('blocked', 'cancelled') then 'STOP'
    when p_status = 'delivery_uncertain' then 'RETRY'
    when p_status = 'failed'
      and coalesce(p_attempts, 0) < greatest(coalesce(p_max_attempts, 1), 1)
      then 'RETRY'
    when p_status = 'failed' then 'STOP'
    else 'AUTO'
  end
$$;

--
-- Name: gridex_customer_status_counts_v1(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_customer_status_counts_v1(p_company_id uuid DEFAULT NULL::uuid, p_customer_type text DEFAULT 'all'::text, p_exclude_test_data boolean DEFAULT false) RETURNS TABLE(all_count bigint, draft bigint, pending_verification bigint, active bigint, inactive bigint, moved bigint, terminated bigint, blocked bigint, archived bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select
    count(*) filter (
      where c.status is null
         or c.status not in ('archived', 'deleted', 'deleted_test_only', 'pending_deletion')
    ) as all_count,
    count(*) filter (where c.status = 'draft') as draft,
    count(*) filter (where c.status = 'pending_verification') as pending_verification,
    count(*) filter (where c.status = 'active') as active,
    count(*) filter (where c.status = 'inactive') as inactive,
    count(*) filter (where c.status = 'moved') as moved,
    count(*) filter (where c.status = 'terminated') as terminated,
    count(*) filter (where c.status = 'blocked') as blocked,
    count(*) filter (where c.status = 'archived') as archived
  from public.customers c
  where c.company_id is not null
    and (p_company_id is null or c.company_id = p_company_id)
    and (c.source is null or c.source <> 'ediel_portal_test')
    and (
      coalesce(p_customer_type, 'all') = 'all'
      or (
        p_customer_type = 'private'
        and (c.customer_type is null or c.customer_type = 'private')
      )
      or (
        p_customer_type in ('business', 'association')
        and c.customer_type = p_customer_type
      )
    )
    and (
      not coalesce(p_exclude_test_data, false)
      or (
        (c.is_test_data is null or c.is_test_data = false)
        and (c.source is null or c.source not ilike '%test%')
      )
    );
$$;

