-- Name: FUNCTION gridex_customer_status_counts_v1(p_company_id uuid, p_customer_type text, p_exclude_test_data boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_customer_status_counts_v1(p_company_id uuid, p_customer_type text, p_exclude_test_data boolean) IS 'Service-role aggregate for OPS customer status chips; preserves tenant/test/customer-type filters while collapsing nine count round-trips into one scan.';

--
-- Name: gridex_db1_default_company_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_db1_default_company_id() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_company_id uuid;
  v_company_count integer := 0;
begin
  select count(*) into v_company_count from public.companies;

  if v_company_count = 0 then
    insert into public.companies (name, slug, company_slug, status, is_active, is_paused, metadata)
    values ('Div3rsa AB', 'div3rsa-ab', 'div3rsa-ab', 'active', true, false, '{"source":"db1_default_company"}'::jsonb)
    returning id into v_company_id;
    return v_company_id;
  end if;

  if v_company_count = 1 then
    select id
    into v_company_id
    from public.companies
    order by created_at nulls last, id::text
    limit 1;
    return v_company_id;
  end if;

  perform public.gridex_db1_log_finding(
    'warning',
    'default_company',
    'companies',
    'No default company selected because more than one company exists.',
    jsonb_build_object('company_count', v_company_count)
  );
  return null;
end;
$$;

--
-- Name: gridex_db1_finish_backfill_run(uuid, text, jsonb, integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_db1_finish_backfill_run(p_run_id uuid, p_status text, p_summary jsonb DEFAULT '{}'::jsonb, p_rows_seen integer DEFAULT 0, p_rows_inserted integer DEFAULT 0, p_rows_updated integer DEFAULT 0, p_rows_skipped integer DEFAULT 0, p_rows_failed integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
begin
  update public.backfill_runs
  set status = coalesce(p_status, 'completed'),
      completed_at = now(),
      rows_seen = coalesce(p_rows_seen, 0),
      rows_inserted = coalesce(p_rows_inserted, 0),
      rows_updated = coalesce(p_rows_updated, 0),
      rows_skipped = coalesce(p_rows_skipped, 0),
      rows_failed = coalesce(p_rows_failed, 0),
      summary = coalesce(p_summary, '{}'::jsonb)
  where id = p_run_id;

  return jsonb_build_object(
    'run_id', p_run_id,
    'status', coalesce(p_status, 'completed'),
    'rows_seen', coalesce(p_rows_seen, 0),
    'rows_inserted', coalesce(p_rows_inserted, 0),
    'rows_updated', coalesce(p_rows_updated, 0),
    'rows_skipped', coalesce(p_rows_skipped, 0),
    'rows_failed', coalesce(p_rows_failed, 0),
    'summary', coalesce(p_summary, '{}'::jsonb)
  );
end;
$$;

--
-- Name: gridex_db1_log_finding(text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_db1_log_finding(p_severity text, p_area text, p_object text, p_message text, p_details jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
begin
  insert into public.gridex_schema_repair_findings(repair_key, severity, finding_area, object_name, message, details)
  values ('db1_schema_repair_backfill_foundation_20260522', p_severity, p_area, p_object, p_message, coalesce(p_details, '{}'::jsonb));
end;
$$;

--
-- Name: gridex_db1_start_backfill_run(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_db1_start_backfill_run(p_run_key text, p_source_scope text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_run_id uuid;
begin
  insert into public.backfill_runs (run_key, source_scope, status, started_at, completed_at, summary)
  values (p_run_key, p_source_scope, 'running', now(), null, '{}'::jsonb)
  on conflict (run_key) do update
  set status = 'running',
      source_scope = excluded.source_scope,
      started_at = now(),
      completed_at = null,
      rows_seen = 0,
      rows_inserted = 0,
      rows_updated = 0,
      rows_skipped = 0,
      rows_failed = 0,
      summary = '{}'::jsonb
  returning id into v_run_id;

  return v_run_id;
end;
$$;

--
-- Name: gridex_db1_try_exec(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_db1_try_exec(p_area text, p_object text, p_sql text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
begin
  execute p_sql;
exception when others then
  perform public.gridex_db1_log_finding(
    'warning',
    p_area,
    p_object,
    SQLERRM,
    jsonb_build_object('sqlstate', SQLSTATE, 'sql', p_sql)
  );
end;
$$;

--
-- Name: gridex_db4b_archive_customer_registry_row(text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_db4b_archive_customer_registry_row(p_lookup text, p_email text DEFAULT NULL::text, p_apply boolean DEFAULT false, p_reason text DEFAULT 'Archived old/test customer from active customer registry.'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_customer_count integer := 0;
  v_updated_customers integer := 0;
begin
  if nullif(btrim(coalesce(p_lookup, '')), '') is null
     and nullif(btrim(coalesce(p_email, '')), '') is null then
    raise exception using
      errcode = '22023',
      message = 'p_lookup or p_email is required';
  end if;

  select count(*) into v_customer_count
  from public.customers customer
  where (
    p_lookup is not null
    and (
      customer.id::text = p_lookup
      or customer.customer_number = p_lookup
      or customer.personal_number = p_lookup
    )
  ) or (
    p_email is not null
    and lower(coalesce(customer.email, '')) = lower(p_email)
  );

  if not p_apply then
    return jsonb_build_object(
      'apply', false,
      'matched_customers', v_customer_count,
      'matched_customer_profiles', 0,
      'message', 'Dry-run only. Re-run with p_apply=true to archive matching canonical customer rows.'
    );
  end if;

  insert into public.gridex_archived_customer_registry_rows(
    archived_by, archive_reason, source_table, source_id, source_email, source_row
  )
  select
    v_actor, p_reason, 'customers', customer.id::text, customer.email,
    to_jsonb(customer)
  from public.customers customer
  where (
    p_lookup is not null
    and (
      customer.id::text = p_lookup
      or customer.customer_number = p_lookup
      or customer.personal_number = p_lookup
    )
  ) or (
    p_email is not null
    and lower(coalesce(customer.email, '')) = lower(p_email)
  );

  update public.customers customer
  set status = 'archived',
      metadata = coalesce(customer.metadata, '{}'::jsonb) || jsonb_build_object(
        'archived_from_active_registry', true,
        'archived_at', now(),
        'archived_reason', p_reason,
        'db4b_cleanup', true
      ),
      updated_at = now(),
      updated_by = coalesce(v_actor, customer.updated_by)
  where (
    p_lookup is not null
    and (
      customer.id::text = p_lookup
      or customer.customer_number = p_lookup
      or customer.personal_number = p_lookup
    )
  ) or (
    p_email is not null
    and lower(coalesce(customer.email, '')) = lower(p_email)
  );
  get diagnostics v_updated_customers = row_count;

  return jsonb_build_object(
    'apply', true,
    'matched_customers_before_apply', v_customer_count,
    'matched_customer_profiles_before_apply', 0,
    'archived_customers', v_updated_customers,
    'removed_customer_profiles', 0,
    'message', 'Matching canonical customer rows were archived. Authentication and tenant memberships were not touched.'
  );
end
$$;

--
-- Name: gridex_default_customer_number_prefix(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_default_customer_number_prefix(p_company_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_prefix text;
begin
  select public.gridex_normalize_customer_number_prefix(
           coalesce(
             nullif(c.customer_number_prefix, ''),
             nullif(s.prefix, ''),
             c.metadata->>'customer_number_prefix'
           ),
           coalesce(nullif(c.slug, ''), nullif(c.name, ''), 'GDX')
         )
    into v_prefix
  from public.companies c
  left join public.company_customer_number_sequences s on s.company_id = c.id
  where c.id = p_company_id;

  return coalesce(v_prefix, 'GDX');
end;
$$;

--
-- Name: gridex_default_document_prefix(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_default_document_prefix(p_company_id uuid, p_sequence_key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_prefix text;
  v_company_name text;
begin
  select c.name,
         case
           when p_sequence_key = 'contract' then c.contract_number_prefix
           when p_sequence_key = 'application' then c.application_number_prefix
           else null
         end
    into v_company_name, v_prefix
  from public.companies c
  where c.id = p_company_id;

  if v_prefix is null or btrim(v_prefix) = '' then
    v_prefix := case
      when p_sequence_key = 'contract' then 'AVT'
      when p_sequence_key = 'application' then 'APP'
      else upper(left(regexp_replace(coalesce(v_company_name, 'DOC'), '[^A-Za-z0-9]', '', 'g'), 6))
    end;
  end if;

  v_prefix := upper(regexp_replace(v_prefix, '[^A-Z0-9]', '', 'g'));
  if length(v_prefix) < 2 then
    v_prefix := rpad(v_prefix, 2, 'X');
  end if;
  return left(v_prefix, 16);
end;
$$;

--
-- Name: gridex_delete_partner_webhook_subscription_v1(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_delete_partner_webhook_subscription_v1(p_company_id uuid, p_api_client_id uuid, p_subscription_reference text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_subscription public.webhook_subscriptions%rowtype;
  v_secret_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode='42501', message='partner_api_service_role_required';
  end if;

  select *
  into v_subscription
  from public.webhook_subscriptions
  where company_id = p_company_id
    and api_client_id = p_api_client_id
    and webhook_subscription_reference = btrim(p_subscription_reference)
  for update;

  if not found then
    return false;
  end if;

  begin
    v_secret_id := nullif(v_subscription.signing_secret_ref,'')::uuid;
  exception when invalid_text_representation then
    v_secret_id := null;
  end;

  delete from public.webhook_subscriptions
  where id = v_subscription.id
    and company_id = p_company_id
    and api_client_id = p_api_client_id;

  if v_secret_id is not null then
    delete from vault.secrets where id = v_secret_id;
  end if;
  return true;
end
$$;

--
-- Name: gridex_delete_unused_contract(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_delete_unused_contract(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  v_preview jsonb;
  v_graph jsonb;
  v_product_id uuid;
  v_public_offer_ids uuid[]:='{}'::uuid[];
  v_assignment_ids uuid[]:='{}'::uuid[];
  v_product_version_ids uuid[]:='{}'::uuid[];
  v_publication_ids uuid[]:='{}'::uuid[];
  v_publication_version_ids uuid[]:='{}'::uuid[];
  v_legal_version_ids uuid[]:='{}'::uuid[];
  v_counts jsonb:='{}'::jsonb;
  v_count bigint;
begin
  perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.delete_unused');
  select * into o
  from public.contract_offers co
  where co.id=p_offer_id and co.company_id=p_company_id
  for update;
  if not found then
    raise exception using errcode='P0002',message='contract_offer_not_found';
  end if;

  v_preview:=public.gridex_preview_delete_unused_contract(p_company_id,p_offer_id);
  if not coalesce((v_preview->>'can_delete')::boolean,false) then
    return jsonb_build_object(
      'ok',false,'changed',false,'deleted',false,'mode','blocked',
      'code','contract_delete_blocked',
      'reason_codes',coalesce(v_preview->'reason_codes','[]'::jsonb),
      'blockers',coalesce(v_preview->'blockers','[]'::jsonb),
      'recommended_action',coalesce(v_preview->>'recommended_action','review'),
      'delete_preview',v_preview
    );
  end if;

  v_graph:=v_preview->'graph';
  select coalesce(array_agg(value::uuid),'{}'::uuid[]) into v_public_offer_ids
    from jsonb_array_elements_text(coalesce(v_graph->'public_contract_offer_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[]) into v_assignment_ids
    from jsonb_array_elements_text(coalesce(v_graph->'tenant_assignment_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[]) into v_product_version_ids
    from jsonb_array_elements_text(coalesce(v_graph->'contract_product_version_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[]) into v_publication_ids
    from jsonb_array_elements_text(coalesce(v_graph->'publication_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[]) into v_publication_version_ids
    from jsonb_array_elements_text(coalesce(v_graph->'publication_version_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[]) into v_legal_version_ids
    from jsonb_array_elements_text(coalesce(v_graph->'legal_bundle_version_ids','[]'::jsonb));

  v_product_id:=o.contract_product_id;
  perform set_config('gridex.public_offer_write','on',true);
  perform set_config('gridex.version_transition','on',true);
  perform set_config('gridex.publication_link_repair','on',true);

  update public.tenant_contract_channels ch
  set status='ended',
      valid_to=coalesce(ch.valid_to,now()),
      updated_by=p_actor_user_id,
      updated_at=now()
  where ch.assignment_id=any(v_assignment_ids) and ch.status<>'ended';

  update public.contract_publications cp
  set status='ended',updated_at=now()
  where cp.id=any(v_publication_ids) and cp.status not in ('ended','archived');

  update public.contract_publication_versions cpv
  set status='ended',valid_to=coalesce(cpv.valid_to,now())
  where cpv.id=any(v_publication_version_ids)
    and cpv.status not in ('ended','archived');

  update public.contract_publication_versions cpv
  set legacy_public_contract_offer_id=null
  where cpv.legacy_public_contract_offer_id=any(v_public_offer_ids);

  -- Diagnostics belong to the removed technical graph. Delete them before the
  -- public offer regardless of historical FK action drift.
  delete from public.contract_lifecycle_backfill_issues i
  where i.company_id=p_company_id and (
    i.contract_offer_id=p_offer_id
    or i.public_contract_offer_id=any(v_public_offer_ids)
  );
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('contract_lifecycle_backfill_issues',v_count);

  perform public.gridex_assert_no_public_offer_fk_references(v_public_offer_ids);

  delete from public.contract_offer_versions cov
  where cov.company_id=p_company_id and cov.contract_offer_id=o.id;
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('contract_offer_versions',v_count);

  delete from public.public_contract_offers pco where pco.id=any(v_public_offer_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('public_contract_offers',v_count);

  delete from public.contract_publication_versions cpv
  where cpv.id=any(v_publication_version_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('contract_publication_versions',v_count);

  delete from public.contract_publications cp where cp.id=any(v_publication_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('contract_publications',v_count);

  delete from public.tenant_contract_channels ch where ch.assignment_id=any(v_assignment_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('tenant_contract_channels',v_count);

  delete from public.tenant_contract_assignments ta where ta.id=any(v_assignment_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('tenant_contract_assignments',v_count);

  delete from public.contract_offers co
  where co.id=o.id and co.company_id=p_company_id;
  get diagnostics v_count=row_count;
  if v_count<>1 then
    raise exception using errcode='55000',message='contract_offer_delete_count_mismatch';
  end if;
  v_counts:=v_counts||jsonb_build_object('contract_offers',v_count);

  delete from public.legal_bundle_version_documents d
  where d.legal_bundle_version_id=any(v_legal_version_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('legal_bundle_version_documents',v_count);

  delete from public.legal_bundle_versions lbv where lbv.id=any(v_legal_version_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('legal_bundle_versions',v_count);

  delete from public.contract_product_versions cpv
  where cpv.id=any(v_product_version_ids);
  get diagnostics v_count=row_count;
  v_counts:=v_counts||jsonb_build_object('contract_product_versions',v_count);

  if v_product_id is not null
     and not exists(
       select 1 from public.contract_product_versions cpv
       where cpv.contract_product_id=v_product_id
     ) then
    delete from public.contract_products cp
    where cp.id=v_product_id and cp.company_id=p_company_id;
    get diagnostics v_count=row_count;
    v_counts:=v_counts||jsonb_build_object('contract_products',v_count);
  end if;

  -- Price versions/books are immutable shared pricing evidence and have many
  -- later consumers (quotes, portfolio, invoices). Contract deletion does not
  -- own their garbage collection.
  insert into public.audit_logs(
    company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata
  ) values(
    p_company_id,p_actor_user_id,'contract_product',coalesce(v_product_id,p_offer_id)::text,
    'contract.delete_unused',to_jsonb(o),null,
    jsonb_build_object('offer_id',p_offer_id,'deleted_rows',v_counts,'preview',v_preview)
  );

  return jsonb_build_object(
    'ok',true,'changed',true,'deleted',true,'mode','deleted',
    'offer_id',p_offer_id,'contract_product_id',v_product_id,
    'deleted_rows',v_counts
  );
end $$;

--
-- Name: FUNCTION gridex_delete_unused_contract(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_delete_unused_contract(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) IS 'Atomically deletes a completely unused exclusive contract graph after locking, shared resolver preview, safe compatibility repair and final dynamic FK assertions.';

--
-- Name: gridex_delete_unused_contract_v2(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_delete_unused_contract_v2(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid, p_expected_preview_token text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_preview jsonb;
  v_result jsonb;
  v_offer_exists boolean:=false;
begin
  perform public.gridex_assert_contract_permission(
    p_actor_user_id,
    'contracts.delete_unused'
  );

  perform pg_advisory_xact_lock(
    hashtextextended(
      'gridex:contract-delete:'||p_company_id::text||':'||p_offer_id::text,
      0
    )
  );

  select true into v_offer_exists
  from public.contract_offers offer
  where offer.id=p_offer_id
    and offer.company_id=p_company_id
  for update;

  if not coalesce(v_offer_exists,false) then
    if exists(
      select 1
      from public.audit_logs audit
      where audit.company_id=p_company_id
        and audit.action='contract.delete_unused'
        and audit.metadata->>'offer_id'=p_offer_id::text
    ) then
      return jsonb_build_object(
        'ok',true,
        'changed',false,
        'deleted',true,
        'mode','deleted',
        'code','contract_already_deleted',
        'offer_id',p_offer_id
      );
    end if;
    return jsonb_build_object(
      'ok',false,
      'changed',false,
      'deleted',false,
      'mode','blocked',
      'code','contract_not_found',
      'recommended_action','none',
      'blockers',jsonb_build_array(jsonb_build_object(
        'resource_type','contract_offer',
        'resource_id',null,
        'count',0,
        'reason','contract_not_found',
        'classification','repairable_broken_relation',
        'recommended_action','none',
        'message','Avtalet hittades inte för valt bolag.'
      ))
    );
  end if;

  v_preview:=public.gridex_contract_delete_dependency_graph_v2(
    p_company_id,
    p_offer_id
  );

  if nullif(p_expected_preview_token,'') is not null
     and p_expected_preview_token is distinct from v_preview->>'preview_token' then
    return jsonb_build_object(
      'ok',false,
      'changed',false,
      'deleted',false,
      'mode','blocked',
      'code','contract_delete_preview_stale',
      'message','Avtalsberoendena ändrades efter förhandsgranskningen. Granska raderingen igen.',
      'recommended_action','refresh_preview',
      'delete_preview',v_preview,
      'blockers',jsonb_build_array(jsonb_build_object(
        'resource_type','contract_product',
        'resource_id',v_preview->>'contract_product_id',
        'count',1,
        'reason','contract_delete_preview_stale',
        'classification','repairable_broken_relation',
        'recommended_action','refresh_preview',
        'message','Avtalsberoendena ändrades efter förhandsgranskningen.'
      ))
    );
  end if;

  if not coalesce((v_preview->>'can_delete')::boolean,false) then
    return jsonb_build_object(
      'ok',false,
      'changed',false,
      'deleted',false,
      'mode','blocked',
      'code','contract_delete_blocked',
      'message','Avtalet har historik eller beroenden som måste bevaras.',
      'reason_codes',coalesce(v_preview->'reason_codes','[]'::jsonb),
      'blockers',coalesce(v_preview->'blockers','[]'::jsonb),
      'recommended_action',coalesce(v_preview->>'recommended_action','archive'),
      'delete_preview',v_preview
    );
  end if;

  -- The existing commit performs the exact same canonical preview again while
  -- the offer row remains locked, and deletes only the approved internal graph.
  v_result:=public.gridex_delete_unused_contract(
    p_company_id,
    p_offer_id,
    p_actor_user_id
  );

  return coalesce(v_result,'{}'::jsonb)||jsonb_build_object(
    'preview_token',v_preview->>'preview_token',
    'delete_preview',v_preview
  );
end
$$;

--
-- Name: FUNCTION gridex_delete_unused_contract_v2(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid, p_expected_preview_token text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_delete_unused_contract_v2(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid, p_expected_preview_token text) IS 'Concurrency-safe, idempotent permanent delete for unused contracts. Repeats the canonical dependency graph under advisory and row locks.';

--
-- Name: gridex_dependency_circuit_before_request_v1(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_dependency_circuit_before_request_v1(p_dependency_key text, p_probe_lease_seconds integer DEFAULT 30) RETURNS TABLE(allowed boolean, circuit_state text, retry_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare v_key text:=lower(btrim(coalesce(p_dependency_key,''))); v_row public.dependency_circuit_state%rowtype;
begin
  if v_key !~ '^[a-z0-9._:-]{2,100}$' or p_probe_lease_seconds<5 or p_probe_lease_seconds>300 then raise exception using errcode='22023',message='dependency_circuit_input_invalid'; end if;
  insert into public.dependency_circuit_state(dependency_key) values(v_key) on conflict(dependency_key) do nothing;
  select * into v_row from public.dependency_circuit_state where dependency_key=v_key for update;
  if v_row.state='closed' then update public.dependency_circuit_state set last_attempt_at=now(),updated_at=now() where dependency_key=v_key; return query select true,'closed'::text,null::timestamptz; return; end if;
  if v_row.state='open' and v_row.half_open_after<=now() then update public.dependency_circuit_state set state='half_open',probe_lease_expires_at=now()+make_interval(secs=>p_probe_lease_seconds),last_attempt_at=now(),updated_at=now() where dependency_key=v_key; return query select true,'half_open'::text,null::timestamptz; return; end if;
  if v_row.state='half_open' and (v_row.probe_lease_expires_at is null or v_row.probe_lease_expires_at<=now()) then update public.dependency_circuit_state set probe_lease_expires_at=now()+make_interval(secs=>p_probe_lease_seconds),last_attempt_at=now(),updated_at=now() where dependency_key=v_key; return query select true,'half_open'::text,null::timestamptz; return; end if;
  return query select false,v_row.state,coalesce(v_row.half_open_after,v_row.probe_lease_expires_at);
end $_$;

--
-- Name: dependency_circuit_state; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.dependency_circuit_state (
    dependency_key text NOT NULL,
    state text DEFAULT 'closed'::text NOT NULL,
    consecutive_failures integer DEFAULT 0 NOT NULL,
    opened_at timestamp with time zone,
    half_open_after timestamp with time zone,
    probe_lease_expires_at timestamp with time zone,
    last_attempt_at timestamp with time zone,
    last_success_at timestamp with time zone,
    last_failure_at timestamp with time zone,
    last_error_code text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dependency_circuit_state_consecutive_failures_check CHECK ((consecutive_failures >= 0)),
    CONSTRAINT dependency_circuit_state_state_check CHECK ((state = ANY (ARRAY['closed'::text, 'open'::text, 'half_open'::text])))
);

--
-- Name: gridex_dependency_circuit_record_v1(text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_dependency_circuit_record_v1(p_dependency_key text, p_outcome text, p_error_code text DEFAULT NULL::text, p_failure_threshold integer DEFAULT 5, p_open_seconds integer DEFAULT 60) RETURNS public.dependency_circuit_state
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare v_key text:=lower(btrim(coalesce(p_dependency_key,''))); v_outcome text:=lower(btrim(coalesce(p_outcome,''))); v_result public.dependency_circuit_state%rowtype;
begin
  if v_key !~ '^[a-z0-9._:-]{2,100}$' or v_outcome not in ('success','failure') or p_failure_threshold<1 or p_failure_threshold>100 or p_open_seconds<5 or p_open_seconds>3600 then raise exception using errcode='22023',message='dependency_circuit_input_invalid'; end if;
  insert into public.dependency_circuit_state(dependency_key) values(v_key) on conflict(dependency_key) do nothing;
  if v_outcome='success' then update public.dependency_circuit_state set state='closed',consecutive_failures=0,opened_at=null,half_open_after=null,probe_lease_expires_at=null,last_success_at=now(),last_attempt_at=now(),last_error_code=null,updated_at=now() where dependency_key=v_key returning * into v_result;
  else update public.dependency_circuit_state set consecutive_failures=consecutive_failures+1,state=case when state='half_open' or consecutive_failures+1>=p_failure_threshold then 'open' else state end,opened_at=case when state='half_open' or consecutive_failures+1>=p_failure_threshold then now() else opened_at end,half_open_after=case when state='half_open' or consecutive_failures+1>=p_failure_threshold then now()+make_interval(secs=>p_open_seconds) else half_open_after end,probe_lease_expires_at=null,last_failure_at=now(),last_attempt_at=now(),last_error_code=nullif(left(btrim(coalesce(p_error_code,'')),100),''),updated_at=now() where dependency_key=v_key returning * into v_result; end if;
  return v_result;
end $_$;

--
-- Name: gridex_dispute_information_complete(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_dispute_information_complete(p_value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select length(btrim(coalesce(p_value->>'authority',''))) >= 3
     and (coalesce(p_value->>'url','') ~* '^https?://' or length(btrim(coalesce(p_value->>'description',''))) >= 20)
$$;

--
-- Name: gridex_ediel_message_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ediel_message_summary(p_company_id uuid DEFAULT NULL::uuid) RETURNS TABLE(total_messages bigint, inbound_messages bigint, outbound_messages bigint, draft_messages bigint, failed_messages bigint, queued_messages bigint, prepared_messages bigint, sent_messages bigint, ack_pending_messages bigint, ack_overdue_messages bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
    select
      count(*) as total_messages,
      count(*) filter (where direction = 'inbound') as inbound_messages,
      count(*) filter (where direction = 'outbound') as outbound_messages,
      count(*) filter (where status = 'draft') as draft_messages,
      count(*) filter (where status = 'failed') as failed_messages,
      count(*) filter (where status = 'queued') as queued_messages,
      count(*) filter (where status = 'prepared') as prepared_messages,
      count(*) filter (where status = 'sent') as sent_messages,
      count(*) filter (
        where contrl_status = 'pending' or aperak_status = 'pending'
      ) as ack_pending_messages,
      count(*) filter (
        where (contrl_status = 'pending' or aperak_status = 'pending')
          and ack_due_at < now()
      ) as ack_overdue_messages
    from public.ediel_messages
    where p_company_id is null or company_id = p_company_id
  $$;

--
-- Name: gridex_edifact_cci_cav_value(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_edifact_cci_cav_value(p_raw text, p_cci_code text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_match text[];
  v_value text;
begin
  if coalesce(p_raw, '') = '' or coalesce(p_cci_code, '') = '' then return null; end if;
  v_match := regexp_match(
    p_raw,
    'CCI\\+\\+' || regexp_replace(p_cci_code, '([^a-zA-Z0-9])', '\\\1', 'g') || '[^'']*''[[:space:]]*CAV\\+([^+''\\r\\n]+)'
  );
  v_value := nullif(btrim(v_match[1]), '');
  if v_value is null then return null; end if;
  return nullif(btrim(regexp_replace(v_value, '^.*:', '')), '');
exception when others then return null;
end;
$$;

--
-- Name: gridex_edifact_first_lin_item_id(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_edifact_first_lin_item_id(p_raw text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $$
declare
  v_match text[];
begin
  if coalesce(p_raw, '') = '' then return null; end if;
  v_match := regexp_match(p_raw, 'LIN\+[^'']*\+\+([^:+''\r\n]+)');
  return nullif(btrim(v_match[1]), '');
exception when others then
  return null;
end;
$$;

--
-- Name: gridex_edifact_nad_element(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_edifact_nad_element(p_raw text, p_qualifier text, p_element_index integer) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_match text[];
  v_parts text[];
  v_segment text;
begin
  if coalesce(p_raw, '') = '' or coalesce(p_qualifier, '') = '' or p_element_index < 0 then return null; end if;
  v_match := regexp_match(
    p_raw,
    'NAD\\+' || regexp_replace(p_qualifier, '([^a-zA-Z0-9])', '\\\1', 'g') || '\\+([^''\\r\\n]+)'
  );
  v_segment := 'NAD+' || p_qualifier || '+' || coalesce(v_match[1], '');
  v_parts := string_to_array(v_segment, '+');
  return nullif(btrim(v_parts[p_element_index + 1]), '');
exception when others then return null;
end;
$$;

--
-- Name: gridex_edifact_rff_value(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_edifact_rff_value(p_raw text, p_qualifier text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $_$
declare
  v_match text[];
  v_qualifier text;
begin
  v_qualifier := upper(btrim(coalesce(p_qualifier, '')));
  if coalesce(p_raw, '') = ''
     or v_qualifier = ''
     or v_qualifier !~ '^[A-Z0-9]{1,8}$' then
    return null;
  end if;

  v_match := regexp_match(
    p_raw,
    'RFF\+' || v_qualifier || ':([^+''\r\n]+)'
  );
  return nullif(btrim(v_match[1]), '');
exception when others then
  return null;
end;
$_$;

--
-- Name: FUNCTION gridex_edifact_rff_value(p_raw text, p_qualifier text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_edifact_rff_value(p_raw text, p_qualifier text) IS 'Extracts one typed EDIFACT RFF reference value. Qualifier is restricted to alphanumeric Ediel qualifiers; returns NULL on malformed input.';

--
-- Name: gridex_end_contract_channel(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_end_contract_channel(p_company_id uuid, p_offer_id uuid, p_channel text, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_channel text := lower(coalesce(p_channel, ''));
  v_offer public.contract_offers%rowtype;
  v_assignment_id uuid;
  v_unpublish jsonb;
  v_channels bigint := 0;
  v_publications bigint := 0;
  v_public_offers bigint := 0;
begin
  if v_channel not in ('internal','website','api','partner','phone') then
    raise exception using
      errcode = '22023',
      message = 'invalid_contract_channel';
  end if;

  -- The canonical pause command performs permission checking, locks the graph
  -- and closes published immutable publication versions first.
  v_unpublish := public.gridex_unpublish_contract_channel(
    p_company_id, p_offer_id, v_channel, p_actor_user_id
  );
  if not coalesce((v_unpublish->>'ok')::boolean, false) then
    return v_unpublish;
  end if;

  select * into v_offer
  from public.contract_offers offer
  where offer.id = p_offer_id
    and offer.company_id = p_company_id
  for update;
  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'contract_offer_not_found';
  end if;

  select assignment.id into v_assignment_id
  from public.tenant_contract_assignments assignment
  where assignment.company_id = p_company_id
    and assignment.contract_product_version_id
      = v_offer.contract_product_version_id
  for update;
  if v_assignment_id is null then
    raise exception using
      errcode = 'P0002',
      message = 'contract_assignment_not_found';
  end if;

  update public.tenant_contract_channels channel
  set status = 'ended',
      valid_to = coalesce(channel.valid_to, now()),
      updated_by = p_actor_user_id,
      updated_at = now()
  where channel.assignment_id = v_assignment_id
    and channel.channel = v_channel
    and channel.status <> 'ended';
  get diagnostics v_channels = row_count;

  update public.contract_publications publication
  set status = 'ended',
      updated_at = now()
  where publication.assignment_id = v_assignment_id
    and publication.channel = v_channel
    and publication.status not in ('ended', 'archived');
  get diagnostics v_publications = row_count;

  if v_channel = 'website' then
    perform set_config('gridex.public_offer_write', 'on', true);
    update public.public_contract_offers public_offer
    set lifecycle_status = 'closed',
        publication_status = 'unpublished',
        is_public = false,
        website_enabled = false,
        website_cta_enabled = false,
        closed_at = coalesce(public_offer.closed_at, now()),
        closed_by = coalesce(public_offer.closed_by, p_actor_user_id),
        close_reason = coalesce(
          nullif(public_offer.close_reason, ''),
          'contract_channel_ended'
        ),
        updated_by = p_actor_user_id,
        updated_at = now()
    where public_offer.company_id = p_company_id
      and public_offer.source_contract_offer_id = p_offer_id
      and public_offer.lifecycle_status <> 'closed';
    get diagnostics v_public_offers = row_count;
  end if;

  if not exists (
    select 1
    from public.tenant_contract_channels channel
    join public.tenant_contract_assignments assignment
      on assignment.id = channel.assignment_id
    where assignment.company_id = p_company_id
      and assignment.contract_product_version_id
        = v_offer.contract_product_version_id
      and channel.status = 'active'
  ) then
    update public.contract_offers offer
    set lifecycle_status = 'closed',
        status = 'inactive',
        is_active = false,
        closed_at = coalesce(offer.closed_at, now()),
        closed_by = coalesce(offer.closed_by, p_actor_user_id),
        close_reason = coalesce(
          nullif(offer.close_reason, ''),
          'all_contract_channels_ended'
        ),
        updated_by = p_actor_user_id,
        updated_at = now()
    where offer.id = p_offer_id
      and offer.company_id = p_company_id;
  end if;

  insert into public.audit_logs(
    company_id, actor_user_id, entity_type, entity_id, action, metadata
  ) values (
    p_company_id,
    p_actor_user_id,
    'contract_product_version',
    v_offer.contract_product_version_id::text,
    'contract.channel.ended',
    jsonb_build_object(
      'offer_id', p_offer_id,
      'channel', v_channel,
      'affected_channels', v_channels,
      'affected_publications', v_publications,
      'affected_public_offers', v_public_offers
    )
  );

  return jsonb_build_object(
    'ok', true,
    'changed', (v_channels + v_publications + v_public_offers) > 0,
    'mode', 'ended',
    'offer_id', p_offer_id,
    'channel', v_channel,
    'resulting_status', 'ended',
    'affected_channels', v_channels,
    'affected_publications', v_publications,
    'affected_public_offers', v_public_offers
  );
end
$$;

--
-- Name: FUNCTION gridex_end_contract_channel(p_company_id uuid, p_offer_id uuid, p_channel text, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_end_contract_channel(p_company_id uuid, p_offer_id uuid, p_channel text, p_actor_user_id uuid) IS 'Canonical terminal channel command. Distinct from pause/unpublish and preserves immutable signed history.';

--
-- Name: gridex_enforce_billing_underlay_price_area(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_enforce_billing_underlay_price_area() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_contract_id uuid := coalesce(new.contract_id, new.customer_contract_id);
  v_contract_snapshot_id uuid;
  v_contract_area text;
  v_snapshot_area text;
  v_legacy_snapshot_area text;
  v_metadata_area text;
  v_canonical_area text;
begin
  if v_contract_id is null then
    return new;
  end if;

  select
    c.contract_price_snapshot_id,
    upper(nullif(btrim(c.price_area_used), '')),
    upper(nullif(btrim(c.price_snapshot #>> '{snapshot_json,price_area}'), '')),
    upper(nullif(btrim(c.metadata ->> 'selected_price_area'), ''))
  into
    v_contract_snapshot_id,
    v_contract_area,
    v_legacy_snapshot_area,
    v_metadata_area
  from public.customer_contracts c
  where c.id = v_contract_id
    and c.company_id = new.company_id;

  if not found then
    return new;
  end if;

  select upper(nullif(btrim(s.snapshot_json ->> 'price_area'), ''))
  into v_snapshot_area
  from public.contract_price_snapshots s
  where s.id = coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id)
    and s.contract_id = v_contract_id
    and s.company_id = new.company_id;

  v_canonical_area := coalesce(
    case when v_snapshot_area in ('SE1','SE2','SE3','SE4') then v_snapshot_area end,
    case when v_contract_area in ('SE1','SE2','SE3','SE4') then v_contract_area end,
    case when v_legacy_snapshot_area in ('SE1','SE2','SE3','SE4') then v_legacy_snapshot_area end,
    case when v_metadata_area in ('SE1','SE2','SE3','SE4') then v_metadata_area end
  );

  if coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id) is not null
     and v_canonical_area is null then
    raise exception 'billing_contract_price_area_missing'
      using errcode = '23514',
            detail = jsonb_build_object(
              'billing_underlay_id', new.id,
              'contract_id', v_contract_id,
              'contract_price_snapshot_id', coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id)
            )::text;
  end if;

  if v_canonical_area is null then
    return new;
  end if;

  if new.price_area is null or nullif(btrim(new.price_area), '') is null then
    new.price_area := v_canonical_area;
  elsif upper(btrim(new.price_area)) <> v_canonical_area then
    raise exception 'billing_underlay_price_area_mismatch'
      using errcode = '23514',
            detail = jsonb_build_object(
              'billing_underlay_id', new.id,
              'contract_id', v_contract_id,
              'submitted_price_area', upper(btrim(new.price_area)),
              'canonical_price_area', v_canonical_area,
              'contract_price_snapshot_id', coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id)
            )::text;
  else
    new.price_area := v_canonical_area;
  end if;

  return new;
end;
$$;

--
-- Name: FUNCTION gridex_enforce_billing_underlay_price_area(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_enforce_billing_underlay_price_area() IS 'Locks billing_underlays.price_area to the immutable contract_price_snapshots/customer_contracts price-area evidence.';

--
-- Name: gridex_enforce_commercial_publication(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_enforce_commercial_publication() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_readiness jsonb;
begin
  if new.lifecycle_status in ('published','paused')
    and (
      tg_op='INSERT'
      or old.lifecycle_status is distinct from new.lifecycle_status
    ) then
    v_readiness:=public.gridex_validate_commercial_model_v1(
      new.company_id,new.contract_product_version_id
    );
    if not coalesce((v_readiness->>'ready')::boolean,false) then
      raise exception using
        errcode='23514',
        message='commercial_model_not_ready',
        detail=v_readiness::text;
    end if;
  end if;
  return new;
end
$$;

--
-- Name: gridex_enforce_contract_availability_and_capacity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_enforce_contract_availability_and_capacity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  v_count bigint;
  v_statuses text[]:=array['draft','pending_signature','signed','active'];
begin
  if new.status not in ('draft','pending_signature','signed','active') then
    return new;
  end if;
  if new.contract_offer_id is null and new.contract_product_id is null and new.contract_product_version_id is null then
    return new;
  end if;

  select * into o
  from public.contract_offers
  where company_id=new.company_id and (
    id=new.contract_offer_id
    or (new.contract_product_version_id is not null and contract_product_version_id=new.contract_product_version_id)
    or (new.contract_product_id is not null and contract_product_id=new.contract_product_id and lifecycle_status='published')
  )
  order by version_number desc limit 1 for update;
  if not found then
    raise exception using errcode='23514',message='contract_offer_not_available';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(o.version_series_id::text,0));
  if o.lifecycle_status<>'published' or not o.is_active
     or (o.valid_from is not null and o.valid_from>current_date)
     or (o.valid_to is not null and o.valid_to<current_date) then
    raise exception using errcode='23514',message='contract_offer_not_available';
  end if;
  if not exists(
    select 1 from public.tenant_contract_assignments ta
    join public.tenant_contract_channels ch on ch.assignment_id=ta.id
    where ta.company_id=new.company_id
      and ta.contract_product_version_id=o.contract_product_version_id
      and ta.status='active'
      and ch.channel in ('internal','website','api','partner','phone') and ch.status='active'
      and (
        (ch.channel='internal' and ta.internal_sales_allowed)
        or (ch.channel='website' and ta.website_publication_allowed)
        or ch.channel in ('api','partner','phone')
      )
      and (ch.valid_from is null or ch.valid_from<=now())
      and (ch.valid_to is null or ch.valid_to>=now())
  ) then
    raise exception using errcode='23514',message='contract_channel_not_available';
  end if;

  if o.max_customers is not null then
    select count(*) into v_count
    from public.customer_contracts c
    where c.company_id=new.company_id and c.id is distinct from new.id
      and c.status=any(v_statuses) and (
        c.contract_offer_id=o.id
        or c.contract_product_id=o.contract_product_id
        or c.contract_product_version_id=o.contract_product_version_id
      );
    if v_count>=o.max_customers then
      raise exception using errcode='23514',message='contract_capacity_reached';
    end if;
  end if;
  return new;
end $$;

--
-- Name: gridex_enforce_contract_price_snapshot_hash_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_enforce_contract_price_snapshot_hash_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_expected_hash text;
begin
  if new.snapshot_json is null then
    raise exception using
      errcode = '23502',
      message = 'contract_price_snapshot_json_required';
  end if;

  v_expected_hash := encode(
    extensions.digest(convert_to(new.snapshot_json::text, 'UTF8'), 'sha256'),
    'hex'
  );

  if nullif(btrim(coalesce(new.snapshot_hash, '')), '') is not null
     and lower(btrim(new.snapshot_hash)) is distinct from v_expected_hash then
    raise exception using
      errcode = '23514',
      message = 'contract_price_snapshot_hash_mismatch';
  end if;

  new.snapshot_hash := v_expected_hash;
  return new;
end;
$$;

--
-- Name: FUNCTION gridex_enforce_contract_price_snapshot_hash_v1(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_enforce_contract_price_snapshot_hash_v1() IS 'Central contract-price snapshot integrity boundary: computes canonical SHA-256 after normalization and rejects caller-provided mismatches.';

--
-- Name: gridex_enforce_customer_contract_chain_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_enforce_customer_contract_chain_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row jsonb:=to_jsonb(new);
  v_company_id uuid:=nullif(v_row->>'company_id','')::uuid;
  v_customer_id uuid:=nullif(v_row->>'customer_id','')::uuid;
  v_contract_id uuid:=coalesce(
    nullif(v_row->>'customer_contract_id','')::uuid,
    nullif(v_row->>'contract_id','')::uuid
  );
  v_metering_point_id uuid:=nullif(v_row->>'metering_point_id','')::uuid;
  v_underlay_id uuid:=nullif(v_row->>'billing_underlay_id','')::uuid;
  v_export_item_id uuid:=coalesce(
    nullif(v_row->>'invoice_export_item_id','')::uuid,
    nullif(v_row->>'canonical_export_item_id','')::uuid
  );
begin
  if v_company_id is null or v_customer_id is null then
    raise exception using errcode='23502',message='customer_chain_company_customer_required';
  end if;
  if v_contract_id is not null and not exists(
    select 1 from public.customer_contracts cc
    where cc.id=v_contract_id
      and cc.company_id=v_company_id
      and cc.customer_id=v_customer_id
  ) then
    raise exception using errcode='23514',message='customer_chain_contract_mismatch';
  end if;
  if v_metering_point_id is not null and not exists(
    select 1 from public.metering_points mp
    where mp.id=v_metering_point_id
      and mp.company_id=v_company_id
      and mp.customer_id=v_customer_id
  ) then
    raise exception using errcode='23514',message='customer_chain_metering_point_mismatch';
  end if;
  if v_underlay_id is not null and not exists(
    select 1 from public.billing_underlays bu
    where bu.id=v_underlay_id
      and bu.company_id=v_company_id
      and bu.customer_id=v_customer_id
      and (
        v_contract_id is null
        or coalesce(bu.customer_contract_id,bu.contract_id)=v_contract_id
      )
  ) then
    raise exception using errcode='23514',message='customer_chain_underlay_mismatch';
  end if;
  if v_export_item_id is not null and not exists(
    select 1 from public.invoice_export_items iei
    where iei.id=v_export_item_id
      and iei.company_id=v_company_id
      and iei.customer_id=v_customer_id
      and (
        v_contract_id is null
        or iei.customer_contract_id=v_contract_id
      )
  ) then
    raise exception using errcode='23514',message='customer_chain_export_item_mismatch';
  end if;
  return new;
end
$$;

--
-- Name: gridex_enforce_customer_contract_state_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_enforce_customer_contract_state_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_allowed boolean := false;
begin
  if tg_op = 'INSERT' then
    if new.status in ('signed', 'active')
       and (
         new.signed_at is null
         or new.locked_at is null
         or nullif(new.signature_snapshot_sha256, '') is null
         or new.contract_product_version_id is null
         or new.contract_publication_version_id is null
         or new.legal_bundle_version_id is null
         or new.contract_price_snapshot_id is null
       ) then
      raise exception using
        errcode = '23514',
        message = 'customer_contract_signed_insert_requires_import_command';
    end if;
    return new;
  end if;

  if new.status is not distinct from old.status then
    return new;
  end if;

  v_allowed := case old.status
    when 'draft' then new.status in ('pending_signature', 'cancelled')
    when 'pending_signature' then
      new.status in ('signature_failed', 'signed', 'cancelled')
    when 'signature_failed' then
      new.status in ('pending_signature', 'cancelled')
    when 'signed' then new.status in ('active', 'terminated', 'cancelled')
    when 'active' then new.status in ('terminated', 'cancelled', 'expired')
    else false
  end;
  if not v_allowed then
    raise exception using
      errcode = '23514',
      message = format(
        'customer_contract_transition_not_allowed:%s:%s',
        old.status,
        new.status
      );
  end if;

  if new.status = 'signed'
     and (
       new.signed_at is null
       or new.locked_at is null
       or nullif(new.signature_snapshot_sha256, '') is null
       or jsonb_typeof(coalesce(new.signature_snapshot, 'null'::jsonb))
         <> 'object'
       or new.signature_snapshot = '{}'::jsonb
       or new.contract_product_version_id is null
       or new.contract_publication_version_id is null
       or new.legal_bundle_version_id is null
       or new.contract_price_snapshot_id is null
     ) then
    raise exception using
      errcode = '23514',
      message = 'customer_contract_signature_evidence_incomplete';
  end if;

  if new.status = 'active'
     and (
       old.status <> 'signed'
       or new.signed_at is null
       or nullif(new.signature_snapshot_sha256, '') is null
       or new.actual_start_date is null
       or new.billing_eligible_at is null
       or new.lifecycle_stage <> 'active'
       or coalesce(new.billing_eligibility_source, '')
          <> 'activate_customer_supply_v1'
     ) then
    raise exception using
      errcode = '23514',
      message = 'customer_contract_activation_requires_supply_graph';
  end if;
  if new.status in ('terminated', 'cancelled', 'expired')
     and (
       new.ended_at is null
       or nullif(new.status_reason_code, '') is null
     ) then
    raise exception using
      errcode = '23514',
      message = 'customer_contract_terminal_evidence_required';
  end if;

  return new;
end
$$;

--
-- Name: gridex_enforce_quote_binding_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_enforce_quote_binding_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row jsonb:=to_jsonb(new);
  v_quote public.website_contract_quotes%rowtype;
  v_quote_reference text:=nullif(v_row->>'quote_reference','');
  v_version_id uuid:=nullif(v_row->>'contract_product_version_id','')::uuid;
begin
  if v_quote_reference is null then return new; end if;
  select * into v_quote
  from public.website_contract_quotes q
  where q.company_id=nullif(v_row->>'company_id','')::uuid
    and q.quote_reference=v_quote_reference;
  if not found then
    raise exception using errcode='23503',message='quote_binding_not_found_for_tenant';
  end if;
  if v_version_id is not null
     and v_quote.contract_product_version_id is distinct from v_version_id then
    raise exception using errcode='23514',message='quote_binding_contract_version_mismatch';
  end if;
  return new;
end
$$;

--
-- Name: gridex_enforce_quote_binding_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_enforce_quote_binding_v2() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_row jsonb:=to_jsonb(new);
  v_quote public.website_contract_quotes%rowtype;
  v_company_id uuid:=nullif(v_row->>'company_id','')::uuid;
  v_quote_reference text:=nullif(v_row->>'quote_reference','');
  v_text text;
begin
  if v_quote_reference is null then return new; end if;

  select * into v_quote
  from public.website_contract_quotes q
  where q.company_id=v_company_id
    and q.quote_reference=v_quote_reference;
  if not found then
    raise exception using errcode='23503',message='quote_binding_not_found_for_tenant';
  end if;

  foreach v_text in array array[
    nullif(v_row->>'contract_product_id',''),
    nullif(v_row->>'contract_product_version_id',''),
    nullif(v_row->>'contract_publication_version_id',''),
    nullif(v_row->>'price_plan_id',''),
    nullif(v_row->>'price_plan_version_id',''),
    nullif(v_row->>'price_book_id',''),
    nullif(v_row->>'legal_bundle_version_id',''),
    nullif(v_row->>'energy_direction','')
  ] loop
    if v_text is null then
      raise exception using errcode='23502',message='quote_binding_target_identity_incomplete';
    end if;
  end loop;

  if v_quote.contract_product_id is distinct from (v_row->>'contract_product_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_contract_product_mismatch';
  end if;
  if v_quote.contract_product_version_id is distinct from (v_row->>'contract_product_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_contract_version_mismatch';
  end if;
  if v_quote.contract_publication_version_id is distinct from (v_row->>'contract_publication_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_publication_version_mismatch';
  end if;
  if v_quote.price_plan_id is distinct from (v_row->>'price_plan_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_price_plan_mismatch';
  end if;
  if v_quote.price_plan_version_id is distinct from (v_row->>'price_plan_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_price_plan_version_mismatch';
  end if;
  if v_quote.price_book_id is distinct from (v_row->>'price_book_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_price_book_mismatch';
  end if;
  if v_quote.legal_bundle_version_id is distinct from (v_row->>'legal_bundle_version_id')::uuid then
    raise exception using errcode='23514',message='quote_binding_legal_bundle_mismatch';
  end if;
  if v_quote.energy_direction is distinct from (v_row->>'energy_direction') then
    raise exception using errcode='23514',message='quote_binding_energy_direction_mismatch';
  end if;

  return new;
end
$$;

--
-- Name: FUNCTION gridex_enforce_quote_binding_v2(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_enforce_quote_binding_v2() IS 'Tenant-scoped immutable binding guard for quote -> application -> customer contract, including energy direction and pricing identities.';

--
-- Name: gridex_enforce_quote_canonical_identity_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_enforce_quote_canonical_identity_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_publication public.contract_publication_versions%rowtype;
  v_product_version public.contract_product_versions%rowtype;
  v_product_company_id uuid;
  v_publication_company_id uuid;
  v_price_plan_company_id uuid;
  v_price_book_company_id uuid;
  v_legal_company_id uuid;
begin
  if new.contract_product_id is null
     or new.contract_product_version_id is null
     or new.contract_publication_version_id is null
     or new.price_plan_id is null
     or new.price_plan_version_id is null
     or new.price_book_id is null
     or new.legal_bundle_version_id is null
     or new.energy_direction is null then
    raise exception using errcode='23502',message='quote_canonical_identity_incomplete';
  end if;

  select * into v_publication
  from public.contract_publication_versions
  where id=new.contract_publication_version_id;
  if not found then
    raise exception using errcode='23503',message='quote_publication_version_not_found';
  end if;

  select * into v_product_version
  from public.contract_product_versions
  where id=new.contract_product_version_id;
  if not found then
    raise exception using errcode='23503',message='quote_product_version_not_found';
  end if;

  select company_id into v_product_company_id
  from public.contract_products
  where id=new.contract_product_id;
  if v_product_company_id is not null and v_product_company_id is distinct from new.company_id then
    raise exception using errcode='23514',message='quote_contract_product_tenant_mismatch';
  end if;

  select assignment.company_id into v_publication_company_id
  from public.contract_publications publication
  join public.tenant_contract_assignments assignment
    on assignment.id=publication.assignment_id
  where publication.id=v_publication.contract_publication_id;
  if v_publication_company_id is distinct from new.company_id then
    raise exception using errcode='23514',message='quote_publication_tenant_mismatch';
  end if;

  select company_id into v_price_plan_company_id
  from public.price_plans
  where id=new.price_plan_id;
  if v_price_plan_company_id is distinct from new.company_id then
    raise exception using errcode='23514',message='quote_price_plan_tenant_mismatch';
  end if;

  select company_id into v_price_book_company_id
  from public.price_books
  where id=new.price_book_id;
  if v_price_book_company_id is distinct from new.company_id then
    raise exception using errcode='23514',message='quote_price_book_tenant_mismatch';
  end if;

  select company_id into v_legal_company_id
  from public.legal_bundle_versions
  where id=new.legal_bundle_version_id;
  if v_legal_company_id is distinct from new.company_id then
    raise exception using errcode='23514',message='quote_legal_bundle_tenant_mismatch';
  end if;

  if v_product_version.contract_product_id is distinct from new.contract_product_id
     or v_publication.contract_product_version_id is distinct from new.contract_product_version_id
     or v_publication.price_plan_id is distinct from new.price_plan_id
     or v_publication.price_plan_version_id is distinct from new.price_plan_version_id
     or v_publication.price_book_id is distinct from new.price_book_id
     or v_publication.legal_bundle_version_id is distinct from new.legal_bundle_version_id
     or v_publication.offer_reference is distinct from new.offer_reference
     or v_publication.customer_type not in (new.customer_type,'both')
     or v_product_version.energy_direction is distinct from new.energy_direction
     or v_publication.energy_direction is distinct from new.energy_direction then
    raise exception using errcode='23514',message='quote_canonical_identity_mismatch';
  end if;

  return new;
end
$$;

--
-- Name: FUNCTION gridex_enforce_quote_canonical_identity_v1(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_enforce_quote_canonical_identity_v1() IS 'Rejects quotes without the exact product, publication, price and legal identities or with cross-tenant/mismatched graph references.';

--
-- Name: gridex_enforce_spot_price_month_server_aggregate_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_enforce_spot_price_month_server_aggregate_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_calc record;
begin
  if tg_op='UPDATE' then
    if old.status='locked' then
      return new;
    end if;

    -- Locking/annotation-only updates must be persisted verbatim.
    if (to_jsonb(new) - array['status','locked_at','locked_by','lock_reason','updated_at'])
       = (to_jsonb(old) - array['status','locked_at','locked_by','lock_reason','updated_at'])
       and (
         new.status is distinct from old.status
         or new.locked_at is distinct from old.locked_at
         or new.locked_by is distinct from old.locked_by
         or new.lock_reason is distinct from old.lock_reason
       ) then
      return new;
    end if;
  end if;

  -- Canonicalize aggregate fields in NEW instead of replacing/cancelling the row operation.
  select * into strict v_calc
  from private.gridex_calculate_spot_price_month_v1(new.source,new.price_area,new.billing_month);

  new.period_start := v_calc.period_start;
  new.period_end := v_calc.period_end;
  new.average_sek_per_kwh := v_calc.average_sek_per_kwh;
  new.min_sek_per_kwh := v_calc.min_sek_per_kwh;
  new.max_sek_per_kwh := v_calc.max_sek_per_kwh;
  new.interval_count := v_calc.interval_count;
  new.expected_interval_count := v_calc.expected_interval_count;
  new.covered_duration_minutes := v_calc.covered_duration_minutes;
  new.expected_duration_minutes := v_calc.expected_duration_minutes;
  new.quality_issues := v_calc.quality_issues;
  new.provider_fetched_at := v_calc.provider_fetched_at;
  new.verified_at := v_calc.verified_at;
  new.status := v_calc.status;
  new.source_checksum := v_calc.source_checksum;
  new.updated_at := v_calc.updated_at;

  return new;
end
$$;

--
-- Name: gridex_enforce_supplier_switch_z04_confirmation_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_enforce_supplier_switch_z04_confirmation_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  effective_start_date date;
  stockholm_market_date date := (now() at time zone 'Europe/Stockholm')::date;
begin
  if new.status = 'confirmed' then
    if new.inbound_z04_message_id is null then
      raise exception using
        errcode = '23514',
        message = 'supplier_switch_confirmed_requires_inbound_z04',
        detail = 'Legacy confirmed state may only be normalized when a correlated inbound PRODAT Z04 is linked.';
    end if;
    new.status := 'accepted';
  end if;

  if new.status = 'accepted' and new.inbound_z04_message_id is null then
    new.status := 'submitted';
    if new.submitted_at is null then new.submitted_at := now(); end if;
    new.completed_at := null;
  end if;

  if new.inbound_z04_message_id is not null and not exists (
    select 1
    from public.ediel_messages m
    where m.id = new.inbound_z04_message_id
      and m.company_id = new.company_id
      and m.direction = 'inbound'
      and upper(m.message_family) = 'PRODAT'
      and upper(coalesce(m.message_code,'')) = 'Z04'
  ) then
    raise exception using
      errcode = '23514',
      message = 'supplier_switch_inbound_z04_reference_invalid',
      detail = 'inbound_z04_message_id must reference an inbound PRODAT Z04 in the same tenant.';
  end if;

  if new.status = 'completed' then
    if new.inbound_z04_message_id is null then
      raise exception using
        errcode = '23514',
        message = 'supplier_switch_business_confirmation_requires_inbound_z04',
        detail = 'A supplier switch cannot be completed before a correlated inbound PRODAT Z04 has confirmed the market change.';
    end if;

    if tg_op = 'UPDATE' and old.status not in ('accepted','completed') then
      raise exception using
        errcode = '23514',
        message = 'supplier_switch_completion_requires_accepted_state',
        detail = 'Completion must follow the accepted state established by inbound PRODAT Z04.';
    end if;

    effective_start_date := coalesce(new.confirmed_start_date, new.requested_start_date)::date;
    if effective_start_date is null then
      raise exception using
        errcode = '23514',
        message = 'supplier_switch_effective_start_date_required',
        detail = 'A supplier switch cannot be completed without a confirmed or requested effective start date.';
    end if;

    if effective_start_date > stockholm_market_date then
      raise exception using
        errcode = '23514',
        message = 'supplier_switch_effective_date_not_reached',
        detail = format('Effective start date %s has not been reached in Europe/Stockholm (market date %s).', effective_start_date, stockholm_market_date);
    end if;
  end if;

  return new;
end;
$$;

--
-- Name: FUNCTION gridex_enforce_supplier_switch_z04_confirmation_v1(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_enforce_supplier_switch_z04_confirmation_v1() IS 'PRODAT 26.A invariant: ACK remains submitted; accepted requires inbound Z04; completed requires prior accepted state and reached effective date in Europe/Stockholm.';

--
-- Name: gridex_enforce_supplier_utilts_outbound_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_enforce_supplier_utilts_outbound_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_code text;
  v_requested text;
  v_resolution text;
  v_expected_appref text;
  v_capability_count integer;
  v_operational boolean;
begin
  if new.direction <> 'outbound' or upper(coalesce(new.message_family,'')) <> 'UTILTS' then
    return new;
  end if;

  -- Never reinterpret/mutate already-sent historical market payloads.
  if tg_op = 'UPDATE' and old.status in ('sent','acknowledged','received','validated') then
    return new;
  end if;

  v_code := upper(coalesce(new.message_code,''));
  v_operational := new.grid_owner_data_request_id is not null
    or lower(coalesce(new.process_type,'')) = 'meter_values_request';

  if not v_operational then
    return new;
  end if;

  if v_code = 'E66' then
    raise exception 'utilts_e66_supplier_outbound_not_allowed';
  end if;

  if v_code <> 'E73' then
    raise exception 'utilts_supplier_operational_outbound_not_allowed:%', v_code;
  end if;

  v_requested := upper(coalesce(
    new.parsed_payload->>'requestedMessageCode',
    new.parsed_payload->>'requested_message_code',
    ''
  ));
  if v_requested not in ('S02','E66') then
    raise exception 'utilts_e73_requested_message_required';
  end if;

  if coalesce((new.parsed_payload->>'bilateralCapabilityVerified')::boolean,false) is not true then
    raise exception 'utilts_e73_bilateral_capability_required';
  end if;
  if new.company_id is null then
    raise exception 'utilts_e73_company_required';
  end if;

  select count(*) into v_capability_count
  from public.tenant_message_capabilities c
  where c.company_id = new.company_id
    and c.environment = new.environment
    and upper(c.message_family) = 'UTILTS'
    and upper(c.message_code) = 'E73'
    and lower(c.direction) = 'outbound'
    and c.is_enabled = true
    and c.bilateral = true
    and (c.valid_from is null or c.valid_from <= now())
    and (c.valid_to is null or c.valid_to > now());

  if v_capability_count <> 1 then
    raise exception 'utilts_e73_bilateral_capability_invalid:%', v_capability_count;
  end if;

  v_resolution := upper(coalesce(
    new.parsed_payload->>'resolution',
    new.parsed_payload->>'readingFrequency',
    ''
  ));
  if v_requested = 'S02' then
    v_expected_appref := '23-DDQ-S02-S';
  elsif v_resolution in ('15','PT15M','QUARTER_HOUR','QUARTER-HOURLY','QUARTER_HOURLY','KVART') then
    v_expected_appref := '23-DDQ-E66-T';
  else
    v_expected_appref := '23-DDQ-E66-S';
  end if;

  if upper(coalesce(new.application_reference,'')) = '23-DDQ-UTILTS' then
    raise exception 'utilts_generic_application_reference_forbidden';
  end if;
  if upper(coalesce(new.application_reference,'')) <> v_expected_appref then
    raise exception 'utilts_e73_application_reference_mismatch:expected=% actual=%', v_expected_appref, coalesce(new.application_reference,'');
  end if;

  return new;
end;
$$;

--
-- Name: gridex_enqueue_signed_contract_operation_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_enqueue_signed_contract_operation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_candidate_site_id uuid := coalesce(new.customer_site_id, new.site_id);
  v_site_id uuid;
  v_site_address_hash text;
  v_site_grid_owner_id uuid;
  v_site_grid_area_code text;
  v_site_facility_id text;
  v_site_snapshot jsonb;
  v_operation_id uuid := gen_random_uuid();
  v_trace_id uuid := gen_random_uuid();
  v_job_id uuid;
  v_review_reason text;
begin
  -- Only the edge into a fully signed contract may enqueue lifecycle work.
  if new.status is distinct from 'signed' or new.signed_at is null then
    return new;
  end if;

  if tg_op = 'UPDATE' and old.status = 'signed' and old.signed_at is not null then
    return new;
  end if;

  -- Never trust a relational site ID until it resolves inside exact tenant and
  -- customer scope. The candidate is retained only as diagnostic evidence.
  if v_candidate_site_id is not null then
    select
      s.id,
      coalesce(
        nullif(trim(s.address_hash), ''),
        nullif(
          lower(concat_ws(
            '|',
            nullif(trim(s.street), ''),
            nullif(regexp_replace(coalesce(s.postal_code, ''), '\D', '', 'g'), ''),
            nullif(trim(s.city), '')
          )),
          ''
        ),
        'missing'
      ),
      s.grid_owner_id,
      s.grid_area_code,
      s.facility_id
    into
      v_site_id,
      v_site_address_hash,
      v_site_grid_owner_id,
      v_site_grid_area_code,
      v_site_facility_id
    from public.customer_sites s
    where s.id = v_candidate_site_id
      and s.company_id = new.company_id
      and s.customer_id = new.customer_id;
  end if;

  -- Production agreements have a different lifecycle and must never enter the
  -- consumption Z03 path merely because they were signed.
  if coalesce(new.energy_direction, 'consumption') <> 'consumption' then
    insert into public.customer_operation_events (
      company_id, customer_id, customer_site_id, metering_point_id,
      operation_id, event_code, title, message, status, severity,
      action_required, source, visibility, payload, idempotency_key
    ) values (
      new.company_id, new.customer_id, v_site_id, new.metering_point_id,
      v_operation_id, 'contract.signed.lifecycle_skipped',
      'Signerat avtal kräver ingen consumption supplier-switch',
      'Avtalets energiriktning hanteras av en annan domänprocess och har inte köats för Z03.',
      'completed', 'info', false, 'contract_lifecycle_orchestrator', 'tenant',
      jsonb_build_object(
        'contract_id', new.id,
        'candidate_site_id', v_candidate_site_id,
        'energy_direction', new.energy_direction,
        'operation_id', v_operation_id,
        'trace_id', v_trace_id
      ),
      'contract-signed-skipped:' || new.id::text
    )
    on conflict (company_id, idempotency_key)
      where idempotency_key is not null do nothing;
    return new;
  end if;

  if v_site_id is null then
    v_review_reason := case
      when v_candidate_site_id is null then 'signed_contract_site_missing'
      else 'signed_contract_site_tenant_mismatch'
    end;

    insert into public.customer_operation_jobs (
      company_id, customer_id, customer_site_id, metering_point_id,
      job_type, status, priority, idempotency_key, payload, result,
      attempts, max_attempts, run_after, created_by, operation_id, trace_id,
      review_reason_code, review_environment, review_sla_due_at
    ) values (
      new.company_id, new.customer_id, null, new.metering_point_id,
      'start_supplier_switch', 'needs_review', 25,
      'contract-signed:' || new.id::text,
      jsonb_build_object(
        'contract_id', new.id,
        'candidate_site_id', v_candidate_site_id,
        'trigger', 'contract_signed',
        'signed_at', new.signed_at,
        'requested_start_date', coalesce(new.requested_start_date, new.expected_start_at),
        'operation_id', v_operation_id,
        'trace_id', v_trace_id
      ),
      jsonb_build_object('reason_code', v_review_reason, 'contract_id', new.id),
      0, 5, now(), coalesce(new.updated_by, new.created_by),
      v_operation_id, v_trace_id, v_review_reason, 'production', now() + interval '4 hours'
    )
    on conflict (company_id, job_type, idempotency_key)
      where job_type = 'start_supplier_switch' and idempotency_key like 'contract-signed:%'
    do nothing
    returning id into v_job_id;

    insert into public.customer_operation_tasks (
      company_id, customer_id, site_id, metering_point_id, task_type, status,
      priority, title, description, due_at, metadata, created_by
    )
    select
      new.company_id, new.customer_id, null, new.metering_point_id,
      'contract_lifecycle_readiness', 'open', 'high',
      'Signerat avtal saknar säker anläggningskoppling',
      'Komplettera eller rätta avtalets tenant-säkra anläggningskoppling innan leverantörsbyte kan startas.',
      now() + interval '4 hours',
      jsonb_build_object(
        'contract_id', new.id,
        'candidate_site_id', v_candidate_site_id,
        'reason_code', v_review_reason,
        'operation_id', v_operation_id,
        'customer_operation_job_id', v_job_id
      ),
      coalesce(new.updated_by, new.created_by)
    where not exists (
      select 1 from public.customer_operation_tasks t
      where t.company_id = new.company_id
        and t.customer_id = new.customer_id
        and t.task_type = 'contract_lifecycle_readiness'
        and t.status in ('open', 'in_progress', 'blocked')
        and t.metadata ->> 'contract_id' = new.id::text
    );

    insert into public.customer_operation_events (
      company_id, customer_id, customer_site_id, metering_point_id,
      customer_operation_job_id, operation_id, event_code, title, message,
      status, severity, action_required, action_url, source, visibility,
      payload, idempotency_key
    ) values (
      new.company_id, new.customer_id, null, new.metering_point_id,
      v_job_id, v_operation_id, 'contract.signed.review_required',
      'Signerat avtal kräver granskning',
      'Avtalet kan inte gå vidare automatiskt förrän anläggningskopplingen är tenant-säker.',
      'needs_review', 'warning', true,
      '/admin/customers/' || new.customer_id::text || '?tab=supplier-switch',
      'contract_lifecycle_orchestrator', 'tenant',
      jsonb_build_object(
        'contract_id', new.id,
        'candidate_site_id', v_candidate_site_id,
        'customer_operation_job_id', v_job_id,
        'operation_id', v_operation_id,
        'trace_id', v_trace_id,
        'outcome_class', 'REVIEW'
      ),
      'contract-signed:' || new.id::text
    )
    on conflict (company_id, idempotency_key)
      where idempotency_key is not null do nothing;

    return new;
  end if;

  v_site_snapshot := jsonb_build_object(
    'site_id', v_site_id,
    'address_hash', v_site_address_hash,
    'grid_owner_id', v_site_grid_owner_id,
    'grid_area_code', v_site_grid_area_code,
    'route_profile_id', null,
    'facility_id', v_site_facility_id,
    'captured_at', now(),
    'contract_id', new.id,
    'operation_id', v_operation_id,
    'trace_id', v_trace_id
  );

  insert into public.customer_operation_jobs (
    company_id, customer_id, customer_site_id, metering_point_id,
    job_type, status, priority, idempotency_key, payload, result,
    attempts, max_attempts, run_after, created_by, operation_id, trace_id,
    request_snapshot
  ) values (
    new.company_id, new.customer_id, v_site_id, new.metering_point_id,
    'start_supplier_switch', 'queued', 25,
    'contract-signed:' || new.id::text,
    jsonb_build_object(
      'contract_id', new.id,
      'trigger', 'contract_signed',
      'signed_at', new.signed_at,
      'requested_start_date', coalesce(new.requested_start_date, new.expected_start_at),
      'operation_id', v_operation_id,
      'trace_id', v_trace_id,
      'site_snapshot', v_site_snapshot
    ),
    '{}'::jsonb, 0, 5, now(), coalesce(new.updated_by, new.created_by),
    v_operation_id, v_trace_id, v_site_snapshot
  )
  on conflict (company_id, job_type, idempotency_key)
    where job_type = 'start_supplier_switch' and idempotency_key like 'contract-signed:%'
  do nothing
  returning id into v_job_id;

  insert into public.customer_operation_events (
    company_id, customer_id, customer_site_id, metering_point_id,
    customer_operation_job_id, operation_id, event_code, title, message,
    status, severity, action_required, action_url, source, visibility,
    payload, idempotency_key
  ) values (
    new.company_id, new.customer_id, v_site_id, new.metering_point_id,
    v_job_id, v_operation_id, 'contract.signed',
    'Signerat avtal köat för automatisk onboarding',
    'Systemet fortsätter automatiskt med readiness och leverantörsbyte.',
    'in_progress', 'info', false,
    '/admin/customers/' || new.customer_id::text || '?tab=supplier-switch',
    'contract_lifecycle_orchestrator', 'tenant',
    jsonb_build_object(
      'contract_id', new.id,
      'signed_at', new.signed_at,
      'customer_operation_job_id', v_job_id,
      'operation_id', v_operation_id,
      'trace_id', v_trace_id,
      'outcome_class', 'AUTO'
    ),
    'contract-signed:' || new.id::text
  )
  on conflict (company_id, idempotency_key)
    where idempotency_key is not null do nothing;

  return new;
end;
$$;

--
-- Name: FUNCTION gridex_enqueue_signed_contract_operation_v1(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_enqueue_signed_contract_operation_v1() IS 'Atomic signed-contract bridge into existing readiness/supplier-switch/outbound automation; candidate site scope is fail-closed.';

--
-- Name: gridex_ensure_internal_contract_publication(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ensure_internal_contract_publication(p_company_id uuid, p_contract_offer_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype; v_assignment_id uuid; v_publication_id uuid; v_version_id uuid;
  v_snapshot jsonb; v_hash text; v_number integer; v_status text; v_offer_reference text;
begin
  select * into o from public.contract_offers
  where id=p_contract_offer_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='internal_contract_offer_not_found'; end if;

  if o.contract_product_version_id is null or o.legal_bundle_version_id is null or o.price_plan_version_id is null then
    perform public.gridex_sync_internal_offer_to_canonical(o.id);
    select * into o from public.contract_offers where id=o.id;
  end if;
  if o.contract_product_version_id is null or o.legal_bundle_version_id is null or o.price_plan_version_id is null then
    raise exception using errcode='23514',message='internal_offer_not_canonical_ready';
  end if;

  select id into v_assignment_id from public.tenant_contract_assignments
  where company_id=p_company_id and contract_product_version_id=o.contract_product_version_id
  order by created_at desc limit 1;
  if v_assignment_id is null then
    insert into public.tenant_contract_assignments(
      company_id,contract_product_version_id,internal_sales_allowed,website_publication_allowed,status,legal_mode,valid_from,valid_to,assigned_by
    ) values(
      p_company_id,o.contract_product_version_id,true,false,
      case when o.is_active and o.status='active' then 'active' else 'paused' end,
      'ops_standard',o.valid_from,o.valid_to,p_actor_user_id
    ) returning id into v_assignment_id;
  end if;

  insert into public.contract_publications(assignment_id,channel,status,created_by)
  values(v_assignment_id,'internal',case when o.is_active and o.status='active' then 'published' else 'draft' end,p_actor_user_id)
  on conflict(assignment_id,channel) do update
    set status=excluded.status,updated_at=now()
  returning id into v_publication_id;

  v_status:=case when o.is_active and o.status='active' then 'published' else 'draft' end;
  v_snapshot:=jsonb_strip_nulls(jsonb_build_object(
    'schema','gridex_internal_publication_v1',
    'company_id',p_company_id,
    'legacy_contract_offer_id',o.id,
    'contract_product_version_id',o.contract_product_version_id,
    'price_plan_id',o.price_plan_id,
    'price_plan_version_id',o.price_plan_version_id,
    'legal_bundle_version_id',o.legal_bundle_version_id,
    'name',o.name,
    'customer_type',o.customer_type,
    'contract_type',o.contract_type,
    'valid_from',o.valid_from,
    'valid_to',o.valid_to
  ));
  v_hash:=encode(digest(v_snapshot::text,'sha256'),'hex');
  select id into v_version_id
  from public.contract_publication_versions
  where contract_publication_id=v_publication_id and content_sha256=v_hash limit 1;

  if v_version_id is null then
    select coalesce(max(version_number),0)+1 into v_number
    from public.contract_publication_versions where contract_publication_id=v_publication_id;
    v_offer_reference:='internal_'||replace(o.id::text,'-','')||'_v'||v_number::text;
    insert into public.contract_publication_versions(
      contract_publication_id,version_number,contract_product_version_id,price_plan_id,price_plan_version_id,
      price_book_id,legal_bundle_version_id,legacy_public_contract_offer_id,customer_type,channel,
      valid_from,valid_to,publication_snapshot,offer_reference,content_sha256,status,
      published_at,locked_at,created_by
    ) values(
      v_publication_id,v_number,o.contract_product_version_id,o.price_plan_id,o.price_plan_version_id,
      o.price_book_id,o.legal_bundle_version_id,null,coalesce(o.customer_type,'both'),'internal',
      o.valid_from::timestamptz,o.valid_to::timestamptz,v_snapshot,v_offer_reference,v_hash,v_status,
      case when v_status='published' then now() end,case when v_status='published' then now() end,p_actor_user_id
    ) returning id into v_version_id;
  elsif v_status='published' then
    perform set_config('gridex.version_transition','on',true);
    update public.contract_publication_versions set status='published',published_at=coalesce(published_at,now()),locked_at=coalesce(locked_at,now())
    where id=v_version_id;
  end if;

  return v_version_id;
end $$;

--
-- Name: gridex_escalate_overdue_z01_responses(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_escalate_overdue_z01_responses(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  rec record;
  v_limit integer := greatest(1, least(coalesce(p_limit, 100), 500));
  v_scanned integer := 0;
  v_contrl_overdue integer := 0;
  v_business_overdue integer := 0;
  v_has_business_response boolean;
  v_business_response_message_id uuid;
begin
  for rec in
    select
      m.id as ediel_message_id,
      m.company_id,
      m.customer_id,
      m.site_id,
      m.metering_point_id,
      m.grid_owner_id,
      m.operation_id,
      m.message_sent_at,
      m.contrl_due_at,
      m.business_response_due_at,
      m.response_overdue_at,
      m.requires_contrl,
      m.contrl_status,
      cir.id as customer_info_request_id,
      cir.status as customer_info_status
    from public.ediel_messages m
    left join public.customer_info_requests cir
      on cir.company_id = m.company_id
     and cir.ediel_message_id = m.id
    where m.direction = 'outbound'
      and upper(m.message_family) = 'PRODAT'
      and upper(coalesce(m.message_code,'')) = 'Z01'
      and m.message_sent_at is not null
      and (
        (
          m.requires_contrl = true
          and m.contrl_due_at is not null
          and m.contrl_due_at <= now()
          and (
            coalesce(m.contrl_status, 'pending') not in ('received','sent')
            or (
              coalesce(m.contrl_status, 'pending') in ('received','sent')
              and exists (
                select 1
                from public.ediel_ack_sla_events technical_sla
                where technical_sla.company_id = m.company_id
                  and technical_sla.ediel_message_id = m.id
                  and technical_sla.ack_family = 'CONTRL'
                  and technical_sla.status = 'open'
              )
            )
          )
        )
        or
        (
          m.business_response_due_at is not null
          and m.business_response_due_at <= now()
          and (
            not exists (
              select 1
              from public.ediel_messages response
              where response.company_id = m.company_id
                and response.direction = 'inbound'
                and response.related_message_id = m.id
                and (
                  (
                    upper(response.message_family) = 'PRODAT'
                    and upper(coalesce(response.message_code,'')) = 'Z02'
                  )
                  or
                  (
                    upper(response.message_family) = 'APERAK'
                    and lower(coalesce(response.ack_outcome,'')) = 'negative'
                  )
                )
            )
            or exists (
              select 1
              from public.ediel_ack_sla_events business_sla
              where business_sla.company_id = m.company_id
                and business_sla.ediel_message_id = m.id
                and business_sla.ack_family = 'PRODAT_Z02_OR_NEGATIVE_APERAK'
                and business_sla.status = 'open'
            )
          )
        )
      )
    order by least(
      coalesce(m.contrl_due_at, 'infinity'::timestamptz),
      coalesce(m.business_response_due_at, 'infinity'::timestamptz)
    )
    limit v_limit
  loop
    v_scanned := v_scanned + 1;

    if rec.requires_contrl = true
       and rec.contrl_due_at is not null
       and rec.contrl_due_at <= now()
       and coalesce(rec.contrl_status, 'pending') not in ('received','sent') then

      insert into public.ediel_ack_sla_events (
        company_id, ediel_message_id, ack_family, due_at, breached_at,
        severity, status, metadata
      )
      values (
        rec.company_id, rec.ediel_message_id, 'CONTRL', rec.contrl_due_at, now(),
        'warning', 'open',
        jsonb_build_object(
          'source', 'z01_parallel_sla_watchdog',
          'messageFamily', 'PRODAT',
          'messageCode', 'Z01',
          'automaticResendAllowed', false
        )
      )
      on conflict do nothing;

      if not exists (
        select 1 from public.ediel_message_events e
        where e.ediel_message_id = rec.ediel_message_id
          and e.event_type = 'ack_sla_breached'
          and e.payload ->> 'slaFamily' = 'CONTRL'
      ) then
        insert into public.ediel_message_events (
          company_id, ediel_message_id, event_type, event_status, message, payload
        )
        values (
          rec.company_id, rec.ediel_message_id,
          'ack_sla_breached', 'warning',
          'CONTRL saknas efter canonical SLA. Teknisk kvittens bevakas separat från Z02.',
          jsonb_build_object(
            'slaFamily', 'CONTRL',
            'dueAt', rec.contrl_due_at,
            'messageSentAt', rec.message_sent_at,
            'automaticResendAllowed', false
          )
        );
      end if;

      v_contrl_overdue := v_contrl_overdue + 1;
    end if;

    if rec.requires_contrl = true
       and coalesce(rec.contrl_status, 'pending') in ('received','sent') then
      update public.ediel_ack_sla_events
      set
        status = 'resolved',
        resolved_at = coalesce(resolved_at, now()),
        updated_at = now(),
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'resolvedBy', 'outbound_contrl_status',
          'resolvedContrlStatus', rec.contrl_status
        )
      where company_id = rec.company_id
        and ediel_message_id = rec.ediel_message_id
        and ack_family = 'CONTRL'
        and status = 'open';
    end if;

    v_business_response_message_id := null;
    select r.id
      into v_business_response_message_id
    from public.ediel_messages r
    where r.company_id = rec.company_id
      and r.direction = 'inbound'
      and r.related_message_id = rec.ediel_message_id
      and (
        (
          upper(r.message_family) = 'PRODAT'
          and upper(coalesce(r.message_code,'')) = 'Z02'
        )
        or
        (
          upper(r.message_family) = 'APERAK'
          and lower(coalesce(r.ack_outcome,'')) = 'negative'
        )
      )
    order by coalesce(r.message_received_at, r.created_at) desc
    limit 1;

    v_has_business_response := v_business_response_message_id is not null;

    if v_has_business_response then
      update public.ediel_ack_sla_events
      set
        status = 'resolved',
        resolved_at = coalesce(resolved_at, now()),
        updated_at = now(),
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'resolvedBy', 'late_business_response',
          'resolvedByEdielMessageId', v_business_response_message_id
        )
      where company_id = rec.company_id
        and ediel_message_id = rec.ediel_message_id
        and ack_family = 'PRODAT_Z02_OR_NEGATIVE_APERAK'
        and status = 'open';

      update public.customer_operation_events
      set
        status = 'completed',
        action_required = false,
        payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
          'resolved_at', now(),
          'resolved_by_ediel_message_id', v_business_response_message_id,
          'resolution', 'business_response_received'
        )
      where company_id = rec.company_id
        and idempotency_key = 'z01-response-overdue:' || rec.ediel_message_id::text
        and event_code = 'customer_data.response_overdue'
        and action_required = true;
    end if;

    if rec.business_response_due_at is not null
       and rec.business_response_due_at <= now()
       and not v_has_business_response then

      update public.ediel_messages
      set
        response_overdue_at = coalesce(response_overdue_at, now()),
        updated_at = now()
      where id = rec.ediel_message_id
        and company_id = rec.company_id;

      insert into public.ediel_ack_sla_events (
        company_id, ediel_message_id, ack_family, due_at, breached_at,
        severity, status, metadata
      )
      values (
        rec.company_id, rec.ediel_message_id,
        'PRODAT_Z02_OR_NEGATIVE_APERAK',
        rec.business_response_due_at, now(),
        'warning', 'open',
        jsonb_build_object(
          'source', 'z01_parallel_sla_watchdog',
          'messageFamily', 'PRODAT',
          'messageCode', 'Z01',
          'expectedBusinessResponse', jsonb_build_array('PRODAT Z02','negative APERAK'),
          'automaticResendAllowed', false
        )
      )
      on conflict do nothing;

      if not exists (
        select 1 from public.ediel_message_events e
        where e.ediel_message_id = rec.ediel_message_id
          and e.event_type = 'ack_sla_breached'
          and e.payload ->> 'slaFamily' = 'PRODAT_Z02_OR_NEGATIVE_APERAK'
      ) then
        insert into public.ediel_message_events (
          company_id, ediel_message_id, event_type, event_status, message, payload
        )
        values (
          rec.company_id, rec.ediel_message_id,
          'ack_sla_breached', 'warning',
          'Z02 eller negativ APERAK saknas efter canonical 30-minutersfrist. Ingen automatisk Z01-omsändning görs.',
          jsonb_build_object(
            'slaFamily', 'PRODAT_Z02_OR_NEGATIVE_APERAK',
            'dueAt', rec.business_response_due_at,
            'messageSentAt', rec.message_sent_at,
            'automaticResendAllowed', false,
            'requiredAction', 'check_inbound_mailbox_and_contact_grid_owner'
          )
        );
      end if;

      if rec.customer_info_request_id is not null then
        update public.customer_info_requests
        set
          status = 'manual_review_required',
          blocker_code = 'response_overdue',
          blocker_reason = 'Nätägarens Z02 eller negativa APERAK saknas efter canonical 30-minutersfrist.',
          blocker_details = jsonb_build_object(
            'reason_code', 'response_overdue',
            'issue_type', 'technical',
            'error_class', 'business_blocker',
            'due_at', rec.business_response_due_at,
            'message_sent_at', rec.message_sent_at,
            'automatic_resend_allowed', false
          ),
          next_required_action = 'Kontrollera inkommande Ediel-mailbox/transport och kontakta nätägaren. Skicka inte ny Z01 automatiskt.',
          updated_at = now()
        where id = rec.customer_info_request_id
          and company_id = rec.company_id
          and status in (
            'sent_to_grid_owner','waiting_for_contrl','waiting_for_aperak',
            'waiting_for_z02','waiting_response','sent'
          );

        if not exists (
          select 1 from public.customer_info_request_events e
          where e.company_id = rec.company_id
            and e.customer_info_request_id = rec.customer_info_request_id
            and e.event_type = 'response_overdue'
            and e.payload ->> 'edielMessageId' = rec.ediel_message_id::text
        ) then
          insert into public.customer_info_request_events (
            company_id, customer_info_request_id, customer_id,
            event_type, message, payload
          )
          values (
            rec.company_id, rec.customer_info_request_id, rec.customer_id,
            'response_overdue',
            'Z01-svaret är försenat. Kontrollera mailbox/transport och följ upp nätägaren innan nytt utskick.',
            jsonb_build_object(
              'edielMessageId', rec.ediel_message_id,
              'dueAt', rec.business_response_due_at,
              'automaticResendAllowed', false
            )
          );
        end if;
      end if;

      if rec.customer_id is not null then
        insert into public.customer_operation_events (
          company_id, customer_id, customer_site_id, metering_point_id, operation_id,
          event_code, title, message, status, severity, action_required, action_url,
          source, visibility, payload, idempotency_key
        )
        values (
          rec.company_id, rec.customer_id, rec.site_id, rec.metering_point_id, rec.operation_id,
          'customer_data.response_overdue',
          'Svar från nätägaren är försenat',
          'Z02 eller negativ APERAK saknas efter 30 minuter. Kontrollera inbound-mailbox/transport och kontakta nätägaren. Ingen automatisk Z01-omsändning görs.',
          'needs_review', 'warning', true,
          '/admin/customer-info-requests',
          'ediel_z01_sla_watchdog', 'tenant',
          jsonb_build_object(
            'ediel_message_id', rec.ediel_message_id,
            'customer_info_request_id', rec.customer_info_request_id,
            'grid_owner_id', rec.grid_owner_id,
            'due_at', rec.business_response_due_at,
            'automatic_resend_allowed', false
          ),
          'z01-response-overdue:' || rec.ediel_message_id::text
        )
        on conflict do nothing;
      end if;

      v_business_overdue := v_business_overdue + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'scanned', v_scanned,
    'contrl_overdue', v_contrl_overdue,
    'business_response_overdue', v_business_overdue,
    'automatic_resends', 0
  );
end;
$$;

--
-- Name: FUNCTION gridex_escalate_overdue_z01_responses(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_escalate_overdue_z01_responses(p_limit integer) IS 'Escalates/resolves only actionable outbound PRODAT Z01 SLA dimensions, preventing resolved history from starving newer cases; never resends Z01.';

--
-- Name: gridex_fail_website_contract_signature(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_fail_website_contract_signature(p_company_id uuid, p_contract_id uuid, p_application_id uuid, p_error_code text, p_error_stage text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'auth', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_contract public.customer_contracts%rowtype;
begin
  if auth.role() <> 'service_role' then
    raise exception using
      errcode = '42501',
      message = 'signature_failure_service_role_required';
  end if;
  select * into v_contract
  from public.customer_contracts contract
  where contract.id = p_contract_id
    and contract.company_id = p_company_id
    and contract.metadata->>'website_application_id' = p_application_id::text
  for update;
  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'website_signature_contract_not_found_for_application';
  end if;
  if v_contract.status = 'signature_failed' then
    return;
  end if;
  perform public.gridex_record_customer_contract_event_v1(
    p_company_id,
    p_contract_id,
    v_contract.customer_id,
    'signature_failed',
    now(),
    'Webbsigneringen misslyckades och kan återupptas med ett nytt försök.',
    jsonb_build_object(
      'website_application_id', p_application_id,
      'signature_failure_code', nullif(p_error_code, ''),
      'signature_failure_stage', nullif(p_error_stage, '')
    ),
    null,
    null,
    'website-signature-failed:' || p_application_id::text
  );
end
$$;

--
-- Name: gridex_fill_contract_price_snapshot_binding_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_fill_contract_price_snapshot_binding_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_contract public.customer_contracts%rowtype; v_site_area text; v_meter_area text; v_area text; v_snapshot_area text; v_snapshot_ppv uuid;
begin
  select * into v_contract from public.customer_contracts c where c.id=new.contract_id and c.company_id=new.company_id;
  if not found then return new; end if;
  if v_contract.customer_site_id is not null or v_contract.site_id is not null then
    select upper(nullif(btrim(s.price_area_code),'')) into v_site_area from public.customer_sites s where s.id=coalesce(v_contract.customer_site_id,v_contract.site_id) and s.company_id=new.company_id limit 1;
  end if;
  if v_contract.metering_point_id is not null then
    select upper(nullif(btrim(coalesce(m.price_area_code,m.price_area)),'')) into v_meter_area from public.metering_points m where m.id=v_contract.metering_point_id and m.company_id=new.company_id limit 1;
  end if;
  if v_site_area in ('SE1','SE2','SE3','SE4') and v_meter_area in ('SE1','SE2','SE3','SE4') and v_site_area<>v_meter_area then raise exception using errcode='23514',message='contract_snapshot_price_area_source_conflict'; end if;
  v_area:=coalesce(case when upper(nullif(btrim(v_contract.price_area_used),'')) in ('SE1','SE2','SE3','SE4') then upper(btrim(v_contract.price_area_used)) end,case when v_meter_area in ('SE1','SE2','SE3','SE4') then v_meter_area end,case when v_site_area in ('SE1','SE2','SE3','SE4') then v_site_area end);
  v_snapshot_area:=upper(nullif(btrim(new.snapshot_json->>'price_area'),''));
  if v_snapshot_area is not null and v_snapshot_area not in ('SE1','SE2','SE3','SE4') then raise exception using errcode='23514',message='contract_snapshot_price_area_invalid'; end if;
  if v_snapshot_area is not null and v_area is not null and v_snapshot_area<>v_area then raise exception using errcode='23514',message='contract_snapshot_price_area_mismatch'; end if;
  v_snapshot_ppv:=nullif(new.snapshot_json->>'price_plan_version_id','')::uuid;
  if v_snapshot_ppv is not null and v_contract.price_plan_version_id is not null and v_snapshot_ppv<>v_contract.price_plan_version_id then raise exception using errcode='23514',message='contract_snapshot_price_plan_version_mismatch'; end if;
  new.price_plan_id:=coalesce(new.price_plan_id,v_contract.price_plan_id);
  new.price_plan_version_id:=coalesce(new.price_plan_version_id,v_contract.price_plan_version_id);
  new.price_book_id:=coalesce(new.price_book_id,v_contract.price_book_id);
  if coalesce(jsonb_array_length(new.base_price_components_snapshot),0)=0 then new.base_price_components_snapshot:=coalesce(v_contract.commercial_snapshot->'base_price_components_snapshot',v_contract.commercial_snapshot->'base_components','[]'::jsonb); end if;
  if coalesce(jsonb_array_length(new.price_components_snapshot),0)=0 then new.price_components_snapshot:=coalesce(v_contract.commercial_snapshot->'price_components_snapshot',v_contract.commercial_snapshot->'price_components','[]'::jsonb); end if;
  new.snapshot_json:=coalesce(new.snapshot_json,'{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object('price_area',coalesce(v_snapshot_area,v_area),'price_plan_id',new.price_plan_id,'price_plan_version_id',new.price_plan_version_id,'price_book_id',new.price_book_id,'contract_product_version_id',v_contract.contract_product_version_id,'contract_publication_version_id',v_contract.contract_publication_version_id,'legal_bundle_version_id',v_contract.legal_bundle_version_id,'base_price_components_snapshot',new.base_price_components_snapshot,'price_components_snapshot',new.price_components_snapshot));
  new.snapshot_schema_version:=coalesce(new.snapshot_schema_version,'gridex_contract_pricing_v8_area_bound');
  new.snapshot_hash:=null;
  return new;
end; $$;

--
-- Name: gridex_fill_customer_authorization_document_file_path(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_fill_customer_authorization_document_file_path() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_company text;
  v_customer text;
  v_poa_or_doc text;
begin
  if new.file_path is null or btrim(new.file_path) = '' then
    v_company := coalesce(new.company_id::text, 'unknown-company');
    v_customer := coalesce(new.customer_id::text, 'unknown-customer');
    v_poa_or_doc := coalesce(
      new.power_of_attorney_id::text,
      nullif(regexp_replace(coalesce(new.reference, ''), '^POA-', ''), ''),
      new.id::text
    );

    new.storage_bucket := coalesce(nullif(btrim(new.storage_bucket), ''), 'customer-documents');
    new.file_path := concat('companies/', v_company, '/customers/', v_customer, '/authorizations/', v_poa_or_doc, '.json');
  end if;

  if (new.file_name is null or btrim(new.file_name) = '') and new.document_type = 'power_of_attorney' then
    new.file_name := concat('fullmakt-', coalesce(nullif(new.reference, ''), new.power_of_attorney_id::text, new.id::text), '.json');
  end if;

  return new;
end;
$$;

--
-- Name: gridex_fill_customer_contract_price_area_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_fill_customer_contract_price_area_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_site_area text; v_meter_area text; v_site_grid text; v_meter_grid text; v_area text; v_grid text;
begin
  if new.customer_site_id is not null or new.site_id is not null then
    select upper(nullif(btrim(s.price_area_code),'')), upper(nullif(btrim(s.grid_area_code),'')) into v_site_area,v_site_grid
    from public.customer_sites s where s.id=coalesce(new.customer_site_id,new.site_id) and s.company_id=new.company_id limit 1;
  end if;
  if new.metering_point_id is not null then
    select upper(nullif(btrim(coalesce(m.price_area_code,m.price_area)),'')), upper(nullif(btrim(m.grid_area_code),'')) into v_meter_area,v_meter_grid
    from public.metering_points m where m.id=new.metering_point_id and m.company_id=new.company_id limit 1;
  end if;
  if v_site_area in ('SE1','SE2','SE3','SE4') and v_meter_area in ('SE1','SE2','SE3','SE4') and v_site_area<>v_meter_area then
    raise exception using errcode='23514',message='contract_price_area_source_conflict';
  end if;
  v_area:=coalesce(case when v_meter_area in ('SE1','SE2','SE3','SE4') then v_meter_area end,case when v_site_area in ('SE1','SE2','SE3','SE4') then v_site_area end);
  v_grid:=coalesce(v_meter_grid,v_site_grid);
  if nullif(btrim(coalesce(new.price_area_used,'')),'') is null then new.price_area_used:=v_area;
  elsif v_area is not null and upper(btrim(new.price_area_used))<>v_area then raise exception using errcode='23514',message='contract_price_area_binding_mismatch';
  else new.price_area_used:=upper(btrim(new.price_area_used)); end if;
  if nullif(btrim(coalesce(new.grid_area_code_used,'')),'') is null then new.grid_area_code_used:=v_grid;
  elsif v_grid is not null and upper(btrim(new.grid_area_code_used))<>v_grid then raise exception using errcode='23514',message='contract_grid_area_binding_mismatch';
  else new.grid_area_code_used:=upper(btrim(new.grid_area_code_used)); end if;
  return new;
end; $$;

--
-- Name: gridex_finalize_admin_imported_signed_agreement_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_finalize_admin_imported_signed_agreement_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_catalog', 'pg_temp'
    AS $_$
declare
  v_contract public.customer_contracts%rowtype;
  v_customer public.customers%rowtype;
  v_price public.contract_price_snapshots%rowtype;
  v_binding jsonb;
  v_snapshot jsonb;
  v_base_components jsonb;
  v_price_components jsonb;
  v_pricing_model text;
  v_snapshot_id uuid;
  v_contract_document_id uuid;
  v_accepted_at timestamptz;
  v_legal_versions jsonb;
  v_signature jsonb;
  v_signature_hash text;
  v_acceptance jsonb;
  v_acceptance_hash text;
  v_event jsonb;
begin
  if new.document_type <> 'complete_agreement'
     or new.status <> 'active'
     or coalesce(new.metadata->>'source', '') <> 'customer_intake'
     or coalesce(new.metadata->>'documentRole', '') <> 'signed_agreement' then
    return new;
  end if;

  if new.company_id is null
     or new.customer_id is null
     or new.customer_contract_id is null then
    raise exception using
      errcode = '23514',
      message = 'admin_signed_contract_import_identity_incomplete';
  end if;
  if new.created_by is null then
    raise exception using
      errcode = '23514',
      message = 'admin_signed_contract_import_actor_required';
  end if;
  perform public.gridex_assert_contract_permission(new.created_by, 'contracts.create');

  if nullif(btrim(coalesce(new.storage_bucket, '')), '') is null
     or nullif(btrim(coalesce(new.file_path, '')), '') is null
     or coalesce(new.file_checksum, '') !~ '^[0-9a-f]{64}$' then
    raise exception using
      errcode = '23514',
      message = 'admin_signed_contract_import_document_evidence_incomplete';
  end if;
  if lower(coalesce(new.mime_type, '')) <> 'application/pdf'
     and lower(new.file_path) not like '%.pdf' then
    raise exception using
      errcode = '23514',
      message = 'admin_signed_contract_import_pdf_required';
  end if;

  select * into v_contract
  from public.customer_contracts
  where id = new.customer_contract_id
    and company_id = new.company_id
    and customer_id = new.customer_id
  for update;
  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'admin_signed_contract_import_contract_not_found_for_tenant';
  end if;

  if v_contract.status in ('signed', 'active', 'terminated', 'cancelled', 'expired')
     or v_contract.signed_at is not null then
    if v_contract.document_sha256 = new.file_checksum
       and exists (
         select 1
         from public.customer_contract_documents d
         where d.company_id = new.company_id
           and d.customer_contract_id = new.customer_contract_id
           and d.document_type = 'signed_contract_pdf'
           and d.document_sha256 = new.file_checksum
           and d.verified_at is not null
       ) then
      return new;
    end if;
    raise exception using
      errcode = '23514',
      message = 'admin_signed_contract_import_contract_already_finalized';
  end if;

  if v_contract.status not in ('draft', 'pending_signature', 'signature_failed') then
    raise exception using
      errcode = '23514',
      message = 'admin_signed_contract_import_state_invalid';
  end if;

  -- Materialize the exact canonical contract publication chain before any
  -- signature evidence is recorded. Catalog offers reuse their locked internal
  -- publication; one-off contracts create a dedicated immutable publication.
  if v_contract.contract_publication_version_id is null
     or v_contract.contract_product_version_id is null
     or v_contract.price_plan_version_id is null
     or v_contract.legal_bundle_version_id is null then
    if v_contract.contract_offer_id is not null then
      perform public.gridex_ensure_internal_contract_publication(
        v_contract.company_id,
        v_contract.contract_offer_id,
        new.created_by
      );
      update public.customer_contracts
      set contract_offer_id = v_contract.contract_offer_id,
          updated_by = new.created_by,
          updated_at = now()
      where id = v_contract.id and company_id = v_contract.company_id
      returning * into v_contract;
    else
      v_binding := public.gridex_prepare_manual_contract_binding(
        v_contract.company_id,
        jsonb_strip_nulls(jsonb_build_object(
          'name', v_contract.contract_name,
          'customer_type', (
            select c.customer_type
            from public.customers c
            where c.id = v_contract.customer_id
              and c.company_id = v_contract.company_id
          ),
          'contract_type', v_contract.contract_type,
          'energy_direction', v_contract.energy_direction,
          'campaign_code', v_contract.campaign_code,
          'campaign_version', v_contract.campaign_version,
          'terms_version', v_contract.terms_version,
          'binding_months', v_contract.binding_months,
          'notice_months', v_contract.notice_months,
          'valid_from', coalesce(v_contract.starts_at::date, current_date),
          'valid_to', v_contract.ends_at::date
        )),
        coalesce(v_contract.price_snapshot, '{}'::jsonb) ||
        jsonb_strip_nulls(jsonb_build_object(
          'contract_type', v_contract.contract_type,
          'energy_direction', v_contract.energy_direction,
          'price_area', v_contract.price_area_used,
          'fixed_price_ore_per_kwh', v_contract.fixed_price_ore_per_kwh,
          'spot_markup_ore_per_kwh', v_contract.spot_markup_ore_per_kwh,
          'variable_fee_ore_per_kwh', v_contract.variable_fee_ore_per_kwh,
          'monthly_fee_sek', v_contract.monthly_fee_sek,
          'invoice_fee_sek', v_contract.invoice_fee_sek,
          'green_fee_mode', v_contract.green_fee_mode,
          'green_fee_value', v_contract.green_fee_value,
          'discount_value', v_contract.discount_value,
          'discount_unit', v_contract.discount_unit,
          'start_fee_sek', v_contract.start_fee_sek,
          'admin_fee_sek', v_contract.admin_fee_sek,
          'break_fee_sek', v_contract.break_fee_sek,
          'vat_rate', v_contract.vat_rate
        )),
        new.created_by
      );

      update public.customer_contracts
      set contract_offer_id = nullif(v_binding->>'contract_offer_id', '')::uuid,
          contract_product_id = nullif(v_binding->>'contract_product_id', '')::uuid,
          contract_product_version_id = nullif(v_binding->>'contract_product_version_id', '')::uuid,
          contract_publication_version_id = nullif(v_binding->>'contract_publication_version_id', '')::uuid,
          price_plan_id = nullif(v_binding->>'price_plan_id', '')::uuid,
          price_plan_version_id = nullif(v_binding->>'price_plan_version_id', '')::uuid,
          price_book_id = nullif(v_binding->>'price_book_id', '')::uuid,
          legal_bundle_version_id = nullif(v_binding->>'legal_bundle_version_id', '')::uuid,
          offer_reference = v_binding->>'offer_reference',
          commercial_snapshot = coalesce(v_binding->'commercial_snapshot', '{}'::jsonb),
          legal_snapshot = coalesce(v_binding->'legal_snapshot', '{}'::jsonb),
          updated_by = new.created_by,
          updated_at = now()
      where id = v_contract.id and company_id = v_contract.company_id
      returning * into v_contract;
    end if;
  end if;

  if v_contract.contract_publication_version_id is null
     or v_contract.contract_product_version_id is null
     or v_contract.price_plan_version_id is null
     or v_contract.legal_bundle_version_id is null
     or coalesce(v_contract.commercial_snapshot, '{}'::jsonb) = '{}'::jsonb
     or coalesce(v_contract.legal_snapshot, '{}'::jsonb) = '{}'::jsonb then
    raise exception using
      errcode = '23514',
      message = 'admin_signed_contract_import_exact_contract_chain_missing';
  end if;

  if not exists (
    select 1
    from public.contract_publication_versions cpv
    join public.contract_publications cp
      on cp.id = cpv.contract_publication_id
    join public.tenant_contract_assignments ta
      on ta.id = cp.assignment_id
     and ta.company_id = v_contract.company_id
    join public.contract_product_versions ctv
      on ctv.id = cpv.contract_product_version_id
    join public.price_plan_versions ppv
      on ppv.id = cpv.price_plan_version_id
    join public.legal_bundle_versions lbv
      on lbv.id = cpv.legal_bundle_version_id
    where cpv.id = v_contract.contract_publication_version_id
      and cpv.contract_product_version_id = v_contract.contract_product_version_id
      and cpv.price_plan_version_id = v_contract.price_plan_version_id
      and cpv.legal_bundle_version_id = v_contract.legal_bundle_version_id
      and cpv.status = 'published'
      and cpv.locked_at is not null
      and ctv.status = 'approved'
      and ctv.locked_at is not null
      and ppv.status in ('published', 'approved', 'active')
      and ppv.locked_at is not null
      and lbv.status = 'published'
      and lbv.locked_at is not null
      and cardinality(lbv.unresolved_variables) = 0
  ) then
    raise exception using
      errcode = '23514',
      message = 'admin_signed_contract_import_versions_not_locked';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'legal_bundle_version_document_id', d.id,
    'module_key', d.module_key,
    'title', d.title,
    'legal_document_version', coalesce(d.template_version, left(d.content_sha256, 12)),
    'document_sha256', d.content_sha256,
    'body_sha256', d.content_sha256
  ) order by d.sort_order, d.id), '[]'::jsonb)
  into v_legal_versions
  from public.legal_bundle_version_documents d
  where d.legal_bundle_version_id = v_contract.legal_bundle_version_id;
  if jsonb_array_length(v_legal_versions) = 0 then
    raise exception using
      errcode = '23514',
      message = 'admin_signed_contract_import_legal_document_set_missing';
  end if;

  -- Create a fresh canonical receipt snapshot bound to the exact versions and
  -- the signed document. The thin intake snapshot remains immutable history but
  -- is not used as the signed contract's authoritative pricing receipt.
  select coalesce(cpv.pricing_model, 'spot') into v_pricing_model
  from public.contract_product_versions cpv
  where cpv.id = v_contract.contract_product_version_id;

  v_base_components := coalesce(
    v_contract.commercial_snapshot->'base_price_components_snapshot',
    v_contract.commercial_snapshot->'base_components',
    v_contract.price_snapshot->'base_price_components_snapshot',
    '[]'::jsonb
  );
  v_price_components := coalesce(
    v_contract.commercial_snapshot->'price_components_snapshot',
    v_contract.commercial_snapshot->'price_components',
    v_contract.price_snapshot->'price_components_snapshot',
    '[]'::jsonb
  );
  if jsonb_typeof(v_base_components) <> 'array' then v_base_components := '[]'::jsonb; end if;
  if jsonb_typeof(v_price_components) <> 'array' then v_price_components := '[]'::jsonb; end if;

  v_snapshot := jsonb_strip_nulls(
    coalesce(v_contract.commercial_snapshot, '{}'::jsonb)
    || coalesce(v_contract.price_snapshot, '{}'::jsonb)
    || jsonb_build_object(
      'snapshot_schema', 'gridex_contract_pricing_v7_signed_receipt',
      'schema_version', 'gridex_contract_pricing_v7_signed_receipt',
      'source', 'admin_signed_document_import',
      'company_id', v_contract.company_id,
      'customer_id', v_contract.customer_id,
      'contract_id', v_contract.id,
      'contract_number', v_contract.contract_number,
      'customer_number', v_contract.customer_number,
      'contract_type', v_contract.contract_type,
      'energy_direction', v_contract.energy_direction,
      'price_area', v_contract.price_area_used,
      'fixed_price_ore_per_kwh', v_contract.fixed_price_ore_per_kwh,
      'spot_markup_ore_per_kwh', v_contract.spot_markup_ore_per_kwh,
      'variable_fee_ore_per_kwh', v_contract.variable_fee_ore_per_kwh,
      'monthly_fee_sek', v_contract.monthly_fee_sek,
      'invoice_fee_sek', v_contract.invoice_fee_sek,
      'green_fee_mode', v_contract.green_fee_mode,
      'green_fee_value', v_contract.green_fee_value,
      'discount_value', v_contract.discount_value,
      'discount_unit', v_contract.discount_unit,
      'start_fee_sek', v_contract.start_fee_sek,
      'admin_fee_sek', v_contract.admin_fee_sek,
      'break_fee_sek', v_contract.break_fee_sek,
      'vat_rate', v_contract.vat_rate,
      'binding_months', v_contract.binding_months,
      'notice_months', v_contract.notice_months,
      'starts_at', v_contract.starts_at,
      'ends_at', v_contract.ends_at,
      'offer_reference', v_contract.offer_reference,
      'contract_publication_version_id', v_contract.contract_publication_version_id,
      'contract_product_version_id', v_contract.contract_product_version_id,
      'price_plan_id', v_contract.price_plan_id,
      'price_plan_version_id', v_contract.price_plan_version_id,
      'price_book_id', v_contract.price_book_id,
      'legal_bundle_version_id', v_contract.legal_bundle_version_id,
      'signed_document_sha256', new.file_checksum,
      'base_price_components_snapshot', v_base_components,
      'price_components_snapshot', v_price_components
    )
  );
  v_snapshot := private.gridex_normalize_fixed_area_snapshot_v1(v_snapshot);

  insert into public.contract_price_snapshots(
    company_id,
    contract_id,
    customer_id,
    price_plan_id,
    price_plan_version_id,
    price_book_id,
    pricing_model,
    base_price_components_snapshot,
    price_components_snapshot,
    snapshot_json,
    valid_from,
    valid_to,
    source,
    contract_number,
    customer_number,
    snapshot_hash,
    snapshot_quality,
    snapshot_schema_version
  ) values (
    v_contract.company_id,
    v_contract.id,
    v_contract.customer_id,
    v_contract.price_plan_id,
    v_contract.price_plan_version_id,
    v_contract.price_book_id,
    coalesce(v_pricing_model, 'spot'),
    coalesce(v_snapshot->'base_price_components_snapshot', '[]'::jsonb),
    coalesce(v_snapshot->'price_components_snapshot', '[]'::jsonb),
    v_snapshot,
    coalesce(v_contract.starts_at::date, current_date),
    v_contract.ends_at::date,
    'admin_signed_document_import',
    v_contract.contract_number,
    v_contract.customer_number,
    encode(extensions.digest(convert_to(v_snapshot::text, 'UTF8'), 'sha256'), 'hex'),
    'canonical',
    'gridex_contract_pricing_v7_signed_receipt'
  ) returning * into v_price;
  v_snapshot_id := v_price.id;

  update public.customer_contracts
  set contract_price_snapshot_id = v_snapshot_id,
      price_snapshot = v_snapshot,
      updated_by = new.created_by,
      updated_at = now()
  where id = v_contract.id and company_id = v_contract.company_id
  returning * into v_contract;

  if v_contract.status in ('draft', 'signature_failed') then
    update public.customer_contracts
    set status = 'pending_signature',
        lifecycle_stage = 'agreement_ready',
        updated_by = new.created_by,
        updated_at = now()
    where id = v_contract.id and company_id = v_contract.company_id
    returning * into v_contract;
  end if;
  if v_contract.status <> 'pending_signature' then
    raise exception using
      errcode = '23514',
      message = 'admin_signed_contract_import_pending_signature_required';
  end if;

  insert into public.customer_contract_documents(
    company_id,
    customer_contract_id,
    document_type,
    storage_bucket,
    storage_path,
    mime_type,
    document_sha256,
    generated_at,
    generation_snapshot,
    verified_at
  ) values (
    new.company_id,
    new.customer_contract_id,
    'signed_contract_pdf',
    new.storage_bucket,
    new.file_path,
    coalesce(nullif(new.mime_type, ''), 'application/pdf'),
    new.file_checksum,
    coalesce(new.uploaded_at, now()),
    jsonb_build_object(
      'schema', 'gridex_imported_signed_contract_document_v1',
      'source', 'admin_customer_intake',
      'authorization_document_id', new.id,
      'customer_id', new.customer_id,
      'contract_id', new.customer_contract_id,
      'imported_by', new.created_by,
      'document_sha256', new.file_checksum
    ),
    now()
  )
  on conflict (customer_contract_id, document_type, document_sha256)
  do nothing;

  select d.id into v_contract_document_id
  from public.customer_contract_documents d
  where d.company_id = new.company_id
    and d.customer_contract_id = new.customer_contract_id
    and d.document_type = 'signed_contract_pdf'
    and d.document_sha256 = new.file_checksum
    and d.storage_bucket = new.storage_bucket
    and d.storage_path = new.file_path
    and d.verified_at is not null;
  if v_contract_document_id is null then
    raise exception using
      errcode = '23514',
      message = 'admin_signed_contract_import_document_binding_failed';
  end if;

  select * into v_customer
  from public.customers
  where id = v_contract.customer_id
    and company_id = v_contract.company_id;
  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'admin_signed_contract_import_customer_not_found';
  end if;

  v_accepted_at := coalesce(new.uploaded_at, now());
  v_signature := jsonb_build_object(
    'schema', 'gridex_imported_signed_contract_v1',
    'company_id', v_contract.company_id,
    'customer_id', v_contract.customer_id,
    'contract_id', v_contract.id,
    'channel', 'admin',
    'signing_method', 'imported_signed_document',
    'recorded_at', v_accepted_at,
    'original_signature_timestamp', null,
    'timestamp_semantics', 'administrative_import_time_original_signature_time_not_supplied',
    'contract_number', v_contract.contract_number,
    'offer_reference', v_contract.offer_reference,
    'contract_publication_version_id', v_contract.contract_publication_version_id,
    'contract_product_version_id', v_contract.contract_product_version_id,
    'price_plan_version_id', v_contract.price_plan_version_id,
    'legal_bundle_version_id', v_contract.legal_bundle_version_id,
    'contract_price_snapshot_id', v_snapshot_id,
    'pricing_snapshot_sha256', v_price.snapshot_hash,
    'signed_contract_document_id', v_contract_document_id,
    'signed_document_sha256', new.file_checksum,
    'source_authorization_document_id', new.id,
    'imported_by', new.created_by,
    'legal_versions', v_legal_versions
  );
  v_signature_hash := encode(
    extensions.digest(convert_to(v_signature::text, 'UTF8'), 'sha256'),
    'hex'
  );
  v_acceptance := jsonb_build_object(
    'schema', 'gridex_contract_acceptance_v1',
    'contract_id', v_contract.id,
    'accepted_at', v_accepted_at,
    'channel', 'admin',
    'signing_method', 'imported_signed_document',
    'signature_snapshot_sha256', v_signature_hash,
    'pricing_snapshot_sha256', v_price.snapshot_hash,
    'signed_document_sha256', new.file_checksum,
    'source_authorization_document_id', new.id,
    'legal_versions', v_legal_versions
  );
  v_acceptance_hash := encode(
    extensions.digest(convert_to(v_acceptance::text, 'UTF8'), 'sha256'),
    'hex'
  );

  insert into public.customer_contract_acceptances(
    company_id,
    customer_contract_id,
    contract_publication_version_id,
    accepted_at,
    channel,
    signing_method,
    customer_identity_snapshot,
    power_of_attorney_snapshot,
    acceptance_snapshot,
    acceptance_sha256
  ) values (
    v_contract.company_id,
    v_contract.id,
    v_contract.contract_publication_version_id,
    v_accepted_at,
    'admin',
    'imported_signed_document',
    jsonb_strip_nulls(jsonb_build_object(
      'customer_id', v_customer.id,
      'customer_number', coalesce(v_contract.customer_number, v_customer.customer_number),
      'email', v_customer.email,
      'customer_type', v_customer.customer_type
    )),
    '{}'::jsonb,
    v_acceptance,
    v_acceptance_hash
  )
  on conflict (customer_contract_id, acceptance_sha256) do nothing;

  insert into public.customer_contract_evidence(
    company_id,
    customer_contract_id,
    evidence_type,
    evidence_snapshot,
    evidence_sha256,
    captured_at
  ) values (
    v_contract.company_id,
    v_contract.id,
    'imported_signed_contract',
    v_signature,
    v_signature_hash,
    v_accepted_at
  )
  on conflict (customer_contract_id, evidence_type, evidence_sha256) do nothing;

  insert into public.customer_legal_acceptances(
    company_id,
    customer_id,
    contract_id,
    acceptance_type,
    legal_text_version_id,
    legal_bundle_id,
    legal_bundle_version_document_id,
    legal_module_key,
    legal_document_version,
    legal_document_sha256,
    accepted_at,
    source,
    snapshot,
    metadata,
    created_by,
    reason
  )
  select
    v_contract.company_id,
    v_contract.customer_id,
    v_contract.id,
    case public.gridex_legacy_legal_type_for_module(d.module_key)
      when 'privacy_policy' then 'privacy_policy'
      when 'withdrawal' then 'withdrawal_info'
      when 'power_of_attorney' then 'power_of_attorney'
      when 'price_terms' then 'price_snapshot'
      else 'terms'
    end,
    null,
    lbv.legal_bundle_id,
    d.id,
    d.module_key,
    coalesce(d.template_version, left(d.content_sha256, 12)),
    d.content_sha256,
    v_accepted_at,
    'admin_manual',
    jsonb_build_object(
      'source_authorization_document_id', new.id,
      'signed_document_sha256', new.file_checksum,
      'signature_snapshot_sha256', v_signature_hash
    ),
    jsonb_build_object(
      'signing_method', 'imported_signed_document',
      'pricing_snapshot_sha256', v_price.snapshot_hash,
      'original_signature_timestamp', null,
      'timestamp_semantics', 'administrative_import_time_original_signature_time_not_supplied'
    ),
    new.created_by,
    'Importerat signerat avtal verifierat mot uppladdat PDF-dokument och SHA-256.'
  from public.legal_bundle_version_documents d
  join public.legal_bundle_versions lbv
    on lbv.id = d.legal_bundle_version_id
  where d.legal_bundle_version_id = v_contract.legal_bundle_version_id
  on conflict do nothing;

  -- Any previously prepared online link is no longer valid after an imported
  -- signed document becomes authoritative.
  update public.customer_contract_signature_requests
  set revoked_at = coalesce(revoked_at, now())
  where company_id = v_contract.company_id
    and customer_contract_id = v_contract.id
    and used_at is null
    and revoked_at is null;

  update public.customer_contracts
  set status = 'signed',
      signed_at = v_accepted_at,
      legal_versions_snapshot = v_legal_versions,
      signature_snapshot = v_signature,
      signature_snapshot_sha256 = v_signature_hash,
      locked_at = v_accepted_at,
      lifecycle_stage = 'agreement_signed',
      signed_version = coalesce(terms_version, contract_version, 'v1'),
      terms_signed_version = coalesce(terms_version, 'v1'),
      document_sha256 = new.file_checksum,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'signature_status', 'signed',
        'signature_method', 'imported_signed_document',
        'source_authorization_document_id', new.id,
        'signed_contract_document_id', v_contract_document_id,
        'signature_snapshot_sha256', v_signature_hash,
        'pricing_snapshot_sha256', v_price.snapshot_hash,
        'original_signature_timestamp', null,
        'timestamp_semantics', 'administrative_import_time_original_signature_time_not_supplied'
      ),
      updated_by = new.created_by,
      updated_at = now()
  where id = v_contract.id and company_id = v_contract.company_id
  returning * into v_contract;

  v_event := public.gridex_record_customer_contract_event_v1(
    v_contract.company_id,
    v_contract.id,
    v_contract.customer_id,
    'signed',
    v_accepted_at,
    'Signerat avtal importerat och verifierat av administratör',
    jsonb_build_object(
      'source_authorization_document_id', new.id,
      'signed_contract_document_id', v_contract_document_id,
      'signed_document_sha256', new.file_checksum,
      'signature_snapshot_sha256', v_signature_hash,
      'pricing_snapshot_sha256', v_price.snapshot_hash,
      'channel', 'admin',
      'signing_method', 'imported_signed_document'
    ),
    new.created_by,
    null,
    encode(
      extensions.digest(
        convert_to((new.id::text || ':imported_signed_contract'), 'UTF8'),
        'sha256'
      ),
      'hex'
    )
  );

  return new;
end
$_$;

--
-- Name: gridex_finalize_contract_publication_v1(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_finalize_contract_publication_v1(p_publication_version_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_allow_locked_metadata_repair boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v public.contract_publication_versions%rowtype;
  v_company_id uuid;
  v_channel text;
  v_blockers text[];
  v_price_options jsonb;
  v_legal_snapshot jsonb;
  v_snapshot jsonb;
  v_hash text;
  v_before jsonb;
  v_invoice_fee_sek numeric;
begin
  select pv.* into v
  from public.contract_publication_versions pv
  where pv.id=p_publication_version_id
  for update;

  select a.company_id,p.channel into v_company_id,v_channel
  from public.contract_publications p
  join public.tenant_contract_assignments a on a.id=p.assignment_id
  where p.id=v.contract_publication_id;
  if not found then
    raise exception using errcode='P0002',
      message='PUBLICATION_VERSION_NOT_FOUND';
  end if;
  if v.locked_at is not null and not p_allow_locked_metadata_repair then
    raise exception using errcode='55000',
      message='PUBLICATION_VERSION_NOT_LOCKED_FOR_REPAIR';
  end if;
  v_before:=to_jsonb(v);

  select offer.invoice_fee_sek into v_invoice_fee_sek
  from public.contract_offers offer
  where offer.company_id=v_company_id
    and offer.id::text=v.publication_snapshot->>'source_contract_offer_id';

  if v_invoice_fee_sek is not null then
    v_snapshot:=public.gridex_canonicalize_publication_invoice_fee_v1(
      v.publication_snapshot,
      v_invoice_fee_sek
    );
    if v_snapshot is distinct from v.publication_snapshot then
      if v.locked_at is not null then
        perform set_config('gridex.version_transition','on',true);
        perform set_config('gridex.publication_graph_repair','on',true);
      end if;
      v_hash:=encode(extensions.digest(v_snapshot::text,'sha256'),'hex');
      update public.contract_publication_versions
      set publication_snapshot=v_snapshot,content_sha256=v_hash
      where id=v.id;
      if v.locked_at is not null then
        perform set_config('gridex.publication_graph_repair','off',true);
      end if;
      v.publication_snapshot:=v_snapshot;
      v.content_sha256:=v_hash;
    end if;
  end if;

  perform public.gridex_materialize_publication_price_options_v1(
    v.id,p_actor_user_id
  );
  v_blockers:=public.gridex_validate_publication_graph_v1(v.id);
  if cardinality(v_blockers)>0 then
    raise exception using errcode='23514',
      message=coalesce(v_blockers[1],'PUBLICATION_SNAPSHOT_INVALID'),
      detail=to_jsonb(v_blockers)::text;
  end if;

  v_price_options:=public.gridex_publication_price_options_json_v1(v.id);
  select jsonb_build_object(
    'legal_bundle_version_id',b.id,
    'status',b.status,
    'content_sha256',b.content_sha256,
    'documents',coalesce((select jsonb_agg(jsonb_build_object(
      'module_key',d.module_key,'content_sha256',d.content_sha256
    ) order by d.sort_order,d.module_key)
      from public.legal_bundle_version_documents d
      where d.legal_bundle_version_id=b.id),'[]'::jsonb)
  ) into v_legal_snapshot
  from public.legal_bundle_versions b
  where b.id=v.legal_bundle_version_id;

  select publication_snapshot into v_snapshot
  from public.contract_publication_versions
  where id=v.id;

  v_snapshot:=coalesce(v_snapshot,'{}'::jsonb)
    ||jsonb_build_object(
      'schema','gridex_contract_publication_v6',
      'channel',v_channel,
      'offer_reference',v.offer_reference,
      'price_options',v_price_options,
      'supported_price_areas',to_jsonb(
        public.gridex_supported_price_areas_v1(
          v.contract_product_version_id
        )
      ),
      'legal_snapshot',coalesce(v_legal_snapshot,'{}'::jsonb)
    );
  v_hash:=encode(extensions.digest(v_snapshot::text,'sha256'),'hex');

  perform set_config('gridex.version_transition','on',true);
  if v.locked_at is not null then
    perform set_config('gridex.publication_graph_repair','on',true);
  end if;
  update public.contract_publication_versions
  set publication_snapshot=v_snapshot,content_sha256=v_hash,
      status='published',published_at=coalesce(published_at,now()),
      locked_at=coalesce(locked_at,now())
  where id=v.id;
  if v.locked_at is not null then
    perform set_config('gridex.publication_graph_repair','off',true);
  end if;
  update public.contract_publications
  set status='published',updated_at=now()
  where id=v.contract_publication_id;

  insert into public.audit_logs(
    company_id,actor_user_id,entity_type,entity_id,action,
    old_values,new_values,metadata
  ) values(
    v_company_id,p_actor_user_id,'contract_publication_version',v.id::text,
    case when v.locked_at is null then 'contract_publication_finalized'
      else 'contract_publication_graph_repaired' end,
    v_before,(select to_jsonb(current_row)
      from public.contract_publication_versions current_row
      where current_row.id=v.id),
    jsonb_build_object(
      'channel',v_channel,
      'commercial_values_changed',false,
      'invoice_fee_canonicalized',v_invoice_fee_sek is not null
    )
  );

  return jsonb_build_object('ok',true,'publication_version_id',v.id,
    'channel',v_channel,'content_sha256',v_hash,
    'price_options',v_price_options,'blockers','[]'::jsonb);
end
$$;

--
-- Name: FUNCTION gridex_finalize_contract_publication_v1(p_publication_version_id uuid, p_actor_user_id uuid, p_allow_locked_metadata_repair boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_finalize_contract_publication_v1(p_publication_version_id uuid, p_actor_user_id uuid, p_allow_locked_metadata_repair boolean) IS 'Finalizes the exact contract publication graph and repairs derived invoice-fee snapshot materialization before fail-closed validation.';

--
-- Name: gridex_finalize_customer_contract_signature_v1(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_finalize_customer_contract_signature_v1(p_token_hash text, p_signed_ip_hash text DEFAULT NULL::text, p_signed_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
declare
  v_request public.customer_contract_signature_requests%rowtype;
  v_contract public.customer_contracts%rowtype;
  v_customer public.customers%rowtype;
  v_company public.companies%rowtype;
  v_price public.contract_price_snapshots%rowtype;
  v_legal_versions jsonb;
  v_signature jsonb;
  v_signature_hash text;
  v_acceptance jsonb;
  v_acceptance_hash text;
  v_customer_type text;
  v_withdrawal_required boolean;
  v_withdrawal_deadline timestamptz;
  v_event jsonb;
begin
  if coalesce(p_token_hash,'') !~ '^[0-9a-f]{64}$' then raise exception using errcode='22023',message='signature_token_invalid'; end if;
  select * into v_request from public.customer_contract_signature_requests where token_hash=p_token_hash for update;
  if not found then raise exception using errcode='P0002',message='signature_link_not_found'; end if;
  select * into v_contract from public.customer_contracts where id=v_request.customer_contract_id and company_id=v_request.company_id for update;
  if v_request.used_at is not null then
    if v_contract.status in ('signed','active','terminated','cancelled','expired') and v_contract.signed_at is not null then
      return public.gridex_get_customer_contract_signature_receipt_v1(p_token_hash) || jsonb_build_object('already_signed',true);
    end if;
    raise exception using errcode='55000',message='signature_link_already_used';
  end if;
  if v_request.revoked_at is not null then raise exception using errcode='55000',message='signature_link_revoked'; end if;
  if v_request.expires_at<=now() then raise exception using errcode='55000',message='signature_link_expired'; end if;
  select * into v_company from public.companies where id=v_request.company_id for share;
  if not found or not coalesce(v_company.is_active,false) or coalesce(v_company.lifecycle_status,'')<>'active' or v_company.suspended_at is not null then
    raise exception using errcode='55000',message='signature_tenant_not_operational';
  end if;
  if v_contract.status<>'pending_signature' or v_contract.signed_at is not null then
    raise exception using errcode='23514',message='contract_not_pending_signature';
  end if;
  select * into v_customer from public.customers where id=v_contract.customer_id and company_id=v_contract.company_id;
  select * into v_price from public.contract_price_snapshots where id=v_contract.contract_price_snapshot_id and company_id=v_contract.company_id and contract_id=v_contract.id;
  if not found or nullif(v_price.snapshot_hash,'') is null then raise exception using errcode='23514',message='signature_pricing_snapshot_missing'; end if;

  if not exists(
    select 1 from public.contract_publication_versions cpv
    join public.contract_publications cp on cp.id=cpv.contract_publication_id
    join public.tenant_contract_assignments ta on ta.id=cp.assignment_id and ta.company_id=v_contract.company_id
    join public.contract_product_versions ctv on ctv.id=cpv.contract_product_version_id
    join public.price_plan_versions ppv on ppv.id=cpv.price_plan_version_id
    join public.legal_bundle_versions lbv on lbv.id=cpv.legal_bundle_version_id
    where cpv.id=v_contract.contract_publication_version_id
      and cpv.contract_product_version_id=v_contract.contract_product_version_id
      and cpv.price_plan_version_id=v_contract.price_plan_version_id
      and cpv.legal_bundle_version_id=v_contract.legal_bundle_version_id
      and cpv.status='published' and cpv.locked_at is not null
      and ctv.status='approved' and ctv.locked_at is not null
      and ppv.status in ('published','approved','active') and ppv.locked_at is not null
      and lbv.status='published' and lbv.locked_at is not null and cardinality(lbv.unresolved_variables)=0
  ) then raise exception using errcode='23514',message='signature_exact_locked_chain_invalid'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'legal_bundle_version_document_id',d.id,'module_key',d.module_key,'title',d.title,
    'legal_document_version',coalesce(d.template_version,left(d.content_sha256,12)),
    'document_sha256',d.content_sha256,'body_sha256',d.content_sha256
  ) order by d.sort_order,d.id),'[]'::jsonb)
  into v_legal_versions from public.legal_bundle_version_documents d where d.legal_bundle_version_id=v_contract.legal_bundle_version_id;
  if jsonb_array_length(v_legal_versions)=0 then raise exception using errcode='23514',message='signature_legal_document_set_missing'; end if;

  v_signature:=jsonb_build_object(
    'schema','gridex_online_contract_signature_v1','company_id',v_contract.company_id,'customer_id',v_contract.customer_id,
    'contract_id',v_contract.id,'signature_request_id',v_request.id,'channel',v_request.channel,'accepted_at',now(),
    'recipient_email',v_request.recipient_email,'contract_number',v_contract.contract_number,'offer_reference',v_contract.offer_reference,
    'contract_publication_version_id',v_contract.contract_publication_version_id,'contract_product_version_id',v_contract.contract_product_version_id,
    'price_plan_version_id',v_contract.price_plan_version_id,'legal_bundle_version_id',v_contract.legal_bundle_version_id,
    'contract_price_snapshot_id',v_contract.contract_price_snapshot_id,'pricing_snapshot_sha256',v_price.snapshot_hash,
    'legal_versions',v_legal_versions,'tenant_communication_snapshot_sha256',v_contract.tenant_communication_snapshot_sha256,
    'request_evidence',jsonb_build_object('ip_hash',p_signed_ip_hash,'user_agent',left(p_signed_user_agent,1000))
  );
  v_signature_hash:=encode(extensions.digest(convert_to(v_signature::text,'UTF8'),'sha256'),'hex');
  v_acceptance:=jsonb_build_object(
    'schema','gridex_contract_acceptance_v1','signature_request_id',v_request.id,'contract_id',v_contract.id,
    'accepted_at',v_signature->>'accepted_at','channel',v_request.channel,'signing_method','secure_link_click',
    'signature_snapshot_sha256',v_signature_hash,'pricing_snapshot_sha256',v_price.snapshot_hash,'legal_versions',v_legal_versions
  );
  v_acceptance_hash:=encode(extensions.digest(convert_to(v_acceptance::text,'UTF8'),'sha256'),'hex');

  insert into public.customer_legal_acceptances(
    company_id,customer_id,contract_id,acceptance_type,legal_text_version_id,
    legal_bundle_version_document_id,legal_module_key,legal_document_version,legal_document_sha256,
    accepted_at,accepted_ip_hash,accepted_user_agent,source,snapshot,metadata
  )
  select v_contract.company_id,v_contract.customer_id,v_contract.id,
    case public.gridex_legacy_legal_type_for_module(d.module_key)
      when 'privacy_policy' then 'privacy_policy' when 'withdrawal' then 'withdrawal_info'
      when 'power_of_attorney' then 'power_of_attorney' when 'price_terms' then 'price_snapshot' else 'terms' end,
    null,d.id,d.module_key,coalesce(d.template_version,left(d.content_sha256,12)),d.content_sha256,
    (v_signature->>'accepted_at')::timestamptz,p_signed_ip_hash,left(p_signed_user_agent,1000),'customer_portal',
    jsonb_build_object('signature_request_id',v_request.id,'signature_snapshot_sha256',v_signature_hash),
    jsonb_build_object('channel',v_request.channel,'pricing_snapshot_sha256',v_price.snapshot_hash)
  from public.legal_bundle_version_documents d where d.legal_bundle_version_id=v_contract.legal_bundle_version_id
  on conflict do nothing;

  insert into public.customer_contract_acceptances(
    company_id,customer_contract_id,contract_publication_version_id,accepted_at,channel,signing_method,
    ip_hash,user_agent,customer_identity_snapshot,power_of_attorney_snapshot,acceptance_snapshot,acceptance_sha256
  ) values(
    v_contract.company_id,v_contract.id,v_contract.contract_publication_version_id,(v_signature->>'accepted_at')::timestamptz,
    v_request.channel,'secure_link_click',p_signed_ip_hash,left(p_signed_user_agent,1000),
    jsonb_strip_nulls(jsonb_build_object('customer_id',v_customer.id,'customer_number',coalesce(v_contract.customer_number,v_customer.customer_number),'email',v_customer.email,'customer_type',v_customer.customer_type)),
    '{}',v_acceptance,v_acceptance_hash
  ) on conflict (customer_contract_id,acceptance_sha256) do nothing;

  insert into public.customer_contract_evidence(company_id,customer_contract_id,evidence_type,evidence_snapshot,evidence_sha256,captured_at)
  values(v_contract.company_id,v_contract.id,'online_acceptance',v_signature,v_signature_hash,(v_signature->>'accepted_at')::timestamptz)
  on conflict (customer_contract_id,evidence_type,evidence_sha256) do nothing;

  select coalesce(v_customer.customer_type,'private') into v_customer_type;
  select exists(select 1 from public.legal_bundle_version_documents d where d.legal_bundle_version_id=v_contract.legal_bundle_version_id and d.module_key in ('withdrawal','withdrawal_right','withdrawal_form','distance_contract_information','pre_contract_information')) into v_withdrawal_required;
  v_withdrawal_deadline:=case when v_customer_type='private' and v_withdrawal_required then (v_signature->>'accepted_at')::timestamptz+interval '14 days' else null end;

  update public.customer_contracts set
    status='signed',signed_at=(v_signature->>'accepted_at')::timestamptz,
    is_distance_agreement=true,withdrawal_deadline_at=v_withdrawal_deadline,
    legal_versions_snapshot=v_legal_versions,signature_snapshot=v_signature,signature_snapshot_sha256=v_signature_hash,
    signed_ip_hash=p_signed_ip_hash,signed_user_agent=left(p_signed_user_agent,1000),locked_at=(v_signature->>'accepted_at')::timestamptz,
    lifecycle_stage='agreement_signed',signed_version=coalesce(terms_version,contract_version,'v1'),terms_signed_version=coalesce(terms_version,'v1'),
    metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('signature_status','signed','signature_method','secure_link_click','signature_request_id',v_request.id,'signature_snapshot_sha256',v_signature_hash,'pricing_snapshot_sha256',v_price.snapshot_hash),
    updated_at=now()
  where id=v_contract.id and company_id=v_contract.company_id
  returning * into v_contract;

  update public.customer_contract_signature_requests set used_at=(v_signature->>'accepted_at')::timestamptz where id=v_request.id;

  v_event:=public.gridex_record_customer_contract_event_v1(
    v_contract.company_id,v_contract.id,v_contract.customer_id,'signed',(v_signature->>'accepted_at')::timestamptz,
    'Avtal signerat online via säker engångslänk',
    jsonb_build_object('signature_request_id',v_request.id,'signature_snapshot_sha256',v_signature_hash,'pricing_snapshot_sha256',v_price.snapshot_hash,'channel',v_request.channel),
    null,null,
    encode(extensions.digest(convert_to((v_request.id::text||':signed'),'UTF8'),'sha256'),'hex')
  );

  return public.gridex_get_customer_contract_signature_receipt_v1(p_token_hash) || jsonb_build_object('already_signed',false,'withdrawal_deadline_at',v_withdrawal_deadline);
end
$_$;

--
-- Name: gridex_finalize_supplier_switch_activation(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_finalize_supplier_switch_activation(p_company_id uuid, p_request_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request public.supplier_switch_requests%rowtype;
  v_site public.customer_sites%rowtype;
  v_point public.metering_points%rowtype;
  v_effective_date date;
  v_market_date date := (now() at time zone 'Europe/Stockholm')::date;
  v_now timestamptz := now();
begin
  if p_company_id is null or p_request_id is null or p_actor_user_id is null then
    raise exception 'supplier_switch_activation_scope_required';
  end if;

  select *
  into v_request
  from public.supplier_switch_requests
  where id = p_request_id
    and company_id = p_company_id
  for update;

  if not found then
    return jsonb_build_object(
      'status', 'not_found',
      'reason_code', 'supplier_switch_not_found_in_tenant'
    );
  end if;

  if v_request.status = 'completed' then
    return jsonb_build_object(
      'status', 'already_completed',
      'request_id', v_request.id,
      'company_id', v_request.company_id,
      'effective_start_date', coalesce(v_request.confirmed_start_date, v_request.requested_start_date),
      'market_date', v_market_date
    );
  end if;

  if v_request.status <> 'accepted' then
    return jsonb_build_object(
      'status', 'blocked',
      'reason_code', 'supplier_switch_not_accepted',
      'request_status', v_request.status
    );
  end if;

  if coalesce(v_request.lifecycle_blocked, false) then
    return jsonb_build_object(
      'status', 'blocked',
      'reason_code', 'supplier_switch_lifecycle_blocked'
    );
  end if;

  if v_request.inbound_z04_message_id is null then
    return jsonb_build_object(
      'status', 'blocked',
      'reason_code', 'missing_z04_confirmation'
    );
  end if;

  if not exists (
    select 1
    from public.ediel_messages m
    where m.id = v_request.inbound_z04_message_id
      and m.company_id = p_company_id
      and m.direction = 'inbound'
      and m.message_family = 'PRODAT'
      and m.message_code = 'Z04'
  ) then
    return jsonb_build_object(
      'status', 'blocked',
      'reason_code', 'invalid_z04_confirmation'
    );
  end if;

  v_effective_date := coalesce(v_request.confirmed_start_date, v_request.requested_start_date);

  if v_effective_date is null then
    return jsonb_build_object(
      'status', 'blocked',
      'reason_code', 'missing_effective_start_date'
    );
  end if;

  if v_effective_date > v_market_date then
    return jsonb_build_object(
      'status', 'waiting',
      'reason_code', 'awaiting_effective_start_date',
      'effective_start_date', v_effective_date,
      'market_date', v_market_date
    );
  end if;

  select *
  into v_site
  from public.customer_sites
  where id = v_request.site_id
    and company_id = p_company_id
    and customer_id = v_request.customer_id
  for update;

  if not found then
    raise exception 'supplier_switch_site_tenant_mismatch';
  end if;

  if v_site.status = 'closed' then
    return jsonb_build_object(
      'status', 'blocked',
      'reason_code', 'supplier_switch_site_closed'
    );
  end if;

  if v_request.metering_point_id is not null then
    select *
    into v_point
    from public.metering_points
    where id = v_request.metering_point_id
      and company_id = p_company_id
      and site_id = v_request.site_id
      and (customer_id is null or customer_id = v_request.customer_id)
    for update;

    if not found then
      raise exception 'supplier_switch_metering_point_tenant_mismatch';
    end if;

    if v_point.status = 'closed' then
      return jsonb_build_object(
        'status', 'blocked',
        'reason_code', 'supplier_switch_metering_point_closed'
      );
    end if;
  end if;

  update public.customer_sites
  set current_supplier_name = v_request.incoming_supplier_name,
      current_supplier_org_number = v_request.incoming_supplier_org_number,
      status = 'active',
      grid_owner_id = coalesce(grid_owner_id, v_request.grid_owner_id),
      price_area_code = coalesce(price_area_code, v_request.price_area_code),
      updated_by = p_actor_user_id,
      updated_at = v_now
  where id = v_site.id
    and company_id = p_company_id
    and customer_id = v_request.customer_id;

  if v_request.metering_point_id is not null then
    update public.metering_points
    set status = 'active',
        grid_owner_id = coalesce(grid_owner_id, v_request.grid_owner_id),
        price_area_code = coalesce(price_area_code, v_request.price_area_code),
        updated_by = p_actor_user_id,
        updated_at = v_now
    where id = v_point.id
      and company_id = p_company_id
      and site_id = v_request.site_id;
  end if;

  update public.supplier_switch_requests
  set status = 'completed',
      completed_at = v_now,
      failure_reason = null,
      updated_by = p_actor_user_id,
      updated_at = v_now
  where id = v_request.id
    and company_id = p_company_id
    and status = 'accepted';

  if not found then
    raise exception 'supplier_switch_activation_state_changed';
  end if;

  insert into public.supplier_switch_events (
    company_id,
    switch_request_id,
    event_type,
    event_status,
    message,
    payload,
    created_by
  )
  values (
    p_company_id,
    v_request.id,
    'execution_completed',
    'completed',
    'Leveransen aktiverades automatiskt efter korrelerad inbound PRODAT Z04 och uppnått startdatum.',
    jsonb_build_object(
      'executionSource', 'automation_sweep',
      'effectiveStartDate', v_effective_date,
      'marketDate', v_market_date,
      'previousSupplierName', v_request.current_supplier_name,
      'newSupplierName', v_request.incoming_supplier_name,
      'siteId', v_request.site_id,
      'meteringPointId', v_request.metering_point_id,
      'inboundZ04MessageId', v_request.inbound_z04_message_id
    ),
    p_actor_user_id
  );

  return jsonb_build_object(
    'status', 'activated',
    'request_id', v_request.id,
    'company_id', p_company_id,
    'customer_id', v_request.customer_id,
    'site_id', v_request.site_id,
    'metering_point_id', v_request.metering_point_id,
    'effective_start_date', v_effective_date,
    'market_date', v_market_date
  );
end;
$$;

--
-- Name: gridex_finalize_website_contract_signature(uuid, uuid, uuid, uuid, text, timestamp with time zone, jsonb, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_finalize_website_contract_signature(p_company_id uuid, p_contract_id uuid, p_application_id uuid, p_public_contract_offer_id uuid, p_offer_reference text, p_accepted_at timestamp with time zone, p_legal_versions jsonb, p_signature_snapshot jsonb, p_signature_snapshot_sha256 text, p_signed_ip_hash text DEFAULT NULL::text, p_signed_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_contract public.customer_contracts%rowtype;
  v_customer_type text;
  v_expected_count integer;
  v_submitted_count integer;
  v_withdrawal_required boolean;
  v_withdrawal_deadline timestamptz;
begin
  if p_company_id is null or p_contract_id is null or p_application_id is null or p_accepted_at is null then
    raise exception using errcode='22023',message='company_contract_application_and_acceptance_time_required';
  end if;
  if jsonb_typeof(coalesce(p_legal_versions,'null'::jsonb))<>'array' then
    raise exception using errcode='22023',message='legal_versions_must_be_array';
  end if;

  select * into v_contract from public.customer_contracts
  where id=p_contract_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='customer_contract_not_found_for_tenant'; end if;
  if v_contract.public_contract_offer_id<>p_public_contract_offer_id
     or v_contract.offer_reference is distinct from p_offer_reference
     or v_contract.contract_publication_version_id is null then
    raise exception using errcode='23514',message='contract_not_bound_to_exact_publication';
  end if;

  select coalesce(c.customer_type,'private') into v_customer_type
  from public.customers c where c.id=v_contract.customer_id and c.company_id=p_company_id;
  v_customer_type:=coalesce(v_customer_type,'private');

  with expected as (
    select distinct public.gridex_legacy_legal_type_for_module(d.module_key) legal_type,
           d.legacy_legal_text_version_id legal_id
    from public.legal_bundle_version_documents d
    where d.legal_bundle_version_id=v_contract.legal_bundle_version_id
      and d.legacy_legal_text_version_id is not null
  ) select count(*) into v_expected_count from expected;
  if v_expected_count=0 then raise exception using errcode='23514',message='exact_legal_document_set_missing'; end if;

  with submitted as (
    select distinct item->>'type' legal_type,(item->>'id')::uuid legal_id
    from jsonb_array_elements(p_legal_versions) item
    where nullif(item->>'type','') is not null and nullif(item->>'id','') is not null
  ) select count(*) into v_submitted_count from submitted;
  if v_submitted_count<>v_expected_count or exists (
    with expected as (
      select distinct public.gridex_legacy_legal_type_for_module(d.module_key) legal_type,
             d.legacy_legal_text_version_id legal_id
      from public.legal_bundle_version_documents d
      where d.legal_bundle_version_id=v_contract.legal_bundle_version_id
        and d.legacy_legal_text_version_id is not null
    ), submitted as (
      select distinct item->>'type' legal_type,(item->>'id')::uuid legal_id
      from jsonb_array_elements(p_legal_versions) item
      where nullif(item->>'type','') is not null and nullif(item->>'id','') is not null
    )
    select 1 from expected e full join submitted s using(legal_type,legal_id)
    where e.legal_id is null or s.legal_id is null
  ) then
    raise exception using errcode='23514',message='submitted_legal_versions_do_not_match_exact_publication';
  end if;

  if exists (
    with expected as (
      select distinct public.gridex_legacy_legal_type_for_module(d.module_key) legal_type,
             d.legacy_legal_text_version_id legal_id
      from public.legal_bundle_version_documents d
      where d.legal_bundle_version_id=v_contract.legal_bundle_version_id
        and d.legacy_legal_text_version_id is not null
    )
    select 1 from expected e
    where not exists (
      select 1 from public.customer_legal_acceptances a
      where a.company_id=p_company_id and a.contract_id=p_contract_id
        and a.contract_application_id=p_application_id and a.legal_text_version_id=e.legal_id
        and a.accepted_at=p_accepted_at
        and a.acceptance_type=case e.legal_type
          when 'terms' then 'terms' when 'privacy_policy' then 'privacy_policy'
          when 'withdrawal' then 'withdrawal_info' when 'power_of_attorney' then 'power_of_attorney'
          when 'price_terms' then 'price_snapshot' end
    )
  ) then raise exception using errcode='23514',message='exact_legal_acceptance_evidence_incomplete'; end if;

  select exists(
    select 1 from public.legal_bundle_version_documents d
    where d.legal_bundle_version_id=v_contract.legal_bundle_version_id
      and public.gridex_legacy_legal_type_for_module(d.module_key)='withdrawal'
  ) into v_withdrawal_required;
  v_withdrawal_deadline:=case when v_customer_type='private' and v_withdrawal_required then p_accepted_at+interval '14 days' else null end;

  update public.customer_contracts set
    status='signed',signed_at=p_accepted_at,is_distance_agreement=true,
    withdrawal_deadline_at=v_withdrawal_deadline,legal_versions_snapshot=p_legal_versions,
    signature_snapshot=coalesce(p_signature_snapshot,'{}'::jsonb),
    signature_snapshot_sha256=p_signature_snapshot_sha256,signed_ip_hash=p_signed_ip_hash,
    signed_user_agent=left(p_signed_user_agent,1000),locked_at=p_accepted_at,
    metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
      'signature_status','signed','signature_finalized_at',now(),
      'signature_snapshot_sha256',p_signature_snapshot_sha256,
      'contract_publication_version_id',v_contract.contract_publication_version_id
    ),updated_at=now()
  where id=p_contract_id and company_id=p_company_id;

  return jsonb_build_object('contract_id',p_contract_id,'status','signed','signed_at',p_accepted_at,
    'withdrawal_deadline_at',v_withdrawal_deadline,'public_contract_offer_id',p_public_contract_offer_id,
    'offer_reference',p_offer_reference,'signature_snapshot_sha256',p_signature_snapshot_sha256);
end
$$;

--
-- Name: FUNCTION gridex_finalize_website_contract_signature(p_company_id uuid, p_contract_id uuid, p_application_id uuid, p_public_contract_offer_id uuid, p_offer_reference text, p_accepted_at timestamp with time zone, p_legal_versions jsonb, p_signature_snapshot jsonb, p_signature_snapshot_sha256 text, p_signed_ip_hash text, p_signed_user_agent text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_finalize_website_contract_signature(p_company_id uuid, p_contract_id uuid, p_application_id uuid, p_public_contract_offer_id uuid, p_offer_reference text, p_accepted_at timestamp with time zone, p_legal_versions jsonb, p_signature_snapshot jsonb, p_signature_snapshot_sha256 text, p_signed_ip_hash text, p_signed_user_agent text) IS 'Atomically marks a website contract signed only after exact offer-bound legal acceptance evidence exists.';

--
-- Name: gridex_finalize_website_contract_signature(uuid, uuid, uuid, uuid, text, timestamp with time zone, jsonb, jsonb, jsonb, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_finalize_website_contract_signature(p_company_id uuid, p_contract_id uuid, p_application_id uuid, p_public_contract_offer_id uuid, p_offer_reference text, p_accepted_at timestamp with time zone, p_legal_versions jsonb, p_signature_snapshot jsonb, p_acceptance_evidence jsonb, p_signature_snapshot_sha256 text, p_signed_ip_hash text DEFAULT NULL::text, p_signed_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_contract public.customer_contracts%rowtype;
  v_customer_type text;
  v_expected_count integer;
  v_submitted_count integer;
  v_withdrawal_required boolean;
  v_withdrawal_deadline timestamptz;
  v_signature_sha256 text;
begin
  if p_company_id is null or p_contract_id is null or p_application_id is null or p_accepted_at is null then
    raise exception using errcode='22023',message='company_contract_application_and_acceptance_time_required';
  end if;
  if jsonb_typeof(coalesce(p_legal_versions,'null'::jsonb))<>'array'
     or jsonb_typeof(coalesce(p_signature_snapshot,'null'::jsonb))<>'object'
     or jsonb_typeof(coalesce(p_acceptance_evidence,'null'::jsonb))<>'array' then
    raise exception using errcode='22023',message='signature_legal_versions_and_acceptances_must_be_structured_json';
  end if;

  select * into v_contract
  from public.customer_contracts
  where id=p_contract_id and company_id=p_company_id
  for update;
  if not found then
    raise exception using errcode='P0002',message='customer_contract_not_found_for_tenant';
  end if;

  if not exists(
    select 1 from public.website_customer_applications a
    where a.id=p_application_id and a.company_id=p_company_id
      and a.customer_id=v_contract.customer_id and a.contract_id=v_contract.id
      and a.public_contract_offer_id=p_public_contract_offer_id
      and a.offer_reference=p_offer_reference
  ) then
    raise exception using errcode='23514',message='website_application_contract_chain_mismatch';
  end if;

  if v_contract.public_contract_offer_id<>p_public_contract_offer_id
     or v_contract.offer_reference is distinct from p_offer_reference
     or v_contract.contract_publication_version_id is null
     or v_contract.contract_product_version_id is null
     or v_contract.price_plan_version_id is null
     or v_contract.legal_bundle_version_id is null
     or v_contract.contract_price_snapshot_id is null then
    raise exception using errcode='23514',message='contract_not_bound_to_exact_publication_chain';
  end if;

  if not exists(
    select 1
    from public.public_contract_offers o
    join public.contract_publication_versions cpv
      on cpv.id=v_contract.contract_publication_version_id
     and cpv.legacy_public_contract_offer_id=o.id
    join public.contract_product_versions ctv
      on ctv.id=cpv.contract_product_version_id
    join public.price_plan_versions ppv
      on ppv.id=cpv.price_plan_version_id
    join public.legal_bundle_versions lbv
      on lbv.id=cpv.legal_bundle_version_id
    join public.contract_price_snapshots cps
      on cps.id=v_contract.contract_price_snapshot_id
     and cps.contract_id=v_contract.id
     and cps.company_id=v_contract.company_id
    where o.id=p_public_contract_offer_id
      and o.company_id=p_company_id
      and cpv.offer_reference=p_offer_reference
      and cpv.status='published' and cpv.locked_at is not null
      and cpv.contract_product_version_id=v_contract.contract_product_version_id
      and cpv.price_plan_version_id=v_contract.price_plan_version_id
      and cpv.legal_bundle_version_id=v_contract.legal_bundle_version_id
      and ctv.status='approved' and ctv.locked_at is not null
      and ppv.status in('published','approved','active') and ppv.locked_at is not null
      and lbv.status='published' and lbv.locked_at is not null
      and cardinality(lbv.unresolved_variables)=0
      and cps.price_plan_version_id=v_contract.price_plan_version_id
      and nullif(cps.snapshot_hash,'') is not null
  ) then
    raise exception using errcode='23514',message='exact_locked_contract_chain_invalid';
  end if;

  select count(*) into v_expected_count
  from public.legal_bundle_version_documents d
  where d.legal_bundle_version_id=v_contract.legal_bundle_version_id;
  if v_expected_count=0 then
    raise exception using errcode='23514',message='exact_legal_document_set_missing';
  end if;

  with submitted as (
    select distinct
      coalesce(nullif(item->>'legal_bundle_version_document_id',''),nullif(item->>'id',''))::uuid document_id,
      coalesce(nullif(item->>'module_key',''),nullif(item->>'type','')) module_key,
      coalesce(nullif(item->>'document_sha256',''),nullif(item->>'body_sha256','')) document_sha256
    from jsonb_array_elements(p_legal_versions) item
  )
  select count(*) into v_submitted_count from submitted;

  if v_submitted_count<>v_expected_count or exists(
    with expected as (
    select d.id document_id,d.module_key,d.content_sha256 document_sha256
      from public.legal_bundle_version_documents d
      where d.legal_bundle_version_id=v_contract.legal_bundle_version_id
    ), submitted as (
      select distinct
        coalesce(nullif(item->>'legal_bundle_version_document_id',''),nullif(item->>'id',''))::uuid document_id,
        coalesce(nullif(item->>'module_key',''),nullif(item->>'type','')) module_key,
        coalesce(nullif(item->>'document_sha256',''),nullif(item->>'body_sha256','')) document_sha256
      from jsonb_array_elements(p_legal_versions) item
    )
    select 1
    from expected e full join submitted s
      on s.document_id=e.document_id
     and s.module_key=e.module_key
     and s.document_sha256=e.document_sha256
    where e.document_id is null or s.document_id is null
  ) then
    raise exception using errcode='23514',message='submitted_legal_versions_do_not_match_exact_publication';
  end if;

  if (select count(distinct nullif(item->>'legal_bundle_version_document_id','')::uuid)
      from jsonb_array_elements(p_acceptance_evidence) item)<>v_expected_count then
    raise exception using errcode='23514',message='acceptance_evidence_document_set_mismatch';
  end if;

  insert into public.customer_legal_acceptances(
    company_id,customer_id,contract_id,contract_application_id,acceptance_type,
    legal_text_version_id,legal_bundle_version_document_id,legal_module_key,
    legal_document_version,legal_document_sha256,request_id,trace_id,accepted_at,
    accepted_ip,accepted_ip_hash,accepted_user_agent,source,snapshot,metadata
  )
  select
    p_company_id,v_contract.customer_id,p_contract_id,p_application_id,
    case public.gridex_legacy_legal_type_for_module(d.module_key)
      when 'privacy_policy' then 'privacy_policy'
      when 'withdrawal' then 'withdrawal_info'
      when 'power_of_attorney' then 'power_of_attorney'
      when 'price_terms' then 'price_snapshot'
      else 'terms'
    end,
    null,d.id,d.module_key,nullif(item->>'legal_document_version',''),d.content_sha256,
    nullif(item->>'request_id',''),nullif(item->>'trace_id',''),p_accepted_at,
    nullif(item->>'accepted_ip',''),nullif(item->>'accepted_ip_hash',''),
    left(nullif(item->>'accepted_user_agent',''),1000),'website',
    coalesce(item->'snapshot','{}'::jsonb),coalesce(item->'metadata','{}'::jsonb)
  from jsonb_array_elements(p_acceptance_evidence) item
  join public.legal_bundle_version_documents d
    on d.id=nullif(item->>'legal_bundle_version_document_id','')::uuid
   and d.legal_bundle_version_id=v_contract.legal_bundle_version_id
   and d.module_key=nullif(item->>'legal_module_key','')
   and d.content_sha256=nullif(item->>'legal_document_sha256','')
  where nullif(item->>'legal_document_version','') is not null
  on conflict do nothing;

  if exists(
    select 1
    from public.legal_bundle_version_documents d
    where d.legal_bundle_version_id=v_contract.legal_bundle_version_id
      and not exists(
        select 1
        from public.customer_legal_acceptances a
        where a.company_id=p_company_id
          and a.customer_id=v_contract.customer_id
          and a.contract_id=p_contract_id
          and a.contract_application_id=p_application_id
          and a.legal_bundle_version_document_id=d.id
          and a.legal_module_key=d.module_key
          and a.legal_document_sha256=d.content_sha256
          and a.accepted_at=p_accepted_at
      )
  ) then
    raise exception using errcode='23514',message='exact_legal_acceptance_evidence_incomplete';
  end if;

  if coalesce(p_signature_snapshot->>'company_id','')<>p_company_id::text
     or coalesce(p_signature_snapshot->>'customer_id','')<>v_contract.customer_id::text
     or coalesce(p_signature_snapshot->>'contract_id','')<>p_contract_id::text
     or coalesce(p_signature_snapshot->>'application_id','')<>p_application_id::text
     or coalesce(p_signature_snapshot->>'public_contract_offer_id','')<>p_public_contract_offer_id::text
     or p_signature_snapshot->'legal_versions' is distinct from p_legal_versions
     or coalesce(p_signature_snapshot->>'contract_publication_version_id','')<>v_contract.contract_publication_version_id::text
     or coalesce(p_signature_snapshot->>'contract_product_version_id','')<>v_contract.contract_product_version_id::text
     or coalesce(p_signature_snapshot->>'price_plan_version_id','')<>v_contract.price_plan_version_id::text
     or coalesce(p_signature_snapshot->>'legal_bundle_version_id','')<>v_contract.legal_bundle_version_id::text
     or coalesce(p_signature_snapshot->>'contract_price_snapshot_id','')<>v_contract.contract_price_snapshot_id::text
     or coalesce(p_signature_snapshot->>'offer_reference','')<>p_offer_reference then
    raise exception using errcode='23514',message='signature_snapshot_chain_mismatch';
  end if;

  v_signature_sha256:=encode(
    extensions.digest(convert_to(p_signature_snapshot::text,'UTF8'),'sha256'),
    'hex'
  );

  select coalesce(c.customer_type,'private') into v_customer_type
  from public.customers c
  where c.id=v_contract.customer_id and c.company_id=p_company_id;
  select exists(
    select 1 from public.legal_bundle_version_documents d
    where d.legal_bundle_version_id=v_contract.legal_bundle_version_id
      and d.module_key in(
        'withdrawal','withdrawal_right','withdrawal_form',
        'distance_contract_information','pre_contract_information'
      )
  ) into v_withdrawal_required;
  v_withdrawal_deadline:=case
    when coalesce(v_customer_type,'private')='private' and v_withdrawal_required
      then p_accepted_at+interval '14 days'
    else null
  end;

  update public.customer_contracts set
    status='signed',signed_at=p_accepted_at,is_distance_agreement=true,
    withdrawal_deadline_at=v_withdrawal_deadline,
    legal_versions_snapshot=p_legal_versions,
    signature_snapshot=p_signature_snapshot,
    signature_snapshot_sha256=v_signature_sha256,
    signed_ip_hash=p_signed_ip_hash,
    signed_user_agent=left(p_signed_user_agent,1000),
    locked_at=p_accepted_at,
    lifecycle_stage='agreement_signed',
    metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
      'signature_status','signed',
      'signature_finalized_at',now(),
      'signature_snapshot_sha256',v_signature_sha256,
      'caller_signature_snapshot_sha256',p_signature_snapshot_sha256,
      'contract_publication_version_id',v_contract.contract_publication_version_id,
      'contract_product_version_id',v_contract.contract_product_version_id,
      'legal_bundle_version_id',v_contract.legal_bundle_version_id,
      'request_id',p_signature_snapshot#>>'{request_evidence,request_id}',
      'trace_id',p_signature_snapshot#>>'{request_evidence,trace_id}'
    ),updated_at=now()
  where id=p_contract_id and company_id=p_company_id;

  return jsonb_build_object(
    'contract_id',p_contract_id,
    'status','signed',
    'lifecycle_stage','agreement_signed',
    'signed_at',p_accepted_at,
    'withdrawal_deadline_at',v_withdrawal_deadline,
    'public_contract_offer_id',p_public_contract_offer_id,
    'offer_reference',p_offer_reference,
    'signature_snapshot_sha256',v_signature_sha256,
    'exact_legal_document_count',v_expected_count,
    'acceptance_ids',coalesce((
      select jsonb_object_agg(a.legal_bundle_version_document_id::text,a.id::text)
      from public.customer_legal_acceptances a
      where a.company_id=p_company_id and a.contract_id=p_contract_id
        and a.contract_application_id=p_application_id
        and a.accepted_at=p_accepted_at
        and a.legal_bundle_version_document_id is not null
    ),'{}'::jsonb)
  );
end
$$;

--
-- Name: gridex_fk_reference_blockers(regclass, uuid[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_fk_reference_blockers(p_target regclass, p_target_ids uuid[], p_ignored_relations text[] DEFAULT '{}'::text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $_$
declare
  fk record;
  v_count bigint;
  v_items jsonb:='[]'::jsonb;
begin
  if cardinality(coalesce(p_target_ids,'{}'::uuid[]))=0 then
    return jsonb_build_object('count',0,'items',v_items);
  end if;

  for fk in
    select
      c.conname,
      c.conrelid::regclass as relation_name,
      a.attname as column_name,
      c.confdeltype
    from pg_constraint c
    join pg_attribute a
      on a.attrelid=c.conrelid and a.attnum=c.conkey[1]
    where c.contype='f'
      and c.confrelid=p_target
      and cardinality(c.conkey)=1
      and cardinality(c.confkey)=1
      and c.confdeltype in ('a','r')
      and not (c.conrelid::regclass::text=any(coalesce(p_ignored_relations,'{}'::text[])))
    order by c.conrelid::regclass::text,c.conname
  loop
    execute format(
      'select count(*) from %s where %I=any($1)',
      fk.relation_name,
      fk.column_name
    ) into v_count using p_target_ids;
    if v_count>0 then
      v_items:=v_items||jsonb_build_array(jsonb_build_object(
        'constraint',fk.conname,
        'relation',fk.relation_name::text,
        'column',fk.column_name,
        'rows',v_count,
        'delete_rule',case fk.confdeltype when 'a' then 'NO ACTION' else 'RESTRICT' end
      ));
    end if;
  end loop;

  return jsonb_build_object('count',jsonb_array_length(v_items),'items',v_items);
end $_$;

--
-- Name: gridex_gate_exact_z02_atomic_apply(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_gate_exact_z02_atomic_apply() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request_id uuid;
  v_message_id uuid;
  v_result jsonb;
  v_code text;
begin
  if new.job_type <> 'apply_inbound_grid_owner_response'
     or new.status not in ('queued', 'running')
     or coalesce(new.result ->> 'z02_correlation_status', '') <> 'exact'
     or coalesce(new.result ->> 'z02_payload_validation_status', '') <> 'valid'
     or coalesce(new.result ->> 'z02_snapshot_freshness_status', '') <> 'valid'
     or coalesce((new.result ->> 'z02_atomic_core_applied')::boolean, false) then
    return new;
  end if;

  begin
    v_request_id := nullif(new.payload ->> 'customer_info_request_id', '')::uuid;
    v_message_id := nullif(new.payload ->> 'ediel_message_id', '')::uuid;
  exception when others then
    new.status := 'needs_review';
    new.result := coalesce(new.result, '{}'::jsonb) || jsonb_build_object(
      'reason', 'z02_atomic_apply_invalid_identifiers',
      'reason_code', 'z02_atomic_apply_invalid_identifiers'
    );
    return new;
  end;

  v_result := public.gridex_apply_exact_z02_core(
    new.company_id,
    new.customer_id,
    new.customer_site_id,
    v_request_id,
    v_message_id,
    new.operation_id,
    new.created_by
  );

  if coalesce((v_result ->> 'ok')::boolean, false) then
    new.result := coalesce(new.result, '{}'::jsonb) || jsonb_build_object(
      'z02_atomic_core_applied', true,
      'z02_atomic_core', v_result
    );
    return new;
  end if;

  v_code := coalesce(v_result ->> 'code', 'z02_atomic_core_apply_failed');
  new.status := 'needs_review';
  new.result := coalesce(new.result, '{}'::jsonb) || jsonb_build_object(
    'reason', v_code,
    'reason_code', v_code,
    'z02_atomic_core_applied', false,
    'z02_atomic_core', v_result
  );

  update public.customer_info_requests
  set status = 'manual_review_required',
      blocker_code = v_code,
      blocker_reason = 'Atomisk Z02-apply blockerades av datainvariant.',
      blocker_details = coalesce(blocker_details, '{}'::jsonb) || jsonb_build_object(
        'atomic_core_apply', v_result,
        'inbound_message_id', v_message_id,
        'operation_id', new.operation_id
      ),
      next_required_action = 'Granska Z02-data och lös konflikt innan automation återupptas.',
      updated_at = now(),
      updated_by = new.created_by
  where id = v_request_id
    and company_id = new.company_id;

  insert into public.facility_data_quality_issues (
    company_id,
    customer_id,
    customer_site_id,
    grid_owner_id,
    issue_type,
    severity,
    source,
    source_error_code,
    source_error_text,
    recommended_action,
    retry_allowed,
    next_readiness_required,
    metadata
  )
  select
    new.company_id,
    new.customer_id,
    new.customer_site_id,
    cir.grid_owner_id,
    case
      when v_code = 'duplicate_metering_point' then 'duplicate_metering_point'
      when v_code = 'cross_site_identifier_conflict' then 'cross_site_identifier_conflict'
      when v_code = 'facility_identifier_conflict' then 'facility_identifier_conflict'
      when v_code = 'grid_owner_conflict' then 'grid_owner_conflict'
      when v_code = 'response_site_mismatch' then 'response_site_mismatch'
      else 'request_site_customer_mismatch'
    end,
    'critical',
    'ediel_z02_atomic_core_apply',
    v_code,
    'Atomisk Z02-apply blockerades av datainvariant.',
    'Granska inbound Z02 och site/metering-identitet innan automation återupptas.',
    false,
    true,
    jsonb_build_object(
      'customer_info_request_id', v_request_id,
      'inbound_message_id', v_message_id,
      'operation_id', new.operation_id,
      'result', v_result
    )
  from public.customer_info_requests cir
  where cir.id = v_request_id
    and cir.company_id = new.company_id
    and not exists (
      select 1
      from public.facility_data_quality_issues q
      where q.company_id = new.company_id
        and q.customer_site_id is not distinct from new.customer_site_id
        and q.status = 'open'
        and q.source = 'ediel_z02_atomic_core_apply'
        and q.source_error_code = v_code
        and q.metadata ->> 'inbound_message_id' = v_message_id::text
    );

  return new;
end;
$$;

--
-- Name: FUNCTION gridex_gate_exact_z02_atomic_apply(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_gate_exact_z02_atomic_apply() IS 'Runs after the exact Z02 correlation trigger (trigger name sorts later); conflicts force needs_review before a worker can claim the job.';

--
-- Name: gridex_gate_inbound_z02_operation_job(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_gate_inbound_z02_operation_job() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_request_id uuid;
  v_message_id uuid;
  v_request public.customer_info_requests%rowtype;
  v_inbound public.ediel_messages%rowtype;
  v_source public.ediel_messages%rowtype;
  v_source_count integer := 0;
  v_source_li text;
  v_inbound_li text;
  v_inbound_tn text;
  v_inbound_acw text;
  v_source_li_count integer := 0;
  v_inbound_li_count integer := 0;
  v_source_li_registry_count integer := 0;
  v_source_li_registry_match_count integer := 0;
  v_supplemental_match_count integer := 0;
  v_source_expected_variant text;
  v_inbound_variant text;
  v_reason_code text := null;
  v_reason_text text := null;
  v_details jsonb := '{}'::jsonb;
begin
  if new.job_type <> 'apply_inbound_grid_owner_response'
     or new.status not in ('queued', 'running') then
    return new;
  end if;

  begin
    v_request_id := nullif(new.payload ->> 'customer_info_request_id', '')::uuid;
    v_message_id := nullif(new.payload ->> 'ediel_message_id', '')::uuid;
  exception when others then
    v_reason_code := 'z02_job_invalid_identifiers';
    v_reason_text := 'Inbound-jobbet saknar giltiga UUID-referenser.';
  end;

  if v_reason_code is null and (v_request_id is null or v_message_id is null) then
    v_reason_code := 'z02_job_missing_identifiers';
    v_reason_text := 'Inbound-jobbet saknar customer_info_request_id eller ediel_message_id.';
  end if;

  if v_reason_code is null then
    select * into v_request
    from public.customer_info_requests
    where id = v_request_id
      and company_id = new.company_id;

    if not found then
      v_reason_code := 'z02_request_not_found_for_tenant';
      v_reason_text := 'Customer-info-request hittades inte i jobbets tenant.';
    elsif v_request.customer_id <> new.customer_id
       or v_request.site_id is distinct from new.customer_site_id then
      v_reason_code := 'request_site_customer_mismatch';
      v_reason_text := 'Requestens kund/anläggning matchar inte operation-jobbet.';
    end if;
  end if;

  if v_reason_code is null then
    select * into v_inbound
    from public.ediel_messages
    where id = v_message_id
      and company_id = new.company_id
      and direction = 'inbound'
      and message_family = 'PRODAT'
      and upper(coalesce(message_code, '')) = 'Z02';

    if not found then
      v_reason_code := 'z02_inbound_message_not_found';
      v_reason_text := 'Meddelandet är inte ett inbound PRODAT Z02 i rätt tenant.';
    elsif v_inbound.customer_id is not null and v_inbound.customer_id <> new.customer_id then
      v_reason_code := 'z02_customer_mismatch';
      v_reason_text := 'Inbound Z02 är redan länkat till en annan kund.';
    elsif v_inbound.site_id is not null and v_inbound.site_id <> new.customer_site_id then
      v_reason_code := 'response_site_mismatch';
      v_reason_text := 'Inbound Z02 är redan länkat till en annan anläggning.';
    elsif v_request.grid_owner_id is not null
       and v_inbound.grid_owner_id is not null
       and v_request.grid_owner_id <> v_inbound.grid_owner_id then
      v_reason_code := 'grid_owner_conflict';
      v_reason_text := 'Inbound Z02 kommer från annan nätägare än originating request.';
    end if;
  end if;

  if v_reason_code is null then
    if v_request.ediel_message_id is not null then
      select * into v_source
      from public.ediel_messages
      where id = v_request.ediel_message_id
        and company_id = new.company_id
        and direction = 'outbound'
        and message_family = 'PRODAT'
        and upper(coalesce(message_code, '')) = 'Z01';
      if found then v_source_count := 1; end if;
    end if;

    if v_source_count = 0 and v_request.grid_owner_data_request_id is not null then
      select count(*)::integer into v_source_count
      from public.ediel_messages
      where company_id = new.company_id
        and grid_owner_data_request_id = v_request.grid_owner_data_request_id
        and direction = 'outbound'
        and message_family = 'PRODAT'
        and upper(coalesce(message_code, '')) = 'Z01'
        and status <> 'cancelled';

      if v_source_count = 1 then
        select * into v_source
        from public.ediel_messages
        where company_id = new.company_id
          and grid_owner_data_request_id = v_request.grid_owner_data_request_id
          and direction = 'outbound'
          and message_family = 'PRODAT'
          and upper(coalesce(message_code, '')) = 'Z01'
          and status <> 'cancelled'
        order by created_at desc
        limit 1;
      end if;
    end if;

    if v_source_count = 0 then
      v_reason_code := 'z02_originating_z01_missing';
      v_reason_text := 'Originating PRODAT Z01 kunde inte identifieras.';
    elsif v_source_count > 1 then
      v_reason_code := 'z02_originating_z01_ambiguous';
      v_reason_text := 'Flera möjliga originating PRODAT Z01 hittades.';
    elsif v_source.customer_id is distinct from new.customer_id
       or v_source.site_id is distinct from new.customer_site_id then
      v_reason_code := 'z02_origin_site_customer_mismatch';
      v_reason_text := 'Originating Z01 tillhör inte exakt samma kund och anläggning.';
    elsif coalesce(v_source.receiver_ediel_id, '') <> ''
       and coalesce(v_inbound.sender_ediel_id, '') <> ''
       and v_source.receiver_ediel_id <> v_inbound.sender_ediel_id then
      v_reason_code := 'z02_sender_receiver_mismatch';
      v_reason_text := 'Inbound avsändare matchar inte originating Z01-mottagaren.';
    elsif coalesce(v_source.sender_ediel_id, '') <> ''
       and coalesce(v_inbound.receiver_ediel_id, '') <> ''
       and v_source.sender_ediel_id <> v_inbound.receiver_ediel_id then
      v_reason_code := 'z02_receiver_sender_mismatch';
      v_reason_text := 'Inbound mottagare matchar inte originating Z01-avsändaren.';
    end if;
  end if;

  if v_reason_code is null then
    v_source_li := public.gridex_edifact_rff_value(v_source.raw_payload, 'LI');
    v_inbound_li := public.gridex_edifact_rff_value(v_inbound.raw_payload, 'LI');
    v_inbound_tn := public.gridex_edifact_rff_value(v_inbound.raw_payload, 'TN');
    v_inbound_acw := public.gridex_edifact_rff_value(v_inbound.raw_payload, 'ACW');

    select count(*)::integer into v_source_li_count
    from regexp_matches(
      coalesce(v_source.raw_payload, ''),
      'RFF\+LI:([^+''\r\n]+)',
      'g'
    );

    select count(*)::integer into v_inbound_li_count
    from regexp_matches(
      coalesce(v_inbound.raw_payload, ''),
      'RFF\+LI:([^+''\r\n]+)',
      'g'
    );

    if v_source_li_count = 0 or v_source_li is null then
      v_reason_code := 'z02_origin_line_item_reference_missing';
      v_reason_text := 'Originating Z01 saknar canonical RFF+LI och får inte korreleras automatiskt.';
    elsif v_source_li_count <> 1 then
      v_reason_code := 'z02_origin_line_item_reference_ambiguous';
      v_reason_text := 'Originating Z01 innehåller flera RFF+LI och är inte entydigt korrelerbar.';
    elsif v_inbound_li_count = 0 or v_inbound_li is null then
      v_reason_code := 'z02_line_item_reference_missing';
      v_reason_text := 'Inbound Z02 saknar obligatorisk returnerad RFF+LI från originating Z01.';
    elsif v_inbound_li_count <> 1 then
      v_reason_code := 'z02_line_item_reference_ambiguous';
      v_reason_text := 'Inbound Z02 innehåller flera RFF+LI och får inte appliceras automatiskt.';
    elsif v_inbound_li <> v_source_li then
      v_reason_code := 'z02_line_item_reference_mismatch';
      v_reason_text := 'Inbound Z02 RFF+LI matchar inte originating Z01.';
    end if;
  end if;

  if v_reason_code is null then
    select
      count(*)::integer,
      count(*) filter (where br.reference_value = v_source_li)::integer
    into v_source_li_registry_count, v_source_li_registry_match_count
    from public.ediel_business_references br
    where br.company_id = new.company_id
      and br.source_message_id = v_source.id
      and br.message_family = 'PRODAT'
      and upper(coalesce(br.message_code, '')) = 'Z01'
      and br.reference_type = 'RFF_LI';

    if v_source_li_registry_count = 0 then
      v_reason_code := 'z02_origin_line_item_registry_missing';
      v_reason_text := 'Originating Z01 RFF+LI saknas i canonical business-reference-index.';
    elsif v_source_li_registry_match_count = 0
       or v_source_li_registry_match_count <> v_source_li_registry_count then
      v_reason_code := 'z02_origin_line_item_registry_conflict';
      v_reason_text := 'Originating Z01 payload och business-reference-index har konflikt för RFF+LI.';
    end if;
  end if;

  -- TN and ACW are diagnostic/supplemental evidence only. They must never make
  -- a missing or mismatched LI eligible for automatic apply.
  if v_reason_code is null then
    select count(*)::integer into v_supplemental_match_count
    from public.ediel_business_references br
    where br.company_id = new.company_id
      and br.source_message_id = v_source.id
      and br.message_family = 'PRODAT'
      and upper(coalesce(br.message_code, '')) = 'Z01'
      and (
        (br.reference_type = 'RFF_TN' and v_inbound_tn is not null and br.reference_value = v_inbound_tn)
        or (br.reference_type = 'RFF_ACW' and v_inbound_acw is not null and br.reference_value = v_inbound_acw)
      );
  end if;

  if v_reason_code is null then
    v_source_expected_variant := upper(coalesce(
      v_source.parsed_payload ->> 'expectedZ02Variant',
      v_source.validation_report ->> 'expectedZ02Variant',
      public.gridex_prodat_variant_from_raw(v_source.raw_payload)
    ));
    v_inbound_variant := upper(coalesce(
      v_inbound.parsed_payload ->> 'prodatVariant',
      v_inbound.validation_report ->> 'prodatVariant',
      public.gridex_prodat_variant_from_raw(v_inbound.raw_payload)
    ));

    if v_source_expected_variant not in ('L', 'LK') then
      v_reason_code := 'z02_origin_variant_missing';
      v_reason_text := 'Originating Z01 saknar canonical expected Z02-variant.';
    elsif v_inbound_variant not in ('L', 'LK') then
      v_reason_code := 'z02_response_variant_missing';
      v_reason_text := 'Inbound Z02 saknar entydig L/LK-variant.';
    elsif v_source_expected_variant <> v_inbound_variant then
      v_reason_code := 'z02_variant_mismatch';
      v_reason_text := format(
        'Inbound Z02%s matchar inte originating Z01%s.',
        v_inbound_variant,
        v_source_expected_variant
      );
    end if;
  end if;

  v_details := jsonb_build_object(
    'gate', 'gridex_gate_inbound_z02_operation_job',
    'customer_info_request_id', v_request_id,
    'inbound_message_id', v_message_id,
    'originating_z01_message_id', v_source.id,
    'source_li', v_source_li,
    'inbound_li', v_inbound_li,
    'source_li_count', v_source_li_count,
    'inbound_li_count', v_inbound_li_count,
    'exact_li_match', v_source_li is not null and v_inbound_li = v_source_li,
    'source_li_registry_count', v_source_li_registry_count,
    'source_li_registry_matches', v_source_li_registry_match_count,
    'supplemental_reference_matches', v_supplemental_match_count,
    'typed_reference_matches', v_source_li_registry_match_count + v_supplemental_match_count,
    'expected_z02_variant', v_source_expected_variant,
    'inbound_z02_variant', v_inbound_variant,
    'evaluated_at', now()
  );

  if v_reason_code is not null then
    new.status := 'needs_review';
    new.result := coalesce(new.result, '{}'::jsonb)
      || jsonb_build_object(
        'reason', v_reason_code,
        'reason_code', v_reason_code,
        'blocker_reason', v_reason_text,
        'correlation', v_details
      );

    if v_request_id is not null then
      update public.customer_info_requests
      set status = 'manual_review_required',
          blocker_code = v_reason_code,
          blocker_reason = v_reason_text,
          blocker_details = coalesce(blocker_details, '{}'::jsonb) || v_details,
          next_required_action = 'Granska Z02-korrelation, originating Z01 RFF+LI, tenant/site och L/LK-variant innan svaret appliceras.',
          updated_at = now()
      where id = v_request_id
        and company_id = new.company_id;
    end if;

    insert into public.facility_data_quality_issues (
      company_id,
      customer_id,
      customer_site_id,
      grid_owner_id,
      issue_type,
      severity,
      source,
      source_error_code,
      source_error_text,
      recommended_action,
      retry_allowed,
      next_readiness_required,
      metadata
    )
    select
      new.company_id,
      new.customer_id,
      new.customer_site_id,
      v_request.grid_owner_id,
      case
        when v_reason_code in ('response_site_mismatch', 'z02_origin_site_customer_mismatch') then 'response_site_mismatch'
        when v_reason_code like '%tenant%' then 'tenant_mismatch'
        else 'request_site_customer_mismatch'
      end,
      'critical',
      'ediel_z02_correlation_gate',
      v_reason_code,
      v_reason_text,
      'Granska originating Z01 och inbound Z02, inklusive exakt RFF+LI, innan automation återupptas.',
      false,
      true,
      v_details
    where not exists (
      select 1
      from public.facility_data_quality_issues q
      where q.company_id = new.company_id
        and q.customer_site_id is not distinct from new.customer_site_id
        and q.status = 'open'
        and q.source = 'ediel_z02_correlation_gate'
        and q.source_error_code = v_reason_code
        and (q.metadata ->> 'inbound_message_id') = coalesce(v_message_id::text, '')
    );

    return new;
  end if;

  new.result := coalesce(new.result, '{}'::jsonb)
    || jsonb_build_object(
      'z02_correlation_status', 'exact',
      'correlation', v_details
    );
  return new;
end;
$$;

--
-- Name: FUNCTION gridex_gate_inbound_z02_operation_job(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_gate_inbound_z02_operation_job() IS 'Fail-closed durable PRODAT Z02 gate: automatic apply requires exact tenant/customer/site/origin/party/variant plus exactly one returned RFF+LI matching the originating Z01; TN/ACW are supplemental only.';

--
-- Name: gridex_gate_inbound_z02_required_payload(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_gate_inbound_z02_required_payload() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_request_id uuid;
  v_message_id uuid;
  v_request public.customer_info_requests%rowtype;
  v_message public.ediel_messages%rowtype;
  v_site public.customer_sites%rowtype;
  v_customer public.customers%rowtype;
  v_lin text;
  v_li text;
  v_grid_area text;
  v_measure_method text;
  v_reason text;
  v_ud_composite text;
  v_ud_id text;
  v_ud_qualifier text;
  v_ud_name text;
  v_ud_postcode text;
  v_ud_city text;
  v_ud_country text;
  v_it_composite text;
  v_it_id text;
  v_it_address text;
  v_it_postcode text;
  v_it_city text;
  v_it_country text;
  v_expected_customer_id text;
  v_expected_customer_qualifier text;
  v_expected_facility_id text;
  v_reason_code text := null;
  v_reason_text text := null;
  v_details jsonb := '{}'::jsonb;
begin
  if new.job_type <> 'apply_inbound_grid_owner_response'
     or new.status not in ('queued', 'running')
     or coalesce(new.result ->> 'z02_correlation_status', '') <> 'exact' then
    return new;
  end if;

  begin
    v_request_id := nullif(new.payload ->> 'customer_info_request_id', '')::uuid;
    v_message_id := nullif(new.payload ->> 'ediel_message_id', '')::uuid;
  exception when others then
    v_reason_code := 'z02_payload_identifiers_invalid';
    v_reason_text := 'Z02 payload-gaten saknar giltiga request/message-ID.';
  end;

  if v_reason_code is null then
    select * into v_request from public.customer_info_requests where id = v_request_id and company_id = new.company_id;
    select * into v_message from public.ediel_messages
      where id = v_message_id and company_id = new.company_id
        and direction = 'inbound' and message_family = 'PRODAT' and upper(coalesce(message_code,'')) = 'Z02';
    select * into v_site from public.customer_sites
      where id = new.customer_site_id and company_id = new.company_id and customer_id = new.customer_id;
    select * into v_customer from public.customers where id = new.customer_id and company_id = new.company_id;
    if v_request.id is null or v_message.id is null or v_site.id is null or v_customer.id is null then
      v_reason_code := 'z02_payload_context_missing';
      v_reason_text := 'Z02 payload-gaten kunde inte läsa exakt request, meddelande, kund och anläggning.';
    end if;
  end if;

  if v_reason_code is null then
    v_lin := public.gridex_edifact_first_lin_item_id(v_message.raw_payload);
    v_li := public.gridex_edifact_rff_value(v_message.raw_payload, 'LI');
    v_grid_area := public.gridex_edifact_rff_value(v_message.raw_payload, 'Z05');
    v_measure_method := public.gridex_edifact_cci_cav_value(v_message.raw_payload, 'Z04');
    v_reason := public.gridex_edifact_cci_cav_value(v_message.raw_payload, 'Z13');

    v_ud_composite := public.gridex_edifact_nad_element(v_message.raw_payload, 'UD', 2);
    v_ud_id := nullif(btrim(split_part(coalesce(v_ud_composite,''), ':', 1)), '');
    v_ud_qualifier := nullif(btrim(split_part(coalesce(v_ud_composite,''), ':', 2)), '');
    v_ud_name := public.gridex_edifact_nad_element(v_message.raw_payload, 'UD', 4);
    v_ud_postcode := public.gridex_edifact_nad_element(v_message.raw_payload, 'UD', 8);
    v_ud_city := public.gridex_edifact_nad_element(v_message.raw_payload, 'UD', 6);
    v_ud_country := public.gridex_edifact_nad_element(v_message.raw_payload, 'UD', 9);

    v_it_composite := public.gridex_edifact_nad_element(v_message.raw_payload, 'IT', 2);
    v_it_id := nullif(btrim(split_part(coalesce(v_it_composite,''), ':', 1)), '');
    v_it_address := public.gridex_edifact_nad_element(v_message.raw_payload, 'IT', 5);
    v_it_postcode := public.gridex_edifact_nad_element(v_message.raw_payload, 'IT', 8);
    v_it_city := public.gridex_edifact_nad_element(v_message.raw_payload, 'IT', 6);
    v_it_country := public.gridex_edifact_nad_element(v_message.raw_payload, 'IT', 9);

    v_expected_customer_id := coalesce(nullif(btrim(v_customer.org_number), ''), nullif(btrim(v_customer.personal_number), ''));
    v_expected_customer_qualifier := case
      when nullif(btrim(v_customer.org_number), '') is not null then 'SE1'
      when nullif(btrim(v_customer.personal_number), '') is not null then 'SE2'
      else null
    end;
    v_expected_facility_id := coalesce(nullif(btrim(v_site.normalized_facility_id), ''), nullif(btrim(v_site.facility_id), ''));

    if v_lin is null then
      v_reason_code := 'z02_required_line_item_missing'; v_reason_text := 'Z02 saknar obligatoriskt LIN anläggnings-/mätpunkts-ID (fält 209).';
    elsif v_li is null then
      v_reason_code := 'z02_required_line_reference_missing'; v_reason_text := 'Z02 saknar obligatorisk RFF+LI (fält 226).';
    elsif v_grid_area is null then
      v_reason_code := 'z02_required_grid_area_missing'; v_reason_text := 'Z02 saknar obligatoriskt nätområde RFF+Z05 (fält 260).';
    elsif v_measure_method is null then
      v_reason_code := 'z02_required_measure_method_missing'; v_reason_text := 'Z02 saknar obligatorisk mätmetod CCI++Z04/CAV (fält 217).';
    elsif v_reason is null then
      v_reason_code := 'z02_required_reason_missing'; v_reason_text := 'Z02 saknar obligatorisk transaktionsorsak CCI++Z13/CAV (fält 223).';
    elsif v_ud_id is null or v_ud_name is null or v_ud_postcode is null or v_ud_city is null or v_ud_country is null then
      v_reason_code := 'z02_required_end_user_fields_missing'; v_reason_text := 'Z02 saknar obligatoriska elanvändaruppgifter i NAD+UD (fält 227/228/231/232/316).';
    elsif v_it_id is null or v_it_address is null then
      v_reason_code := 'z02_required_installation_fields_missing'; v_reason_text := 'Z02 saknar obligatoriskt anläggnings-ID eller anläggningsadress i NAD+IT (fält 233/234).';
    elsif regexp_replace(upper(v_it_id), '[^0-9A-Z]', '', 'g') <> regexp_replace(upper(v_lin), '[^0-9A-Z]', '', 'g') then
      v_reason_code := 'z02_installation_id_line_item_mismatch'; v_reason_text := 'Z02 NAD+IT anläggnings-ID matchar inte LIN fält 209.';
    elsif v_expected_facility_id is not null and regexp_replace(upper(v_expected_facility_id), '[^0-9A-Z]', '', 'g') <> regexp_replace(upper(v_lin), '[^0-9A-Z]', '', 'g') then
      v_reason_code := 'z02_facility_identifier_conflict'; v_reason_text := 'Z02 anläggnings-ID matchar inte den anläggning som Gridex frågade om.';
    elsif v_expected_customer_id is not null and regexp_replace(upper(v_expected_customer_id), '[^0-9A-Z]', '', 'g') <> regexp_replace(upper(v_ud_id), '[^0-9A-Z]', '', 'g') then
      v_reason_code := 'z02_end_user_identity_conflict'; v_reason_text := 'Z02 elanvändaridentitet matchar inte kunden i originating Z01.';
    elsif v_expected_customer_qualifier is not null and upper(coalesce(v_ud_qualifier,'')) <> v_expected_customer_qualifier then
      v_reason_code := 'z02_end_user_qualifier_conflict'; v_reason_text := 'Z02 elanvändarens ID-kvalificerare matchar inte kundens juridiska identitet.';
    elsif nullif(btrim(v_site.street), '') is not null and lower(regexp_replace(btrim(v_it_address), '[[:space:]]+', ' ', 'g')) <> lower(regexp_replace(btrim(v_site.street), '[[:space:]]+', ' ', 'g')) then
      v_reason_code := 'z02_installation_address_conflict'; v_reason_text := 'Z02 anläggningsadress matchar inte den canonical adress som originating Z01 avsåg.';
    elsif v_it_postcode is not null and regexp_replace(v_it_postcode, '[^0-9]', '', 'g') <> regexp_replace(coalesce(v_site.postal_code,''), '[^0-9]', '', 'g') then
      v_reason_code := 'z02_installation_postcode_conflict'; v_reason_text := 'Z02 anläggningens postnummer matchar inte originating site.';
    elsif v_it_city is not null and lower(btrim(v_it_city)) <> lower(btrim(coalesce(v_site.city,''))) then
      v_reason_code := 'z02_installation_city_conflict'; v_reason_text := 'Z02 anläggningens ort matchar inte originating site.';
    elsif v_it_country is not null and upper(btrim(v_it_country)) <> upper(btrim(coalesce(v_site.country,'SE'))) then
      v_reason_code := 'z02_installation_country_conflict'; v_reason_text := 'Z02 anläggningens land matchar inte originating site.';
    end if;
  end if;

  v_details := jsonb_build_object(
    'gate', 'gridex_gate_inbound_z02_required_payload',
    'inbound_message_id', v_message_id,
    'customer_info_request_id', v_request_id,
    'line_item_id', v_lin,
    'line_reference', v_li,
    'grid_area', v_grid_area,
    'measure_method', v_measure_method,
    'reason_for_transaction', v_reason,
    'end_user_id', v_ud_id,
    'end_user_qualifier', v_ud_qualifier,
    'installation_id', v_it_id,
    'installation_address', v_it_address,
    'evaluated_at', now()
  );

  if v_reason_code is not null then
    new.status := 'needs_review';
    new.result := coalesce(new.result, '{}'::jsonb) || jsonb_build_object(
      'reason', v_reason_code,
      'reason_code', v_reason_code,
      'blocker_reason', v_reason_text,
      'z02_payload_validation', v_details
    );
    if v_request_id is not null then
      update public.customer_info_requests
      set status = 'manual_review_required',
          blocker_code = v_reason_code,
          blocker_reason = v_reason_text,
          blocker_details = coalesce(blocker_details, '{}'::jsonb) || jsonb_build_object('z02_payload_validation', v_details),
          next_required_action = 'Granska Z02 required fields och identitetskonflikt innan svaret appliceras.',
          updated_at = now()
      where id = v_request_id and company_id = new.company_id;
    end if;
    return new;
  end if;

  new.result := coalesce(new.result, '{}'::jsonb) || jsonb_build_object(
    'z02_payload_validation_status', 'valid',
    'z02_payload_validation', v_details
  );
  return new;
end;
$$;

--
-- Name: FUNCTION gridex_gate_inbound_z02_required_payload(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_gate_inbound_z02_required_payload() IS 'PRODAT 26-A Z02 required-field and identity gate. Runs after exact correlation and before atomic apply; conflicts become needs_review and never mutate site/metering data.';

--
-- Name: gridex_gate_inbound_z02_snapshot_freshness(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_gate_inbound_z02_snapshot_freshness() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  v_request_id uuid;
  v_site public.customer_sites%rowtype;
  v_snapshot jsonb;
  v_expected_site_id text;
  v_expected_address_hash text;
  v_expected_grid_owner_id text;
  v_expected_facility_id text;
  v_current_address_hash text;
  v_reason_code text := null;
  v_reason_text text := null;
  v_details jsonb := '{}'::jsonb;
begin
  if new.job_type <> 'apply_inbound_grid_owner_response'
     or new.status not in ('queued', 'running')
     or coalesce(new.result ->> 'z02_correlation_status', '') <> 'exact'
     or coalesce(new.result ->> 'z02_payload_validation_status', '') <> 'valid'
     or coalesce((new.result ->> 'z02_atomic_core_applied')::boolean, false) then
    return new;
  end if;

  v_snapshot := case
    when jsonb_typeof(new.request_snapshot) = 'object' and new.request_snapshot <> '{}'::jsonb then new.request_snapshot
    when jsonb_typeof(new.payload -> 'site_snapshot') = 'object' then new.payload -> 'site_snapshot'
    else '{}'::jsonb
  end;
  v_expected_site_id := nullif(btrim(v_snapshot ->> 'site_id'), '');
  v_expected_address_hash := nullif(btrim(v_snapshot ->> 'address_hash'), '');
  v_expected_grid_owner_id := nullif(btrim(v_snapshot ->> 'grid_owner_id'), '');
  v_expected_facility_id := nullif(btrim(v_snapshot ->> 'facility_id'), '');

  begin
    v_request_id := nullif(new.payload ->> 'customer_info_request_id', '')::uuid;
  exception when others then
    v_reason_code := 'z02_snapshot_identifiers_invalid';
    v_reason_text := 'Z02 requestsnapshot saknar giltig request-identitet.';
  end;

  if v_reason_code is null then
    select * into v_site from public.customer_sites
    where id = new.customer_site_id and company_id = new.company_id and customer_id = new.customer_id;
    if not found then
      v_reason_code := 'z02_snapshot_site_missing';
      v_reason_text := 'Anläggningen från requestsnapshot finns inte längre i rätt tenant/kund.';
    end if;
  end if;

  if v_reason_code is null then
    v_current_address_hash := coalesce(
      nullif(btrim(v_site.address_hash), ''),
      lower(concat_ws('|',
        nullif(btrim(v_site.street), ''),
        nullif(regexp_replace(coalesce(v_site.postal_code, ''), '[^0-9]', '', 'g'), ''),
        nullif(btrim(v_site.city), '')
      ))
    );
    if v_expected_site_id is null or v_expected_address_hash is null then
      v_reason_code := 'z02_operation_snapshot_missing';
      v_reason_text := 'Originating Z01 saknar komplett requestsnapshot och Z02 får inte appliceras automatiskt.';
    elsif v_expected_site_id <> new.customer_site_id::text then
      v_reason_code := 'z02_snapshot_site_mismatch';
      v_reason_text := 'Requestsnapshot avser en annan anläggning.';
    elsif v_current_address_hash is distinct from v_expected_address_hash then
      v_reason_code := 'site_address_changed_after_request';
      v_reason_text := 'Anläggningsadressen ändrades efter originating Z01. Z02 kräver manuell granskning.';
    elsif v_expected_grid_owner_id is not null and v_site.grid_owner_id::text is distinct from v_expected_grid_owner_id then
      v_reason_code := 'site_grid_owner_changed_after_request';
      v_reason_text := 'Nätägaren ändrades efter originating Z01. Z02 kräver manuell granskning.';
    elsif v_expected_facility_id is not null and regexp_replace(upper(coalesce(v_site.facility_id, '')), '[^0-9A-Z]', '', 'g') <> regexp_replace(upper(v_expected_facility_id), '[^0-9A-Z]', '', 'g') then
      v_reason_code := 'site_facility_changed_after_request';
      v_reason_text := 'Anläggnings-ID ändrades efter originating Z01. Z02 kräver manuell granskning.';
    end if;
  end if;

  v_details := jsonb_build_object(
    'gate', 'gridex_gate_inbound_z02_snapshot_freshness',
    'customer_info_request_id', v_request_id,
    'expected_site_id', v_expected_site_id,
    'expected_address_hash', v_expected_address_hash,
    'current_address_hash', v_current_address_hash,
    'expected_grid_owner_id', v_expected_grid_owner_id,
    'current_grid_owner_id', v_site.grid_owner_id,
    'expected_facility_id', v_expected_facility_id,
    'current_facility_id', v_site.facility_id,
    'evaluated_at', now()
  );

  if v_reason_code is not null then
    new.status := 'needs_review';
    new.result := coalesce(new.result, '{}'::jsonb) || jsonb_build_object(
      'reason', v_reason_code,
      'reason_code', v_reason_code,
      'blocker_reason', v_reason_text,
      'z02_snapshot_freshness', v_details
    );
    if v_request_id is not null then
      update public.customer_info_requests
      set status = 'manual_review_required', blocker_code = v_reason_code,
          blocker_reason = v_reason_text,
          blocker_details = coalesce(blocker_details, '{}'::jsonb) || jsonb_build_object('z02_snapshot_freshness', v_details),
          next_required_action = 'Granska ändrad anläggning mot originating Z01 innan Z02 appliceras.', updated_at = now()
      where id = v_request_id and company_id = new.company_id;
    end if;
    return new;
  end if;

  new.result := coalesce(new.result, '{}'::jsonb) || jsonb_build_object(
    'z02_snapshot_freshness_status', 'valid', 'z02_snapshot_freshness', v_details
  );
  return new;
end;
$$;

--
-- Name: gridex_generate_portfolio_price_estimate(uuid, uuid, uuid, uuid, text, date, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_generate_portfolio_price_estimate(p_actor_user_id uuid, p_company_id uuid, p_portfolio_id uuid, p_price_plan_version_id uuid, p_price_area_code text, p_estimate_month date, p_estimate_source text, p_manual_or_forecast_price_ore_per_kwh numeric DEFAULT NULL::numeric, p_confidence text DEFAULT NULL::text, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_price numeric; v_ids uuid[]:=array[]::uuid[]; v_id uuid;
begin
  perform public.gridex_assert_portfolio_permission(
    p_actor_user_id,'portfolio_settlement.calculate',p_company_id,p_portfolio_id
  );
  if not exists(
    select 1 from public.portfolios p
    join public.price_plan_versions v on v.id=p_price_plan_version_id
    where p.id=p_portfolio_id and p.company_id=p_company_id and p.status='active'
      and v.company_id=p_company_id
      and v.snapshot_json#>>'{portfolio_method,portfolio_id}'=p_portfolio_id::text
  ) then
    raise exception using errcode='23514',message='portfolio_estimate_scope_mismatch';
  end if;
  if upper(p_price_area_code) not in('SE1','SE2','SE3','SE4')
     or p_estimate_month<>date_trunc('month',p_estimate_month)::date
     or p_estimate_source not in('latest_final','rolling_3','forecast','manual') then
    raise exception using errcode='22023',message='invalid_portfolio_estimate_input';
  end if;
  if p_estimate_source in('manual','forecast') then
    v_price:=p_manual_or_forecast_price_ore_per_kwh;
  elsif p_estimate_source='latest_final' then
    select s.portfolio_price_ore_per_kwh,array[s.id]
      into v_price,v_ids
    from public.portfolio_monthly_settlements s
    where s.company_id=p_company_id and s.portfolio_id=p_portfolio_id
      and s.price_plan_version_id=p_price_plan_version_id
      and s.price_area_code=upper(p_price_area_code)
      and s.delivery_month<p_estimate_month and s.is_current and s.status in('final','locked')
    order by s.delivery_month desc limit 1;
  else
    select avg(x.portfolio_price_ore_per_kwh),array_agg(x.id order by x.delivery_month)
      into v_price,v_ids
    from (
      select s.id,s.delivery_month,s.portfolio_price_ore_per_kwh
      from public.portfolio_monthly_settlements s
      where s.company_id=p_company_id and s.portfolio_id=p_portfolio_id
        and s.price_plan_version_id=p_price_plan_version_id
        and s.price_area_code=upper(p_price_area_code)
        and s.delivery_month<p_estimate_month and s.is_current and s.status in('final','locked')
      order by s.delivery_month desc limit 3
    ) x;
  end if;
  if v_price is null then
    raise exception using errcode='23514',message='portfolio_estimate_source_unavailable';
  end if;
  if nullif(btrim(p_reason),'') is null then
    raise exception using errcode='22023',message='portfolio_estimate_reason_required';
  end if;
  update public.portfolio_price_estimates set is_current=false
  where company_id=p_company_id and portfolio_id=p_portfolio_id
    and price_plan_version_id=p_price_plan_version_id
    and price_area_code=upper(p_price_area_code) and estimate_month=p_estimate_month and is_current;
  insert into public.portfolio_price_estimates(
    company_id,portfolio_id,price_plan_version_id,price_area_code,estimate_month,
    estimate_source,estimate_price_ore_per_kwh,based_on_settlement_ids,
    confidence,non_binding,reason,created_by
  ) values(
    p_company_id,p_portfolio_id,p_price_plan_version_id,upper(p_price_area_code),p_estimate_month,
    p_estimate_source,v_price,coalesce(v_ids,'{}'),p_confidence,true,btrim(p_reason),p_actor_user_id
  ) returning id into v_id;
  insert into public.portfolio_settlement_audit_log(
    company_id,portfolio_id,actor_user_id,permission,action,new_values,reason
  ) values(
    p_company_id,p_portfolio_id,p_actor_user_id,'portfolio_settlement.calculate','estimate.created',
    jsonb_build_object('estimate_id',v_id,'estimate_month',p_estimate_month,'source',p_estimate_source,'non_binding',true),
    btrim(p_reason)
  );
  return v_id;
end $$;

--
-- Name: gridex_get_customer_card(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_get_customer_card(p_customer_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'customer', to_jsonb(c),
    'sites', coalesce((
      select jsonb_agg(to_jsonb(s) order by s.created_at desc)
      from public.customer_sites s
      where s.customer_id = c.id and s.company_id = c.company_id
    ), '[]'::jsonb),
    'metering_points', coalesce((
      select jsonb_agg(to_jsonb(mp) order by mp.created_at desc)
      from public.metering_points mp
      where mp.customer_id = c.id and mp.company_id = c.company_id
    ), '[]'::jsonb),
    'contracts', coalesce((
      select jsonb_agg(to_jsonb(cc) order by cc.created_at desc)
      from public.customer_contracts cc
      where cc.customer_id = c.id and cc.company_id = c.company_id
    ), '[]'::jsonb),
    'powers_of_attorney', coalesce((
      select jsonb_agg(to_jsonb(poa) order by poa.created_at desc)
      from public.powers_of_attorney poa
      where poa.customer_id = c.id and poa.company_id = c.company_id
    ), '[]'::jsonb),
    'switch_requests', coalesce((
      select jsonb_agg(to_jsonb(ssr) order by ssr.created_at desc)
      from public.supplier_switch_requests ssr
      where ssr.customer_id = c.id and ssr.company_id = c.company_id
    ), '[]'::jsonb),
    'communication_logs', coalesce((
      select jsonb_agg(to_jsonb(cl) order by cl.created_at desc)
      from (
        select *
        from public.communication_logs cl
        where cl.customer_id = c.id and cl.company_id = c.company_id
        order by cl.created_at desc
        limit 50
      ) cl
    ), '[]'::jsonb),
    'open_work_items', coalesce((
      select jsonb_agg(to_jsonb(wq) order by wq.created_at desc)
      from public.gridex_work_queue_v wq
      where wq.customer_id = c.id and wq.company_id = c.company_id
    ), '[]'::jsonb)
  )
  from public.customers c
  where c.id = p_customer_id
    and public.gridex_can_read_company(c.company_id)
  limit 1
$$;

--
-- Name: gridex_get_customer_contract_signature_receipt_v1(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_get_customer_contract_signature_receipt_v1(p_token_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_request public.customer_contract_signature_requests%rowtype;
  v_contract public.customer_contracts%rowtype;
  v_customer public.customers%rowtype;
  v_company public.companies%rowtype;
  v_price public.contract_price_snapshots%rowtype;
  v_legal_versions jsonb;
begin
  select * into v_request from public.customer_contract_signature_requests where token_hash=p_token_hash;
  if not found then raise exception using errcode='P0002',message='signature_link_not_found'; end if;
  if v_request.revoked_at is not null then raise exception using errcode='55000',message='signature_link_revoked'; end if;
  if v_request.used_at is null and v_request.expires_at<=now() then raise exception using errcode='55000',message='signature_link_expired'; end if;
  select * into v_contract from public.customer_contracts where id=v_request.customer_contract_id and company_id=v_request.company_id;
  select * into v_customer from public.customers where id=v_request.customer_id and company_id=v_request.company_id;
  select * into v_company from public.companies where id=v_request.company_id;
  select * into v_price from public.contract_price_snapshots where id=v_contract.contract_price_snapshot_id and company_id=v_request.company_id;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',d.id,'module_key',d.module_key,'title',d.title,
    'version',coalesce(d.template_version,left(d.content_sha256,12)),
    'document_sha256',d.content_sha256,'body',d.rendered_body
  ) order by d.sort_order,d.id),'[]'::jsonb)
  into v_legal_versions
  from public.legal_bundle_version_documents d where d.legal_bundle_version_id=v_contract.legal_bundle_version_id;
  return jsonb_build_object(
    'request_id',v_request.id,'company_id',v_request.company_id,'customer_id',v_request.customer_id,
    'contract_id',v_contract.id,'contract_number',v_contract.contract_number,'contract_name',v_contract.contract_name,
    'contract_type',v_contract.contract_type,'status',v_contract.status,'signed_at',v_contract.signed_at,
    'used_at',v_request.used_at,'expires_at',v_request.expires_at,'channel',v_request.channel,
    'customer_name',coalesce(v_customer.full_name,v_customer.company_name,concat_ws(' ',v_customer.first_name,v_customer.last_name),v_customer.email),
    'customer_email',v_customer.email,'customer_number',coalesce(v_contract.customer_number,v_customer.customer_number),
    'company_name',v_company.name,'offer_reference',v_contract.offer_reference,
    'starts_at',v_contract.starts_at,'ends_at',v_contract.ends_at,'price_area',coalesce(v_contract.price_area_used,v_price.snapshot_json->>'price_area'),
    'pricing_snapshot',v_price.snapshot_json,'pricing_snapshot_sha256',v_price.snapshot_hash,
    'legal_versions',v_legal_versions,'legal_bundle_version_id',v_contract.legal_bundle_version_id,
    'contract_publication_version_id',v_contract.contract_publication_version_id,'price_plan_version_id',v_contract.price_plan_version_id,
    'signature_snapshot_sha256',v_contract.signature_snapshot_sha256
  );
end
$$;

