    route_count integer DEFAULT 0 NOT NULL,
    prodat_route_count integer DEFAULT 0 NOT NULL,
    utilts_route_count integer DEFAULT 0 NOT NULL,
    duplicate_group_key text,
    duplicate_count integer DEFAULT 0 NOT NULL,
    resolver_source_status text,
    verification_checked_at timestamp with time zone,
    verified_at timestamp with time zone,
    verification_metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    prodat_subaddress_status text DEFAULT 'missing'::text NOT NULL,
    utilts_subaddress_status text DEFAULT 'missing'::text NOT NULL,
    prodat_subaddress_source text DEFAULT 'missing'::text NOT NULL,
    utilts_subaddress_source text DEFAULT 'missing'::text NOT NULL,
    subaddress_verified_at timestamp with time zone,
    subaddress_verified_by uuid,
    subaddress_verification_note text,
    prodat_ready_for_customer_flow boolean DEFAULT false NOT NULL,
    utilts_ready_for_metering_flow boolean DEFAULT false NOT NULL,
    supplier_switch_ready boolean DEFAULT false NOT NULL,
    certificate_last_import_at timestamp with time zone,
    certificate_import_source text,
    certificate_valid_to timestamp with time zone,
    not_seen_in_latest_import boolean DEFAULT false NOT NULL,
    last_seen_in_import_at timestamp with time zone,
    electricity_scope_status text DEFAULT 'electricity_scope_pending'::text NOT NULL,
    excluded_from_electricity_scope boolean DEFAULT false NOT NULL,
    manual_review_required boolean DEFAULT false NOT NULL,
    manual_review_reason text,
    CONSTRAINT grid_owners_environment_check CHECK ((environment = ANY (ARRAY['test'::text, 'production'::text]))),
    CONSTRAINT grid_owners_lifecycle_status_check CHECK ((lifecycle_status = ANY (ARRAY['draft'::text, 'verified'::text, 'active'::text, 'deprecated'::text, 'blocked'::text]))),
    CONSTRAINT grid_owners_prodat_subaddress_source_check CHECK ((prodat_subaddress_source = ANY (ARRAY['route'::text, 'manual_verified'::text, 'not_required_confirmed'::text, 'registry_empty_route'::text, 'missing'::text, 'ambiguous'::text]))),
    CONSTRAINT grid_owners_prodat_subaddress_status_check CHECK ((prodat_subaddress_status = ANY (ARRAY['verified'::text, 'not_required_confirmed'::text, 'missing'::text, 'ambiguous'::text]))),
    CONSTRAINT grid_owners_utilts_subaddress_source_check CHECK ((utilts_subaddress_source = ANY (ARRAY['route'::text, 'manual_verified'::text, 'not_required_confirmed'::text, 'registry_empty_route'::text, 'missing'::text, 'ambiguous'::text]))),
    CONSTRAINT grid_owners_utilts_subaddress_status_check CHECK ((utilts_subaddress_status = ANY (ARRAY['verified'::text, 'not_required_confirmed'::text, 'missing'::text, 'ambiguous'::text])))
);

