--
-- Name: gridex_facility_work_queue_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_facility_work_queue_v WITH (security_invoker='true') AS
 WITH site_status AS (
         SELECT cs.id,
            cs.company_id,
            cs.customer_id,
            cs.id AS site_id,
            COALESCE(NULLIF(c.customer_number, ''::text), NULL::text) AS customer_number,
            COALESCE(NULLIF(c.company_name, ''::text), NULLIF(c.full_name, ''::text), NULLIF(TRIM(BOTH FROM concat_ws(' '::text, c.first_name, c.last_name)), ''::text), NULLIF(c.email, ''::text), 'Kund utan namn'::text) AS customer_label,
            COALESCE(NULLIF(cs.site_name, ''::text), NULLIF(cs.facility_id, ''::text), NULLIF(TRIM(BOTH FROM concat_ws(', '::text, cs.street, cs.postal_code, cs.city)), ''::text), 'Anläggning'::text) AS site_label,
            cs.facility_id,
            ( SELECT mp.id
                   FROM public.metering_points mp
                  WHERE ((mp.company_id = cs.company_id) AND (mp.site_id = cs.id))
                  ORDER BY
                        CASE
                            WHEN (mp.status = 'active'::text) THEN 0
                            ELSE 1
                        END, mp.updated_at DESC NULLS LAST
                 LIMIT 1) AS metering_point_id,
            ( SELECT COALESCE(NULLIF(mp.meter_point_id, ''::text), NULLIF(mp.metering_point_id, ''::text), (mp.id)::text) AS "coalesce"
                   FROM public.metering_points mp
                  WHERE ((mp.company_id = cs.company_id) AND (mp.site_id = cs.id))
                  ORDER BY
                        CASE
                            WHEN (mp.status = 'active'::text) THEN 0
                            ELSE 1
                        END, mp.updated_at DESC NULLS LAST
                 LIMIT 1) AS metering_point_label,
            COALESCE(cs.grid_owner_id, ( SELECT mp.grid_owner_id
                   FROM public.metering_points mp
                  WHERE ((mp.company_id = cs.company_id) AND (mp.site_id = cs.id) AND (mp.grid_owner_id IS NOT NULL))
                  ORDER BY
                        CASE
                            WHEN (mp.status = 'active'::text) THEN 0
                            ELSE 1
                        END, mp.updated_at DESC NULLS LAST
                 LIMIT 1)) AS grid_owner_id,
            go.name AS grid_owner_name,
            COALESCE(cs.price_area_code, ( SELECT mp.price_area_code
                   FROM public.metering_points mp
                  WHERE ((mp.company_id = cs.company_id) AND (mp.site_id = cs.id) AND (mp.price_area_code IS NOT NULL))
                  ORDER BY
                        CASE
                            WHEN (mp.status = 'active'::text) THEN 0
                            ELSE 1
                        END, mp.updated_at DESC NULLS LAST
                 LIMIT 1)) AS price_area_code,
            (EXISTS ( SELECT 1
                   FROM public.metering_points mp
                  WHERE ((mp.company_id = cs.company_id) AND (mp.site_id = cs.id) AND (COALESCE(NULLIF(mp.meter_point_id, ''::text), NULLIF(mp.metering_point_id, ''::text)) IS NOT NULL)))) AS has_metering_point,
            ((EXISTS ( SELECT 1
                   FROM public.powers_of_attorney poa
                  WHERE ((poa.customer_id = cs.customer_id) AND (COALESCE(poa.company_id, cs.company_id) = cs.company_id) AND (poa.status = 'signed'::text) AND ((NULLIF(poa.document_path, ''::text) IS NOT NULL) OR (poa.signed_at IS NOT NULL) OR (poa.accepted_at IS NOT NULL) OR (NULLIF(poa.reference, ''::text) IS NOT NULL) OR (poa.fullmakt_snapshot IS NOT NULL))))) OR (EXISTS ( SELECT 1
                   FROM public.customer_documents d
                  WHERE ((d.customer_id = cs.customer_id) AND (COALESCE(d.company_id, cs.company_id) = cs.company_id) AND (d.document_type = 'power_of_attorney'::text) AND (COALESCE(d.status, 'available'::text) = ANY (ARRAY['available'::text, 'uploaded'::text, 'signed'::text, 'active'::text])))))) AS has_signed_power_of_attorney,
            ((EXISTS ( SELECT 1
                   FROM public.customer_info_requests cir
                  WHERE ((cir.company_id = cs.company_id) AND (cir.customer_id = cs.customer_id) AND ((cir.site_id = cs.id) OR (cir.site_id IS NULL)) AND (cir.status = ANY (ARRAY['pending'::text, 'sent'::text, 'waiting_response'::text, 'waiting_for_z02'::text, 'z01_prepared'::text, 'ready_to_send'::text, 'manual_review_required'::text]))))) OR (EXISTS ( SELECT 1
                   FROM public.grid_owner_data_requests gor
                  WHERE ((gor.company_id = cs.company_id) AND (gor.customer_id = cs.customer_id) AND ((gor.site_id = cs.id) OR (gor.site_id IS NULL)) AND (gor.status = ANY (ARRAY['pending'::text, 'sent'::text, 'failed'::text])))))) AS has_open_data_request,
            GREATEST(COALESCE(cs.updated_at, cs.created_at), COALESCE(( SELECT max(mp.updated_at) AS max
                   FROM public.metering_points mp
                  WHERE ((mp.company_id = cs.company_id) AND (mp.site_id = cs.id))), cs.updated_at, cs.created_at), COALESCE(( SELECT max(cir.updated_at) AS max
                   FROM public.customer_info_requests cir
                  WHERE ((cir.company_id = cs.company_id) AND (cir.customer_id = cs.customer_id) AND ((cir.site_id = cs.id) OR (cir.site_id IS NULL)))), cs.updated_at, cs.created_at), COALESCE(( SELECT max(gor.updated_at) AS max
                   FROM public.grid_owner_data_requests gor
                  WHERE ((gor.company_id = cs.company_id) AND (gor.customer_id = cs.customer_id) AND ((gor.site_id = cs.id) OR (gor.site_id IS NULL)))), cs.updated_at, cs.created_at)) AS updated_at,
            cs.created_at
           FROM ((public.customer_sites cs
             JOIN public.customers c ON (((c.id = cs.customer_id) AND (c.company_id = cs.company_id))))
             LEFT JOIN public.grid_owners go ON ((go.id = COALESCE(cs.grid_owner_id, ( SELECT mp.grid_owner_id
                   FROM public.metering_points mp
                  WHERE ((mp.company_id = cs.company_id) AND (mp.site_id = cs.id) AND (mp.grid_owner_id IS NOT NULL))
                  ORDER BY
                        CASE
                            WHEN (mp.status = 'active'::text) THEN 0
                            ELSE 1
                        END, mp.updated_at DESC NULLS LAST
                 LIMIT 1)))))
          WHERE ((COALESCE(c.source, ''::text) <> 'ediel_portal_test'::text) AND (COALESCE(c.status, ''::text) <> ALL (ARRAY['archived'::text, 'deleted'::text, 'deleted_test_only'::text, 'pending_deletion'::text])))
        )
 SELECT id,
    company_id,
    customer_id,
    customer_number,
    customer_label,
    site_id,
    site_label,
    metering_point_id,
    metering_point_label,
    facility_id,
    grid_owner_id,
    grid_owner_name,
    price_area_code,
        CASE
            WHEN has_open_data_request THEN 'awaiting_grid_owner'::text
            WHEN (NOT has_signed_power_of_attorney) THEN 'missing_authorization'::text
            WHEN (grid_owner_id IS NULL) THEN 'needs_grid_owner_review'::text
            WHEN ((NULLIF(facility_id, ''::text) IS NULL) OR (NOT has_metering_point) OR (price_area_code IS NULL)) THEN 'needs_facility_data'::text
            ELSE 'ready_for_switch'::text
        END AS status,
        CASE
            WHEN has_open_data_request THEN 'normal'::text
            WHEN ((NOT has_signed_power_of_attorney) OR (grid_owner_id IS NULL)) THEN 'high'::text
            ELSE 'normal'::text
        END AS priority,
    array_remove(ARRAY[
        CASE
            WHEN (NULLIF(facility_id, ''::text) IS NULL) THEN 'facility_id'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT has_metering_point) THEN 'metering_point_id'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (grid_owner_id IS NULL) THEN 'grid_owner'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (price_area_code IS NULL) THEN 'price_area'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT has_signed_power_of_attorney) THEN 'power_of_attorney'::text
            ELSE NULL::text
        END], NULL::text) AS missing_fields,
        CASE
            WHEN has_open_data_request THEN 'Följ upp nätägarens svar'::text
            WHEN (NOT has_signed_power_of_attorney) THEN 'Ladda upp eller verifiera fullmakt'::text
            WHEN (grid_owner_id IS NULL) THEN 'Verifiera nätägare/nätområde'::text
            WHEN ((NULLIF(facility_id, ''::text) IS NULL) OR (NOT has_metering_point) OR (price_area_code IS NULL)) THEN 'Begär uppgifter från nätägare'::text
            ELSE 'Starta leverantörsbyte'::text
        END AS next_action,
        CASE
            WHEN has_open_data_request THEN 'Begäran är skickad eller köad. Följ upp svar och koppla inkommen Z02/manuellt svar till kundkortet.'::text
            WHEN (NOT has_signed_power_of_attorney) THEN 'Kunden är sparad, men utskick till nätägare stoppas tills signerad fullmakt finns.'::text
            WHEN (grid_owner_id IS NULL) THEN 'Adress/postnummer kan vara förslag, men verifierad nätägare eller nätområdeskod saknas.'::text
            WHEN ((NULLIF(facility_id, ''::text) IS NULL) OR (NOT has_metering_point) OR (price_area_code IS NULL)) THEN 'Anläggnings-ID, mätpunkt eller elområde saknas. Begär uppgifter innan switch.'::text
            ELSE 'Anläggningsdata ser komplett ut. Nästa steg är leverantörsbyte eller aktiv kundprocess.'::text
        END AS description,
    created_at,
    updated_at,
    (('/admin/customers/'::text || (customer_id)::text) ||
        CASE
            WHEN (NOT has_signed_power_of_attorney) THEN '?tab=authorization-documents'::text
            WHEN ((NULLIF(facility_id, ''::text) IS NULL) OR (NOT has_metering_point) OR (grid_owner_id IS NULL) OR (price_area_code IS NULL) OR has_open_data_request) THEN '?tab=data-requests'::text
            ELSE '?tab=switch-operations'::text
        END) AS href
   FROM site_status ss
  WHERE (has_open_data_request OR (NOT has_signed_power_of_attorney) OR (grid_owner_id IS NULL) OR (NULLIF(facility_id, ''::text) IS NULL) OR (NOT has_metering_point) OR (price_area_code IS NULL));

--
-- Name: gridex_get_facility_work_queue(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_get_facility_work_queue(p_company_id uuid, p_limit integer DEFAULT 200) RETURNS SETOF public.gridex_facility_work_queue_v
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select *
  from public.gridex_facility_work_queue_v
  where p_company_id is null or company_id = p_company_id
  order by
    case priority when 'critical' then 4 when 'high' then 3 when 'normal' then 2 else 1 end desc,
    updated_at desc nulls last,
    created_at desc nulls last
  limit greatest(1, least(coalesce(p_limit, 200), 500))
$$;

--
-- Name: gridex_get_user_permissions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_get_user_permissions(p_user_id uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  with role_based as (
    select distinct coalesce(p.key, p.name) as permission_name
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id and coalesce(r.is_active, true)
    join public.role_permissions rp on rp.role_id = r.id and coalesce(rp.effect, 'allow') = 'allow'
    join public.permissions p on p.id = rp.permission_id
    where ur.user_id = p_user_id
      and coalesce(ur.is_active, true)
      and coalesce(ur.status, 'active') = 'active'
      and (
        (
          ur.company_id is null
          and public.gridex_normalize_platform_role(coalesce(r.key, r.name))
            in ('super_admin', 'platform_admin')
        )
        or exists (
          select 1 from public.company_memberships m
          where m.user_id = p_user_id
            and m.company_id = ur.company_id
            and m.status = 'active'
            and coalesce(m.is_active, true)
        )
      )
      and coalesce(p.key, p.name) is not null
  ),
  direct_permissions as (
    select distinct coalesce(p.key, p.name) as permission_name
    from public.user_permissions up
    join public.permissions p on p.id = up.permission_id
    where up.user_id = p_user_id and coalesce(p.key, p.name) is not null
  ),
  explicit_platform_admin_fallback as (
    select 'admin.access'::text as permission_name
    where exists (
      select 1 from public.admin_users au
      where au.user_id = p_user_id
        and coalesce(au.is_active, true)
        and public.gridex_normalize_platform_role(au.role) in ('super_admin', 'platform_admin')
    )
  )
  select coalesce(array_agg(distinct permission_name order by permission_name), '{}'::text[])
  from (
    select permission_name from role_based
    union select permission_name from direct_permissions
    union select permission_name from explicit_platform_admin_fallback
  ) q
  where permission_name is not null;
$$;

--
-- Name: FUNCTION gridex_get_user_permissions(p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_get_user_permissions(p_user_id uuid) IS 'F-18: permissions the user holds anywhere they are an active member. For platform-shared data only. Tenant decisions must use gridex_get_user_permissions_in_company / gridex_has_permission_in_company.';

--
-- Name: gridex_get_user_permissions_in_company(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_get_user_permissions_in_company(p_user_id uuid, p_company_id uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  with role_based as (
    select distinct coalesce(p.key, p.name) as permission_name
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id and coalesce(r.is_active, true)
    join public.role_permissions rp on rp.role_id = r.id and coalesce(rp.effect, 'allow') = 'allow'
    join public.permissions p on p.id = rp.permission_id
    where ur.user_id = p_user_id
      and coalesce(ur.is_active, true)
      and coalesce(ur.status, 'active') = 'active'
      and (
        -- platform roles apply everywhere; company roles only in their own company,
        -- and only while the membership backing them is active
        (
          ur.company_id is null
          and public.gridex_normalize_platform_role(coalesce(r.key, r.name))
            in ('super_admin', 'platform_admin')
        )
        or (
          p_company_id is not null
          and ur.company_id = p_company_id
          and exists (
            select 1 from public.company_memberships m
            where m.user_id = p_user_id
              and m.company_id = ur.company_id
              and m.status = 'active'
              and coalesce(m.is_active, true)
          )
        )
      )
      and coalesce(p.key, p.name) is not null
  ),
  direct_permissions as (
    select distinct coalesce(p.key, p.name) as permission_name
    from public.user_permissions up
    join public.permissions p on p.id = up.permission_id
    where up.user_id = p_user_id and coalesce(p.key, p.name) is not null
  ),
  explicit_platform_admin_fallback as (
    select 'admin.access'::text as permission_name
    where exists (
      select 1 from public.admin_users au
      where au.user_id = p_user_id
        and coalesce(au.is_active, true)
        and public.gridex_normalize_platform_role(au.role) in ('super_admin', 'platform_admin')
    )
  )
  select coalesce(array_agg(distinct permission_name order by permission_name), '{}'::text[])
  from (
    select permission_name from role_based
    union select permission_name from direct_permissions
    union select permission_name from explicit_platform_admin_fallback
  ) q
  where permission_name is not null;
$$;

--
-- Name: FUNCTION gridex_get_user_permissions_in_company(p_user_id uuid, p_company_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_get_user_permissions_in_company(p_user_id uuid, p_company_id uuid) IS 'F-2: company-scoped permission resolution. A company-bound role grants only inside its own company.';

--
-- Name: customer_blockers; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.customer_blockers (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    customer_id uuid NOT NULL,
    customer_site_id uuid,
    metering_point_id uuid,
    contract_id uuid,
    blocker_type text NOT NULL,
    severity text DEFAULT 'warning'::text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    title text NOT NULL,
    description text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by uuid,
    resolved_by uuid,
    resolved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT customer_blockers_severity_check CHECK ((severity = ANY (ARRAY['info'::text, 'warning'::text, 'blocking'::text, 'critical'::text]))),
    CONSTRAINT customer_blockers_status_check CHECK ((status = ANY (ARRAY['open'::text, 'pending_review'::text, 'resolved'::text, 'dismissed'::text, 'cancelled'::text])))
);

--
-- Name: gridex_work_queue_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_work_queue_v WITH (security_invoker='true') AS
 SELECT cb.id,
    cb.company_id,
    cb.customer_id,
    'Blockerare'::text AS source,
    COALESCE(c.customer_number, (cb.customer_id)::text) AS customer_number,
    COALESCE(NULLIF(c.company_name, ''::text), NULLIF(c.full_name, ''::text), NULLIF(TRIM(BOTH FROM concat_ws(' '::text, c.first_name, c.last_name)), ''::text), c.email, 'Kund utan namn'::text) AS customer_label,
    COALESCE(NULLIF(cb.title, ''::text), replace(COALESCE(cb.blocker_type, 'blocker'::text), '_'::text, ' '::text)) AS title,
    COALESCE(NULLIF(cb.description, ''::text), replace(COALESCE(cb.blocker_type, 'blocker'::text), '_'::text, ' '::text)) AS description,
    COALESCE(cb.status, 'open'::text) AS status,
        CASE
            WHEN (cb.severity = 'critical'::text) THEN 'critical'::text
            WHEN (cb.severity = 'warning'::text) THEN 'high'::text
            ELSE 'normal'::text
        END AS priority,
    cb.created_at,
    ('/admin/customers/'::text || (cb.customer_id)::text) AS href,
    'Öppna kundkort'::text AS action_label
   FROM (public.customer_blockers cb
     JOIN public.customers c ON (((c.id = cb.customer_id) AND (c.company_id = cb.company_id))))
  WHERE ((cb.status = ANY (ARRAY['open'::text, 'pending_review'::text, 'action_required'::text])) AND (COALESCE(c.source, ''::text) <> 'ediel_portal_test'::text) AND (COALESCE(c.status, ''::text) <> ALL (ARRAY['archived'::text, 'deleted'::text, 'deleted_test_only'::text, 'pending_deletion'::text])))
UNION ALL
 SELECT cir.id,
    cir.company_id,
    cir.customer_id,
    'Uppgiftsbegäran'::text AS source,
    COALESCE(c.customer_number, (cir.customer_id)::text) AS customer_number,
    COALESCE(NULLIF(c.company_name, ''::text), NULLIF(c.full_name, ''::text), NULLIF(TRIM(BOTH FROM concat_ws(' '::text, c.first_name, c.last_name)), ''::text), c.email, 'Kund utan namn'::text) AS customer_label,
    ('Väntar på '::text ||
        CASE
            WHEN (cir.target_party_type = 'current_supplier'::text) THEN 'nuvarande leverantör'::text
            WHEN (cir.target_party_type = 'grid_owner'::text) THEN 'nätägare'::text
            ELSE 'kund'::text
        END) AS title,
    COALESCE(NULLIF(cir.blocker_reason, ''::text), NULLIF(cir.notes, ''::text), replace(COALESCE(cir.request_type, 'uppgiftsbegäran'::text), '_'::text, ' '::text)) AS description,
    COALESCE(cir.status, 'pending'::text) AS status,
        CASE
            WHEN (cir.status = ANY (ARRAY['missing_authorization'::text, 'blocked'::text, 'negative_aperak'::text, 'route_missing'::text])) THEN 'high'::text
            ELSE 'normal'::text
        END AS priority,
    cir.created_at,
    (('/admin/customers/'::text || (cir.customer_id)::text) || '?tab=data-requests'::text) AS href,
    'Öppna uppgiftsbegäran'::text AS action_label
   FROM (public.customer_info_requests cir
     JOIN public.customers c ON (((c.id = cir.customer_id) AND (c.company_id = cir.company_id))))
  WHERE ((cir.status = ANY (ARRAY['open'::text, 'new'::text, 'pending'::text, 'pending_review'::text, 'action_required'::text, 'missing_authorization'::text, 'blocked'::text, 'route_missing'::text, 'manual_review_required'::text, 'failed'::text, 'sent'::text, 'waiting_for_z02'::text, 'waiting_response'::text])) AND (COALESCE(c.source, ''::text) <> 'ediel_portal_test'::text) AND (COALESCE(c.status, ''::text) <> ALL (ARRAY['archived'::text, 'deleted'::text, 'deleted_test_only'::text, 'pending_deletion'::text])))
UNION ALL
 SELECT gor.id,
    gor.company_id,
    gor.customer_id,
    'Nätägare'::text AS source,
    COALESCE(c.customer_number, (gor.customer_id)::text) AS customer_number,
    COALESCE(NULLIF(c.company_name, ''::text), NULLIF(c.full_name, ''::text), NULLIF(TRIM(BOTH FROM concat_ws(' '::text, c.first_name, c.last_name)), ''::text), c.email, 'Kund utan namn'::text) AS customer_label,
    'Begäran till nätägare'::text AS title,
    COALESCE(NULLIF(gor.failure_reason, ''::text), NULLIF(gor.notes, ''::text), replace(COALESCE(gor.request_scope, 'uppgiftsbegäran'::text), '_'::text, ' '::text)) AS description,
    COALESCE(gor.status, 'pending'::text) AS status,
        CASE
            WHEN (gor.status = 'failed'::text) THEN 'high'::text
            ELSE 'normal'::text
        END AS priority,
    gor.created_at,
    (('/admin/customers/'::text || (gor.customer_id)::text) || '?tab=data-requests'::text) AS href,
    'Öppna kundkort'::text AS action_label
   FROM (public.grid_owner_data_requests gor
     JOIN public.customers c ON (((c.id = gor.customer_id) AND (c.company_id = gor.company_id))))
  WHERE ((gor.status = ANY (ARRAY['pending'::text, 'sent'::text, 'failed'::text])) AND (COALESCE(c.source, ''::text) <> 'ediel_portal_test'::text) AND (COALESCE(c.status, ''::text) <> ALL (ARRAY['archived'::text, 'deleted'::text, 'deleted_test_only'::text, 'pending_deletion'::text])))
UNION ALL
 SELECT cot.id,
    cot.company_id,
    cot.customer_id,
    'Ärende'::text AS source,
    COALESCE(c.customer_number, (cot.customer_id)::text) AS customer_number,
    COALESCE(NULLIF(c.company_name, ''::text), NULLIF(c.full_name, ''::text), NULLIF(TRIM(BOTH FROM concat_ws(' '::text, c.first_name, c.last_name)), ''::text), c.email, 'Kund utan namn'::text) AS customer_label,
    COALESCE(NULLIF(cot.title, ''::text), replace(COALESCE(cot.task_type, 'åtgärd'::text), '_'::text, ' '::text)) AS title,
    COALESCE(NULLIF(cot.description, ''::text), replace(COALESCE(cot.task_type, 'åtgärd'::text), '_'::text, ' '::text)) AS description,
    COALESCE(cot.status, 'open'::text) AS status,
        CASE
            WHEN (cot.priority = ANY (ARRAY['critical'::text, 'high'::text, 'low'::text])) THEN cot.priority
            ELSE 'normal'::text
        END AS priority,
    cot.created_at,
    ('/admin/customers/'::text || (cot.customer_id)::text) AS href,
    'Öppna kundkort'::text AS action_label
   FROM (public.customer_operation_tasks cot
     JOIN public.customers c ON (((c.id = cot.customer_id) AND (c.company_id = cot.company_id))))
  WHERE ((cot.status = ANY (ARRAY['open'::text, 'new'::text, 'pending'::text, 'action_required'::text])) AND (COALESCE(c.source, ''::text) <> 'ediel_portal_test'::text) AND (COALESCE(c.status, ''::text) <> ALL (ARRAY['archived'::text, 'deleted'::text, 'deleted_test_only'::text, 'pending_deletion'::text])))
UNION ALL
 SELECT ssr.id,
    ssr.company_id,
    ssr.customer_id,
    'Leverantörsbyte'::text AS source,
    COALESCE(c.customer_number, (ssr.customer_id)::text) AS customer_number,
    COALESCE(NULLIF(c.company_name, ''::text), NULLIF(c.full_name, ''::text), NULLIF(TRIM(BOTH FROM concat_ws(' '::text, c.first_name, c.last_name)), ''::text), c.email, 'Kund utan namn'::text) AS customer_label,
    'Leverantörsbyte behöver uppföljning'::text AS title,
    replace(COALESCE(ssr.request_type, 'supplier_switch'::text), '_'::text, ' '::text) AS description,
    COALESCE(ssr.status, 'pending'::text) AS status,
        CASE
            WHEN (ssr.status = ANY (ARRAY['accepted'::text, 'ready'::text])) THEN 'high'::text
            ELSE 'normal'::text
        END AS priority,
    ssr.created_at,
    (('/admin/customers/'::text || (ssr.customer_id)::text) || '?tab=supplier-switch'::text) AS href,
    'Öppna leverantörsbyte'::text AS action_label
   FROM (public.supplier_switch_requests ssr
     JOIN public.customers c ON (((c.id = ssr.customer_id) AND (c.company_id = ssr.company_id))))
  WHERE ((ssr.status = ANY (ARRAY['draft'::text, 'ready'::text, 'queued'::text, 'submitted'::text, 'accepted'::text, 'pending'::text, 'open'::text])) AND (COALESCE(c.source, ''::text) <> 'ediel_portal_test'::text) AND (COALESCE(c.status, ''::text) <> ALL (ARRAY['archived'::text, 'deleted'::text, 'deleted_test_only'::text, 'pending_deletion'::text])));

--
-- Name: gridex_get_work_queue(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_get_work_queue(p_company_id uuid, p_limit integer DEFAULT 200) RETURNS SETOF public.gridex_work_queue_v
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select *
  from public.gridex_work_queue_v
  where p_company_id is null or company_id = p_company_id
  order by
    case priority when 'critical' then 4 when 'high' then 3 when 'normal' then 2 else 1 end desc,
    created_at desc nulls last
  limit greatest(1, least(coalesce(p_limit, 200), 500))
$$;

--
-- Name: gridex_grant_portfolio_settlement_permission(uuid, uuid, text, uuid, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_grant_portfolio_settlement_permission(p_actor_user_id uuid, p_user_id uuid, p_permission text, p_company_id uuid, p_portfolio_id uuid DEFAULT NULL::uuid, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  if not public.gridex_portfolio_actor_is_superadmin(p_actor_user_id) then
    raise exception using errcode='42501',message='portfolio_manage_access_superadmin_only';
  end if;
  if p_permission='portfolio_settlement.manage_access'
     or p_permission not like 'portfolio_settlement.%' then
    raise exception using errcode='22023',message='portfolio_permission_not_delegable';
  end if;
  if nullif(btrim(p_reason),'') is null then
    raise exception using errcode='22023',message='portfolio_permission_reason_required';
  end if;
  if p_portfolio_id is not null and not exists(
    select 1 from public.portfolios p where p.id=p_portfolio_id and p.company_id=p_company_id
  ) then
    raise exception using errcode='23514',message='portfolio_permission_scope_mismatch';
  end if;
  insert into public.portfolio_settlement_permission_grants(
    user_id,permission,company_id,portfolio_id,granted_by,expires_at,reason
  ) values(
    p_user_id,p_permission,p_company_id,p_portfolio_id,p_actor_user_id,p_expires_at,btrim(p_reason)
  ) returning id into v_id;
  insert into public.portfolio_settlement_audit_log(
    company_id,portfolio_id,actor_user_id,permission,action,new_values,reason
  ) values(
    p_company_id,p_portfolio_id,p_actor_user_id,'portfolio_settlement.manage_access','access.granted',
    jsonb_build_object('grant_id',v_id,'user_id',p_user_id,'permission',p_permission,'expires_at',p_expires_at),
    btrim(p_reason)
  );
  return v_id;
end $$;

--
-- Name: gridex_grant_portfolio_settlement_role(uuid, uuid, text, uuid, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_grant_portfolio_settlement_role(p_actor_user_id uuid, p_user_id uuid, p_role_key text, p_company_id uuid, p_portfolio_id uuid DEFAULT NULL::uuid, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_reason text DEFAULT NULL::text) RETURNS uuid[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_permissions text[]; v_permission text; v_ids uuid[]:=array[]::uuid[]; v_id uuid;
begin
  if not public.gridex_portfolio_actor_is_superadmin(p_actor_user_id) then
    raise exception using errcode='42501',message='portfolio_manage_access_superadmin_only';
  end if;
  if nullif(btrim(p_reason),'') is null then
    raise exception using errcode='22023',message='portfolio_permission_reason_required';
  end if;
  select t.permissions into v_permissions
  from public.portfolio_settlement_role_templates t where t.role_key=p_role_key;
  if v_permissions is null then
    raise exception using errcode='22023',message='portfolio_settlement_role_unknown';
  end if;
  foreach v_permission in array v_permissions loop
    v_id:=public.gridex_grant_portfolio_settlement_permission(
      p_actor_user_id,p_user_id,v_permission,p_company_id,p_portfolio_id,
      p_expires_at,concat('[',p_role_key,'] ',btrim(p_reason))
    );
    v_ids:=array_append(v_ids,v_id);
  end loop;
  return v_ids;
end $$;

--
-- Name: gridex_grid_owner_name_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_grid_owner_name_key(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
  select regexp_replace(
    regexp_replace(
      regexp_replace(lower(btrim(coalesce(p_name, ''))), '[^a-z0-9åäö]+', ' ', 'g'),
      '\\s+(ab|aktiebolag)$',
      '',
      'g'
    ),
    '\\s+',
    '',
    'g'
  );
$_$;

--
-- Name: gridex_guard_billing_underlay_exact_refs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_guard_billing_underlay_exact_refs() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if new.status in ('ready','priced','approved','exported','invoiced') and (new.contract_id is null or new.pricing_snapshot_id is null) then
    raise exception using errcode='23514',message='billing_underlay_requires_exact_contract_and_snapshot';
  end if;
  return new;
end $$;

--
-- Name: gridex_guard_canonical_public_offer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_guard_canonical_public_offer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Stand-alone public offers are no longer allowed. Every compatibility row,
  -- including a non-public draft, must point back to the canonical internal
  -- contract offer. This also makes the legacy gridex_publish_contract_version
  -- path fail closed instead of creating a parallel pricing/legal model.
  if new.source_contract_offer_id is null then
    raise exception using errcode='23514',message='canonical_contract_source_required';
  end if;

  if (coalesce(new.is_public,false)
      or coalesce(new.website_enabled,false)
      or coalesce(new.website_cta_enabled,false)
      or coalesce(new.publication_status,'draft')='published')
     and (new.contract_product_id is null
          or new.contract_product_version_id is null
          or new.contract_publication_version_id is null) then
    raise exception using errcode='23514',message='canonical_contract_publication_required';
  end if;
  return new;
end $$;

--
-- Name: gridex_guard_immutable_meter_reading_series(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_guard_immutable_meter_reading_series() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if tg_op='DELETE' then raise exception 'meter_reading_series_is_immutable' using errcode='55000'; end if;
  if (to_jsonb(new)-'is_current') is distinct from (to_jsonb(old)-'is_current') then
    raise exception 'meter_reading_series_is_immutable' using errcode='55000';
  end if;
  return new;
end $$;

--
-- Name: gridex_guard_immutable_meter_reading_value(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_guard_immutable_meter_reading_value() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  raise exception 'meter_reading_value_is_immutable' using errcode='55000';
end $$;

--
-- Name: gridex_guard_meter_reading_series_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_guard_meter_reading_series_tenant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_company uuid;
begin
  new.version_no := coalesce(new.version_no,1);
  if new.source_ediel_message_id is not null then
    select company_id into v_company from public.ediel_messages where id=new.source_ediel_message_id;
    if v_company is distinct from new.company_id then
      raise exception 'meter_reading_series_source_tenant_mismatch' using errcode='23514';
    end if;
  end if;
  if new.supersedes_series_id is not null then
    select company_id into v_company from public.meter_reading_series where id=new.supersedes_series_id;
    if v_company is distinct from new.company_id then
      raise exception 'meter_reading_series_supersedes_tenant_mismatch' using errcode='23514';
    end if;
  end if;
  return new;
end $$;

--
-- Name: gridex_guard_meter_reading_value_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_guard_meter_reading_value_tenant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare v_company uuid;
begin
  select company_id into v_company from public.meter_reading_series where id=new.series_id;
  if v_company is distinct from new.company_id then
    raise exception 'meter_reading_value_series_tenant_mismatch' using errcode='23514';
  end if;
  return new;
end $$;

--
-- Name: gridex_guard_metering_value_source_tenant_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_guard_metering_value_source_tenant_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not exists (
    select 1 from public.metering_values mv
    where mv.id = new.metering_value_id and mv.company_id = new.company_id
  ) then
    raise exception 'metering_value_source_metering_value_tenant_mismatch' using errcode='23503';
  end if;
  if not exists (
    select 1 from public.normalized_metering_values nmv
    where nmv.id = new.normalized_metering_value_id and nmv.company_id = new.company_id
  ) then
    raise exception 'metering_value_source_normalized_value_tenant_mismatch' using errcode='23503';
  end if;
  if not exists (
    select 1 from public.ediel_messages em
    where em.id = new.source_ediel_message_id and em.company_id = new.company_id
  ) then
    raise exception 'metering_value_source_ediel_message_tenant_mismatch' using errcode='23503';
  end if;
  return new;
end;
$$;

--
-- Name: gridex_guard_portfolio_estimate_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_guard_portfolio_estimate_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op='DELETE' or old.is_current=false or new.is_current<>false
     or (to_jsonb(new)-'is_current')<>(to_jsonb(old)-'is_current') then
    raise exception using errcode='55000',message='portfolio_estimate_append_only';
  end if;
  return new;
end $$;

--
-- Name: gridex_guard_portfolio_invoice_binding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_guard_portfolio_invoice_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op='DELETE' or old.customer_invoice_id is not null
     or new.customer_invoice_id is null
     or new.invoice_idempotency_key is null
     or (to_jsonb(new)-'customer_invoice_id'-'invoice_idempotency_key')
       <>(to_jsonb(old)-'customer_invoice_id'-'invoice_idempotency_key') then
    raise exception using errcode='55000',message='portfolio_invoice_binding_immutable';
  end if;
  return new;
end $$;

--
-- Name: gridex_guard_portfolio_invoice_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_guard_portfolio_invoice_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'UPDATE' and old.status in ('issued', 'sent', 'exported', 'paid') and (
    new.portfolio_id is distinct from old.portfolio_id
    or new.customer_contract_id is distinct from old.customer_contract_id
    or new.price_plan_version_id is distinct from old.price_plan_version_id
    or new.portfolio_monthly_settlement_id is distinct from old.portfolio_monthly_settlement_id
    or new.portfolio_settlement_revision is distinct from old.portfolio_settlement_revision
    or new.portfolio_settlement_sha256 is distinct from old.portfolio_settlement_sha256
    or new.portfolio_settlement_snapshot is distinct from old.portfolio_settlement_snapshot
    or new.portfolio_price_area_code is distinct from old.portfolio_price_area_code
    or new.portfolio_delivery_month is distinct from old.portfolio_delivery_month
    or new.portfolio_price_ore_per_kwh is distinct from old.portfolio_price_ore_per_kwh
    or new.portfolio_management_fee_ore_per_kwh is distinct from old.portfolio_management_fee_ore_per_kwh
    or new.portfolio_gross_energy_cost_sek is distinct from old.portfolio_gross_energy_cost_sek
    or new.portfolio_energy_volume_kwh is distinct from old.portfolio_energy_volume_kwh
    or new.delivery_month is distinct from old.delivery_month
    or new.price_area_code is distinct from old.price_area_code
    or new.consumption_kwh is distinct from old.consumption_kwh
    or new.portfolio_share_percent is distinct from old.portfolio_share_percent
    or new.spot_share_percent is distinct from old.spot_share_percent
    or new.fixed_share_percent is distinct from old.fixed_share_percent
    or new.fixed_price_sek_per_kwh is distinct from old.fixed_price_sek_per_kwh
    or new.portfolio_energy_cost_sek is distinct from old.portfolio_energy_cost_sek
    or new.spot_energy_cost_sek is distinct from old.spot_energy_cost_sek
    or new.fixed_energy_cost_sek is distinct from old.fixed_energy_cost_sek
    or new.management_fee_sek is distinct from old.management_fee_sek
    or new.other_fees_sek is distinct from old.other_fees_sek
    or new.vat_rate is distinct from old.vat_rate
    or new.calculation_snapshot is distinct from old.calculation_snapshot
    or new.calculation_snapshot_sha256 is distinct from old.calculation_snapshot_sha256
  ) then
    raise exception using errcode = '55000', message = 'issued_invoice_portfolio_evidence_immutable';
  end if;

  if new.status in ('issued', 'sent', 'exported', 'paid')
     and new.portfolio_id is not null
     and (
       new.portfolio_monthly_settlement_id is null
       or new.portfolio_settlement_status <> 'locked'
       or nullif(new.portfolio_settlement_sha256, '') is null
       or coalesce(new.portfolio_settlement_snapshot, '{}'::jsonb) = '{}'::jsonb
       or new.customer_contract_id is null
       or new.price_plan_version_id is null
       or new.delivery_month is null
       or new.price_area_code is null
       or new.consumption_kwh is null
       or new.portfolio_share_percent is null
       or new.spot_share_percent is null
       or new.fixed_share_percent is null
       or abs(
         new.portfolio_share_percent
         + new.spot_share_percent
         + new.fixed_share_percent
         - 100
       ) > 0.000001
       or new.portfolio_energy_cost_sek is null
       or new.spot_energy_cost_sek is null
       or new.fixed_energy_cost_sek is null
       or (new.fixed_share_percent > 0 and new.fixed_price_sek_per_kwh is null)
       or new.management_fee_sek is null
       or new.other_fees_sek is null
       or new.vat_rate is null
       or nullif(new.calculation_snapshot_sha256, '') is null
       or coalesce(new.calculation_snapshot, '{}'::jsonb) = '{}'::jsonb
     ) then
    raise exception using errcode = '23514', message = 'final_invoice_requires_locked_portfolio_settlement_evidence';
  end if;
  return new;
end $$;

--
-- Name: gridex_guard_portfolio_settlement_immutability(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_guard_portfolio_settlement_immutability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op='DELETE' then raise exception using errcode='55000',message='portfolio_settlement_append_only'; end if;
  if old.status<>new.status and not (
    (old.status='draft' and new.status='calculated')
    or (old.status='calculated' and new.status='reviewed')
    or (old.status='reviewed' and new.status='final')
    or (old.status='final' and new.status='locked')
  ) then
    raise exception using errcode='23514',message='invalid_portfolio_settlement_transition';
  end if;
  if new.status in('final','locked') and (
    new.portfolio_price_ore_per_kwh is null
    or new.calculation_snapshot_sha256 is null
    or new.calculated_at is null or new.reviewed_at is null or new.approved_at is null
  ) then
    raise exception using errcode='23514',message='portfolio_settlement_final_evidence_incomplete';
  end if;
  if old.status='locked' and not (
    coalesce(current_setting('gridex.portfolio_correction_write',true),'')='on'
    and new.is_current=false and new.superseded_by_settlement_id is not null
    and (to_jsonb(new)-'is_current'-'superseded_by_settlement_id')=(to_jsonb(old)-'is_current'-'superseded_by_settlement_id')
  ) then
    raise exception using errcode='55000',message='locked_portfolio_settlement_immutable';
  end if;
  if old.status='final' and not (
    (
      new.status='locked'
      and (to_jsonb(new)-'status'-'locked_by'-'locked_at')
        =(to_jsonb(old)-'status'-'locked_by'-'locked_at')
    ) or (
      coalesce(current_setting('gridex.portfolio_correction_write',true),'')='on'
      and new.status='final' and new.is_current=false
      and new.superseded_by_settlement_id is not null
      and (to_jsonb(new)-'is_current'-'superseded_by_settlement_id')
        =(to_jsonb(old)-'is_current'-'superseded_by_settlement_id')
    )
  ) then
    raise exception using errcode='55000',message='final_portfolio_settlement_immutable_create_correction_revision';
  end if;
  return new;
end $$;

--
-- Name: gridex_guard_primary_tenant_website_client_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_guard_primary_tenant_website_client_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_environment text;
  v_primary boolean;
begin
  v_environment := coalesce(nullif(new.metadata->>'environment',''), 'production');
  perform pg_advisory_xact_lock(
    hashtextextended(
      new.company_id::text || ':tenant_website:' || v_environment,
      0
    )
  );

  v_primary := coalesce(
    case
      when lower(coalesce(new.metadata->>'primary','true')) in ('true','1','yes') then true
      when lower(coalesce(new.metadata->>'primary','true')) in ('false','0','no') then false
      else true
    end,
    true
  );

  if new.profile_key = 'tenant_website'
     and new.status = 'active'
     and new.deleted_at is null
     and v_primary
     and exists (
       select 1
       from public.integration_api_clients existing
       where existing.company_id = new.company_id
         and existing.id is distinct from new.id
         and existing.profile_key = 'tenant_website'
         and existing.status = 'active'
         and existing.deleted_at is null
         and coalesce(nullif(existing.metadata->>'environment',''), 'production') = v_environment
         and lower(coalesce(existing.metadata->>'primary','true')) not in ('false','0','no')
     )
  then
    raise exception using
      errcode = '23505',
      message = 'DUPLICATE_PRIMARY_TENANT_WEBSITE_CLIENT',
      detail = format('company_id=%s environment=%s', new.company_id, v_environment);
  end if;

  return new;
end;
$$;

--
-- Name: gridex_guard_supplier_switch_dispatch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_guard_supplier_switch_dispatch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_contract_id uuid; v_evidence jsonb;
begin
  if new.status not in('ready','queued','submitted','sent','processing') then
    return new;
  end if;
  v_contract_id:=coalesce(
    new.customer_contract_id,new.contract_id,
    nullif(new.metadata->>'contract_id','')::uuid
  );
  if v_contract_id is null then
    raise exception using errcode='23514',message='supplier_switch_exact_contract_required';
  end if;
  v_evidence:=public.gridex_assert_supplier_switch_ready(new.company_id,v_contract_id);
  new.contract_id:=v_contract_id;
  new.customer_contract_id:=v_contract_id;
  new.readiness_snapshot:=coalesce(new.readiness_snapshot,'{}'::jsonb)||v_evidence;
  new.readiness_checked_at:=now();
  return new;
end $$;

--
-- Name: gridex_guard_tenant_website_activation_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_guard_tenant_website_activation_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_receipt_id_text text;
begin
  if new.profile_key is distinct from 'tenant_website'
     or new.status is distinct from 'active'
     or (tg_op = 'UPDATE' and old.status = 'active')
  then
    return new;
  end if;

  if new.deleted_at is not null or new.revoked_at is not null then
    raise exception using
      errcode = '23514',
      message = 'TENANT_WEBSITE_ACTIVATION_REQUIRES_CANONICAL_GO_LIVE';
  end if;

  -- Lifecycle resume: offboarding paused an already launch-ready client and is
  -- restoring status=active while clearing lifecycle_* metadata keys.
  if tg_op = 'UPDATE'
     and old.status = 'paused'
     and coalesce((old.metadata->>'lifecycle_paused_by_tenant')::boolean, false)
     and new.launch_ready is true
     and coalesce(new.metadata->>'go_live_flow','') = 'canonical_tenant_website_v2'
     and nullif(coalesce(new.metadata->>'provisioning_receipt_id',''), '') is not null
     and not coalesce((new.metadata->>'lifecycle_paused_by_tenant')::boolean, false)
  then
    v_receipt_id_text := nullif(coalesce(new.metadata->>'provisioning_receipt_id',''), '');
    if exists (
      select 1
      from public.tenant_website_installation_receipts receipt
      where receipt.id::text = v_receipt_id_text
        and receipt.company_id = new.company_id
        and receipt.api_client_id = new.id
        and receipt.profile_key = 'tenant_website'
        and receipt.state = 'completed'
        and receipt.completed_at is not null
        and nullif(receipt.receipt_sha256,'') is not null
    ) then
      return new;
    end if;
  end if;

  v_receipt_id_text := nullif(coalesce(new.metadata->>'provisioning_receipt_id',''), '');

  if coalesce(new.metadata->>'go_live_flow','') <> 'canonical_tenant_website_v2'
     or v_receipt_id_text is null
     or jsonb_typeof(coalesce(new.launch_blockers,'[]'::jsonb)) <> 'array'
     or not exists (
       select 1
       from jsonb_array_elements(coalesce(new.launch_blockers,'[]'::jsonb)) blocker
       where blocker->>'code' in ('provisioning_preflight_pending','provisioning_retry_in_progress')
     )
     or not exists (
       select 1
       from public.tenant_website_installation_receipts receipt
       where receipt.id::text = v_receipt_id_text
         and receipt.company_id = new.company_id
         and receipt.profile_key = 'tenant_website'
         and receipt.environment = coalesce(nullif(new.metadata->>'environment',''), 'production')
         and receipt.state in ('company_ready','client_ready','credential_created','failed')
     )
  then
    raise exception using
      errcode = '23514',
      message = 'TENANT_WEBSITE_ACTIVATION_REQUIRES_CANONICAL_GO_LIVE',
      detail = 'Use the canonical tenant website provision/revalidation action instead of a generic status activation.';
  end if;

  return new;
end
$$;

--
-- Name: FUNCTION gridex_guard_tenant_website_activation_v2(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_guard_tenant_website_activation_v2() IS 'Fail-closed guard: tenant_website credentials may enter active only through canonical_tenant_website_v2 provisioning/revalidation, or via lifecycle resume of a launch-ready client paused by tenant offboarding with a completed binding receipt.';

--
-- Name: gridex_has_permission(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_has_permission(p_user_id uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  select p_user_id is not null
    and p_permission is not null
    and p_permission = any(public.gridex_get_user_permissions(p_user_id));
$$;

--
-- Name: FUNCTION gridex_has_permission(p_user_id uuid, p_permission text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_has_permission(p_user_id uuid, p_permission text) IS 'F-18: true if the user holds the permission in any active membership or via a platform role. Never sufficient on its own for a tenant table -- pair it with a company predicate or a restrictive tenant guard.';

--
-- Name: gridex_has_permission_in_company(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_has_permission_in_company(p_company_id uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  select p_company_id is not null
    and p_permission is not null
    and (select auth.uid()) is not null
    and p_permission = any(
      public.gridex_get_user_permissions_in_company((select auth.uid()), p_company_id)
    );
$$;

--
-- Name: FUNCTION gridex_has_permission_in_company(p_company_id uuid, p_permission text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_has_permission_in_company(p_company_id uuid, p_permission text) IS 'F-2: use this in RLS policies. gridex_has_permission(uid, perm) carries no tenant binding.';

--
-- Name: gridex_import_grid_area_geojson_feature(text, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_import_grid_area_geojson_feature(p_feature_id text, p_properties jsonb, p_geometry_geojson jsonb, p_source_url text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'extensions'
    AS $$
declare
  v_area_id uuid;
  v_code text;
  v_name text;
  v_owner_name text;
  v_price_area text;
  v_geometry_type text;
  v_property_keys text;
  v_geom extensions.geometry(MultiPolygon, 3006);
begin
  if p_properties is null or jsonb_typeof(p_properties) <> 'object' then
    raise exception 'svk_feature_properties_invalid'
      using errcode = '22023',
            detail = jsonb_build_object('feature_id', p_feature_id)::text;
  end if;

  select string_agg(key, ', ' order by key)
  into v_property_keys
  from jsonb_object_keys(p_properties) as keys(key);

  -- The official SVK FeatureServer uses Natomrade, Namn, Agare and Elomrade.
  -- Older aliases remain supported so an archived source can still be audited.
  v_code := upper(nullif(btrim(public.gridex_json_text(
    p_properties,
    'Natomrade','NATOMRADE','natomrade',
    'NATOMRADESKOD','NÄTOMRÅDESKOD','Nätområdeskod','natomradeskod',
    'grid_area_code','GRID_AREA_CODE','OMR_KOD','OMRKOD','OMRÅDESKOD',
    'omradeskod','ELNATSOMRADE','ELNÄTSOMRÅDE','kod','KOD'
  )), ''));
  v_name := nullif(btrim(public.gridex_json_text(
    p_properties,
    'Namn','NAMN','namn',
    'NATOMRADESNAMN','NÄTOMRÅDESNAMN','Nätområdets namn','natomradesnamn',
    'grid_area_name','OMR_NAMN'
  )), '');
  v_owner_name := nullif(btrim(public.gridex_json_text(
    p_properties,
    'Agare','AGARE','agare','Ägare','ägare',
    'ELNATSFORETAG','ELNÄTSFÖRETAG','Elnätsföretag','elnatsforetag',
    'grid_owner_name','NATAGARE','NÄTÄGARE','owner','FORETAG','FÖRETAG'
  )), '');
  v_price_area := upper(nullif(btrim(public.gridex_json_text(
    p_properties,
    'Elomrade','ELOMRADE','elomrade','Elområde','ELOMRÅDE',
    'price_area','PRICE_AREA','SE_OMRADE','elomr'
  )), ''));

  if v_code is null then
    raise exception 'svk_grid_area_code_missing'
      using errcode = '22023',
            detail = jsonb_build_object(
              'feature_id', p_feature_id,
              'required_source_field', 'Natomrade',
              'available_property_keys', v_property_keys
            )::text;
  end if;
  if v_name is null then
    raise exception 'svk_grid_area_name_missing'
      using errcode = '22023',
            detail = jsonb_build_object(
              'feature_id', p_feature_id,
              'grid_area_code', v_code,
              'required_source_field', 'Namn'
            )::text;
  end if;
  if v_owner_name is null then
    raise exception 'svk_grid_owner_name_missing'
      using errcode = '22023',
            detail = jsonb_build_object(
              'feature_id', p_feature_id,
              'grid_area_code', v_code,
              'required_source_field', 'Agare'
            )::text;
  end if;
  if v_price_area not in ('SE1','SE2','SE3','SE4') then
    raise exception 'svk_price_area_invalid'
      using errcode = '22023',
            detail = jsonb_build_object(
              'feature_id', p_feature_id,
              'grid_area_code', v_code,
              'required_source_field', 'Elomrade',
              'actual_value', v_price_area
            )::text;
  end if;

  v_area_id := public.gridex_import_grid_area_master_row(
    v_owner_name,
    v_name,
    v_code,
    v_price_area,
    'svk_arcgis',
    p_properties || jsonb_build_object(
      '_gridex_source_feature_id', p_feature_id,
      '_gridex_source_url', p_source_url
    )
  );

  if p_geometry_geojson is null or jsonb_typeof(p_geometry_geojson) <> 'object' then
    raise exception 'svk_geometry_missing'
      using errcode = '22023',
            detail = jsonb_build_object('feature_id', p_feature_id, 'grid_area_code', v_code)::text;
  end if;

  v_geometry_type := p_geometry_geojson ->> 'type';
  if v_geometry_type not in ('Polygon', 'MultiPolygon') then
    raise exception 'svk_geometry_type_invalid'
      using errcode = '22023',
            detail = jsonb_build_object(
              'feature_id', p_feature_id,
              'grid_area_code', v_code,
              'geometry_type', v_geometry_type
            )::text;
  end if;

  v_geom := extensions.ST_Multi(
    extensions.ST_Transform(
      extensions.ST_SetSRID(
        extensions.ST_GeomFromGeoJSON(p_geometry_geojson::text),
        4326
      ),
      3006
    )
  );

  if v_geom is null or extensions.ST_IsEmpty(v_geom) then
    raise exception 'svk_geometry_empty'
      using errcode = '22023',
            detail = jsonb_build_object('feature_id', p_feature_id, 'grid_area_code', v_code)::text;
  end if;

  insert into public.platform_grid_area_geometries (
    grid_area_id,
    grid_area_code,
    source_feature_id,
    source_url,
    source_properties,
    geometry,
    geometry_geojson,
    updated_at
  )
  values (
    v_area_id,
    v_code,
    p_feature_id,
    p_source_url,
    p_properties,
    v_geom,
    p_geometry_geojson,
    now()
  )
  on conflict (source, source_feature_id) where source_feature_id is not null
  do update set
    grid_area_id = excluded.grid_area_id,
    grid_area_code = excluded.grid_area_code,
    source_url = excluded.source_url,
    source_properties = excluded.source_properties,
    geometry = excluded.geometry,
    geometry_geojson = excluded.geometry_geojson,
    is_active = true,
    imported_at = now(),
    updated_at = now();

  return v_area_id;
end;
$$;

--
-- Name: FUNCTION gridex_import_grid_area_geojson_feature(p_feature_id text, p_properties jsonb, p_geometry_geojson jsonb, p_source_url text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_import_grid_area_geojson_feature(p_feature_id text, p_properties jsonb, p_geometry_geojson jsonb, p_source_url text) IS 'Imports one official SVK Nätområden GeoJSON feature. Canonical source fields: Natomrade, Namn, Agare, Elomrade.';

--
-- Name: gridex_import_grid_area_master_row(text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_import_grid_area_master_row(p_grid_owner_name text, p_grid_area_name text, p_grid_area_code text, p_price_area text, p_source text DEFAULT 'svk_esett'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $$
declare
  v_owner_id uuid;
  v_area_id uuid;
  v_code text := upper(nullif(trim(p_grid_area_code), ''));
  v_price_area text := upper(nullif(trim(p_price_area), ''));
  v_owner_key text := public.gridex_grid_owner_name_key(p_grid_owner_name);
  v_canonical_count integer := 0;
begin
  if v_code is null then
    raise exception 'grid_area_code is required';
  end if;
  if v_price_area not in ('SE1','SE2','SE3','SE4') then
    v_price_area := null;
  end if;

  select min(pgo.id::text)::uuid, count(*)::integer
    into v_owner_id, v_canonical_count
    from public.platform_grid_owners pgo
   where coalesce(pgo.is_active, true) = true
     and public.gridex_grid_owner_name_key(pgo.name) = v_owner_key
     and nullif(btrim(pgo.ediel_id), '') is not null
     and pgo.ops_grid_owner_id is not null;

  if v_canonical_count <> 1 then
    v_owner_id := null;
  end if;

  if v_owner_id is null then
    insert into public.platform_grid_owners(name, source, metadata, updated_at)
    values (
      nullif(trim(coalesce(p_grid_owner_name, 'Okänd nätägare')), ''),
      p_source,
      p_metadata,
      now()
    )
    on conflict (lower(name)) do update
      set updated_at = now(),
          metadata = public.platform_grid_owners.metadata || excluded.metadata
    returning id into v_owner_id;
  end if;

  insert into public.platform_grid_areas(
    grid_area_code,
    grid_area_name,
    grid_owner_id,
    grid_owner_name,
    price_area,
    source,
    metadata,
    updated_at
  )
  values (
    v_code,
    nullif(trim(p_grid_area_name), ''),
    v_owner_id,
    nullif(trim(p_grid_owner_name), ''),
    v_price_area,
    p_source,
    p_metadata,
    now()
  )
  on conflict (grid_area_code) do update set
    grid_area_name = coalesce(excluded.grid_area_name, public.platform_grid_areas.grid_area_name),
    grid_owner_id = coalesce(excluded.grid_owner_id, public.platform_grid_areas.grid_owner_id),
    grid_owner_name = coalesce(excluded.grid_owner_name, public.platform_grid_areas.grid_owner_name),
    price_area = coalesce(excluded.price_area, public.platform_grid_areas.price_area),
    source = excluded.source,
    metadata = public.platform_grid_areas.metadata || excluded.metadata,
    updated_at = now()
  returning id into v_area_id;

  return v_area_id;
end;
$$;

--
-- Name: gridex_ingest_metering_value_atomic(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ingest_metering_value_atomic(p_payload jsonb) RETURNS public.metering_values
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_company_id uuid := nullif(p_payload->>'company_id','')::uuid;
  v_customer_id uuid := nullif(p_payload->>'customer_id','')::uuid;
  v_site_id uuid := nullif(p_payload->>'site_id','')::uuid;
  v_customer_site_id uuid := nullif(p_payload->>'customer_site_id','')::uuid;
  v_metering_point_id uuid := nullif(p_payload->>'metering_point_id','')::uuid;
  v_key text := nullif(p_payload->>'canonical_dedupe_key','');
  v_existing public.metering_values%rowtype;
  v_inserted public.metering_values%rowtype;
  v_revision integer := 1;
  v_direction text := coalesce(nullif(p_payload->>'direction',''),case when p_payload->>'reading_type'='production' then 'production' else 'consumption' end);
  v_unit text := coalesce(nullif(p_payload->>'unit',''),'kWh');
  v_raw jsonb := coalesce(p_payload->'raw_payload','{}'::jsonb);
  v_normalized_id uuid;
  v_source_message_id uuid := nullif(p_payload->>'source_ediel_message_id','')::uuid;
  v_source_tx text := nullif(p_payload->>'source_transaction_reference','');
  v_source_line text := nullif(p_payload->>'source_line_reference','');
begin
  if v_company_id is null or v_customer_id is null or v_metering_point_id is null or v_key is null then
    raise exception 'metering_company_customer_point_key_required' using errcode='22023';
  end if;
  if not exists(select 1 from public.customers where company_id=v_company_id and id=v_customer_id) then
    raise exception 'metering_customer_tenant_mismatch' using errcode='23503';
  end if;
  if not exists(select 1 from public.metering_points where company_id=v_company_id and id=v_metering_point_id and customer_id=v_customer_id) then
    raise exception 'metering_point_tenant_or_customer_mismatch' using errcode='23503';
  end if;
  if (p_payload->>'period_start')::timestamptz >= (p_payload->>'period_end')::timestamptz then
    raise exception 'metering_period_invalid' using errcode='22023';
  end if;
  if v_direction not in ('consumption','production','net_consumption','net_production') then
    raise exception 'metering_direction_invalid' using errcode='22023';
  end if;
  if v_unit not in ('Wh','kWh','MWh') then raise exception 'metering_unit_invalid' using errcode='22023'; end if;

  select * into v_existing
    from public.metering_values
   where company_id=v_company_id and canonical_dedupe_key=v_key and is_current=true
   order by created_at desc,id desc limit 1 for update;

  if found and v_existing.value_kwh is not distinct from (p_payload->>'value_kwh')::numeric
           and v_existing.quality_code is not distinct from nullif(p_payload->>'quality_code','') then
    if v_source_message_id is not null then
      select id into v_normalized_id
        from public.normalized_metering_values
       where company_id=v_company_id
         and source_metering_value_id=v_existing.id
         and revision_status='current'
       order by created_at desc,id desc
       limit 1;
      if v_normalized_id is null then
        raise exception 'atomic_metering_projection_missing_for_existing_value' using errcode='23503';
      end if;
      insert into public.metering_value_sources(
        company_id,metering_value_id,normalized_metering_value_id,source_ediel_message_id,
        source_transaction_reference,source_line_reference,source_type
      ) values (
        v_company_id,v_existing.id,v_normalized_id,v_source_message_id,
        v_source_tx,v_source_line,coalesce(nullif(p_payload->>'source_system',''),'grid_owner')
      ) on conflict do nothing;
    end if;
    return v_existing;
  end if;

  if v_existing.id is not null then
    v_revision := coalesce(v_existing.revision_number,1)+1;
    update public.metering_values
       set is_current=false,value_status='replaced',revision_status='replaced',
           correction_reason=coalesce(nullif(p_payload->>'correction_reason',''),'Nytt mätvärde ersatte tidigare revision.')
     where id=v_existing.id and company_id=v_company_id;
    update public.normalized_metering_values
       set revision_status='replaced',status='replaced',updated_at=now()
     where company_id=v_company_id and source_metering_value_id=v_existing.id and revision_status='current';
  end if;

  insert into public.metering_values(
    company_id,customer_id,site_id,customer_site_id,metering_point_id,source_request_id,grid_owner_id,reading_type,
    value_kwh,quality_code,read_at,period_start,period_end,source_system,raw_payload,source_ediel_message_id,
    source_transaction_reference,source_line_reference,price_area,resolution,canonical_dedupe_key,is_current,previous_value_id,
    revision_number,correction_reason,value_status,revision_status,billing_status,register_code,product_code,direction,unit,created_by
  ) values (
    v_company_id,v_customer_id,v_site_id,v_customer_site_id,v_metering_point_id,nullif(p_payload->>'source_request_id','')::uuid,
    nullif(p_payload->>'grid_owner_id','')::uuid,coalesce(nullif(p_payload->>'reading_type',''),'consumption'),
    (p_payload->>'value_kwh')::numeric,nullif(p_payload->>'quality_code',''),(p_payload->>'read_at')::timestamptz,
    (p_payload->>'period_start')::timestamptz,(p_payload->>'period_end')::timestamptz,coalesce(nullif(p_payload->>'source_system',''),'grid_owner'),
    v_raw,v_source_message_id,v_source_tx,
    v_source_line,nullif(p_payload->>'price_area',''),nullif(p_payload->>'resolution',''),v_key,true,
    v_existing.id,v_revision,case when v_existing.id is null then null else coalesce(nullif(p_payload->>'correction_reason',''),'Korrigerat mätvärde.') end,
    'current','current','pending_match',nullif(p_payload->>'register_code',''),nullif(p_payload->>'product_code',''),v_direction,v_unit,
    nullif(p_payload->>'created_by','')::uuid
  ) returning * into v_inserted;

  if v_existing.id is not null then
    update public.metering_values set replaced_by_value_id=v_inserted.id where company_id=v_company_id and id=v_existing.id;
    update public.normalized_metering_values set replaced_by_value_id=v_inserted.id where company_id=v_company_id and source_metering_value_id=v_existing.id;
  end if;

  insert into public.normalized_metering_values(
    company_id,customer_id,customer_site_id,site_id,metering_point_id,facility_id,price_area,grid_area,period_start,period_end,
    resolution,quantity_kwh,quality_status,source_type,source_message_id,source_transaction_reference,source_line_reference,
    source_metering_value_id,raw_payload,status,revision_status,billing_status,register_code,product_code,direction,unit,
    canonical_dedupe_key,previous_value_id,revision_number,created_by
  ) values (
    v_company_id,v_customer_id,v_customer_site_id,v_site_id,v_metering_point_id,nullif(p_payload->>'facility_id',''),
    nullif(p_payload->>'price_area',''),nullif(p_payload->>'grid_area',''),(p_payload->>'period_start')::timestamptz,
    (p_payload->>'period_end')::timestamptz,nullif(p_payload->>'resolution',''),(p_payload->>'value_kwh')::numeric,
    nullif(p_payload->>'quality_code',''),coalesce(nullif(p_payload->>'source_system',''),'grid_owner'),
    v_source_message_id,v_source_tx,
    v_source_line,v_inserted.id,v_raw,'stored','current','pending_match',
    nullif(p_payload->>'register_code',''),nullif(p_payload->>'product_code',''),v_direction,v_unit,v_key,v_existing.id,v_revision,
    nullif(p_payload->>'created_by','')::uuid
  ) returning id into v_normalized_id;

  if v_source_message_id is not null then
    insert into public.metering_value_sources(
      company_id,metering_value_id,normalized_metering_value_id,source_ediel_message_id,
      source_transaction_reference,source_line_reference,source_type
    ) values (
      v_company_id,v_inserted.id,v_normalized_id,v_source_message_id,
      v_source_tx,v_source_line,coalesce(nullif(p_payload->>'source_system',''),'grid_owner')
    ) on conflict do nothing;
  end if;

  return v_inserted;
end;
$$;

