-- Name: gridex_normalize_country_code(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_normalize_country_code(p_value text, p_default text DEFAULT 'SE'::text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_country text := upper(coalesce(nullif(btrim(coalesce(p_value, '')), ''), nullif(btrim(coalesce(p_default, '')), ''), 'SE'));
begin
  if v_country !~ '^[A-Z]{2}$' then
    raise exception using errcode = '23514', message = 'invalid_country_code';
  end if;
  return v_country;
end
$_$;

