--

CREATE FUNCTION public.gridex_normalize_platform_role(p_role text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select case lower(trim(coalesce(p_role,'')))
    when 'super_admin' then 'super_admin'
    when 'superadmin' then 'super_admin'
    when 'platform_superadmin' then 'super_admin'
    when 'platformsuperadmin' then 'super_admin'
    when 'platform_admin' then 'platform_admin'
    when 'platformadmin' then 'platform_admin'
    else lower(trim(coalesce(p_role,'')))
  end
$$;

--
-- Name: gridex_normalize_postal_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_normalize_postal_code(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select public.gridex_normalize_postal_code(p_value, 'SE')
$$;

--
-- Name: gridex_normalize_postal_code(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_normalize_postal_code(p_value text, p_country_code text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_value text := nullif(btrim(coalesce(p_value, '')), '');
  v_country text := public.gridex_normalize_country_code(p_country_code, 'SE');
  v_digits text;
begin
  if v_value is null then return null; end if;

  if v_country = 'SE' then
    if v_value !~ '^[0-9]{3}[ ]?[0-9]{2}$' then
      raise exception using errcode = '23514', message = 'invalid_swedish_postal_code';
    end if;
    v_digits := regexp_replace(v_value, '[^0-9]', '', 'g');
    return substring(v_digits from 1 for 3) || ' ' || substring(v_digits from 4 for 2);
  end if;

  if length(v_value) < 2 or length(v_value) > 16 or v_value !~ '^[[:alnum:]][[:alnum:] -]*$' then
    raise exception using errcode = '23514', message = 'invalid_postal_code';
  end if;
  return upper(v_value);
end
$_$;

