-- Name: gridex_normalize_signature_request_event_truth_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_normalize_signature_request_event_truth_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
begin
  if new.event_type='signature_requested' and new.note is not null then
    new.note := replace(new.note,'Signering skickad / väntar signering','Signering begärd / väntar signering');
    new.note := replace(new.note,'Signering skickad','Signering begärd');
  end if;
  return new;
end
$$;

--
-- Name: gridex_normalize_swedish_organization_number(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_normalize_swedish_organization_number(p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_digits text := regexp_replace(coalesce(p_value, ''), '[^0-9]', '', 'g');
begin
  if v_digits = '' then return null; end if;
  if not public.gridex_luhn_valid(v_digits) then
    raise exception using errcode = '23514', message = 'invalid_swedish_organization_number';
  end if;
  return substring(v_digits from 1 for 6) || '-' || substring(v_digits from 7 for 4);
end
$$;

