$$;

--
-- Name: gridex_onboard_customer_graph(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_onboard_customer_graph(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_channel text:=nullif(p_command->>'channel','');
  v_company_id uuid:=nullif(p_command->>'company_id','')::uuid;
  v_quote_command jsonb:=p_command->'quote';
  v_contract_command jsonb:=p_command->'contract';
  v_quote public.website_contract_quotes%rowtype;
  v_command_components text[];
  v_contract_components text[];
begin
  if v_channel<>'website' then
    return public.gridex_onboard_customer_graph_quote_commit_v2(p_command);
  end if;

  if v_company_id is null
    or jsonb_typeof(coalesce(v_quote_command,'null'::jsonb))<>'object'
    or jsonb_typeof(coalesce(v_contract_command,'null'::jsonb))<>'object'
    or nullif(v_quote_command->>'quote_reference','') is null then
    raise exception using
      errcode='22023',
      message='website_onboarding_quote_commit_payload_required';
  end if;

  select quote.*
    into v_quote
  from public.website_contract_quotes quote
  where quote.company_id=v_company_id
    and quote.quote_reference=v_quote_command->>'quote_reference'
  for share;
  if not found then
    raise exception using
      errcode='P0002',
      message='website_quote_not_found_for_tenant';
  end if;

  if v_quote.quote_hash_version='v3_commercial_selection' then
    if nullif(v_quote.price_option_reference,'') is null
      or nullif(v_quote.invoice_delivery_method,'') is null
      or v_quote.site_count<1
      or jsonb_typeof(
        coalesce(
          v_quote.quote_snapshot->'selected_component_references',
          'null'::jsonb
        )
      )<>'array' then
      raise exception using
        errcode='23514',
        message='website_quote_commercial_selection_incomplete';
    end if;

    v_command_components:=array(
      select value
      from jsonb_array_elements_text(
        coalesce(
          v_quote_command->'selected_component_references',
          '[]'::jsonb
        )
      )
      order by value
    );
    v_contract_components:=array(
      select value
      from jsonb_array_elements_text(
        coalesce(
          v_contract_command->'selected_component_references',
          '[]'::jsonb
        )
      )
      order by value
    );

    if v_quote.price_option_reference is distinct from
        v_quote_command->>'price_option_reference'
      or v_quote.price_option_reference is distinct from
        v_contract_command->>'price_option_reference'
      or v_quote.area_price_reference is distinct from
        nullif(v_quote_command->>'area_price_reference','')
      or v_quote.area_price_reference is distinct from
        nullif(v_contract_command->>'area_price_reference','')
      or v_quote.invoice_delivery_method is distinct from
        v_quote_command->>'invoice_delivery_method'
      or v_quote.invoice_delivery_method is distinct from
        v_contract_command->>'invoice_delivery_method'
      or v_quote.site_count is distinct from
        nullif(v_quote_command->>'site_count','')::integer
      or v_quote.site_count is distinct from
        nullif(v_contract_command->>'site_count','')::integer
      or array(
        select value
        from unnest(v_quote.selected_component_references) value
        order by value
      ) is distinct from v_command_components
      or array(
        select value
        from unnest(v_quote.selected_component_references) value
        order by value
      ) is distinct from v_contract_components then
      raise exception using
        errcode='23514',
        message='website_quote_commercial_assertion_mismatch';
    end if;

    if v_quote.price_option_reference is distinct from
        v_quote.quote_snapshot->>'price_option_reference'
      or v_quote.area_price_reference is distinct from
        nullif(v_quote.quote_snapshot->>'area_price_reference','')
      or v_quote.invoice_delivery_method is distinct from
        v_quote.quote_snapshot->>'invoice_delivery_method'
      or v_quote.site_count is distinct from
        nullif(v_quote.quote_snapshot->>'site_count','')::integer
      or array(
        select value
        from unnest(v_quote.selected_component_references) value
        order by value
      ) is distinct from array(
        select value
        from jsonb_array_elements_text(
          v_quote.quote_snapshot->'selected_component_references'
        )
        order by value
      ) then
      raise exception using
        errcode='23514',
        message='website_quote_commercial_snapshot_mismatch';
    end if;
  end if;

  return public.gridex_onboard_customer_graph_quote_commit_v2(p_command);
end
$$;

--
-- Name: FUNCTION gridex_onboard_customer_graph(p_command jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_onboard_customer_graph(p_command jsonb) IS 'Canonical website commit: validates v3 publication-bound price option, area row, invoice delivery, component selection and site count against the immutable quote snapshot before the atomic graph commit and quote consumption.';

--
-- Name: gridex_onboard_customer_graph_core(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_onboard_customer_graph_core(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_channel text;
  v_idempotency_key text;
  v_correlation_id uuid;
  v_operation public.customer_onboarding_operations%rowtype;
  v_customer_payload jsonb;
  v_site_payload jsonb;
  v_meter_payload jsonb;
  v_contract_payload jsonb;
  v_price_payload jsonb;
  v_legal_payload jsonb;
  v_poa_payload jsonb;
  v_contact_payload jsonb;
  v_address_payload jsonb;
  v_application_payload jsonb;
  v_task_payload jsonb;
  v_info_request_payload jsonb;
  v_existing_customer_id uuid;
  v_existing_site_id uuid;
  v_existing_metering_point_id uuid;
  v_customer_id uuid;
  v_contact_id uuid;
  v_address_id uuid;
  v_site_id uuid;
  v_metering_point_id uuid;
  v_contract_id uuid;
  v_price_snapshot_id uuid;
  v_power_of_attorney_id uuid;
  v_authorization_document_id uuid;
  v_authorization_scope_id uuid;
  v_legal_snapshot_id uuid;
  v_application_id uuid;
  v_task_id uuid;
  v_info_request_id uuid;
  v_domain_event_id uuid;
  v_candidate_ids uuid[] := '{}'::uuid[];
  v_candidate_count integer := 0;
  v_customer_number text;
  v_contract_number text;
  v_matching_policy text;
  v_update_existing boolean;
  v_signed_scopes jsonb := '[]'::jsonb;
  v_scope_values text[] := '{}'::text[];
  v_result jsonb;
  v_row jsonb;
  v_source_record_id text;
  v_source_record_type text;
  v_fail_after text;
  v_cross_tenant_facility_seen boolean := false;
  v_review_resolution_type text;
  v_review_customer_id uuid;
begin
  if p_command is null or jsonb_typeof(p_command) <> 'object' then
    raise exception 'canonical onboarding command must be a JSON object' using errcode = '22023';
  end if;

  v_company_id := nullif(btrim(p_command->>'company_id'), '')::uuid;
  v_channel := lower(nullif(btrim(p_command->>'channel'), ''));
  v_idempotency_key := nullif(btrim(p_command->>'idempotency_key'), '');
  v_correlation_id := coalesce(nullif(btrim(p_command->>'correlation_id'), '')::uuid, gen_random_uuid());
  v_matching_policy := coalesce(nullif(lower(btrim(p_command->>'matching_policy')), ''), 'link_unique');
  v_update_existing := coalesce((p_command->>'update_existing')::boolean, false);
  v_fail_after := nullif(btrim(p_command->>'test_fail_after'), '');

  if v_company_id is null or not exists (select 1 from public.companies where id = v_company_id) then
    raise exception 'company_not_found' using errcode = 'P0002';
  end if;
  if v_channel not in ('admin','website','external_contract','ediel_inbound','api','import','repair') then
    raise exception 'unsupported_onboarding_channel' using errcode = '22023';
  end if;
  if v_idempotency_key is null then
    raise exception 'idempotency_key_required' using errcode = '22023';
  end if;
  if v_matching_policy not in ('link_unique','create_only','create_separate','link_selected') then
    raise exception 'unsupported_matching_policy' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_company_id::text || ':' || v_channel || ':' || v_idempotency_key, 0));

  select * into v_operation
    from public.customer_onboarding_operations
   where company_id = v_company_id and channel = v_channel and idempotency_key = v_idempotency_key
   for update;

  if v_operation.id is not null and v_operation.status = 'completed' then
    return v_operation.result_snapshot;
  end if;
  if v_operation.id is not null and v_operation.status = 'ambiguous_customer_match' then
    select resolution_type, resolved_customer_id
      into v_review_resolution_type, v_review_customer_id
      from public.customer_match_review_cases
     where onboarding_operation_id = v_operation.id
       and status = 'resolved';

    if v_review_resolution_type = 'link_customer' and v_review_customer_id is not null then
      p_command := p_command || jsonb_build_object(
        'existing_customer_id', v_review_customer_id,
        'matching_policy', 'link_selected'
      );
      v_matching_policy := 'link_selected';
    elsif v_review_resolution_type = 'create_separate' then
      p_command := (p_command - 'existing_customer_id') || jsonb_build_object('matching_policy', 'create_separate');
      v_matching_policy := 'create_separate';
    else
      return v_operation.result_snapshot;
    end if;
  end if;

  if v_operation.id is null then
    insert into public.customer_onboarding_operations(
      company_id, channel, idempotency_key, correlation_id, status, command_snapshot
    ) values (
      v_company_id, v_channel, v_idempotency_key, v_correlation_id, 'started', p_command - 'test_fail_after'
    ) returning * into v_operation;
  else
    update public.customer_onboarding_operations
       set correlation_id = v_correlation_id,
           status = 'started',
           command_snapshot = p_command - 'test_fail_after',
           error_code = null,
           updated_at = now()
     where id = v_operation.id
     returning * into v_operation;
  end if;

  v_customer_payload := coalesce(p_command->'customer', '{}'::jsonb) || jsonb_build_object('company_id', v_company_id);
  v_contact_payload := coalesce(p_command->'contact', '{}'::jsonb);
  v_address_payload := coalesce(p_command->'address', '{}'::jsonb);
  v_site_payload := coalesce(p_command->'site', '{}'::jsonb);
  v_meter_payload := coalesce(p_command->'metering_point', '{}'::jsonb);
  v_contract_payload := coalesce(p_command->'contract', '{}'::jsonb);
  v_price_payload := coalesce(p_command->'price_snapshot', '{}'::jsonb);
  v_legal_payload := coalesce(p_command->'legal', '{}'::jsonb);
  v_poa_payload := coalesce(p_command->'power_of_attorney', '{}'::jsonb);
  v_application_payload := coalesce(p_command->'application', '{}'::jsonb);
  v_task_payload := coalesce(p_command->'task', '{}'::jsonb);
  v_info_request_payload := coalesce(p_command->'info_request', '{}'::jsonb);

  -- Cross-tenant matches are a platform-only integrity signal. They never
  -- disclose another tenant's customer or block legitimate onboarding here.
  if nullif(btrim(v_site_payload->>'facility_id'), '') is not null then
    select exists (
      select 1
        from public.customer_sites s
       where s.company_id <> v_company_id
         and s.normalized_facility_id = public.gridex_normalize_facility_id(v_site_payload->>'facility_id')
    ) into v_cross_tenant_facility_seen;
  end if;

  v_existing_customer_id := nullif(btrim(p_command->>'existing_customer_id'), '')::uuid;
  v_existing_site_id := nullif(btrim(p_command->>'existing_site_id'), '')::uuid;
  v_existing_metering_point_id := nullif(btrim(p_command->>'existing_metering_point_id'), '')::uuid;
  if v_existing_customer_id is not null then
    if not exists (
      select 1 from public.customers where id = v_existing_customer_id and company_id = v_company_id
    ) then
      raise exception 'selected_customer_not_found_for_tenant' using errcode = 'P0002';
    end if;
    if exists(
      select 1
      from public.customers c
      where c.id=v_existing_customer_id
        and c.company_id=v_company_id
        and (
          (
            nullif(btrim(v_customer_payload->>'personal_number'),'') is not null
            and c.normalized_personal_number is distinct from
                public.gridex_normalize_personal_number(v_customer_payload->>'personal_number')
          )
          or (
            nullif(btrim(v_customer_payload->>'org_number'),'') is not null
            and c.normalized_org_number is distinct from
                public.gridex_normalize_org_number(v_customer_payload->>'org_number')
          )
          or (
            nullif(btrim(v_customer_payload->>'customer_type'),'') is not null
            and lower(coalesce(c.customer_type,'')) is distinct from
                lower(v_customer_payload->>'customer_type')
          )
        )
    ) then
      raise exception using
        errcode='23514',
        message='selected_customer_legal_identity_mismatch',
        detail=jsonb_build_object(
          'requires_manual_review',true,
          'match_method','selected_customer',
          'match_strength','conflicting',
          'conflicting_identifiers',jsonb_build_array(
            'customer_type','personal_number','org_number'
          )
        )::text;
    end if;
    v_candidate_ids := array[v_existing_customer_id];
  else
    select coalesce(array_agg(distinct candidate_id), '{}'::uuid[])
      into v_candidate_ids
      from (
        select c.id candidate_id
          from public.customers c
         where c.company_id = v_company_id
           and nullif(btrim(v_customer_payload->>'personal_number'), '') is not null
           and c.normalized_personal_number = public.gridex_normalize_personal_number(v_customer_payload->>'personal_number')
        union all
        select c.id
          from public.customers c
         where c.company_id = v_company_id
           and nullif(btrim(v_customer_payload->>'org_number'), '') is not null
           and c.normalized_org_number = public.gridex_normalize_org_number(v_customer_payload->>'org_number')      ) matches
     where candidate_id is not null;
  end if;

  v_candidate_count := coalesce(array_length(v_candidate_ids, 1), 0);
  if v_candidate_count > 1 or (v_candidate_count > 0 and v_matching_policy = 'create_only') then
    v_result := jsonb_build_object(
      'ok', false,
      'code', 'ambiguous_customer_match',
      'correlation_id', v_correlation_id,
      'operation_id', v_operation.id,
      'candidate_customer_ids', to_jsonb(v_candidate_ids)
    );
    insert into public.customer_match_review_cases(
      company_id, onboarding_operation_id, candidate_customer_ids, match_evidence
    ) values (
      v_company_id,
      v_operation.id,
      v_candidate_ids,
      jsonb_build_object(
        'customer_identity', jsonb_build_object(
          'personal_number_present', nullif(btrim(v_customer_payload->>'personal_number'), '') is not null,
          'org_number_present', nullif(btrim(v_customer_payload->>'org_number'), '') is not null,
          'email', nullif(btrim(v_customer_payload->>'email'), '')
        ),
        'facility_id', nullif(btrim(v_site_payload->>'facility_id'), ''),
        'metering_point_id', nullif(btrim(coalesce(v_meter_payload->>'meter_point_id', v_meter_payload->>'metering_point_id')), '')
      )
    ) on conflict (onboarding_operation_id) do update set
      candidate_customer_ids = excluded.candidate_customer_ids,
      match_evidence = excluded.match_evidence,
      status = 'open',
      updated_at = now();

    update public.customer_onboarding_operations
       set status = 'ambiguous_customer_match', result_snapshot = v_result,
           error_code = 'ambiguous_customer_match', completed_at = now(), updated_at = now()
     where id = v_operation.id;
    return v_result;
  end if;

  if v_candidate_count = 1 and v_matching_policy in ('link_unique','link_selected') then
    v_customer_id := v_candidate_ids[1];
    if v_update_existing then
      v_row := public.gridex_update_jsonb_row('public.customers'::regclass, v_customer_id, v_company_id, v_customer_payload);
    else
      select to_jsonb(c) into v_row from public.customers c where c.id = v_customer_id and c.company_id = v_company_id;
    end if;
  else
    v_row := public.gridex_insert_jsonb_row('public.customers'::regclass, v_customer_payload);
    v_customer_id := (v_row->>'id')::uuid;
  end if;

  select customer_number into v_customer_number
    from public.customers where id = v_customer_id and company_id = v_company_id for update;
  if nullif(btrim(v_customer_number), '') is null then
    raise exception 'customer_number_assignment_failed' using errcode = '23502';
  end if;

  if v_fail_after = 'customer' and current_setting('gridex.allow_test_failpoints', true) = 'on' then
    raise exception 'test_fail_after_customer' using errcode = 'P0001';
  end if;

  if jsonb_typeof(v_contact_payload) = 'object' and v_contact_payload <> '{}'::jsonb then
    v_row := public.gridex_insert_jsonb_row(
      'public.customer_contacts'::regclass,
      v_contact_payload || jsonb_build_object('company_id', v_company_id, 'customer_id', v_customer_id)
    );
    v_contact_id := (v_row->>'id')::uuid;
  end if;

  if jsonb_typeof(v_address_payload) = 'object' and v_address_payload <> '{}'::jsonb then
    v_row := public.gridex_insert_jsonb_row(
      'public.customer_addresses'::regclass,
      v_address_payload || jsonb_build_object('company_id', v_company_id, 'customer_id', v_customer_id)
    );
    v_address_id := (v_row->>'id')::uuid;
  end if;

  if jsonb_typeof(v_site_payload) = 'object' and v_site_payload <> '{}'::jsonb then
    if v_existing_site_id is not null then
      select id into v_site_id
        from public.customer_sites
       where id = v_existing_site_id and company_id = v_company_id and customer_id = v_customer_id;
      if v_site_id is null then
        raise exception 'selected_site_not_found_for_customer_tenant' using errcode = 'P0002';
      end if;
    end if;
    if v_site_id is null and nullif(btrim(v_site_payload->>'facility_id'), '') is not null then
      select id into v_site_id
        from public.customer_sites
       where company_id = v_company_id
         and normalized_facility_id = public.gridex_normalize_facility_id(v_site_payload->>'facility_id')
         and customer_id = v_customer_id
       order by created_at desc limit 1;
      if v_site_id is null and exists (
        select 1 from public.customer_sites
         where company_id = v_company_id
           and normalized_facility_id = public.gridex_normalize_facility_id(v_site_payload->>'facility_id')
           and customer_id <> v_customer_id
      ) then
        raise exception 'facility_id_owned_by_another_customer' using errcode = '23505';
      end if;
    end if;
    if v_site_id is null then
      v_row := public.gridex_insert_jsonb_row(
        'public.customer_sites'::regclass,
        v_site_payload || jsonb_build_object('company_id', v_company_id, 'customer_id', v_customer_id)
      );
      v_site_id := (v_row->>'id')::uuid;
    elsif v_update_existing or v_existing_site_id is not null then
      perform public.gridex_update_jsonb_row('public.customer_sites'::regclass, v_site_id, v_company_id, v_site_payload);
    end if;
  end if;

  if v_fail_after = 'site' and current_setting('gridex.allow_test_failpoints', true) = 'on' then
    raise exception 'test_fail_after_site' using errcode = 'P0001';
  end if;

  if jsonb_typeof(v_meter_payload) = 'object' and v_meter_payload <> '{}'::jsonb then
    if v_existing_metering_point_id is not null then
      select id into v_metering_point_id
        from public.metering_points
       where id = v_existing_metering_point_id and company_id = v_company_id and customer_id = v_customer_id;
      if v_metering_point_id is null then
        raise exception 'selected_metering_point_not_found_for_customer_tenant' using errcode = 'P0002';
      end if;
    end if;
    if v_metering_point_id is null and nullif(btrim(coalesce(v_meter_payload->>'meter_point_id', v_meter_payload->>'metering_point_id')), '') is not null then
      select id into v_metering_point_id
        from public.metering_points
       where company_id = v_company_id
         and normalized_metering_point_id = public.gridex_normalize_metering_point_id(coalesce(v_meter_payload->>'meter_point_id', v_meter_payload->>'metering_point_id'))
         and customer_id = v_customer_id
       order by created_at desc limit 1;
      if v_metering_point_id is null and exists (
        select 1 from public.metering_points
         where company_id = v_company_id
           and normalized_metering_point_id = public.gridex_normalize_metering_point_id(coalesce(v_meter_payload->>'meter_point_id', v_meter_payload->>'metering_point_id'))
           and customer_id <> v_customer_id
      ) then
        raise exception 'metering_point_owned_by_another_customer' using errcode = '23505';
      end if;
    end if;
    if v_metering_point_id is null then
      v_row := public.gridex_insert_jsonb_row(
        'public.metering_points'::regclass,
        v_meter_payload || jsonb_build_object(
          'company_id', v_company_id,
          'customer_id', v_customer_id,
          'site_id', v_site_id,
          'customer_site_id', v_site_id
        )
      );
      v_metering_point_id := (v_row->>'id')::uuid;
    elsif v_update_existing or v_existing_metering_point_id is not null then
      perform public.gridex_update_jsonb_row(
        'public.metering_points'::regclass,
        v_metering_point_id,
        v_company_id,
        v_meter_payload || jsonb_build_object('site_id', v_site_id, 'customer_site_id', v_site_id)
      );
    end if;
  end if;

  if jsonb_typeof(v_contract_payload) = 'object' and v_contract_payload <> '{}'::jsonb then
    -- Contract/customer numbers are allocated inside this transaction. Intake
    -- callers may never reserve a customer number before the customer commit.
    v_contract_number := coalesce(
      nullif(btrim(v_contract_payload->>'contract_number'), ''),
      public.gridex_next_contract_number(v_company_id, v_customer_number)
    );
    v_contract_payload := v_contract_payload || jsonb_build_object(
      'contract_number', v_contract_number,
      'customer_number', v_customer_number
    );
    v_row := public.gridex_insert_jsonb_row(
      'public.customer_contracts'::regclass,
      v_contract_payload || jsonb_build_object(
        'company_id', v_company_id,
        'customer_id', v_customer_id,
        'site_id', v_site_id,
        'customer_site_id', v_site_id,
        'metering_point_id', v_metering_point_id
      )
    );
    v_contract_id := (v_row->>'id')::uuid;
  end if;

  if v_contract_id is not null and jsonb_typeof(v_price_payload) = 'object' and v_price_payload <> '{}'::jsonb then
    v_price_payload := v_price_payload || jsonb_build_object(
      'customer_number', v_customer_number,
      'contract_number', v_contract_number,
      'snapshot_json', coalesce(v_price_payload->'snapshot_json', '{}'::jsonb) || jsonb_build_object(
        'customer_number', v_customer_number,
        'contract_number', v_contract_number
      )
    );
    v_row := public.gridex_insert_jsonb_row(
      'public.contract_price_snapshots'::regclass,
      v_price_payload || jsonb_build_object(
        'company_id', v_company_id,
        'contract_id', v_contract_id,
        'customer_id', v_customer_id
      )
    );
    v_price_snapshot_id := (v_row->>'id')::uuid;
    perform public.gridex_update_jsonb_row(
      'public.customer_contracts'::regclass,
      v_contract_id,
      v_company_id,
      jsonb_build_object(
        'contract_price_snapshot_id', v_price_snapshot_id,
        'pricing_snapshot_id', v_price_snapshot_id,
        'price_snapshot', coalesce(v_price_payload->'snapshot_json', v_price_payload)
      )
    );
  end if;

  if jsonb_typeof(v_legal_payload->'signed_scopes') = 'array' then
    v_signed_scopes := v_legal_payload->'signed_scopes';
  elsif jsonb_typeof(v_poa_payload->'signed_scopes') = 'array' then
    v_signed_scopes := v_poa_payload->'signed_scopes';
  else
    v_signed_scopes := '[]'::jsonb;
  end if;
  select coalesce(array_agg(value), '{}'::text[]) into v_scope_values
    from jsonb_array_elements_text(v_signed_scopes) value;

  if jsonb_typeof(v_poa_payload) = 'object' and v_poa_payload <> '{}'::jsonb then
    if coalesce(jsonb_array_length(v_signed_scopes), 0) = 0 then
      raise exception 'signed_power_of_attorney_scope_required' using errcode = '22023';
    end if;
    v_row := public.gridex_insert_jsonb_row(
      'public.powers_of_attorney'::regclass,
      (v_poa_payload - 'signed_scopes') || jsonb_build_object(
        'company_id', v_company_id,
        'customer_id', v_customer_id,
        'site_id', v_site_id,
        'customer_site_id', v_site_id,
        'metering_point_id', v_metering_point_id,
        'contract_id', v_contract_id,
        'customer_contract_id', v_contract_id,
        'signed_scope_snapshot', v_signed_scopes,
        'scope_summary', jsonb_build_object('scopes', v_signed_scopes, 'source', v_channel)
      )
    );
    v_power_of_attorney_id := (v_row->>'id')::uuid;

    v_row := public.gridex_insert_jsonb_row(
      'public.customer_authorization_documents'::regclass,
      coalesce(p_command->'authorization_document', '{}'::jsonb) || jsonb_build_object(
        'company_id', v_company_id,
        'customer_id', v_customer_id,
        'site_id', v_site_id,
        'metering_point_id', v_metering_point_id,
        'customer_contract_id', v_contract_id,
        'power_of_attorney_id', v_power_of_attorney_id,
        'document_type', 'power_of_attorney',
        'status', coalesce(nullif(p_command#>>'{authorization_document,status}', ''), 'active'),
        'title', coalesce(nullif(p_command#>>'{authorization_document,title}', ''), 'Signerad fullmakt'),
        'metadata', coalesce(p_command#>'{authorization_document,metadata}', '{}'::jsonb) || jsonb_build_object('signed_scopes', v_signed_scopes)
      )
    );
    v_authorization_document_id := (v_row->>'id')::uuid;

    v_row := public.gridex_insert_jsonb_row(
      'public.authorization_scopes'::regclass,
      jsonb_build_object(
        'company_id', v_company_id,
        'customer_id', v_customer_id,
        'authorization_document_id', v_authorization_document_id,
        'scope_type', 'signed_customer_authorization',
        'status', 'active',
        'covers_grid_owner_data', ('grid_owner_data' = any(v_scope_values) or 'facility_information_lookup' = any(v_scope_values) or 'supplier_switch' = any(v_scope_values)),
        'covers_current_supplier_contract', ('current_supplier_contract' = any(v_scope_values) or 'supplier_switch' = any(v_scope_values)),
        'covers_metering_data', ('metering_data' = any(v_scope_values) or 'facility_information_lookup' = any(v_scope_values)),
        'valid_from', nullif(v_poa_payload->>'valid_from', ''),
        'valid_to', nullif(v_poa_payload->>'valid_to', ''),
        'evidence_note', 'Coverage derived exactly from immutable signed scope snapshot.',
        'signed_scope_snapshot', v_signed_scopes,
        'metadata', jsonb_build_object('power_of_attorney_id', v_power_of_attorney_id, 'source', v_channel),
        'created_by', nullif(p_command->>'actor_user_id', '')
      )
    );
    v_authorization_scope_id := (v_row->>'id')::uuid;
  end if;

  if jsonb_typeof(v_legal_payload) = 'object' and v_legal_payload <> '{}'::jsonb then
    insert into public.customer_onboarding_legal_snapshots(
      company_id, onboarding_operation_id, customer_id, contract_id, power_of_attorney_id,
      legal_bundle_version_id, terms_version, privacy_version, cooling_off_version,
      signed_scope_snapshot, acceptance_snapshot, accepted_at, content_hash
    ) values (
      v_company_id, v_operation.id, v_customer_id, v_contract_id, v_power_of_attorney_id,
      nullif(v_legal_payload->>'legal_bundle_version_id', '')::uuid,
      nullif(v_legal_payload->>'terms_version', ''),
      nullif(v_legal_payload->>'privacy_version', ''),
      nullif(v_legal_payload->>'cooling_off_version', ''),
      v_signed_scopes,
      coalesce(v_legal_payload->'acceptance_snapshot', v_legal_payload - 'signed_scopes'),
      nullif(v_legal_payload->>'accepted_at', '')::timestamptz,
      encode(digest(convert_to((v_legal_payload || jsonb_build_object('signed_scopes', v_signed_scopes))::text, 'utf8'), 'sha256'), 'hex')
    ) returning id into v_legal_snapshot_id;

    if v_power_of_attorney_id is not null then
      update public.powers_of_attorney
         set legal_snapshot_id = v_legal_snapshot_id,
             updated_at = now()
       where id = v_power_of_attorney_id and company_id = v_company_id;
      update public.authorization_scopes
         set legal_snapshot_id = v_legal_snapshot_id,
             updated_at = now()
       where id = v_authorization_scope_id and company_id = v_company_id;
    end if;
  end if;

  insert into public.customer_onboarding_applications(
    company_id, onboarding_operation_id, customer_id, customer_site_id,
    metering_point_id, contract_id, channel, source_record_type, source_record_id,
    status, payload_snapshot
  ) values (
    v_company_id, v_operation.id, v_customer_id, v_site_id, v_metering_point_id,
    v_contract_id, v_channel,
    nullif(v_application_payload->>'source_record_type', ''),
    nullif(v_application_payload->>'source_record_id', ''),
    coalesce(nullif(v_application_payload->>'status', ''), 'committed'),
    coalesce(v_application_payload->'payload_snapshot', v_application_payload)
  ) returning id into v_application_id;

  v_source_record_type := nullif(v_application_payload->>'source_record_type', '');
  v_source_record_id := nullif(v_application_payload->>'source_record_id', '');

  if jsonb_typeof(v_info_request_payload) = 'object' and v_info_request_payload <> '{}'::jsonb then
    v_row := public.gridex_insert_jsonb_row(
      'public.customer_info_requests'::regclass,
      v_info_request_payload || jsonb_build_object(
        'company_id', v_company_id,
        'customer_id', v_customer_id,
        'site_id', v_site_id,
        'metering_point_id', v_metering_point_id,
        'authorization_document_id', v_authorization_document_id
      )
    );
    v_info_request_id := (v_row->>'id')::uuid;
  end if;

  if jsonb_typeof(v_task_payload) = 'object' and v_task_payload <> '{}'::jsonb then
    v_row := public.gridex_insert_jsonb_row(
      'public.customer_operation_tasks'::regclass,
      v_task_payload || jsonb_build_object(
        'company_id', v_company_id,
        'customer_id', v_customer_id,
        'site_id', v_site_id,
        'metering_point_id', v_metering_point_id,
        'metadata', coalesce(v_task_payload->'metadata', '{}'::jsonb) || jsonb_build_object(
          'onboarding_operation_id', v_operation.id,
          'correlation_id', v_correlation_id,
          'contract_id', v_contract_id,
          'application_id', v_application_id
        )
      )
    );
    v_task_id := (v_row->>'id')::uuid;
  end if;

  insert into public.domain_events(
    company_id, event_type, aggregate_type, aggregate_id, subject_customer_id,
    actor_user_id, source, idempotency_key, payload
  ) values (
    v_company_id,
    'customer.onboarding_committed',
    'customer_onboarding_operation',
    v_operation.id::text,
    v_customer_id,
    nullif(p_command->>'actor_user_id', '')::uuid,
    v_channel,
    'customer-onboarding:' || v_operation.id::text,
    jsonb_build_object(
      'correlation_id', v_correlation_id,
      'customer_id', v_customer_id,
      'customer_number', v_customer_number,
      'site_id', v_site_id,
      'metering_point_id', v_metering_point_id,
      'contract_id', v_contract_id,
      'power_of_attorney_id', v_power_of_attorney_id,
      'source_record_type', v_source_record_type,
      'source_record_id', v_source_record_id,
      'cross_tenant_facility_seen', v_cross_tenant_facility_seen,
      'cross_tenant_signal_visibility', 'platform_only'
    )
  ) returning id into v_domain_event_id;

  insert into public.event_outbox(
    company_id, domain_event_id, destination_type, destination_key, status, payload
  ) values (
    v_company_id,
    v_domain_event_id,
    'internal',
    'customer-onboarding-orchestrator',
    'queued',
    jsonb_build_object(
      'operation_id', v_operation.id,
      'correlation_id', v_correlation_id,
      'customer_id', v_customer_id,
      'application_id', v_application_id,
      'info_request_id', v_info_request_id,
      'task_id', v_task_id
    )
  ) on conflict (domain_event_id, destination_type, destination_key) where destination_key is not null do nothing;

  insert into public.audit_logs(
    company_id, actor_user_id, entity_type, entity_id, action, new_values, metadata
  ) values (
    v_company_id,
    nullif(p_command->>'actor_user_id', '')::uuid,
    'customer_onboarding_operation',
    v_operation.id::text,
    'customer_onboarding.committed',
    jsonb_build_object(
      'customer_id', v_customer_id,
      'customer_number', v_customer_number,
      'site_id', v_site_id,
      'metering_point_id', v_metering_point_id,
      'contract_id', v_contract_id
    ),
    jsonb_build_object(
      'channel', v_channel,
      'correlation_id', v_correlation_id,
      'cross_tenant_facility_seen', v_cross_tenant_facility_seen,
      'cross_tenant_signal_visibility', 'platform_only'
    )
  );

  if v_fail_after = 'complete' and current_setting('gridex.allow_test_failpoints', true) = 'on' then
    raise exception 'test_fail_before_commit' using errcode = 'P0001';
  end if;

  v_result := jsonb_build_object(
    'ok', true,
    'code', 'customer_onboarding_committed',
    'operation_id', v_operation.id,
    'correlation_id', v_correlation_id,
    'customer_id', v_customer_id,
    'customer_number', v_customer_number,
    'created_new_customer', v_candidate_count = 0 or v_matching_policy = 'create_separate',
    'contact_id', v_contact_id,
    'address_id', v_address_id,
    'site_id', v_site_id,
    'metering_point_id', v_metering_point_id,
    'contract_id', v_contract_id,
    'contract_number', v_contract_number,
    'price_snapshot_id', v_price_snapshot_id,
    'power_of_attorney_id', v_power_of_attorney_id,
    'authorization_document_id', v_authorization_document_id,
    'authorization_scope_id', v_authorization_scope_id,
    'legal_snapshot_id', v_legal_snapshot_id,
    'application_id', v_application_id,
    'task_id', v_task_id,
    'info_request_id', v_info_request_id,
    'outbox_event_id', v_domain_event_id
  );

  update public.customer_onboarding_operations
     set status = 'completed', result_snapshot = v_result, completed_at = now(), updated_at = now()
   where id = v_operation.id;

  return v_result;
exception
  when others then
    -- PL/pgSQL exception handling creates an internal subtransaction. Every row
    -- written above is rolled back before this block runs. Re-raise so callers
    -- cannot receive a false success. Failed attempts are observable through
    -- application logs using the correlation id included in the error detail.
    raise exception '%', SQLERRM
      using errcode = SQLSTATE,
            detail = jsonb_build_object(
              'correlation_id', v_correlation_id,
              'channel', v_channel,
              'idempotency_key', v_idempotency_key,
              'sqlstate', SQLSTATE
            )::text;
end;
$$;

--
-- Name: FUNCTION gridex_onboard_customer_graph_core(p_command jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_onboard_customer_graph_core(p_command jsonb) IS 'Canonical fail-closed, tenant-scoped and idempotent customer onboarding transaction for all intake channels.';

--
-- Name: gridex_onboard_customer_graph_quote_commit_v2(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_onboard_customer_graph_quote_commit_v2(p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_channel text := nullif(p_command->>'channel', '');
  v_company_id uuid := nullif(p_command->>'company_id', '')::uuid;
  v_quote_command jsonb := p_command->'quote';
  v_contract_command jsonb := p_command->'contract';
  v_quote public.website_contract_quotes%rowtype;
  v_application_id uuid;
  v_result jsonb;
  v_domain_event_id uuid;
  v_public_offer_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception using
      errcode = '42501',
      message = 'canonical_onboarding_service_role_required';
  end if;

  if v_channel <> 'website' then
    return public.gridex_onboard_customer_graph_core(p_command);
  end if;

  if v_company_id is null
     or jsonb_typeof(coalesce(v_quote_command, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(v_contract_command, 'null'::jsonb)) <> 'object'
     or nullif(v_quote_command->>'quote_reference', '') is null
     or nullif(v_quote_command->>'quote_hash', '') is null
     or nullif(v_quote_command->>'application_id', '') is null then
    raise exception using
      errcode = '22023',
      message = 'website_onboarding_quote_commit_payload_required';
  end if;

  v_application_id := (v_quote_command->>'application_id')::uuid;
  v_public_offer_id :=
    nullif(v_contract_command->>'public_contract_offer_id', '')::uuid;

  select *
  into v_quote
  from public.website_contract_quotes quote
  where quote.company_id = v_company_id
    and quote.quote_reference = v_quote_command->>'quote_reference'
  for update;
  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'website_quote_not_found_for_tenant';
  end if;

  if v_quote.status = 'consumed'
     and v_quote.consumed_application_id = v_application_id then
    v_result := public.gridex_onboard_customer_graph_core(p_command);
    return v_result || jsonb_build_object(
      'quote_id', v_quote.id,
      'quote_status', 'consumed',
      'quote_existing', true
    );
  end if;
  if v_quote.status <> 'active' then
    raise exception using
      errcode = '23514',
      message = 'website_quote_not_active';
  end if;
  if v_quote.quote_hash_version not in (
       'v2_full_quote',
       'v3_commercial_selection'
     )
     or v_quote.quote_hash is distinct from v_quote_command->>'quote_hash' then
    raise exception using
      errcode = '23514',
      message = 'website_quote_integrity_mismatch';
  end if;

  if v_quote.offer_reference is distinct from
       v_quote_command->>'offer_reference'
     or v_quote.offer_reference is distinct from
       v_contract_command->>'offer_reference'
     or v_quote.contract_product_id is distinct from
       nullif(v_contract_command->>'contract_product_id', '')::uuid
     or v_quote.contract_product_version_id is distinct from
       nullif(v_contract_command->>'contract_product_version_id', '')::uuid
     or v_quote.contract_publication_version_id is distinct from
       nullif(v_contract_command->>'contract_publication_version_id', '')::uuid
     or v_quote.price_plan_id is distinct from
       nullif(v_contract_command->>'price_plan_id', '')::uuid
     or v_quote.price_plan_version_id is distinct from
       nullif(v_contract_command->>'price_plan_version_id', '')::uuid
     or v_quote.price_book_id is distinct from
       nullif(v_contract_command->>'price_book_id', '')::uuid
     or v_quote.legal_bundle_version_id is distinct from
       nullif(v_contract_command->>'legal_bundle_version_id', '')::uuid
     or v_quote.energy_direction is distinct from
       v_contract_command->>'energy_direction' then
    raise exception using
      errcode = '23514',
      message = 'website_quote_contract_chain_mismatch';
  end if;

  if not exists (
    select 1
    from public.canonical_public_contract_offers_v offer
    where offer.company_id = v_company_id
      and offer.id = v_public_offer_id
      and offer.canonical_offer_reference = v_quote.offer_reference
      and offer.contract_product_id = v_quote.contract_product_id
      and offer.contract_product_version_id =
        v_quote.contract_product_version_id
      and offer.contract_publication_version_id =
        v_quote.contract_publication_version_id
      and offer.legal_bundle_version_id = v_quote.legal_bundle_version_id
      and offer.publication_status = 'published'
      and offer.lifecycle_status = 'published'
      and offer.is_public = true
      and offer.website_enabled = true
      and offer.website_cta_enabled = true
      and (offer.valid_from is null or offer.valid_from <= current_date)
      and (offer.valid_to is null or offer.valid_to >= current_date)
  ) then
    raise exception using
      errcode = '23514',
      message = 'website_quote_offer_no_longer_available';
  end if;

  if not exists (
    select 1
    from public.website_customer_applications application
    where application.id = v_application_id
      and application.company_id = v_company_id
      and application.status = 'processing'
      and p_command->'application'->>'source_record_id' =
        v_application_id::text
  ) then
    raise exception using
      errcode = '23514',
      message = 'website_application_reservation_invalid';
  end if;

  v_result := public.gridex_onboard_customer_graph_core(p_command);
  if not coalesce((v_result->>'ok')::boolean, false) then
    raise exception using
      errcode = '23514',
      message = 'website_onboarding_graph_not_committed';
  end if;
  if nullif(v_result->>'contract_id', '') is null
     or nullif(v_result->>'application_id', '') is null then
    raise exception using
      errcode = '23502',
      message = 'website_onboarding_graph_incomplete';
  end if;

  update public.website_contract_quotes
  set status = 'consumed',
      consumed_at = now(),
      consumed_application_id = v_application_id,
      updated_at = now()
  where id = v_quote.id
    and company_id = v_company_id
    and status = 'active';
  if not found then
    raise exception using
      errcode = '40001',
      message = 'website_quote_consume_race';
  end if;

  update public.website_customer_applications
  set customer_id = (v_result->>'customer_id')::uuid,
      customer_site_id = nullif(v_result->>'site_id', '')::uuid,
      metering_point_id =
        nullif(v_result->>'metering_point_id', '')::uuid,
      contract_id = (v_result->>'contract_id')::uuid,
      contract_number = nullif(v_result->>'contract_number', ''),
      quote_reference = v_quote.quote_reference,
      public_contract_offer_id = v_public_offer_id,
      contract_product_id = v_quote.contract_product_id,
      contract_product_version_id = v_quote.contract_product_version_id,
      contract_publication_version_id =
        v_quote.contract_publication_version_id,
      price_plan_id = v_quote.price_plan_id,
      price_plan_version_id = v_quote.price_plan_version_id,
      price_book_id = v_quote.price_book_id,
      legal_bundle_version_id = v_quote.legal_bundle_version_id,
      energy_direction = v_quote.energy_direction,
      updated_at = now()
  where id = v_application_id
    and company_id = v_company_id;

  insert into public.domain_events(
    company_id,
    event_type,
    aggregate_type,
    aggregate_id,
    actor_user_id,
    source,
    idempotency_key,
    payload
  ) values (
    v_company_id,
    'application.quote_committed',
    'website_customer_application',
    v_application_id,
    nullif(p_command->>'actor_user_id', '')::uuid,
    'gridex_onboard_customer_graph',
    'application-quote-commit:' || v_application_id::text,
    jsonb_build_object(
      'application_id', v_application_id,
      'quote_id', v_quote.id,
      'quote_reference', v_quote.quote_reference,
      'customer_id', v_result->>'customer_id',
      'contract_id', v_result->>'contract_id'
    )
  )
  on conflict do nothing
  returning id into v_domain_event_id;

  if v_domain_event_id is not null then
    insert into public.event_outbox(
      company_id,
      domain_event_id,
      destination_type,
      destination_key,
      payload
    ) values (
      v_company_id,
      v_domain_event_id,
      'internal',
      'application.quote_committed',
      jsonb_build_object(
        'domain_event_id', v_domain_event_id,
        'application_id', v_application_id,
        'quote_id', v_quote.id
      )
    ) on conflict do nothing;
  end if;

  insert into public.audit_logs(
    company_id,
    actor_user_id,
    entity_type,
    entity_id,
    action,
    old_values,
    new_values,
    metadata
  ) values (
    v_company_id,
    nullif(p_command->>'actor_user_id', '')::uuid,
    'website_customer_application',
    v_application_id,
    'application.quote_committed',
    jsonb_build_object('quote_status', 'active'),
    jsonb_build_object(
      'quote_status', 'consumed',
      'contract_id', v_result->>'contract_id'
    ),
    jsonb_build_object(
      'quote_id', v_quote.id,
      'idempotency_key', p_command->>'idempotency_key'
    )
  );

  return v_result || jsonb_build_object(
    'quote_id', v_quote.id,
    'quote_status', 'consumed',
    'quote_existing', false
  );
end
$$;

--
-- Name: FUNCTION gridex_onboard_customer_graph_quote_commit_v2(p_command jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_onboard_customer_graph_quote_commit_v2(p_command jsonb) IS 'Canonical website application commit: locks and validates v2/v3 immutable quote identity, commits the customer graph, consumes the quote, and writes audit/events/outbox in one transaction.';

--
-- Name: gridex_ops_health_checks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ops_health_checks() RETURNS TABLE(check_key text, status text, issue_count bigint, details jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  expected text[] := array[
    'customer_operation_jobs',
    'customer_operation_request_snapshots',
    'customer_application_workflows',
    'customer_sites',
    'customer_site_resolution',
    'customer_site_address_conflicts',
    'platform_grid_areas',
    'platform_grid_owners',
    'grid_owners',
    'gridex_verified_grid_owners_v',
    'tenant_email_outbox',
    'webhook_deliveries',
    'ediel_outbox'
  ];
  item text;
  missing_count bigint := 0;
  count_value bigint;
begin
  foreach item in array expected loop
    if to_regclass('public.' || item) is null then
      missing_count := missing_count + 1;
      return query select
        'schema:' || item,
        'blocking'::text,
        1::bigint,
        jsonb_build_object('missing_relation', item);
    end if;
  end loop;

  if missing_count > 0 then
    return;
  end if;

  select count(*) into count_value
  from (
    select company_id, job_type, idempotency_key
    from public.customer_operation_jobs job
    where job.status in ('queued', 'running', 'waiting_response')
      and idempotency_key is not null
    group by company_id, job_type, idempotency_key
    having count(*) > 1
  ) active_duplicates;
  return query select 'queue:customer_operation_active_idempotency_duplicate',
    case when count_value = 0 then 'ok' else 'blocking' end,
    count_value,
    '{}'::jsonb;

  select count(*) into count_value
  from public.customer_operation_jobs job
  where job.status = 'running'
    and locked_at < now() - interval '15 minutes';
  return query select 'queue:customer_operation_stale',
    case when count_value = 0 then 'ok' else 'warning' end,
    count_value,
    '{}'::jsonb;

  select count(*) into count_value
  from public.tenant_email_outbox email_outbox
  where email_outbox.status = 'delivery_uncertain';
  return query select 'queue:email_delivery_uncertain',
    case when count_value = 0 then 'ok' else 'warning' end,
    count_value,
    '{}'::jsonb;

  select count(*) into count_value
  from public.webhook_deliveries webhook
  where webhook.status = 'processing'
    and locked_at < now() - interval '15 minutes';
  return query select 'queue:webhook_stale_processing',
    case when count_value = 0 then 'ok' else 'warning' end,
    count_value,
    '{}'::jsonb;

  select count(*) into count_value
  from public.ediel_outbox ediel
  where ediel.status = 'delivery_uncertain';
  return query select 'queue:ediel_delivery_uncertain',
    case when count_value = 0 then 'ok' else 'blocking' end,
    count_value,
    '{}'::jsonb;

  select count(*) into count_value
  from public.platform_grid_areas a
  left join public.platform_grid_owners pgo on pgo.id = a.grid_owner_id
  where a.is_active
    and (a.grid_owner_id is null or pgo.ops_grid_owner_id is null);
  return query select 'masterdata:grid_area_ops_owner_mapping_missing',
    case when count_value = 0 then 'ok' else 'blocking' end,
    count_value,
    '{}'::jsonb;

  if exists (
    select 1 from information_schema.columns
    where table_schema = 'public'
      and table_name = 'gridex_verified_grid_owners_v'
      and column_name = 'can_use_for_prodat'
  ) then
    execute 'select count(*) from public.gridex_verified_grid_owners_v where coalesce(can_use_for_prodat, false) = false'
      into count_value;
    return query select 'masterdata:grid_owner_prodat_readiness_missing',
      case when count_value = 0 then 'ok' else 'warning' end,
      count_value,
      jsonb_build_object('source', 'gridex_verified_grid_owners_v');
  else
    return query select 'schema:gridex_verified_grid_owners_v.can_use_for_prodat',
      'blocking'::text,
      1::bigint,
      jsonb_build_object('missing_column', 'can_use_for_prodat');
  end if;

  select count(*) into count_value
  from (
    select company_id, customer_site_id, dedupe_key
    from public.customer_site_address_conflicts conflict_row
    where conflict_row.status = 'open' and dedupe_key is not null
    group by company_id, customer_site_id, dedupe_key
    having count(*) > 1
  ) duplicates;
  return query select 'address_conflict:duplicate_open',
    case when count_value = 0 then 'ok' else 'warning' end,
    count_value,
    '{}'::jsonb;

  select count(*) into count_value
  from public.customer_sites site
  where site.status = 'active'
    and resolution_status in ('needs_review', 'failed')
    and coalesce(trim(street), '') <> '';
  return query select 'customer_site:unresolved_grid_context',
    case when count_value = 0 then 'ok' else 'warning' end,
    count_value,
    '{}'::jsonb;
end;
$$;

--
-- Name: gridex_ops_health_checks_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ops_health_checks_v2() RETURNS TABLE(check_key text, status text, issue_count bigint, details jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  count_value bigint;
begin
  return query select * from public.gridex_ops_health_checks();

  if to_regclass('public.ediel_route_runtime_v') is null then
    return query select 'schema:ediel_route_runtime_v', 'blocking'::text, 1::bigint, jsonb_build_object('missing_relation','ediel_route_runtime_v');
    return;
  end if;

  execute $q$
    select count(*) from public.ediel_route_runtime_v
    where coalesce(is_enabled,false) = true
      and coalesce(communication_route_active,false) = true
      and (coalesce(receiver_ediel_id,'') = '' or coalesce(target_email,'') = '')
  $q$ into count_value;
  return query select 'route:receiver_or_mailbox_missing', case when count_value=0 then 'ok' else 'blocking' end, count_value, '{}'::jsonb;

  execute $q$
    select count(*) from public.ediel_route_runtime_v
    where coalesce(is_enabled,false) = true
      and coalesce(communication_route_active,false) = true
      and coalesce(subaddress_required,false) = true
      and coalesce(nullif(receiver_message_subaddress,''),nullif(receiver_subaddress,''),nullif(receiver_sub_address,'')) is null
  $q$ into count_value;
  return query select 'route:required_receiver_subaddress_missing', case when count_value=0 then 'ok' else 'blocking' end, count_value, '{}'::jsonb;

  if to_regclass('public.ediel_certificates') is not null then
    execute $q$
      select count(*) from public.ediel_route_runtime_v r
      left join public.ediel_certificates c on c.id = coalesce(r.receiver_certificate_id,r.certificate_id)
      where coalesce(r.is_enabled,false) = true
        and coalesce(r.communication_route_active,false) = true
        and (coalesce(r.certificate_required,false) = true or coalesce(r.encryption_mode,'') = 'smime')
        and (
          coalesce(r.receiver_certificate_id,r.certificate_id) is null
          or c.id is null
          or coalesce(c.status,'') not in ('valid','active','renewal_available')
          or (c.valid_from is not null and c.valid_from > now())
          or (c.valid_to is not null and c.valid_to <= now())
          or (c.environment is not null and c.environment <> r.environment)
          or (c.owner_ediel_id is not null and c.owner_ediel_id <> r.receiver_ediel_id)
        )
    $q$ into count_value;
    return query select 'route:receiver_certificate_invalid_or_missing', case when count_value=0 then 'ok' else 'blocking' end, count_value, '{}'::jsonb;
  end if;

  if to_regclass('public.customer_application_provisioning_steps') is not null then
    select count(*) into count_value
      from public.customer_application_workflows w
      left join public.customer_application_provisioning_steps s
        on s.company_id = w.company_id
       and s.customer_application_id = w.customer_application_id
       and s.operation_id = w.operation_id
       and s.step = 'workflow_committed'
       and s.status = 'completed'
     where w.state in ('pending_customer_data','ready_for_switch') and s.id is null;
    return query select 'workflow:missing_atomic_commit_marker', case when count_value=0 then 'ok' else 'blocking' end, count_value, '{}'::jsonb;
  end if;
end;
$_$;

--
-- Name: gridex_ops_health_checks_v3(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ops_health_checks_v3() RETURNS TABLE(check_key text, status text, issue_count bigint, details jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  return query select h.check_key,h.status,h.issue_count,h.details
  from public.gridex_ops_health_checks_v2() h;

  return query select h.check_key,h.status,h.issue_count,h.details
  from public.gridex_market_price_readiness_v h;
end;
$$;

--
-- Name: gridex_ops_health_checks_v4(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ops_health_checks_v4() RETURNS TABLE(check_key text, status text, issue_count bigint, details jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  count_value bigint;
begin
  -- Preserve all existing checks except the four configuration checks whose old
  -- implementation treated every enabled candidate profile/reference row as live.
  return query
  select h.check_key, h.status, h.issue_count, h.details
  from public.gridex_ops_health_checks_v3() h
  where h.check_key not in (
    'masterdata:grid_area_ops_owner_mapping_missing',
    'route:receiver_or_mailbox_missing',
    'route:required_receiver_subaddress_missing',
    'route:receiver_certificate_invalid_or_missing'
  );

  -- SVK reference coverage is important but an unmapped imported area is not a
  -- live customer-flow outage. Runtime intake still fails closed if that exact
  -- area is selected and no OPS owner mapping can be resolved.
  select count(*) into count_value
  from public.platform_grid_areas a
  join public.platform_grid_owners o on o.id = a.grid_owner_id
  where coalesce(a.is_active, false) = true
    and o.ops_grid_owner_id is null;
  return query select
    'masterdata:grid_area_ops_owner_mapping_missing',
    case when count_value = 0 then 'ok' else 'warning' end,
    count_value,
    jsonb_build_object(
      'classification', 'reference_masterdata_not_live_customer_state',
      'runtime_guard', 'grid_owner_mapping_missing',
      'action', 'reconcile_svk_owner_alias_to_verified_ops_owner'
    );

  -- A route can block production only after the readiness workflow has approved
  -- it for live use. Shadow/disabled profiles remain visible in candidate checks.
  select count(*) into count_value
  from public.ediel_route_profiles rp
  join public.communication_routes cr on cr.id = rp.communication_route_id
  where rp.environment = 'production'
    and coalesce(rp.is_enabled, false) = true
    and coalesce(cr.is_active, false) = true
    and coalesce(rp.is_production_ready, false) = true
    and coalesce(rp.production_mode, 'disabled') = 'live'
    and (nullif(btrim(coalesce(rp.receiver_ediel_id, '')), '') is null
      or nullif(btrim(coalesce(rp.smtp_to, cr.target_email, '')), '') is null);
  return query select
    'route:receiver_or_mailbox_missing',
    case when count_value = 0 then 'ok' else 'blocking' end,
    count_value,
    jsonb_build_object('scope', 'live_production_ready_only');

  select count(*) into count_value
  from public.ediel_route_profiles rp
  join public.communication_routes cr on cr.id = rp.communication_route_id
  where rp.environment = 'production'
    and coalesce(rp.is_enabled, false) = true
    and coalesce(cr.is_active, false) = true
    and not (coalesce(rp.is_production_ready, false) = true and coalesce(rp.production_mode, 'disabled') = 'live')
    and (nullif(btrim(coalesce(rp.receiver_ediel_id, '')), '') is null
      or nullif(btrim(coalesce(rp.smtp_to, cr.target_email, '')), '') is null);
  return query select
    'route:candidate_receiver_or_mailbox_missing',
    case when count_value = 0 then 'ok' else 'warning' end,
    count_value,
    jsonb_build_object('classification', 'non_live_route_candidate');

  select count(*) into count_value
  from public.ediel_route_profiles rp
  join public.communication_routes cr on cr.id = rp.communication_route_id
  where rp.environment = 'production'
    and coalesce(rp.is_enabled, false) = true
    and coalesce(cr.is_active, false) = true
    and coalesce(rp.is_production_ready, false) = true
    and coalesce(rp.production_mode, 'disabled') = 'live'
    and coalesce(rp.subaddress_required, false) = true
    and coalesce(nullif(rp.receiver_message_subaddress, ''), nullif(rp.receiver_subaddress, ''), nullif(rp.receiver_sub_address, '')) is null;
  return query select
    'route:required_receiver_subaddress_missing',
    case when count_value = 0 then 'ok' else 'blocking' end,
    count_value,
    jsonb_build_object('scope', 'live_production_ready_only');

  select count(*) into count_value
  from public.ediel_route_profiles rp
  join public.communication_routes cr on cr.id = rp.communication_route_id
  left join public.ediel_certificates c on c.id = coalesce(rp.receiver_certificate_id, rp.certificate_id)
  where rp.environment = 'production'
    and coalesce(rp.is_enabled, false) = true
    and coalesce(cr.is_active, false) = true
    and coalesce(rp.is_production_ready, false) = true
    and coalesce(rp.production_mode, 'disabled') = 'live'
    and (coalesce(rp.certificate_required, false) = true or coalesce(rp.encryption_mode, '') = 'smime')
    and (
      coalesce(rp.receiver_certificate_id, rp.certificate_id) is null
      or c.id is null
      or coalesce(c.status, '') not in ('valid', 'active', 'renewal_available')
      or (c.valid_from is not null and c.valid_from > now())
      or (c.valid_to is not null and c.valid_to <= now())
      or (c.environment is not null and c.environment <> rp.environment)
      or (c.owner_ediel_id is not null and c.owner_ediel_id <> rp.receiver_ediel_id)
      or nullif(btrim(coalesce(c.public_certificate_pem, '')), '') is null
    );
  return query select
    'route:receiver_certificate_invalid_or_missing',
    case when count_value = 0 then 'ok' else 'blocking' end,
    count_value,
    jsonb_build_object('scope', 'live_production_ready_only');

  select count(*) into count_value
  from public.ediel_route_profiles rp
  join public.communication_routes cr on cr.id = rp.communication_route_id
  left join public.ediel_certificates c on c.id = coalesce(rp.receiver_certificate_id, rp.certificate_id)
  where rp.environment = 'production'
    and coalesce(rp.is_enabled, false) = true
    and coalesce(cr.is_active, false) = true
    and not (coalesce(rp.is_production_ready, false) = true and coalesce(rp.production_mode, 'disabled') = 'live')
    and (coalesce(rp.certificate_required, false) = true or coalesce(rp.encryption_mode, '') = 'smime')
    and (
      coalesce(rp.receiver_certificate_id, rp.certificate_id) is null
      or c.id is null
      or coalesce(c.status, '') not in ('valid', 'active', 'renewal_available')
      or (c.valid_from is not null and c.valid_from > now())
      or (c.valid_to is not null and c.valid_to <= now())
      or (c.environment is not null and c.environment <> rp.environment)
      or (c.owner_ediel_id is not null and c.owner_ediel_id <> rp.receiver_ediel_id)
      or nullif(btrim(coalesce(c.public_certificate_pem, '')), '') is null
    );
  return query select
    'route:candidate_receiver_certificate_invalid_or_missing',
    case when count_value = 0 then 'ok' else 'warning' end,
    count_value,
    jsonb_build_object('classification', 'non_live_route_candidate');
end;
$$;

--
-- Name: gridex_ops_health_checks_v5(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_ops_health_checks_v5() RETURNS TABLE(check_key text, status text, issue_count bigint, details jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with
base as (
  select h.check_key, h.status, h.issue_count, h.details
  from public.gridex_ops_health_checks_v4() h
  where h.check_key not in (
    'masterdata:grid_owner_prodat_readiness_missing',
    'masterdata:grid_area_ops_owner_mapping_missing',
    'route:candidate_receiver_or_mailbox_missing',
    'route:candidate_receiver_certificate_invalid_or_missing'
  )
),
prodat_action_required as (
  select v.*
  from public.gridex_verified_grid_owners_v v
  where coalesce(v.can_use_for_prodat, false) = false
    and coalesce(v.is_electricity_grid_owner_scope, false) = true
    and coalesce(v.excluded_from_electricity_scope, false) = false
),
prodat_out_of_scope as (
  select v.*
  from public.gridex_verified_grid_owners_v v
  where coalesce(v.can_use_for_prodat, false) = false
    and (
      coalesce(v.excluded_from_electricity_scope, false) = true
      or coalesce(v.is_electricity_grid_owner_scope, false) = false
    )
),
unmapped_areas as (
  select
    a.id,
    a.grid_area_code,
    a.grid_area_name,
    a.grid_owner_id,
    o.name as platform_grid_owner_name
  from public.platform_grid_areas a
  join public.platform_grid_owners o
    on o.id = a.grid_owner_id
  where coalesce(a.is_active, true)
    and (a.valid_to is null or a.valid_to >= current_date)
    and o.ops_grid_owner_id is null
),
candidate_profiles as (
  select
    rp.*,
    cr.target_email as communication_target_email,
    cr.is_active as communication_route_is_active,
    c.id as resolved_certificate_id,
    c.status as resolved_certificate_status,
    c.valid_from as resolved_certificate_valid_from,
    c.valid_to as resolved_certificate_valid_to,
    c.environment as resolved_certificate_environment,
    c.owner_ediel_id as resolved_certificate_owner_ediel_id,
    c.public_certificate_pem as resolved_certificate_pem
  from public.ediel_route_profiles rp
  join public.communication_routes cr
    on cr.id = rp.communication_route_id
  left join public.ediel_certificates c
    on c.id = coalesce(rp.receiver_certificate_id, rp.certificate_id)
  where rp.environment = 'production'
    and coalesce(rp.is_enabled, false) = true
    and coalesce(cr.is_active, false) = true
    and not (
      coalesce(rp.is_production_ready, false) = true
      and coalesce(rp.production_mode, 'disabled') = 'live'
    )
),
dynamic_candidate_templates as (
  select cp.*
  from candidate_profiles cp
  where cp.receiver_source in ('dynamic_grid_owner', 'selected_metering_point_grid_owner')
    and nullif(btrim(coalesce(cp.dynamic_receiver_strategy, '')), '') is not null
    and nullif(btrim(coalesce(cp.smtp_to, cp.communication_target_email, '')), '') is not null
),
invalid_dynamic_candidate_templates as (
  select cp.*
  from candidate_profiles cp
  where cp.receiver_source in ('dynamic_grid_owner', 'selected_metering_point_grid_owner')
    and (
      nullif(btrim(coalesce(cp.dynamic_receiver_strategy, '')), '') is null
      or nullif(btrim(coalesce(cp.smtp_to, cp.communication_target_email, '')), '') is null
    )
),
invalid_static_candidate_receivers as (
  select cp.*
  from candidate_profiles cp
  where coalesce(cp.production_mode, 'disabled') <> 'disabled'
    and coalesce(cp.receiver_source, 'static') not in ('dynamic_grid_owner', 'selected_metering_point_grid_owner')
    and (
      nullif(btrim(coalesce(cp.receiver_ediel_id, '')), '') is null
      or nullif(btrim(coalesce(cp.smtp_to, cp.communication_target_email, '')), '') is null
    )
),
invalid_candidate_certificates as (
  select cp.*
  from candidate_profiles cp
  where (
      coalesce(cp.certificate_required, false) = true
      or coalesce(cp.encryption_mode, '') = 'smime'
    )
    and (
      coalesce(cp.receiver_certificate_id, cp.certificate_id) is null
      or cp.resolved_certificate_id is null
      or coalesce(cp.resolved_certificate_status, '') not in ('valid', 'active', 'renewal_available')
      or (cp.resolved_certificate_valid_from is not null and cp.resolved_certificate_valid_from > now())
      or (cp.resolved_certificate_valid_to is not null and cp.resolved_certificate_valid_to <= now())
      or (cp.resolved_certificate_environment is not null and cp.resolved_certificate_environment <> cp.environment)
      or (
        cp.resolved_certificate_owner_ediel_id is not null
        and cp.resolved_certificate_owner_ediel_id <> cp.receiver_ediel_id
      )
      or nullif(btrim(coalesce(cp.resolved_certificate_pem, '')), '') is null
    )
),
non_live_certificate_inventory as (
  select ic.*
  from invalid_candidate_certificates ic
  where coalesce(ic.production_mode, 'disabled') = 'disabled'
     or ic.receiver_source in ('dynamic_grid_owner', 'selected_metering_point_grid_owner')
),
actionable_static_candidate_certificates as (
  select ic.*
  from invalid_candidate_certificates ic
  where coalesce(ic.production_mode, 'disabled') <> 'disabled'
    and coalesce(ic.receiver_source, 'static') not in ('dynamic_grid_owner', 'selected_metering_point_grid_owner')
)
select b.check_key, b.status, b.issue_count, b.details
from base b

union all

select
  'masterdata:grid_owner_prodat_action_required'::text,
  case when count(*) > 0 then 'warning' else 'ok' end::text,
  count(*)::bigint,
  jsonb_build_object(
    'health_class', 'actionable_warning',
    'scope', 'electricity_grid_owner_supplier_switch',
    'manual_review_count', count(*) filter (where coalesce(manual_review_required, false)),
    'certificate_blocker_count', count(*) filter (where 'missing_or_invalid_certificate'=any(coalesce(role_aware_blocking_reasons,'{}'::text[]))),
    'sample', coalesce((
      select jsonb_agg(to_jsonb(s))
      from (
        select
          name,
          ediel_id,
          supplier_switch_readiness_status,
          manual_review_required,
          manual_review_reason,
          role_aware_blocking_reasons
        from prodat_action_required
        order by name
        limit 20
      ) s
    ), '[]'::jsonb)
  )
from prodat_action_required

union all

select
  'masterdata:grid_owner_prodat_out_of_scope_inventory'::text,
  'ok'::text,
  count(*)::bigint,
  jsonb_build_object(
    'health_class', 'inventory_info',
    'scope', 'excluded_or_non_electricity_grid_owner',
    'sample', coalesce((
      select jsonb_agg(to_jsonb(s))
      from (
        select name, ediel_id, primary_role_group, supplier_switch_readiness_status
        from prodat_out_of_scope
        order by name
        limit 20
      ) s
    ), '[]'::jsonb)
  )
from prodat_out_of_scope

union all

select
  'masterdata:grid_area_ops_owner_mapping_review'::text,
  case when count(*) > 0 then 'warning' else 'ok' end::text,
  count(*)::bigint,
  jsonb_build_object(
    'health_class', 'masterdata_review',
    'distinct_platform_grid_owners', count(distinct grid_owner_id),
    'reconciliation_engine', 'gridex_reconcile_grid_owner_mappings_v1',
    'automatic_write_policy', 'deterministic_verified_identity_only',
    'sample', coalesce((
      select jsonb_agg(to_jsonb(s))
      from (
        select grid_area_code, grid_area_name, platform_grid_owner_name, grid_owner_id
        from unmapped_areas
        order by grid_area_code
        limit 20
      ) s
    ), '[]'::jsonb)
  )
from unmapped_areas

union all

select
  'route:dynamic_receiver_candidate_templates'::text,
  'ok'::text,
  count(*)::bigint,
  jsonb_build_object(
    'health_class', 'inventory_info',
    'receiver_semantics', 'resolved_at_operation_time',
    'sample', coalesce((
      select jsonb_agg(to_jsonb(s))
      from (
        select route_name, production_mode, receiver_source, dynamic_receiver_strategy, message_family
        from dynamic_candidate_templates
        order by route_name
        limit 20
      ) s
    ), '[]'::jsonb)
  )
from dynamic_candidate_templates

union all

select
  'route:dynamic_receiver_candidate_template_invalid'::text,
  case when count(*) > 0 then 'warning' else 'ok' end::text,
  count(*)::bigint,
  jsonb_build_object(
    'health_class', 'actionable_warning',
    'reason', 'dynamic receiver candidates require a resolver strategy and mailbox',
    'sample', coalesce((
      select jsonb_agg(to_jsonb(s))
      from (
        select route_name, production_mode, receiver_source, dynamic_receiver_strategy
        from invalid_dynamic_candidate_templates
        order by route_name
        limit 20
      ) s
    ), '[]'::jsonb)
  )
from invalid_dynamic_candidate_templates

union all

select
  'route:static_candidate_receiver_or_mailbox_missing'::text,
  case when count(*) > 0 then 'warning' else 'ok' end::text,
  count(*)::bigint,
  jsonb_build_object(
    'health_class', 'actionable_warning',
    'reason', 'non-disabled static candidates require a receiver and mailbox',
    'sample', coalesce((
      select jsonb_agg(to_jsonb(s))
      from (
        select route_name, production_mode, receiver_source, receiver_ediel_id
        from invalid_static_candidate_receivers
        order by route_name
        limit 20
      ) s
    ), '[]'::jsonb)
  )
from invalid_static_candidate_receivers

union all

select
  'route:non_live_certificate_candidate_inventory'::text,
  'ok'::text,
  count(*)::bigint,
  jsonb_build_object(
    'health_class', 'inventory_info',
    'disabled_count', count(*) filter (where coalesce(production_mode, 'disabled') = 'disabled'),
    'dynamic_receiver_count', count(*) filter (where receiver_source in ('dynamic_grid_owner', 'selected_metering_point_grid_owner')),
    'reason', 'disabled profiles and dynamic receiver templates defer or do not require a static production recipient certificate'
  )
from non_live_certificate_inventory

union all

select
  'route:static_candidate_receiver_certificate_invalid_or_missing'::text,
  case when count(*) > 0 then 'warning' else 'ok' end::text,
  count(*)::bigint,
  jsonb_build_object(
    'health_class', 'actionable_warning',
    'reason', 'non-disabled static candidate requires a usable recipient certificate',
    'sample', coalesce((
      select jsonb_agg(to_jsonb(s))
      from (
        select route_name, production_mode, receiver_source, receiver_ediel_id, resolved_certificate_status
        from actionable_static_candidate_certificates
        order by route_name
        limit 20
      ) s
    ), '[]'::jsonb)
  )
from actionable_static_candidate_certificates;
$$;

--
-- Name: FUNCTION gridex_ops_health_checks_v5(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_ops_health_checks_v5() IS 'Role/scope-aware OPS health v5. Preserves live route blocking while separating actionable warnings, masterdata review, and inventory information.';

--
-- Name: gridex_optimize_rls_auth_initplans(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_optimize_rls_auth_initplans() RETURNS TABLE(table_name text, policy_name text, status text, old_using text, new_using text, old_check text, new_check text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
declare
  p record;
  v_roles text;
  v_using text;
  v_check text;
  v_cmd text;
  v_permissive text;
  v_sql text;
begin
  for p in
    select *
    from pg_policies
    where schemaname = 'public'
      and (
        coalesce(qual, '') ilike '%auth.uid()%'
        or coalesce(qual, '') ilike '%auth.role()%'
        or coalesce(qual, '') ilike '%auth.jwt()%'
        or coalesce(qual, '') ilike '%gridex_user_is_platform_admin()%'
        or coalesce(with_check, '') ilike '%auth.uid()%'
        or coalesce(with_check, '') ilike '%auth.role()%'
        or coalesce(with_check, '') ilike '%auth.jwt()%'
        or coalesce(with_check, '') ilike '%gridex_user_is_platform_admin()%'
      )
  loop
    v_using := public.gridex_rls_initplan_rewrite(p.qual);
    v_check := public.gridex_rls_initplan_rewrite(p.with_check);

    if coalesce(v_using, '') = coalesce(p.qual, '') and coalesce(v_check, '') = coalesce(p.with_check, '') then
      table_name := p.tablename;
      policy_name := p.policyname;
      status := 'unchanged';
      old_using := p.qual;
      new_using := v_using;
      old_check := p.with_check;
      new_check := v_check;
      return next;
      continue;
    end if;

    select string_agg(format('%I', r::text), ', ' order by r::text)
      into v_roles
    from unnest(p.roles) as r;

    v_roles := coalesce(nullif(v_roles, ''), 'public');
    v_cmd := upper(p.cmd);
    -- ALTER POLICY preserves command, permissive/restrictive mode and roles.
    -- This is intentionally safer than drop/create because a failed rewrite cannot remove access.
    v_sql := format('alter policy %I on public.%I', p.policyname, p.tablename);

    if v_using is not null and v_cmd <> 'INSERT' then
      v_sql := v_sql || format(' using (%s)', v_using);
    end if;

    if v_check is not null and v_cmd <> 'SELECT' and v_cmd <> 'DELETE' then
      v_sql := v_sql || format(' with check (%s)', v_check);
    end if;

    begin
      execute v_sql;
      table_name := p.tablename;
      policy_name := p.policyname;
      status := 'rewritten';
      old_using := p.qual;
      new_using := v_using;
      old_check := p.with_check;
      new_check := v_check;
      return next;
    exception when others then
      raise notice 'RLS initplan rewrite skipped for %.%: %', p.tablename, p.policyname, sqlerrm;
      table_name := p.tablename;
      policy_name := p.policyname;
      status := 'skipped: ' || sqlerrm;
      old_using := p.qual;
      new_using := v_using;
      old_check := p.with_check;
      new_check := v_check;
      return next;
    end;
  end loop;
end;
$$;

--
-- Name: gridex_partner_contract_event_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_partner_contract_event_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_event_type text;
  v_data jsonb;
begin
  if coalesce(new.metadata->>'source_channel','') <> 'partner_api' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    v_event_type := 'contract.created';
    v_data := jsonb_build_object(
      'contract_reference',new.customer_contract_reference,
      'status',new.status,
      'offer_reference',new.offer_reference
    );
  elsif new.status is distinct from old.status then
    v_event_type := 'contract.status_changed';
    v_data := jsonb_build_object(
      'contract_reference',new.customer_contract_reference,
      'status',new.status,
      'previous_status',old.status,
      'offer_reference',new.offer_reference
    );
  else
    return new;
  end if;

  perform private.gridex_emit_partner_resource_event_v2(
    new.company_id,
    new.customer_id,
    v_event_type,
    'contract',
    new.customer_contract_reference,
    v_data,
    'partner:' || v_event_type || ':' || new.id::text || ':' || coalesce(new.updated_at::text,new.created_at::text,now()::text)
  );
  return new;
end
$$;

--
-- Name: gridex_pause_contract_channels(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_pause_contract_channels(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  v_channels bigint:=0;
  v_publications bigint:=0;
  v_versions bigint:=0;
  v_public_offers bigint:=0;
begin
  perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.pause');
  select * into o from public.contract_offers
  where id=p_offer_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='contract_offer_not_found'; end if;
  if o.contract_product_version_id is null then
    perform public.gridex_sync_internal_offer_to_canonical(o.id);
    select * into o from public.contract_offers where id=o.id for update;
  end if;
  if o.contract_product_version_id is null then
    return jsonb_build_object('ok',false,'changed',false,'code','contract_backfill_incomplete');
  end if;

  update public.tenant_contract_channels ch
  set status='paused',updated_by=p_actor_user_id,updated_at=now()
  from public.tenant_contract_assignments ta
  where ch.assignment_id=ta.id and ta.company_id=p_company_id
    and ta.contract_product_version_id=o.contract_product_version_id
    and ch.status='active';
  get diagnostics v_channels=row_count;

  update public.contract_publications p set status='paused',updated_at=now()
  from public.tenant_contract_assignments ta
  where p.assignment_id=ta.id and ta.company_id=p_company_id
    and ta.contract_product_version_id=o.contract_product_version_id
    and p.status='published';
  get diagnostics v_publications=row_count;

  perform set_config('gridex.version_transition','on',true);
  update public.contract_publication_versions pv
  set status='ended',valid_to=coalesce(pv.valid_to,now())
  from public.contract_publications p
  join public.tenant_contract_assignments ta on ta.id=p.assignment_id
  where pv.contract_publication_id=p.id and ta.company_id=p_company_id
    and ta.contract_product_version_id=o.contract_product_version_id
    and pv.status='published';
  get diagnostics v_versions=row_count;

  perform set_config('gridex.public_offer_write','on',true);
  update public.public_contract_offers
  set lifecycle_status='paused',publication_status='unpublished',is_public=false,
      website_enabled=false,website_cta_enabled=false,updated_by=p_actor_user_id,updated_at=now()
  where company_id=p_company_id and source_contract_offer_id=o.id
    and (is_public or website_enabled or website_cta_enabled or publication_status='published');
  get diagnostics v_public_offers=row_count;

  update public.tenant_contract_assignments
  set status='paused',updated_at=now()
  where company_id=p_company_id and contract_product_version_id=o.contract_product_version_id
    and status='active';
  update public.contract_offers
  set lifecycle_status='paused',status='inactive',is_active=false,updated_by=p_actor_user_id,updated_at=now()
  where id=o.id returning * into o;
  update public.contract_products set status='paused',updated_at=now()
  where id=o.contract_product_id and company_id=p_company_id;

  insert into public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata)
  values(p_company_id,p_actor_user_id,'contract_product_version',o.contract_product_version_id::text,
    'contract.channels.paused',null,to_jsonb(o),
    jsonb_build_object('offer_id',o.id,'affected_channels',v_channels,'affected_publication_versions',v_versions));

  return jsonb_build_object(
    'ok',true,'changed',(v_channels+v_publications+v_versions+v_public_offers)>0,'mode','paused','offer',to_jsonb(o),
    'affected_channels',v_channels,'affected_publications',v_publications,
    'affected_publication_versions',v_versions,'affected_public_offers',v_public_offers
  );
end $$;

--
-- Name: gridex_persist_pricing_run(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_persist_pricing_run(p_company_id uuid, p_billing_underlay_id uuid, p_result jsonb, p_pricing_snapshot jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_underlay public.billing_underlays%rowtype;
  v_run_id uuid;
  v_final_status text:=coalesce(nullif(p_result->>'status',''),'failed');
  v_rows integer;
begin
  if p_company_id is null or p_billing_underlay_id is null then
    raise exception using errcode='22023',message='company_and_billing_underlay_required';
  end if;
  if v_final_status not in ('success','failed','needs_review') then
    raise exception using errcode='22023',message='invalid_pricing_result_status';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_billing_underlay_id::text,0));
  select * into v_underlay from public.billing_underlays
  where id=p_billing_underlay_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='billing_underlay_not_found_for_tenant'; end if;
  if v_underlay.contract_id is null or coalesce(v_underlay.contract_price_snapshot_id,v_underlay.pricing_snapshot_id) is null then
    raise exception using errcode='23514',message='exact_contract_and_price_snapshot_required';
  end if;
  if exists(select 1 from public.pricing_runs where company_id=p_company_id and billing_underlay_id=p_billing_underlay_id and status='locked') then
    raise exception using errcode='55000',message='pricing_run_locked';
  end if;

  insert into public.pricing_runs(
    company_id,billing_underlay_id,customer_id,billing_period_start,billing_period_end,status,
    total_ex_vat,vat_amount,total_inc_vat,warnings,errors,metadata
  ) values (
    p_company_id,p_billing_underlay_id,v_underlay.customer_id,v_underlay.billing_period_start,v_underlay.billing_period_end,
    case when v_final_status='success' then 'needs_review' else v_final_status end,
    coalesce((p_result->>'total_ex_vat')::numeric,0),coalesce((p_result->>'vat_amount')::numeric,0),
    coalesce((p_result->>'total_inc_vat')::numeric,0),coalesce(p_result->'warnings','[]'::jsonb),
    coalesce(p_result->'errors','[]'::jsonb),jsonb_build_object('source','pricing_core','atomic',true)
  ) returning id into v_run_id;

  insert into public.pricing_preview_lines(
    company_id,pricing_run_id,billing_underlay_id,line_type,description,quantity,unit,
    unit_price_ex_vat,amount_ex_vat,vat_rate,vat_amount,amount_inc_vat,sort_order,metadata
  )
  select p_company_id,v_run_id,p_billing_underlay_id,
    coalesce(nullif(x->>'line_type',''),'unknown'),coalesce(nullif(x->>'description',''),'Prisrad'),
    nullif(x->>'quantity','')::numeric,coalesce(nullif(x->>'unit',''),'st'),nullif(x->>'unit_price_ex_vat','')::numeric,
    coalesce(nullif(x->>'amount_ex_vat','')::numeric,0),coalesce(nullif(x->>'vat_rate','')::numeric,0),
    coalesce(nullif(x->>'vat_amount','')::numeric,0),coalesce(nullif(x->>'amount_inc_vat','')::numeric,0),
    coalesce(nullif(x->>'sort_order','')::integer,100),coalesce(x->'metadata','{}'::jsonb)
  from jsonb_array_elements(coalesce(p_result->'lines','[]'::jsonb)) x;

  insert into public.pricing_interval_evidence(
    company_id,pricing_run_id,billing_underlay_id,billing_underlay_item_id,customer_contract_id,
    metering_interval_start,metering_interval_end,resolution,consumption_kwh,price_sek_per_kwh,
    amount_ex_vat,price_source_id,price_area,evidence_sha256
  )
  select p_company_id,v_run_id,p_billing_underlay_id,nullif(x->>'billing_underlay_item_id','')::uuid,
    v_underlay.contract_id,(x->>'metering_interval_start')::timestamptz,(x->>'metering_interval_end')::timestamptz,
    x->>'resolution',(x->>'consumption_kwh')::numeric,(x->>'price_sek_per_kwh')::numeric,
    (x->>'amount_ex_vat')::numeric,nullif(x->>'price_source_id','')::uuid,x->>'price_area',
    encode(digest((x||jsonb_build_object('pricing_run_id',v_run_id))::text,'sha256'),'hex')
  from jsonb_array_elements(coalesce(p_result->'interval_evidence','[]'::jsonb)) x;

  if v_final_status='success' then
    update public.pricing_runs set status='superseded'
    where company_id=p_company_id and billing_underlay_id=p_billing_underlay_id and id<>v_run_id and status='success';
    update public.pricing_runs set status='success' where id=v_run_id;
    update public.billing_underlays set
      status='validated',readiness_status='ready',readiness_issues='[]'::jsonb,
      invoice_readiness_status='ready_for_invoice',invoice_readiness_issues='[]'::jsonb,
      calculated_total_sek_ex_vat=coalesce((p_result->>'total_ex_vat')::numeric,0),
      calculated_vat_sek=coalesce((p_result->>'vat_amount')::numeric,0),
      calculated_total_sek_inc_vat=coalesce((p_result->>'total_inc_vat')::numeric,0),
      pricing_snapshot=coalesce(p_pricing_snapshot,'{}'::jsonb)||jsonb_build_object(
        'latest_pricing_run_id',v_run_id,'latest_pricing_warnings',coalesce(p_result->'warnings','[]'::jsonb),
        'latest_pricing_errors',coalesce(p_result->'errors','[]'::jsonb)
      ),updated_at=now()
    where id=p_billing_underlay_id and company_id=p_company_id;
    get diagnostics v_rows=row_count;
    if v_rows<>1 then raise exception using errcode='P0002',message='billing_underlay_atomic_update_failed'; end if;
  else
    update public.billing_underlays set
      pricing_snapshot=coalesce(pricing_snapshot,'{}'::jsonb)||jsonb_build_object(
        'latest_failed_pricing_run_id',v_run_id,'latest_pricing_errors',coalesce(p_result->'errors','[]'::jsonb)
      ),updated_at=now()
    where id=p_billing_underlay_id and company_id=p_company_id;
  end if;
  return v_run_id;
end
$$;

--
-- Name: gridex_persist_utilts_transactions_v1(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_persist_utilts_transactions_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_message_code text, p_transactions jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  v_source public.ediel_messages%rowtype;
  v_item jsonb;
  v_transaction_id text;
  v_disposition text;
  v_response_type text;
  v_dedupe_key text;
  v_series_identity text;
  v_series_id uuid;
  v_previous_id uuid;
  v_version integer;
  v_inserted boolean;
  v_quantity jsonb;
  v_order integer;
  v_results jsonb := '[]'::jsonb;
  v_error text;
begin
  if p_environment not in ('test','production') then raise exception 'utilts_environment_invalid'; end if;
  if jsonb_typeof(p_transactions) <> 'array' then raise exception 'utilts_transactions_must_be_array'; end if;

  select * into v_source from public.ediel_messages where id=p_source_message_id for share;
  if not found or v_source.message_family <> 'UTILTS' then raise exception 'utilts_source_message_missing'; end if;
  if v_source.company_id is distinct from p_company_id or v_source.environment is distinct from p_environment then
    raise exception 'utilts_source_tenant_or_environment_mismatch' using errcode='23514';
  end if;

  for v_item in select value from jsonb_array_elements(p_transactions)
  loop
    v_transaction_id := nullif(btrim(v_item->>'transactionId'),'');
    v_disposition := coalesce(nullif(v_item->>'disposition',''),'processability_rejected');
    v_response_type := coalesce(nullif(v_item->>'responseType',''),'utilts_err');
    if v_transaction_id is null then v_transaction_id := 'transaction-' || (jsonb_array_length(v_results)+1)::text; end if;

    insert into public.ediel_ack_transaction_results(
      company_id,environment,source_message_id,source_transaction_id,
      syntax_result,guide_validation_result,processability_result,
      disposition,planned_response_type,issue_codes,persistence_status,updated_at
    ) values (
      p_company_id,p_environment,p_source_message_id,v_transaction_id,
      case when v_disposition='syntax_rejected' then 'negative' else 'positive' end,
      case when v_disposition='guide_rejected' then 'negative' when v_disposition='syntax_rejected' then 'pending' else 'positive' end,
      case when v_disposition='processability_rejected' then 'negative' when v_disposition='accepted' then 'positive' else 'not_applicable' end,
      v_disposition,v_response_type,
      coalesce(array(select jsonb_array_elements_text(coalesce(v_item->'issueCodes','[]'::jsonb))),array[]::text[]),
      case when v_disposition='accepted' then 'pending' else 'not_applicable' end,now()
    ) on conflict(company_id,environment,source_message_id,source_transaction_id)
    do update set
      syntax_result=excluded.syntax_result,
      guide_validation_result=excluded.guide_validation_result,
      processability_result=excluded.processability_result,
      disposition=excluded.disposition,
      planned_response_type=excluded.planned_response_type,
      issue_codes=excluded.issue_codes,
      persistence_status=excluded.persistence_status,
      persisted_series_id=null,
      persistence_error=null,
      updated_at=now();

    if v_disposition <> 'accepted' then
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'transactionId',v_transaction_id,'disposition',v_disposition,
        'responseType',v_response_type,'persistenceStatus','not_applicable'
      ));
      continue;
    end if;

    begin
      v_series_identity := concat_ws('|',p_company_id::text,coalesce(v_item->>'seriesKind','actual'),
        p_message_code,coalesce(v_item->>'externalMeteringPointId',''),coalesce(v_item->>'gridAreaId',''),
        coalesce(v_item->>'periodStart',''),coalesce(v_item->>'periodEnd',''),
        coalesce(v_item->>'resolution','UNKNOWN'),coalesce(v_item->>'productId',''));
      perform pg_advisory_xact_lock(hashtextextended(v_series_identity,0));
      v_dedupe_key := encode(digest(convert_to(v_series_identity || '|' || v_transaction_id,'UTF8'),'sha256'),'hex');
      v_previous_id := null;
      v_version := 1;
      select id,version_no into v_previous_id,v_version
      from public.meter_reading_series
      where company_id=p_company_id and is_current
        and series_kind=coalesce(v_item->>'seriesKind','actual')
        and coalesce(message_code,'')=coalesce(p_message_code,'')
        and coalesce(external_metering_point_id,'')=coalesce(v_item->>'externalMeteringPointId','')
        and coalesce(grid_area_id,'')=coalesce(v_item->>'gridAreaId','')
        and period_start is not distinct from nullif(v_item->>'periodStart','')::timestamptz
        and period_end is not distinct from nullif(v_item->>'periodEnd','')::timestamptz
        and resolution=coalesce(v_item->>'resolution','UNKNOWN')
        and coalesce(product_id,'')=coalesce(v_item->>'productId','')
        and dedupe_key<>v_dedupe_key
      order by version_no desc limit 1 for update;
      if v_previous_id is not null then v_version := v_version + 1; end if;

      insert into public.meter_reading_series(
        company_id,metering_point_id,source_ediel_message_id,external_metering_point_id,
        grid_area_id,period_start,period_end,resolution,unit,quality_status,dedupe_key,
        message_code,source_transaction_reference,series_kind,product_id,time_series_product,
        actor_context,registration_date,latest_update_date,version_no,supersedes_series_id,
        is_current,correction_reason,raw_transaction,immutable_hash
      ) values (
        p_company_id,nullif(v_item->>'meteringPointId','')::uuid,p_source_message_id,
        nullif(v_item->>'externalMeteringPointId',''),nullif(v_item->>'gridAreaId',''),
        nullif(v_item->>'periodStart','')::timestamptz,nullif(v_item->>'periodEnd','')::timestamptz,
        coalesce(nullif(v_item->>'resolution',''),'UNKNOWN'),coalesce(nullif(v_item->>'unit',''),'KWH'),
        'received',v_dedupe_key,p_message_code,v_transaction_id,coalesce(v_item->>'seriesKind','actual'),
        nullif(v_item->>'productId',''),v_item->'timeSeriesProduct',coalesce(v_item->'actorContext','{}'::jsonb),
        nullif(v_item->>'registrationDate','')::timestamptz,nullif(v_item->>'latestUpdateDate','')::timestamptz,
        v_version,v_previous_id,true,nullif(v_item->>'correctionReason',''),v_item,
        encode(digest(convert_to(v_item::text,'UTF8'),'sha256'),'hex')
      ) on conflict(company_id,dedupe_key) do nothing returning id into v_series_id;
      v_inserted := v_series_id is not null;
      if not v_inserted then
        select id into v_series_id from public.meter_reading_series
        where company_id=p_company_id and dedupe_key=v_dedupe_key;
      else
        if v_previous_id is not null then
          update public.meter_reading_series set is_current=false where id=v_previous_id;
        end if;
        v_order := 0;
        for v_quantity in select value from jsonb_array_elements(coalesce(v_item->'quantities','[]'::jsonb))
        loop
          v_order := v_order + 1;
          insert into public.meter_reading_values(
            company_id,series_id,reading_at,quantity,unit,quality,source_order,
            observation_id,qualifier,raw_value,metadata
          ) values (
            p_company_id,v_series_id,nullif(v_quantity->>'readingAt','')::timestamptz,
            nullif(v_quantity->>'value','')::numeric,coalesce(nullif(v_item->>'unit',''),'KWH'),
            coalesce(nullif(v_quantity->>'quality',''),'unknown'),v_order,
            coalesce(nullif(v_quantity->>'observationId',''),v_order::text),
            nullif(v_quantity->>'qualifier',''),v_quantity->>'raw',coalesce(v_quantity->'metadata','{}'::jsonb)
          );
        end loop;
      end if;

      update public.ediel_ack_transaction_results set
        persistence_status='persisted',persisted_series_id=v_series_id,persistence_error=null,updated_at=now()
      where company_id=p_company_id and environment=p_environment
        and source_message_id=p_source_message_id and source_transaction_id=v_transaction_id;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'transactionId',v_transaction_id,'disposition','accepted','responseType','positive_aperak',
        'persistenceStatus','persisted','seriesId',v_series_id,'idempotentReplay',not v_inserted
      ));
    exception when others then
      get stacked diagnostics v_error = message_text;
      update public.ediel_ack_transaction_results set
        disposition='processability_rejected',planned_response_type='utilts_err',
        processability_result='negative',persistence_status='failed',persistence_error=left(v_error,500),
        issue_codes=array_append(issue_codes,'UTILTS_PERSISTENCE_FAILED'),updated_at=now()
      where company_id=p_company_id and environment=p_environment
        and source_message_id=p_source_message_id and source_transaction_id=v_transaction_id;
      v_results := v_results || jsonb_build_array(jsonb_build_object(
        'transactionId',v_transaction_id,'disposition','processability_rejected','responseType','utilts_err',
        'persistenceStatus','failed','issueCodes',jsonb_build_array('UTILTS_PERSISTENCE_FAILED')
      ));
    end;
  end loop;
  return v_results;
end $$;

--
-- Name: gridex_platform_dashboard_summary_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_platform_dashboard_summary_v1() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
with
customer_stats as (
  select count(*) filter (
    where company_id is not null
      and (source is null or source <> 'ediel_portal_test')
      and (status is null or status not in ('archived','deleted','deleted_test_only','pending_deletion'))
  )::bigint as customers_total
  from public.customers
),
contract_stats as (
  select
    count(*)::bigint as contracts_total,
    count(*) filter (
      where ends_at >= current_date
        and ends_at <= current_date + interval '30 days'
    )::bigint as upcoming_terminations
  from public.customer_contracts
),
site_stats as (
  select count(*)::bigint as sites_total
  from public.customer_sites
),
metering_point_stats as (
  select count(*)::bigint as metering_points_total
  from public.metering_points
),
task_stats as (
  select
    count(*) filter (where status = 'open')::bigint as open_tasks,
    count(*) filter (where status in ('open','in_progress','blocked'))::bigint as customers_action_required
  from public.customer_operation_tasks
),
grid_owner_request_stats as (
  select
    count(*) filter (where status = 'sent')::bigint as open_grid_owner_requests,
    count(*) filter (where status in ('sent','waiting_response','queued'))::bigint as waiting_for_grid_owner
  from public.grid_owner_data_requests
),
switch_stats as (
  select
    count(*) filter (where status = 'open')::bigint as open_switches,
    count(*) filter (
      where status in (
        'draft','queued','submitted','accepted','cancellation_requested',
        'cancellation_sent','manual_followup_required'
      )
    )::bigint as ongoing_supplier_switches
  from public.supplier_switch_requests
),
outbound_stats as (
  select count(*)::bigint as outbound_requests_total
  from public.outbound_requests
),
metering_value_stats as (
  select
    count(*)::bigint as metering_values_total,
    count(*) filter (where created_at >= now() - interval '7 days')::bigint as latest_metering_values
  from public.metering_values
),
billing_stats as (
  select count(*)::bigint as billing_underlays_total
  from public.billing_underlays
),
data_quality_stats as (
  select count(*) filter (
    where status = 'open' and issue_type = 'missing_metering_values'
  )::bigint as missing_metering_values
  from public.data_quality_issues
),
intake_stats as (
  select count(*) filter (
    where status in ('needs_review','partially_created','failed')
  )::bigint as pending_customer_applications
  from public.external_contract_intakes
),
ediel_message_stats as (
  select
    count(*)::bigint as total_messages,
    count(*) filter (where direction = 'inbound')::bigint as inbound_messages,
    count(*) filter (where direction = 'outbound')::bigint as outbound_messages,
    count(*) filter (where status = 'draft')::bigint as draft_messages,
    count(*) filter (where status = 'failed')::bigint as failed_messages,
    count(*) filter (where status = 'queued')::bigint as queued_messages,
    count(*) filter (where status = 'prepared')::bigint as prepared_messages,
    count(*) filter (where status = 'sent')::bigint as sent_messages,
    count(*) filter (
      where contrl_status = 'pending' or aperak_status = 'pending'
    )::bigint as ack_pending_messages,
    count(*) filter (
      where (contrl_status = 'pending' or aperak_status = 'pending')
        and ack_due_at < now()
    )::bigint as ack_overdue_messages,
    count(*) filter (where ack_outcome = 'negative')::bigint as negative_acknowledgements
  from public.ediel_messages
),
route_stats as (
  select count(*) filter (
    where is_active = true
      and (
        route_type = 'ediel_partner'
        or target_system ilike '%ediel%'
        or target_email ilike '%ediel%'
      )
  )::bigint as active_routes
  from public.communication_routes
),
profile_stats as (
  select count(*)::bigint as configured_profiles
  from public.ediel_route_profiles
),
test_stats as (
  select count(*) filter (where status in ('draft','running'))::bigint as active_test_runs
  from public.ediel_test_runs
),
platform_stats as (
  select
    (select count(*)::bigint from public.companies) as companies_total,
    (select count(*)::bigint from public.grid_owners) as grid_owners_total,
    (select count(*)::bigint from public.electricity_suppliers) as electricity_suppliers_total
)
select jsonb_build_object(
  'generated_at', now(),
  'customers_total', cs.customers_total,
  'contracts_total', cts.contracts_total,
  'sites_total', ss.sites_total,
  'metering_points_total', mps.metering_points_total,
  'open_tasks', ts.open_tasks,
  'open_grid_owner_requests', gos.open_grid_owner_requests,
  'open_switches', sws.open_switches,
  'outbound_requests_total', os.outbound_requests_total,
  'metering_values_total', mvs.metering_values_total,
  'billing_underlays_total', bs.billing_underlays_total,
  'ongoing_supplier_switches', sws.ongoing_supplier_switches,
  'waiting_for_grid_owner', gos.waiting_for_grid_owner,
  'negative_acknowledgements', ems.negative_acknowledgements,
  'missing_metering_values', dqs.missing_metering_values,
  'customers_action_required', ts.customers_action_required,
  'latest_metering_values', mvs.latest_metering_values,
  'upcoming_terminations', cts.upcoming_terminations,
  'pending_customer_applications', ins.pending_customer_applications,
  'companies_total', ps.companies_total,
  'grid_owners_total', ps.grid_owners_total,
  'electricity_suppliers_total', ps.electricity_suppliers_total,
  'ediel', jsonb_build_object(
    'total_messages', ems.total_messages,
    'inbound_messages', ems.inbound_messages,
    'outbound_messages', ems.outbound_messages,
    'draft_messages', ems.draft_messages,
    'failed_messages', ems.failed_messages,
    'queued_messages', ems.queued_messages,
    'prepared_messages', ems.prepared_messages,
    'sent_messages', ems.sent_messages,
    'ack_pending_messages', ems.ack_pending_messages,
    'ack_overdue_messages', ems.ack_overdue_messages,
    'active_routes', rs.active_routes,
    'configured_profiles', prs.configured_profiles,
    'active_test_runs', tes.active_test_runs,
    'running_tests', tes.active_test_runs
  )
)
from customer_stats cs
cross join contract_stats cts
cross join site_stats ss
cross join metering_point_stats mps
cross join task_stats ts
cross join grid_owner_request_stats gos
cross join switch_stats sws
cross join outbound_stats os
cross join metering_value_stats mvs
cross join billing_stats bs
cross join data_quality_stats dqs
cross join intake_stats ins
cross join ediel_message_stats ems
cross join route_stats rs
cross join profile_stats prs
cross join test_stats tes
cross join platform_stats ps;
$$;

--
-- Name: gridex_platform_default_legal_templates_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_platform_default_legal_templates_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.updated_at := now();
  return new;
end $$;

--
-- Name: gridex_point_to_grid_area(numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_point_to_grid_area(p_x numeric, p_y numeric) RETURNS TABLE(grid_area_code text, grid_area_name text, grid_owner_id uuid, grid_owner_name text, price_area text, confidence numeric, source text)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
  with point_input as (
    select extensions.ST_SetSRID(
      extensions.ST_MakePoint(p_x::double precision, p_y::double precision),
      3006
    ) as geom
  ),
  matching_codes as (
    select distinct g.grid_area_code
    from public.platform_grid_area_geometries g
    cross join point_input p
    where g.is_active = true
      and g.geometry is not null
      and extensions.ST_Covers(g.geometry, p.geom)
  ),
  unique_code as (
    select min(grid_area_code) as grid_area_code, count(*)::integer as match_count
    from matching_codes
  ),
  area_geometry as (
    select
      u.grid_area_code,
      u.match_count,
      extensions.ST_UnaryUnion(extensions.ST_Collect(g.geometry)) as geometry
    from unique_code u
    join public.platform_grid_area_geometries g
      on g.grid_area_code = u.grid_area_code
     and g.is_active = true
     and g.geometry is not null
    where u.match_count = 1
    group by u.grid_area_code, u.match_count
  ),
  scored as (
    select
      a.grid_area_code,
      extensions.ST_Distance(p.geom, extensions.ST_Boundary(a.geometry)) as boundary_distance_m
    from area_geometry a
    cross join point_input p
  )
  select
    ga.grid_area_code,
    ga.grid_area_name,
    ga.grid_owner_id,
    coalesce(go.name, ga.grid_owner_name) as grid_owner_name,
    ga.price_area,
    case
      when s.boundary_distance_m >= 5000 then 0.99::numeric
      when s.boundary_distance_m >= 2500 then 0.97::numeric
      when s.boundary_distance_m >= 1500 then 0.95::numeric
      when s.boundary_distance_m >= 750 then 0.88::numeric
      else 0.75::numeric
    end as confidence,
    'svk_arcgis_polygon'::text as source
  from scored s
  join public.platform_grid_areas ga
    on ga.grid_area_code = s.grid_area_code
   and ga.is_active = true
  left join public.platform_grid_owners go on go.id = ga.grid_owner_id;
$$;

--
-- Name: FUNCTION gridex_point_to_grid_area(p_x numeric, p_y numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_point_to_grid_area(p_x numeric, p_y numeric) IS 'Matches one point to exactly one active SVK grid area. Confidence is boundary-distance based: >=1.5 km is the default high-confidence Papilite threshold; exact-address callers may still use lower-confidence matches for review.';

--
-- Name: gridex_portfolio_actor_has_permission(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_portfolio_actor_has_permission(p_actor_user_id uuid, p_permission text, p_company_id uuid, p_portfolio_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  select (coalesce(auth.role(),'')='service_role' or p_actor_user_id=auth.uid())
  and (public.gridex_portfolio_actor_is_superadmin(p_actor_user_id)
  or (
    p_permission<>'portfolio_settlement.manage_access'
    and exists(
      select 1 from public.portfolio_settlement_permission_grants g
      where g.user_id=p_actor_user_id
        and g.permission=p_permission
        and g.company_id=p_company_id
        and (g.portfolio_id is null or g.portfolio_id=p_portfolio_id)
        and g.revoked_at is null
        and g.valid_from<=now()
        and (g.expires_at is null or g.expires_at>now())
    )
  ))
$$;

--
-- Name: gridex_portfolio_actor_is_superadmin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_portfolio_actor_is_superadmin(p_actor_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
  select p_actor_user_id is not null
  and (coalesce(auth.role(), '') = 'service_role' or p_actor_user_id = auth.uid())
  and (
    exists (
      select 1
      from public.admin_users au
      where au.user_id = p_actor_user_id
        and coalesce(au.is_active, true)
        and lower(coalesce(au.role, '')) in ('super_admin', 'platform_superadmin')
    )
    or exists (
      select 1
      from public.user_roles ur
      left join public.roles r on r.id = ur.role_id
      where ur.user_id = p_actor_user_id
        and coalesce(ur.status, 'active') = 'active'
        and coalesce(ur.is_active, true)
        and lower(coalesce(ur.role, r.key, r.name, '')) in ('super_admin', 'platform_superadmin')
    )
  )
$$;

