--
-- Name: gridex_prepare_billing_export_retry(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_prepare_billing_export_retry(p_company_id uuid, p_export_run_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_rows integer;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_export_run_id::text||':retry',0));
  perform 1 from public.billing_export_runs where id=p_export_run_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='billing_export_run_not_found'; end if;
  update public.billing_export_run_items set export_status='ready_for_retry',status='ready_for_retry',partner_result_type='none',failed_at=null,last_error=null,
    retry_count=retry_count+1,updated_at=now() where company_id=p_company_id and billing_export_run_id=p_export_run_id and export_status='failed';
  get diagnostics v_rows=row_count;
  update public.billing_export_runs set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('retryPreparedAt',now(),'retryPreparedBy',p_actor_user_id,'retryPreparedRows',v_rows),updated_at=now()
  where id=p_export_run_id and company_id=p_company_id;
  perform public.gridex_refresh_billing_export_run(p_company_id,p_export_run_id);
  return jsonb_build_object('reopened',v_rows);
end $$;

--
-- Name: gridex_prepare_customer_contract_signature_request_v1(uuid, uuid, uuid, text, text, timestamp with time zone, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_prepare_customer_contract_signature_request_v1(p_company_id uuid, p_customer_id uuid, p_contract_id uuid, p_token_hash text, p_recipient_email text, p_expires_at timestamp with time zone, p_actor_user_id uuid, p_channel text DEFAULT 'internal'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $_$
declare
  v_contract public.customer_contracts%rowtype;
  v_company public.companies%rowtype;
  v_binding jsonb;
  v_snapshot_id uuid;
  v_snapshot jsonb;
  v_base_components jsonb;
  v_price_components jsonb;
  v_pricing_model text;
  v_request public.customer_contract_signature_requests%rowtype;
  v_event jsonb;
begin
  perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.create');

  if p_company_id is null or p_customer_id is null or p_contract_id is null then
    raise exception using errcode='22023',message='signature_request_company_customer_contract_required';
  end if;
  if coalesce(p_token_hash,'') !~ '^[0-9a-f]{64}$' then
    raise exception using errcode='22023',message='signature_request_token_hash_invalid';
  end if;
  if nullif(btrim(coalesce(p_recipient_email,'')),'') is null or position('@' in p_recipient_email)=0 then
    raise exception using errcode='22023',message='signature_request_recipient_email_required';
  end if;
  if p_channel not in ('internal','website','partner_api','customer_portal') then
    raise exception using errcode='22023',message='signature_request_channel_invalid';
  end if;
  if p_expires_at is null or p_expires_at <= now() or p_expires_at > now()+interval '14 days' then
    raise exception using errcode='22023',message='signature_request_expiry_invalid';
  end if;

  select * into v_company from public.companies where id=p_company_id for share;
  if not found or not coalesce(v_company.is_active,false) or coalesce(v_company.lifecycle_status,'')<>'active' or v_company.suspended_at is not null then
    raise exception using errcode='55000',message='signature_request_tenant_not_operational';
  end if;

  select * into v_contract
  from public.customer_contracts
  where id=p_contract_id and company_id=p_company_id and customer_id=p_customer_id
  for update;
  if not found then
    raise exception using errcode='P0002',message='signature_request_contract_not_found_for_tenant';
  end if;
  if v_contract.status in ('signed','active','terminated','cancelled','expired') or v_contract.signed_at is not null then
    raise exception using errcode='23514',message='signature_request_contract_already_finalized';
  end if;
  if v_contract.status not in ('draft','pending_signature','signature_failed') then
    raise exception using errcode='23514',message='signature_request_contract_state_invalid';
  end if;

  if v_contract.contract_publication_version_id is null
     or v_contract.contract_product_version_id is null
     or v_contract.price_plan_version_id is null
     or v_contract.legal_bundle_version_id is null then
    if v_contract.contract_offer_id is not null then
      perform public.gridex_ensure_internal_contract_publication(p_company_id,v_contract.contract_offer_id,p_actor_user_id);
      update public.customer_contracts
      set contract_offer_id=v_contract.contract_offer_id,updated_by=p_actor_user_id,updated_at=now()
      where id=v_contract.id and company_id=p_company_id
      returning * into v_contract;
    else
      v_binding:=public.gridex_prepare_manual_contract_binding(
        p_company_id,
        jsonb_strip_nulls(jsonb_build_object(
          'name',v_contract.contract_name,
          'customer_type',(select c.customer_type from public.customers c where c.id=v_contract.customer_id and c.company_id=p_company_id),
          'contract_type',v_contract.contract_type,
          'energy_direction',v_contract.energy_direction,
          'campaign_code',v_contract.campaign_code,
          'campaign_version',v_contract.campaign_version,
          'terms_version',v_contract.terms_version,
          'binding_months',v_contract.binding_months,
          'notice_months',v_contract.notice_months,
          'valid_from',coalesce(v_contract.starts_at::date,current_date),
          'valid_to',v_contract.ends_at::date
        )),
        coalesce(v_contract.price_snapshot,'{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
          'contract_type',v_contract.contract_type,
          'energy_direction',v_contract.energy_direction,
          'price_area',v_contract.price_area_used,
          'fixed_price_ore_per_kwh',v_contract.fixed_price_ore_per_kwh,
          'spot_markup_ore_per_kwh',v_contract.spot_markup_ore_per_kwh,
          'variable_fee_ore_per_kwh',v_contract.variable_fee_ore_per_kwh,
          'monthly_fee_sek',v_contract.monthly_fee_sek,
          'invoice_fee_sek',v_contract.invoice_fee_sek,
          'green_fee_mode',v_contract.green_fee_mode,
          'green_fee_value',v_contract.green_fee_value,
          'discount_value',v_contract.discount_value,
          'discount_unit',v_contract.discount_unit,
          'start_fee_sek',v_contract.start_fee_sek,
          'admin_fee_sek',v_contract.admin_fee_sek,
          'break_fee_sek',v_contract.break_fee_sek,
          'vat_rate',v_contract.vat_rate
        )),
        p_actor_user_id
      );
      update public.customer_contracts set
        contract_offer_id=nullif(v_binding->>'contract_offer_id','')::uuid,
        contract_product_id=nullif(v_binding->>'contract_product_id','')::uuid,
        contract_product_version_id=nullif(v_binding->>'contract_product_version_id','')::uuid,
        contract_publication_version_id=nullif(v_binding->>'contract_publication_version_id','')::uuid,
        price_plan_id=nullif(v_binding->>'price_plan_id','')::uuid,
        price_plan_version_id=nullif(v_binding->>'price_plan_version_id','')::uuid,
        price_book_id=nullif(v_binding->>'price_book_id','')::uuid,
        legal_bundle_version_id=nullif(v_binding->>'legal_bundle_version_id','')::uuid,
        offer_reference=v_binding->>'offer_reference',
        commercial_snapshot=coalesce(v_binding->'commercial_snapshot','{}'::jsonb),
        legal_snapshot=coalesce(v_binding->'legal_snapshot','{}'::jsonb),
        updated_by=p_actor_user_id,updated_at=now()
      where id=v_contract.id and company_id=p_company_id
      returning * into v_contract;
    end if;
  end if;

  if v_contract.contract_publication_version_id is null
     or v_contract.contract_product_version_id is null
     or v_contract.price_plan_version_id is null
     or v_contract.legal_bundle_version_id is null then
    raise exception using errcode='23514',message='signature_request_exact_contract_chain_missing';
  end if;

  if v_contract.contract_price_snapshot_id is null then
    select coalesce(cpv.pricing_model,'spot') into v_pricing_model
    from public.contract_product_versions cpv where cpv.id=v_contract.contract_product_version_id;
    v_base_components:=coalesce(
      v_contract.price_snapshot->'base_price_components_snapshot',
      v_contract.commercial_snapshot->'base_price_components_snapshot',
      v_contract.commercial_snapshot->'base_components',
      '[]'::jsonb
    );
    v_price_components:=coalesce(
      v_contract.price_snapshot->'price_components_snapshot',
      v_contract.commercial_snapshot->'price_components_snapshot',
      v_contract.commercial_snapshot->'price_components',
      '[]'::jsonb
    );
    if jsonb_typeof(v_base_components)<>'array' then v_base_components:='[]'::jsonb; end if;
    if jsonb_typeof(v_price_components)<>'array' then v_price_components:='[]'::jsonb; end if;
    v_snapshot:=jsonb_strip_nulls(coalesce(v_contract.price_snapshot,'{}'::jsonb) || jsonb_build_object(
      'snapshot_schema','gridex_contract_pricing_v7_signed_receipt',
      'source','signature_prepare',
      'company_id',v_contract.company_id,
      'contract_id',v_contract.id,
      'contract_number',v_contract.contract_number,
      'customer_number',v_contract.customer_number,
      'contract_type',v_contract.contract_type,
      'energy_direction',v_contract.energy_direction,
      'price_area',v_contract.price_area_used,
      'fixed_price_ore_per_kwh',v_contract.fixed_price_ore_per_kwh,
      'spot_markup_ore_per_kwh',v_contract.spot_markup_ore_per_kwh,
      'variable_fee_ore_per_kwh',v_contract.variable_fee_ore_per_kwh,
      'monthly_fee_sek',v_contract.monthly_fee_sek,
      'invoice_fee_sek',v_contract.invoice_fee_sek,
      'green_fee_mode',v_contract.green_fee_mode,
      'green_fee_value',v_contract.green_fee_value,
      'discount_value',v_contract.discount_value,
      'discount_unit',v_contract.discount_unit,
      'start_fee_sek',v_contract.start_fee_sek,
      'admin_fee_sek',v_contract.admin_fee_sek,
      'break_fee_sek',v_contract.break_fee_sek,
      'vat_rate',v_contract.vat_rate,
      'binding_months',v_contract.binding_months,
      'notice_months',v_contract.notice_months,
      'starts_at',v_contract.starts_at,
      'ends_at',v_contract.ends_at,
      'offer_reference',v_contract.offer_reference,
      'contract_publication_version_id',v_contract.contract_publication_version_id,
      'contract_product_version_id',v_contract.contract_product_version_id,
      'price_plan_version_id',v_contract.price_plan_version_id,
      'legal_bundle_version_id',v_contract.legal_bundle_version_id,
      'base_price_components_snapshot',v_base_components,
      'price_components_snapshot',v_price_components
    ));
    v_snapshot:=private.gridex_normalize_fixed_area_snapshot_v1(v_snapshot);
    insert into public.contract_price_snapshots(
      company_id,contract_id,customer_id,price_plan_version_id,pricing_model,
      base_price_components_snapshot,price_components_snapshot,snapshot_json,
      valid_from,valid_to,source,contract_number,customer_number,snapshot_hash,
      snapshot_quality,snapshot_schema_version
    ) values(
      p_company_id,v_contract.id,v_contract.customer_id,v_contract.price_plan_version_id,
      coalesce(v_pricing_model,'spot'),v_snapshot->'base_price_components_snapshot',
      coalesce(v_snapshot->'price_components_snapshot','[]'::jsonb),v_snapshot,
      coalesce(v_contract.starts_at::date,current_date),v_contract.ends_at::date,
      'signature_prepare',v_contract.contract_number,v_contract.customer_number,
      encode(extensions.digest(convert_to(v_snapshot::text,'UTF8'),'sha256'),'hex'),
      'canonical','gridex_contract_pricing_v7_signed_receipt'
    ) returning id into v_snapshot_id;
    update public.customer_contracts
    set contract_price_snapshot_id=v_snapshot_id,price_snapshot=v_snapshot,updated_by=p_actor_user_id,updated_at=now()
    where id=v_contract.id and company_id=p_company_id
    returning * into v_contract;
  end if;

  if not exists(
    select 1
    from public.contract_publication_versions cpv
    join public.contract_publications cp on cp.id=cpv.contract_publication_id
    join public.tenant_contract_assignments ta on ta.id=cp.assignment_id and ta.company_id=p_company_id
    join public.contract_product_versions ctv on ctv.id=cpv.contract_product_version_id
    join public.price_plan_versions ppv on ppv.id=cpv.price_plan_version_id
    join public.legal_bundle_versions lbv on lbv.id=cpv.legal_bundle_version_id
    join public.contract_price_snapshots cps on cps.id=v_contract.contract_price_snapshot_id and cps.contract_id=v_contract.id and cps.company_id=p_company_id
    where cpv.id=v_contract.contract_publication_version_id
      and cpv.contract_product_version_id=v_contract.contract_product_version_id
      and cpv.price_plan_version_id=v_contract.price_plan_version_id
      and cpv.legal_bundle_version_id=v_contract.legal_bundle_version_id
      and cpv.status='published' and cpv.locked_at is not null
      and ctv.status='approved' and ctv.locked_at is not null
      and ppv.status in ('published','approved','active') and ppv.locked_at is not null
      and lbv.status='published' and lbv.locked_at is not null and cardinality(lbv.unresolved_variables)=0
      and nullif(cps.snapshot_hash,'') is not null
  ) then
    raise exception using errcode='23514',message='signature_request_exact_locked_chain_invalid';
  end if;
  if not exists(select 1 from public.legal_bundle_version_documents d where d.legal_bundle_version_id=v_contract.legal_bundle_version_id) then
    raise exception using errcode='23514',message='signature_request_legal_document_set_missing';
  end if;

  if v_contract.status in ('draft','signature_failed') then
    update public.customer_contracts
    set status='pending_signature',lifecycle_stage='agreement_ready',updated_by=p_actor_user_id,updated_at=now()
    where id=v_contract.id and company_id=p_company_id
    returning * into v_contract;
  end if;

  update public.customer_contract_signature_requests
  set revoked_at=now()
  where company_id=p_company_id and customer_contract_id=p_contract_id
    and used_at is null and revoked_at is null;

  insert into public.customer_contract_signature_requests(
    company_id,customer_id,customer_contract_id,token_hash,recipient_email,
    channel,expires_at,created_by,metadata
  ) values(
    p_company_id,p_customer_id,p_contract_id,p_token_hash,lower(btrim(p_recipient_email)),
    p_channel,p_expires_at,p_actor_user_id,
    jsonb_build_object(
      'contract_number',v_contract.contract_number,
      'offer_reference',v_contract.offer_reference,
      'contract_publication_version_id',v_contract.contract_publication_version_id,
      'price_plan_version_id',v_contract.price_plan_version_id,
      'legal_bundle_version_id',v_contract.legal_bundle_version_id,
      'contract_price_snapshot_id',v_contract.contract_price_snapshot_id
    )
  ) returning * into v_request;

  v_event:=public.gridex_record_customer_contract_event_v1(
    p_company_id,v_contract.id,v_contract.customer_id,'signature_requested',now(),
    'Online-signering begärd',
    jsonb_build_object('signature_request_id',v_request.id,'channel',p_channel,'expires_at',p_expires_at),
    p_actor_user_id,null,
    encode(extensions.digest(convert_to((v_request.id::text||':signature_requested'),'UTF8'),'sha256'),'hex')
  );

  return jsonb_build_object(
    'ok',true,
    'request_id',v_request.id,
    'company_id',p_company_id,
    'customer_id',v_contract.customer_id,
    'contract_id',v_contract.id,
    'contract_number',v_contract.contract_number,
    'contract_name',v_contract.contract_name,
    'status',v_contract.status,
    'recipient_email',v_request.recipient_email,
    'expires_at',v_request.expires_at,
    'channel',v_request.channel,
    'offer_reference',v_contract.offer_reference,
    'contract_publication_version_id',v_contract.contract_publication_version_id,
    'price_plan_version_id',v_contract.price_plan_version_id,
    'legal_bundle_version_id',v_contract.legal_bundle_version_id,
    'contract_price_snapshot_id',v_contract.contract_price_snapshot_id
  );
end
$_$;

--
-- Name: gridex_prepare_manual_contract_binding(uuid, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_prepare_manual_contract_binding(p_company_id uuid, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_identity uuid := gen_random_uuid();
  v_saved jsonb;
  v_offer_id uuid;
  v_publication_id uuid;
  v_publication public.contract_publication_versions%rowtype;
  v_product public.contract_product_versions%rowtype;
  v_legal public.legal_bundle_versions%rowtype;
begin
  if p_company_id is null then
    raise exception using errcode='22023',message='company_required';
  end if;

  p_payload := coalesce(p_payload,'{}'::jsonb) || jsonb_build_object(
    'name',coalesce(nullif(p_payload->>'name',''),'Kundspecifikt avtal'),
    'slug','one-off-' || replace(v_identity::text,'-',''),
    'status','active',
    'is_active',true,
    'customer_type',coalesce(nullif(p_payload->>'customer_type',''),'both'),
    'contract_type',coalesce(nullif(p_payload->>'contract_type',''),'variable_hourly'),
    'campaign_code',coalesce(nullif(p_payload->>'campaign_code',''),'ONE_OFF'),
    'campaign_version',coalesce(nullif(p_payload->>'campaign_version',''),'v1'),
    'terms_version',coalesce(nullif(p_payload->>'terms_version',''),'canonical')
  );
  p_pricing_snapshot := coalesce(p_pricing_snapshot,'{}'::jsonb) || jsonb_build_object(
    'one_off',true,
    'one_off_identity',v_identity,
    'source_of_truth','price_plan_versions'
  );

  v_saved := public.gridex_upsert_internal_contract_offer(
    p_company_id,null,p_payload,p_pricing_snapshot,p_actor_user_id
  );
  v_offer_id := nullif(v_saved#>>'{offer,id}','')::uuid;
  if v_offer_id is null then
    raise exception using errcode='P0001',message='one_off_offer_creation_failed';
  end if;

  v_publication_id := public.gridex_ensure_internal_contract_publication(
    p_company_id,v_offer_id,p_actor_user_id
  );
  select * into v_publication
  from public.contract_publication_versions
  where id=v_publication_id and status='published' and locked_at is not null;
  if not found then
    raise exception using errcode='23514',message='one_off_publication_not_locked';
  end if;

  select * into v_product
  from public.contract_product_versions
  where id=v_publication.contract_product_version_id and status='approved' and locked_at is not null;
  if not found then
    raise exception using errcode='23514',message='one_off_product_version_not_locked';
  end if;
  select * into v_legal
  from public.legal_bundle_versions
  where id=v_publication.legal_bundle_version_id and status='published' and locked_at is not null;
  if not found or cardinality(v_legal.unresolved_variables)>0 then
    raise exception using errcode='23514',message='one_off_legal_version_not_ready';
  end if;

  update public.contract_offers
  set status='inactive',is_active=false,archived_at=coalesce(archived_at,now()),updated_at=now(),updated_by=p_actor_user_id
  where id=v_offer_id;

  return jsonb_build_object(
    'contract_offer_id',v_offer_id,
    'contract_product_id',v_product.contract_product_id,
    'contract_product_version_id',v_product.id,
    'contract_publication_version_id',v_publication.id,
    'price_plan_id',v_publication.price_plan_id,
    'price_plan_version_id',v_publication.price_plan_version_id,
    'price_book_id',v_publication.price_book_id,
    'legal_bundle_version_id',v_publication.legal_bundle_version_id,
    'offer_reference',v_publication.offer_reference,
    'commercial_snapshot',v_product.commercial_snapshot,
    'legal_snapshot',v_legal.rendered_snapshot,
    'source_of_truth','contract_publication_versions'
  );
end $$;

--
-- Name: gridex_prevent_locked_portfolio_price_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_prevent_locked_portfolio_price_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.price_plan_version_id is not null and old.locked_at is not null then
    raise exception 'locked_portfolio_monthly_price_immutable';
  end if;
  return case when tg_op='DELETE' then old else new end;
end $$;

--
-- Name: gridex_prevent_published_legal_text_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_prevent_published_legal_text_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.status = 'published' then
      raise exception 'Published legal text versions cannot be deleted. Archive by publishing a new version instead.';
    end if;
    return old;
  end if;

  if old.status = 'published' and (
    old.company_id is distinct from new.company_id or
    old.type is distinct from new.type or
    old.version is distinct from new.version or
    old.title is distinct from new.title or
    old.body is distinct from new.body
  ) then
    raise exception 'Published legal text content is immutable. Create a new version instead.';
  end if;

  return new;
end $$;

--
-- Name: gridex_preview_delete_unused_contract(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_preview_delete_unused_contract(p_company_id uuid, p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  v_business jsonb;
  v_graph jsonb;
  v_counts jsonb;
  v_public_offer_ids uuid[]:='{}'::uuid[];
  v_product_version_ids uuid[]:='{}'::uuid[];
  v_publication_version_ids uuid[]:='{}'::uuid[];
  v_legal_version_ids uuid[]:='{}'::uuid[];
  v_offer_references text[]:='{}'::text[];
  v_quote_count bigint:=0;
  v_backfill_issue_count bigint:=0;
  v_business_total bigint:=0;
  v_unsafe_total bigint:=0;
  v_reason_codes text[]:='{}'::text[];
  v_can_delete boolean:=false;
  v_delete_status_allowed boolean:=false;
  v_public_fk_blockers jsonb;
begin
  select * into o
  from public.contract_offers co
  where co.id=p_offer_id and co.company_id=p_company_id;
  if not found then
    return jsonb_build_object(
      'ok',false,'code','contract_offer_not_found',
      'can_delete',false,'deletable',false,
      'blockers',jsonb_build_array(jsonb_build_object(
        'resource_type','contract_offer','count',0,
        'reason','contract_offer_not_found',
        'message','Avtalet hittades inte för valt bolag.'
      ))
    );
  end if;

  v_business:=public.gridex_contract_business_usage_counts(p_company_id,p_offer_id);
  v_graph:=public.gridex_resolve_contract_lifecycle_graph(p_company_id,p_offer_id);
  if not coalesce((v_graph->>'ok')::boolean,false) then
    return v_graph||jsonb_build_object('can_delete',false,'deletable',false);
  end if;
  v_counts:=coalesce(v_graph->'counts','{}'::jsonb);

  select coalesce(array_agg(value::uuid),'{}'::uuid[])
    into v_public_offer_ids
  from jsonb_array_elements_text(coalesce(v_graph->'public_contract_offer_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[])
    into v_product_version_ids
  from jsonb_array_elements_text(coalesce(v_graph->'contract_product_version_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[])
    into v_publication_version_ids
  from jsonb_array_elements_text(coalesce(v_graph->'publication_version_ids','[]'::jsonb));
  select coalesce(array_agg(value::uuid),'{}'::uuid[])
    into v_legal_version_ids
  from jsonb_array_elements_text(coalesce(v_graph->'legal_bundle_version_ids','[]'::jsonb));

  v_offer_references:=public.gridex_contract_offer_references_v1(
    p_company_id,
    v_public_offer_ids,
    v_product_version_ids,
    v_publication_version_ids
  );

  select count(*) into v_quote_count
  from public.website_contract_quotes q
  where q.company_id=p_company_id and (
    q.contract_product_version_id=any(v_product_version_ids)
    or q.contract_publication_version_id=any(v_publication_version_ids)
    or q.legal_bundle_version_id=any(v_legal_version_ids)
    or q.offer_reference=any(v_offer_references)
  );

  select count(*) into v_backfill_issue_count
  from public.contract_lifecycle_backfill_issues i
  where i.company_id=p_company_id and (
    i.contract_offer_id=p_offer_id
    or i.public_contract_offer_id=any(v_public_offer_ids)
  );

  v_business_total:=coalesce((v_business->>'total')::bigint,0)+v_quote_count;
  v_unsafe_total:=coalesce((v_counts->>'successor_offers')::bigint,0)
    +coalesce((v_counts->>'shared_product_version_references')::bigint,0)
    +coalesce((v_counts->>'shared_legal_version_references')::bigint,0)
    +coalesce((v_counts->>'unsafe_graph_issues')::bigint,0);
  v_delete_status_allowed:=o.lifecycle_status in ('draft','ready');

  if coalesce((v_business->>'customer_contracts')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_CUSTOMER_CONTRACTS'); end if;
  if coalesce((v_business->>'customer_applications')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_ACCEPTED_APPLICATIONS'); end if;
  if coalesce((v_business->>'external_intakes')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_EXTERNAL_INTAKES'); end if;
  if coalesce((v_business->>'binding_price_snapshots')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_BINDING_PRICE_SNAPSHOTS'); end if;
  if coalesce((v_business->>'invoices')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_INVOICES'); end if;
  if coalesce((v_business->>'billing_underlays')::bigint,0)>0 or coalesce((v_business->>'billing_underlay_items')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_BILLING_HISTORY'); end if;
  if coalesce((v_business->>'charge_ledger')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_CHARGE_LEDGER'); end if;
  if coalesce((v_business->>'legal_acceptances')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_LEGAL_ACCEPTANCES'); end if;
  if v_quote_count>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_WEBSITE_QUOTES'); end if;
  if coalesce((v_counts->>'successor_offers')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_SUCCESSOR_VERSION'); end if;
  if coalesce((v_counts->>'shared_product_version_references')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_SHARED_CANONICAL_VERSION'); end if;
  if coalesce((v_counts->>'shared_legal_version_references')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'HAS_SHARED_LEGAL_VERSION'); end if;
  if coalesce((v_counts->>'unsafe_graph_issues')::bigint,0)>0 then v_reason_codes:=array_append(v_reason_codes,'PUBLICATION_GRAPH_INCONSISTENT'); end if;
  if not v_delete_status_allowed then v_reason_codes:=array_append(v_reason_codes,'PERMANENT_DELETE_REQUIRES_DRAFT'); end if;

  -- Backfill issue rows are technical diagnostics and are deleted before their
  -- referenced public offer. They are reported but never misclassified as
  -- customer/business history.
  v_public_fk_blockers:=public.gridex_fk_reference_blockers(
    'public.public_contract_offers'::regclass,
    v_public_offer_ids,
    array[
      'contract_lifecycle_backfill_issues',
      'contract_publication_versions'
    ]
  );
  if coalesce((v_public_fk_blockers->>'count')::integer,0)>0 then
    v_reason_codes:=array_append(v_reason_codes,'HAS_RESTRICTING_FOREIGN_KEYS');
  end if;

  v_can_delete:=v_delete_status_allowed
    and v_business_total=0
    and v_unsafe_total=0
    and coalesce((v_public_fk_blockers->>'count')::integer,0)=0;

  return jsonb_build_object(
    'ok',true,
    'code',case when v_can_delete then null else 'contract_delete_blocked' end,
    'contract_product_id',o.contract_product_id,
    'can_delete',v_can_delete,
    'deletable',v_can_delete,
    'has_business_usage',v_business_total>0,
    'requires_archive',v_business_total>0 or not v_delete_status_allowed,
    'requires_unpublish',o.lifecycle_status in ('published','paused'),
    'recommended_action',case
      when o.lifecycle_status in ('published','paused') then 'unpublish'
      when o.lifecycle_status in ('closed','expired','archived','superseded') then 'hide_terminal'
      when v_business_total>0 then 'archive'
      when v_unsafe_total>0 then 'repair'
      when v_can_delete then 'delete'
      else 'review'
    end,
    'result_mode',case when v_can_delete then 'delete' else 'archive_only' end,
    'business_blockers',(v_business-'ok'-'total')||jsonb_build_object('website_quotes',v_quote_count),
    'business_references',(v_business-'ok'-'total')||jsonb_build_object('website_quotes',v_quote_count),
    'removable_system_dependencies',jsonb_build_object(
      'public_offers',coalesce((v_counts->>'public_offers')::bigint,0),
      'tenant_assignments',coalesce((v_counts->>'tenant_assignments')::bigint,0),
      'publications',coalesce((v_counts->>'publications')::bigint,0),
      'publication_versions',coalesce((v_counts->>'publication_versions')::bigint,0),
      'legal_bundle_versions',coalesce((v_counts->>'legal_bundle_versions')::bigint,0),
      'backfill_issues',v_backfill_issue_count
    ),
    'system_references',v_counts||jsonb_build_object(
      'website_quotes',v_quote_count,
      'contract_lifecycle_backfill_issues',v_backfill_issue_count
    ),
    'foreign_key_blockers',v_public_fk_blockers,
    'reason_codes',to_jsonb(v_reason_codes),
    'blockers',public.gridex_contract_delete_blocker_details_v1(
      v_reason_codes,v_business,v_quote_count,v_counts,v_public_fk_blockers
    ),
    'lifecycle_status',o.lifecycle_status,
    'canonical_mapping_complete',
      o.contract_product_id is not null and o.contract_product_version_id is not null,
    'legacy_cleanup_supported',true,
    'graph',v_graph
  );
end $$;

--
-- Name: FUNCTION gridex_preview_delete_unused_contract(p_company_id uuid, p_offer_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_preview_delete_unused_contract(p_company_id uuid, p_offer_id uuid) IS 'Service-only tenant-safe delete preview using the same dependency graph and structured blockers as the commit command.';

--
-- Name: gridex_preview_delete_unused_contract_v2(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_preview_delete_unused_contract_v2(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
begin
  perform public.gridex_assert_contract_permission(
    p_actor_user_id,
    'contracts.delete_unused'
  );
  return public.gridex_contract_delete_dependency_graph_v2(
    p_company_id,
    p_offer_id
  );
end
$$;

--
-- Name: FUNCTION gridex_preview_delete_unused_contract_v2(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_preview_delete_unused_contract_v2(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) IS 'Service-only actor-aware delete preview. The server binds actor and tenant from the authenticated session.';

--
-- Name: gridex_preview_public_contract_backfill_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_preview_public_contract_backfill_v1(p_company_id uuid DEFAULT NULL::uuid, p_offer_id uuid DEFAULT NULL::uuid, p_publication_version_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT NULL::text) RETURNS TABLE(company_id uuid, external_tenant_reference text, offer_id uuid, offer_reference text, publication_id uuid, publication_version_id uuid, channel text, current_status text, detected_problem text, proposed_action text, safe_to_apply boolean, manual_review_reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
with candidates as (
  select diagnostic.*,
    exists(select 1 from public.contract_price_options template
      where template.company_id=diagnostic.company_id
        and template.contract_product_version_id=(select pv.contract_product_version_id
          from public.contract_publication_versions pv
          where pv.id=diagnostic.publication_version_id)
        and template.price_plan_version_id=(select pv.price_plan_version_id
          from public.contract_publication_versions pv
          where pv.id=diagnostic.publication_version_id)
        and template.contract_publication_version_id is null) template_exists,
    exists(select 1 from public.contract_price_options snapshot_option
      where snapshot_option.contract_publication_version_id=
        diagnostic.publication_version_id) snapshot_exists,
    (select count(*)
      from public.contract_price_options snapshot_option
      where snapshot_option.contract_publication_version_id=
        diagnostic.publication_version_id) snapshot_option_count,
    (select count(*)
      from public.contract_price_options snapshot_option
      where snapshot_option.contract_publication_version_id=
          diagnostic.publication_version_id
        and not exists(
          select 1 from public.contract_price_options template
          where template.company_id=snapshot_option.company_id
            and template.contract_product_version_id=
              snapshot_option.contract_product_version_id
            and template.price_plan_version_id=
              snapshot_option.price_plan_version_id
            and template.contract_publication_version_id is null
            and template.option_reference=snapshot_option.option_reference
            and template.option_code=snapshot_option.option_code
        )) template_missing_count,
    (select count(distinct prior.contract_publication_version_id)
      from public.contract_price_options prior
      join public.contract_publication_versions current_version
        on current_version.id=diagnostic.publication_version_id
      where prior.company_id=diagnostic.company_id
        and prior.contract_product_version_id=current_version.contract_product_version_id
        and prior.price_plan_version_id=current_version.price_plan_version_id
        and prior.contract_publication_version_id is not null
        and prior.contract_publication_version_id<>diagnostic.publication_version_id
    ) prior_snapshot_source_count
  from public.canonical_public_contract_diagnostics_v diagnostic
  where (diagnostic.publication_version_id is null
      or diagnostic.publication_version_status in (
        'published','paused','ended','draft','review'))
    and (p_company_id is null or diagnostic.company_id=p_company_id)
    and (p_offer_id is null or diagnostic.source_contract_offer_id=p_offer_id)
    and (p_publication_version_id is null
      or diagnostic.publication_version_id=p_publication_version_id)
    and (p_channel is null or diagnostic.channel=lower(p_channel))
)
select c.company_id,c.external_tenant_reference,
  c.source_contract_offer_id,c.offer_reference,c.publication_id,
  c.publication_version_id,c.channel,
  coalesce(c.publication_version_status,c.channel_state),
  array_to_string(c.blockers,','),
  case
    when c.publication_version_id is null then 'MANUAL_CHANNEL_OR_PUBLICATION_REVIEW'
    when c.price_option_count=0 then 'MATERIALIZE_PRICE_OPTION_SNAPSHOT'
    when c.missing_area_count>0 then 'COMPLETE_AREA_PRICE_RELATIONS'
    when c.template_missing_count>0 and c.snapshot_exists
      then 'RESTORE_TEMPLATE_COPY'
    else 'REFINALIZE_SNAPSHOT_AND_REVISION'
  end,
  (
    c.publication_version_id is not null
    and (c.price_option_count>0 or c.template_exists
      or c.snapshot_exists or c.prior_snapshot_source_count=1)
    and c.legal_ready
    and c.invoice_fee_ready
    and c.assignment_id is not null
    and c.channel_id is not null
    and c.snapshot_source_contract_offer_id=
      c.source_contract_offer_id::text
    and c.duplicate_option_count=0
    and c.supported_areas_valid
    and (c.missing_area_count=0 or c.template_exists)
  ),
  case
    when c.publication_version_id is null then 'PUBLICATION_VERSION_MISSING'
    when c.snapshot_source_contract_offer_id is distinct from
      c.source_contract_offer_id::text
      then 'SOURCE_OFFER_NOT_DETERMINISTIC'
    when c.duplicate_option_count>0
      then 'PRICE_OPTION_DUPLICATES_REQUIRE_REVIEW'
    when not c.supported_areas_valid
      then 'SUPPORTED_PRICE_AREAS_INVALID'
    when not c.legal_ready then 'LEGAL_BUNDLE_NOT_DETERMINISTIC'
    when not c.invoice_fee_ready then 'INVOICE_FEE_CONFIGURATION_MISSING'
    when c.assignment_id is null then 'TENANT_ASSIGNMENT_MISSING'
    when c.channel_id is null then 'CHANNEL_INTENT_NOT_PROVEN'
    when c.missing_area_count>0 and not c.template_exists
      then 'SUPPORTED_AREA_PRICE_SOURCE_MISSING'
    when not (c.price_option_count>0 or c.template_exists
      or c.snapshot_exists or c.prior_snapshot_source_count=1)
      then case when c.prior_snapshot_source_count>1
        then 'PRICE_SOURCE_AMBIGUOUS'
        else 'PRICE_SOURCE_NOT_DETERMINISTIC' end
    else null
  end
from candidates c
where cardinality(c.blockers)>0
   or c.template_missing_count>0
order by c.company_id,c.source_contract_offer_id,c.channel
$$;

--
-- Name: gridex_preview_public_contract_legal_backfill_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_preview_public_contract_legal_backfill_v1(p_company_id uuid DEFAULT NULL::uuid) RETURNS TABLE(publication_version_id uuid, company_id uuid, category text, safe_to_apply boolean, legal_bundle_version_id uuid, module_count bigint, derivation_method text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
  select pv.id,assignment.company_id,
    case
      when pv.legal_bundle_version_id is null then 'missing_source'
      when bundle.id is null then 'missing_source'
      when count(document.id)=0 then 'blocked'
      when pv.publication_snapshot->'legal_snapshot'->>'legal_bundle_version_id'=
          pv.legal_bundle_version_id::text
        and pv.publication_snapshot->'legal_snapshot'->>'immutable'='true'
        and jsonb_typeof(
          pv.publication_snapshot->'legal_snapshot'->'module_versions'
        )='array'
        and jsonb_array_length(case
          when jsonb_typeof(
            pv.publication_snapshot->'legal_snapshot'->'module_versions'
          )='array' then
            pv.publication_snapshot->'legal_snapshot'->'module_versions'
          else '[]'::jsonb end
        )=count(document.id)
        and not exists(
          select 1
          from jsonb_array_elements(case
            when jsonb_typeof(
              pv.publication_snapshot->'legal_snapshot'->'module_versions'
            )='array' then
              pv.publication_snapshot->'legal_snapshot'->'module_versions'
            else '[]'::jsonb end
          ) module
          where module->>'legal_bundle_version_id' is distinct from
            pv.legal_bundle_version_id::text
        ) then 'already_valid'
      else 'backfillable'
    end,
    pv.legal_bundle_version_id is not null and bundle.id is not null
      and count(document.id)>0,
    pv.legal_bundle_version_id,count(document.id),
    case when pv.legal_bundle_version_id is not null then
      'exact_locked_bundle_relation' else null end
  from public.contract_publication_versions pv
  join public.contract_publications publication
    on publication.id=pv.contract_publication_id
  join public.tenant_contract_assignments assignment
    on assignment.id=publication.assignment_id
  left join public.legal_bundle_versions bundle
    on bundle.id=pv.legal_bundle_version_id
   and bundle.company_id=assignment.company_id
   and bundle.locked_at is not null
  left join public.legal_bundle_version_documents document
    on document.legal_bundle_version_id=bundle.id
  where pv.status in ('published','paused','ended')
    and (p_company_id is null or assignment.company_id=p_company_id)
  group by pv.id,assignment.company_id,bundle.id
$$;

--
-- Name: gridex_price_option_unique_objects_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_price_option_unique_objects_v1() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
with constraint_objects as (
  select
    table_rel.relname table_name,
    constraint_row.conname object_name,
    'constraint'::text object_kind,
    array_agg(attribute_row.attname::text order by key_row.ordinality) columns,
    null::text predicate
  from pg_constraint constraint_row
  join pg_class table_rel on table_rel.oid=constraint_row.conrelid
  join pg_namespace table_ns on table_ns.oid=table_rel.relnamespace
  cross join lateral unnest(constraint_row.conkey)
    with ordinality key_row(attnum,ordinality)
  join pg_attribute attribute_row
    on attribute_row.attrelid=table_rel.oid
   and attribute_row.attnum=key_row.attnum
  where table_ns.nspname='public'
    and table_rel.relname in (
      'contract_price_options','contract_price_option_area_prices'
    )
    and constraint_row.contype in ('p','u')
  group by table_rel.relname,constraint_row.conname
), standalone_indexes as (
  select
    table_rel.relname table_name,
    index_rel.relname object_name,
    'index'::text object_kind,
    array_agg(attribute_row.attname::text order by key_row.ordinality)
      filter(where key_row.ordinality<=index_row.indnkeyatts) columns,
    pg_get_expr(index_row.indpred,index_row.indrelid) predicate
  from pg_index index_row
  join pg_class table_rel on table_rel.oid=index_row.indrelid
  join pg_namespace table_ns on table_ns.oid=table_rel.relnamespace
  join pg_class index_rel on index_rel.oid=index_row.indexrelid
  cross join lateral unnest(index_row.indkey::smallint[])
    with ordinality key_row(attnum,ordinality)
  join pg_attribute attribute_row
    on attribute_row.attrelid=table_rel.oid
   and attribute_row.attnum=key_row.attnum
  where table_ns.nspname='public'
    and table_rel.relname in (
      'contract_price_options','contract_price_option_area_prices'
    )
    and index_row.indisunique
    and not index_row.indisprimary
    and index_row.indexprs is null
    and not exists(
      select 1 from pg_constraint constraint_row
      where constraint_row.conindid=index_row.indexrelid
    )
  group by table_rel.relname,index_rel.relname,index_row.indpred,
    index_row.indrelid
), all_objects as (
  select * from constraint_objects
  union all
  select * from standalone_indexes
)
select coalesce(
  jsonb_agg(
    jsonb_build_object(
      'table',table_name,
      'name',object_name,
      'kind',object_kind,
      'columns',to_jsonb(columns),
      'predicate',predicate
    ) order by table_name,object_kind,object_name
  ),
  '[]'::jsonb
)
from all_objects;
$$;

--
-- Name: gridex_process_ready_supplier_switch_activations(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_process_ready_supplier_switch_activations(p_actor_user_id uuid, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);
  v_market_date date := (now() at time zone 'Europe/Stockholm')::date;
  v_row record;
  v_activation jsonb;
  v_status text;
  v_activated integer := 0;
  v_already_completed integer := 0;
  v_waiting integer := 0;
  v_blocked integer := 0;
  v_failed integer := 0;
  v_scanned integer := 0;
  v_failures jsonb := '[]'::jsonb;
  v_activated_customers jsonb := '[]'::jsonb;
begin
  if p_actor_user_id is null then
    raise exception 'supplier_switch_activation_actor_required';
  end if;

  for v_row in
    select
      r.id,
      r.company_id,
      r.customer_id
    from public.supplier_switch_requests r
    where r.status = 'accepted'
      and r.company_id is not null
      and r.inbound_z04_message_id is not null
      and coalesce(r.confirmed_start_date, r.requested_start_date) is not null
      and coalesce(r.confirmed_start_date, r.requested_start_date) <= v_market_date
    order by coalesce(r.confirmed_start_date, r.requested_start_date), r.created_at, r.id
    limit v_limit
  loop
    v_scanned := v_scanned + 1;

    begin
      v_activation := public.gridex_finalize_supplier_switch_activation(
        v_row.company_id,
        v_row.id,
        p_actor_user_id
      );
      v_status := coalesce(v_activation->>'status', 'unknown');

      if v_status = 'activated' then
        v_activated := v_activated + 1;
        if not (v_activated_customers @> jsonb_build_array(v_row.customer_id::text)) then
          v_activated_customers := v_activated_customers || jsonb_build_array(v_row.customer_id::text);
        end if;
      elsif v_status = 'already_completed' then
        v_already_completed := v_already_completed + 1;
      elsif v_status = 'waiting' then
        v_waiting := v_waiting + 1;
      elsif v_status = 'blocked' then
        v_blocked := v_blocked + 1;
        v_failures := v_failures || jsonb_build_array(jsonb_build_object(
          'requestId', v_row.id,
          'companyId', v_row.company_id,
          'code', coalesce(v_activation->>'reason_code', 'supplier_switch_activation_blocked')
        ));
      else
        v_failed := v_failed + 1;
        v_failures := v_failures || jsonb_build_array(jsonb_build_object(
          'requestId', v_row.id,
          'companyId', v_row.company_id,
          'code', coalesce(v_activation->>'reason_code', 'supplier_switch_activation_unexpected_result'),
          'status', v_status
        ));
      end if;
    exception when others then
      v_failed := v_failed + 1;
      v_failures := v_failures || jsonb_build_array(jsonb_build_object(
        'requestId', v_row.id,
        'companyId', v_row.company_id,
        'code', 'supplier_switch_activation_failed',
        'message', sqlerrm
      ));
    end;
  end loop;

  return jsonb_build_object(
    'marketDate', v_market_date,
    'scanned', v_scanned,
    'ready', v_scanned,
    'activated', v_activated,
    'alreadyCompleted', v_already_completed,
    'waiting', v_waiting,
    'blocked', v_blocked,
    'failed', v_failed,
    'failures', v_failures,
    'activatedCustomerIds', v_activated_customers
  );
end;
$$;

--
-- Name: gridex_prodat_variant_from_raw(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_prodat_variant_from_raw(p_raw text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select case
    when coalesce(p_raw, '') ~ E'CAV\\+[^'']*Z23' then 'LK'
    when coalesce(p_raw, '') ~ E'CAV\\+[^'']*Z22' then 'L'
    else null
  end
$$;

--
-- Name: gridex_project_terminal_application_continuation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_project_terminal_application_continuation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_application_id uuid;
  v_state text;
  v_public_status text;
  v_next_step text;
  v_reason text;
begin
  if new.job_type <> 'customer_application_continuation'
     or new.status not in ('failed','delivery_uncertain')
     or new.status is not distinct from old.status then
    return new;
  end if;

  begin
    v_application_id := nullif(new.payload ->> 'application_id', '')::uuid;
  exception when others then
    v_application_id := null;
  end;
  if v_application_id is null then return new; end if;

  v_state := 'failed';
  v_public_status := 'failed';
  v_next_step := 'resume_customer_application_continuation';
  v_reason := coalesce(new.last_error_code, new.last_error_message, new.last_error, 'customer_application_continuation_failed');

  update public.customer_application_workflows
  set state = v_state,
      next_action = v_next_step,
      failure_code = v_reason,
      snapshot = coalesce(snapshot, '{}'::jsonb) || jsonb_build_object(
        'terminal_job_id', new.id,
        'terminal_job_status', new.status,
        'terminal_error', v_reason
      ),
      last_job_id = new.id,
      last_transition_at = now(),
      updated_at = now()
  where company_id = new.company_id
    and customer_application_id = v_application_id;

  update public.website_customer_applications
  set status = 'failed',
      next_step = v_next_step,
      response_payload = coalesce(response_payload, '{}'::jsonb) || jsonb_build_object(
        'status', v_public_status,
        'workflow_state', v_state,
        'next_step', v_next_step,
        'blocking_reason', v_reason,
        'automation', jsonb_build_object(
          'status', new.status,
          'error_code', new.last_error_code,
          'error_message', coalesce(new.last_error_message, new.last_error)
        )
      ),
      updated_at = now()
  where id = v_application_id
    and company_id = new.company_id;

  return new;
end;
$$;

--
-- Name: gridex_promote_energy_geodata_version(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_promote_energy_geodata_version(p_geodata_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp', 'extensions'
    AS $$
declare
  v_version public.energy_geodata_versions%rowtype;
  v_feature record;
  v_feature_count integer := 0;
  v_now timestamptz := now();
  v_error_detail text;
  v_error_hint text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'energy_geodata_promote_service_role_required' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('energy-geodata:' || p_geodata_version_id::text, 0));

  select *
  into v_version
  from public.energy_geodata_versions
  where id = p_geodata_version_id
  for update;

  if not found then
    raise exception 'energy_geodata_version_not_found' using errcode = 'P0002';
  end if;
  if v_version.status = 'verified' then
    return to_jsonb(v_version);
  end if;
  if v_version.status <> 'importing' or v_version.coverage_status <> 'complete' then
    raise exception 'energy_geodata_version_not_complete' using errcode = '23514';
  end if;

  select count(*)::integer
  into v_feature_count
  from public.energy_geodata_features_staging
  where geodata_version_id = p_geodata_version_id;

  if v_feature_count <= 0 or v_feature_count <> v_version.feature_count then
    raise exception 'energy_geodata_feature_count_mismatch'
      using errcode = '23514',
            detail = jsonb_build_object(
              'geodata_version_id', p_geodata_version_id,
              'staged_feature_count', v_feature_count,
              'declared_feature_count', v_version.feature_count
            )::text;
  end if;

  for v_feature in
    select feature_id, properties, geometry_geojson, source_url
    from public.energy_geodata_features_staging
    where geodata_version_id = p_geodata_version_id
    order by feature_id
  loop
    begin
      perform public.gridex_import_grid_area_geojson_feature(
        v_feature.feature_id,
        v_feature.properties,
        v_feature.geometry_geojson,
        v_feature.source_url
      );
    exception when others then
      get stacked diagnostics
        v_error_detail = PG_EXCEPTION_DETAIL,
        v_error_hint = PG_EXCEPTION_HINT;
      raise exception 'energy_geodata_feature_promotion_failed'
        using errcode = 'P0001',
              detail = jsonb_build_object(
                'geodata_version_id', p_geodata_version_id,
                'feature_id', v_feature.feature_id,
                'source_error_code', sqlstate,
                'source_error_message', sqlerrm,
                'source_error_detail', v_error_detail,
                'source_error_hint', v_error_hint
              )::text;
    end;

    update public.platform_grid_area_geometries
    set geodata_version_id = p_geodata_version_id,
        is_active = true,
        updated_at = v_now
    where source = 'svk_arcgis'
      and source_feature_id = v_feature.feature_id;
  end loop;

  update public.platform_grid_area_geometries
  set is_active = false,
      updated_at = v_now
  where source = 'svk_arcgis'
    and is_active = true
    and geodata_version_id is distinct from p_geodata_version_id;

  update public.energy_geodata_versions
  set status = 'superseded',
      updated_at = v_now
  where provider = v_version.provider
    and status = 'verified'
    and id <> p_geodata_version_id;

  update public.energy_geodata_versions
  set status = 'verified',
      coverage_status = 'complete',
      verified_at = v_now,
      completed_at = v_now,
      updated_at = v_now
  where id = p_geodata_version_id
  returning * into v_version;

  insert into public.canonical_energy_flow_events(event_type, source, payload, actor_type)
  values (
    'energy_geodata.version.verified',
    'svk_arcgis',
    jsonb_build_object(
      'geodata_version_id', v_version.id,
      'geodata_version', v_version.version_key,
      'feature_count', v_feature_count,
      'verified_at', v_version.verified_at,
      'source_url', v_version.source_url,
      'source_layer_id', v_version.metadata -> 'layer_id'
    ),
    'system'
  );

  return to_jsonb(v_version);
end;
$$;

--
-- Name: gridex_protect_authorization_scope_coverage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_authorization_scope_coverage() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  -- Legacy rows may receive their first immutable snapshot once. The boolean
  -- coverage must then equal that snapshot exactly. After the snapshot exists,
  -- neither the snapshot nor any false->true coverage transition is allowed.
  if coalesce(jsonb_array_length(old.signed_scope_snapshot), 0) = 0
     and coalesce(jsonb_array_length(new.signed_scope_snapshot), 0) > 0 then
    if coalesce(new.covers_grid_owner_data, false) is distinct from (new.signed_scope_snapshot ?| array['grid_owner_data','facility_information_lookup','supplier_switch'])
       or coalesce(new.covers_current_supplier_contract, false) is distinct from (new.signed_scope_snapshot ?| array['current_supplier_contract','supplier_switch'])
       or coalesce(new.covers_metering_data, false) is distinct from (new.signed_scope_snapshot ?| array['metering_data','facility_information_lookup']) then
      raise exception 'Authorization coverage must match signed scope snapshot.' using errcode = '55000';
    end if;
    return new;
  end if;
  if old.signed_scope_snapshot is distinct from new.signed_scope_snapshot then
    raise exception 'Authorization signed scope snapshot is immutable.' using errcode = '55000';
  end if;
  if coalesce(new.covers_grid_owner_data, false) and not coalesce(old.covers_grid_owner_data, false) then
    raise exception 'Authorization coverage cannot be widened after signing.' using errcode = '55000';
  end if;
  if coalesce(new.covers_current_supplier_contract, false) and not coalesce(old.covers_current_supplier_contract, false) then
    raise exception 'Authorization coverage cannot be widened after signing.' using errcode = '55000';
  end if;
  if coalesce(new.covers_metering_data, false) and not coalesce(old.covers_metering_data, false) then
    raise exception 'Authorization coverage cannot be widened after signing.' using errcode = '55000';
  end if;
  return new;
end;
$$;

--
-- Name: gridex_protect_closed_contract_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_closed_contract_delete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.lifecycle_status='closed' then
    raise exception using errcode='55000',message='contract_closed_terminal';
  end if;
  return old;
end $$;

--
-- Name: gridex_protect_customer_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_customer_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.customer_number is not null
     and btrim(old.customer_number) <> ''
     and new.customer_number is distinct from old.customer_number then
    raise exception using errcode = '23514', message = 'customer_number_is_permanent';
  end if;
  if (old.customer_number is null or btrim(old.customer_number) = '')
     and (new.customer_number is null or btrim(new.customer_number) = '')
     and new.customer_number is distinct from old.customer_number then
    -- normalize '' -> null noise writes without failing
    new.customer_number := old.customer_number;
  end if;
  return new;
end;
$$;

--
-- Name: gridex_protect_locked_pricing_runs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_locked_pricing_runs() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('app.gridex_pricing_maintenance', true), '') = 'on' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if old.status = 'locked' then
      raise exception 'Locked pricing runs cannot be deleted. Unlock the billing period and use the explicit maintenance path.'
        using errcode = 'P0001';
    end if;
    return old;
  end if;

  if old.status = 'locked' then
    raise exception 'Locked pricing runs are immutable. Unlock the billing period via the explicit maintenance path before changing run %.', old.id
      using errcode = 'P0001';
  end if;

  return new;
end;
$$;

