-- Name: gridex_protect_onboarding_legal_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_onboarding_legal_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  raise exception 'Published onboarding legal snapshots are immutable.' using errcode = '55000';
