--
-- Name: gridex_protect_published_legacy_offer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_published_legacy_offer() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.publication_status='published'
     and coalesce(current_setting('gridex.public_offer_write',true),'')<>'on' then
    raise exception using errcode='55000',message='published_offer_is_immutable_create_new_version';
  end if;
  return case when tg_op='DELETE' then old else new end;
end $$;

--
-- Name: gridex_protect_sent_invoice_export_items(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_sent_invoice_export_items() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  protected boolean;
begin
  if coalesce(current_setting('app.gridex_billing_maintenance', true), '') = 'on' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  protected := old.status in ('sent', 'credited');

  if tg_op = 'DELETE' then
    if protected then
      raise exception 'Skickade/krediterade fakturaexportposter kan inte raderas (item %). Skapa kredit eller korrigering i stället.', old.id
        using errcode = 'P0001';
    end if;
    return old;
  end if;

  if not protected then
    return new;
  end if;

  -- Block re-send: status must never go back to a sendable state.
  if new.status in ('pending', 'failed', 'failed_retryable') then
    raise exception 'Fakturaexportpost % är redan skickad och kan inte skickas om. Skapa kredit eller korrigering i stället.', old.id
      using errcode = 'P0001';
  end if;

  -- Block financial mutation of a sent invoice.
  if new.amount_ex_vat is distinct from old.amount_ex_vat
     or new.vat_amount is distinct from old.vat_amount
     or new.amount_inc_vat is distinct from old.amount_inc_vat
     or new.rounding_amount is distinct from old.rounding_amount
     or new.request_payload is distinct from old.request_payload
     or new.idempotency_key is distinct from old.idempotency_key
     or new.pricing_run_id is distinct from old.pricing_run_id
     or new.billing_underlay_id is distinct from old.billing_underlay_id
     or new.customer_id is distinct from old.customer_id
  then
    raise exception 'Fakturaexportpost % är skickad och får inte ändras finansiellt. Skapa kredit eller korrigering i stället.', old.id
      using errcode = 'P0001';
  end if;

  -- Provider invoice identity may be set once but never rewritten.
  if old.provider_invoice_guid is not null
     and new.provider_invoice_guid is distinct from old.provider_invoice_guid
  then
    raise exception 'Fakturaexportpost % har redan ett leverantörs-id och det får inte skrivas om.', old.id
      using errcode = 'P0001';
  end if;

  return new;
end;
$$;

--
-- Name: gridex_protect_signed_poa_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_protect_signed_poa_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.signed_scope_snapshot is distinct from new.signed_scope_snapshot then
    raise exception 'Signed power-of-attorney scope snapshot is immutable.' using errcode = '55000';
  end if;
  if old.legal_snapshot_id is not null and old.legal_snapshot_id is distinct from new.legal_snapshot_id then
    raise exception 'Power-of-attorney legal snapshot link is immutable.' using errcode = '55000';
  end if;
  return new;
end;
$$;

--
-- Name: gridex_provision_tenant_website_client_v1(uuid, text, text, text, text, text[], text[], integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_provision_tenant_website_client_v1(p_company_id uuid, p_environment text, p_client_name text, p_key_prefix text, p_secret_hash text, p_scopes text[], p_allowed_origins text[], p_rate_limit_per_minute integer, p_actor_user_id uuid, p_idempotency_key text) RETURNS TABLE(api_client_id uuid, client_created boolean, tenant_reference text, receipt_id uuid, installation_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $_$
declare
  v_environment text := coalesce(nullif(trim(p_environment),''), 'production');
  v_company public.companies%rowtype;
  v_client public.integration_api_clients%rowtype;
  v_active_count integer := 0;
  v_paused_count integer := 0;
  v_created boolean := false;
  v_adopted boolean := false;
  v_receipt_id uuid;
  v_previous_status text;
  v_previous_blockers jsonb;
begin
  if p_company_id is null or p_actor_user_id is null then
    raise exception using errcode='22023', message='TENANT_WEBSITE_PROVISIONING_CONTEXT_REQUIRED';
  end if;
  if v_environment not in ('development','staging','production') then
    raise exception using errcode='22023', message='TENANT_WEBSITE_ENVIRONMENT_INVALID';
  end if;
  if nullif(trim(coalesce(p_idempotency_key,'')),'') is null then
    raise exception using errcode='22023', message='TENANT_WEBSITE_IDEMPOTENCY_KEY_REQUIRED';
  end if;
  if coalesce(cardinality(p_scopes),0) = 0 then
    raise exception using errcode='22023', message='TENANT_WEBSITE_SCOPES_REQUIRED';
  end if;
  if coalesce(cardinality(p_allowed_origins),0) = 0 then
    raise exception using errcode='22023', message='TENANT_WEBSITE_ORIGINS_REQUIRED';
  end if;
  if exists (
    select 1
    from unnest(coalesce(p_allowed_origins,'{}'::text[])) origin
    where origin !~ '^https://[A-Za-z0-9.-]+(:[0-9]+)?$'
  ) then
    raise exception using errcode='22023', message='TENANT_WEBSITE_ORIGIN_INVALID';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_company_id::text || ':tenant_website:' || v_environment, 0)
  );

  select * into v_company
  from public.companies
  where id = p_company_id
  for update;

  if not found then
    raise exception using errcode='P0002', message='TENANT_NOT_FOUND';
  end if;
  if v_company.status not in ('active','onboarding') then
    raise exception using errcode='23514', message='TENANT_NOT_OPERATIONALLY_READY';
  end if;

  if nullif(trim(coalesce(v_company.external_tenant_reference,'')),'') is null then
    update public.companies
       set external_tenant_reference = 'tenant_' || substr(
             encode(extensions.digest(p_company_id::text,'sha256'),'hex'),
             1,
             36
           ),
           updated_at = now()
     where id = p_company_id
     returning * into v_company;
  end if;

  -- One idempotency key identifies the canonical production installation. A
  -- new explicit provisioning/revalidation run resets proof fields before any
  -- credential is made executable. This prevents a historical completed receipt
  -- from authorizing a changed configuration.
  insert into public.tenant_website_installation_receipts(
    company_id, environment, profile_key, idempotency_key, state,
    tenant_reference, allowed_origins, scopes, readiness_blockers,
    receipt_sha256, failure_code, failure_message, created_by, completed_at
  ) values (
    p_company_id, v_environment, 'tenant_website', trim(p_idempotency_key),
    'company_ready', v_company.external_tenant_reference,
    coalesce(p_allowed_origins,'{}'::text[]), coalesce(p_scopes,'{}'::text[]),
    '[]'::jsonb, null, null, null, p_actor_user_id, null
  )
  on conflict (company_id, environment, profile_key, idempotency_key)
  do update set
    state = 'company_ready',
    tenant_reference = excluded.tenant_reference,
    allowed_origins = excluded.allowed_origins,
    scopes = excluded.scopes,
    readiness_blockers = '[]'::jsonb,
    receipt_sha256 = null,
    failure_code = null,
    failure_message = null,
    completed_at = null,
    updated_at = now()
  returning id into v_receipt_id;

  select count(*)::integer into v_active_count
  from public.integration_api_clients existing
  where existing.company_id = p_company_id
    and existing.profile_key = 'tenant_website'
    and existing.status = 'active'
    and existing.deleted_at is null
    and coalesce(nullif(existing.metadata->>'environment',''), 'production') = v_environment
    and lower(coalesce(existing.metadata->>'primary','true')) not in ('false','0','no');

  if v_active_count > 1 then
    update public.tenant_website_installation_receipts
       set state='failed',
           failure_code='DUPLICATE_PRIMARY_TENANT_WEBSITE_CLIENT',
           failure_message='Explicit duplicate-client repair is required.',
           readiness_blockers=jsonb_build_array(jsonb_build_object(
             'code','duplicate_primary_tenant_website_client',
             'environment',v_environment
           )),
           updated_at=now()
     where id=v_receipt_id;
    raise exception using errcode='23505', message='DUPLICATE_PRIMARY_TENANT_WEBSITE_CLIENT';
  end if;

  if v_active_count = 1 then
    select * into v_client
    from public.integration_api_clients existing
    where existing.company_id = p_company_id
      and existing.profile_key = 'tenant_website'
      and existing.status = 'active'
      and existing.deleted_at is null
      and coalesce(nullif(existing.metadata->>'environment',''), 'production') = v_environment
      and lower(coalesce(existing.metadata->>'primary','true')) not in ('false','0','no')
    for update;

    if v_client.revoked_at is not null then
      update public.tenant_website_installation_receipts
         set state='failed',
             failure_code='TENANT_WEBSITE_ACTIVE_CLIENT_REVOKED',
             failure_message='The selected primary client has revocation evidence and cannot be reused.',
             readiness_blockers=jsonb_build_array(jsonb_build_object('code','api_client_revoked')),
             updated_at=now()
       where id=v_receipt_id;
      raise exception using errcode='23514', message='TENANT_WEBSITE_ACTIVE_CLIENT_REVOKED';
    end if;

    update public.integration_api_clients
       set scopes = (
             select array_agg(distinct scope order by scope)
             from unnest(coalesce(v_client.scopes,'{}'::text[]) || coalesce(p_scopes,'{}'::text[])) expanded(scope)
           ),
           allowed_origins = coalesce(p_allowed_origins,'{}'::text[]),
           rate_limit_per_minute = greatest(1,least(coalesce(p_rate_limit_per_minute,120),5000)),
           profile_key = 'tenant_website',
           launch_ready = false,
           launch_blockers = jsonb_build_array(jsonb_build_object('code','provisioning_preflight_pending')),
           metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
             'primary',true,
             'environment',v_environment,
             'provisioning_idempotency_key',trim(p_idempotency_key),
             'provisioning_receipt_id',v_receipt_id,
             'tenant_identity_source','api_key',
             'go_live_flow','canonical_tenant_website_v2'
           ),
           updated_at = now()
     where id = v_client.id
     returning * into v_client;

  else
    select count(*)::integer into v_paused_count
    from public.integration_api_clients existing
    where existing.company_id = p_company_id
      and existing.profile_key = 'tenant_website'
      and existing.status = 'paused'
      and existing.deleted_at is null
      and coalesce(nullif(existing.metadata->>'environment',''), 'production') = v_environment
      and lower(coalesce(existing.metadata->>'primary','true')) not in ('false','0','no');

    if v_paused_count > 1 then
      update public.tenant_website_installation_receipts
         set state='failed',
             failure_code='AMBIGUOUS_PAUSED_PRIMARY_TENANT_WEBSITE_CLIENT',
             failure_message='Multiple paused primary clients require explicit operator repair.',
             readiness_blockers=jsonb_build_array(jsonb_build_object(
               'code','ambiguous_paused_primary_tenant_website_client',
               'environment',v_environment
             )),
             updated_at=now()
       where id=v_receipt_id;
      raise exception using errcode='23505', message='AMBIGUOUS_PAUSED_PRIMARY_TENANT_WEBSITE_CLIENT';
    end if;

    if v_paused_count = 1 then
      select * into v_client
      from public.integration_api_clients existing
      where existing.company_id = p_company_id
        and existing.profile_key = 'tenant_website'
        and existing.status = 'paused'
        and existing.deleted_at is null
        and coalesce(nullif(existing.metadata->>'environment',''), 'production') = v_environment
        and lower(coalesce(existing.metadata->>'primary','true')) not in ('false','0','no')
      for update;

      v_previous_status := v_client.status;
      v_previous_blockers := coalesce(v_client.launch_blockers,'[]'::jsonb);

      -- Auto-adoption is deliberately narrow. A paused credential may be reused
      -- only when every blocker is one of the canonical-readiness migration/
      -- revalidation blockers and at least one such blocker exists. Manual pause,
      -- revocation, deletion, unknown blocker shapes, or mixed blocker reasons
      -- require explicit operator review.
      if v_client.revoked_at is not null
         or jsonb_typeof(v_previous_blockers) <> 'array'
         or jsonb_array_length(v_previous_blockers) = 0
         or not exists (
           select 1
           from jsonb_array_elements(v_previous_blockers) blocker
           where coalesce(blocker->>'code','') in (
             'canonical_readiness_required',
             'canonical_readiness_revalidation_required',
             'canonical_readiness_revalidation_pending'
           )
         )
         or exists (
           select 1
           from jsonb_array_elements(v_previous_blockers) blocker
           where coalesce(blocker->>'code','') not in (
             'canonical_readiness_required',
             'canonical_readiness_revalidation_required',
             'canonical_readiness_revalidation_pending'
           )
         )
      then
        update public.tenant_website_installation_receipts
           set state='failed',
               failure_code='TENANT_WEBSITE_PAUSED_CLIENT_REQUIRES_OPERATOR_REVIEW',
               failure_message='Paused primary client was not paused solely by canonical readiness migration/revalidation.',
               readiness_blockers=jsonb_build_array(jsonb_build_object(
                 'code','paused_client_requires_operator_review',
                 'api_client_id',v_client.id
               )),
               updated_at=now()
         where id=v_receipt_id;
        raise exception using errcode='23514', message='TENANT_WEBSITE_PAUSED_CLIENT_REQUIRES_OPERATOR_REVIEW';
      end if;

      update public.integration_api_clients
         set status = 'active',
             scopes = (
               select array_agg(distinct scope order by scope)
               from unnest(coalesce(v_client.scopes,'{}'::text[]) || coalesce(p_scopes,'{}'::text[])) expanded(scope)
             ),
             allowed_origins = coalesce(p_allowed_origins,'{}'::text[]),
             rate_limit_per_minute = greatest(1,least(coalesce(p_rate_limit_per_minute,120),5000)),
             profile_key = 'tenant_website',
             launch_ready = false,
             launch_blockers = jsonb_build_array(jsonb_build_object('code','provisioning_preflight_pending')),
             metadata = coalesce(metadata,'{}'::jsonb) || jsonb_build_object(
               'primary',true,
               'environment',v_environment,
               'provisioning_idempotency_key',trim(p_idempotency_key),
               'provisioning_receipt_id',v_receipt_id,
               'tenant_identity_source','api_key',
               'go_live_flow','canonical_tenant_website_v2',
               'canonical_readiness_adopted_at',now(),
               'canonical_readiness_adopted_by',p_actor_user_id
             ),
             updated_at = now()
       where id = v_client.id
       returning * into v_client;

      v_adopted := true;
    else
      if nullif(trim(coalesce(p_key_prefix,'')),'') is null
         or nullif(trim(coalesce(p_secret_hash,'')),'') is null then
        raise exception using errcode='22023', message='TENANT_WEBSITE_CREDENTIAL_MATERIAL_REQUIRED';
      end if;

      insert into public.integration_api_clients(
        company_id, name, status, key_prefix, secret_hash, scopes,
        allowed_origins, allowed_ips, rate_limit_per_minute, created_by,
        permission_groups, purpose_label, profile_key, launch_ready,
        launch_blockers, metadata
      ) values (
        p_company_id,
        coalesce(nullif(trim(p_client_name),''),'Tenant website integration'),
        'active', trim(p_key_prefix), trim(p_secret_hash),
        coalesce(p_scopes,'{}'::text[]), coalesce(p_allowed_origins,'{}'::text[]),
        '{}'::text[], greatest(1,least(coalesce(p_rate_limit_per_minute,120),5000)),
        p_actor_user_id, '{}'::text[], 'Tenant website', 'tenant_website', false,
        jsonb_build_array(jsonb_build_object('code','provisioning_preflight_pending')),
        jsonb_build_object(
          'primary',true,
          'environment',v_environment,
          'provisioning_idempotency_key',trim(p_idempotency_key),
          'provisioning_receipt_id',v_receipt_id,
          'tenant_identity_source','api_key',
          'go_live_flow','canonical_tenant_website_v2',
          'token_display','shown_once_on_create'
        )
      )
      returning * into v_client;
      v_created := true;
    end if;
  end if;

  update public.tenant_website_installation_receipts
     set api_client_id=v_client.id,
         state=case when v_created then 'credential_created' else 'client_ready' end,
         updated_at=now()
   where id=v_receipt_id;

  if v_adopted then
    insert into public.audit_logs(
      company_id, actor_user_id, entity_type, entity_id, action,
      old_values, new_values, metadata
    ) values (
      p_company_id,
      p_actor_user_id,
      'integration_api_client',
      v_client.id,
      'api_client.canonical_readiness_adopted',
      jsonb_build_object(
        'status',v_previous_status,
        'launch_blockers',v_previous_blockers
      ),
      jsonb_build_object(
        'status','active',
        'launch_ready',false,
        'launch_blockers',jsonb_build_array(jsonb_build_object('code','provisioning_preflight_pending'))
      ),
      jsonb_build_object(
        'environment',v_environment,
        'receipt_id',v_receipt_id,
        'credential_rotated',false,
        'reason','canonical_readiness_revalidation'
      )
    );
  end if;

  return query select
    v_client.id,
    v_created,
    v_company.external_tenant_reference,
    v_receipt_id,
    case when v_created then 'credential_created' else 'client_ready' end;
end
$_$;

--
-- Name: FUNCTION gridex_provision_tenant_website_client_v1(p_company_id uuid, p_environment text, p_client_name text, p_key_prefix text, p_secret_hash text, p_scopes text[], p_allowed_origins text[], p_rate_limit_per_minute integer, p_actor_user_id uuid, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_provision_tenant_website_client_v1(p_company_id uuid, p_environment text, p_client_name text, p_key_prefix text, p_secret_hash text, p_scopes text[], p_allowed_origins text[], p_rate_limit_per_minute integer, p_actor_user_id uuid, p_idempotency_key text) IS 'Canonical tenant website go-live/revalidation v2. Safely adopts only canonical-readiness-paused primary clients; manual pause/revocation remains fail-closed.';

--
-- Name: gridex_public_catalog_dependency_revision_trigger_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_public_catalog_dependency_revision_trigger_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_row jsonb := case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_company_id uuid;
  v_entity_id text := v_row->>'id';
begin
  case tg_table_name
    when 'companies' then
      v_company_id := (v_row->>'id')::uuid;
    when 'tenant_contract_assignments' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_offers' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_products' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_product_versions' then
      select cp.company_id into v_company_id
      from public.contract_products cp
      where cp.id = nullif(v_row->>'contract_product_id','')::uuid;
    when 'legal_bundle_versions' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'legal_bundle_version_documents' then
      select lb.company_id into v_company_id
      from public.legal_bundle_versions lb
      where lb.id = nullif(v_row->>'legal_bundle_version_id','')::uuid;
    when 'tenant_legal_profiles' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_plans' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_plan_versions' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_books' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'integration_api_clients' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'portfolios' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'portfolio_monthly_settlements' then
      v_company_id := nullif(v_row->>'company_id','')::uuid;
    else
      v_company_id := null;
  end case;

  if v_company_id is not null then
    perform public.gridex_bump_contract_publication_revision(
      v_company_id,
      'website',
      tg_table_name || '.' || lower(tg_op),
      v_entity_id
    );
    perform public.gridex_bump_contract_publication_revision(
      v_company_id,
      'api',
      tg_table_name || '.' || lower(tg_op),
      v_entity_id
    );
  end if;

  if tg_op='DELETE' then return old; end if;
  return new;
end
$$;

--
-- Name: gridex_public_contract_offer_forward_link_sync(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_public_contract_offer_forward_link_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if current_setting('gridex.publication_link_repair',true)='on' then return new; end if;
  perform set_config('gridex.version_transition','on',true);
  perform set_config('gridex.publication_link_repair','on',true);
  if old.contract_publication_version_id is not null
     and old.contract_publication_version_id is distinct from new.contract_publication_version_id then
    update public.contract_publication_versions
    set legacy_public_contract_offer_id=null
    where id=old.contract_publication_version_id
      and legacy_public_contract_offer_id=old.id;
  end if;
  if new.contract_publication_version_id is not null then
    if not exists(
      select 1
      from public.contract_publication_versions cpv
      join public.contract_publications cp on cp.id=cpv.contract_publication_id
      join public.tenant_contract_assignments ta on ta.id=cp.assignment_id
      where cpv.id=new.contract_publication_version_id
        and ta.company_id=new.company_id
        and (new.contract_product_version_id is null or cpv.contract_product_version_id=new.contract_product_version_id)
    ) then
      raise exception using errcode='23514',message='public_offer_forward_publication_link_invalid';
    end if;
    update public.contract_publication_versions
    set legacy_public_contract_offer_id=new.id
    where id=new.contract_publication_version_id
      and legacy_public_contract_offer_id is distinct from new.id;
  end if;
  return new;
end $$;

--
-- Name: gridex_publication_compatibility_link_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publication_compatibility_link_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_company_id uuid;
  v_forward_id uuid;
begin
  if new.legacy_public_contract_offer_id is null then return new; end if;
  if current_setting('gridex.publication_link_repair',true)='on' then return new; end if;
  select po.company_id,po.contract_publication_version_id
    into v_company_id,v_forward_id
  from public.public_contract_offers po
  where po.id=new.legacy_public_contract_offer_id;
  if not found then
    raise exception using errcode='23503',message='legacy_public_contract_offer_not_found';
  end if;
  if v_forward_id is distinct from new.id then
    raise exception using errcode='23514',message='publication_version_link_mismatch';
  end if;
  if not exists(
    select 1
    from public.contract_publications cp
    join public.tenant_contract_assignments ta on ta.id=cp.assignment_id
    where cp.id=new.contract_publication_id and ta.company_id=v_company_id
  ) then
    raise exception using errcode='23514',message='publication_company_mismatch';
  end if;
  return new;
end $$;

--
-- Name: gridex_publication_legal_snapshot_json_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publication_legal_snapshot_json_v1(p_company_id uuid, p_legal_bundle_version_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'legal_bundle_version_id',bundle.id,
    'status',bundle.status,
    'content_sha256',bundle.content_sha256,
    'immutable',bundle.locked_at is not null,
    'module_versions',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',document.id,
        'legal_bundle_version_id',document.legal_bundle_version_id,
        'module_key',document.module_key,
        'title',document.title,
        'version',coalesce(nullif(document.template_version,''),
          bundle.published_at::text,document.created_at::text,document.id::text),
        'published_at',coalesce(bundle.published_at,document.created_at),
        'content_sha256',document.content_sha256,
        'origin',coalesce(nullif(document.origin,''),'canonical_bundle_document')
      ) order by document.sort_order,document.module_key,document.id
      ) from public.legal_bundle_version_documents document
      where document.legal_bundle_version_id=bundle.id
    ),'[]'::jsonb),
    'documents',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',document.id,
        'legal_bundle_version_id',document.legal_bundle_version_id,
        'module_key',document.module_key,
        'title',document.title,
        'version',coalesce(nullif(document.template_version,''),
          bundle.published_at::text,document.created_at::text,document.id::text),
        'published_at',coalesce(bundle.published_at,document.created_at),
        'content_sha256',document.content_sha256,
        'origin',coalesce(nullif(document.origin,''),'canonical_bundle_document')
      ) order by document.sort_order,document.module_key,document.id
      ) from public.legal_bundle_version_documents document
      where document.legal_bundle_version_id=bundle.id
    ),'[]'::jsonb)
  )
  from public.legal_bundle_versions bundle
  where bundle.id=p_legal_bundle_version_id
    and bundle.company_id=p_company_id
    and bundle.locked_at is not null
    and bundle.status in ('published','replaced','archived')
$$;

--
-- Name: gridex_publication_price_options_json_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publication_price_options_json_v1(p_publication_version_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $_$
  select coalesce(jsonb_agg(
    jsonb_strip_nulls(jsonb_build_object(
      'price_option_reference',o.option_reference,
      'option_code',o.option_code,
      'customer_name',o.customer_name,
      'price_type',o.contract_type,
      'contract_type',o.contract_type,
      'customer_type',o.customer_type,
      'resolution',coalesce(nullif(o.metadata->>'resolution',''),
        case o.contract_type
          when 'variable_hourly' then 'hourly'
          when 'variable_quarterly' then 'quarterly'
          else 'monthly'
        end),
      'is_default',o.is_default,
      'default',o.is_default,
      'selection_required',o.selection_required,
      'currency',coalesce(nullif(o.metadata->>'currency',''),'SEK'),
      'unit',coalesce(nullif(o.metadata->>'unit',''),'ore_per_kwh'),
      'fixed_price',case when coalesce(o.metadata->>'fixed_price','')
        ~ '^-?[0-9]+([.][0-9]+)?$'
        then (o.metadata->>'fixed_price')::numeric else null end,
      'markup',case when coalesce(o.metadata->>'markup','')
        ~ '^-?[0-9]+([.][0-9]+)?$'
        then (o.metadata->>'markup')::numeric else null end,
      'monthly_fee',case when coalesce(o.metadata->>'monthly_fee','')
        ~ '^-?[0-9]+([.][0-9]+)?$'
        then (o.metadata->>'monthly_fee')::numeric else null end,
      'binding_months',o.binding_months,
      'notice_months',o.notice_months,
      'auto_renew_enabled',o.auto_renew_enabled,
      'renewal_term_months',o.renewal_term_months,
      'valid_from',o.valid_from,
      'valid_to',o.valid_to,
      'earliest_start_date',o.earliest_start_date,
      'latest_start_date',o.latest_start_date,
      'area_prices',coalesce((
        select jsonb_agg(jsonb_build_object(
          'area_price_reference',a.price_row_reference,
          'price_area',a.price_area,
          'energy_price_ore_per_kwh',case when a.unit='sek_per_kwh'
            then a.amount*100 else a.amount end,
          'unit','ore_per_kwh',
          'valid_from',a.valid_from,
          'valid_to',a.valid_to
        ) order by a.price_area)
        from public.contract_price_option_area_prices a
        where a.contract_price_option_id=o.id and a.status='active'
      ),'[]'::jsonb)
    )) order by o.sort_order,o.option_reference
  ),'[]'::jsonb)
  from public.contract_price_options o
  where o.contract_publication_version_id=p_publication_version_id
    and o.status='active'
$_$;

--
-- Name: gridex_publish_contract_channel(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_contract_channel(p_company_id uuid, p_offer_id uuid, p_channel text, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $_$
declare
  o public.contract_offers%rowtype;
  v_readiness jsonb;
  v_assignment_id uuid;
  v_publication_id uuid;
  v_publication_version_id uuid;
  v_legal_version_id uuid;
  v_public_offer_id uuid;
  v_snapshot jsonb;
  v_hash text;
  v_offer_reference text;
  v_version integer;
  v_channel text;
  v_billing_model text;
  v_spot_weight numeric;
  v_portfolio_weight numeric;
  v_fixed_weight numeric;
  v_price_areas text[]:='{}'::text[];
begin
  v_channel:=lower(coalesce(p_channel,''));
  if v_channel not in ('internal','website','api','partner','phone') then
    return jsonb_build_object(
      'ok',false,'changed',false,'code','invalid_contract_channel','channel',v_channel,
      'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'invalid_contract_channel','channel',
        'Kanalen måste vara internal, website, api, partner eller phone.',to_jsonb(v_channel)
      ))
    );
  end if;
  perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.publish');
  perform public.gridex_assert_contract_permission(p_actor_user_id,'pricing.publish');

  select * into o from public.contract_offers
  where id=p_offer_id and company_id=p_company_id for update;
  if not found then
    return jsonb_build_object(
      'ok',false,'changed',false,'code','contract_offer_not_found',
      'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'contract_offer_not_found','contract_offer_id',
        'Avtalsversionen hittades inte för valt bolag.',to_jsonb(p_offer_id),
        'contract_offer',p_offer_id
      ))
    );
  end if;

  v_readiness:=public.gridex_validate_contract_readiness_v2(
    p_company_id,p_offer_id,
    case when o.lifecycle_status='paused' then 'resume_channel' else 'activate_channel' end,
    v_channel
  );
  if not coalesce((v_readiness->>'can_execute')::boolean,false) then
    return jsonb_build_object(
      'ok',false,'changed',false,'code','contract_channel_not_ready',
      'channel',v_channel,'lifecycle_status',o.lifecycle_status,
      'blockers',coalesce(v_readiness->'blockers','[]'::jsonb),
      'readiness',v_readiness
    );
  end if;
  if o.contract_product_version_id is null or not exists(
    select 1 from public.contract_product_versions pv
    where pv.id=o.contract_product_version_id and pv.status='approved' and pv.locked_at is not null
  ) then
    return jsonb_build_object(
      'ok',false,'changed',false,'code','contract_version_not_locked',
      'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'contract_version_not_locked','contract_product_version_id',
        'Canonical avtalsversion måste vara approved och låst före kanalaktivering.',
        to_jsonb(o.contract_product_version_id),'contract_product_version',o.contract_product_version_id
      ))
    );
  end if;

  if exists(
    select 1
    from public.tenant_contract_assignments ta
    join public.tenant_contract_channels ch on ch.assignment_id=ta.id
    join public.contract_publications cp on cp.assignment_id=ta.id and cp.channel=v_channel
    join public.contract_publication_versions cpv
      on cpv.contract_publication_id=cp.id
     and cpv.contract_product_version_id=o.contract_product_version_id
    where ta.company_id=p_company_id
      and ta.contract_product_version_id=o.contract_product_version_id
      and ta.status='active'
      and ch.channel=v_channel and ch.status='active'
      and cp.status='published' and cpv.status='published'
      and cardinality(public.gridex_validate_publication_graph_v1(cpv.id))=0
      and (ch.valid_from is null or ch.valid_from<=now())
      and (ch.valid_to is null or ch.valid_to>=now())
      and (
        v_channel<>'website'
        or exists(
          select 1 from public.public_contract_offers pco
          where pco.company_id=p_company_id
            and pco.contract_publication_version_id=cpv.id
            and pco.source_contract_offer_id=o.id
            and pco.lifecycle_status='published'
            and pco.publication_status='published'
            and pco.is_public and pco.website_enabled and pco.website_cta_enabled
        )
      )
  ) then
    return jsonb_build_object(
      'ok',true,'changed',false,'mode','published','code','contract_channel_already_active',
      'channel',v_channel,'contract_product_id',o.contract_product_id,
      'contract_product_version_id',o.contract_product_version_id,
      'blockers','[]'::jsonb
    );
  end if;

  perform public.gridex_sync_internal_offer_to_canonical(o.id);
  select * into o from public.contract_offers where id=o.id;

  -- The compatibility public-offer row is still consumed by parts of the
  -- website runtime. Derive its presentation fields from the same immutable
  -- commercial snapshot that is locked into the publication version.
  v_billing_model:=coalesce(nullif(o.commercial_snapshot->>'pricing_model',''),o.contract_type);
  v_spot_weight:=coalesce(
    case when coalesce(o.commercial_snapshot#>>'{portfolio_method,mix_shares,spot_weight_percent}','') ~ '^-?[0-9]+([.][0-9]+)?$'
      then (o.commercial_snapshot#>>'{portfolio_method,mix_shares,spot_weight_percent}')::numeric end,
    case when coalesce(o.commercial_snapshot->>'spot_weight_percent','') ~ '^-?[0-9]+([.][0-9]+)?$'
      then (o.commercial_snapshot->>'spot_weight_percent')::numeric end,
    100
  );
  v_portfolio_weight:=coalesce(
    case when coalesce(o.commercial_snapshot#>>'{portfolio_method,mix_shares,portfolio_weight_percent}','') ~ '^-?[0-9]+([.][0-9]+)?$'
      then (o.commercial_snapshot#>>'{portfolio_method,mix_shares,portfolio_weight_percent}')::numeric end,
    case when coalesce(o.commercial_snapshot->>'portfolio_weight_percent','') ~ '^-?[0-9]+([.][0-9]+)?$'
      then (o.commercial_snapshot->>'portfolio_weight_percent')::numeric end,
    0
  );
  v_fixed_weight:=coalesce(
    case when coalesce(o.commercial_snapshot#>>'{portfolio_method,mix_shares,fixed_weight_percent}','') ~ '^-?[0-9]+([.][0-9]+)?$'
      then (o.commercial_snapshot#>>'{portfolio_method,mix_shares,fixed_weight_percent}')::numeric end,
    case when coalesce(o.commercial_snapshot->>'fixed_weight_percent','') ~ '^-?[0-9]+([.][0-9]+)?$'
      then (o.commercial_snapshot->>'fixed_weight_percent')::numeric end,
    0
  );
  select coalesce(array_agg(distinct upper(btrim(area)) order by upper(btrim(area))),'{}'::text[])
  into v_price_areas
  from (
    select value as area
    from jsonb_array_elements_text(
      case when jsonb_typeof(o.commercial_snapshot->'price_areas')='array'
        then o.commercial_snapshot->'price_areas' else '[]'::jsonb end
    )
    where nullif(btrim(value),'') is not null
    union all
    select unnest(cpv.price_areas)
    from public.contract_product_versions cpv
    where cpv.id=o.contract_product_version_id
      and jsonb_array_length(
        case when jsonb_typeof(o.commercial_snapshot->'price_areas')='array'
          then o.commercial_snapshot->'price_areas' else '[]'::jsonb end
      )=0
  ) areas;

  -- Move only the selected channel from older versions in the same product
  -- series. Other channels stay active until separately switched.
  update public.tenant_contract_channels old_channel
  set status='ended',valid_to=coalesce(old_channel.valid_to,now()),updated_at=now()
  from public.tenant_contract_assignments old_assignment
  join public.contract_product_versions old_version on old_version.id=old_assignment.contract_product_version_id
  where old_channel.assignment_id=old_assignment.id
    and old_assignment.company_id=p_company_id
    and old_version.contract_product_id=o.contract_product_id
    and old_assignment.contract_product_version_id<>o.contract_product_version_id
    and old_channel.channel=v_channel
    and old_channel.status in ('active','paused');

  -- Locked publication versions may only move through an explicit lifecycle transition.
  perform set_config('gridex.version_transition','on',true);
  update public.contract_publication_versions old_publication_version
  set status='ended',valid_to=coalesce(old_publication_version.valid_to,now())
  from public.contract_publications old_publication
  join public.tenant_contract_assignments old_assignment on old_assignment.id=old_publication.assignment_id
  join public.contract_product_versions old_version on old_version.id=old_assignment.contract_product_version_id
  where old_publication_version.contract_publication_id=old_publication.id
    and old_assignment.company_id=p_company_id
    and old_version.contract_product_id=o.contract_product_id
    and old_assignment.contract_product_version_id<>o.contract_product_version_id
    and old_publication.channel=v_channel
    and old_publication_version.status='published';

  update public.contract_publications old_publication
  set status='ended',updated_at=now()
  from public.tenant_contract_assignments old_assignment
  join public.contract_product_versions old_version on old_version.id=old_assignment.contract_product_version_id
  where old_publication.assignment_id=old_assignment.id
    and old_assignment.company_id=p_company_id
    and old_version.contract_product_id=o.contract_product_id
    and old_assignment.contract_product_version_id<>o.contract_product_version_id
    and old_publication.channel=v_channel
    and old_publication.status not in ('ended','archived');

  update public.tenant_contract_assignments old_assignment
  set status=case when exists(
        select 1 from public.tenant_contract_channels remaining
        where remaining.assignment_id=old_assignment.id and remaining.status='active'
          and (remaining.valid_from is null or remaining.valid_from<=now())
          and (remaining.valid_to is null or remaining.valid_to>=now())
      ) then 'active' else 'ended' end,
      valid_to=case when exists(
        select 1 from public.tenant_contract_channels remaining
        where remaining.assignment_id=old_assignment.id and remaining.status='active'
          and (remaining.valid_from is null or remaining.valid_from<=now())
          and (remaining.valid_to is null or remaining.valid_to>=now())
      ) then old_assignment.valid_to else coalesce(old_assignment.valid_to,current_date) end,
      updated_at=now()
  from public.contract_product_versions old_version
  where old_version.id=old_assignment.contract_product_version_id
    and old_assignment.company_id=p_company_id
    and old_version.contract_product_id=o.contract_product_id
    and old_assignment.contract_product_version_id<>o.contract_product_version_id;

  update public.contract_offers old_offer
  set lifecycle_status=case when exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=old_offer.contract_product_version_id
          and ta.status='active' and ch.status='active'
          and (ch.valid_from is null or ch.valid_from<=now())
          and (ch.valid_to is null or ch.valid_to>=now())
      ) then 'published' else 'superseded' end,
      status=case when exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=old_offer.contract_product_version_id
          and ta.status='active' and ch.status='active'
      ) then 'active' else 'inactive' end,
      is_active=exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=old_offer.contract_product_version_id
          and ta.status='active' and ch.status='active'
      ),
      superseded_at=case when exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=old_offer.contract_product_version_id
          and ta.status='active' and ch.status='active'
      ) then old_offer.superseded_at else coalesce(old_offer.superseded_at,now()) end,
      updated_by=p_actor_user_id,updated_at=now()
  where old_offer.company_id=p_company_id
    and old_offer.contract_product_id=o.contract_product_id
    and old_offer.id<>o.id
    and old_offer.lifecycle_status not in ('archived','expired','closed');

  update public.contract_offers
  set lifecycle_status='published',status='active',is_active=true,
      superseded_at=null,updated_by=p_actor_user_id,updated_at=now()
  where id=o.id;
  update public.contract_products set status='active',updated_at=now()
  where id=o.contract_product_id and company_id=p_company_id;

  select id into v_assignment_id
  from public.tenant_contract_assignments
  where company_id=p_company_id and contract_product_version_id=o.contract_product_version_id
  for update;
  if v_assignment_id is null then
    raise exception using errcode='23514',
      message='PUBLICATION_TENANT_NOT_READY';
  end if;

  update public.tenant_contract_assignments
  set website_publication_allowed=website_publication_allowed or v_channel='website',
      internal_sales_allowed=internal_sales_allowed or v_channel='internal',
      status='active',valid_from=o.valid_from,valid_to=o.valid_to,updated_at=now()
  where id=v_assignment_id;

  insert into public.tenant_contract_channels(
    assignment_id,channel,status,valid_from,valid_to,marketing_content,updated_by
  ) values(
    v_assignment_id,v_channel,'active',o.valid_from::timestamptz,o.valid_to::timestamptz,
    jsonb_build_object('name',o.name,'source_contract_offer_id',o.id,'source_of_truth','contract_product_versions'),
    p_actor_user_id
  ) on conflict(assignment_id,channel) do update set
    status='active',valid_from=excluded.valid_from,valid_to=excluded.valid_to,
    marketing_content=excluded.marketing_content,updated_by=excluded.updated_by,updated_at=now();

  select legal_bundle_version_id into v_legal_version_id
  from public.contract_offers where id=o.id;
  if v_legal_version_id is null then
    raise exception using errcode='23514',
      message='PUBLICATION_LEGAL_BUNDLE_MISSING';
  end if;

  -- A publication root and version remain non-visible while the immutable
  -- child graph is materialized. The surrounding RPC transaction guarantees
  -- that no observer can see an intermediate state.
  insert into public.contract_publications(assignment_id,channel,status,created_by)
  values(v_assignment_id,v_channel,'draft',p_actor_user_id)
  on conflict(assignment_id,channel) do update set status='draft',updated_at=now()
  returning id into v_publication_id;

  select id,offer_reference
    into v_publication_version_id,v_offer_reference
  from public.contract_publication_versions
  where contract_publication_id=v_publication_id
    and contract_product_version_id=o.contract_product_version_id
    and channel=v_channel
    and publication_snapshot->>'source_contract_offer_id'=o.id::text
  order by version_number desc
  limit 1
  for update;

  if v_publication_version_id is null then
    select coalesce(max(version_number),0)+1 into v_version
    from public.contract_publication_versions
    where contract_publication_id=v_publication_id;
    v_offer_reference:=public.gridex_new_offer_reference(
      concat_ws('|',p_company_id::text,o.version_series_id::text,
        o.version_number::text,v_channel)
    );
    v_snapshot:=jsonb_build_object(
      'schema','gridex_contract_publication_v6',
      'company_id',p_company_id,
      'contract_product_id',o.contract_product_id,
      'contract_product_version_id',o.contract_product_version_id,
      'source_contract_offer_id',o.id,
      'channel',v_channel,
      'offer_reference',v_offer_reference,
      'commercial_snapshot',o.commercial_snapshot,
      'legal_bundle_version_id',v_legal_version_id,
      'price_options','[]'::jsonb,
      'valid_from',o.valid_from,
      'valid_to',o.valid_to
    );
    v_hash:=encode(extensions.digest(v_snapshot::text,'sha256'),'hex');
    insert into public.contract_publication_versions(
      contract_publication_id,version_number,contract_product_version_id,
      price_plan_id,price_plan_version_id,price_book_id,legal_bundle_version_id,
      customer_type,channel,valid_from,valid_to,publication_snapshot,
      offer_reference,content_sha256,status,published_at,locked_at,created_by
    ) values(
      v_publication_id,v_version,o.contract_product_version_id,
      o.price_plan_id,o.price_plan_version_id,o.price_book_id,v_legal_version_id,
      o.customer_type,v_channel,o.valid_from::timestamptz,o.valid_to::timestamptz,
      v_snapshot,v_offer_reference,v_hash,'draft',null,null,p_actor_user_id
    ) returning id into v_publication_version_id;
  else
    perform set_config('gridex.version_transition','on',true);
    update public.contract_publication_versions
    set status='draft',valid_from=o.valid_from::timestamptz,
        valid_to=o.valid_to::timestamptz
    where id=v_publication_version_id;
  end if;

  perform public.gridex_finalize_contract_publication_v1(
    v_publication_version_id,p_actor_user_id,true
  );
  select publication_snapshot,content_sha256,offer_reference
    into v_snapshot,v_hash,v_offer_reference
  from public.contract_publication_versions
  where id=v_publication_version_id;

  update public.contract_publications
  set status='published',updated_at=now()
  where id=v_publication_id;

  if v_channel='website' then
    perform set_config('gridex.public_offer_write','on',true);

    -- Only one website offer in a product series may be public. Older public
    -- compatibility rows remain for historic references but are immediately
    -- removed from all public/CTA surfaces.
    update public.public_contract_offers old_public
    set lifecycle_status='superseded',publication_status='unpublished',
        is_public=false,website_enabled=false,website_cta_enabled=false,
        updated_by=p_actor_user_id,updated_at=now()
    where old_public.company_id=p_company_id
      and old_public.contract_product_id=o.contract_product_id
      and old_public.source_contract_offer_id is distinct from o.id
      and (old_public.is_public or old_public.website_enabled or old_public.website_cta_enabled
           or old_public.publication_status='published');

    select id into v_public_offer_id
    from public.public_contract_offers
    where company_id=p_company_id and source_contract_offer_id=o.id
    order by created_at desc limit 1 for update;

    if v_public_offer_id is null then
      insert into public.public_contract_offers(
        company_id,source_contract_offer_id,version_series_id,version_number,
        contract_product_id,contract_product_version_id,contract_publication_version_id,
        legal_bundle_version_id,price_plan_id,price_plan_version_id,price_book_id,
        product_code,offer_code,public_name,public_description,contract_type,billing_model,
        customer_type,monthly_fee_sek,invoice_fee_sek,spot_markup_ore_per_kwh,
        variable_fee_ore_per_kwh,fixed_price_ore_per_kwh,green_fee_mode,green_fee_value,
        start_fee_sek,administration_fee_sek,break_fee_sek,discount_value,discount_unit,
        discount_months,vat_rate,terms_version,binding_months,notice_months,
        spot_weight_percent,portfolio_weight_percent,fixed_weight_percent,price_areas,
        automatic_renewal,power_of_attorney_required,valid_from,valid_to,
        is_public,is_archived,publication_status,lifecycle_status,website_enabled,
        website_cta_enabled,published_at,metadata,created_by,updated_by
      ) values(
        p_company_id,o.id,o.version_series_id,o.version_number,
        o.contract_product_id,o.contract_product_version_id,v_publication_version_id,
        v_legal_version_id,o.price_plan_id,o.price_plan_version_id,o.price_book_id,
        'electricity','contract-'||o.version_series_id::text,o.name,o.description,o.contract_type,
        v_billing_model,o.customer_type,
        o.monthly_fee_sek,o.invoice_fee_sek,o.spot_markup_ore_per_kwh,o.variable_fee_ore_per_kwh,
        o.fixed_price_ore_per_kwh,o.green_fee_mode,o.green_fee_value,o.start_fee_sek,o.admin_fee_sek,
        o.break_fee_sek,o.discount_value,o.discount_unit,o.discount_months,o.vat_rate,o.terms_version,
        o.default_binding_months,o.default_notice_months,
        v_spot_weight,v_portfolio_weight,v_fixed_weight,v_price_areas,
        o.automatic_renewal,o.power_of_attorney_required,o.valid_from,o.valid_to,
        true,false,'published','published',true,true,now(),
        jsonb_build_object('source_of_truth','contract_product_versions','offer_reference',v_offer_reference),
        p_actor_user_id,p_actor_user_id
      ) returning id into v_public_offer_id;
    else
      update public.public_contract_offers set
        contract_product_id=o.contract_product_id,
        contract_product_version_id=o.contract_product_version_id,
        contract_publication_version_id=v_publication_version_id,
        legal_bundle_version_id=v_legal_version_id,
        price_plan_id=o.price_plan_id,price_plan_version_id=o.price_plan_version_id,price_book_id=o.price_book_id,
        public_name=o.name,public_description=o.description,contract_type=o.contract_type,
        billing_model=v_billing_model,customer_type=o.customer_type,
        monthly_fee_sek=o.monthly_fee_sek,invoice_fee_sek=o.invoice_fee_sek,
        spot_markup_ore_per_kwh=o.spot_markup_ore_per_kwh,variable_fee_ore_per_kwh=o.variable_fee_ore_per_kwh,
        fixed_price_ore_per_kwh=o.fixed_price_ore_per_kwh,green_fee_mode=o.green_fee_mode,green_fee_value=o.green_fee_value,
        start_fee_sek=o.start_fee_sek,administration_fee_sek=o.admin_fee_sek,break_fee_sek=o.break_fee_sek,
        discount_value=o.discount_value,discount_unit=o.discount_unit,discount_months=o.discount_months,
        vat_rate=o.vat_rate,terms_version=o.terms_version,binding_months=o.default_binding_months,
        notice_months=o.default_notice_months,
        spot_weight_percent=v_spot_weight,portfolio_weight_percent=v_portfolio_weight,
        fixed_weight_percent=v_fixed_weight,price_areas=v_price_areas,
        automatic_renewal=o.automatic_renewal,
        power_of_attorney_required=o.power_of_attorney_required,valid_from=o.valid_from,valid_to=o.valid_to,
        is_public=true,is_archived=false,publication_status='published',lifecycle_status='published',
        website_enabled=true,website_cta_enabled=true,published_at=coalesce(published_at,now()),archived_at=null,
        metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('source_of_truth','contract_product_versions','offer_reference',v_offer_reference),
        updated_by=p_actor_user_id,updated_at=now()
      where id=v_public_offer_id;
    end if;
    update public.contract_publication_versions
    set legacy_public_contract_offer_id=v_public_offer_id
    where id=v_publication_version_id and legacy_public_contract_offer_id is null;
  end if;

  insert into public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata)
  values(
    p_company_id,p_actor_user_id,'contract_publication_version',v_publication_version_id::text,
    'contract.channel.published',null,v_snapshot,
    jsonb_build_object('offer_id',o.id,'channel',v_channel,'offer_reference',v_offer_reference)
  );

  return jsonb_build_object(
    'ok',true,'changed',true,'mode','published','channel',v_channel,
    'contract_product_id',o.contract_product_id,
    'contract_product_version_id',o.contract_product_version_id,
    'contract_publication_version_id',v_publication_version_id,
    'public_contract_offer_id',v_public_offer_id,
    'offer_reference',v_offer_reference,
    'affected_channels',1,
    'affected_publication_versions',1,
    'affected_public_offers',case when v_channel='website' then 1 else 0 end
  );
end $_$;

--
-- Name: FUNCTION gridex_publish_contract_channel(p_company_id uuid, p_offer_id uuid, p_channel text, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_publish_contract_channel(p_company_id uuid, p_offer_id uuid, p_channel text, p_actor_user_id uuid) IS 'Canonical channel publication RPC. Final valid_to-qualified source of truth after 20260727030000.';

--
-- Name: contract_publication_versions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.contract_publication_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contract_publication_id uuid NOT NULL,
    version_number integer NOT NULL,
    contract_product_version_id uuid NOT NULL,
    price_plan_id uuid,
    price_plan_version_id uuid,
    price_book_id uuid,
    legal_bundle_version_id uuid NOT NULL,
    legacy_public_contract_offer_id uuid,
    customer_type text NOT NULL,
    channel text NOT NULL,
    valid_from timestamp with time zone,
    valid_to timestamp with time zone,
    publication_snapshot jsonb DEFAULT '{}'::jsonb NOT NULL,
    offer_reference text,
    content_sha256 text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    published_at timestamp with time zone,
    locked_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    energy_direction text NOT NULL,
    CONSTRAINT contract_publication_versions_customer_type_check CHECK ((customer_type = ANY (ARRAY['private'::text, 'business'::text, 'both'::text]))),
    CONSTRAINT contract_publication_versions_energy_direction_check CHECK ((energy_direction = ANY (ARRAY['consumption'::text, 'production'::text]))),
    CONSTRAINT contract_publication_versions_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'review'::text, 'published'::text, 'paused'::text, 'ended'::text, 'archived'::text])))
);

--
-- Name: COLUMN contract_publication_versions.energy_direction; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.contract_publication_versions.energy_direction IS 'Immutable direction copied from the exact published product version.';

--
-- Name: gridex_publish_contract_publication_version(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_contract_publication_version(p_publication_version_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS public.contract_publication_versions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_row public.contract_publication_versions; v_blockers text[]; v_company uuid; v_product uuid;
begin
  select r.blockers,r.company_id,pv.contract_product_id into v_blockers,v_company,v_product
  from public.contract_publication_readiness_v r
  join public.contract_publication_versions x on x.id=r.contract_publication_version_id
  join public.contract_product_versions pv on pv.id=x.contract_product_version_id
  where r.contract_publication_version_id=p_publication_version_id;
  if not found then raise exception 'publication_version_not_found'; end if;
  if coalesce(array_length(v_blockers,1),0)>0 then raise exception 'publication_not_ready:%',array_to_string(v_blockers,','); end if;
  perform set_config('gridex.version_transition','on',true);
  update public.contract_publication_versions oldv set status='ended'
  from public.contract_product_versions oldpv
  where oldv.contract_product_version_id=oldpv.id and oldpv.contract_product_id=v_product and oldv.id<>p_publication_version_id and oldv.status='published';
  update public.tenant_contract_channels ch set status='ended',updated_at=now()
  from public.tenant_contract_assignments ta join public.contract_product_versions oldpv on oldpv.id=ta.contract_product_version_id
  where ch.assignment_id=ta.id and ta.company_id=v_company and oldpv.contract_product_id=v_product and ch.channel='website' and ch.status='active';
  update public.contract_publications p set status='ended',updated_at=now()
  from public.tenant_contract_assignments ta join public.contract_product_versions oldpv on oldpv.id=ta.contract_product_version_id
  where p.assignment_id=ta.id and ta.company_id=v_company and oldpv.contract_product_id=v_product and p.channel='website' and p.status='published';
  update public.contract_publication_versions cpv set status='published',published_at=coalesce(cpv.published_at,now()),locked_at=coalesce(cpv.locked_at,now()),offer_reference=coalesce(cpv.offer_reference,'offer_'||encode(gen_random_bytes(20),'hex'))
  where cpv.id=p_publication_version_id returning * into v_row;
  update public.contract_publications set status='published',updated_at=now() where id=v_row.contract_publication_id;
  update public.tenant_contract_channels ch set status='active',updated_at=now() from public.contract_publications p where p.id=v_row.contract_publication_id and ch.assignment_id=p.assignment_id and ch.channel='website';
  return v_row;
end $$;

--
-- Name: gridex_publish_contract_version(uuid, uuid, text, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_contract_version(p_company_id uuid, p_draft_contract_id uuid, p_offer_code text, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_result jsonb; v_publication_id uuid; v_readiness jsonb; v_message text; v_codes text[];
  v_payload jsonb:=coalesce(p_payload,'{}'::jsonb); v_legal_result jsonb:='{}'::jsonb;
  v_publish boolean; v_correlation_id text; v_audit_metadata jsonb;
  v_profile_status text; v_profile_missing_fields text[]; v_profile_review_required boolean;
  v_error_code text; v_user_message text;
  v_invoice_fee_raw text; v_invoice_fee numeric; v_invoice_fee_readiness jsonb;
begin
  begin
    if p_company_id is null or p_actor_user_id is null then raise exception using errcode='22023',message='company_and_actor_required'; end if;
    v_publish:=coalesce(v_payload->>'publication_status','draft')='published';
    v_correlation_id:=coalesce(nullif(v_payload#>>'{metadata,correlation_id}',''),gen_random_uuid()::text);

    v_invoice_fee_raw:=nullif(btrim(coalesce(v_payload->>'invoice_fee_sek','')),'');
    if v_invoice_fee_raw is not null then
      if replace(v_invoice_fee_raw,',','.') !~ '^[0-9]+([.][0-9]+)?$' then
        raise exception using errcode='23514',message='publication_not_ready:invoice_fee_missing';
      end if;
      v_invoice_fee:=replace(v_invoice_fee_raw,',','.')::numeric;
      if v_invoice_fee<0 then
        raise exception using errcode='23514',message='publication_not_ready:invoice_fee_missing';
      end if;
      v_payload:=jsonb_set(v_payload,'{invoice_fee_sek}',to_jsonb(v_invoice_fee),true);
    end if;
    if v_publish and v_invoice_fee is null then
      raise exception using errcode='23514',message='publication_not_ready:invoice_fee_missing';
    end if;
    v_invoice_fee_readiness:=public.gridex_invoice_fee_readiness(
      coalesce(p_pricing_snapshot,'{}'::jsonb),v_invoice_fee
    );
    if v_publish and coalesce(v_invoice_fee_readiness->>'status','blocked')<>'ready' then
      raise exception using errcode='23514',message='publication_not_ready:'||coalesce(v_invoice_fee_readiness->>'code','invoice_fee_missing');
    end if;

    if v_publish then
      select completeness_status,missing_fields,coalesce(review_required,false)
      into v_profile_status,v_profile_missing_fields,v_profile_review_required
      from public.tenant_legal_profiles where company_id=p_company_id;
      if not found then raise exception using errcode='23514',message='publication_not_ready:tenant_legal_profile_missing'; end if;
      if v_profile_status not in('complete','verified') or v_profile_review_required then
        v_codes:=array_remove(array[
          case when v_profile_status not in('complete','verified') then 'tenant_legal_profile_incomplete' end,
          case when v_profile_review_required then 'tenant_legal_profile_review_required' end
        ],null);
        select v_codes||coalesce(array_agg('missing_legal_profile_field:'||field order by field),'{}')
        into v_codes from unnest(coalesce(v_profile_missing_fields,'{}')) field;
        raise exception using errcode='23514',message='publication_not_ready:'||array_to_string(v_codes,',');
      end if;
    end if;

    v_payload:=jsonb_set(
      v_payload,'{metadata}',coalesce(v_payload->'metadata','{}'::jsonb)||jsonb_build_object(
        'correlation_id',v_correlation_id,
        'publication_command','gridex_publish_contract_version',
        'publication_command_version','2026-07-20.2',
        'legal_source','legal_template_versions'
      ),true
    )-'legal_bundle_id';

    if v_publish then
      v_legal_result:=public.gridex_resolve_or_create_legal_source_bundle(
        p_company_id,v_payload,coalesce(p_pricing_snapshot,'{}'::jsonb),p_actor_user_id
      );
    end if;

    v_result:=public.gridex_upsert_public_contract_offer(
      p_company_id,p_draft_contract_id,p_offer_code,v_payload,coalesce(p_pricing_snapshot,'{}'::jsonb),p_actor_user_id
    );
    v_publication_id:=nullif(v_result->>'contract_publication_version_id','')::uuid;

    if v_publication_id is not null then
      select jsonb_build_object(
        'status',readiness_status,'can_display',can_display,'can_accept_applications',can_accept_applications,
        'blockers',blockers,'display_blockers',display_blockers,'application_blockers',application_blockers,
        'legal_profile_missing_fields',legal_profile_missing_fields,'required_legal_modules',required_legal_modules,
        'included_legal_modules',included_legal_modules
      ) into v_readiness
      from public.contract_publication_readiness_v
      where contract_publication_version_id=v_publication_id;
    end if;

    if v_publish and exists(
      select 1
      from jsonb_array_elements_text(coalesce(v_readiness->'blockers','[]'::jsonb)) blocker
      where blocker in ('invoice_fee_missing','invoice_fee_conflict','invoice_fee_ambiguous')
    ) then
      select coalesce(array_agg(value order by value),'{}'::text[]) into v_codes
      from jsonb_array_elements_text(coalesce(v_readiness->'blockers','[]'::jsonb)) value
      where value in ('invoice_fee_missing','invoice_fee_conflict','invoice_fee_ambiguous');
      raise exception using errcode='23514',message='publication_not_ready:'||array_to_string(v_codes,',');
    end if;

    v_audit_metadata:=jsonb_strip_nulls(jsonb_build_object(
      'correlation_id',v_correlation_id,
      'offer_reference',v_result->>'offer_reference',
      'contract_publication_version_id',v_publication_id,
      'price_plan_id',v_result#>>'{pricing,price_plan_id}',
      'price_plan_version_id',v_result#>>'{pricing,price_plan_version_id}',
      'price_book_id',v_result#>>'{pricing,price_book_id}',
      'pricing_snapshot_sha256',v_result#>>'{pricing,content_sha256}',
      'legal_bundle_version_id',v_result#>>'{offer,legal_bundle_version_id}',
      'legal_source','legal_template_versions',
      'readiness',coalesce(v_readiness,'{}'::jsonb)
    ));

    insert into public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata)
    values(
      p_company_id,p_actor_user_id,'contract_publication_version',
      coalesce(v_publication_id::text,v_result#>>'{offer,id}',coalesce(p_draft_contract_id::text,'unknown')),
      case when v_publish then 'contract.publication.atomic_published' else 'contract.publication.atomic_draft_saved' end,
      null,v_result,v_audit_metadata
    );

    return coalesce(v_result,'{}'::jsonb)||jsonb_build_object(
      'ok',true,'readiness',coalesce(v_readiness,'{}'::jsonb),
      'correlation_id',v_correlation_id,'legal_source','legal_template_versions'
    );
  exception when others then
    v_message:=sqlerrm;
    v_correlation_id:=coalesce(v_correlation_id,gen_random_uuid()::text);
    if v_message like 'publication_not_ready:%' then
      v_error_code:='publication_not_ready'; v_user_message:='Avtalet kan inte publiceras ännu.';
      v_codes:=string_to_array(substring(v_message from length('publication_not_ready:')+1),',');
    elsif v_message like 'legal_requirement_rule_missing:%' then
      v_error_code:='legal_requirement_rule_missing'; v_user_message:='Juridikregler saknas för vald kund- eller avtalstyp.'; v_codes:=array[v_message];
    elsif v_message like 'canonical_legal_template_missing:%' then
      v_error_code:='canonical_legal_template_missing'; v_user_message:='Publicerade juridikmoduler saknas.';
      select coalesce(array_agg('missing_legal_module:'||module_key order by module_key),'{}') into v_codes
      from unnest(string_to_array(substring(v_message from length('canonical_legal_template_missing:')+1),',')) module_key;
    else
      raise;
    end if;

    insert into public.audit_logs(company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata)
    values(
      p_company_id,p_actor_user_id,'contract_publication_version',coalesce(p_draft_contract_id::text,'blocked'),
      'contract.publication.atomic_blocked',null,null,
      jsonb_build_object('correlation_id',v_correlation_id,'error_code',v_error_code,'blockers',v_codes,'database_message',v_message)
    );
    return jsonb_build_object('ok',false,'error_code',v_error_code,'message',v_user_message,'blockers',v_codes,'correlation_id',v_correlation_id);
  end;
end $_$;

--
-- Name: FUNCTION gridex_publish_contract_version(p_company_id uuid, p_draft_contract_id uuid, p_offer_code text, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_publish_contract_version(p_company_id uuid, p_draft_contract_id uuid, p_offer_code text, p_payload jsonb, p_pricing_snapshot jsonb, p_actor_user_id uuid) IS 'Canonical atomic contract publication command. Pricing, legal, contract version and publication either commit together or roll back together.';

--
-- Name: gridex_publish_internal_contract_version(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_internal_contract_version(p_company_id uuid, p_offer_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  o public.contract_offers%rowtype;
  v_readiness jsonb;
  v_pricing jsonb;
  v_canonical uuid;
begin
  perform public.gridex_assert_contract_permission(p_actor_user_id,'contracts.publish');
  perform public.gridex_assert_contract_permission(p_actor_user_id,'pricing.publish');

  select * into o
  from public.contract_offers
  where id=p_offer_id and company_id=p_company_id
  for update;
  if not found then
    return jsonb_build_object(
      'ok',false,'changed',false,'code','contract_offer_not_found',
      'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'contract_offer_not_found','contract_offer_id',
        'Avtalsversionen hittades inte för valt bolag.',to_jsonb(p_offer_id),
        'contract_offer',p_offer_id
      ))
    );
  end if;
  if o.lifecycle_status='published' then
    return jsonb_build_object(
      'ok',true,'changed',false,'mode','published','code','contract_already_published',
      'offer',to_jsonb(o),'blockers','[]'::jsonb
    );
  end if;
  if o.lifecycle_status not in ('draft','ready','paused') then
    return jsonb_build_object(
      'ok',false,'changed',false,'code','contract_version_not_publishable',
      'lifecycle_status',o.lifecycle_status,
      'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
        'lifecycle_status_not_publishable','lifecycle_status',
        'Endast draft, ready eller paused kan publiceras som en immutable avtalsversion.',
        to_jsonb(o.lifecycle_status),'contract_offer',o.id
      ))
    );
  end if;

  v_readiness:=public.gridex_validate_contract_readiness_v2(
    p_company_id,o.id,'publish_version',null
  );
  if not coalesce((v_readiness->>'can_execute')::boolean,false) then
    return jsonb_build_object(
      'ok',false,'changed',false,'code','contract_version_not_publishable',
      'lifecycle_status',o.lifecycle_status,
      'blockers',coalesce(v_readiness->'blockers','[]'::jsonb),
      'readiness',v_readiness
    );
  end if;

  -- Pricing promotion can write canonical pricing rows. Keep it inside a
  -- subtransaction so an identity mismatch returns a structured business
  -- result without leaving orphaned price versions or books behind.
  begin
    v_pricing:=public.gridex_create_or_version_contract_pricing(
      p_company_id,o.name,o.contract_type,
      coalesce(o.commercial_snapshot->>'pricing_model',o.contract_type),
      o.customer_type,coalesce(o.commercial_snapshot,'{}'::jsonb)-'lifecycle_status',
      o.valid_from,o.valid_to,true,p_actor_user_id
    );

    if (v_pricing->>'price_plan_version_id')::uuid is distinct from o.price_plan_version_id
       or nullif(v_pricing->>'price_book_id','')::uuid is distinct from o.price_book_id then
      raise exception using
        errcode='P0001',
        message='contract_pricing_identity_changed_during_publish';
    end if;
  exception
    when raise_exception then
      if sqlerrm='contract_pricing_identity_changed_during_publish' then
        return jsonb_build_object(
          'ok',false,'changed',false,'code','contract_pricing_identity_changed_during_publish',
          'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
            'contract_pricing_identity_changed_during_publish','price_plan_version_id',
            'Publicering försökte byta den immutable prisidentiteten. Skapa en ny avtalsversion i stället.',
            to_jsonb(o.price_plan_version_id),'contract_offer',o.id
          ))
        );
      end if;
      raise;
  end;

  begin
    update public.contract_offers
    set lifecycle_status='published',status='active',is_active=true,
        price_plan_id=(v_pricing->>'price_plan_id')::uuid,
        price_plan_version_id=(v_pricing->>'price_plan_version_id')::uuid,
        price_book_id=nullif(v_pricing->>'price_book_id','')::uuid,
        updated_by=p_actor_user_id,updated_at=now()
    where id=o.id
    returning * into o;

    v_canonical:=public.gridex_sync_internal_offer_to_canonical(o.id);
  exception
    when check_violation then
      if sqlerrm='internal_offer_legal_documents_not_ready' then
        return jsonb_build_object(
          'ok',false,'changed',false,'code','contract_version_not_publishable',
          'blockers',jsonb_build_array(public.gridex_contract_readiness_blocker_v2(
            'unresolved_legal_variables','legal_bundle_version_id',
            'Juridikmaterialiseringen innehåller olösta variabler.',null,
            'contract_offer',o.id
          )),
          'readiness',v_readiness
        );
      end if;
      raise;
  end;
  select * into o from public.contract_offers where id=o.id;

  update public.contract_offers predecessor
  set lifecycle_status=case when exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=predecessor.contract_product_version_id
          and ta.status='active' and ch.status='active'
          and (ch.valid_from is null or ch.valid_from<=now())
          and (ch.valid_to is null or ch.valid_to>=now())
      ) then 'published' else 'superseded' end,
      status=case when exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=predecessor.contract_product_version_id
          and ta.status='active' and ch.status='active'
          and (ch.valid_from is null or ch.valid_from<=now())
          and (ch.valid_to is null or ch.valid_to>=now())
      ) then 'active' else 'inactive' end,
      is_active=exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=predecessor.contract_product_version_id
          and ta.status='active' and ch.status='active'
          and (ch.valid_from is null or ch.valid_from<=now())
          and (ch.valid_to is null or ch.valid_to>= now())
      ),
      superseded_at=case when exists(
        select 1 from public.tenant_contract_assignments ta
        join public.tenant_contract_channels ch on ch.assignment_id=ta.id
        where ta.company_id=p_company_id
          and ta.contract_product_version_id=predecessor.contract_product_version_id
          and ta.status='active' and ch.status='active'
      ) then predecessor.superseded_at else coalesce(predecessor.superseded_at,now()) end,
      updated_by=p_actor_user_id,updated_at=now()
  where predecessor.company_id=p_company_id
    and predecessor.version_series_id=o.version_series_id
    and predecessor.id<>o.id
    and predecessor.lifecycle_status in ('published','paused','ready','draft');

  insert into public.audit_logs(
    company_id,actor_user_id,entity_type,entity_id,action,old_values,new_values,metadata
  ) values(
    p_company_id,p_actor_user_id,'contract_offer',o.id::text,
    'contract.version.published',null,to_jsonb(o),
    jsonb_build_object(
      'version_series_id',o.version_series_id,
      'contract_product_id',o.contract_product_id,
      'contract_product_version_id',v_canonical,
      'price_plan_version_id',o.price_plan_version_id,
      'price_book_id',o.price_book_id,
      'readiness',v_readiness
    )
  );

  return jsonb_build_object(
    'ok',true,'changed',true,'mode','published','code','contract_version_published',
    'offer',to_jsonb(o),
    'contract_product_id',o.contract_product_id,
    'contract_product_version_id',v_canonical,
    'price_plan_version_id',o.price_plan_version_id,
    'price_book_id',o.price_book_id,
    'readiness',v_readiness
  );
end $$;

