--
-- Name: gridex_publish_legal_template_version(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_legal_template_version(p_version_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.legal_template_versions
  set status='published',reviewed_by=p_actor_user_id,reviewed_at=now(),published_at=now(),locked_at=now()
  where id=p_version_id and status in('draft','review') and locked_at is null;
  if not found then
    if exists(select 1 from public.legal_template_versions where id=p_version_id and status='published' and locked_at is not null) then
      return p_version_id;
    end if;
    raise exception using errcode='55000',message='legal_template_version_not_publishable';
  end if;
  return p_version_id;
end $$;

--
-- Name: gridex_publish_market_price_preview(text, text, text, date, date, timestamp with time zone, numeric, timestamp with time zone, boolean, text, uuid[], text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_market_price_preview(p_provider text, p_price_area text, p_reference_period text, p_period_start date, p_period_end date, p_as_of timestamp with time zone, p_price_sek_per_kwh numeric, p_stale_after timestamp with time zone, p_fallback_used boolean DEFAULT false, p_fallback_reason text DEFAULT NULL::text, p_source_summary_ids uuid[] DEFAULT '{}'::uuid[], p_source_checksum text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  if coalesce(auth.role(),'')<>'service_role' then
    raise exception 'market_preview_publish_service_role_required' using errcode='42501';
  end if;
  if upper(coalesce(p_price_area,'')) not in ('SE1','SE2','SE3','SE4')
     or p_reference_period not in ('latest_complete_day','rolling_7_days','rolling_30_days','month_to_date','forecast')
     or p_period_end<p_period_start or p_as_of is null or p_stale_after<=p_as_of
     or p_price_sek_per_kwh is null then
    raise exception 'invalid_market_preview' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(lower(trim(p_provider))||':'||upper(trim(p_price_area))||':'||p_reference_period,0));
  update public.market_price_previews
  set status='superseded',updated_at=now()
  where provider=lower(trim(p_provider)) and price_area=upper(trim(p_price_area))
    and reference_period=p_reference_period and status='active';
  insert into public.market_price_previews(
    provider,price_area,reference_period,period_start,period_end,as_of,price_sek_per_kwh,
    stale_after,status,fallback_used,fallback_reason,source_summary_ids,source_checksum,metadata,updated_at
  ) values (
    lower(trim(p_provider)),upper(trim(p_price_area)),p_reference_period,p_period_start,p_period_end,p_as_of,p_price_sek_per_kwh,
    p_stale_after,'active',coalesce(p_fallback_used,false),nullif(btrim(p_fallback_reason),''),
    coalesce(p_source_summary_ids,'{}'::uuid[]),p_source_checksum,coalesce(p_metadata,'{}'::jsonb),now()
  ) returning id into v_id;
  return v_id;
end;
$$;

--
-- Name: gridex_publish_market_price_preview_v2(text, text, text, date, date, timestamp with time zone, timestamp with time zone, numeric, timestamp with time zone, integer, integer, boolean, text, uuid[], text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_market_price_preview_v2(p_provider text, p_price_area text, p_reference_period text, p_period_start date, p_period_end date, p_source_as_of timestamp with time zone, p_generated_at timestamp with time zone, p_price_sek_per_kwh numeric, p_stale_after timestamp with time zone, p_requested_days integer, p_included_days integer, p_fallback_used boolean DEFAULT false, p_fallback_reason text DEFAULT NULL::text, p_source_summary_ids uuid[] DEFAULT '{}'::uuid[], p_source_checksum text DEFAULT NULL::text, p_source_resolution text DEFAULT 'daily'::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_active public.market_price_previews%rowtype;
  v_id uuid;
  v_provider text := lower(trim(p_provider));
  v_area text := upper(trim(p_price_area));
  v_now timestamptz := now();
begin
  if coalesce(auth.role(),'') <> 'service_role' then
    raise exception 'market_preview_publish_service_role_required' using errcode='42501';
  end if;
  if v_area not in ('SE1','SE2','SE3','SE4')
     or p_reference_period not in ('latest_complete_day','rolling_7_days','rolling_30_days','month_to_date','forecast')
     or p_period_end < p_period_start
     or p_source_as_of is null
     or p_generated_at is null
     or p_stale_after <= p_generated_at
     or p_price_sek_per_kwh is null
     or p_requested_days is null or p_requested_days <= 0
     or p_included_days is null or p_included_days <= 0 or p_included_days > p_requested_days then
    raise exception 'invalid_market_preview' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_provider||':'||v_area||':'||p_reference_period,0)
  );

  select * into v_active
  from public.market_price_previews m
  where m.provider = v_provider
    and m.price_area = v_area
    and m.reference_period = p_reference_period
    and m.status = 'active'
  for update;

  if found
     and v_active.source_checksum is not distinct from p_source_checksum
     and v_active.source_as_of is not distinct from p_source_as_of
     and v_active.price_sek_per_kwh is not distinct from p_price_sek_per_kwh
     and v_active.period_start = p_period_start
     and v_active.period_end = p_period_end
     and v_active.requested_days is not distinct from p_requested_days
     and v_active.included_days is not distinct from p_included_days
     and v_active.fallback_used is not distinct from coalesce(p_fallback_used,false)
     and v_active.fallback_reason is not distinct from nullif(btrim(p_fallback_reason),'') then
    return jsonb_build_object(
      'created', false,
      'unchanged', true,
      'preview_id', v_active.id,
      'source_checksum', v_active.source_checksum
    );
  end if;

  update public.market_price_previews
  set status='superseded', updated_at=v_now
  where provider=v_provider
    and price_area=v_area
    and reference_period=p_reference_period
    and status='active';

  insert into public.market_price_previews(
    provider,price_area,reference_period,period_start,period_end,
    as_of,source_as_of,generated_at,price_sek_per_kwh,stale_after,
    requested_days,included_days,status,fallback_used,fallback_reason,
    source_summary_ids,source_checksum,source_resolution,metadata,updated_at
  ) values (
    v_provider,v_area,p_reference_period,p_period_start,p_period_end,
    p_source_as_of,p_source_as_of,p_generated_at,p_price_sek_per_kwh,p_stale_after,
    p_requested_days,p_included_days,'active',coalesce(p_fallback_used,false),
    nullif(btrim(p_fallback_reason),''),coalesce(p_source_summary_ids,'{}'::uuid[]),
    p_source_checksum,coalesce(nullif(btrim(p_source_resolution),''),'daily'),
    coalesce(p_metadata,'{}'::jsonb),v_now
  ) returning id into v_id;

  return jsonb_build_object(
    'created', true,
    'unchanged', false,
    'preview_id', v_id,
    'source_checksum', p_source_checksum
  );
end;
$$;

--
-- Name: FUNCTION gridex_publish_market_price_preview_v2(p_provider text, p_price_area text, p_reference_period text, p_period_start date, p_period_end date, p_source_as_of timestamp with time zone, p_generated_at timestamp with time zone, p_price_sek_per_kwh numeric, p_stale_after timestamp with time zone, p_requested_days integer, p_included_days integer, p_fallback_used boolean, p_fallback_reason text, p_source_summary_ids uuid[], p_source_checksum text, p_source_resolution text, p_metadata jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_publish_market_price_preview_v2(p_provider text, p_price_area text, p_reference_period text, p_period_start date, p_period_end date, p_source_as_of timestamp with time zone, p_generated_at timestamp with time zone, p_price_sek_per_kwh numeric, p_stale_after timestamp with time zone, p_requested_days integer, p_included_days integer, p_fallback_used boolean, p_fallback_reason text, p_source_summary_ids uuid[], p_source_checksum text, p_source_resolution text, p_metadata jsonb) IS 'Publishes a canonical market preview idempotently. An unchanged source checksum and unchanged provider evidence never receive artificial freshness. A new source_as_of requires a real provider fetch.';

--
-- Name: gridex_publish_tenant_legal_override(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_publish_tenant_legal_override(p_company_id uuid, p_override_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  update public.tenant_legal_overrides
  set status='published',submitted_at=coalesce(submitted_at,now()),reviewed_at=now(),reviewed_by=p_actor_user_id,locked_at=now()
  where id=p_override_id and company_id=p_company_id and status in('draft','submitted','approved') and locked_at is null;
  if not found then
    if exists(select 1 from public.tenant_legal_overrides where id=p_override_id and company_id=p_company_id and status='published' and locked_at is not null) then
      return p_override_id;
    end if;
    raise exception using errcode='55000',message='tenant_legal_override_not_publishable';
  end if;
  return p_override_id;
end $$;

--
-- Name: gridex_published_website_offer_integrity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_published_website_offer_integrity(p_company_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
with missing as (
  select cpv.id
  from public.contract_publication_versions cpv
  join public.contract_publications cp on cp.id=cpv.contract_publication_id
  join public.tenant_contract_assignments ta on ta.id=cp.assignment_id
  where ta.company_id=p_company_id
    and cpv.status='published'
    and cp.status='published'
    and cp.channel='website'
    and not exists(
      select 1
      from public.public_contract_offers pco
      where pco.company_id=p_company_id
        and pco.contract_publication_version_id=cpv.id
        and pco.lifecycle_status='published'
        and pco.publication_status='published'
        and pco.is_public=true
        and pco.website_enabled=true
        and pco.website_cta_enabled=true
    )
)
select jsonb_build_object(
  'ready', count(*)=0,
  'missing_count', count(*),
  'missing_publication_version_ids', coalesce(jsonb_agg(id) filter(where id is not null),'[]'::jsonb),
  'source','canonical_runtime_v2'
)
from missing;
$$;

--
-- Name: gridex_queue_billing_export_run(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_queue_billing_export_run(p_company_id uuid, p_export_run_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_run public.billing_export_runs%rowtype; v_item public.billing_export_run_items%rowtype;
v_partner public.partner_exports%rowtype; v_key text; v_queued integer:=0; v_skipped integer:=0; v_blocked integer:=0;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_company_id::text||':'||p_export_run_id::text||':queue',0));
  select * into v_run from public.billing_export_runs where id=p_export_run_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='billing_export_run_not_found'; end if;
  for v_item in select * from public.billing_export_run_items
    where company_id=p_company_id and billing_export_run_id=p_export_run_id order by created_at,id for update
  loop
    if v_item.status not in ('ready','ready_for_retry') then v_blocked:=v_blocked+1; continue; end if;
    if not exists(select 1 from public.billing_export_readiness_v r where r.company_id=p_company_id and r.billing_underlay_id=v_item.billing_underlay_id and r.is_exportable) then
      update public.billing_export_run_items set status='blocked',readiness_status='blocked',export_status='blocked',
        blocker_reasons=coalesce(blocker_reasons,'[]'::jsonb)||jsonb_build_array(jsonb_build_object('code','canonical_export_readiness_failed','severity','blocked')),
        last_error='Canonical exportreadiness blockerar raden.',failed_at=now(),updated_at=now() where id=v_item.id;
      v_blocked:=v_blocked+1; continue;
    end if;
    if v_item.customer_id is null then raise exception using errcode='23514',message='export_item_customer_required'; end if;
    if v_item.export_status in ('queued','sent','acknowledged') then v_skipped:=v_skipped+1; continue; end if;
    v_key:=coalesce(nullif(v_item.idempotency_key,''),'billing-export-run-item:'||v_item.id::text);
    if v_item.partner_export_id is not null then
      select * into v_partner from public.partner_exports
       where id=v_item.partner_export_id and company_id=p_company_id for update;
      if not found then
        select * into v_partner from public.partner_exports
         where company_id=p_company_id and idempotency_key=v_key for update;
      end if;
    else
      select * into v_partner from public.partner_exports
       where company_id=p_company_id and idempotency_key=v_key for update;
    end if;
    if not found then
      insert into public.partner_exports(company_id,customer_id,site_id,metering_point_id,billing_underlay_id,export_kind,target_system,status,
        payload,external_reference,export_batch_key,idempotency_key,adapter_key,payload_version,queued_at,created_by,updated_by)
      values(p_company_id,v_item.customer_id,v_item.site_id,v_item.metering_point_id,v_item.billing_underlay_id,'billing_underlay',v_run.target_system,'queued',
        jsonb_build_object('adapterPayload',v_item.adapter_payload_snapshot,'exportRunId',p_export_run_id,'exportRunItemId',v_item.id)||coalesce(v_item.payload_snapshot,'{}'::jsonb),
        coalesce(v_item.external_reference,'BILLING-'||upper(left(v_item.id::text,8))),p_export_run_id::text,v_key,
        coalesce(v_item.adapter_key,'gridex_billing_partner_v1'),coalesce(v_item.payload_version,'partner_export_v4c'),now(),p_actor_user_id,p_actor_user_id)
      returning * into v_partner;
    else
      update public.partner_exports set status='queued',
        payload=jsonb_build_object('adapterPayload',v_item.adapter_payload_snapshot,'exportRunId',p_export_run_id,'exportRunItemId',v_item.id)||coalesce(v_item.payload_snapshot,'{}'::jsonb),
        queued_at=now(),sent_at=null,failed_at=null,failure_reason=null,response_payload=null,
        updated_at=now(),updated_by=p_actor_user_id where id=v_partner.id returning * into v_partner;
    end if;
    update public.billing_export_run_items set export_status='queued',partner_result_type='none',partner_export_id=v_partner.id,idempotency_key=v_key,
      queued_at=now(),sent_at=null,failed_at=null,last_error=null,updated_at=now() where id=v_item.id;
    v_queued:=v_queued+1;
  end loop;
  perform public.gridex_refresh_billing_export_run(p_company_id,p_export_run_id);
  return jsonb_build_object('queued',v_queued,'skipped',v_skipped,'blocked',v_blocked);
end $$;

--
-- Name: gridex_read_webhook_signing_secret_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_read_webhook_signing_secret_v1(p_company_id uuid, p_subscription_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_secret text;
begin
  if auth.role() <> 'service_role' then
    raise exception using errcode='42501', message='partner_api_service_role_required';
  end if;

  select secret.decrypted_secret
  into v_secret
  from public.webhook_subscriptions subscription
  join vault.decrypted_secrets secret
    on secret.id::text = subscription.signing_secret_ref
  where subscription.id = p_subscription_id
    and subscription.company_id = p_company_id
    and subscription.status = 'active'
  limit 1;

  return v_secret;
end
$$;

--
-- Name: gridex_reaggregate_customer_after_legacy_state_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reaggregate_customer_after_legacy_state_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if pg_trigger_depth() < 2 then
    perform public.gridex_refresh_customer_process_summary(new.company_id,new.id,new.latest_customer_action);
  end if;
  return new;
end;
$$;

--
-- Name: gridex_rebuild_company_legal_profile(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_rebuild_company_legal_profile(p_company_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_mark_reviewed boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare
  v_company jsonb;
  v_defaults jsonb;
  v_existing public.tenant_legal_profiles%rowtype;
  v_profile public.tenant_legal_profiles%rowtype;
  v_changed boolean := true;
  v_now timestamptz := now();
begin
  if coalesce(p_mark_reviewed, false) then
    raise exception using errcode = '42501', message = 'direct_legal_review_not_allowed_use_gridex_review_company_legal_profile';
  end if;

  select to_jsonb(c) into v_company
  from public.companies c
  where c.id = p_company_id
  for update;
  if v_company is null then
    raise exception using errcode = 'P0002', message = 'company_not_found';
  end if;

  v_defaults := public.gridex_company_legal_profile_defaults(v_company);
  select * into v_existing
  from public.tenant_legal_profiles
  where company_id = p_company_id;
  if found then
    v_changed := v_existing.source_company_snapshot_sha256 is distinct from v_defaults->>'source_company_snapshot_sha256';
  end if;

  insert into public.tenant_legal_profiles(
    company_id, legal_name, organization_number, postal_address, customer_service_address,
    customer_service_email, phone, website, customer_service_contact, complaints_contact,
    data_protection_contact, billing_information, dispute_resolution_information,
    source_company_snapshot, source_company_snapshot_sha256, source_company_updated_at,
    review_required, last_synced_at, last_synced_by
  ) values (
    p_company_id, v_defaults->>'legal_name', v_defaults->>'organization_number', v_defaults->'postal_address', v_defaults->'customer_service_address',
    v_defaults->>'customer_service_email', v_defaults->>'phone', v_defaults->>'website', v_defaults->'customer_service_contact', v_defaults->'complaints_contact',
    v_defaults->'data_protection_contact', v_defaults->'billing_information', v_defaults->'dispute_resolution_information',
    v_defaults->'source_company_snapshot', v_defaults->>'source_company_snapshot_sha256', v_now,
    false, v_now, p_actor_user_id
  )
  on conflict (company_id) do update set
    legal_name = excluded.legal_name,
    organization_number = excluded.organization_number,
    postal_address = excluded.postal_address,
    customer_service_address = excluded.customer_service_address,
    customer_service_email = excluded.customer_service_email,
    phone = excluded.phone,
    website = excluded.website,
    customer_service_contact = excluded.customer_service_contact,
    complaints_contact = excluded.complaints_contact,
    data_protection_contact = excluded.data_protection_contact,
    billing_information = excluded.billing_information,
    dispute_resolution_information = excluded.dispute_resolution_information,
    source_company_snapshot = excluded.source_company_snapshot,
    source_company_snapshot_sha256 = excluded.source_company_snapshot_sha256,
    source_company_updated_at = v_now,
    last_synced_at = v_now,
    last_synced_by = p_actor_user_id;

  select * into v_profile
  from public.tenant_legal_profiles
  where company_id = p_company_id;

  if coalesce(array_length(v_profile.missing_fields, 1), 0) > 0 then
    update public.tenant_legal_profiles
    set review_required = false,
        reviewed_at = null,
        reviewed_by = null,
        verified_at = null,
        verified_by = null
    where company_id = p_company_id;
  elsif v_changed then
    update public.tenant_legal_profiles
    set review_required = true,
        reviewed_at = null,
        reviewed_by = null,
        verified_at = null,
        verified_by = null
    where company_id = p_company_id;
  end if;

  select * into v_profile
  from public.tenant_legal_profiles
  where company_id = p_company_id;

  if p_actor_user_id is not null and to_regclass('public.audit_logs') is not null then
    insert into public.audit_logs(
      actor_user_id, company_id, entity_type, entity_id, action, new_values, metadata
    ) values (
      p_actor_user_id,
      p_company_id,
      'tenant_legal_profile',
      p_company_id,
      'COMPANY_LEGAL_PROFILE_REBUILT',
      jsonb_build_object(
        'completeness_status', public.gridex_tenant_legal_profile_readiness_status(v_profile),
        'missing_fields', v_profile.missing_fields,
        'review_required', v_profile.review_required,
        'source_sha256', v_profile.source_company_snapshot_sha256
      ),
      jsonb_build_object('canonical_source', 'companies', 'atomic', true, 'review_operation', false)
    );
  end if;

  return jsonb_build_object(
    'company_id', p_company_id,
    'company_name', v_company->>'name',
    'completeness_status', public.gridex_tenant_legal_profile_readiness_status(v_profile),
    'missing_fields', v_profile.missing_fields,
    'missing_field_details', public.gridex_legal_missing_field_details(p_company_id, v_profile.missing_fields),
    'review_required', v_profile.review_required,
    'reviewed_at', coalesce(v_profile.reviewed_at, v_profile.verified_at),
    'updated_at', v_profile.updated_at
  );
end
$$;

--
-- Name: gridex_recalculate_actor_readiness(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_recalculate_actor_readiness(p_platform_market_actor_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_grid_updated int := 0;
  v_supplier_updated int := 0;
begin
  update public.grid_owners g
  set verified_for_customer_flow = coalesce(r.can_start_supplier_switch, false),
      supplier_switch_ready = coalesce(r.can_start_supplier_switch, false),
      prodat_ready_for_customer_flow = coalesce(r.can_use_for_prodat, false),
      utilts_ready_for_metering_flow = coalesce(r.can_use_for_utilts, false),
      excluded_from_electricity_scope = coalesce(r.electricity_scope_status = 'excluded_from_electricity_scope', false),
      electricity_scope_status = coalesce(r.electricity_scope_status, 'separate_role_scope'),
      manual_review_required = coalesce(r.manual_review_required, false),
      manual_review_reason = r.manual_review_reason,
      actor_registry_status = case
        when coalesce(r.can_start_supplier_switch, false) then 'verified'
        when r.electricity_scope_status = 'excluded_from_electricity_scope' then 'excluded_from_electricity_scope'
        else 'under_review'
      end,
      verification_status = case
        when r.electricity_scope_status = 'excluded_from_electricity_scope' then 'excluded_from_electricity_scope'
        when coalesce(r.can_start_supplier_switch, false) then 'verified'
        when 'open_blocking_conflicts' = any(r.blocking_reasons) then 'unresolved_duplicate'
        when 'missing_prodat_route' = any(r.blocking_reasons) then 'needs_route'
        when 'missing_or_invalid_certificate' = any(r.blocking_reasons) then 'needs_certificate'
        when 'unsafe_or_missing_subaddress' = any(r.blocking_reasons) then 'needs_subaddress'
        when 'missing_contact_path' = any(r.blocking_reasons) then 'needs_contact'
        when 'missing_ediel_id' = any(r.blocking_reasons) then 'needs_ediel_id'
        else 'unknown'
      end,
      verification_reasons = coalesce(r.blocking_reasons, '{}'::text[]),
      verification_checked_at = now(),
      verified_at = case when coalesce(r.can_start_supplier_switch, false) then coalesce(g.verified_at, now()) else g.verified_at end,
      verification_metadata = coalesce(g.verification_metadata, '{}'::jsonb) || jsonb_build_object(
        'o6_4_role_aware_readiness_at', now(),
        'electricity_scope_status', r.electricity_scope_status,
        'primary_role_group', r.primary_role_group,
        'manual_review_required', r.manual_review_required,
        'manual_review_reason', r.manual_review_reason
      ),
      updated_at = now()
  from public.actor_readiness_status r
  where g.platform_market_actor_id = r.platform_market_actor_id
    and (p_platform_market_actor_id is null or r.platform_market_actor_id = p_platform_market_actor_id);
  get diagnostics v_grid_updated = row_count;

  if to_regclass('public.electricity_suppliers') is not null then
    update public.electricity_suppliers s
    set verified_for_customer_flow = coalesce(r.can_use_for_prodat, false),
        can_start_supplier_switch = coalesce(r.can_use_for_prodat, false),
        actor_registry_status = case when coalesce(r.can_use_for_prodat, false) then 'verified' else 'under_review' end,
        verification_status = case when coalesce(r.can_use_for_prodat, false) then 'verified' else 'needs_review' end,
        verification_reasons = coalesce(r.blocking_reasons, '{}'::text[]),
        verification_checked_at = now(),
        verification_metadata = coalesce(s.verification_metadata, '{}'::jsonb) || jsonb_build_object('readiness_checked_at', now(), 'o6_4_scope', r.primary_role_group)
    from public.actor_readiness_status r
    where s.platform_market_actor_id = r.platform_market_actor_id
      and (p_platform_market_actor_id is null or r.platform_market_actor_id = p_platform_market_actor_id);
    get diagnostics v_supplier_updated = row_count;
  end if;

  return jsonb_build_object('ok', true, 'grid_owners_updated', v_grid_updated, 'suppliers_updated', v_supplier_updated, 'batch', 'O6.4');
end;
$$;

--
-- Name: gridex_reconcile_company_onboarding_tasks_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reconcile_company_onboarding_tasks_v1(p_company_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_contract jsonb := '{}'::jsonb;
  v_go_live jsonb := '{}'::jsonb;
  v_api boolean := false;
  v_prod_actor boolean := false;
  v_test_actor boolean := false;
  v_brp boolean := false;
  v_prod_route boolean := false;
  v_test_route boolean := false;
  v_transport boolean := false;
  v_prod_certificate boolean := false;
  v_legal boolean := false;
  v_website boolean := false;
  v_customer_automation boolean := false;
  v_complete_count integer := 0;
begin
  if not exists(select 1 from public.companies where id = p_company_id) then
    raise exception 'tenant_not_found';
  end if;

  perform public.gridex_seed_company_onboarding_tasks(p_company_id);

  v_contract := public.gridex_contract_platform_readiness_internal_v1(p_company_id);
  v_go_live := public.gridex_company_go_live_readiness(p_company_id);

  select exists(
    select 1
    from public.integration_api_clients i
    where i.company_id = p_company_id
      and i.status = 'active'
      and array[
        'integration_context.read',
        'website_contracts.read',
        'website_contracts.diagnostics',
        'website_energy_area.resolve',
        'website_quotes.write',
        'website_quotes.validate',
        'website_applications.write',
        'website_legal.read'
      ]::text[] <@ coalesce(i.scopes, '{}'::text[])
  ) into v_api;

  select exists(
    select 1 from public.ediel_actor_settings a
    where a.company_id = p_company_id
      and a.environment = 'production'
      and coalesce(a.is_active, false) = true
      and lower(coalesce(a.actor_role, a.role, '')) in ('supplier', 'electricity_supplier')
  ) into v_prod_actor;

  select exists(
    select 1 from public.ediel_actor_settings a
    where a.company_id = p_company_id
      and a.environment = 'test'
      and coalesce(a.is_active, false) = true
      and lower(coalesce(a.actor_role, a.role, '')) in ('supplier', 'electricity_supplier')
  ) into v_test_actor;

  select exists(
    select 1 from public.ediel_brp_settings b
    where b.company_id = p_company_id
      and b.environment = 'production'
      and coalesce(b.is_active, true) = true
      and nullif(btrim(coalesce(b.brp_ediel_id, '')), '') is not null
  ) into v_brp;

  select exists(
    select 1
    from public.ediel_route_profiles r
    join public.ediel_actor_settings a on a.id = r.actor_setting_id
    where r.company_id = p_company_id
      and r.environment = 'production'
      and a.company_id = p_company_id
      and a.environment = 'production'
      and coalesce(a.is_active, false) = true
      and lower(coalesce(a.actor_role, a.role, '')) in ('supplier', 'electricity_supplier')
      and coalesce(r.is_enabled, false) = true
      and coalesce(r.is_active, true) = true
      and upper(coalesce(r.message_family, '')) = 'PRODAT'
  ) into v_prod_route;

  select exists(
    select 1
    from public.ediel_route_profiles r
    join public.ediel_actor_settings a on a.id = r.actor_setting_id
    where r.company_id = p_company_id
      and r.environment = 'test'
      and a.company_id = p_company_id
      and a.environment = 'test'
      and coalesce(a.is_active, false) = true
      and lower(coalesce(a.actor_role, a.role, '')) in ('supplier', 'electricity_supplier')
      and coalesce(r.is_enabled, false) = true
      and coalesce(r.is_active, true) = true
  ) into v_test_route;

  select exists(
    select 1
    from public.ediel_route_profiles r
    join public.ediel_actor_settings a on a.id = r.actor_setting_id
    join public.ediel_mailboxes m on m.id = r.mailbox_id
    where r.company_id = p_company_id
      and a.company_id = p_company_id
      and coalesce(a.is_active, false) = true
      and lower(coalesce(a.actor_role, a.role, '')) in ('supplier', 'electricity_supplier')
      and coalesce(r.is_enabled, false) = true
      and coalesce(r.is_active, true) = true
      and coalesce(m.is_active, false) = true
      and m.environment = r.environment
      and (m.company_id = p_company_id or m.company_id is null)
  ) into v_transport;

  select exists(
    select 1
    from public.ediel_route_profiles r
    join public.ediel_actor_settings a on a.id = r.actor_setting_id
    where r.company_id = p_company_id
      and r.environment = 'production'
      and a.company_id = p_company_id
      and a.environment = 'production'
      and coalesce(a.is_active, false) = true
      and lower(coalesce(a.actor_role, a.role, '')) in ('supplier', 'electricity_supplier')
      and coalesce(r.is_enabled, false) = true
      and coalesce(r.is_active, true) = true
      and upper(coalesce(r.message_family, '')) = 'PRODAT'
      and (
        coalesce(r.certificate_required, false) = false
        or lower(coalesce(r.receiver_source, '')) in (
          'selected_metering_point_grid_owner',
          'selected_customer_site_grid_owner',
          'selected_supplier_switch_grid_owner',
          'selected_data_request_grid_owner',
          'original_inbound_sender',
          'original_inbound_receiver'
        )
        or r.receiver_certificate_id is not null
        or r.certificate_id is not null
      )
  ) into v_prod_certificate;

  v_legal :=
    coalesce(v_contract #>> '{legal_profile,status}', '') = 'ready'
    and coalesce(v_contract #>> '{documents,status}', '') = 'ready';

  v_website :=
    v_api
    and coalesce((v_contract #>> '{website,can_display}')::boolean, false)
    and coalesce((v_contract #>> '{applications,can_accept}')::boolean, false);

  v_customer_automation :=
    coalesce((v_contract #>> '{applications,can_accept}')::boolean, false)
    and coalesce(v_contract #>> '{customer_operations,status}', '') = 'ready';

  update public.company_onboarding_tasks
  set status = case when v_api then 'complete' else 'pending' end,
      blocker_reason = case when v_api then null else 'Aktiv API-klient med obligatoriska website_sales-scopes saknas.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'api_client_scopes';

  update public.company_onboarding_tasks
  set status = case when v_customer_automation then 'complete' else 'pending' end,
      blocker_reason = case when v_customer_automation then null else 'Ansöknings- eller kundoperationsflödet är inte ready.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'customer_automation_readiness';

  update public.company_onboarding_tasks
  set status = case when v_brp then 'complete' else 'pending' end,
      blocker_reason = case when v_brp then null else 'Aktiv production-BRP saknas.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'brp_settings';

  update public.company_onboarding_tasks
  set status = case when v_prod_certificate then 'complete' else 'pending' end,
      blocker_reason = case when v_prod_certificate then null else 'PRODAT-route saknar säker mottagar-/certifikatstrategi.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'production_certificate';

  update public.company_onboarding_tasks
  set status = case when v_prod_actor then 'complete' else 'pending' end,
      blocker_reason = case when v_prod_actor then null else 'Aktiv supplier-produktionsaktörsprofil saknas.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'production_ediel_actor_settings';

  update public.company_onboarding_tasks
  set status = case when v_test_actor then 'complete' else 'pending' end,
      blocker_reason = case when v_test_actor then null else 'Aktiv supplier-testaktörsprofil saknas.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'test_ediel_actor_settings';

  update public.company_onboarding_tasks
  set status = case when v_legal then 'complete' else 'pending' end,
      blocker_reason = case when v_legal then null else 'Juridisk profil eller dokumentflöde är inte ready.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'legal_default_package';

  update public.company_onboarding_tasks
  set status = case when v_prod_route then 'complete' else 'pending' end,
      blocker_reason = case when v_prod_route then null else 'Supplier-bunden PRODAT-produktionsroute saknas.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'production_route_readiness';

  update public.company_onboarding_tasks
  set status = case when v_test_route then 'complete' else 'pending' end,
      blocker_reason = case when v_test_route then null else 'Supplier-bunden test-route saknas.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'test_route_readiness';

  update public.company_onboarding_tasks
  set status = case when v_transport then 'complete' else 'pending' end,
      blocker_reason = case when v_transport then null else 'Aktiv route saknar tenant- eller shared-mailboxtransport.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'shared_mailbox_transport';

  update public.company_onboarding_tasks
  set status = case when v_website then 'complete' else 'pending' end,
      blocker_reason = case when v_website then null else 'Webb/API-kontraktflödet är inte komplett.' end,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('source', 'canonical_runtime_v2', 'reconciled_at', now())
  where company_id = p_company_id and task_key = 'website_portal_integration';

  select count(*)
  into v_complete_count
  from public.company_onboarding_tasks
  where company_id = p_company_id and status = 'complete';

  return jsonb_build_object(
    'company_id', p_company_id,
    'complete_count', v_complete_count,
    'total_count', (select count(*) from public.company_onboarding_tasks where company_id = p_company_id),
    'go_live', v_go_live,
    'source', 'canonical_runtime_v2',
    'reconciled_at', now()
  );
end;
$$;

--
-- Name: gridex_reconcile_grid_owner_mappings_v1(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reconcile_grid_owner_mappings_v1(p_apply boolean DEFAULT false) RETURNS TABLE(platform_grid_owner_id uuid, status text, candidate_ops_grid_owner_id uuid, match_method text, candidate_count integer, details jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
with
unmapped as (
  select pgo.id, pgo.name, pgo.org_number, pgo.ediel_id, pgo.market_actor_id, pgo.metadata
  from public.platform_grid_owners pgo
  where pgo.ops_grid_owner_id is null
    and coalesce(pgo.is_active, true)
),
verified_actors as (
  select a.id
  from public.platform_market_actors a
  where a.match_status = 'verified'
),
verified_identifiers as (
  select
    i.actor_id,
    lower(regexp_replace(btrim(i.identifier_type), '[^a-z0-9]+', '', 'g')) as identifier_type_normalized,
    i.identifier_value
  from public.platform_actor_identifiers i
  where i.is_verified = true
    and (i.valid_from is null or i.valid_from <= current_date)
    and (i.valid_to is null or i.valid_to >= current_date)
),
candidates as (
  select u.id as platform_grid_owner_id, g.id as ops_grid_owner_id, 1 as priority,
         'verified_ediel_id'::text as match_method
  from unmapped u
  join verified_actors va on va.id = u.market_actor_id
  join verified_identifiers i
    on i.actor_id = u.market_actor_id
   and i.identifier_type_normalized = 'edielid'
  join public.grid_owners g
    on nullif(lower(btrim(g.ediel_id)), '') = nullif(lower(btrim(i.identifier_value)), '')
   and coalesce(g.is_active, true)
  where nullif(lower(btrim(u.ediel_id)), '') = nullif(lower(btrim(i.identifier_value)), '')

  union all

  select u.id, g.id, 2, 'verified_organization_number'::text
  from unmapped u
  join verified_actors va on va.id = u.market_actor_id
  join verified_identifiers i
    on i.actor_id = u.market_actor_id
   and i.identifier_type_normalized in ('orgno', 'orgnumber', 'orgnr', 'organizationnumber')
  join public.grid_owners g
    on nullif(regexp_replace(coalesce(g.org_number, g.organization_number, ''), '[^0-9]', '', 'g'), '')
       = nullif(regexp_replace(coalesce(i.identifier_value, ''), '[^0-9]', '', 'g'), '')
   and coalesce(g.is_active, true)
  where nullif(regexp_replace(coalesce(u.org_number, ''), '[^0-9]', '', 'g'), '')
        = nullif(regexp_replace(coalesce(i.identifier_value, ''), '[^0-9]', '', 'g'), '')

  union all

  select u.id, g.id, 3, 'verified_actor_identity'::text
  from unmapped u
  join verified_actors va on va.id = u.market_actor_id
  join public.grid_owners g
    on g.platform_market_actor_id = u.market_actor_id
   and coalesce(g.is_active, true)

  union all

  select u.id, g.id, 4, 'verified_exact_alias'::text
  from unmapped u
  join public.platform_actor_aliases aa
    on aa.actor_id = u.market_actor_id
   and aa.is_verified = true
  join public.grid_owners g
    on g.platform_market_actor_id = aa.actor_id
   and coalesce(g.is_active, true)
  where nullif(regexp_replace(lower(coalesce(aa.normalized_alias, aa.alias, '')), '[^a-z0-9åäö]+', '', 'g'), '')
        = nullif(regexp_replace(lower(coalesce(u.name, '')), '[^a-z0-9åäö]+', '', 'g'), '')

  union all

  select u.id, g.id, 5, 'verified_existing_relation'::text
  from unmapped u
  join public.grid_owners g
    on g.platform_grid_owner_id = u.id
   and g.verification_status = 'verified'
   and coalesce(g.manual_review_required, false) = false
   and coalesce(g.is_active, true)
),
best_priority as (
  select c.platform_grid_owner_id, min(c.priority) as priority
  from candidates c
  group by c.platform_grid_owner_id
),
best_candidates as (
  select c.platform_grid_owner_id, c.ops_grid_owner_id, c.priority, c.match_method
  from candidates c
  join best_priority b
    on b.platform_grid_owner_id = c.platform_grid_owner_id
   and b.priority = c.priority
),
classified as (
  select
    u.id as platform_grid_owner_id,
    count(distinct b.ops_grid_owner_id)::integer as candidate_count,
    case when count(distinct b.ops_grid_owner_id) = 1
      then min(b.ops_grid_owner_id::text)::uuid else null::uuid end as candidate_ops_grid_owner_id,
    min(b.match_method) as match_method,
    min(b.priority) as match_priority
  from unmapped u
  left join best_candidates b on b.platform_grid_owner_id = u.id
  group by u.id
),
target_counts as (
  select c.candidate_ops_grid_owner_id, count(*)::integer as target_count
  from classified c
  where c.candidate_count = 1 and c.candidate_ops_grid_owner_id is not null
  group by c.candidate_ops_grid_owner_id
),
guarded as (
  select
    c.*,
    coalesce(tc.target_count, 0)::integer as target_count,
    exists (
      select 1 from public.platform_grid_owners occupied
      where occupied.ops_grid_owner_id = c.candidate_ops_grid_owner_id
        and occupied.id <> c.platform_grid_owner_id
    ) as target_already_mapped
  from classified c
  left join target_counts tc on tc.candidate_ops_grid_owner_id = c.candidate_ops_grid_owner_id
),
applied as (
  update public.platform_grid_owners pgo
     set ops_grid_owner_id = c.candidate_ops_grid_owner_id,
         metadata = jsonb_set(
           coalesce(pgo.metadata, '{}'::jsonb),
           '{ops_reconciliation}',
           jsonb_build_object(
             'engine', 'gridex_reconcile_grid_owner_mappings_v1',
             'engine_version', 3,
             'match_method', c.match_method,
             'match_priority', c.match_priority,
             'confidence', 'deterministic',
             'verified', true,
             'ops_grid_owner_id', c.candidate_ops_grid_owner_id,
             'reconciled_at', now()
           ), true
         ),
         updated_at = now()
  from guarded c
  where p_apply
    and c.candidate_count = 1
    and c.candidate_ops_grid_owner_id is not null
    and c.target_count = 1
    and not c.target_already_mapped
    and pgo.id = c.platform_grid_owner_id
    and pgo.ops_grid_owner_id is null
  returning pgo.id
)
select
  c.platform_grid_owner_id,
  case
    when a.id is not null then 'mapped'
    when c.candidate_count > 1 or c.target_count > 1 or c.target_already_mapped then 'ambiguous'
    when c.candidate_count = 1 and not p_apply then 'would_map'
    else 'review_required'
  end as status,
  c.candidate_ops_grid_owner_id,
  c.match_method,
  c.candidate_count,
  jsonb_build_object(
    'engine_version', 3,
    'apply_requested', p_apply,
    'match_priority', c.match_priority,
    'deterministic', c.candidate_count = 1 and c.target_count = 1 and not c.target_already_mapped,
    'target_candidate_count', c.target_count,
    'target_already_mapped', c.target_already_mapped,
    'identifier_type_normalized', true,
    'fuzzy_write_allowed', false
  ) as details
from guarded c
left join applied a on a.id = c.platform_grid_owner_id
order by c.platform_grid_owner_id;
$$;

--
-- Name: FUNCTION gridex_reconcile_grid_owner_mappings_v1(p_apply boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_reconcile_grid_owner_mappings_v1(p_apply boolean) IS 'Deterministic Gridex OPS grid-owner reconciliation v3. Normalizes verified identifier types (Ediel and organization-number variants), preserves one-to-one target guards, and never performs fuzzy writes.';

--
-- Name: gridex_record_application_provisioning_step(uuid, uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_record_application_provisioning_step(p_company_id uuid, p_customer_application_id uuid, p_operation_id uuid, p_step text, p_status text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into public.customer_application_provisioning_steps (
    company_id, customer_application_id, operation_id, step, status, payload
  ) values (
    p_company_id, p_customer_application_id, p_operation_id, p_step, p_status, coalesce(p_payload, '{}'::jsonb)
  )
  on conflict (company_id, customer_application_id, operation_id, step)
  do update set
    status = excluded.status,
    payload = public.customer_application_provisioning_steps.payload || excluded.payload,
    updated_at = now();
end;
$$;

--
-- Name: gridex_record_contract_backfill_issue(uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_record_contract_backfill_issue(p_company_id uuid, p_contract_offer_id uuid, p_public_contract_offer_id uuid, p_issue_code text, p_issue_detail jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  insert into public.contract_lifecycle_backfill_issues(
    company_id,contract_offer_id,public_contract_offer_id,issue_code,issue_detail,status,last_seen_at
  ) values(
    p_company_id,p_contract_offer_id,p_public_contract_offer_id,p_issue_code,coalesce(p_issue_detail,'{}'::jsonb),'open',now()
  )
  on conflict(
    issue_code,
    (coalesce(contract_offer_id,'00000000-0000-0000-0000-000000000000'::uuid)),
    (coalesce(public_contract_offer_id,'00000000-0000-0000-0000-000000000000'::uuid))
  ) do update set
    company_id=excluded.company_id,
    issue_detail=excluded.issue_detail,
    status='open',last_seen_at=now(),resolved_at=null;
end $$;

--
-- Name: gridex_record_customer_contract_event_v1(uuid, uuid, uuid, text, timestamp with time zone, text, jsonb, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_record_customer_contract_event_v1(p_company_id uuid, p_customer_contract_id uuid, p_customer_id uuid, p_event_type text, p_happened_at timestamp with time zone DEFAULT now(), p_note text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_derived_ends_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_contract public.customer_contracts%rowtype;
  v_event public.customer_contract_events%rowtype;
  v_previous_status text;
  v_new_status text;
  v_domain_event_id uuid;
  v_idempotency_key text := coalesce(
    nullif(btrim(p_idempotency_key), ''),
    encode(digest(
      concat_ws(
        ':',
        p_company_id,
        p_customer_contract_id,
        p_event_type,
        p_happened_at,
        coalesce(p_note, '')
      ),
      'sha256'
    ), 'hex')
  );
begin
  if auth.role() <> 'service_role' then
    raise exception using
      errcode = '42501',
      message = 'customer_contract_event_service_role_required';
  end if;
  if p_company_id is null
     or p_customer_contract_id is null
     or p_customer_id is null
     or p_event_type not in (
       'created', 'signature_requested', 'signature_failed',
       'signature_retry_requested', 'signed', 'activated', 'updated',
       'termination_notice_received', 'terminated', 'cancelled', 'note'
     ) then
    raise exception using
      errcode = '22023',
      message = 'customer_contract_event_payload_invalid';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_company_id::text || ':' || p_customer_contract_id::text, 0)
  );
  select *
  into v_contract
  from public.customer_contracts contract
  where contract.id = p_customer_contract_id
    and contract.company_id = p_company_id
    and contract.customer_id = p_customer_id
  for update;
  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'customer_contract_not_found_for_tenant';
  end if;

  select *
  into v_event
  from public.customer_contract_events event
  where event.company_id = p_company_id
    and event.customer_contract_id = p_customer_contract_id
    and event.metadata->>'idempotency_key' = v_idempotency_key
  order by event.created_at
  limit 1;
  if found then
    return jsonb_build_object(
      'event', to_jsonb(v_event),
      'contract_status', v_contract.status,
      'existing', true
    );
  end if;

  v_previous_status := v_contract.status;
  v_new_status := v_contract.status;

  if p_event_type = 'signature_failed' then
    if v_contract.status <> 'pending_signature' then
      raise exception using
        errcode = '23514',
        message = 'signature_failure_requires_pending_signature';
    end if;
    v_new_status := 'signature_failed';
    update public.customer_contracts contract
    set status = v_new_status,
        lifecycle_stage = 'agreement_ready',
        metadata = coalesce(contract.metadata, '{}'::jsonb)
          || coalesce(p_metadata, '{}'::jsonb)
          || jsonb_build_object(
            'signature_status', 'failed',
            'signature_failed_at', p_happened_at,
            'recoverable_by_new_signature_attempt', true
          ),
        updated_by = p_actor_user_id,
        updated_at = now()
    where contract.id = p_customer_contract_id
      and contract.company_id = p_company_id;
  elsif p_event_type = 'signature_retry_requested' then
    if v_contract.status <> 'signature_failed' then
      raise exception using
        errcode = '23514',
        message = 'signature_retry_requires_signature_failed';
    end if;
    v_new_status := 'pending_signature';
    update public.customer_contracts contract
    set status = v_new_status,
        metadata = coalesce(contract.metadata, '{}'::jsonb)
          || coalesce(p_metadata, '{}'::jsonb)
          || jsonb_build_object(
            'signature_status', 'pending',
            'signature_retry_requested_at', p_happened_at,
            'recoverable_by_new_signature_attempt', false
          ),
        updated_by = p_actor_user_id,
        updated_at = now()
    where contract.id = p_customer_contract_id
      and contract.company_id = p_company_id;
  elsif p_event_type = 'signed' then
    -- Only the canonical signature finalizer may transition a contract to
    -- signed. This event merely records that already-committed evidence.
    if v_contract.status <> 'signed'
       or v_contract.signed_at is null
       or v_contract.locked_at is null
       or nullif(v_contract.signature_snapshot_sha256, '') is null
       or v_contract.contract_publication_version_id is null
       or v_contract.contract_product_version_id is null
       or v_contract.legal_bundle_version_id is null
       or v_contract.contract_price_snapshot_id is null then
      raise exception using
        errcode = '23514',
        message = 'signed_event_requires_canonical_signature_evidence';
    end if;
  elsif p_event_type = 'activated' then
    -- Supply activation is a larger atomic graph and must use its dedicated
    -- command, which also writes the supply period and switch confirmation.
    raise exception using
      errcode = '23514',
      message = 'use_gridex_activate_customer_supply_v1';
  elsif p_event_type in ('terminated', 'cancelled') then
    v_new_status := case
      when p_event_type = 'terminated' then 'terminated'
      else 'cancelled'
    end;
    update public.customer_contracts
    set status = v_new_status,
        ended_at = coalesce(
          nullif(p_metadata->>'ended_at', '')::timestamptz,
          nullif(p_metadata->>'ends_at', '')::timestamptz,
          p_happened_at,
          ended_at
        ),
        termination_notice_date = coalesce(
          nullif(p_metadata->>'termination_notice_date', '')::timestamptz,
          termination_notice_date
        ),
        termination_reason = coalesce(
          nullif(p_metadata->>'termination_reason', ''),
          termination_reason
        ),
        withdrawal_requested_at = coalesce(
          nullif(p_metadata->>'withdrawal_requested_at', '')::timestamptz,
          withdrawal_requested_at
        ),
        rejected_reason = coalesce(
          nullif(p_metadata->>'rejected_reason', ''),
          rejected_reason
        ),
        status_reason_code = coalesce(
          nullif(p_metadata->>'reason_code', ''),
          status_reason_code,
          p_event_type
        ),
        metadata = coalesce(metadata, '{}'::jsonb)
          || jsonb_build_object(
            'status_reason_code',
            nullif(p_metadata->>'reason_code', '')
          ),
        updated_by = p_actor_user_id,
        updated_at = now()
    where id = p_customer_contract_id
      and company_id = p_company_id;
  elsif p_event_type = 'termination_notice_received' then
    update public.customer_contracts
    set termination_notice_date = p_happened_at,
        ended_at = coalesce(p_derived_ends_at, ended_at),
        updated_by = p_actor_user_id,
        updated_at = now()
    where id = p_customer_contract_id
      and company_id = p_company_id;
  end if;

  insert into public.customer_contract_events(
    company_id,
    customer_contract_id,
    customer_id,
    event_type,
    happened_at,
    note,
    metadata,
    actor_user_id
  ) values (
    p_company_id,
    p_customer_contract_id,
    p_customer_id,
    p_event_type,
    p_happened_at,
    p_note,
    coalesce(p_metadata, '{}'::jsonb)
      || jsonb_build_object('idempotency_key', v_idempotency_key),
    p_actor_user_id
  )
  returning * into v_event;

  insert into public.domain_events(
    company_id,
    event_type,
    aggregate_type,
    aggregate_id,
    actor_user_id,
    source,
    idempotency_key,
    payload
  ) values (
    p_company_id,
    'contract.event.recorded',
    'customer_contract',
    p_customer_contract_id,
    p_actor_user_id,
    'gridex_record_customer_contract_event_v1',
    'customer-contract-event:' || v_idempotency_key,
    jsonb_build_object(
      'customer_contract_event_id', v_event.id,
      'customer_id', p_customer_id,
      'event_type', p_event_type,
      'previous_status', v_previous_status,
      'new_status', v_new_status
    )
  )
  on conflict do nothing
  returning id into v_domain_event_id;

  if v_domain_event_id is not null then
    insert into public.event_outbox(
      company_id,
      domain_event_id,
      destination_type,
      destination_key,
      payload
    ) values (
      p_company_id,
      v_domain_event_id,
      'webhook',
      'contract.event.recorded',
      jsonb_build_object(
        'domain_event_id', v_domain_event_id,
        'customer_contract_id', p_customer_contract_id,
        'event_type', p_event_type
      )
    ) on conflict do nothing;
  end if;

  return jsonb_build_object(
    'event', to_jsonb(v_event),
    'contract_status', v_new_status,
    'existing', false
  );
end
$$;

--
-- Name: FUNCTION gridex_record_customer_contract_event_v1(p_company_id uuid, p_customer_contract_id uuid, p_customer_id uuid, p_event_type text, p_happened_at timestamp with time zone, p_note text, p_metadata jsonb, p_actor_user_id uuid, p_derived_ends_at timestamp with time zone, p_idempotency_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gridex_record_customer_contract_event_v1(p_company_id uuid, p_customer_contract_id uuid, p_customer_id uuid, p_event_type text, p_happened_at timestamp with time zone, p_note text, p_metadata jsonb, p_actor_user_id uuid, p_derived_ends_at timestamp with time zone, p_idempotency_key text) IS 'Atomic, tenant-scoped customer-contract event command. Signed events require pre-existing canonical evidence; activation is reserved for the supply activation graph.';

--
-- Name: gridex_record_invoice_fee_remediation(uuid, text, uuid, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_record_invoice_fee_remediation(p_company_id uuid, p_source_table text, p_offer_id uuid, p_status text, p_blocker_code text, p_evidence jsonb, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if p_company_id is null
     and coalesce(p_blocker_code,'') not in('tenant_context_missing','tenant_context_conflict') then
    raise exception using errcode='23502',message='company_required_for_tenant_remediation';
  end if;

  insert into public.contract_invoice_fee_remediation_tasks(
    company_id,source_table,offer_id,status,blocker_code,evidence,last_error,resolved_at,updated_at
  ) values(
    p_company_id,p_source_table,p_offer_id,p_status,p_blocker_code,coalesce(p_evidence,'{}'::jsonb),p_error,
    case when p_status='resolved' then now() else null end,now()
  )
  on conflict(source_table,offer_id) do update set
    company_id=excluded.company_id,status=excluded.status,blocker_code=excluded.blocker_code,
    evidence=excluded.evidence,last_error=excluded.last_error,resolved_at=excluded.resolved_at,updated_at=now();
end $$;

--
-- Name: gridex_record_legacy_api_key_use_v1(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_record_legacy_api_key_use_v1(p_api_client_id uuid, p_route text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
 update public.integration_api_clients set legacy_api_key_request_count=legacy_api_key_request_count+1,last_legacy_api_key_used_at=now(),last_legacy_api_key_route=left(nullif(btrim(coalesce(p_route,'')),''),500),legacy_api_key_migration_status=case when legacy_api_key_migration_status='migrated' then 'in_progress' when legacy_api_key_migration_status='unknown' then 'not_started' else legacy_api_key_migration_status end,updated_at=now() where id=p_api_client_id;
$$;

--
-- Name: gridex_refresh_actor_certificate_statuses(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_refresh_actor_certificate_statuses(p_run_type text DEFAULT 'certificate_refresh'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_run_id uuid;
  v_checked int := 0;
  v_missing int := 0;
begin
  insert into public.platform_actor_readiness_runs(run_type, status, metadata)
  values (coalesce(p_run_type, 'certificate_refresh'), 'running', jsonb_build_object('source', 'gridex_refresh_actor_certificate_statuses'))
  returning id into v_run_id;

  update public.platform_actor_certificates c
  set status = case
      when c.status = 'missing' then 'missing'
      when c.valid_to is not null and c.valid_to < now() then 'expired'
      when c.valid_to is not null and c.valid_to <= now() + interval '45 days' then 'expires_soon'
      when c.fingerprint_sha256 is not null and (c.valid_to is null or c.valid_to >= now()) then 'valid'
      else coalesce(nullif(c.status, ''), 'unknown')
    end,
    last_checked_at = coalesce(c.last_checked_at, now()),
    next_check_at = case
      when c.valid_to is not null and c.valid_to <= now() + interval '45 days' then now() + interval '7 days'
      else now() + interval '30 days'
    end,
    updated_at = now(),
    metadata = coalesce(c.metadata, '{}'::jsonb) || jsonb_build_object('status_refreshed_at', now(), 'status_refreshed_by', 'system')
  where c.next_check_at is null or c.next_check_at <= now() or c.last_checked_at is null;

  get diagnostics v_checked = row_count;

  insert into public.platform_actor_certificates(actor_id, ediel_id, environment, certificate_type, purpose, status, source, metadata, last_checked_at, next_check_at)
  select distinct v.actor_id, v.ediel_id, v.environment, 'unknown', 'encryption', 'missing', 'auto_readiness_missing_certificate',
         jsonb_build_object('reason', 'PRODAT production route requires receiver certificate before auto-send', 'created_by', 'gridex_refresh_actor_certificate_statuses'),
         now(), now() + interval '30 days'
  from public.platform_actor_send_readiness_v v
  where v.requires_certificate = true
    and v.certificate_id is null
    and not exists (
      select 1
      from public.platform_actor_certificates existing
      where existing.actor_id = v.actor_id
        and existing.environment = v.environment
        and existing.purpose = 'encryption'
        and existing.status in ('missing','unknown')
    );

  get diagnostics v_missing = row_count;

  update public.platform_actor_readiness_runs
  set status = 'completed', finished_at = now(), checked_certificate_count = v_checked + v_missing,
      metadata = metadata || jsonb_build_object('certificates_refreshed', v_checked, 'missing_certificate_placeholders_created', v_missing)
  where id = v_run_id;

  return jsonb_build_object('ok', true, 'run_id', v_run_id, 'certificates_refreshed', v_checked, 'missing_certificate_placeholders_created', v_missing);
exception when others then
  if v_run_id is not null then
    update public.platform_actor_readiness_runs
    set status = 'failed', finished_at = now(), failed_count = 1, metadata = metadata || jsonb_build_object('error', sqlerrm)
    where id = v_run_id;
  end if;
  raise;
end;
$$;

--
-- Name: gridex_refresh_billing_export_run(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_refresh_billing_export_run(p_company_id uuid, p_export_run_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions', 'pg_temp'
    AS $$
declare v_run public.billing_export_runs%rowtype; v_total integer; v_ready integer; v_blocked integer;
v_queued integer; v_sent integer; v_ack integer; v_failed integer; v_rejected integer; v_status text;
begin
  select * into v_run from public.billing_export_runs where id=p_export_run_id and company_id=p_company_id for update;
  if not found then raise exception using errcode='P0002',message='billing_export_run_not_found'; end if;
  select count(*),count(*) filter(where status in ('ready','ready_for_retry')),count(*) filter(where status='blocked'),
    count(*) filter(where export_status='queued'),count(*) filter(where export_status='sent'),
    count(*) filter(where export_status='acknowledged'),count(*) filter(where export_status='failed'),
    count(*) filter(where partner_result_type='rejected')
  into v_total,v_ready,v_blocked,v_queued,v_sent,v_ack,v_failed,v_rejected
  from public.billing_export_run_items where company_id=p_company_id and billing_export_run_id=p_export_run_id;
  v_status:=case
    when (v_failed>0 or v_blocked>0) and v_sent+v_ack>0 then 'partial_failed'
    when v_failed>0 then 'failed'
    when v_blocked>0 then 'blocked'
    when v_total>0 and v_ack=v_total then 'acknowledged'
    when v_total>0 and v_sent+v_ack=v_total then 'sent'
    when v_queued>0 then 'queued'
    when v_ready>0 then 'ready_with_flags'
    else 'blocked' end;
  update public.billing_export_runs set status=v_status,rows_total=v_total,rows_ready=v_ready,rows_blocked=v_blocked,
    rows_queued=v_queued,rows_sent=v_sent,rows_acknowledged=v_ack,rows_failed=v_failed,rows_rejected=v_rejected,
    rows_exported=v_sent+v_ack,updated_at=now()
  where id=p_export_run_id and company_id=p_company_id returning * into v_run;
  return to_jsonb(v_run);
end $$;

--
-- Name: gridex_refresh_customer_process_summary(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_refresh_customer_process_summary(p_company_id uuid, p_customer_id uuid, p_latest_action text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_active integer;
  v_pending integer;
  v_blocked integer;
  v_total integer;
  v_summary jsonb;
begin
  select
    count(*) filter (where coalesce(onboarding_status,'') in ('active_supply','active')),
    count(*) filter (where coalesce(onboarding_status,'') not in ('active_supply','active','needs_admin_review','blocked')),
    count(*) filter (where coalesce(onboarding_status,'') in ('needs_admin_review','blocked')),
    count(*)
  into v_active,v_pending,v_blocked,v_total
  from public.customer_sites
  where company_id=p_company_id
    and customer_id=p_customer_id
    and coalesce(is_active,true)=true;

  v_summary := jsonb_build_object(
    'total_sites', v_total,
    'active_sites', v_active,
    'pending_sites', v_pending,
    'blocked_sites', v_blocked,
    'refreshed_at', now()
  );

  update public.customers
  set active_sites=v_active,
      pending_sites=v_pending,
      blocked_sites=v_blocked,
      latest_customer_action=coalesce(p_latest_action,latest_customer_action),
      process_summary=v_summary,
      intake_status=case
        when v_total=0 then 'needs_admin_review'
        when v_blocked>0 then 'blocked'
        when v_pending>0 then 'pending_information'
        when v_active=v_total then 'active_supply'
        else 'pending_information'
      end,
      next_action=case
        when v_blocked>0 then 'review_blocker'
        when v_pending>0 then 'continue_site_processes'
        else 'none'
      end,
      updated_at=now()
  where id=p_customer_id and company_id=p_company_id;

  return v_summary;
end;
$$;

--
-- Name: gridex_refresh_customer_summary_from_site_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_refresh_customer_summary_from_site_trigger() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  perform public.gridex_refresh_customer_process_summary(
    coalesce(new.company_id,old.company_id),
    coalesce(new.customer_id,old.customer_id),
    case when tg_op='DELETE' then 'site_deleted' else concat_ws(':',new.id::text,coalesce(new.onboarding_status,''),coalesce(new.next_action,'')) end
  );
  return coalesce(new,old);
end;
$$;

--
-- Name: gridex_refresh_legal_profile_completeness(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_refresh_legal_profile_completeness() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  new.missing_fields := public.gridex_tenant_legal_profile_missing_fields(new);
  -- Keep the persisted value compatible with the existing table constraint and
  -- publication functions. The semantic API status is calculated separately as
  -- complete_unreviewed when review is still required.
  new.completeness_status := case
    when coalesce(array_length(new.missing_fields, 1), 0) > 0 then 'incomplete'
    when coalesce(new.review_required, false) then 'complete'
    when coalesce(new.reviewed_at, new.verified_at) is not null then 'verified'
    else 'complete'
  end;
  new.updated_at := now();
  return new;
end
$$;

--
-- Name: platform_runtime_readiness; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_runtime_readiness (
    id boolean DEFAULT true NOT NULL,
    schema_version text NOT NULL,
    schema_fingerprint text NOT NULL,
    is_ready boolean DEFAULT false NOT NULL,
    blocking_issues jsonb DEFAULT '[]'::jsonb NOT NULL,
    capabilities jsonb DEFAULT '{}'::jsonb NOT NULL,
    verified_at timestamp with time zone NOT NULL,
    deployment_id text,
    migration_version text NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT platform_runtime_readiness_blocking_issues_check CHECK ((jsonb_typeof(blocking_issues) = 'array'::text)),
    CONSTRAINT platform_runtime_readiness_capabilities_check CHECK ((jsonb_typeof(capabilities) = 'object'::text)),
    CONSTRAINT platform_runtime_readiness_id_check CHECK (id),
    CONSTRAINT platform_runtime_readiness_migration_version_check CHECK ((migration_version ~ '^[0-9]{14}$'::text)),
    CONSTRAINT platform_runtime_readiness_schema_fingerprint_check CHECK ((schema_fingerprint ~ '^[a-f0-9]{64}$'::text))
);

--
-- Name: gridex_refresh_platform_runtime_readiness_v1(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_refresh_platform_runtime_readiness_v1(p_schema_version text, p_deployment_id text DEFAULT NULL::text, p_migration_version text DEFAULT NULL::text) RETURNS public.platform_runtime_readiness
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_runtime record;
  v_result public.platform_runtime_readiness%rowtype;
  v_schema_version text := nullif(btrim(coalesce(p_schema_version, '')), '');
  v_migration_version text := nullif(btrim(coalesce(p_migration_version, '')), '');
begin
  if v_schema_version is null then raise exception using errcode='22023', message='runtime_schema_version_required'; end if;
  if v_migration_version is null then
    select max(version::text) into v_migration_version from supabase_migrations.schema_migrations;
  end if;
  if v_migration_version is null or v_migration_version !~ '^[0-9]{14}$' then
    raise exception using errcode='22023', message='runtime_migration_version_invalid';
  end if;
  select is_ready, schema_fingerprint, blocking_issues, capabilities into strict v_runtime
  from public.gridex_runtime_schema_capabilities_v3;
  insert into public.platform_runtime_readiness(id,schema_version,schema_fingerprint,is_ready,blocking_issues,capabilities,verified_at,deployment_id,migration_version,updated_at)
  values(true,v_schema_version,v_runtime.schema_fingerprint,v_runtime.is_ready and coalesce(cardinality(v_runtime.blocking_issues),0)=0,to_jsonb(coalesce(v_runtime.blocking_issues,'{}'::text[])),coalesce(v_runtime.capabilities,'{}'::jsonb),now(),nullif(btrim(coalesce(p_deployment_id,'')),''),v_migration_version,now())
  on conflict(id) do update set schema_version=excluded.schema_version,schema_fingerprint=excluded.schema_fingerprint,is_ready=excluded.is_ready,blocking_issues=excluded.blocking_issues,capabilities=excluded.capabilities,verified_at=excluded.verified_at,deployment_id=excluded.deployment_id,migration_version=excluded.migration_version,updated_at=excluded.updated_at
  returning * into v_result;
  return v_result;
end $_$;

--
-- Name: gridex_register_late_metering_correction(uuid, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_register_late_metering_correction(p_company_id uuid, p_original_underlay_id uuid, p_corrected_underlay_id uuid, p_source_value_id uuid, p_reason text, p_currency text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare v_id uuid; v_status text;
begin
  if nullif(btrim(p_reason),'') is null then raise exception 'adjustment_reason_required'; end if;
  if p_currency !~ '^[A-Z]{3}$' then raise exception 'invalid_currency'; end if;
  select status into v_status from public.billing_underlays where id=p_original_underlay_id and company_id=p_company_id;
  if not found then raise exception 'original_underlay_not_found_for_tenant'; end if;
  if v_status not in ('exported','invoiced','locked','completed') then raise exception 'underlay_not_locked_or_invoiced'; end if;
  insert into public.billing_adjustment_cases(company_id,original_billing_underlay_id,corrected_billing_underlay_id,source_normalized_metering_value_id,reason,status,currency)
  values(p_company_id,p_original_underlay_id,p_corrected_underlay_id,p_source_value_id,p_reason,'detected',p_currency)
  on conflict(company_id,original_billing_underlay_id,source_normalized_metering_value_id)
  do update set corrected_billing_underlay_id=excluded.corrected_billing_underlay_id,reason=excluded.reason,updated_at=now()
  returning id into v_id;
  return v_id;
end $_$;

