--
-- Name: gridex_reject_billing_configuration_snapshot_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reject_billing_configuration_snapshot_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.billing_configuration_snapshot_sha256 is not null
     and (
       new.billing_configuration_snapshot is distinct from old.billing_configuration_snapshot
       or new.billing_configuration_snapshot_sha256 is distinct from old.billing_configuration_snapshot_sha256
       or new.billing_configuration_snapshotted_at is distinct from old.billing_configuration_snapshotted_at
     ) then
    raise exception 'billing_configuration_snapshot_is_immutable'
      using errcode = '23514';
  end if;
  return new;
end;
$$;

--
-- Name: gridex_reject_locked_legal_document_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reject_locked_legal_document_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if exists(
    select 1 from public.legal_bundle_versions b
    where b.id=old.legal_bundle_version_id
      and (b.locked_at is not null or b.published_at is not null)
  ) and coalesce(current_setting('gridex.version_transition',true),'')<>'on' then
    raise exception using errcode='55000',message='immutable_legal_document_locked';
  end if;
  return case when tg_op='DELETE' then old else new end;
end $$;

--
-- Name: gridex_reject_locked_market_price_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reject_locked_market_price_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if tg_op='DELETE' then
    if old.status='locked' then
      raise exception 'locked_market_price_immutable' using errcode='55000';
    end if;
    return old;
  end if;
  if old.status='locked' and new is distinct from old then
    raise exception 'locked_market_price_immutable' using errcode='55000';
  end if;
  return new;
end;
$$;

--
-- Name: gridex_reject_locked_price_book_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reject_locked_price_book_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_book_id uuid;
  v_locked_at timestamptz;
begin
  if tg_table_name = 'price_books' then
    if old.locked_at is not null and coalesce(current_setting('gridex.pricing_version_write', true), '') <> 'on' then
      raise exception 'Publicerad prislista är låst och får inte ändras.' using errcode = '55000';
    end if;
  else
    v_book_id := coalesce(old.price_book_id, new.price_book_id);
    select locked_at into v_locked_at from public.price_books where id = v_book_id;
    if v_locked_at is not null and coalesce(current_setting('gridex.pricing_version_write', true), '') <> 'on' then
      raise exception 'Rad i låst prislista får inte ändras.' using errcode = '55000';
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;

--
-- Name: gridex_reject_locked_price_child_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reject_locked_price_child_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_version_id uuid;
  v_locked_at timestamptz;
begin
  v_version_id := coalesce(old.price_plan_version_id, new.price_plan_version_id);
  if v_version_id is not null then
    select locked_at into v_locked_at from public.price_plan_versions where id = v_version_id;
    if v_locked_at is not null and coalesce(current_setting('gridex.pricing_version_write', true), '') <> 'on' then
      raise exception 'Priskomponent tillhör en låst prisversion och får inte ändras.' using errcode = '55000';
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;

--
-- Name: gridex_reject_locked_price_version_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reject_locked_price_version_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
begin
  if old.locked_at is not null and coalesce(current_setting('gridex.pricing_version_write', true), '') <> 'on' then
    raise exception 'Publicerad prisversion är låst och får inte ändras. Skapa en ny version.' using errcode = '55000';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end $$;

--
-- Name: gridex_reject_locked_row_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reject_locked_row_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions', 'pg_catalog', 'pg_temp'
    AS $$
declare
  v_transition boolean:=coalesce(
    current_setting('gridex.version_transition',true),'')='on';
  v_publication_repair boolean:=coalesce(
    current_setting('gridex.publication_graph_repair',true),'')='on';
  v_old jsonb;
  v_new jsonb;
  v_allowed text[];
  v_expected_price_options jsonb;
begin
  if nullif(to_jsonb(old)->>'locked_at','') is null
     and nullif(to_jsonb(old)->>'published_at','') is null then
    return case when tg_op='DELETE' then old else new end;
  end if;
  if not v_transition then
    raise exception using errcode='55000',message='immutable_version_locked';
  end if;
  if tg_op='DELETE' then return old; end if;

  v_allowed:=case tg_table_name
    when 'contract_product_versions'
      then array['status','approved_at','approved_by','locked_at']
    when 'legal_template_versions'
      then array['status','reviewed_by','reviewed_at','published_at','locked_at']
    when 'legal_bundle_versions'
      then array['status','published_at','locked_at']
    when 'contract_publication_versions'
      then array['status','valid_from','valid_to','published_at','locked_at',
        'legacy_public_contract_offer_id']
    when 'tenant_legal_overrides'
      then array['status','submitted_at','reviewed_at','reviewed_by',
        'review_notes','locked_at']
    else array[]::text[]
  end;

  if tg_table_name='contract_publication_versions'
     and v_publication_repair then
    if current_user not in ('postgres','supabase_admin','service_role')
       and not pg_has_role(current_user,'service_role','member') then
      raise exception using errcode='42501',
        message='PUBLICATION_REPAIR_ROLE_REQUIRED';
    end if;
    if old.publication_snapshot->'commercial_snapshot'
       is distinct from new.publication_snapshot->'commercial_snapshot' then
      raise exception using errcode='55000',
        message='locked_publication_commercial_snapshot_is_immutable';
    end if;
    v_expected_price_options:=
      public.gridex_publication_price_options_json_v1(new.id);
    if coalesce(new.publication_snapshot->'price_options','[]'::jsonb)
       is distinct from v_expected_price_options then
      raise exception using errcode='23514',
        message='PUBLICATION_PRICE_OPTION_SNAPSHOT_MISMATCH';
    end if;
    if new.content_sha256 is distinct from encode(
      extensions.digest(new.publication_snapshot::text,'sha256'),'hex') then
      raise exception using errcode='23514',
        message='PUBLICATION_SNAPSHOT_INVALID';
    end if;
    v_allowed:=v_allowed||array['publication_snapshot','content_sha256'];
  end if;

  v_old:=to_jsonb(old)-v_allowed;
  v_new:=to_jsonb(new)-v_allowed;
  if v_old is distinct from v_new then
    raise exception using errcode='55000',
      message='immutable_version_content_changed';
  end if;
  return new;
end $$;

--
-- Name: gridex_reject_quote_site_count_mutation_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_reject_quote_site_count_mutation_v1() RETURNS trigger
