--
-- Name: contract_publication_graph_integrity_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.contract_publication_graph_integrity_v WITH (security_invoker='true') AS
 SELECT public_offer.company_id,
    public_offer.id AS public_contract_offer_id,
    public_offer.source_contract_offer_id,
    public_offer.contract_product_version_id AS public_offer_product_version_id,
    public_offer.contract_publication_version_id AS canonical_publication_version_id,
    publication_version.id AS publication_version_id,
    publication_version.contract_product_version_id AS publication_product_version_id,
    publication_version.legacy_public_contract_offer_id,
    publication.channel,
    assignment.company_id AS publication_company_id,
    ((public_offer.contract_publication_version_id IS NOT NULL) AND (publication_version.id = public_offer.contract_publication_version_id)) AS forward_publication_link_valid,
    (publication_version.legacy_public_contract_offer_id = public_offer.id) AS reverse_legacy_link_valid,
    (assignment.company_id = public_offer.company_id) AS company_chain_valid,
    (assignment.contract_product_version_id = publication_version.contract_product_version_id) AS tenant_assignment_valid,
    ((publication.channel = 'website'::text) AND (publication_version.channel = 'website'::text)) AS channel_valid,
    (publication_version.contract_product_version_id = public_offer.contract_product_version_id) AS product_version_valid,
    ((publication_version.publication_snapshot ->> 'source_contract_offer_id'::text) = (public_offer.source_contract_offer_id)::text) AS source_offer_consistent,
    ((publication.status = 'published'::text) AND (publication_version.status = 'published'::text) AND (assignment.status = 'active'::text) AND (channel.status = 'active'::text)) AS publication_active,
    ((public_offer.contract_publication_version_id IS NOT NULL) AND (publication_version.id = public_offer.contract_publication_version_id) AND (publication_version.legacy_public_contract_offer_id = public_offer.id) AND (assignment.company_id = public_offer.company_id) AND (assignment.contract_product_version_id = publication_version.contract_product_version_id) AND assignment.website_publication_allowed AND (assignment.status = 'active'::text) AND (publication.channel = 'website'::text) AND (publication.status = 'published'::text) AND (publication_version.channel = 'website'::text) AND (publication_version.status = 'published'::text) AND (channel.channel = 'website'::text) AND (channel.status = 'active'::text) AND (company.status = 'active'::text) AND ((channel.valid_from IS NULL) OR (channel.valid_from <= now())) AND ((channel.valid_to IS NULL) OR (channel.valid_to > now())) AND ((publication_version.valid_from IS NULL) OR (publication_version.valid_from <= now())) AND ((publication_version.valid_to IS NULL) OR (publication_version.valid_to > now())) AND (publication_version.contract_product_version_id = public_offer.contract_product_version_id) AND ((publication_version.publication_snapshot ->> 'source_contract_offer_id'::text) = (public_offer.source_contract_offer_id)::text) AND (publication_version.content_sha256 = encode(extensions.digest((publication_version.publication_snapshot)::text, 'sha256'::text), 'hex'::text)) AND (COALESCE(NULLIF(lower((publication_version.publication_snapshot ->> 'energy_direction'::text)), ''::text), NULLIF(lower(publication_version.energy_direction), ''::text), 'consumption'::text) = COALESCE(NULLIF(lower(public_offer.energy_direction), ''::text), 'consumption'::text)) AND (COALESCE(NULLIF(lower(publication_version.energy_direction), ''::text), 'consumption'::text) = COALESCE(NULLIF(lower(product_version.energy_direction), ''::text), 'consumption'::text)) AND (COALESCE(NULLIF(lower((publication_version.publication_snapshot ->> 'contract_type'::text)), ''::text), NULLIF(lower(product_version.contract_type), ''::text)) = lower(public_offer.contract_type)) AND (( SELECT count(*) AS count
           FROM public.contract_publication_versions active_version
          WHERE ((active_version.contract_publication_id = publication.id) AND (active_version.status = 'published'::text))) = 1) AND (NOT (EXISTS ( SELECT 1
           FROM public.contract_offers successor
          WHERE ((successor.supersedes_offer_id = public_offer.source_contract_offer_id) AND (successor.lifecycle_status = 'published'::text) AND successor.is_active))))) AS canonical_graph_consistent,
    (publication_version.content_sha256 = encode(extensions.digest((publication_version.publication_snapshot)::text, 'sha256'::text), 'hex'::text)) AS snapshot_hash_valid,
    ((COALESCE(NULLIF(lower((publication_version.publication_snapshot ->> 'energy_direction'::text)), ''::text), NULLIF(lower(publication_version.energy_direction), ''::text), 'consumption'::text) = COALESCE(NULLIF(lower(public_offer.energy_direction), ''::text), 'consumption'::text)) AND (COALESCE(NULLIF(lower(publication_version.energy_direction), ''::text), 'consumption'::text) = COALESCE(NULLIF(lower(product_version.energy_direction), ''::text), 'consumption'::text))) AS energy_direction_valid,
    (COALESCE(NULLIF(lower((publication_version.publication_snapshot ->> 'contract_type'::text)), ''::text), NULLIF(lower(product_version.contract_type), ''::text)) = lower(public_offer.contract_type)) AS contract_type_valid,
    (NOT (EXISTS ( SELECT 1
           FROM public.contract_offers successor
          WHERE ((successor.supersedes_offer_id = public_offer.source_contract_offer_id) AND (successor.lifecycle_status = 'published'::text) AND successor.is_active)))) AS successor_chain_valid,
    COALESCE(assignment.website_publication_allowed, false) AS channel_permission_granted,
    ((assignment.status = 'active'::text) AND (channel.status = 'active'::text) AND (publication.status = 'published'::text) AND (publication_version.status = 'published'::text)) AS channel_graph_active,
    (((channel.valid_from IS NULL) OR (channel.valid_from <= now())) AND ((channel.valid_to IS NULL) OR (channel.valid_to > now())) AND ((publication_version.valid_from IS NULL) OR (publication_version.valid_from <= now())) AND ((publication_version.valid_to IS NULL) OR (publication_version.valid_to > now()))) AS date_window_valid,
    ( SELECT (count(*) = 1)
           FROM public.contract_publication_versions active_version
          WHERE ((active_version.contract_publication_id = publication.id) AND (active_version.status = 'published'::text))) AS single_active_publication_version
   FROM ((((((public.public_contract_offers public_offer
     LEFT JOIN public.contract_publication_versions publication_version ON ((publication_version.id = public_offer.contract_publication_version_id)))
     LEFT JOIN public.contract_publications publication ON ((publication.id = publication_version.contract_publication_id)))
     LEFT JOIN public.tenant_contract_assignments assignment ON ((assignment.id = publication.assignment_id)))
     LEFT JOIN public.tenant_contract_channels channel ON (((channel.assignment_id = assignment.id) AND (channel.channel = publication.channel))))
     LEFT JOIN public.contract_product_versions product_version ON ((product_version.id = publication_version.contract_product_version_id)))
     LEFT JOIN public.companies company ON ((company.id = assignment.company_id)));

--
-- Name: VIEW contract_publication_graph_integrity_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.contract_publication_graph_integrity_v IS 'Fail-closed canonical publication integrity including bidirectional links, tenant/channel/product chain, immutable hash, energy direction, contract type and successor use.';

