--
-- Name: canonical_internal_contract_offers_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.canonical_internal_contract_offers_v WITH (security_invoker='true') AS
 WITH source AS (
         SELECT offer.id,
            offer.company_id,
            offer.name,
            offer.slug,
            offer.status,
            offer.contract_type,
            offer.campaign_name,
            offer.campaign_code,
            offer.campaign_version,
            offer.price_version,
            offer.terms_version,
            offer.offer_version,
            offer.terms_document_url,
            offer.version_snapshot,
            offer.max_customers,
            offer.discount_value,
            offer.discount_unit,
            offer.start_fee_sek,
            offer.admin_fee_sek,
            offer.break_fee_sek,
            offer.vat_rate,
            offer.description,
            offer.fixed_price_ore_per_kwh,
            offer.spot_markup_ore_per_kwh,
            offer.variable_fee_ore_per_kwh,
            offer.monthly_fee_sek,
            offer.green_fee_mode,
            offer.green_fee_value,
            offer.default_binding_months,
            offer.default_notice_months,
            offer.optional_fee_lines,
            offer.is_active,
            offer.valid_from,
            offer.valid_to,
            offer.created_at,
            offer.updated_at,
            offer.created_by,
            offer.updated_by,
            offer.version_number,
            offer.published_at,
            offer.archived_at,
            offer.last_price_change_at,
            offer.pricing_components,
            offer.billing_validation_rules,
            offer.price_plan_id,
            offer.price_plan_version_id,
            offer.price_book_id,
            offer.commercial_snapshot,
            offer.customer_type,
            offer.automatic_renewal,
            offer.power_of_attorney_required,
            offer.legal_bundle_id,
            offer.contract_product_id,
            offer.contract_product_version_id,
            offer.legal_bundle_version_id,
            offer.invoice_fee_sek,
            offer.version_series_id,
            offer.supersedes_offer_id,
            offer.superseded_at,
            offer.lifecycle_status,
            offer.discount_months,
            offer.discount_calculation_base,
            offer.discount_starts_on_mode,
            offer.automatic_renewal_term_months,
            offer.power_of_attorney_mode,
            offer.closed_at,
            offer.closed_by,
            offer.close_reason,
            offer.energy_direction,
            offer.copied_from_contract_offer_id,
            product.product_code AS canonical_product_code,
            product.status AS canonical_product_status,
            product_version.version_number AS canonical_version_number,
            product_version.status AS canonical_version_status,
            product_version.content_sha256 AS canonical_content_sha256,
            assignment.id AS assignment_id,
            COALESCE(assignment.status, 'missing'::text) AS assignment_status,
            assignment.valid_from AS assignment_valid_from,
            assignment.valid_to AS assignment_valid_to,
            COALESCE(assignment.internal_sales_allowed, false) AS internal_sales_allowed,
            COALESCE(assignment.website_publication_allowed, false) AS website_publication_allowed,
            COALESCE(assignment.api_publication_allowed, false) AS api_publication_allowed,
            company.status AS tenant_status,
            internal_channel.status AS internal_channel_status_raw,
            internal_channel.valid_from AS internal_channel_valid_from,
            internal_channel.valid_to AS internal_channel_valid_to,
            website_channel.status AS website_channel_status_raw,
            website_channel.valid_from AS website_channel_valid_from,
            website_channel.valid_to AS website_channel_valid_to,
            api_channel.status AS api_channel_status_raw,
            api_channel.valid_from AS api_channel_valid_from,
            api_channel.valid_to AS api_channel_valid_to,
            (COALESCE(publication_counts.active_count, (0)::bigint))::integer AS active_publication_version_count,
            COALESCE(channel_readiness.internal, jsonb_build_object('ready', false, 'blockers', jsonb_build_array(jsonb_build_object('code', 'contract_assignment_not_found', 'message', 'Avtalstilldelningen saknas.')))) AS internal_readiness_source,
            COALESCE(channel_readiness.website, jsonb_build_object('ready', false, 'blockers', jsonb_build_array(jsonb_build_object('code', 'contract_assignment_not_found', 'message', 'Avtalstilldelningen saknas.')))) AS website_readiness_source,
            COALESCE(channel_readiness.api, jsonb_build_object('ready', false, 'blockers', jsonb_build_array(jsonb_build_object('code', 'contract_assignment_not_found', 'message', 'Avtalstilldelningen saknas.')))) AS api_readiness_source,
            ((company.status = 'active'::text) AND (offer.lifecycle_status = ANY (ARRAY['published'::text, 'paused'::text])) AND (assignment.id IS NOT NULL) AND (assignment.status = ANY (ARRAY['active'::text, 'paused'::text])) AND ((assignment.valid_from IS NULL) OR (assignment.valid_from <= ((now() AT TIME ZONE 'Europe/Stockholm'::text))::date)) AND ((assignment.valid_to IS NULL) OR (assignment.valid_to >= ((now() AT TIME ZONE 'Europe/Stockholm'::text))::date)) AND (product_version.status = 'approved'::text) AND (product_version.locked_at IS NOT NULL) AND (offer.price_plan_version_id IS NOT NULL) AND (offer.legal_bundle_version_id IS NOT NULL) AND ((offer.valid_from IS NULL) OR (offer.valid_from <= ((now() AT TIME ZONE 'Europe/Stockholm'::text))::date)) AND ((offer.valid_to IS NULL) OR (offer.valid_to >= ((now() AT TIME ZONE 'Europe/Stockholm'::text))::date))) AS common_channel_ready,
                CASE
                    WHEN (offer.contract_product_version_id IS NULL) THEN 'missing_product_version'::text
                    WHEN (product_version.id IS NULL) THEN 'broken_product_version'::text
                    WHEN (product.id IS NULL) THEN 'missing_product'::text
                    ELSE 'ok'::text
                END AS relation_status
           FROM (((((((((public.contract_offers offer
             LEFT JOIN public.contract_product_versions product_version ON (((product_version.id = offer.contract_product_version_id) AND (product_version.contract_product_id = offer.contract_product_id))))
             LEFT JOIN public.contract_products product ON ((product.id = offer.contract_product_id)))
             LEFT JOIN public.tenant_contract_assignments assignment ON (((assignment.company_id = offer.company_id) AND (assignment.contract_product_version_id = offer.contract_product_version_id))))
             LEFT JOIN public.companies company ON ((company.id = offer.company_id)))
             LEFT JOIN public.tenant_contract_channels internal_channel ON (((internal_channel.assignment_id = assignment.id) AND (internal_channel.channel = 'internal'::text))))
             LEFT JOIN public.tenant_contract_channels website_channel ON (((website_channel.assignment_id = assignment.id) AND (website_channel.channel = 'website'::text))))
             LEFT JOIN public.tenant_contract_channels api_channel ON (((api_channel.assignment_id = assignment.id) AND (api_channel.channel = 'api'::text))))
             LEFT JOIN LATERAL ( SELECT count(*) AS active_count
                   FROM (public.contract_publications publication
                     JOIN public.contract_publication_versions publication_version ON ((publication_version.contract_publication_id = publication.id)))
                  WHERE ((publication.assignment_id = assignment.id) AND (publication.status = 'published'::text) AND (publication_version.status = 'published'::text))) publication_counts ON (true))
             LEFT JOIN LATERAL ( SELECT public.gridex_validate_contract_channel_readiness(offer.company_id, assignment.id, 'internal'::text) AS internal,
                    public.gridex_validate_contract_channel_readiness(offer.company_id, assignment.id, 'website'::text) AS website,
                    public.gridex_validate_contract_channel_readiness(offer.company_id, assignment.id, 'api'::text) AS api) channel_readiness ON ((assignment.id IS NOT NULL)))
        )
 SELECT id,
    company_id,
    name,
    slug,
    status,
    contract_type,
    campaign_name,
    campaign_code,
    campaign_version,
    price_version,
    terms_version,
    offer_version,
    terms_document_url,
    version_snapshot,
    max_customers,
    discount_value,
    discount_unit,
    start_fee_sek,
    admin_fee_sek,
    break_fee_sek,
    vat_rate,
    description,
    fixed_price_ore_per_kwh,
    spot_markup_ore_per_kwh,
    variable_fee_ore_per_kwh,
    monthly_fee_sek,
    green_fee_mode,
    green_fee_value,
    default_binding_months,
    default_notice_months,
    optional_fee_lines,
    is_active,
    valid_from,
    valid_to,
    created_at,
    updated_at,
    created_by,
    updated_by,
    version_number,
    published_at,
    archived_at,
    last_price_change_at,
    pricing_components,
    billing_validation_rules,
    price_plan_id,
    price_plan_version_id,
    price_book_id,
    commercial_snapshot,
    customer_type,
    automatic_renewal,
    power_of_attorney_required,
    legal_bundle_id,
    contract_product_id,
    contract_product_version_id,
    legal_bundle_version_id,
    invoice_fee_sek,
    version_series_id,
    supersedes_offer_id,
    superseded_at,
    lifecycle_status,
    discount_months,
    discount_calculation_base,
    discount_starts_on_mode,
    automatic_renewal_term_months,
    power_of_attorney_mode,
    closed_at,
    closed_by,
    close_reason,
    energy_direction,
    copied_from_contract_offer_id,
    canonical_product_code,
    canonical_product_status,
    canonical_version_number,
    canonical_version_status,
    canonical_content_sha256,
    assignment_id,
    assignment_status,
    assignment_valid_from,
    assignment_valid_to,
    internal_sales_allowed,
    website_publication_allowed,
    api_publication_allowed,
    tenant_status,
    internal_channel_status_raw,
    internal_channel_valid_from,
    internal_channel_valid_to,
    website_channel_status_raw,
    website_channel_valid_from,
    website_channel_valid_to,
    api_channel_status_raw,
    api_channel_valid_from,
    api_channel_valid_to,
    active_publication_version_count,
    internal_readiness_source,
    website_readiness_source,
    api_readiness_source,
    common_channel_ready,
    relation_status,
    id AS contract_offer_id,
    status AS offer_status,
    NULL::jsonb AS readiness,
    NULL::jsonb AS deletion_preview,
    COALESCE(internal_channel_status_raw, 'missing'::text) AS internal_channel_status,
    COALESCE(website_channel_status_raw, 'missing'::text) AS website_channel_status,
    COALESCE(api_channel_status_raw, 'missing'::text) AS api_channel_status,
    (common_channel_ready AND internal_sales_allowed AND (assignment_status = 'active'::text) AND (internal_channel_status_raw = 'active'::text) AND ((internal_channel_valid_from IS NULL) OR (internal_channel_valid_from <= now())) AND ((internal_channel_valid_to IS NULL) OR (internal_channel_valid_to > now())) AND (EXISTS ( SELECT 1
           FROM (public.contract_publications publication
             JOIN public.contract_publication_versions publication_version ON ((publication_version.contract_publication_id = publication.id)))
          WHERE ((publication.assignment_id = source.assignment_id) AND (publication.channel = 'internal'::text) AND (publication.status = 'published'::text) AND (publication_version.status = 'published'::text) AND (publication_version.contract_product_version_id = source.contract_product_version_id) AND (publication_version.content_sha256 = encode(extensions.digest((publication_version.publication_snapshot)::text, 'sha256'::text), 'hex'::text)) AND ((publication_version.valid_from IS NULL) OR (publication_version.valid_from <= now())) AND ((publication_version.valid_to IS NULL) OR (publication_version.valid_to > now())))))) AS internally_sellable_now,
    (common_channel_ready AND website_publication_allowed AND (assignment_status = 'active'::text) AND (website_channel_status_raw = 'active'::text) AND ((website_channel_valid_from IS NULL) OR (website_channel_valid_from <= now())) AND ((website_channel_valid_to IS NULL) OR (website_channel_valid_to > now())) AND (EXISTS ( SELECT 1
           FROM ((public.contract_publications publication
             JOIN public.contract_publication_versions publication_version ON ((publication_version.contract_publication_id = publication.id)))
             JOIN public.public_contract_offers public_offer ON ((public_offer.contract_publication_version_id = publication_version.id)))
          WHERE ((publication.assignment_id = source.assignment_id) AND (publication.channel = 'website'::text) AND (publication.status = 'published'::text) AND (publication_version.status = 'published'::text) AND (public_offer.company_id = source.company_id) AND (public_offer.source_contract_offer_id = source.id) AND (public_offer.lifecycle_status = 'published'::text) AND (public_offer.publication_status = 'published'::text) AND public_offer.is_public AND public_offer.website_enabled AND public_offer.website_cta_enabled AND (EXISTS ( SELECT 1
                   FROM public.contract_publication_graph_integrity_v graph
                  WHERE ((graph.public_contract_offer_id = public_offer.id) AND graph.canonical_graph_consistent))))))) AS website_available_now,
    (common_channel_ready AND api_publication_allowed AND (assignment_status = 'active'::text) AND (api_channel_status_raw = 'active'::text) AND ((api_channel_valid_from IS NULL) OR (api_channel_valid_from <= now())) AND ((api_channel_valid_to IS NULL) OR (api_channel_valid_to > now())) AND (EXISTS ( SELECT 1
           FROM (public.contract_publications publication
             JOIN public.contract_publication_versions publication_version ON ((publication_version.contract_publication_id = publication.id)))
          WHERE ((publication.assignment_id = source.assignment_id) AND (publication.channel = 'api'::text) AND (publication.status = 'published'::text) AND (publication_version.status = 'published'::text) AND (publication_version.contract_product_version_id = source.contract_product_version_id) AND (publication_version.content_sha256 = encode(extensions.digest((publication_version.publication_snapshot)::text, 'sha256'::text), 'hex'::text)) AND ((publication_version.valid_from IS NULL) OR (publication_version.valid_from <= now())) AND ((publication_version.valid_to IS NULL) OR (publication_version.valid_to > now()))))) AND (EXISTS ( SELECT 1
           FROM public.integration_api_clients client
          WHERE ((client.company_id = source.company_id) AND (client.status = 'active'::text) AND ((client.expires_at IS NULL) OR (client.expires_at > now())) AND (COALESCE(client.scopes, '{}'::text[]) @> ARRAY['api_contracts.read'::text]))))) AS api_available_now,
    (common_channel_ready AND internal_sales_allowed) AS internal_publication_ready,
    jsonb_build_object('ready', COALESCE(((internal_readiness_source ->> 'ready'::text))::boolean, false), 'blockers', COALESCE((internal_readiness_source -> 'blockers'::text), '[]'::jsonb)) AS internal_readiness,
    jsonb_build_object('ready', COALESCE(((website_readiness_source ->> 'ready'::text))::boolean, false), 'blockers', COALESCE((website_readiness_source -> 'blockers'::text), '[]'::jsonb)) AS website_readiness,
    jsonb_build_object('ready', COALESCE(((api_readiness_source ->> 'ready'::text))::boolean, false), 'blockers', COALESCE((api_readiness_source -> 'blockers'::text), '[]'::jsonb)) AS api_readiness,
    (common_channel_ready AND internal_sales_allowed AND (assignment_status = 'active'::text) AND (internal_channel_status_raw = 'active'::text) AND ((internal_channel_valid_from IS NULL) OR (internal_channel_valid_from <= now())) AND ((internal_channel_valid_to IS NULL) OR (internal_channel_valid_to > now())) AND (EXISTS ( SELECT 1
           FROM (public.contract_publications publication
             JOIN public.contract_publication_versions publication_version ON ((publication_version.contract_publication_id = publication.id)))
          WHERE ((publication.assignment_id = source.assignment_id) AND (publication.channel = 'internal'::text) AND (publication.status = 'published'::text) AND (publication_version.status = 'published'::text) AND (publication_version.contract_product_version_id = source.contract_product_version_id) AND (publication_version.content_sha256 = encode(extensions.digest((publication_version.publication_snapshot)::text, 'sha256'::text), 'hex'::text)) AND ((publication_version.valid_from IS NULL) OR (publication_version.valid_from <= now())) AND ((publication_version.valid_to IS NULL) OR (publication_version.valid_to > now())))))) AS currently_sellable
   FROM source;

