    CONSTRAINT contract_price_options_contract_type_check CHECK ((contract_type = ANY (ARRAY['fixed'::text, 'variable_monthly'::text, 'variable_hourly'::text, 'variable_quarterly'::text, 'portfolio'::text, 'mixed'::text]))),
    CONSTRAINT contract_price_options_customer_type_check CHECK (((customer_type IS NULL) OR (customer_type = ANY (ARRAY['private'::text, 'business'::text, 'both'::text])))),
    CONSTRAINT contract_price_options_dates CHECK ((((valid_from IS NULL) OR (valid_to IS NULL) OR (valid_to >= valid_from)) AND ((earliest_start_date IS NULL) OR (latest_start_date IS NULL) OR (latest_start_date >= earliest_start_date)))),
    CONSTRAINT contract_price_options_notice_months_check CHECK (((notice_months >= 0) AND (notice_months <= 36))),
    CONSTRAINT contract_price_options_reference_format CHECK (((option_reference ~ '^[a-z0-9][a-z0-9_-]{2,99}$'::text) AND (option_code ~ '^[a-z0-9][a-z0-9_-]{2,99}$'::text))),
    CONSTRAINT contract_price_options_renewal CHECK (((auto_renew_enabled AND ((renewal_term_months >= 1) AND (renewal_term_months <= 120))) OR ((NOT auto_renew_enabled) AND (renewal_term_months IS NULL)))),
    CONSTRAINT contract_price_options_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'paused'::text, 'archived'::text]))),
    CONSTRAINT contract_price_options_version_number_check CHECK ((version_number > 0))
);

