    created_at timestamp with time zone DEFAULT now() NOT NULL,
    created_by uuid,
    version_number integer NOT NULL,
    content_sha256 text NOT NULL,
    approved_at timestamp with time zone,
    approved_by uuid,
    published_at timestamp with time zone,
