);

--
-- Name: canonical_public_contract_offers_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.canonical_public_contract_offers_v WITH (security_invoker='true') AS
 SELECT public_offer.id,
    public_offer.company_id,
    public_offer.price_plan_id,
    public_offer.price_plan_version_id,
    public_offer.campaign_version_id,
    public_offer.product_code,
    public_offer.public_name,
    public_offer.public_description,
    public_offer.contract_type,
    public_offer.billing_model,
    public_offer.customer_type,
    public_offer.monthly_fee_sek,
    public_offer.invoice_fee_sek,
    public_offer.markup_ore_per_kwh,
    public_offer.spot_markup_ore_per_kwh,
    public_offer.variable_fee_ore_per_kwh,
    public_offer.fixed_price_ore_per_kwh,
    public_offer.green_fee_mode,
    public_offer.green_fee_value,
    public_offer.terms_version,
    public_offer.valid_from,
    public_offer.valid_to,
    public_offer.is_public,
    public_offer.is_archived,
    public_offer.sort_order,
    public_offer.metadata,
    public_offer.created_by,
    public_offer.updated_by,
    public_offer.created_at,
    public_offer.updated_at,
    public_offer.offer_code,
    public_offer.publication_status,
    public_offer.website_enabled,
    public_offer.website_cta_enabled,
    public_offer.public_price_text,
    public_offer.terms_url,
    public_offer.binding_months,
    public_offer.notice_months,
    public_offer.spot_weight_percent,
    public_offer.portfolio_weight_percent,
    public_offer.fixed_weight_percent,
    public_offer.price_area,
    public_offer.published_at,
    public_offer.archived_at,
    public_offer.readiness_issues,
    public_offer.publication_notes,
    public_offer.legal_bundle_id,
    public_offer.price_book_id,
    public_offer.readiness_status,
    public_offer.readiness_blockers,
    public_offer.electricity_certificate_ore_per_kwh,
    public_offer.start_fee_sek,
    public_offer.administration_fee_sek,
    public_offer.break_fee_sek,
    public_offer.portfolio_management_fee_ore_per_kwh,
    public_offer.discount_value,
    public_offer.discount_unit,
    public_offer.discount_months,
    public_offer.vat_rate,
    public_offer.price_areas,
    public_offer.automatic_renewal,
    public_offer.power_of_attorney_required,
    public_offer.version_series_id,
    public_offer.version_number,
    public_offer.supersedes_offer_id,
    public_offer.contract_product_id,
    public_offer.contract_product_version_id,
    public_offer.legal_bundle_version_id,
    public_offer.contract_publication_version_id,
    publication_version.offer_reference AS canonical_offer_reference,
    publication_version.locked_at AS publication_locked_at,
    publication_version.content_sha256 AS publication_content_sha256,
    price_plan_version.snapshot_json AS canonical_pricing_snapshot,
    (COALESCE(public_offer.metadata, '{}'::jsonb) || jsonb_build_object('canonical_offer_reference', publication_version.offer_reference, 'publication_content_sha256', publication_version.content_sha256, 'source_of_truth', 'contract_publication_versions')) AS canonical_metadata,
    public_offer.source_contract_offer_id,
    public_offer.lifecycle_status,
    public_offer.closed_at,
    public_offer.closed_by,
    public_offer.close_reason,
    COALESCE(NULLIF(lower(public_offer.energy_direction), ''::text), NULLIF(lower(publication_version.energy_direction), ''::text), 'consumption'::text) AS energy_direction,
    assignment.website_publication_allowed,
    true AS website_available_now
   FROM ((((((public.public_contract_offers public_offer
     JOIN public.contract_publication_versions publication_version ON (((publication_version.id = public_offer.contract_publication_version_id) AND (publication_version.status = 'published'::text) AND (publication_version.locked_at IS NOT NULL))))
     JOIN public.contract_publications publication ON (((publication.id = publication_version.contract_publication_id) AND (publication.channel = 'website'::text) AND (publication.status = 'published'::text))))
     JOIN public.tenant_contract_assignments assignment ON (((assignment.id = publication.assignment_id) AND (assignment.company_id = public_offer.company_id) AND (assignment.status = 'active'::text) AND assignment.website_publication_allowed AND (assignment.contract_product_version_id = publication_version.contract_product_version_id))))
     JOIN public.tenant_contract_channels channel ON (((channel.assignment_id = assignment.id) AND (channel.channel = 'website'::text) AND (channel.status = 'active'::text))))
     JOIN public.companies company ON (((company.id = assignment.company_id) AND (company.status = 'active'::text))))
     JOIN public.price_plan_versions price_plan_version ON (((price_plan_version.id = publication_version.price_plan_version_id) AND (price_plan_version.locked_at IS NOT NULL))))
  WHERE ((public_offer.publication_status = 'published'::text) AND (public_offer.lifecycle_status = 'published'::text) AND (public_offer.contract_product_version_id = publication_version.contract_product_version_id) AND ((publication_version.publication_snapshot ->> 'source_contract_offer_id'::text) = (public_offer.source_contract_offer_id)::text) AND (publication_version.content_sha256 = encode(extensions.digest((publication_version.publication_snapshot)::text, 'sha256'::text), 'hex'::text)) AND public_offer.website_enabled AND public_offer.website_cta_enabled AND public_offer.is_public AND (NOT public_offer.is_archived) AND ((public_offer.valid_from IS NULL) OR (public_offer.valid_from <= ((now() AT TIME ZONE 'Europe/Stockholm'::text))::date)) AND ((public_offer.valid_to IS NULL) OR (public_offer.valid_to >= ((now() AT TIME ZONE 'Europe/Stockholm'::text))::date)) AND ((channel.valid_from IS NULL) OR (channel.valid_from <= now())) AND ((channel.valid_to IS NULL) OR (channel.valid_to > now())) AND ((publication_version.valid_from IS NULL) OR (publication_version.valid_from <= now())) AND ((publication_version.valid_to IS NULL) OR (publication_version.valid_to > now())));

--
-- Name: VIEW canonical_public_contract_offers_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.canonical_public_contract_offers_v IS 'Canonical website offer projection. Uses an explicit compatibility column order and appends source lifecycle plus energy direction.';

