--
-- Name: contract_fixed_area_prices_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.contract_fixed_area_prices_v WITH (security_invoker='true') AS
 SELECT cpv.id AS contract_product_version_id,
    cpv.contract_product_id,
    cpv.contract_type,
    cpv.status AS contract_version_status,
    upper((component.value ->> 'price_area'::text)) AS price_area,
    (((component.value ->> 'fixed_price_sek_per_kwh'::text))::numeric * (100)::numeric) AS fixed_price_ore_per_kwh,
    component.value AS component_snapshot
   FROM (public.contract_product_versions cpv
     CROSS JOIN LATERAL jsonb_array_elements(
        CASE
            WHEN (jsonb_typeof((cpv.commercial_snapshot -> 'base_components'::text)) = 'array'::text) THEN (cpv.commercial_snapshot -> 'base_components'::text)
            WHEN (jsonb_typeof(((cpv.commercial_snapshot -> 'pricing_snapshot'::text) -> 'base_components'::text)) = 'array'::text) THEN ((cpv.commercial_snapshot -> 'pricing_snapshot'::text) -> 'base_components'::text)
            ELSE '[]'::jsonb
        END) component(value))
  WHERE ((COALESCE((component.value ->> 'source_type'::text), ''::text) = 'fixed'::text) AND (upper(COALESCE((component.value ->> 'price_area'::text), ''::text)) = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text])) AND (NULLIF((component.value ->> 'fixed_price_sek_per_kwh'::text), ''::text) IS NOT NULL));

