    sqlstate text,
    error_message text NOT NULL,
    error_detail text,
    error_hint text,
    blocker_relation text,
    request_id text,
    correlation_id text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

