--
-- Name: contract_publication_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.contract_publication_readiness_v WITH (security_invoker='true') AS
 WITH base AS (
         SELECT cpv.id AS contract_publication_version_id,
            a.company_id,
            a.id AS assignment_id,
            cpv.status,
            cpv.locked_at,
            cpv.valid_from,
            cpv.valid_to,
            cpv.price_plan_id,
            cpv.price_plan_version_id,
            cpv.price_book_id,
            cpv.legal_bundle_version_id,
            lbv.status AS legal_bundle_status,
            lbv.locked_at AS legal_bundle_locked_at,
            lbv.unresolved_variables,
            tlp.completeness_status AS legal_profile_status,
            COALESCE(tlp.review_required, false) AS legal_profile_review_required,
            pv.status AS contract_version_status,
            pv.required_legal_modules,
            COALESCE(( SELECT array_agg(DISTINCT d.module_key ORDER BY d.module_key) AS array_agg
                   FROM public.legal_bundle_version_documents d
                  WHERE (d.legal_bundle_version_id = lbv.id)), '{}'::text[]) AS included_legal_modules,
            cp.channel,
            COALESCE(tlp.missing_fields, ARRAY['tenant_legal_profile'::text]) AS legal_profile_missing_fields,
            pv.price_areas,
            pv.contract_type,
            pp.id AS plan_found,
            pp.status AS plan_status,
            pp.pricing_model,
            ppv.id AS version_found,
            ppv.status AS version_status,
            ppv.locked_at AS price_version_locked_at,
            ppv.snapshot_json AS price_version_snapshot,
            pco.invoice_fee_sek AS invoice_fee_row_amount,
                CASE
                    WHEN (cp.channel = 'website'::text) THEN public.gridex_invoice_fee_readiness(ppv.snapshot_json, pco.invoice_fee_sek)
                    ELSE public.gridex_invoice_fee_snapshot_readiness(ppv.snapshot_json)
                END AS invoice_fee_readiness,
            pb.id AS book_found,
            pb.status AS book_status,
            pb.locked_at AS price_book_locked_at,
            (EXISTS ( SELECT 1
                   FROM public.integration_api_clients i
                  WHERE ((i.company_id = a.company_id) AND (i.status = 'active'::text) AND (i.scopes @> ARRAY['website_contracts.read'::text])))) AS has_website_read_scope,
            (EXISTS ( SELECT 1
                   FROM public.integration_api_clients i
                  WHERE ((i.company_id = a.company_id) AND (i.status = 'active'::text) AND (i.scopes @> ARRAY['website_applications.write'::text])))) AS has_website_write_scope
           FROM (((((((((public.contract_publication_versions cpv
             JOIN public.contract_publications cp ON ((cp.id = cpv.contract_publication_id)))
             JOIN public.tenant_contract_assignments a ON ((a.id = cp.assignment_id)))
             JOIN public.contract_product_versions pv ON ((pv.id = cpv.contract_product_version_id)))
             LEFT JOIN public.legal_bundle_versions lbv ON (((lbv.id = cpv.legal_bundle_version_id) AND (lbv.company_id = a.company_id))))
             LEFT JOIN public.tenant_legal_profiles tlp ON ((tlp.company_id = a.company_id)))
             LEFT JOIN public.price_plans pp ON (((pp.id = cpv.price_plan_id) AND (pp.company_id = a.company_id))))
             LEFT JOIN public.price_plan_versions ppv ON (((ppv.id = cpv.price_plan_version_id) AND (ppv.company_id = a.company_id) AND (ppv.price_plan_id = cpv.price_plan_id))))
             LEFT JOIN public.public_contract_offers pco ON (((pco.contract_publication_version_id = cpv.id) AND (pco.company_id = a.company_id))))
             LEFT JOIN public.price_books pb ON (((pb.id = cpv.price_book_id) AND (pb.company_id = a.company_id) AND (pb.price_plan_version_id = cpv.price_plan_version_id))))
        ), calculated AS (
         SELECT b.contract_publication_version_id,
            b.company_id,
            b.assignment_id,
            b.status,
            b.locked_at,
            b.valid_from,
            b.valid_to,
            b.price_plan_id,
            b.price_plan_version_id,
            b.price_book_id,
            b.legal_bundle_version_id,
            b.legal_bundle_status,
            b.legal_bundle_locked_at,
            b.unresolved_variables,
            b.legal_profile_status,
            b.legal_profile_review_required,
            b.contract_version_status,
            b.required_legal_modules,
            b.included_legal_modules,
            b.channel,
            b.legal_profile_missing_fields,
            b.price_areas,
            b.contract_type,
            b.plan_found,
            b.plan_status,
            b.pricing_model,
            b.version_found,
            b.version_status,
            b.price_version_locked_at,
            b.price_version_snapshot,
            b.invoice_fee_row_amount,
            b.invoice_fee_readiness,
            b.book_found,
            b.book_status,
            b.price_book_locked_at,
            b.has_website_read_scope,
            b.has_website_write_scope,
            (array_remove(ARRAY[
                CASE
                    WHEN (b.legal_profile_status IS NULL) THEN 'tenant_legal_profile_missing'::text
                    WHEN (b.legal_profile_status <> ALL (ARRAY['complete'::text, 'verified'::text])) THEN 'tenant_legal_profile_incomplete'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN b.legal_profile_review_required THEN 'tenant_legal_profile_review_required'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (b.contract_version_status <> 'approved'::text) THEN 'contract_version_not_approved'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (COALESCE(array_length(b.price_areas, 1), 0) = 0) THEN 'price_areas_missing'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (EXISTS ( SELECT 1
                       FROM unnest(COALESCE(b.price_areas, '{}'::text[])) area(area)
                      WHERE (area.area <> ALL (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text])))) THEN 'price_area_invalid'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((b.plan_found IS NULL) OR (b.plan_status <> ALL (ARRAY['active'::text, 'published'::text, 'approved'::text]))) THEN 'price_plan_not_active'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((b.version_found IS NULL) OR (b.version_status <> ALL (ARRAY['active'::text, 'published'::text, 'approved'::text])) OR (b.price_version_locked_at IS NULL)) THEN 'price_plan_version_not_locked'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((b.book_found IS NULL) OR (b.book_status <> ALL (ARRAY['active'::text, 'published'::text])) OR (b.price_book_locked_at IS NULL)) THEN 'price_book_not_locked'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((b.legal_bundle_version_id IS NULL) OR (b.legal_bundle_status <> 'published'::text) OR (b.legal_bundle_locked_at IS NULL)) THEN 'legal_bundle_not_locked'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN (COALESCE(array_length(b.unresolved_variables, 1), 0) > 0) THEN 'unresolved_legal_variables'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((b.valid_from IS NOT NULL) AND (b.valid_to IS NOT NULL) AND (b.valid_to < b.valid_from)) THEN 'invalid_validity_period'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((b.contract_type = ANY (ARRAY['portfolio'::text, 'mixed'::text])) AND (COALESCE((b.price_version_snapshot #>> '{portfolio_method,pricing_model}'::text[]), ''::text) <> 'portfolio_monthly_settlement'::text)) THEN 'portfolio_settlement_method_missing'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((b.contract_type = ANY (ARRAY['portfolio'::text, 'mixed'::text])) AND (NOT (EXISTS ( SELECT 1
                       FROM public.portfolios p
                      WHERE ((p.company_id = b.company_id) AND (p.status = 'active'::text) AND ((p.id)::text = COALESCE((b.price_version_snapshot #>> '{portfolio_method,portfolio_id}'::text[]), ''::text))))))) THEN 'portfolio_scope_missing_or_invalid'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((b.contract_type = ANY (ARRAY['portfolio'::text, 'mixed'::text])) AND (NULLIF((b.price_version_snapshot #>> '{portfolio_method,settlement_timing}'::text[]), ''::text) IS NULL)) THEN 'portfolio_settlement_timing_missing'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((b.contract_type = ANY (ARRAY['portfolio'::text, 'mixed'::text])) AND (NULLIF((b.price_version_snapshot #>> '{portfolio_method,estimate_rule}'::text[]), ''::text) IS NULL)) THEN 'portfolio_estimate_rule_missing'::text
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((b.channel = ANY (ARRAY['website'::text, 'api'::text])) AND (COALESCE((b.invoice_fee_readiness ->> 'status'::text), 'blocked'::text) <> 'ready'::text)) THEN COALESCE((b.invoice_fee_readiness ->> 'code'::text), 'invoice_fee_missing'::text)
                    ELSE NULL::text
                END,
                CASE
                    WHEN ((b.contract_type = 'mixed'::text) AND (COALESCE(( SELECT sum(COALESCE(((component.value ->> 'weight_percent'::text))::numeric, (0)::numeric)) AS sum
                       FROM jsonb_array_elements(COALESCE((b.price_version_snapshot -> 'base_components'::text), '[]'::jsonb)) component(value)), (0)::numeric) <> (100)::numeric)) THEN 'mixed_price_shares_must_equal_100'::text
                    ELSE NULL::text
                END], NULL::text) || COALESCE(ARRAY( SELECT ('missing_legal_module:'::text || module_key.module_key)
                   FROM unnest(COALESCE(b.required_legal_modules, '{}'::text[])) module_key(module_key)
                  WHERE (NOT (module_key.module_key = ANY (b.included_legal_modules)))), '{}'::text[])) AS core_blockers
           FROM base b
        ), readiness AS (
         SELECT c.contract_publication_version_id,
            c.company_id,
            c.assignment_id,
            c.status,
            c.locked_at,
            c.valid_from,
            c.valid_to,
            c.price_plan_id,
            c.price_plan_version_id,
            c.price_book_id,
            c.legal_bundle_version_id,
            c.legal_bundle_status,
            c.legal_bundle_locked_at,
            c.unresolved_variables,
            c.legal_profile_status,
            c.legal_profile_review_required,
            c.contract_version_status,
            c.required_legal_modules,
            c.included_legal_modules,
            c.channel,
            c.legal_profile_missing_fields,
            c.price_areas,
            c.contract_type,
            c.plan_found,
            c.plan_status,
            c.pricing_model,
            c.version_found,
            c.version_status,
            c.price_version_locked_at,
            c.price_version_snapshot,
            c.invoice_fee_row_amount,
            c.invoice_fee_readiness,
            c.book_found,
            c.book_status,
            c.price_book_locked_at,
            c.has_website_read_scope,
            c.has_website_write_scope,
            c.core_blockers,
            (c.core_blockers ||
                CASE
                    WHEN ((c.channel = ANY (ARRAY['website'::text, 'api'::text])) AND (NOT c.has_website_read_scope)) THEN ARRAY['website_contracts_read_scope_missing'::text]
                    ELSE '{}'::text[]
                END) AS display_blockers,
            ((c.core_blockers ||
                CASE
                    WHEN ((c.channel = ANY (ARRAY['website'::text, 'api'::text])) AND (NOT c.has_website_read_scope)) THEN ARRAY['website_contracts_read_scope_missing'::text]
                    ELSE '{}'::text[]
                END) ||
                CASE
                    WHEN ((c.channel = ANY (ARRAY['website'::text, 'api'::text])) AND (NOT c.has_website_write_scope)) THEN ARRAY['website_applications_write_scope_missing'::text]
                    ELSE '{}'::text[]
                END) AS application_blockers
           FROM calculated c
        )
 SELECT contract_publication_version_id,
    company_id,
    assignment_id,
    status,
    locked_at,
    valid_from,
    valid_to,
    price_plan_id,
    price_plan_version_id,
    price_book_id,
    legal_bundle_version_id,
    legal_bundle_status,
    legal_bundle_locked_at,
    unresolved_variables,
    legal_profile_status,
    contract_version_status,
    required_legal_modules,
    included_legal_modules,
    core_blockers AS blockers,
    channel,
    legal_profile_missing_fields,
    legal_profile_review_required,
    display_blockers,
    application_blockers,
        CASE
            WHEN (legal_profile_status IS NULL) THEN 'unknown'::text
            WHEN (COALESCE(array_length(core_blockers, 1), 0) > 0) THEN 'blocked'::text
            ELSE 'ready'::text
        END AS readiness_status,
    (COALESCE(array_length(display_blockers, 1), 0) = 0) AS can_display,
    (COALESCE(array_length(application_blockers, 1), 0) = 0) AS can_accept_applications,
    has_website_read_scope,
    has_website_write_scope,
    invoice_fee_readiness
   FROM readiness r;

--
-- Name: VIEW contract_publication_readiness_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.contract_publication_readiness_v IS 'Publication readiness validates immutable legal, pricing and invoice-fee state. invoice_fee_missing/conflict/ambiguous block publication and applications; zero remains valid.';

