    CONSTRAINT customer_legal_acceptances_admin_reason_chk CHECK (((source <> 'admin_manual'::text) OR (NULLIF(btrim(COALESCE(reason, ''::text)), ''::text) IS NOT NULL))),
    CONSTRAINT customer_legal_acceptances_exact_document_check CHECK (((legal_bundle_version_document_id IS NULL) OR ((legal_text_version_id IS NULL) AND (NULLIF(btrim(legal_module_key), ''::text) IS NOT NULL) AND (NULLIF(btrim(legal_document_version), ''::text) IS NOT NULL) AND (legal_document_sha256 ~ '^[0-9a-f]{64}$'::text)))),
    CONSTRAINT customer_legal_acceptances_source_check CHECK ((source = ANY (ARRAY['website'::text, 'customer_portal'::text, 'admin_manual'::text])))
);

