--
-- Name: customer_contract_lifecycle_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.customer_contract_lifecycle_readiness_v WITH (security_invoker='true') AS
 WITH evidence AS (
         SELECT c.id,
            c.company_id,
            c.customer_id,
            c.site_id,
            c.metering_point_id,
            c.customer_site_id,
            c.contract_offer_id,
            c.source_type,
            c.status,
            c.contract_name,
            c.contract_type,
            c.campaign_name,
            c.campaign_code,
            c.campaign_version,
            c.price_version,
            c.terms_version,
            c.contract_version,
            c.signed_version,
            c.terms_signed_version,
            c.version_snapshot,
            c.start_status,
            c.old_supplier_start_at,
            c.grid_owner_confirmed_start_at,
            c.ediel_confirmed_start_at,
            c.export_blocked,
            c.export_block_reason,
            c.price_snapshot,
            c.campaign_snapshot,
            c.billing_ready_status,
            c.billing_blocker_reasons,
            c.withdrawal_requested_at,
            c.rejected_reason,
            c.fixed_price_ore_per_kwh,
            c.spot_markup_ore_per_kwh,
            c.variable_fee_ore_per_kwh,
            c.monthly_fee_sek,
            c.green_fee_mode,
            c.green_fee_value,
            c.binding_months,
            c.notice_months,
            c.optional_fee_lines,
            c.starts_at,
            c.expected_start_at,
            c.confirmed_start_at,
            c.actual_start_at,
            c.start_date_source,
            c.ends_at,
            c.signed_at,
            c.termination_notice_date,
            c.termination_reason,
            c.auto_renew_enabled,
            c.auto_renew_term_months,
            c.override_reason,
            c.invoice_recipient,
            c.invoice_email,
            c.invoice_reference,
            c.billing_street,
            c.billing_postal_code,
            c.billing_city,
            c.billing_country,
            c.billing_address_same_as_site,
            c.billing_level,
            c.consolidated_invoice,
            c.metadata,
            c.created_at,
            c.updated_at,
            c.created_by,
            c.updated_by,
            c.requested_start_mode,
            c.calculated_earliest_start_date,
            c.price_area_used,
            c.grid_area_code_used,
            c.resolution_status,
            c.onboarding_status,
            c.onboarding_issues,
            c.requested_start_date,
            c.confirmed_start_date,
            c.actual_start_date,
            c.agreement_channel,
            c.contract_number,
            c.price_plan_id,
            c.price_plan_version_id,
            c.invoice_fee_sek,
            c.markup_ore_per_kwh,
            c.contract_price_snapshot_id,
            c.legal_acceptance_snapshot,
            c.legal_readiness_status,
            c.legal_readiness_reasons,
            c.application_snapshot,
            c.website_application_id,
            c.legal_bundle_id,
            c.price_book_id,
            c.snapshot_quality,
            c.snapshot_hash,
            c.billing_blocked_reason,
            c.customer_number,
            c.external_customer_id,
            c.public_contract_offer_id,
            c.offer_reference,
            c.legal_versions_snapshot,
            c.signature_snapshot,
            c.signature_snapshot_sha256,
            c.signed_ip_hash,
            c.signed_user_agent,
            c.contract_product_id,
            c.contract_product_version_id,
            c.contract_publication_version_id,
            c.legal_bundle_version_id,
            c.commercial_snapshot,
            c.legal_snapshot,
            c.document_sha256,
            c.locked_at,
            c.tenant_communication_snapshot,
            c.tenant_communication_snapshot_sha256,
            c.tenant_legal_party_snapshot,
            c.lifecycle_stage,
            ( SELECT count(*) AS count
                   FROM public.legal_bundle_version_documents d
                  WHERE (d.legal_bundle_version_id = c.legal_bundle_version_id)) AS legal_document_count,
            ( SELECT count(DISTINCT a.legal_bundle_version_document_id) AS count
                   FROM public.customer_legal_acceptances a
                  WHERE ((a.company_id = c.company_id) AND (a.customer_id = c.customer_id) AND (a.contract_id = c.id) AND (a.legal_bundle_version_document_id IS NOT NULL))) AS accepted_document_count,
            (EXISTS ( SELECT 1
                   FROM public.customer_contract_documents d
                  WHERE ((d.company_id = c.company_id) AND (d.customer_contract_id = c.id) AND (d.document_type = 'signed_contract_pdf'::text) AND (d.storage_path IS NOT NULL) AND (d.archived_at IS NOT NULL) AND (d.verified_at IS NOT NULL) AND (d.document_sha256 = c.document_sha256)))) AS signed_pdf_archived,
            (EXISTS ( SELECT 1
                   FROM public.customer_sites s
                  WHERE ((s.id = COALESCE(c.customer_site_id, c.site_id)) AND (s.company_id = c.company_id) AND (s.customer_id = c.customer_id) AND (NULLIF(s.facility_id, ''::text) IS NOT NULL) AND (s.grid_owner_id IS NOT NULL) AND (NULLIF(s.grid_area_code, ''::text) IS NOT NULL) AND (s.price_area_code = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text])) AND (s.status <> ALL (ARRAY['inactive'::text, 'closed'::text]))))) AS facility_data_ready,
            (EXISTS ( SELECT 1
                   FROM public.metering_points m
                  WHERE ((m.id = COALESCE(c.metering_point_id, m.id)) AND (m.site_id = COALESCE(c.customer_site_id, c.site_id)) AND (m.company_id = c.company_id) AND (m.customer_id = c.customer_id) AND (NULLIF(COALESCE(m.meter_point_id, m.metering_point_id), ''::text) IS NOT NULL) AND (m.grid_owner_id IS NOT NULL) AND (m.price_area_code = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text])) AND (m.status <> ALL (ARRAY['inactive'::text, 'closed'::text]))))) AS metering_data_ready,
            (EXISTS ( SELECT 1
                   FROM public.powers_of_attorney p
                  WHERE ((p.company_id = c.company_id) AND (p.customer_id = c.customer_id) AND (COALESCE(p.contract_id, p.customer_contract_id) = c.id) AND (COALESCE(p.customer_site_id, p.site_id) = COALESCE(c.customer_site_id, c.site_id)) AND (p.status = ANY (ARRAY['signed'::text, 'active'::text, 'accepted'::text])) AND (COALESCE(p.accepted_at, p.signed_at) IS NOT NULL) AND (p.revoked_at IS NULL) AND ((COALESCE(p.valid_until, p.valid_to) IS NULL) OR (COALESCE(p.valid_until, p.valid_to) >= CURRENT_DATE))))) AS valid_power_of_attorney,
            (COALESCE(c.requested_start_date, c.expected_start_at, c.starts_at) IS NOT NULL) AS start_date_ready
           FROM public.customer_contracts c
        ), stages AS (
         SELECT e.id,
            e.company_id,
            e.customer_id,
            e.site_id,
            e.metering_point_id,
            e.customer_site_id,
            e.contract_offer_id,
            e.source_type,
            e.status,
            e.contract_name,
            e.contract_type,
            e.campaign_name,
            e.campaign_code,
            e.campaign_version,
            e.price_version,
            e.terms_version,
            e.contract_version,
            e.signed_version,
            e.terms_signed_version,
            e.version_snapshot,
            e.start_status,
            e.old_supplier_start_at,
            e.grid_owner_confirmed_start_at,
            e.ediel_confirmed_start_at,
            e.export_blocked,
            e.export_block_reason,
            e.price_snapshot,
            e.campaign_snapshot,
            e.billing_ready_status,
            e.billing_blocker_reasons,
            e.withdrawal_requested_at,
            e.rejected_reason,
            e.fixed_price_ore_per_kwh,
            e.spot_markup_ore_per_kwh,
            e.variable_fee_ore_per_kwh,
            e.monthly_fee_sek,
            e.green_fee_mode,
            e.green_fee_value,
            e.binding_months,
            e.notice_months,
            e.optional_fee_lines,
            e.starts_at,
            e.expected_start_at,
            e.confirmed_start_at,
            e.actual_start_at,
            e.start_date_source,
            e.ends_at,
            e.signed_at,
            e.termination_notice_date,
            e.termination_reason,
            e.auto_renew_enabled,
            e.auto_renew_term_months,
            e.override_reason,
            e.invoice_recipient,
            e.invoice_email,
            e.invoice_reference,
            e.billing_street,
            e.billing_postal_code,
            e.billing_city,
            e.billing_country,
            e.billing_address_same_as_site,
            e.billing_level,
            e.consolidated_invoice,
            e.metadata,
            e.created_at,
            e.updated_at,
            e.created_by,
            e.updated_by,
            e.requested_start_mode,
            e.calculated_earliest_start_date,
            e.price_area_used,
            e.grid_area_code_used,
            e.resolution_status,
            e.onboarding_status,
            e.onboarding_issues,
            e.requested_start_date,
            e.confirmed_start_date,
            e.actual_start_date,
            e.agreement_channel,
            e.contract_number,
            e.price_plan_id,
            e.price_plan_version_id,
            e.invoice_fee_sek,
            e.markup_ore_per_kwh,
            e.contract_price_snapshot_id,
            e.legal_acceptance_snapshot,
            e.legal_readiness_status,
            e.legal_readiness_reasons,
            e.application_snapshot,
            e.website_application_id,
            e.legal_bundle_id,
            e.price_book_id,
            e.snapshot_quality,
            e.snapshot_hash,
            e.billing_blocked_reason,
            e.customer_number,
            e.external_customer_id,
            e.public_contract_offer_id,
            e.offer_reference,
            e.legal_versions_snapshot,
            e.signature_snapshot,
            e.signature_snapshot_sha256,
            e.signed_ip_hash,
            e.signed_user_agent,
            e.contract_product_id,
            e.contract_product_version_id,
            e.contract_publication_version_id,
            e.legal_bundle_version_id,
            e.commercial_snapshot,
            e.legal_snapshot,
            e.document_sha256,
            e.locked_at,
            e.tenant_communication_snapshot,
            e.tenant_communication_snapshot_sha256,
            e.tenant_legal_party_snapshot,
            e.lifecycle_stage,
            e.legal_document_count,
            e.accepted_document_count,
            e.signed_pdf_archived,
            e.facility_data_ready,
            e.metering_data_ready,
            e.valid_power_of_attorney,
            e.start_date_ready,
            ((e.contract_publication_version_id IS NOT NULL) AND (e.contract_product_version_id IS NOT NULL) AND (e.price_plan_version_id IS NOT NULL) AND (e.legal_bundle_version_id IS NOT NULL) AND (e.contract_price_snapshot_id IS NOT NULL)) AS agreement_ready,
            ((e.status = 'signed'::text) AND (e.signed_at IS NOT NULL) AND (NULLIF(e.signature_snapshot_sha256, ''::text) IS NOT NULL) AND (e.legal_document_count > 0) AND (e.accepted_document_count = e.legal_document_count)) AS agreement_signed
           FROM evidence e
        ), readiness AS (
         SELECT s.id,
            s.company_id,
            s.customer_id,
            s.site_id,
            s.metering_point_id,
            s.customer_site_id,
            s.contract_offer_id,
            s.source_type,
            s.status,
            s.contract_name,
            s.contract_type,
            s.campaign_name,
            s.campaign_code,
            s.campaign_version,
            s.price_version,
            s.terms_version,
            s.contract_version,
            s.signed_version,
            s.terms_signed_version,
            s.version_snapshot,
            s.start_status,
            s.old_supplier_start_at,
            s.grid_owner_confirmed_start_at,
            s.ediel_confirmed_start_at,
            s.export_blocked,
            s.export_block_reason,
            s.price_snapshot,
            s.campaign_snapshot,
            s.billing_ready_status,
            s.billing_blocker_reasons,
            s.withdrawal_requested_at,
            s.rejected_reason,
            s.fixed_price_ore_per_kwh,
            s.spot_markup_ore_per_kwh,
            s.variable_fee_ore_per_kwh,
            s.monthly_fee_sek,
            s.green_fee_mode,
            s.green_fee_value,
            s.binding_months,
            s.notice_months,
            s.optional_fee_lines,
            s.starts_at,
            s.expected_start_at,
            s.confirmed_start_at,
            s.actual_start_at,
            s.start_date_source,
            s.ends_at,
            s.signed_at,
            s.termination_notice_date,
            s.termination_reason,
            s.auto_renew_enabled,
            s.auto_renew_term_months,
            s.override_reason,
            s.invoice_recipient,
            s.invoice_email,
            s.invoice_reference,
            s.billing_street,
            s.billing_postal_code,
            s.billing_city,
            s.billing_country,
            s.billing_address_same_as_site,
            s.billing_level,
            s.consolidated_invoice,
            s.metadata,
            s.created_at,
            s.updated_at,
            s.created_by,
            s.updated_by,
            s.requested_start_mode,
            s.calculated_earliest_start_date,
            s.price_area_used,
            s.grid_area_code_used,
            s.resolution_status,
            s.onboarding_status,
            s.onboarding_issues,
            s.requested_start_date,
            s.confirmed_start_date,
            s.actual_start_date,
            s.agreement_channel,
            s.contract_number,
            s.price_plan_id,
            s.price_plan_version_id,
            s.invoice_fee_sek,
            s.markup_ore_per_kwh,
            s.contract_price_snapshot_id,
            s.legal_acceptance_snapshot,
            s.legal_readiness_status,
            s.legal_readiness_reasons,
            s.application_snapshot,
            s.website_application_id,
            s.legal_bundle_id,
            s.price_book_id,
            s.snapshot_quality,
            s.snapshot_hash,
            s.billing_blocked_reason,
            s.customer_number,
            s.external_customer_id,
            s.public_contract_offer_id,
            s.offer_reference,
            s.legal_versions_snapshot,
            s.signature_snapshot,
            s.signature_snapshot_sha256,
            s.signed_ip_hash,
            s.signed_user_agent,
            s.contract_product_id,
            s.contract_product_version_id,
            s.contract_publication_version_id,
            s.legal_bundle_version_id,
            s.commercial_snapshot,
            s.legal_snapshot,
            s.document_sha256,
            s.locked_at,
            s.tenant_communication_snapshot,
            s.tenant_communication_snapshot_sha256,
            s.tenant_legal_party_snapshot,
            s.lifecycle_stage,
            s.legal_document_count,
            s.accepted_document_count,
            s.signed_pdf_archived,
            s.facility_data_ready,
            s.metering_data_ready,
            s.valid_power_of_attorney,
            s.start_date_ready,
            s.agreement_ready,
            s.agreement_signed,
            (s.facility_data_ready AND s.metering_data_ready) AS switch_data_ready,
            (s.agreement_ready AND s.agreement_signed AND s.facility_data_ready AND s.metering_data_ready AND s.signed_pdf_archived AND s.valid_power_of_attorney AND s.start_date_ready AND (COALESCE(s.withdrawal_requested_at, '-infinity'::timestamp with time zone) = '-infinity'::timestamp with time zone) AND (COALESCE(s.export_blocked, false) = false)) AS switch_ready
           FROM stages s
        )
 SELECT id AS customer_contract_id,
    company_id,
    customer_id,
    COALESCE(customer_site_id, site_id) AS customer_site_id,
    metering_point_id,
    agreement_ready,
    agreement_signed,
    facility_data_ready,
    switch_data_ready,
    switch_ready,
    (agreement_signed AND (contract_price_snapshot_id IS NOT NULL)) AS billing_ready,
    ((status = 'active'::text) AND (actual_start_at IS NOT NULL)) AS active,
    signed_pdf_archived,
    valid_power_of_attorney,
    start_date_ready,
    legal_document_count,
    accepted_document_count,
        CASE
            WHEN ((status = 'active'::text) AND (actual_start_at IS NOT NULL)) THEN 'active'::text
            WHEN (agreement_signed AND (contract_price_snapshot_id IS NOT NULL)) THEN
            CASE
                WHEN switch_ready THEN 'switch_ready'::text
                ELSE
                CASE
                    WHEN switch_data_ready THEN 'switch_data_ready'::text
                    ELSE
                    CASE
                        WHEN facility_data_ready THEN 'facility_data_ready'::text
                        ELSE 'agreement_signed'::text
                    END
                END
            END
            ELSE 'agreement_ready'::text
        END AS lifecycle_stage,
    array_remove(ARRAY[
        CASE
            WHEN (NOT agreement_ready) THEN 'agreement_not_canonically_bound'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT agreement_signed) THEN 'agreement_not_signed_with_exact_evidence'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT facility_data_ready) THEN 'facility_data_not_ready'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT metering_data_ready) THEN 'metering_data_not_ready'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT signed_pdf_archived) THEN 'signed_pdf_not_archived_or_hash_mismatch'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT valid_power_of_attorney) THEN 'valid_power_of_attorney_missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (NOT start_date_ready) THEN 'contract_start_date_missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (withdrawal_requested_at IS NOT NULL) THEN 'withdrawal_requested'::text
            ELSE NULL::text
        END,
        CASE
            WHEN COALESCE(export_blocked, false) THEN 'contract_export_blocked'::text
            ELSE NULL::text
        END], NULL::text) AS blockers
   FROM readiness r;

