    source text DEFAULT 'customer_operations'::text NOT NULL,
    visibility text DEFAULT 'tenant'::text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    idempotency_key text,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT customer_operation_events_severity_check CHECK ((severity = ANY (ARRAY['info'::text, 'warning'::text, 'error'::text, 'critical'::text]))),
    CONSTRAINT customer_operation_events_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'in_progress'::text, 'waiting_response'::text, 'response_received'::text, 'completed'::text, 'needs_review'::text, 'failed'::text, 'blocked'::text, 'skipped'::text, 'cancelled'::text]))),
    CONSTRAINT customer_operation_events_visibility_check CHECK ((visibility = ANY (ARRAY['tenant'::text, 'platform'::text])))
);

