--
-- Name: ediel_active_actor_settings_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ediel_active_actor_settings_v WITH (security_invoker='true') AS
 SELECT id,
    company_id,
    actor_name,
    actor_ediel_id,
    actor_role,
    environment,
    is_active,
    sender_name,
    sender_sub_address,
    default_application_reference,
    default_timezone,
    default_charset,
    default_test_flag,
    smtp_from_email,
    smtp_reply_to_email,
    mailbox,
    brp_name,
    brp_ediel_id,
    brp_status,
    esett_status,
    valid_from,
    valid_to,
    notes,
    metadata,
    created_at,
    updated_at,
    created_by,
    updated_by
   FROM public.ediel_actor_settings
  WHERE ((COALESCE(is_active, true) = true) AND ((valid_from IS NULL) OR (valid_from <= CURRENT_DATE)) AND ((valid_to IS NULL) OR (valid_to >= CURRENT_DATE)));

