--
-- Name: grid_owner_supplier_switch_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.grid_owner_supplier_switch_readiness_v WITH (security_invoker='true') AS
 SELECT r.platform_market_actor_id,
    g.id AS grid_owner_id,
    g.company_id,
    COALESCE(g.name, r.actor_name) AS actor_name,
    r.legal_name,
    COALESCE(g.org_number, r.org_number) AS org_number,
    COALESCE(g.ediel_id, r.ediel_id) AS ediel_id,
    r.roles,
    r.has_grid_owner_role,
    r.is_electricity_grid_owner_scope,
    r.is_gas_actor,
    r.is_dummy_or_test_actor,
    r.is_system_supplier_only,
    r.electricity_scope_status,
    r.supplier_switch_readiness_status,
    r.has_prodat_route,
    r.has_safe_subaddress,
    r.has_contact_path,
    r.has_valid_prodat_certificate,
    r.open_blocking_conflicts,
    r.can_use_for_prodat,
    r.can_use_for_utilts,
    r.can_start_supplier_switch,
    r.blocking_reasons,
    r.manual_review_required,
    r.manual_review_reason,
    ('missing_or_invalid_certificate'::text = ANY (r.blocking_reasons)) AS missing_or_invalid_certificate,
    ('missing_prodat_route'::text = ANY (r.blocking_reasons)) AS missing_prodat_route,
    ('unsafe_or_missing_subaddress'::text = ANY (r.blocking_reasons)) AS unsafe_or_missing_subaddress,
    ('missing_contact_path'::text = ANY (r.blocking_reasons)) AS missing_contact_path,
    ('missing_ediel_id'::text = ANY (r.blocking_reasons)) AS missing_ediel_id,
    r.checked_at
   FROM (public.actor_readiness_status r
     LEFT JOIN public.grid_owners g ON ((g.platform_market_actor_id = r.platform_market_actor_id)))
  WHERE (r.has_grid_owner_role = true);

--
-- Name: ediel_blocked_grid_owner_certificate_refresh_candidates_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ediel_blocked_grid_owner_certificate_refresh_candidates_v WITH (security_invoker='true') AS
 WITH route_candidates AS (
         SELECT DISTINCT ON (r.actor_id) r.actor_id AS platform_market_actor_id,
            r.id AS route_id,
            g.id AS grid_owner_id,
            g.company_id,
            COALESCE(g.ediel_id, ar.ediel_id, ids.ediel_id) AS ediel_id,
            r.communication_address AS smtp_email,
            r.subaddress,
            r.environment,
            c.status AS certificate_status,
            c.next_check_at AS certificate_next_check_at,
            c.fingerprint_sha256 AS certificate_fingerprint_sha256
           FROM ((((public.platform_actor_routes r
             JOIN public.grid_owner_supplier_switch_readiness_v ar ON ((ar.platform_market_actor_id = r.actor_id)))
             LEFT JOIN public.grid_owners g ON ((g.platform_market_actor_id = r.actor_id)))
             LEFT JOIN ( SELECT platform_actor_identifiers.actor_id,
                    max(platform_actor_identifiers.identifier_value) FILTER (WHERE (lower(platform_actor_identifiers.identifier_type) = ANY (ARRAY['edielid'::text, 'ediel_id'::text, 'ediel'::text]))) AS ediel_id
                   FROM public.platform_actor_identifiers
                  GROUP BY platform_actor_identifiers.actor_id) ids ON ((ids.actor_id = r.actor_id)))
             LEFT JOIN public.platform_actor_certificates c ON (((c.actor_id = r.actor_id) AND (c.environment = COALESCE(r.environment, 'production'::text)) AND (c.purpose = 'encryption'::text))))
          WHERE ((ar.is_electricity_grid_owner_scope = true) AND (ar.missing_or_invalid_certificate = true) AND (ar.has_prodat_route = true) AND (ar.has_contact_path = true) AND (upper(r.message_family) = 'PRODAT'::text) AND (COALESCE(r.environment, 'production'::text) = 'production'::text) AND (COALESCE(r.status, ''::text) = 'active'::text) AND (NULLIF(btrim(COALESCE(r.communication_address, ''::text)), ''::text) IS NOT NULL) AND ((NULLIF(btrim(COALESCE(r.subaddress, ''::text)), ''::text) IS NOT NULL) OR (COALESCE((r.metadata ->> 'subaddress_status'::text), ''::text) = 'not_required_confirmed'::text)) AND (upper(COALESCE(r.subaddress, ''::text)) <> 'GAS'::text))
          ORDER BY r.actor_id,
                CASE
                    WHEN (c.next_check_at IS NULL) THEN 0
                    ELSE 1
                END, c.next_check_at NULLS FIRST, r.updated_at DESC
        )
 SELECT platform_market_actor_id,
    route_id,
    grid_owner_id,
    company_id,
    ediel_id,
    smtp_email,
    subaddress,
    'production'::text AS environment,
    'PRODAT'::text AS message_family,
    certificate_status,
    certificate_next_check_at,
    certificate_fingerprint_sha256
   FROM route_candidates;

