--
-- Name: ediel_duplicate_ack_candidates_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ediel_duplicate_ack_candidates_v WITH (security_invoker='true') AS
 SELECT company_id,
    related_message_id,
    message_family AS ack_family,
    transaction_reference,
    count(*) AS duplicate_count,
    array_agg(id ORDER BY created_at) AS message_ids
   FROM public.ediel_messages
  WHERE ((related_message_id IS NOT NULL) AND (message_family = ANY (ARRAY['APERAK'::text, 'CONTRL'::text, 'UTILTS_ERR'::text])))
  GROUP BY company_id, related_message_id, message_family, transaction_reference
 HAVING (count(*) > 1);

