--
-- Name: ediel_rule_ambiguities_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.ediel_rule_ambiguities_v WITH (security_invoker='true') AS
 SELECT company_id,
    message_family,
    message_code,
    message_standard,
    version_code,
    direction,
    count(*) AS rule_count
   FROM public.ediel_message_rules
  WHERE (COALESCE(is_active, true) = true)
  GROUP BY company_id, message_family, message_code, message_standard, version_code, direction
 HAVING (count(*) > 1);

