    CONSTRAINT grid_owner_information_requests_channel_check CHECK ((channel = ANY (ARRAY['email'::text, 'ediel'::text, 'portal'::text, 'manual'::text, 'manual_email'::text, 'ediel_prodat'::text, 'manual_phone'::text, 'ai_list'::text, 'manual_upload'::text]))),
    CONSTRAINT grid_owner_information_requests_dispatch_status_check CHECK ((dispatch_status = ANY (ARRAY['not_started'::text, 'ready'::text, 'blocked'::text, 'queued'::text, 'sent'::text, 'waiting_response'::text, 'response_received'::text, 'completed'::text, 'failed'::text, 'skipped'::text]))),
    CONSTRAINT grid_owner_information_requests_price_area_check CHECK (((price_area IS NULL) OR (price_area = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text])))),
    CONSTRAINT grid_owner_information_requests_request_type_check CHECK ((request_type = ANY (ARRAY['facility_lookup'::text, 'metering_point_lookup'::text, 'grid_area_confirmation'::text, 'metering_values_request'::text, 'switch_prerequisite_check'::text, 'facility_identifier_lookup'::text, 'supplier_switch_manual'::text, 'grid_contract_information'::text, 'ai_list_request'::text]))),
    CONSTRAINT grid_owner_information_requests_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'ready_to_send'::text, 'sent'::text, 'waiting_response'::text, 'received'::text, 'completed'::text, 'failed'::text, 'needs_review'::text, 'facility_data_invalid'::text, 'customer_information_mismatch'::text, 'grid_owner_rejected_request'::text, 'negative_aperak_received'::text, 'z02_rejected'::text, 'needs_customer_correction'::text, 'needs_grid_owner_followup'::text, 'timeout'::text, 'retry_blocked'::text, 'blocked_missing_poa'::text, 'blocked_missing_grid_owner_contact'::text, 'blocked_missing_manual_mailbox'::text, 'ready_to_send_manual_email'::text, 'manual_email_queued'::text, 'manual_email_sent'::text, 'waiting_manual_response'::text, 'manual_response_received'::text, 'manual_response_parsed'::text, 'cancelled'::text])))
