--
-- Name: gridex_actor_import_preview_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_actor_import_preview_v WITH (security_invoker='true') AS
 SELECT id AS import_run_id,
    source,
    import_type,
    status,
    COALESCE((metadata ->> 'mode'::text), 'apply'::text) AS import_mode,
    records_seen,
    records_upserted,
    records_failed,
    safe,
        CASE
            WHEN ((metadata #>> '{preview,newActors}'::text[]) ~ '^[0-9]+$'::text) THEN ((metadata #>> '{preview,newActors}'::text[]))::integer
            ELSE NULL::integer
        END AS new_actors,
        CASE
            WHEN ((metadata #>> '{preview,existingActors}'::text[]) ~ '^[0-9]+$'::text) THEN ((metadata #>> '{preview,existingActors}'::text[]))::integer
            ELSE NULL::integer
        END AS existing_actors,
        CASE
            WHEN ((metadata #>> '{preview,changedActors}'::text[]) ~ '^[0-9]+$'::text) THEN ((metadata #>> '{preview,changedActors}'::text[]))::integer
            ELSE NULL::integer
        END AS changed_actors,
        CASE
            WHEN ((metadata #>> '{preview,gridOwners}'::text[]) ~ '^[0-9]+$'::text) THEN ((metadata #>> '{preview,gridOwners}'::text[]))::integer
            ELSE NULL::integer
        END AS grid_owners,
        CASE
            WHEN ((metadata #>> '{preview,electricitySuppliers}'::text[]) ~ '^[0-9]+$'::text) THEN ((metadata #>> '{preview,electricitySuppliers}'::text[]))::integer
            ELSE NULL::integer
        END AS electricity_suppliers,
        CASE
            WHEN ((metadata #>> '{preview,routesSeen}'::text[]) ~ '^[0-9]+$'::text) THEN ((metadata #>> '{preview,routesSeen}'::text[]))::integer
            ELSE NULL::integer
        END AS routes_seen,
        CASE
            WHEN ((metadata #>> '{preview,prodatRoutes}'::text[]) ~ '^[0-9]+$'::text) THEN ((metadata #>> '{preview,prodatRoutes}'::text[]))::integer
            ELSE NULL::integer
        END AS prodat_routes,
        CASE
            WHEN ((metadata #>> '{preview,utiltsRoutes}'::text[]) ~ '^[0-9]+$'::text) THEN ((metadata #>> '{preview,utiltsRoutes}'::text[]))::integer
            ELSE NULL::integer
        END AS utilts_routes,
        CASE
            WHEN ((metadata #>> '{preview,missingEdielId}'::text[]) ~ '^[0-9]+$'::text) THEN ((metadata #>> '{preview,missingEdielId}'::text[]))::integer
            ELSE NULL::integer
        END AS missing_ediel_id,
        CASE
            WHEN ((metadata #>> '{preview,missingRoutes}'::text[]) ~ '^[0-9]+$'::text) THEN ((metadata #>> '{preview,missingRoutes}'::text[]))::integer
            ELSE NULL::integer
        END AS missing_routes,
        CASE
            WHEN ((metadata #>> '{preview,conflicts}'::text[]) ~ '^[0-9]+$'::text) THEN ((metadata #>> '{preview,conflicts}'::text[]))::integer
            ELSE NULL::integer
        END AS conflicts,
    started_at,
    completed_at,
    created_by,
    metadata,
    error_log
   FROM public.platform_actor_import_runs r;

