--
-- Name: gridex_automation_control_center_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_automation_control_center_v WITH (security_invoker='true') AS
 SELECT c.id AS company_id,
    c.name AS company_name,
    COALESCE(c.status, 'active'::text) AS company_status,
        CASE eps.state
            WHEN 'live'::text THEN 'live'::text
            WHEN 'paused'::text THEN 'paused'::text
            WHEN 'blocked'::text THEN 'blocked'::text
            WHEN 'prepared'::text THEN 'production_prepared'::text
            WHEN 'retired'::text THEN 'blocked'::text
            WHEN 'configuring'::text THEN 'not_ready'::text
            WHEN 'disabled'::text THEN 'not_ready'::text
            ELSE COALESCE(c.production_status, 'not_ready'::text)
        END AS production_status,
        CASE
            WHEN (eps.company_id IS NOT NULL) THEN (eps.state = 'live'::text)
            ELSE COALESCE(c.live_ediel_enabled, false)
        END AS live_ediel_enabled,
    COALESCE((public.gridex_company_go_live_readiness(c.id) ->> 'status'::text), 'blocked'::text) AS go_live_readiness,
    COALESCE(( SELECT count(*) AS count
           FROM public.customer_cases cc
          WHERE ((cc.company_id = c.id) AND (COALESCE(cc.status, ''::text) <> ALL (ARRAY['closed'::text, 'resolved'::text])))), (0)::bigint) AS open_case_count,
    COALESCE(( SELECT count(*) AS count
           FROM public.outbound_requests o
          WHERE ((o.company_id = c.id) AND (COALESCE(o.status, ''::text) = ANY (ARRAY['draft'::text, 'queued'::text, 'failed'::text, 'blocked'::text])))), (0)::bigint) AS unresolved_outbound_count,
    COALESCE(( SELECT count(*) AS count
           FROM public.billing_export_run_items bei
          WHERE ((bei.company_id = c.id) AND (bei.status = 'blocked'::text))), (0)::bigint) AS blocked_billing_rows,
    COALESCE(( SELECT count(*) AS count
           FROM public.partner_exports pe
          WHERE ((pe.company_id = c.id) AND (COALESCE(pe.status, ''::text) = ANY (ARRAY['failed'::text, 'blocked'::text])))), (0)::bigint) AS failed_partner_exports,
    c.updated_at
   FROM (public.companies c
     LEFT JOIN public.ediel_production_state eps ON ((eps.company_id = c.id)))
  WHERE (COALESCE(c.status, ''::text) <> 'deleted_test_only'::text);

