    resolved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT metering_period_gaps_severity_check CHECK ((severity = ANY (ARRAY['info'::text, 'warning'::text, 'critical'::text]))),
    CONSTRAINT metering_period_gaps_status_check CHECK ((status = ANY (ARRAY['open'::text, 'request_queued'::text, 'waiting_for_data'::text, 'resolved'::text, 'ignored'::text, 'failed'::text])))
);

--
-- Name: gridex_batch_2c_drift_queue_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_batch_2c_drift_queue_v WITH (security_invoker='true') AS
 SELECT 'billing_export_item'::text AS queue_type,
    bei.company_id,
    bei.id AS source_id,
    bei.customer_id,
    bei.site_id,
    bei.metering_point_id,
        CASE
            WHEN (bei.status = 'blocked'::text) THEN 'critical'::text
            ELSE 'info'::text
        END AS severity,
    bei.status,
    'Faktureringsrad blockerad'::text AS title,
    'Raden är blockerad och ska hanteras utan att stoppa övriga rader i exportkörningen.'::text AS description,
    bei.created_at,
    COALESCE(bei.updated_at, bei.created_at) AS updated_at,
    jsonb_build_object('billing_export_run_id', bei.billing_export_run_id, 'billing_underlay_id', bei.billing_underlay_id, 'export_status', bei.export_status, 'blocker_reasons', bei.blocker_reasons) AS payload
   FROM public.billing_export_run_items bei
  WHERE (bei.status = 'blocked'::text)
UNION ALL
 SELECT 'metering_period_gap'::text AS queue_type,
    mpg.company_id,
    mpg.id AS source_id,
    mpg.customer_id,
    mpg.site_id,
    mpg.metering_point_id,
    mpg.severity,
    mpg.status,
    'Saknade mätvärden'::text AS title,
    'Perioden saknar mätvärden och behöver begäras eller kompletteras.'::text AS description,
    mpg.created_at,
    mpg.updated_at,
    jsonb_build_object('period_month', mpg.period_month, 'period_start', mpg.period_start, 'period_end', mpg.period_end, 'outbound_request_id', mpg.outbound_request_id, 'customer_case_id', mpg.customer_case_id) AS payload
   FROM public.metering_period_gaps mpg
  WHERE (mpg.status = ANY (ARRAY['open'::text, 'request_queued'::text, 'waiting_for_data'::text, 'failed'::text]))
UNION ALL
 SELECT 'customer_case'::text AS queue_type,
    cc.company_id,
    cc.id AS source_id,
    cc.customer_id,
    cc.site_id,
    cc.metering_point_id,
        CASE
            WHEN (cc.priority = ANY (ARRAY['high'::text, 'urgent'::text])) THEN 'critical'::text
            ELSE 'warning'::text
        END AS severity,
    cc.status,
    COALESCE(cc.title, 'Kundärende'::text) AS title,
    COALESCE(cc.description, 'Kundärende kräver handläggning.'::text) AS description,
    cc.created_at,
    cc.updated_at,
    jsonb_build_object('case_type', cc.case_type, 'reason_category', cc.reason_category, 'billing_blocked', cc.billing_blocked) AS payload
   FROM public.customer_cases cc
  WHERE (cc.status <> ALL (ARRAY['resolved'::text, 'closed'::text, 'cancelled'::text]))
UNION ALL
 SELECT 'partner_export'::text AS queue_type,
    pe.company_id,
    pe.id AS source_id,
    pe.customer_id,
    pe.site_id,
    pe.metering_point_id,
        CASE
            WHEN (pe.status = 'failed'::text) THEN 'critical'::text
            ELSE 'warning'::text
        END AS severity,
    pe.status,
    'Partnerexport kräver uppföljning'::text AS title,
    COALESCE(pe.failure_reason, 'Exporten har inte kvitterats färdigt.'::text) AS description,
    pe.created_at,
    pe.updated_at,
    jsonb_build_object('target_system', pe.target_system, 'external_reference', pe.external_reference, 'export_batch_key', pe.export_batch_key) AS payload
   FROM public.partner_exports pe
  WHERE (pe.status = ANY (ARRAY['queued'::text, 'failed'::text]))
UNION ALL
 SELECT 'external_contract_intake'::text AS queue_type,
    eci.company_id,
    eci.id AS source_id,
    eci.created_customer_id AS customer_id,
    eci.created_site_id AS site_id,
    eci.created_metering_point_id AS metering_point_id,
        CASE
            WHEN (eci.status = 'failed'::text) THEN 'critical'::text
            ELSE 'warning'::text
        END AS severity,
    eci.status,
    'Externt avtal kräver kontroll'::text AS title,
    'Ett avtal från extern ingång behöver granskas, kompletteras eller kopplas vidare.'::text AS description,
    eci.created_at,
    eci.updated_at,
    jsonb_build_object('email', eci.email, 'facility_id', eci.facility_id, 'issues', eci.issues) AS payload
   FROM public.external_contract_intakes eci
  WHERE (eci.status = ANY (ARRAY['received'::text, 'needs_review'::text, 'failed'::text]));

--
-- Name: gridex_batch_2c_control_tower_summary_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_batch_2c_control_tower_summary_v WITH (security_invoker='true') AS
 SELECT c.id AS company_id,
    c.name AS company_name,
    (COALESCE(( SELECT count(*) AS count
           FROM public.gridex_batch_2c_drift_queue_v q
          WHERE (q.company_id = c.id)), (0)::bigint))::integer AS open_queue_count,
    (COALESCE(( SELECT count(*) AS count
           FROM public.gridex_batch_2c_drift_queue_v q
          WHERE ((q.company_id = c.id) AND (q.severity = 'critical'::text))), (0)::bigint))::integer AS critical_queue_count,
    (COALESCE(( SELECT count(*) AS count
           FROM public.metering_period_gaps g
          WHERE ((g.company_id = c.id) AND (g.status = ANY (ARRAY['open'::text, 'request_queued'::text, 'waiting_for_data'::text, 'failed'::text])))), (0)::bigint))::integer AS open_metering_gap_count,
    (COALESCE(( SELECT count(*) AS count
           FROM public.billing_export_run_items bei
          WHERE ((bei.company_id = c.id) AND (bei.status = 'blocked'::text))), (0)::bigint))::integer AS blocked_export_row_count,
    (COALESCE(( SELECT count(*) AS count
           FROM public.external_contract_intakes eci
          WHERE ((eci.company_id = c.id) AND (eci.status = ANY (ARRAY['received'::text, 'needs_review'::text, 'failed'::text])))), (0)::bigint))::integer AS open_external_intake_count,
    (COALESCE(( SELECT count(*) AS count
           FROM public.customer_portal_completions cpc
          WHERE ((cpc.company_id = c.id) AND (cpc.status = ANY (ARRAY['submitted'::text, 'in_review'::text])))), (0)::bigint))::integer AS open_portal_completion_count,
        CASE eps.state
            WHEN 'live'::text THEN 'live'::text
            WHEN 'paused'::text THEN 'paused'::text
            WHEN 'blocked'::text THEN 'blocked'::text
            WHEN 'prepared'::text THEN 'production_prepared'::text
            WHEN 'retired'::text THEN 'blocked'::text
            WHEN 'configuring'::text THEN 'not_ready'::text
            WHEN 'disabled'::text THEN 'not_ready'::text
            ELSE c.production_status
        END AS production_status,
        CASE
            WHEN (eps.company_id IS NOT NULL) THEN (eps.state = 'live'::text)
            ELSE c.live_ediel_enabled
        END AS live_ediel_enabled,
    c.updated_at
   FROM (public.companies c
     LEFT JOIN public.ediel_production_state eps ON ((eps.company_id = c.id)));

--
-- Name: gridex_billing_launch_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_billing_launch_readiness_v WITH (security_invoker='true') AS
 SELECT cc.company_id,
    cc.id AS contract_id,
    cc.customer_id,
    COALESCE(cc.customer_site_id, cc.site_id) AS site_id,
    cc.metering_point_id,
        CASE
            WHEN (cs.id IS NULL) THEN 'blocked'::text
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE(cs.facility_id, ''::text)), ''::text) IS NULL) THEN 'blocked'::text
            WHEN (cs.grid_owner_id IS NULL) THEN 'blocked'::text
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE(cs.grid_area_code, ''::text)), ''::text) IS NULL) THEN 'blocked'::text
            WHEN (NULLIF(TRIM(BOTH FROM COALESCE(cs.price_area_code, cc.price_area_used, ''::text)), ''::text) IS NULL) THEN 'blocked'::text
            WHEN (cps.id IS NULL) THEN 'blocked'::text
            WHEN (cps.price_plan_version_id IS NULL) THEN 'blocked'::text
            WHEN (EXISTS ( SELECT 1
               FROM public.ediel_business_errors e
              WHERE ((e.company_id = cc.company_id) AND (e.customer_id = cc.customer_id) AND (e.status <> ALL (ARRAY['resolved'::text, 'ignored'::text])) AND (e.business_error = ANY (ARRAY['negative_aperak'::text, 'z02_rejected'::text, 'object_not_identified'::text, 'facility_rejected'::text]))))) THEN 'blocked'::text
            ELSE 'ready'::text
        END AS readiness_status,
    array_remove(ARRAY[
        CASE
            WHEN (cs.id IS NULL) THEN 'site_missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((cs.id IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM COALESCE(cs.facility_id, ''::text)), ''::text) IS NULL)) THEN 'facility_missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((cs.id IS NOT NULL) AND (cs.grid_owner_id IS NULL)) THEN 'grid_owner_missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((cs.id IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM COALESCE(cs.grid_area_code, ''::text)), ''::text) IS NULL)) THEN 'grid_area_missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((cs.id IS NOT NULL) AND (NULLIF(TRIM(BOTH FROM COALESCE(cs.price_area_code, cc.price_area_used, ''::text)), ''::text) IS NULL)) THEN 'price_area_missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (cps.id IS NULL) THEN 'contract_price_snapshot_missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN ((cps.id IS NOT NULL) AND (cps.price_plan_version_id IS NULL)) THEN 'price_plan_version_missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM public.ediel_business_errors e
              WHERE ((e.company_id = cc.company_id) AND (e.customer_id = cc.customer_id) AND (e.status <> ALL (ARRAY['resolved'::text, 'ignored'::text])) AND (e.business_error = ANY (ARRAY['negative_aperak'::text, 'z02_rejected'::text, 'object_not_identified'::text, 'facility_rejected'::text]))))) THEN 'negative_market_response_open'::text
            ELSE NULL::text
        END], NULL::text) AS blockers,
    now() AS checked_at
   FROM ((public.customer_contracts cc
     LEFT JOIN public.customer_sites cs ON (((cs.id = COALESCE(cc.customer_site_id, cc.site_id)) AND (cs.company_id = cc.company_id))))
     LEFT JOIN LATERAL ( SELECT cps_1.id,
            cps_1.company_id,
            cps_1.contract_id,
            cps_1.customer_id,
            cps_1.price_plan_version_id,
            cps_1.campaign_version_id,
            cps_1.pricing_model,
            cps_1.base_price_components_snapshot,
            cps_1.price_components_snapshot,
            cps_1.snapshot_json,
            cps_1.valid_from,
            cps_1.valid_to,
            cps_1.created_at
           FROM public.contract_price_snapshots cps_1
          WHERE ((cps_1.company_id = cc.company_id) AND (cps_1.contract_id = cc.id))
          ORDER BY cps_1.valid_from DESC NULLS LAST, cps_1.created_at DESC
         LIMIT 1) cps ON (true));

--
-- Name: gridex_certificate_lookup_runtime_debug_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_certificate_lookup_runtime_debug_v WITH (security_invoker='true') AS
 SELECT j.created_at,
    j.triggered_by,
    j.status AS job_status,
    j.ediel_id AS job_ediel_id,
    j.grid_owner_id,
    j.platform_market_actor_id,
    j.found_count,
    j.inserted_count,
    j.updated_count,
    j.valid_count,
    j.expired_count,
    j.error_message,
    (j.metadata -> 'lookupAddresses'::text) AS lookup_addresses,
    (j.metadata -> 'lookupSources'::text) AS lookup_sources,
    (j.metadata -> 'routeSources'::text) AS route_sources,
    (j.metadata -> 'errors'::text) AS errors,
    (j.metadata -> 'lookupResults'::text) AS lookup_results,
    j.metadata AS job_metadata,
    g.name AS grid_owner_name,
    g.ediel_id AS grid_owner_ediel_id,
    g.platform_market_actor_id AS grid_owner_actor_id,
    g.certificate_status AS grid_owner_certificate_status,
    g.verification_status AS grid_owner_verification_status,
    j.finished_at,
    (j.metadata -> 'stage'::text) AS stage,
    count(pac.id) FILTER (WHERE ((pac.actor_id = j.platform_market_actor_id) AND (pac.environment = 'production'::text) AND (pac.purpose = 'encryption'::text) AND (pac.status = ANY (ARRAY['valid'::text, 'expires_soon'::text])) AND (pac.valid_to > now()) AND (NULLIF(btrim(COALESCE(pac.raw_certificate_pem, ''::text)), ''::text) IS NOT NULL))) AS usable_actor_certificate_rows,
    max(pac.valid_to) FILTER (WHERE (pac.actor_id = j.platform_market_actor_id)) AS newest_actor_certificate_valid_to
   FROM ((public.ediel_certificate_refresh_jobs j
     LEFT JOIN public.grid_owners g ON ((g.id = j.grid_owner_id)))
     LEFT JOIN public.platform_actor_certificates pac ON ((pac.actor_id = j.platform_market_actor_id)))
  GROUP BY j.id, j.created_at, j.triggered_by, j.status, j.ediel_id, j.grid_owner_id, j.platform_market_actor_id, j.found_count, j.inserted_count, j.updated_count, j.valid_count, j.expired_count, j.error_message, j.metadata, j.finished_at, g.name, g.ediel_id, g.platform_market_actor_id, g.certificate_status, g.verification_status;

--
-- Name: integration_api_rate_limit_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.integration_api_rate_limit_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid,
    api_client_id uuid,
    route text,
    ip_address text,
    user_agent text,
    request_count integer DEFAULT 0 NOT NULL,
    limit_per_minute integer DEFAULT 0 NOT NULL,
    cooldown_until timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

--
-- Name: platform_actor_import_issues; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.platform_actor_import_issues (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    import_run_id uuid,
    actor_id uuid,
    issue_type text NOT NULL,
    severity text DEFAULT 'warning'::text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    message text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    CONSTRAINT platform_actor_import_issues_severity_check CHECK ((severity = ANY (ARRAY['info'::text, 'warning'::text, 'blocking'::text]))),
    CONSTRAINT platform_actor_import_issues_status_check CHECK ((status = ANY (ARRAY['open'::text, 'acknowledged'::text, 'resolved'::text, 'ignored'::text])))
);

--
-- Name: gridex_company_operations_statistics_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_company_operations_statistics_v WITH (security_invoker='true') AS
 SELECT id AS company_id,
    name AS company_name,
    ( SELECT count(*) AS count
           FROM public.customers x
          WHERE (x.company_id = c.id)) AS customers_total,
    ( SELECT count(*) AS count
           FROM public.customers x
          WHERE ((x.company_id = c.id) AND (x.created_at >= date_trunc('day'::text, now())))) AS customers_today,
    ( SELECT count(*) AS count
           FROM public.customers x
          WHERE ((x.company_id = c.id) AND (x.created_at >= (now() - '7 days'::interval)))) AS customers_last_7_days,
    ( SELECT count(*) AS count
           FROM public.customers x
          WHERE ((x.company_id = c.id) AND (x.created_at >= date_trunc('month'::text, now())))) AS customers_this_month,
    ( SELECT count(*) AS count
           FROM public.customers x
          WHERE ((x.company_id = c.id) AND (x.status = 'active'::text))) AS customers_active,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE (x.company_id = c.id)) AS web_intakes_total,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (x.status = 'received'::text))) AS web_intakes_received,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (x.status = 'needs_review'::text))) AS web_intakes_needs_review,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (x.status = 'failed'::text))) AS web_intakes_failed,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (x.created_customer_id IS NOT NULL))) AS web_intakes_with_customer,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (x.created_site_id IS NOT NULL))) AS web_intakes_with_site,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (x.created_metering_point_id IS NOT NULL))) AS web_intakes_with_metering_point,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (x.created_contract_id IS NOT NULL))) AS web_intakes_with_contract,
    ( SELECT count(*) AS count
           FROM public.customer_sites x
          WHERE (x.company_id = c.id)) AS sites_total,
    ( SELECT count(*) AS count
           FROM public.customer_sites x
          WHERE ((x.company_id = c.id) AND (x.grid_area_code IS NULL))) AS sites_missing_grid_area,
    ( SELECT count(*) AS count
           FROM public.customer_sites x
          WHERE ((x.company_id = c.id) AND (x.grid_owner_id IS NULL))) AS sites_missing_grid_owner,
    ( SELECT count(*) AS count
           FROM public.customer_sites x
          WHERE ((x.company_id = c.id) AND (x.price_area_code IS NULL))) AS sites_missing_price_area_code,
    ( SELECT count(*) AS count
           FROM public.metering_points x
          WHERE (x.company_id = c.id)) AS metering_points_total,
    ( SELECT count(*) AS count
           FROM public.metering_points x
          WHERE ((x.company_id = c.id) AND (COALESCE(x.metering_point_id, x.meter_point_id) IS NOT NULL))) AS metering_points_with_identifier,
    ( SELECT count(*) AS count
           FROM public.metering_points x
          WHERE ((x.company_id = c.id) AND (COALESCE(x.metering_point_id, x.meter_point_id) IS NULL))) AS metering_points_without_identifier,
    ( SELECT count(*) AS count
           FROM public.customer_contracts x
          WHERE (x.company_id = c.id)) AS contracts_total,
    ( SELECT count(*) AS count
           FROM public.billing_underlays x
          WHERE (x.company_id = c.id)) AS billing_underlays_total,
    ( SELECT count(*) AS count
           FROM public.billing_underlays x
          WHERE ((x.company_id = c.id) AND (COALESCE(x.readiness_status, x.status) = ANY (ARRAY['blocked'::text, 'failed'::text, 'needs_review'::text])))) AS billing_blocked_or_failed,
    ( SELECT count(*) AS count
           FROM public.ediel_messages x
          WHERE ((x.company_id = c.id) AND (x.direction = 'inbound'::text))) AS ediel_inbound,
    ( SELECT count(*) AS count
           FROM public.ediel_messages x
          WHERE ((x.company_id = c.id) AND (x.direction = 'outbound'::text))) AS ediel_outbound,
    ( SELECT count(*) AS count
           FROM public.ediel_messages x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['failed'::text, 'blocked'::text, 'unresolved'::text])))) AS ediel_blocked_failed_unresolved,
    ( SELECT count(*) AS count
           FROM public.integration_api_requests x
          WHERE (x.company_id = c.id)) AS api_requests,
    ( SELECT count(*) AS count
           FROM public.integration_api_requests x
          WHERE ((x.company_id = c.id) AND (COALESCE(x.status_code, 200) >= 400))) AS api_errors,
    ( SELECT count(*) AS count
           FROM public.webhook_deliveries x
          WHERE (x.company_id = c.id)) AS webhook_deliveries,
    ( SELECT count(*) AS count
           FROM public.webhook_deliveries x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['failed'::text, 'dead'::text, 'dead_letter'::text, 'retrying'::text])))) AS webhook_failures,
    ( SELECT COALESCE(sum(r.issue_count), (0)::numeric) AS "coalesce"
           FROM public.gridex_company_launch_blocker_reasons_v r
          WHERE ((r.company_id = c.id) AND (r.issue_count > 0))) AS customers_blocked_or_data_issues,
    ( SELECT COALESCE(jsonb_object_agg(r.reason_key, r.issue_count), '{}'::jsonb) AS "coalesce"
           FROM public.gridex_company_launch_blocker_reasons_v r
          WHERE ((r.company_id = c.id) AND (r.issue_count > 0))) AS blocker_reasons,
    ( SELECT count(*) AS count
           FROM public.external_contract_intakes x
          WHERE ((x.company_id = c.id) AND (jsonb_typeof(x.issues) = 'array'::text) AND (jsonb_array_length(x.issues) > 0))) AS web_intakes_with_issues,
    ( SELECT count(*) AS count
           FROM public.metering_points x
          WHERE ((x.company_id = c.id) AND (COALESCE(x.status, ''::text) = ANY (ARRAY['verified'::text, 'active'::text])))) AS metering_points_verified,
    ( SELECT count(*) AS count
           FROM public.metering_points x
          WHERE ((x.company_id = c.id) AND ((x.grid_owner_id IS NULL) OR (x.grid_area_code IS NULL) OR (x.price_area_code IS NULL)))) AS metering_points_missing_market_data,
    ( SELECT count(*) AS count
           FROM public.supplier_switch_requests x
          WHERE (x.company_id = c.id)) AS supplier_switch_requests_total,
    ( SELECT count(*) AS count
           FROM public.supplier_switch_requests x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['ready'::text, 'ready_to_execute'::text, 'queued_for_outbound'::text])))) AS supplier_switch_ready,
    ( SELECT count(*) AS count
           FROM public.supplier_switch_requests x
          WHERE ((x.company_id = c.id) AND ((x.status = ANY (ARRAY['blocked'::text, 'failed'::text, 'rejected'::text])) OR (x.lifecycle_blocked = true)))) AS supplier_switch_blocked_failed,
    ( SELECT count(*) AS count
           FROM public.supplier_switch_requests x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['confirmed'::text, 'completed'::text])))) AS supplier_switch_confirmed,
    ( SELECT count(*) AS count
           FROM public.powers_of_attorney x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['signed'::text, 'accepted'::text, 'active'::text, 'completed'::text])))) AS active_powers_of_attorney,
    ( SELECT count(*) AS count
           FROM public.contract_price_snapshots x
          WHERE (x.company_id = c.id)) AS contract_price_snapshots_total,
    ( SELECT count(*) AS count
           FROM public.ediel_business_errors x
          WHERE ((x.company_id = c.id) AND (x.status <> ALL (ARRAY['resolved'::text, 'ignored'::text])))) AS business_errors_open,
    ( SELECT count(*) AS count
           FROM public.facility_data_quality_issues x
          WHERE ((x.company_id = c.id) AND (x.status <> ALL (ARRAY['resolved'::text, 'ignored'::text])))) AS facility_data_quality_issues_open,
    ( SELECT count(*) AS count
           FROM public.communication_logs x
          WHERE (x.company_id = c.id)) AS communication_logs_total,
    ( SELECT count(*) AS count
           FROM public.communication_logs x
          WHERE ((x.company_id = c.id) AND (x.status = ANY (ARRAY['failed'::text, 'bounced'::text])))) AS communication_logs_failed_bounced,
    ( SELECT count(*) AS count
           FROM public.integration_api_rate_limit_events x
          WHERE (x.company_id = c.id)) AS api_rate_limit_events,
    ( SELECT count(*) AS count
           FROM public.platform_actor_import_issues x
          WHERE (x.status = 'open'::text)) AS platform_import_issues_open,
    ( SELECT count(*) AS count
           FROM public.gridex_route_readiness_v x
          WHERE (x.readiness_status = ANY (ARRAY['critical_missing_route'::text, 'recommended_missing_route'::text, 'not_sendable'::text, 'needs_review'::text]))) AS route_missing_or_not_ready
   FROM public.companies c;

--
-- Name: gridex_company_route_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_company_route_readiness_v WITH (security_invoker='true') AS
 WITH company_sender AS (
         SELECT eas.id AS sender_settings_id,
            eas.company_id,
            eas.environment,
            eas.ediel_id,
            eas.actor_ediel_id,
            eas.role,
            eas.actor_role,
            eas.market_roles,
            eas.production_send_lock_enabled,
            eas.first_production_send_approved,
            eas.is_active
           FROM public.ediel_actor_settings eas
          WHERE (eas.is_active = true)
        ), grid_owner_actor AS (
         SELECT go.id AS grid_owner_id,
            go.name AS grid_owner_name,
            go.ediel_id AS grid_owner_ediel_id,
            go.platform_market_actor_id,
            pma.id AS platform_market_actor_id_resolved,
            pma.name AS platform_actor_name,
            pma.status AS platform_actor_status,
            pma.match_status
           FROM (public.grid_owners go
             LEFT JOIN public.platform_market_actors pma ON ((pma.id = go.platform_market_actor_id)))
          WHERE (COALESCE(go.is_active, true) = true)
        ), platform_routes AS (
         SELECT par.id AS platform_actor_route_id,
            par.actor_id,
            par.message_family,
            COALESCE((par.metadata ->> 'message_code'::text),
                CASE
                    WHEN (par.message_family = 'PRODAT'::text) THEN 'Z01'::text
                    ELSE NULL::text
                END) AS message_code,
            par.environment,
            par.communication_address,
            par.party_id,
            par.interchange_party_id,
            par.status,
            par.is_verified,
            par.auto_send_allowed
           FROM public.platform_actor_routes par
          WHERE (par.status = 'active'::text)
        ), matrix AS (
         SELECT cs.company_id,
            goa.grid_owner_id,
            goa.grid_owner_name,
            goa.grid_owner_ediel_id,
            goa.platform_market_actor_id,
            pr.platform_actor_route_id,
            pr.message_family,
            pr.message_code,
            pr.environment,
            cs.sender_settings_id,
            cs.production_send_lock_enabled,
            cs.first_production_send_approved,
            cmpr.id AS company_market_party_route_id,
            cmpr.communication_route_id AS cmpr_communication_route_id,
            cmpr.route_profile_id AS cmpr_route_profile_id
           FROM (((company_sender cs
             JOIN grid_owner_actor goa ON ((goa.platform_market_actor_id IS NOT NULL)))
             JOIN platform_routes pr ON (((pr.actor_id = goa.platform_market_actor_id) AND (pr.environment = cs.environment) AND (pr.message_family = ANY (ARRAY['PRODAT'::text, 'UTILTS'::text])))))
             LEFT JOIN public.company_market_party_routes cmpr ON (((cmpr.company_id = cs.company_id) AND (cmpr.market_party_id = pr.actor_id) AND (cmpr.message_family = pr.message_family) AND (COALESCE(cmpr.environment, (cmpr.metadata ->> 'environment'::text)) = pr.environment) AND (COALESCE(NULLIF(cmpr.message_code, ''::text), NULLIF((cmpr.metadata ->> 'message_code'::text), ''::text),
                CASE
                    WHEN (pr.message_family = 'PRODAT'::text) THEN 'Z01'::text
                    ELSE ''::text
                END) = COALESCE(pr.message_code, ''::text)) AND (COALESCE((cmpr.platform_actor_route_id)::text, (cmpr.metadata ->> 'platform_actor_route_id'::text)) = (pr.platform_actor_route_id)::text) AND (cmpr.active = true))))
          WHERE (cs.environment = ANY (ARRAY['test'::text, 'production'::text]))
        ), resolved AS (
         SELECT m.company_id,
            m.grid_owner_id,
            m.grid_owner_name,
            m.grid_owner_ediel_id,
            m.platform_market_actor_id,
            m.platform_actor_route_id,
            m.message_family,
            m.message_code,
            m.environment,
            m.sender_settings_id,
            m.production_send_lock_enabled,
            m.first_production_send_approved,
            m.company_market_party_route_id,
            m.cmpr_communication_route_id,
            m.cmpr_route_profile_id,
            cr.id AS communication_route_id,
            erp.id AS ediel_route_profile_id,
            COALESCE(cr.is_active, false) AS communication_route_active,
            COALESCE(erp.is_active, false) AS profile_active,
            COALESCE(erp.is_enabled, false) AS profile_enabled,
            COALESCE(erp.receiver_ediel_id, cr.counterparty_ediel_id, m.grid_owner_ediel_id) AS receiver_ediel_id,
            erp.receiver_certificate_id,
            erp.security_policy_status
           FROM ((matrix m
             LEFT JOIN public.communication_routes cr ON ((cr.id = m.cmpr_communication_route_id)))
             LEFT JOIN public.ediel_route_profiles erp ON ((erp.id = m.cmpr_route_profile_id)))
        )
 SELECT company_id,
    grid_owner_id,
    grid_owner_name,
    grid_owner_ediel_id,
    platform_market_actor_id,
    platform_actor_route_id,
    message_family,
    message_code,
    environment,
    true AS actor_registry_ready,
    true AS platform_route_ready,
    ((company_market_party_route_id IS NOT NULL) AND communication_route_active AND profile_active AND profile_enabled) AS operational_route_ready,
    ((company_market_party_route_id IS NOT NULL) AND communication_route_active AND profile_active AND profile_enabled AND (NOT ((environment = 'production'::text) AND (COALESCE(production_send_lock_enabled, false) = true) AND (COALESCE(first_production_send_approved, false) = false))) AND (receiver_ediel_id IS NOT NULL)) AS send_ready,
        CASE
            WHEN (company_market_party_route_id IS NULL) THEN 'platform_route_exists_but_not_materialized'::text
            WHEN (NOT communication_route_active) THEN 'communication_route_inactive'::text
            WHEN (NOT (profile_active AND profile_enabled)) THEN 'ediel_route_profile_inactive'::text
            WHEN ((environment = 'production'::text) AND (COALESCE(production_send_lock_enabled, false) = true) AND (COALESCE(first_production_send_approved, false) = false)) THEN 'production_send_locked'::text
            WHEN (receiver_ediel_id IS NULL) THEN 'receiver_ediel_id_missing'::text
            ELSE NULL::text
        END AS blocker_code,
        CASE
            WHEN (company_market_party_route_id IS NULL) THEN 'Nätägaren är verifierad i aktörsregistret, men bolagets operativa route är inte materialiserad.'::text
            WHEN ((environment = 'production'::text) AND (COALESCE(production_send_lock_enabled, false) = true) AND (COALESCE(first_production_send_approved, false) = false)) THEN 'Första produktionssändningen kräver platform-admins godkännande.'::text
            WHEN (receiver_ediel_id IS NULL) THEN 'Operativ route saknar mottagande Ediel-ID.'::text
            WHEN (NOT communication_route_active) THEN 'Communication route är inaktiv.'::text
            WHEN (NOT (profile_active AND profile_enabled)) THEN 'Ediel route profile är inaktiv.'::text
            ELSE 'Route är operativ och redo enligt grundkontroller.'::text
        END AS readiness_message,
    communication_route_id,
    ediel_route_profile_id,
    company_market_party_route_id,
    sender_settings_id,
        CASE
            WHEN ((environment = 'production'::text) AND (COALESCE(production_send_lock_enabled, false) = true) AND (COALESCE(first_production_send_approved, false) = false)) THEN 'locked'::text
            WHEN (environment = 'production'::text) THEN 'approved'::text
            ELSE 'not_applicable'::text
        END AS production_send_lock_status
   FROM resolved;

