--
-- Name: spot_price_intervals; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.spot_price_intervals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source text DEFAULT 'elprisetjustnu'::text NOT NULL,
    price_area text NOT NULL,
    time_start timestamp with time zone NOT NULL,
    time_end timestamp with time zone NOT NULL,
    sek_per_kwh numeric NOT NULL,
    eur_per_kwh numeric,
    exchange_rate numeric,
    resolution text NOT NULL,
    source_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT spot_price_intervals_price_area_check CHECK ((price_area = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text]))),
    CONSTRAINT spot_price_intervals_resolution_check CHECK ((resolution = ANY (ARRAY['hourly'::text, 'quarter_hour'::text]))),
    CONSTRAINT spot_price_intervals_time_check CHECK ((time_end > time_start))
);

--
-- Name: gridex_spot_interval_gaps_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_spot_interval_gaps_v WITH (security_invoker='true') AS
 WITH ordered AS (
         SELECT spot_price_intervals.source,
            spot_price_intervals.price_area,
            spot_price_intervals.time_start,
            spot_price_intervals.time_end,
            lag(spot_price_intervals.time_end) OVER (PARTITION BY spot_price_intervals.source, spot_price_intervals.price_area ORDER BY spot_price_intervals.time_start, spot_price_intervals.time_end) AS previous_end
           FROM public.spot_price_intervals
        )
 SELECT source,
    price_area,
    previous_end AS gap_start,
    time_start AS gap_end,
    (EXTRACT(epoch FROM (time_start - previous_end)) / (60)::numeric) AS gap_minutes
   FROM ordered
  WHERE ((previous_end IS NOT NULL) AND (time_start > previous_end));

--
-- Name: gridex_spot_interval_overlaps_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.gridex_spot_interval_overlaps_v WITH (security_invoker='true') AS
 WITH ordered AS (
         SELECT spot_price_intervals.source,
            spot_price_intervals.price_area,
            spot_price_intervals.id,
            spot_price_intervals.time_start,
            spot_price_intervals.time_end,
            lag(spot_price_intervals.time_end) OVER (PARTITION BY spot_price_intervals.source, spot_price_intervals.price_area ORDER BY spot_price_intervals.time_start, spot_price_intervals.time_end) AS previous_end
           FROM public.spot_price_intervals
        )
 SELECT source,
    price_area,
    id,
    time_start,
    time_end,
    previous_end
   FROM ordered
  WHERE ((previous_end IS NOT NULL) AND (time_start < previous_end));

--
-- Name: gridex_stale_market_previews_v; Type: VIEW; Schema: public; Owner: -
--

