    can_use_for_prodat,
    can_use_for_utilts,
    can_start_supplier_switch,
    blocking_reasons,
    checked_at,
    is_gas_actor,
    is_dummy_or_test_actor,
    is_system_supplier_only,
    is_electricity_grid_owner_scope,
    electricity_scope_status,
    primary_role_group,
    supplier_switch_readiness_status,
    manual_review_required,
    manual_review_reason
   FROM public.actor_readiness_status
  WHERE (electricity_scope_status <> 'in_electricity_supplier_switch_scope'::text);

