    CONSTRAINT portfolio_monthly_prices_billing_month_check CHECK ((billing_month ~ '^\d{4}-\d{2}$'::text)),
    CONSTRAINT portfolio_monthly_prices_price_area_check CHECK ((price_area = ANY (ARRAY['SE1'::text, 'SE2'::text, 'SE3'::text, 'SE4'::text]))),
    CONSTRAINT portfolio_monthly_prices_source_check CHECK ((source = ANY (ARRAY['manual'::text, 'api'::text, 'import'::text, 'contract_price_version'::text]))),
    CONSTRAINT portfolio_monthly_prices_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'confirmed'::text, 'locked'::text, 'published'::text, 'corrected'::text, 'archived'::text, 'superseded'::text])))
);

--
-- Name: portfolio_monthly_price_versions_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.portfolio_monthly_price_versions_v WITH (security_invoker='true') AS
 SELECT id,
    company_id,
    price_plan_id,
    price_plan_version_id,
    ((billing_month || '-01'::text))::date AS period_month,
    price_area AS price_area_code,
    (price_ex_vat_sek_per_kwh * (100)::numeric) AS amount,
    'ore_per_kwh'::text AS unit,
    false AS vat_included,
    status,
    source,
    version_number,
    supersedes_id,
    superseded_at,
    confirmed_at,
    published_at,
    locked_at,
    created_at,
    updated_at
   FROM public.portfolio_monthly_prices;

--
-- Name: VIEW portfolio_monthly_price_versions_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.portfolio_monthly_price_versions_v IS 'Canonical monthly portfolio prices. Amount is represented in ore/kWh excluding VAT and rows are tenant- and price-plan-version scoped.';

