--
-- Name: tenant_contract_catalog_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.tenant_contract_catalog_v WITH (security_invoker='true') AS
 SELECT a.company_id,
    a.id AS assignment_id,
    p.id AS contract_product_id,
    p.product_code,
    p.name AS product_name,
    p.product_category,
    v.id AS contract_product_version_id,
    v.version_number,
    v.customer_type,
    v.contract_type,
    v.pricing_model,
    v.price_plan_id,
    v.price_plan_version_id,
    v.binding_months,
    v.notice_months,
    v.status AS version_status,
    a.internal_sales_allowed,
    a.website_publication_allowed,
    a.status AS assignment_status,
    a.legal_mode,
    a.valid_from,
    a.valid_to,
    ch.status AS website_channel_status,
    pub.status AS publication_status,
    pv.id AS publication_version_id,
    pv.version_number AS publication_version_number,
    pv.price_book_id,
    pv.legal_bundle_version_id,
    pv.offer_reference,
    pv.content_sha256 AS publication_sha256
   FROM (((((public.tenant_contract_assignments a
     JOIN public.contract_product_versions v ON ((v.id = a.contract_product_version_id)))
     JOIN public.contract_products p ON ((p.id = v.contract_product_id)))
     LEFT JOIN public.tenant_contract_channels ch ON (((ch.assignment_id = a.id) AND (ch.channel = 'website'::text))))
     LEFT JOIN public.contract_publications pub ON (((pub.assignment_id = a.id) AND (pub.channel = 'website'::text))))
     LEFT JOIN LATERAL ( SELECT x.id,
            x.contract_publication_id,
            x.version_number,
            x.contract_product_version_id,
            x.price_plan_id,
            x.price_plan_version_id,
            x.price_book_id,
            x.legal_bundle_version_id,
            x.legacy_public_contract_offer_id,
            x.customer_type,
            x.channel,
            x.valid_from,
            x.valid_to,
            x.publication_snapshot,
            x.offer_reference,
            x.content_sha256,
            x.status,
            x.published_at,
            x.locked_at,
            x.created_by,
            x.created_at
           FROM public.contract_publication_versions x
          WHERE (x.contract_publication_id = pub.id)
          ORDER BY x.version_number DESC
         LIMIT 1) pv ON (true));

--
-- Name: tenant_contract_offer_readiness_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.tenant_contract_offer_readiness_v WITH (security_invoker='true') AS
 SELECT c.id AS company_id,
    c.name AS company_name,
    count(o.id) AS total_contract_offers,
    count(o.id) FILTER (WHERE (lower(COALESCE(o.status, ''::text)) = 'draft'::text)) AS draft_contracts,
    count(o.id) FILTER (WHERE ((lower(COALESCE(o.status, ''::text)) = 'active'::text) AND (COALESCE(o.is_active, false) = true))) AS internal_active_contracts,
    count(o.id) FILTER (WHERE ((lower(COALESCE(o.status, ''::text)) = 'active'::text) AND (COALESCE(o.is_active, false) = false))) AS active_but_hidden_contracts,
    count(o.id) FILTER (WHERE (COALESCE(o.price_version, ''::text) <> ''::text)) AS contracts_with_price_version,
    count(o.id) FILTER (WHERE (COALESCE(o.terms_version, ''::text) <> ''::text)) AS contracts_with_terms_version,
    count(pco.id) FILTER (WHERE ((lower(COALESCE(pco.publication_status, ''::text)) = 'published'::text) AND (COALESCE(pco.website_enabled, false) = true) AND (COALESCE(pco.is_public, false) = true) AND (COALESCE(pco.is_archived, false) = false))) AS website_published_contracts,
        CASE
            WHEN (count(o.id) FILTER (WHERE ((lower(COALESCE(o.status, ''::text)) = 'active'::text) AND (COALESCE(o.is_active, false) = true) AND (COALESCE(o.price_version, ''::text) <> ''::text) AND (COALESCE(o.terms_version, ''::text) <> ''::text))) > 0) THEN true
            ELSE false
        END AS can_use_internal_customer_intake,
        CASE
            WHEN (count(pco.id) FILTER (WHERE ((lower(COALESCE(pco.publication_status, ''::text)) = 'published'::text) AND (COALESCE(pco.website_enabled, false) = true) AND (COALESCE(pco.is_public, false) = true) AND (COALESCE(pco.is_archived, false) = false))) > 0) THEN true
            ELSE false
        END AS can_show_contracts_on_website,
    array_remove(ARRAY[
        CASE
            WHEN (count(o.id) = 0) THEN 'contract_missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (count(o.id) FILTER (WHERE ((lower(COALESCE(o.status, ''::text)) = 'active'::text) AND (COALESCE(o.is_active, false) = true))) = 0) THEN 'internal_active_contract_missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (count(o.id) FILTER (WHERE ((lower(COALESCE(o.status, ''::text)) = 'active'::text) AND (COALESCE(o.is_active, false) = true) AND (COALESCE(o.price_version, ''::text) <> ''::text))) = 0) THEN 'price_version_missing'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (count(o.id) FILTER (WHERE ((lower(COALESCE(o.status, ''::text)) = 'active'::text) AND (COALESCE(o.is_active, false) = true) AND (COALESCE(o.terms_version, ''::text) <> ''::text))) = 0) THEN 'terms_version_missing'::text
            ELSE NULL::text
        END], NULL::text) AS internal_blockers,
    array_remove(ARRAY[
        CASE
            WHEN (count(pco.id) FILTER (WHERE ((lower(COALESCE(pco.publication_status, ''::text)) = 'published'::text) AND (COALESCE(pco.website_enabled, false) = true) AND (COALESCE(pco.is_public, false) = true) AND (COALESCE(pco.is_archived, false) = false))) = 0) THEN 'website_contract_publication_missing'::text
            ELSE NULL::text
        END], NULL::text) AS website_blockers
   FROM ((public.companies c
     LEFT JOIN public.contract_offers o ON ((o.company_id = c.id)))
     LEFT JOIN public.public_contract_offers pco ON ((pco.company_id = c.id)))
  GROUP BY c.id, c.name;

--
-- Name: VIEW tenant_contract_offer_readiness_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.tenant_contract_offer_readiness_v IS 'Plain-language tenant contract readiness. Internal OPS contracts require active status, price version and terms version. Website/API publication is a separate track and must not block internal customer handling or Ediel production.';

--
-- Name: COLUMN tenant_contract_offer_readiness_v.can_use_internal_customer_intake; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_contract_offer_readiness_v.can_use_internal_customer_intake IS 'True when the tenant has at least one internally active OPS contract with price/version and terms snapshot inputs. Does not require API or website publication.';

--
-- Name: COLUMN tenant_contract_offer_readiness_v.can_show_contracts_on_website; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tenant_contract_offer_readiness_v.can_show_contracts_on_website IS 'True when the tenant has at least one published public contract offer. This is a website/API readiness signal only.';

