--
-- Name: tenant_customer_intake_tracking_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.tenant_customer_intake_tracking_v WITH (security_invoker='true') AS
 WITH website AS (
         SELECT website_customer_applications.company_id,
            website_customer_applications.status,
            website_customer_applications.created_at,
            website_customer_applications.updated_at,
            website_customer_applications.customer_id,
            website_customer_applications.contract_id,
            website_customer_applications.grid_owner_id,
            website_customer_applications.resolution_status,
            website_customer_applications.blocking_reasons,
            website_customer_applications.next_step
           FROM public.website_customer_applications
          WHERE (to_regclass('public.website_customer_applications'::text) IS NOT NULL)
        ), external_intakes AS (
         SELECT external_contract_intakes.company_id,
            external_contract_intakes.status,
            external_contract_intakes.created_at,
            external_contract_intakes.updated_at,
            external_contract_intakes.created_customer_id AS customer_id,
            external_contract_intakes.created_contract_id AS contract_id,
            NULL::uuid AS grid_owner_id,
            NULL::text AS resolution_status,
            external_contract_intakes.issues AS blocking_reasons,
            NULL::text AS next_step
           FROM public.external_contract_intakes
          WHERE (to_regclass('public.external_contract_intakes'::text) IS NOT NULL)
        ), combined AS (
         SELECT website.company_id,
            website.status,
            website.created_at,
            website.updated_at,
            website.customer_id,
            website.contract_id,
            website.grid_owner_id,
            website.resolution_status,
            website.blocking_reasons,
            website.next_step
           FROM website
        UNION ALL
         SELECT external_intakes.company_id,
            external_intakes.status,
            external_intakes.created_at,
            external_intakes.updated_at,
            external_intakes.customer_id,
            external_intakes.contract_id,
            external_intakes.grid_owner_id,
            external_intakes.resolution_status,
            external_intakes.blocking_reasons,
            external_intakes.next_step
           FROM external_intakes
        )
 SELECT c.id AS company_id,
    c.name AS company_name,
    count(combined.*) AS total_applications,
    count(combined.*) FILTER (WHERE (combined.created_at >= date_trunc('month'::text, now()))) AS applications_this_month,
    count(combined.*) FILTER (WHERE (lower(COALESCE(combined.status, ''::text)) = ANY (ARRAY['received'::text, 'pending'::text, 'pending_review'::text, 'partially_created'::text]))) AS pending_applications,
    count(combined.*) FILTER (WHERE (lower(COALESCE(combined.status, ''::text)) = ANY (ARRAY['customer_created'::text, 'created'::text, 'completed'::text, 'accepted'::text]))) AS completed_applications,
    count(combined.*) FILTER (WHERE ((lower(COALESCE(combined.status, ''::text)) = ANY (ARRAY['failed'::text, 'blocked'::text, 'error'::text])) OR (jsonb_array_length(COALESCE(combined.blocking_reasons, '[]'::jsonb)) > 0))) AS applications_requiring_action,
    count(combined.*) FILTER (WHERE ((combined.grid_owner_id IS NOT NULL) OR (lower(COALESCE(combined.resolution_status, ''::text)) = ANY (ARRAY['resolved'::text, 'verified'::text])))) AS grid_owner_resolved,
    max(combined.updated_at) AS last_application_updated_at
   FROM (public.companies c
     LEFT JOIN combined ON ((combined.company_id = c.id)))
  GROUP BY c.id, c.name;

--
-- Name: VIEW tenant_customer_intake_tracking_v; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.tenant_customer_intake_tracking_v IS 'Per-tenant website/customer-intake tracking for dashboard cards: pending, completed, action required and grid-owner resolved.';

