--
-- Name: tenant_integrity_company_summary_v; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.tenant_integrity_company_summary_v WITH (security_invoker='true') AS
 SELECT c.id AS company_id,
    c.name AS company_name,
    c.status AS company_status,
    chosen.id AS latest_run_id,
    chosen.started_at AS audited_at,
    (COALESCE(counts.finding_count, (0)::bigint))::integer AS finding_count,
    (COALESCE(counts.critical_count, (0)::bigint))::integer AS critical_count,
    (COALESCE(counts.high_count, (0)::bigint))::integer AS high_count,
    (COALESCE(counts.medium_count, (0)::bigint))::integer AS medium_count,
    (COALESCE(counts.low_count, (0)::bigint))::integer AS low_count,
    (COALESCE(counts.info_count, (0)::bigint))::integer AS info_count,
        CASE
            WHEN (chosen.id IS NULL) THEN 'not_audited'::text
            WHEN (chosen.status <> 'completed'::text) THEN chosen.status
            WHEN (COALESCE(counts.critical_count, (0)::bigint) > 0) THEN 'critical'::text
            WHEN (COALESCE(counts.high_count, (0)::bigint) > 0) THEN 'attention'::text
            WHEN (COALESCE(counts.finding_count, (0)::bigint) > 0) THEN 'warning'::text
            ELSE 'healthy'::text
        END AS integrity_status
   FROM ((public.companies c
     LEFT JOIN LATERAL ( SELECT ar.id,
            ar.company_id,
            ar.scope,
            ar.status,
            ar.requested_by,
            ar.started_at,
            ar.finished_at,
            ar.finding_count,
            ar.critical_count,
            ar.high_count,
            ar.medium_count,
            ar.low_count,
            ar.info_count,
            ar.error_message,
            ar.metadata
           FROM public.tenant_integrity_audit_runs ar
          WHERE ((ar.scope = 'all'::text) AND (ar.status = 'completed'::text) AND ((ar.company_id = c.id) OR (ar.company_id IS NULL)))
          ORDER BY ar.started_at DESC, (ar.company_id IS NOT NULL) DESC, ar.id DESC
         LIMIT 1) chosen ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS finding_count,
            count(*) FILTER (WHERE (f.severity = 'critical'::text)) AS critical_count,
            count(*) FILTER (WHERE (f.severity = 'high'::text)) AS high_count,
            count(*) FILTER (WHERE (f.severity = 'medium'::text)) AS medium_count,
            count(*) FILTER (WHERE (f.severity = 'low'::text)) AS low_count,
            count(*) FILTER (WHERE (f.severity = 'info'::text)) AS info_count
           FROM public.tenant_integrity_findings f
          WHERE ((f.run_id = chosen.id) AND (f.company_id = c.id))) counts ON (true))
  WHERE (c.status <> 'deleted_test_only'::text);

