--
-- Name: webhook_subscriptions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.webhook_subscriptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    name text NOT NULL,
    endpoint_url text NOT NULL,
    event_types text[] DEFAULT ARRAY[]::text[] NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    signing_algorithm text DEFAULT 'hmac-sha256'::text NOT NULL,
    signing_secret_ref text,
    signing_secret_hash text,
    custom_headers jsonb DEFAULT '{}'::jsonb NOT NULL,
    timeout_ms integer DEFAULT 10000 NOT NULL,
    max_attempts integer DEFAULT 8 NOT NULL,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    failure_count integer DEFAULT 0 NOT NULL,
    last_tested_at timestamp with time zone,
    rotated_at timestamp with time zone,
    rotated_by uuid,
    status_reason text,
    lifecycle_paused_by_tenant boolean DEFAULT false NOT NULL,
    lifecycle_previous_status text,
    webhook_subscription_reference text DEFAULT public.gridex_new_public_resource_reference('webhook'::text) NOT NULL,
    CONSTRAINT webhook_subscriptions_endpoint_check CHECK ((endpoint_url ~ '^https://'::text)),
    CONSTRAINT webhook_subscriptions_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 20))),
    CONSTRAINT webhook_subscriptions_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'disabled'::text]))),
    CONSTRAINT webhook_subscriptions_timeout_check CHECK (((timeout_ms >= 1000) AND (timeout_ms <= 30000)))
);

