--

ALTER TABLE public.actor_registry_conflicts ENABLE ROW LEVEL SECURITY;

--
-- Name: actor_registry_conflicts actor_registry_conflicts_platform_admin_read; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY actor_registry_conflicts_platform_admin_read ON public.actor_registry_conflicts FOR SELECT TO authenticated USING (( SELECT public.gridex_user_is_platform_admin() AS gridex_user_is_platform_admin));

--
-- Name: POLICY actor_registry_conflicts_platform_admin_read ON actor_registry_conflicts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON POLICY actor_registry_conflicts_platform_admin_read ON public.actor_registry_conflicts IS 'GRIDEX-OPS-BL-002: platform-global conflict data is visible only to active platform admins.';

--
-- Name: actor_registry_conflicts actor_registry_conflicts_service_role_read; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY actor_registry_conflicts_service_role_read ON public.actor_registry_conflicts FOR SELECT TO service_role USING (true);

--
-- Name: POLICY actor_registry_conflicts_service_role_read ON actor_registry_conflicts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON POLICY actor_registry_conflicts_service_role_read ON public.actor_registry_conflicts IS 'GRIDEX-OPS-BL-002: service-role access for actor-registry background processing.';

--
-- Name: actor_registry_conflicts actor_registry_conflicts_write; Type: POLICY; Schema: public; Owner: -
--

